-- the start of an untitled text.
CatQuest335Books = CatQuest335Books or {}
CatQuest335Books.books = {
    ["000409bf"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Холмы Разбойничьих Кинжалов — скалистая гряда за Луноречьем, её ещё называют южным Западным Краем." }, { 7.70, "Народное ополчение полагает, что именно здесь скрываются разбойники, налётчики и кастетчики Братства Справедливости, ускользнувшие от него." }, { 18.36, "Среди камней нашёл уединение и дворф-пивовар Мрачнобух Громовар, который варит здесь своё светлое." } } } },
    ["0032c7cd"] = { d = 19.7, g = 1, v = "narrator", c = { m = { { 0.00, "Это письменное доказательство подтверждает тот факт, что путник убил Маргола Яростня – бич Тлеющего ущелья." }, { 8.66, "Музей Стальгорна ценит этот экспонат и благодарит дарителя за столь щедрое подношение." }, { 15.70, "-Главный куратор музея, Ториус Каменный Сторож" } }, f = { { 0.00, "Это письменное доказательство подтверждает тот факт, что путница убила Маргола Яростня – бич Тлеющего ущелья." }, { 8.85, "Музей Стальгорна ценит этот экспонат и благодарит дарителя за столь щедрое подношение." }, { 15.93, "-Главный куратор музея, Ториус Каменный Сторож" } } } },
    ["0037ce32"] = { d = 23.9, v = "narrator", c = { x = { { 0.00, "НАСТАВЛЕНИЕ ПО ВОИНСКИМ ЗВАНИЯМ." }, { 2.73, "Ниже перечислены воинские звания Альянса, снабжённые пояснениями, касающимися народов Орды." }, { 10.41, "Звания представлены в двух разделах – офицерский и рядовой состав – и перечислены в каждом разделе в убывающем порядке, от старших к младшим." }, { 22.18, "Да здравствует Альянс!" } } } },
    ["0058706b"] = { d = 36.9, v = "narrator", c = { x = { { 0.00, "Долина Копий — укрытая горами долина на западе Пустошей, куда ведут лишь узкие проходы с юга и востока." }, { 8.55, "Здесь живёт племя Мародин — хранители Мародона, священной гробницы Зейтара, отца всех кентавров; вход в неё — на юго-западе долины." }, { 19.06, "Стеречь его дозволено лишь самым сильным воинам племени, а правит здесь вождь Храта." }, { 25.93, "Мародин не ищут союзников и встречают пришельцев копьями." }, { 30.61, "У северного края долины в клетке томится гоблинша Мелисса, пленница кентавров." } } } },
    ["006d5b31"] = { d = 33.8, g = 1, v = "scourge-male", c = { m = { { 0.00, "Многие наши соплеменники считают, что тайная магия и чародейство – единственные источники силы." }, { 9.62, "Но ты-то так не думаешь, герой?" }, { 12.79, "Клинки – наша магия, щиты – наши обереги, броня – наша мудрость." }, { 19.51, "Будучи мёртвыми, мы сохраняем и умножаем свою силу." }, { 24.68, "Ищи меня в таверне в Могильнике." }, { 28.03, "Там мы обо-всём и поговорим." }, { 30.76, "-Даннал Штерн, наставник воинов" } }, f = { { 0.00, "Многие наши соплеменники считают, что тайная магия и чародейство – единственные источники силы." }, { 9.29, "Но ты-то так не думаешь, героиня?" }, { 12.54, "Клинки – наша магия, щиты – наши обереги, броня – наша мудрость." }, { 19.03, "Будучи мёртвыми, мы сохраняем и умножаем свою силу." }, { 24.02, "Ищи меня в таверне в Могильнике." }, { 27.27, "Там мы обо-всём и поговорим." }, { 29.90, "-Даннал Штерн, наставник воинов" } } } },
    ["00dbfbea"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Разрушенная башня в западной части топей — обветшалый дозорный пост, некогда построенный людьми Терамора." }, { 7.87, "Теперь в нём засели дезертиры, бросившие службу леди Джайне; их главарь, говорят, знает кое-что о пропавшем дипломате, которого ищет весь Терамор." }, { 18.83, "Город считает башню потерянной и посылает сюда только тех, кто готов задавать вопросы силой." } } } },
    ["0122ab90"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Драконы встретились высоко в небе над Силитусом, в тысячах метров над твердыней Ан'Кираж." }, { 7.58, "Там был Анахронос, дитя Ноздорму, Аспекта Времени." }, { 11.86, "Из Изумрудного Сна явилась Меритра, дитя Изеры, Аспекта Природы." }, { 17.37, "Келестраз, отпрыск Алекстразы, Аспекта Жизни, представлял Красных драконов." }, { 23.80, "Аригос же, дитя Малигоса, Аспекта Магии, говорил от имени Синих драконов." } } } },
    ["01431271"] = { d = 38.0, v = "narrator", c = { x = { { 0.00, "Кардрос и воины Громового Молота отправились на север через пограничные ворота Дун Альгаз и основали своё собственное королевство под далёкой горой Грим Батол." }, { 12.41, "Там Громовые Молоты разбогатели и построили новые сокровищницы." }, { 17.37, "Тауриссан и другие члены клана Чёрного Железа не были столь же удачливы." }, { 23.05, "Униженные и разгневанные своим поражением, они поклялись отомстить Стальгорну." }, { 29.22, "Уведя своих сородичей далеко на юг, Тауриссан основал город (названный в свою честь) под прекрасным Красногорьем." } } } },
    ["0150058c"] = { d = 34.2, g = 1, v = "orc-male", c = { m = { { 0.00, "Чтобы подчинить коня погибели, нужно сделать три вещи:" }, { 4.52, "Сотворить Круг Великого Призыва." }, { 7.14, "Внутри этого круга открыть портал в Ксорот и вывести коня через него." }, { 12.97, "Победить его и покорить его дух." }, { 15.66, "На следующих страницах подробно описан каждый из трёх шагов." }, { 20.54, "Сделать это непросто, но ты доказал, что способности у тебя есть." }, { 25.79, "Я уверен, что ты со своей целеустремлённостью подчинишь себе коня гибели." }, { 31.62, "Читай дальше." }, { 32.78, "-Мор'зул Кровопуск" } }, f = { { 0.00, "Чтобы подчинить коня погибели, нужно сделать три вещи:" }, { 4.39, "Сотворить Круг Великого Призыва." }, { 6.94, "Внутри этого круга открыть портал в Ксорот и вывести коня через него." }, { 12.61, "Победить его и покорить его дух." }, { 15.23, "На следующих страницах подробно описан каждый из трёх шагов." }, { 19.97, "Сделать это непросто, но ты доказала, что способности у тебя есть." }, { 25.14, "Я уверен, что ты со своей целеустремлённостью подчинишь себе коня гибели." }, { 30.81, "Читай дальше." }, { 31.94, "-Мор'зул Кровопуск" } } } },
    ["015c3d71"] = { d = 30.2, g = 1, v = "human-female", c = { m = { { 0.00, "Секрет успеха жреца – в его связи с миром." }, { 3.28, "Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред." }, { 13.92, "Но к этому ты должен прийти сам." }, { 16.33, "Когда ты это осознаешь, тебе понадобятся новые способности и заклинания." }, { 21.75, "Вот с этим я могу тебе помочь." }, { 24.10, "Приходи в библиотечное крыло Аббатства Североземья." }, { 27.91, "-Жрица Анетта, наставница жрецов" } }, f = { { 0.00, "Секрет успеха жреца – в его связи с миром." }, { 3.23, "Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред." }, { 13.71, "Но к этому ты должна прийти сама." }, { 16.22, "Когда ты это осознаешь, тебе понадобятся новые способности и заклинания." }, { 21.56, "Вот с этим я могу тебе помочь." }, { 23.87, "Приходи в библиотечное крыло Аббатства Североземья." }, { 27.63, "-Жрица Анетта, наставница жрецов" } } } },
    ["01628035"] = { d = 31.3, v = "narrator", c = { x = { { 0.00, "Зелёный Пояс — полоса леса и болот на востоке Болотины, за развилкой на дороге к Дун Модру." }, { 7.49, "Здесь обитает Зелёный Страж, древний хранитель здешних мест, о котором в гавани говорят с опаской: он рыщет по болотам вместе с кроколисками и прочими тварями." }, { 20.39, "Страж печётся о природе края и с неприязнью смотрит на гноллов, вырубающих лес, и на порчу, что поразила его меньших болотных сородичей." } } } },
    ["0167594b"] = { d = 31.2, v = "narrator", c = { x = { { 0.00, "Искать спасения для своего застигнутого врасплох народа пришлось Малфуриону Ярости Бури." }, { 7.02, "Родной брат Малфуриона, Иллидан, практиковал магию высокорождённых, и Малфуриона очень сильно беспокоила его растущая одержимость." }, { 17.16, "Малфурион убедил брата отказаться от свого пагубного пристрастия и вместе с ним отправиться на поиски Кенария." }, { 25.82, "Кроме того, братьям надлежало собрать силы для сопротивления демонам." } } } },
    ["0174519d"] = { d = 13.4, v = "human-male", c = { x = { { 0.00, "Ван Клиф..." }, { 0.88, "Неразборчиво." }, { 1.97, "Вызывает МЕНЯ?" }, { 3.22, "ДА КЕМ ОН СЕБЯ ВОЗОМНИЛ???" }, { 5.33, "Я – Клейвен Мортвейк!" }, { 7.09, "И чтобы какое-то насекомое ещё мне указывало?!" }, { 10.82, "Остальные страницы книги утеряны." } } } },
    ["0174c2d4"] = { d = 23.8, v = "narrator", c = { x = { { 0.00, "Зловещее море омывает восточный берег Внутренних земель, у подножия Отвесных скал." }, { 6.94, "Это неизведанные воды, которые редко пересекают корабли, и на картах за ними не значится ничего." }, { 15.09, "Лишь рыбаки из деревни Сломанного Клыка выходят в прибрежные волны, да морские черепахи греются на песке." } } } },
    ["01b532e7"] = { d = 28.0, v = "narrator", c = { x = { { 0.00, "Святилище Эссины прячется в лесной лощине к западу от Астранаара и к югу от заставы Мейстры." }, { 7.51, "Это древнее место ночных эльфов, посвящённое духу дикой природы Эссине: тихая поляна с прозрачной водой под сенью старых деревьев." }, { 18.23, "Сюда не заходят ни сатиры, ни орки, и это одно из немногих мест в лесу, где ещё можно перевести дух, не опасаясь нападения." } } } },
    ["01dfa75a"] = { d = 29.6, v = "narrator", c = { x = { { 0.00, "Король Лордерона Теренас, уверенный в том, что орки готовят новое нашествие, созвал к себе своих самых преданных военачальников." }, { 10.01, "Он приказал генералу Туралиону и верховному магу Кадгару возглавить поход сквозь Тёмный портал, чтобы раз и навсегда разделаться с орками." }, { 20.65, "Силы Туралиона и Кадгара вторглись в Дренор и вступили в сражение с войсками Нер'зула на Полуострове Адского Пламени." } } } },
    ["020726b6"] = { d = 25.9, v = "nightelf-female", c = { x = { { 0.00, "Элуна с тобой." }, { 1.12, "Ветер прошептал мне твоё имя, и я очень рада, что могу принять участие в обучении следующего поколения охотников." }, { 9.39, "Я знаю, что ты сейчас где-то недалеко от Альдрассила." }, { 13.26, "Я буду ждать там." }, { 14.51, "Наши старейшины поручили мне подготовить всех новых охотников к грядущим испытаниям." }, { 20.62, "Ты входишь в их число." }, { 22.26, "До встречи." }, { 23.11, "-Аянна Вечнобродка, наставница охотников" } } } },
    ["02433eca"] = { d = 28.5, v = "narrator", c = { x = { { 0.00, "Восточная колонна — одна из двух исполинских скал, которые зовут Двумя Колоссами." }, { 6.16, "Её вершина плоская, и на ней прячется небольшое, но глубокое озерцо." }, { 11.30, "Дворф Греган видел, как по отвесной стене сюда вскарабкался огромный макрура, и с тех пор наверху не бывает тихо." }, { 19.86, "Спуститься отсюда своими ногами невозможно — путник, оказавшийся на вершине, должен заранее подумать о дороге вниз." } } } },
    ["0257faad"] = { d = 68.2, v = "narrator" },
    ["0273ec45"] = { d = 26.1, v = "narrator", c = { x = { { 0.00, "Сокрытое Море омывает весь запад Калимдора — от Тельдрассила на севере до берегов Фераласа и дальше." }, { 8.39, "Имя своё оно получило от тумана, которым ночные эльфы веками укрывали свой континент от чужих глаз." }, { 16.78, "У Забытого берега в его волнах поднимаются острова Сардор и Ужаса, а в глубинах ходят акулы и морские великаны." } } } },
    ["027bfa1d"] = { d = 27.4, v = "human-male", c = { x = { { 0.00, "Ноздорму:" }, { 0.67, "Ноздорму известен как Хозяин Времени и Вневременный." }, { 4.23, "Он и его драконы – бронзового цвета, показывают большую сметливость во всём." }, { 9.37, "Внимание Ноздорму всегда привлекают артефакты прошлого, ведь о нынешних делах смертных народов, как и о замыслах его сотоварищей-Аспектов, он особо не заботится." }, { 20.27, "Но его безразличие к задумкам других не означает, что он не уделяет внимания событиям, происходящим в мире." } } } },
    ["0280f5f4"] = { d = 18.1, v = "narrator", c = { x = { { 0.00, "Мглистая долина укрыта в южной части мыса, среди туманных холмов." }, { 5.51, "Здесь обитают могучие гориллы, чьи клыки и жилы ценятся охотниками и знахарями." }, { 11.98, "В северном конце долины прячется пещера Духов, где живёт троллиный знахарь." } } } },
    ["02a3668e"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Знойные Пески — широкая равнина на северо-западе Бесплодных земель, между Каргатом и Долиной Клыков." }, { 8.37, "Среди редких кактусов и чахлых деревьев рыщут койоты, кружат стервятники и медленно бредут малые каменные элементали." }, { 18.14, "У дороги, к востоку от Каргата, разбил свой лагерь учёный Лотвил, что изучает здешних элементалей и не терпит, когда его отвлекают от работы." }, { 29.70, "К югу от равнины дымят костры огрского лагеря Вург." } } } },
    ["02fbab56"] = { d = 32.4, v = "narrator", c = { x = { { 0.00, "Архиепископ Алонсий Фаол." }, { 2.02, "Блаженный покровитель Церкви Света." }, { 4.81, "Несмотря на то что архиепископ Фаол начал свой светлый путь в Стратхольме, что в Лордероне, он всегда был другом Штормграда." }, { 14.22, "В тёмные времена после Второй войны он помогал монастырю в Североземье и жертвовал значительные средства на восстановление самого города." }, { 24.74, "Сей собор стоит не только как бастион Света, но и как памятник благородному духу и щедрости человека." } } } },
    ["0319794a"] = { d = 21.6, v = "narrator", c = { x = { { 0.00, "Сейчас Король-лич Артас пребывает в Нордсколе." }, { 3.51, "Говорят, что он собирается восстановить Ледяную Корону." }, { 7.63, "Его верный помощник Кел'Тузад командует силами Плети в Чумных землях." }, { 12.97, "Сильвана же со своими Отрёкшимися удерживает лишь Тирисфальские луга – небольшую часть растерзанного войной королевства." } } } },
    ["033b6750"] = { d = 35.4, g = 1, v = "creature/bolvar", c = { m = { { 0.00, "Соломон!" }, { 0.65, "Предъявителю данного приказа дарован официальный статус действующего представителя Штормграда." }, { 7.38, "Вы можете воспользоваться его помощью в поисках доказательства участия чёрных драконов в делах клана Чёрной Горы." }, { 15.46, "В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозёрье." }, { 31.51, "С наилучшими пожеланиями," }, { 33.32, "Верховный лорд Болвар Фордрагон" } }, f = { { 0.00, "Соломон!" }, { 0.65, "Предъявителю данного приказа дарован официальный статус действующего представителя Штормграда." }, { 7.39, "Вы можете воспользоваться её помощью в поисках доказательства участия чёрных драконов в делах клана Чёрной Горы." }, { 15.36, "В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозёрье." }, { 31.42, "С наилучшими пожеланиями," }, { 33.24, "Верховный лорд Болвар Фордрагон" } } } },
    ["034adc19"] = { d = 45.5, v = "narrator", c = { x = { { 0.00, "Лорд Брант Вэлор, глава рода Вэлор." }, { 2.90, "Лорд Брант, да упокоится он с миром, был воплощением всего лучшего, что есть в Альянсе." }, { 9.73, "Прирождённый вождь, он привёл жителей Вороньего Холма к процветанию." }, { 15.03, "Когда тьма начала расползаться по лесам, он первым поднял наш народ на защиту." }, { 21.35, "Не было для лорда Бранта врага омерзительнее нежити." }, { 25.63, "Он сам обходил кладбища Сумеречного леса, сдерживая бредущие орды мертвецов." }, { 31.80, "В тот день, когда чудовища тяжело ранили его, весь город разделил его боль." }, { 37.90, "Благодаря заботе семьи он вернулся к своему долгу, но недуг так и не отпустил его до конца дней." } } } },
    ["0368ec0a"] = { d = 27.8, v = "narrator", c = { x = { { 0.00, "Северный Дол — разрушенный городок к северу от часовни Последней Надежды, на пути к перевалу в Кель'Талас." }, { 8.44, "Живых здесь давно нет: по руинам скользят банши и незримые безглазые соглядатаи Плети, а воду соседнего озера отравили и населили порченые элементали." }, { 20.48, "Говорят, именно здесь сын Тириона Фордринга отрёкся от Серебряной Длани и ушёл к Алому ордену." } } } },
    ["037649dd"] = { d = 20.9, v = "narrator", c = { x = { { 0.00, "Военные звания Альянса." }, { 2.39, "Офицеры: главнокомандующий, фельдмаршал, маршал, командор, лейтенант-командор, рыцарь-защитник, рыцарь-капитан, рыцарь-лейтенант, рыцарь." }, { 15.83, "Рядовые: старшина, старший сержант, капрал, рядовой." } } } },
    ["03965fbd"] = { d = 22.9, v = "narrator", c = { x = { { 0.00, "Полубог Кенарий обитал неподалёку оттуда на Лунных полянах горы Хиджал." }, { 6.00, "Его сыновья, известные как Хранители Рощ, наблюдали за ночными эльфами и регулярно помогали Часовым поддерживать мир на этих землях." }, { 16.96, "Даже скромные дочери Кенария, дриады, стали появляться всё чаще и чаще." } } } },
    ["03a545ac"] = { d = 49.1, v = "orc-male", c = { x = { { 0.00, "Наши союзники Отрёкшиеся обитают в землях под названием Тирисфальские леса – это на восточном континенте." }, { 8.05, "Глубоко под руинами города, что некогда звался Лордероном, ты найдёшь Подгород." }, { 14.09, "Чтобы попасть в Тирисфаль, выйди из города через великие южные ворота и отправляйся на восток, к башне дирижаблей." }, { 22.97, "Садись на дирижабль, что причаливает с южной стороны башни." }, { 27.55, "Перелетев через великое море, ты прибудешь в городок Брилл." }, { 32.13, "Оттуда просто иди на север, к руинам Лордерона." }, { 35.88, "Найди подъёмник, спустись на нём в глубины Подгорода и разыщи в Королевском квартале Тёмную Госпожу." }, { 43.44, "Только предупреждаю: столица Отрёкшихся может показаться тебе... жутковатой." } } } },
    ["03c0c9f2"] = { d = 43.8, v = "gnome-male", c = { x = { { 0.00, "Кормок." }, { 0.57, "Двухголовый огр некромант" }, { 2.36, "Что сказать о Кормоке?" }, { 3.95, "Это двухголовый огр-заклинатель, который, кстати, не всегда был так уж плох." }, { 9.24, "Когда мы его приняли к себе, мы взялись за одну работу в Пылающих степях, и он был нашим пленником." }, { 16.32, "Но он оказал нам неоценимую помощь, когда мы попали там в небольшую переделку, и после этого стал одним из наших главных магов." }, { 25.31, "Что нас в нём немало удивило, так это то, что две его головы вели себя совершенно по-разному." }, { 31.87, "Одна из них была вечно весёлая, даже немного глуповатая, вторая же – коварная и расчётливая, а взгляд в её глазах был совершенно безжизненным." }, { 41.69, "Пугающее зрелище, скажу я тебе." } } } },
    ["03cac899"] = { d = 35.1, v = "narrator", c = { x = { { 0.00, "Остров Очищения поднимается из Великого моря к югу от берега Хилсбрада — крутая скала, обвитая спиральной тропой." }, { 9.49, "На вершине стоят старое кладбище и разрушенная сторожевая башня." }, { 14.87, "Остров населён неупокоенными: проклятые паладины и судьи, осуждённые монахи и служители, корчащиеся в муках маги — духи людей и дворфов, которым нет покоя и после смерти." }, { 28.92, "Живым здесь делать нечего, и лишь самые отчаянные переправляются сюда вплавь." } } } },
    ["03e3d245"] = { d = 13.2, v = "narrator", c = { x = { { 0.00, "Здесь опасность кругом!" }, { 2.14, "Жаждут враги заковать" }, { 4.21, "Нас обратно в оковы." }, { 6.10, "Помни же в яростной битве" }, { 8.50, "О том, кто свой выполнил долг." }, { 11.14, "Адский Крик вечно живёт!" } } } },
    ["03e429de"] = { d = 30.2, v = "dwarf-male", c = { x = { { 0.00, "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Дун Морога." }, { 5.42, "Большая часть троллей, обитающих в Дун Мороге, сконцентрирована в форте Мерзлогривов, горной пещере на западной границе." }, { 13.84, "Их численность может вызывать некоторые опасения, однако, похоже, они не собираются покидать свою пещеру." }, { 21.37, "Вне всяких сомнений, они не хотят вызывать гнев дворфов и рисковать своей шкурой." }, { 27.18, "Они всего лишь обороняют свою территорию, и" } } } },
    ["03fbb2db"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Общими усилиями Медив и волшебники Совета Теней открыли портал между измерениями – Тёмный портал." }, { 7.51, "Этот портал позволил армии Дренора попасть на Азерот." }, { 11.71, "Гул'дан послал через портал разведчиков, чтобы они исследовали земли, которые им предстояло завоевать." }, { 19.62, "Вернувшись, они доложили Совету Теней, что можно начать вторжение." } } } },
    ["04265f3d"] = { d = 27.5, v = "narrator", c = { x = { { 0.00, "Анналы Дарроушира." }, { 1.61, "Поселение Дарроушир, названное в честь озёра Дарроумир, находится к западу от этого озера на южной границе Лордерона." }, { 11.53, "Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война." }, { 22.76, "Герои появляются во время войны, а после неё их забывают." } } } },
    ["0447da2b"] = { d = 58.9, v = "human-male", c = { x = { { 0.00, "Моя дорогая Амелия!" }, { 1.44, "То, что я увидел сегодня, навсегда останется в моей памяти." }, { 5.58, "Стратхольм охвачен огнём… и в этом наша вина." }, { 8.78, "Сегодня ночью мы вышли на городские улицы, и наш принц велел нам врываться в дома мирных жителей и… убивать их, пока они спят." }, { 17.56, "Принц Артас сказал, что они поражены чумой и их нужно лишить жизни, пока они не сделали то же самое с нами." }, { 25.15, "Началась резня." }, { 26.28, "Сотни людей погибли от рук тех, кто поклялся их защищать." }, { 30.23, "Я просто не мог на это смотреть и сбежал." }, { 33.12, "Да, я теперь дезертир, но у меня не поднялась рука совершить столь ужасное злодеяние." }, { 39.01, "Смотря на лица этих несчастных, обречённых на смерть горожан, я видел тебя… и наших детей…" }, { 45.29, "И если противостоять подобной жестокости – предательство, значит так тому и быть." }, { 50.87, "Надеюсь, мне удастся вернуться к тебе вовремя, но на дорогах сейчас небезопасно." }, { 56.45, "Передай детям, что я люблю их." }, { 58.58, "Джеймс" } } } },
    ["04581935"] = { d = 26.0, v = "creature/furbolg", c = { x = { { 0.58, "Удачи тебе." }, { 1.64, "Вот тебе подсказка, как справится с приспешниками Аррока:" }, { 6.39, "Заклятие Омокка, убивающее огров, останется в силе даже после гибели самого Омокка." }, { 13.56, "В бою с приспешниками Аррока пробуди силу в голове Омокка – и она, может быть, убьёт твоих врагов!" }, { 21.86, "Способ что надо." } } } },
    ["04622942"] = { d = 13.3, v = "narrator", c = { x = { { 0.00, "Сначала Анахронос отказывался вовлекать свой народ в дела низших рас." }, { 5.33, "Лишь после дерзкого нападения киражей на Пещеры Времени он согласился выступить сообща с ночными эльфами." } } } },
    ["04707cfc"] = { d = 32.9, v = "narrator", c = { x = { { 0.00, "Сумеречный лагерь — один из четырёх станов Сумеречного Молота в Силитусе, обнесённое низкой стеной скопище хижин и нор." }, { 9.33, "Сектанты в тёмных одеждах поклоняются Древним богам и по обрывкам старого пророчества возвели здесь Ветровой Камень, через который взывают к своим повелителям из Совета Бездны." }, { 23.21, "Хранители лагеря ревниво берегут тексты Истинно Верующего, и любого чужака, застигнутого у камня, ждёт немедленная расправа." } } } },
    ["047da6de"] = { d = 33.5, v = "narrator", c = { x = { { 0.00, "Яшмовая шахта лежит у подножия гор к северо-востоку от башни Азоры." }, { 5.14, "Вместе с рудником Подземных Глубин она была одной из главных шахт Элвинна и снабжала Штормград рудой в годы войн." }, { 13.72, "Теперь её заполонили кобольды, а армия, занятая на дальних границах, не может выделить людей, чтобы выгнать эту нечисть." }, { 22.85, "В самых глубоких штольнях поселилась колония пауков, для которых кобольды стали лёгкой добычей, так что вглубь шахты лучше не соваться без нужды." } } } },
    ["04835242"] = { d = 37.0, v = "nightelf-male", c = { x = { { 0.00, "Несса, рад был получить от тебя весточку." }, { 3.26, "Коллекция костей и чешуек, которую ты послала мне, превосходна." }, { 8.22, "Никогда ещё я не видел за пределами материка рыб такого размера." }, { 13.25, "Должно быть, рыбаки деревни Рут'теран с лёгкостью выуживают по тонне за день!" }, { 19.20, "Я хоть и завидую размеру их добычи, но всё же немного обеспокоен." }, { 24.23, "Может ли наше новое древо Жизни сделать так, чтобы наша рыба дорастала до таких же размеров?" }, { 31.67, "И если может, то чего ещё следует ожидать?" }, { 35.07, "Это стоит обдумать." }, { 36.69, "-Лайрд" } } } },
    ["04a26278"] = { d = 10.9, v = "narrator", c = { x = { { 0.00, "Компендиум Форора по убийству драконов - это толстая исписанная книга." }, { 5.85, "К сожалению, текст выглядит искажённым и не имеет для вас смысла." } } } },
    ["04c71eb6"] = { d = 22.8, v = "human-female", c = { x = { { 0.00, "Здравствуй, Вильям!" }, { 1.45, "Мы уже много лет не разговариваем, но я надеюсь, что у вас с братом всё в порядке и что ваша аптека процветает." }, { 9.43, "У меня к тебе просьба, Вильям." }, { 11.74, "В общем, мой внук Томми Джо влюблён в юную Мейбелл Маклюр." }, { 15.96, "Они друг в друге души не чают, но наши семьи..." }, { 19.52, "Конечно, наши семьи враждуют уже много лет..." } } } },
    ["0506f7fc"] = { d = 19.0, v = "narrator", c = { x = { { 0.00, "Эльфы сказали Торадину, что армия троллей неисчислима, что, уничтожив Кель'Талас, они двинутся на юг." }, { 7.87, "Будучи в отчаянии, эльфы, нуждавшиеся в военной помощи, быстро согласились обучить некоторых избранных людей искусству магии в обмен на помощь." } } } },
    ["0517d062"] = { d = 25.8, v = "gnome-male", c = { x = { { 0.00, "Дорогой дневник, сегодня мой злейший враг Нарайн Причудень пытался меня обмануть, послав вместо себя друзей на казнь." }, { 8.88, "На СВОЮ казнь." }, { 9.97, "Ты можешь в это поверить?" }, { 11.93, "Я, несмотря ни на что, разрабатывал свой дьявольский план, чтобы выманить его из этой проклятой хижины, а он выкинул такое!" }, { 21.08, "Да что там…" }, { 21.90, "Больше писать не могу, слишком зол." }, { 24.61, "Продолжу позже." } } } },
    ["052ee89b"] = { d = 24.8, v = "narrator", c = { x = { { 0.00, "Затем Артас погрузил останки Кел'Тузада в священные воды Солнечного Колодца." }, { 6.35, "Могучие воды Вечности были осквернены этим злодеянием, но Кел'Тузад воскрес и вернулся в этот мир могущественным личом." }, { 16.17, "Кел'Тузад, чьи силы теперь многократно возросли, объяснил, в чём состоял следующий этап плана Короля-лича." } } } },
    ["0576f467"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "Долина Кошмаров — широкая долина на юго-западе Тирисфаля." }, { 4.87, "Когда-то здесь зеленели рощи и водилось лесное зверьё, но деревья засохли, а всё живое сожрали голодные псы тьмы и огромные летучие мыши-вампиры." }, { 16.85, "На краю долины стоит заброшенная башня, куда Алый орден прислал капитана Перрина с отрядом." } } } },
    ["058fa927"] = { d = 24.7, g = 1, v = "dwarf-male" },
    ["05a1ba8e"] = { d = 30.6, v = "human-female", c = { x = { { 0.00, "Я начала мои эксперименты с предположения, что кровавые камни были каким-то видом камня, как кварц или обсидиан." }, { 7.66, "Посему я запустила серию экспериментов для опознания того, какие минералы содержатся в кровавом камне, какие силы использовались для придания ему такой твёрдости и цвета, и других свойств, сходных с камнем или рудой." }, { 22.37, "Но подвеска Кровавого камня, к моему разочарованию, не отреагировала на мои процедуры так, как это сделала бы обычная руда." } } } },
    ["05c9e398"] = { d = 28.2, v = "human-male", c = { x = { { 0.00, "Я долго исследовал Аспекты и их создателей-титанов – так долго, насколько хватит человеческой жизни." }, { 6.97, "Когда титаны покинули этот мир, Аспектов насчитывалось пять; это были могучие драконы, в задачи которых входила защита мира Азерота." }, { 16.33, "О них сложено множество разных историй, и даже сейчас, когда я собрал множество сведений, я знаю, что нам ещё очень многое предстоит узнать об этих величественных существах." } } } },
    ["05f02e54"] = { d = 25.5, v = "human-male" },
    ["062a2128"] = { d = 28.6, v = "orc-male", c = { x = { { 0.00, "Здесь покоится Дуротан – вождь клана Северного Волка и отец нашего почтенного Военного Вождя Тралла." }, { 8.69, "Он был храбрейшим среди нас, и его предали те, кто жаждал нашего порабощения." }, { 15.29, "Дуротан отдал свою жизнь, чтобы мы могли обрести свободу." }, { 20.34, "Мы чтим его и заветы, что он передал нам через своего сына." }, { 25.46, "Дрек'Тар, шаман клана Северного Волка" } } } },
    ["06984e3d"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Владыкой Приливов." }, { 1.49, "Так продолжалось много веков: Камень выносило на берег, а потом Владыка Приливов уходил в море." }, { 9.09, "Камень Приливов периодически упоминается в современных источниках, но почему столь могущественный предмет появляется с такой регулярностью и кто тому причиной, остаётся загадкой." } } } },
    ["06a525b7"] = { d = 37.8, v = "narrator", c = { x = { { 0.00, "Дарроушир — деревня на юге Восточных Чумных земель, разрушенная в Третью войну." }, { 6.57, "Плеть под началом повелителя вурдалаков и рыцаря смерти обрушилась на неё, и защитники, поначалу державшиеся стойко, были перебиты до последнего." }, { 18.30, "Ныне Дарроушир молчит: здесь остались лишь руины, призраки и память." }, { 23.90, "Павшие защитники бродят по Чумным землям вурдалаками на службе Плети, их души заперты в гниющих телах, и лишь изредка над развалинами вновь разыгрывается битва за Дарроушир." } } } },
    ["06b2630d"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Потеряв свою королеву, воины клана Чёрного Железа бежали от ярости Громовых Молотов." }, { 6.93, "Они бежали на юг, к крепости своего короля, но столкнулись с армией Стальгорна, пришедшей помочь Грим Батолу." }, { 15.76, "Зажатые между двух армий, силы Чёрного Железа были полностью уничтожены." } } } },
    ["06b52881"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Демоны-чернокнижники призвали инферналов, которые обрушились на изящные шпили калимдорских храмов будто адские пылающие метеоры." }, { 10.30, "Армия кровожадных убийц, называемых стражниками ужаса, прошла по калимдорским полям, уничтожая всё живое на своём пути." }, { 19.81, "Демонические гончие Скверны наводнили сельскую местность." }, { 24.42, "Разумеется, храбрые воины-кальдорай пытались защитить свои родные земли, но они не могли сдержать всю ярость Пылающего Легиона, и им пришлось шаг за шагом отступать." } } } },
    ["06c9c811"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Нер'зул выпустил на просторы ледяной пустыни чуму нежити, зародившуюся глубоко внутри Ледяного Трона." }, { 8.56, "Направляя её силами одного лишь разума, он привёл её в поселение людей." }, { 14.42, "Спустя три дня все его жители погибли, но вскоре восстали, превратившись в ужасных зомби." }, { 21.86, "Нер'зул чувствовал их мысли и настроения так же ясно, как свои." } } } },
    ["06de738a"] = { d = 29.4, v = "dwarf-male", c = { x = { { 0.00, "Болиды, что участвуют в гонках на Равнинах, имеют очень тонкие настройки и требуют внимательнейшего ухода." }, { 7.58, "Поэтому неудивительно, что у команды работа есть всегда." }, { 11.57, "Механики команды постоянно проверяют машины, чинят их и доводят." }, { 16.20, "Только так можно содержать технику в идеальном состоянии." }, { 20.31, "Итак... мы изыскиваем возможность немного притупить бдительность команды, поскольку при этом их машина быстро придёт в негодность." } } } },
    ["0710b7a4"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Несколько воинов, оставшихся в Строме, решили и дальше защищать древние стены." }, { 6.26, "Стром более не был центром империи, но он превратился в новое государство – Стромгард." }, { 13.01, "Хотя каждый город-государство сам по себе процветал, империя Аратор практически распалась." }, { 20.19, "Каждое государство завело свои собственные обычаи и верования, и они начали всё больше отдаляться друг от друга." }, { 29.08, "Мечта короля Торадина об объединении человечества развеялась." } } } },
    ["0723097a"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Пробираясь через Ясеневый лес, Адский Крик и его верные воины Песни Войны наткнулись на древних ночных эльфов-Часовых." }, { 9.70, "Полубог Кенарий решил, что орки вновь возжаждали войны, и хотел прогнать их из своих земель." }, { 17.21, "Но Адский Крик со своими воинами, преисполненные сверхъестественной ярости и злобы, убили Кенария и осквернили древние леса." } } } },
    ["076110b9"] = { d = 25.2, v = "human-female", c = { x = { { 0.00, "Или кровавый камень состоит из крови?" }, { 2.90, "И, если так, чьей крови?" }, { 4.72, "Моей?" }, { 5.19, "Крови другого человека?" }, { 7.01, "Животного?" }, { 7.82, "Или, может быть, кровавый камень – это кровь некоего неизвестного существа – того самого существа, которого Кеган одновременно почитал и боялся, когда отдавал мне эту подвеску?" }, { 21.10, "Вот вопрос, на который нужно получить ответ." }, { 24.47, "Это – ключ." } } } },
    ["0761b3ca"] = { d = 31.3, v = "narrator", c = { x = { { 0.00, "Дуротан, по-прежнему уверенный в том, что Гул'дан приведёт их народ к гибели, снова высказался против действий волшебников." }, { 9.45, "Храбрый воин сказал, что они уничтожили чистый дух орков и что это безрассудное нападение на Азерот погубит их всех." }, { 18.48, "Гул'дан не мог пойти на риск, убив любимого всеми героя, и был вынужден отправить Дуротана вместе с его кланом Северного Волка в самые отдалённые области нового мира." } } } },
    ["07633f40"] = { d = 40.3, v = "narrator", c = { x = { { 0.00, "Мельница Таррен стоит на севере предгорий, у подножия Альтеракских гор." }, { 5.60, "До Третьей войны это был обычный городок Лордерона; Плеть истребила его жителей, а опустевшие дома заняли Отрёкшиеся, и теперь это самое южное владение Подгорода." }, { 18.43, "Гарнизоном командует верховный палач Дарталия, подчинённая Вариматрасу: её задача — сдерживать людей Хилсбрада, пока аптекари вроде Лидона ищут состав новой чумы." }, { 31.26, "Церковь, несколько домов и высохшие сады окружают старую мельницу, а вокруг рыщут огры, йети и грабители Синдиката." } } } },
    ["07748c77"] = { d = 28.6, v = "human-male", c = { x = { { 0.00, "Мой дневник." }, { 0.89, "Ужасы последних недель почти лишают меня разума; единственное, что меня спасает, – записи в дневнике." }, { 8.09, "Я как будто исповедуюсь в своих грехах перед безмолвным собеседником или как будто освобождаю свою голову от мрачных мыслей, перенося их на бумагу." }, { 18.46, "Это второй мой дневник, первый остался в месте, куда я не могу вернуться." }, { 23.71, "Поэтому я начал всё с нуля." }, { 25.67, "Но в этот раз я буду писать только правду." } } } },
    ["077a7979"] = { d = 41.3, v = "narrator", c = { x = { { 0.00, "Долина Летлор — широкий скалистый каньон на востоке Бесплодных земель и самое опасное место во всей округе." }, { 8.80, "Здесь обитают чёрные драконы: над обрывами кружат опалённые дракончики, а в глубине долины ходят взрослые драконы-стражи." }, { 18.55, "Разведчики Каргата, что подбирались слишком близко, назад не возвращались, и никто не знает, сколько здесь драконов и как они велики." }, { 29.33, "Среди скал высятся кристаллические обелиски древних времён; говорят, под ними томятся в узилище чёрные драконы, и отомкнуть его может лишь Знак Земли." } } } },
    ["077d5dde"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "Участок Эддла – брошенная ферма на юго-западе Сумеречного леса, южнее Вороньего Холма и западнее лощины Вул'Гол." }, { 8.91, "Хозяева ушли отсюда, когда в лес пришла тьма, а ферму целиком захватило Братство Справедливости: разбойники крадутся по полю, ночные клинки прячутся в амбаре, а зачаровыватели колдуют в маленьком доме." }, { 24.56, "Агенты Штормграда полагают, что здесь хранятся бумаги, важные для короны, поэтому сюда порой посылают тех, кто не боится разбойников." } } } },
    ["0780b232"] = { d = 44.6, v = "narrator", c = { x = { { 0.00, "Погань — южная часть перевала, где дорога изгибается и выходит к Каражану." }, { 6.01, "В отвесных скалах вдоль неё огры Мёртвого Ветра вырыли свои курганы и пещеры, а стоянки разбили у самой обочины, чтобы сверху высматривать чужаков." }, { 18.03, "Одеты они в грязные лохмотья и бьются грубым самодельным оружием, но именно из-за них мало кто из шедших к башне возвращался." }, { 28.30, "Почему огры выбрали этот пустынный край, где им составляют компанию лишь беспокойные духи и стервятники, остаётся загадкой." }, { 38.20, "Иные шепчут, будто огры служат некоему «хозяину», но кто это — никто не скажет." } } } },
    ["07aa1743"] = { d = 39.8, v = "narrator", c = { x = { { 0.00, "Остров Терамор — скалистый остров у восточного берега болота и главный оплот Альянса в Калимдоре." }, { 7.52, "Леди Джайна Праудмур основала этот город после битвы за гору Хиджал, приведя сюда уцелевших с земель Лордерона, и отсюда держит хрупкий мир с Ордой Тралла." }, { 20.47, "За крепкими стенами стоят гавань, откуда корабли ходят в Гавань Менетилов, казармы стражи и башня самой волшебницы." }, { 29.44, "Но дальше стен власть Терамора не простирается: дороги стерегут дезертиры и таурены Зловещего Тотема, а в городе ищут пропавшего дипломата." } } } },
    ["07c53d8e"] = { d = 15.9, v = "narrator", c = { x = { { 0.00, "Некогда за власть над большей частью Калимдора боролась древняя раса разумных насекомых, известная под именем киражи." }, { 9.33, "Именно напыщенный Олений Шлем со своим войском ночных эльфов и сошёлся в бою с ними." } } } },
    ["07e186ff"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Застава Талрендис — небольшой лагерь ночных эльфов на юго-западе Азшары, у самого моста через Строптивую." }, { 8.12, "Отсюда часовые следят за проклятой землёй, что начинается сразу за рекой." }, { 13.69, "Путникам Альянса застава даёт приют и гиппогрифов до Аубердина и Кабестана, но иных услуг здесь не найти." } } } },
    ["07f2cea1"] = { d = 17.9, v = "narrator", c = { x = { { 0.00, "Когда Артас со своей армией нежити повернул на юг, в землях Кель'Таласа уже не осталось ни одного живого эльфа." }, { 9.49, "Славного королевства высших эльфов, просуществовавшего более девяти тысяч лет, больше не существовало." } } } },
    ["08146dbc"] = { d = 9.2, v = "narrator", c = { x = { { 0.00, "РЯДОВЫЕ ЗВАНИЯ ОРДЫ." }, { 2.45, "Высший Сержант." }, { 4.28, "Старший Сержант." }, { 6.22, "Сержант." }, { 7.24, "Рубака." }, { 8.16, "Разведчик." } } } },
    ["08195eb6"] = { d = 37.3, v = "narrator", c = { x = { { 0.00, "Легенда о Дедушке Зиме." }, { 2.06, "Говорят, что название \"Зимний Покров\" происходит от сверхъестественного существа, именуемого во многих культурах Дедушкой Зимой." }, { 12.81, "Считается, что, когда на исходе года он шествует по земле, за ним вздымающимся шлейфом ложится снежный покров." }, { 22.11, "Говорят, что просыпается Дедушка Зима под одеялом из снега и укрывает снежной вуалью землю." }, { 29.89, "Месяцы, когда Азерот частично укрыт снегом, дают земле время обновиться и переродиться." } } } },
    ["0857cf05"] = { d = 20.0, v = "narrator", c = { x = { { 0.00, "Зависимость Иллидана от магической энергии непрестанно мучила его, и он с трудом сдерживался, чтобы не броситься к источнику Вечности." }, { 10.07, "Однако Тиранда всё время была рядом и поддерживала его, так что в итоге они всё же добрались до полубога-отшельника по имени Кенарий." } } } },
    ["08762c1a"] = { d = 22.0, v = "narrator", c = { x = { { 0.00, "Туннель Ужаса — длинный извилистый ход сквозь гору на северо-западе края, от Долины Ужаса до берега реки Тондрорил." }, { 9.42, "Его населили нерубы, могильные твари Плети, и время от времени по туннелю проходит их могучий надсмотрщик." }, { 18.18, "У выхода к реке живёт отшельник Тирион Фордринг." } } } },
    ["08c79c41"] = { d = 9.8, v = "narrator", c = { x = { { 0.00, "ЖИЗНЕННО ВАЖНЫЕ ДАННЫЕ!" }, { 2.04, "УРОВЕНЬ СЕКРЕТНОСТИ пять тысяч сто двадцать два!" }, { 6.06, "Дальше страница испещрена нулями и единицами." } } } },
    ["08d06d5b"] = { d = 13.3, v = "human-male", c = { x = { { 0.00, "Вот от этой самой бочки иди прямёхонько на север." }, { 3.48, "Иди, пока не увидишь пустой кувшин рядом с заброшенной ветряной мельницей, стоящей на крутом берегу у моря." }, { 11.14, "В том кувшине найдёшь, что ищешь." } } } },
    ["0901eeeb"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Лабиринты Иглошкурых — исполинский терновый холм на юге Степей, пронизанный ходами, где живёт племя Иглогривых." }, { 8.57, "По преданию, шипы эти выросли из крови полубога Агамаггана, и свинобразы считают их священными." }, { 16.01, "В глубине лабиринта правит старая шаманка племени, а по коридорам бродят вепри, летучие мыши и загнанные в клетки пленники — среди них незадачливый гоблин Вилликс, явившийся сюда за корнем синелиста." }, { 31.60, "Кривозуб из Таурахо когда-то был здесь своим." } } } },
    ["090f50da"] = { d = 26.1, v = "narrator", c = { x = { { 0.00, "Но зная, что все вожди, в первую очередь Адский Крик и Оргрим Молот Рока, начнут борьбу за превосходство, Гул'дан поставил во главу Орды своего вождя-марионетку." }, { 13.53, "На эту роль он выбрал Чернорука Разрушителя, злобного и жестокого орка." }, { 19.47, "Под командованием Чернорука Орда выдвинулась в первый пробный бой против дренеев." } } } },
    ["091d3906"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Шли месяцы; к Кел'Тузаду приходили всё новые и новые приверженцы Культа Проклятых." }, { 6.61, "Кел'Тузад на удивление легко добился своей цели: многие потеряли веру в Священный Свет и стали поклоняться тёмному владыке Нер'зулу." }, { 17.28, "Культ Проклятых становился всё более влиятельным, но благодаря Кел'Тузаду власти Лордерона всё ещё не замечали перемен…" } } } },
    ["0931a51e"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Мглистый берег — полоса побережья озера Лордамер, что тянется от Овчарни Дандреда до купола Даларана." }, { 8.07, "Здесь всегда стоит туман, в камышах греются черепахи, а на воде виднеются Рассветные острова и мрачная громада крепости Фенрис." }, { 18.21, "У берега затаились фанатики Алого ордена, готовые напасть на всякого, кто подойдёт слишком близко." } } } },
    ["09370170"] = { d = 23.7, v = "narrator", c = { x = { { 0.00, "И так он бродил, и так он искал." }, { 2.86, "И его рука оставалась потерянной для него." }, { 6.78, "И так он изрыгал проклятия и рычал при ходьбе." }, { 10.94, "Но Гри'лек давно перестал слушать духов, и они были сердиты на него и не слышали его проклятий." }, { 19.76, "Гри'лек был обречён." }, { 21.56, "Обречён бродить без руки." } } } },
    ["09645725"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Руины Соларсаля лежат к юго-западу от Крепости Оперённой Луны, на том же острове Сардор." }, { 6.96, "Некогда здесь стояло поселение ночных эльфов, а теперь среди упавших колонн хозяйничают наги Гребня Ненависти." }, { 15.77, "В Крепости с тревогой следят за руинами: наги что-то ищут в развалинах, и находки, попадающие оттуда в руки эльфов, ставят учёных в тупик." } } } },
    ["0971e867"] = { d = 22.4, v = "narrator", c = { x = { { 0.00, "Лагерь Бофф стоит на юго-востоке Бесплодных земель, у дороги, ведущей к долине Летлор." }, { 6.67, "Это небольшая стоянка огров-Гнилобрюхов, которую стерегут лишь несколько громил." }, { 12.86, "Но именно сюда наведывается главарь племени То'грун, что обходит все четыре лагеря огров, и в Каргате давно ждут с ним встречи." } } } },
    ["097e2cab"] = { d = 39.4, v = "narrator", c = { x = { { 0.00, "Судьба Карлина Редпата" }, { 1.87, "Карлин, брат капитана Джозефа Редпата, был тяжело ранен в битве за Дарроушир, однако ему удалось выжить." }, { 10.28, "Через несколько дней измученного жаждой и сильным жаром Карлина, неизвестно как оказавшегося возле Перекрёстка Корина, подобрали агенты Серебряного Рассвета." }, { 22.71, "Они залечили его раны и доставили в часовню Последней Надежды." }, { 27.81, "Благодарный Карлин вступил в ряды Серебряного Рассвета." }, { 32.26, "И в наши дни он сражается с Плетью, стремясь отомстить тем, кто погубил его дом и его брата." } } } },
    ["09927249"] = { d = 12.3, v = "human-female", c = { x = { { 0.00, "Добудь нефрит." }, { 1.05, "Он попадается в различных местах." }, { 3.33, "Камень довольно редок, но если ты спросишь о нём у кузнеца или инженера, они, вероятно, смогут продать тебе несколько таких камней." } } } },
    ["09c31fcc"] = { d = 25.7, v = "narrator", c = { x = { { 0.00, "Низинные чащобы — восточная часть Фераласа, что спускается от Лагеря Мохаче к каньонам Тысячи Игл." }, { 7.81, "Лес здесь ниже и светлее, чем на западе, а по холмам бродят гориллы, медведи и гноллы клана Древолапов." }, { 16.06, "Дорога из Таланаара в глубь джунглей проходит именно здесь, и таурены Лагеря Мохаче зорко следят за всеми, кто по ней идёт." } } } },
    ["09e3e428"] = { d = 22.1, v = "narrator", c = { x = { { 0.00, "Удел Ольсена стоит у главной дороги к югу от Гробницы и когда-то был бойкой фермой на самом торговом пути." }, { 8.23, "Через несколько лет после Третьей войны от хозяйства остались лишь заросшие бурьяном руины." }, { 15.23, "Здесь рыщет нежить, подчинённая Тулу Когтю Ворона, и нападает на любого, кто сойдёт с дороги." } } } },
    ["0a2b4e69"] = { d = 41.2, v = "narrator", c = { x = { { 0.00, "К северо-востоку от Аубердина, на холмах над дорогой, лежат руины Башал'Арана." }, { 6.49, "Вместе с Амет'Араном это был один из городов-близнецов, куда королева Азшара привела своих любимых слуг — высокорождённых; здесь жил маг Астерион, второй после правителя Атрикуса Нарассина." }, { 22.02, "Раскол уничтожил город, а спустя тысячелетия в руинах поселились грелли и сатиры, что питаются остатками древней магии." }, { 31.95, "Лишь к одному святилищу на западном краю руин демоны не приближаются: над ним разливается странное синее свечение." } } } },
    ["0a3c3213"] = { d = 37.8, v = "narrator", c = { x = { { 0.00, "Овчарня Дандреда — небольшая усадьба с фермой и пристанью на западном краю Высокогорья, у самого озера Лордамер." }, { 9.37, "Некогда она принадлежала альтеракскому дворянину, а теперь стала тайным убежищем предводителя Синдиката — наследника павшего королевского дома Альтерака." }, { 21.61, "Здесь его окружают телохранители и убийцы, а гостит у него орк Нагаз, жрец тайного ордена Недремлющего Аргуса." }, { 30.40, "Мировой судья Южнобережья подозревает, что за Синдикатом стоят силы куда страшнее разбойников." } } } },
    ["0a759759"] = { d = 19.2, v = "narrator", c = { x = { { 0.00, "Избавившись от всех противников, Король-лич мог, наконец, приступить к выполнению своей истинной миссии в этом мире." }, { 9.57, "Он устремил свои помыслы к землям людей, выискивая тех, в чьих душах скрывалась тьма, тех, кто слышал его зловещий зов…" } } } },
    ["0a83e63f"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Зул'Машар на северо-востоке края — древняя столица лесных троллей, некогда отделившихся от империи Амани." }, { 8.44, "Долгие войны с людьми Лордерона отняли у них большую часть земель, а чума довершила разгром: почти все тролли за пределами города обратились в нежить." }, { 20.39, "Ныне Зул'Машар — тень былого величия, и его обитатели с тревогой видят, как порча тайно подтачивает их собственных сородичей." }, { 30.33, "В сердце города высится зиккурат Мазра'Алор." } } } },
    ["0a929cbe"] = { d = 36.3, v = "narrator", c = { x = { { 0.00, "Пещеры предгорий уходят в склон холма на южной границе Альтеракских гор, там, где горы спускаются к Хилсбраду." }, { 8.84, "Некогда здесь укрылся чернокнижник Гелькулар, задумавший превратить себя в лича, но толпа крестьян отыскала его логово и жестоко расправилась с ним." }, { 20.83, "С тех пор пещеры облюбовали йети: их рёв разносится по тёмным ходам, а на стенах поблёскивают жилы олова и альтеракского гранита." }, { 31.06, "Лишь самые отчаянные путники решаются заглянуть сюда ради добычи." } } } },
    ["0aaec017"] = { d = 33.9, v = "narrator", c = { x = { { 0.00, "Саргерас выжидал подходящего момента, когда таящаяся в юноше сила даст о себе знать." }, { 6.60, "Уже будучи подростком, Медив заработал себе популярность среди жителей Азерота своими выдающимися магическими способностями и часто отправлялся на поиски приключений вместе со своими друзьями – принцем Азерота Лланом и Андуином Лотаром, одним из последних сыновей рода Арати." }, { 28.17, "Трое мальчишек постоянно попадали в переделки, но горожане их очень любили." } } } },
    ["0ae80c2f"] = { d = 11.8, g = 1, v = "human-male" },
    ["0b052e45"] = { d = 31.3, v = "dwarf-male", c = { x = { { 0.00, "Ружьё резко подалось назад в его руках." }, { 3.12, "Дуло ушло в сторону и попало под ствол ружья Ажек." }, { 7.08, "И именно в этот момент Ажек спустила курок." }, { 10.55, "Неуклюже вздёрнувшееся к кронам деревьев ружьё отчётливо и громко выстрелило." }, { 16.30, "Стая птиц, крича, вспорхнула в небо, разлетаясь во все стороны." }, { 21.16, "Струйка дыма вилась из дерева." }, { 23.59, "Мы в оцепенении смотрели, как гигантская ветка рухнула прямо на убегающую пантеру и сломала ей хребет." } } } },
    ["0b1384d3"] = { d = 21.1, v = "human-female", c = { x = { { 0.00, "Похоже, то, что прятал в своём сундуке Клейвен, оно оказало неблагоприятный эффект на обитателей башни." }, { 7.24, "Я подозреваю, что и другие стражники столь же слабы, и, возможно, даже сам Клейвен пал жертвой этих нежелательных побочных эффектов." }, { 16.44, "Агент Эмбер Кеарнен" }, { 17.90, "ШРУ семь, полевой оперативник, отдел восемь" } } } },
    ["0b62f931"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "На северо-западе Чумных земель лежит поле Джанис, когда-то живая, кормившая людей ферма." }, { 7.44, "Плеть поставила посреди поля громадный котёл, который днём и ночью выдыхает в небо ядовитые пары; стерегут его Хранитель котла Желчень, скелеты-чародеи и вурдалаки." }, { 20.91, "Порой сюда прорываются и крестоносцы Алого ордена, рубящие без разбора и мёртвых, и живых." }, { 28.28, "А в доме на краю поля бродит призрак хозяйки, Джанис Фелстоун." }, { 33.51, "Она всё зовёт мужа и не понимает, отчего ей так холодно." } } } },
    ["0b685941"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Каньоны Красногорья прорезают северо-западную часть края: узкие проходы между красных скал, где эхо разносит каждый шаг." }, { 9.99, "Здесь логово Изувоя, вожака гноллов стаи Красногорья, чей вой слышен даже в холмах над Приозёрьем." }, { 18.05, "Его громилы и мистики спускаются к городу, воруют лошадей из конюшен и грабят обозы на дорогах." }, { 25.97, "Кузнец Вернер Осгуд уверен, что без вожака стая разбежится, но Изувой не зря возглавляет её." } } } },
    ["0b789db3"] = { d = 36.9, v = "narrator", c = { x = { { 0.00, "Погибель Роланда – старая шахта на юго-востоке Сумеречного леса, к востоку от Гниющего сада." }, { 7.46, "Здесь теряется след жрицы ночных эльфов, принёсшей в эти края Косу Элуны, и здесь же отряд людей, спустившийся в шахту в поисках источника тьмы, был растерзан воргенами: единственным уцелевшим стал человек по прозвищу Трясунчик, поднявший Косу из камней." }, { 27.49, "Теперь в шахте живёт стая Ночной Погибели, в чьих жилах течёт горящая кровь, а их главарь Кишкодёр хранит горящий камень." } } } },
    ["0b8af7ae"] = { d = 24.7, v = "narrator", c = { x = { { 0.00, "В то время как высшие эльфы сражались не на жизнь, а на смерть против яростного натиска троллей, разрозненные, ведущие кочевой образ жизни люди Лордерона боролись за объединение своих земель." }, { 14.58, "Изначально племена людей постоянно совершали набеги на другие людские поселения, пренебрегая честью и не заботясь об объединении расы." } } } },
    ["0bae9666"] = { d = 33.1, v = "narrator", c = { x = { { 0.00, "Безветренный каньон — широкая полоса ущелий к северу от дороги между Заставой Вольного Ветра и Мерцающей равниной." }, { 9.61, "Здесь гнездятся крылатые змеи, и их ядовитые стаи вьются над скалами." }, { 15.40, "Именно у этих гнёзд нашли странное чужое яйцо, о котором шепчутся и на заставе, и на Пике Тёмного Облака: по преданию, из него должна вылупиться Арикара, Змея Мщения." }, { 29.29, "Отсюда же начинается тропа к Углу Семи Ветров." } } } },
    ["0bc782fb"] = { d = 43.0, v = "narrator", c = { x = { { 0.00, "Пустошь Гаррона — восточная из четырёх чумных ферм, и здесь стоит последний котёл, до которого ещё не добрался Серебряный Рассвет." }, { 10.25, "Над полем кружат голодные призраки и стонущие духи, а стережёт котёл один из Хранителей Плети." }, { 17.82, "Именно сюда судьба привела Джозефа Редпата, капитана ополчения Дарроушира: во время битвы за его деревню рыцарь смерти Мардук Чёрный растерзал его душу и обратил в злобную тень." }, { 32.29, "Силы Альянса в конце концов одолели Редпата на пустоши Гаррона, и его щит до сих пор лежит у амбара." }, { 40.43, "Приспешники Плети об этом помнят." } } } },
    ["0bfb5c7d"] = { d = 19.6, v = "narrator", c = { x = { { 0.00, "Луна над долиной взошла, Освещая ночные джунгли, Где воины сошлись на зов Защищать свой народ и святыни." }, { 10.01, "Луна над долиной взошла, Раздаются крики битвы, И кровь ручьями струится, Погибают враги и побратимы." } } } },
    ["0c0ce4b6"] = { d = 38.3, v = "quilboar-male" },
    ["0c6686af"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Когда проклятие демонов было снято, Орда превратилась из безжалостной военной машины в относительно свободный союз, направленный не столько на захват новых земель, сколько на жизнь и процветание." }, { 14.78, "Тралл и его орки предвкушали начало новой мирной эры, получая помощь от благородных тауренов и хитрых троллей из племени Чёрного Копья." } } } },
    ["0c85c3c0"] = { d = 30.5, v = "human-male", c = { x = { { 0.00, "Если бы я знал, что произойдёт, я бы отрезал свою собственную руку, лишь бы не вытаскивать этот кусок дерева, покрытый рунами." }, { 8.62, "Как сильно я жалею об этом!" }, { 10.56, "Я всегда думал, что сожаления – привилегия старости." }, { 14.19, "Теперь я знаю, что не старость, а отчаяние надевает на нас мантию из сожалений, не способную и не желающую спадать с плеч, сгорбленных страданием." }, { 24.12, "Но достаточно стенать, как какой-нибудь недоделанный поэт." }, { 28.12, "Я должен продолжать свои хроники..." } } } },
    ["0c8a2a68"] = { d = 21.3, v = "narrator", c = { x = { { 0.00, "Ещё до дней, которые мы помним, Мать-Земля своим дыханием создала золотые туманы рассвета." }, { 7.94, "Там где эти янтарные облака коснулись земли, появились бесконечные пшеничные и ячменные поля." }, { 16.20, "Это была чаша её творений – великая чаша жизни и надежды." } } } },
    ["0c95658e"] = { d = 23.1, v = "narrator", c = { x = { { 0.00, "Северная комбинация кристаллов" }, { 2.65, "Есть два возможных эффекта: наносящий урон и нейтрализующий его." }, { 8.17, "КРИСТАЛЬНЫЙ ЗАРЯД: требует жёлтых и красных кристаллов." }, { 12.92, "Провоцирует сильный взрыв." }, { 15.18, "КРИСТАЛЬНОЕ ВОССТАНОВЛЕНИЕ: требует жёлтых и зелёных кристаллов." }, { 20.55, "Наделяет вас целительной аурой." } } } },
    ["0c9aee3d"] = { d = 17.5, v = "tauren-male", c = { x = { { 0.00, "Гриш, твоя просьба об отпуске удовлетворена." }, { 3.87, "Посылаю тебе на смену таурена-воина, чтобы он занял твой пост, пока ты будешь проводить время с семьёй." }, { 12.94, "Через неделю доложи о возвращении!" }, { 16.02, "-Землепряд Маггран" } } } },
    ["0cb83855"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Единственными, кто внушал им тревогу, были могущественные древние драконы." }, { 5.80, "Хотя эти большие змееподобные существа часто жили отшельниками, они всегда старались охранять известные им земли от возможной угрозы." }, { 16.40, "Ночные эльфы решили, что драконы провозгласили себя защитниками мира и что их вместе с их секретами лучше не трогать." } } } },
    ["0cf501d2"] = { d = 19.9, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Брат, я надеюсь, ты получил эту руну." }, { 2.81, "Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине." }, { 7.95, "Я знаю, как важно для нас держаться вместе, особенно в такое неспокойное время." }, { 13.83, "Загляни ко мне, когда будет свободное время." }, { 17.17, "-Сольм Харгрин, наставник разбойников" } }, f = { { 0.00, "Сестра, я надеюсь, ты получила эту руну." }, { 3.06, "Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине." }, { 8.17, "Я знаю, как важно для нас держаться вместе, особенно в такое неспокойное время." }, { 14.02, "Загляни ко мне, когда будет свободное время." }, { 17.34, "-Сольм Харгрин, наставник разбойников" } } } },
    ["0d3292c6"] = { d = 33.1, v = "narrator", c = { x = { { 0.00, "Ксавиан лежит на северо-востоке Ясеневого леса, у водопадов, где река Фалфаррен спускается с гор в озеро." }, { 8.25, "Сатиры поселились здесь в руинах древнего храма ночных эльфов, и из трёх сатирских логовищ леса Ксавиан считается главным: здесь живут их вожди." }, { 19.53, "Название хранит память о Ксавиусе — высокорождённом, которого Саргерас обратил в первого сатира во время Войны Древних." }, { 28.83, "Дриады, приходящие сюда, редко возвращаются невредимыми." } } } },
    ["0d3cf4b2"] = { d = 31.1, v = "human-male", c = { x = { { 0.00, "Немного хорошего белокаменного дуба – прежде чем шахты под Луноречьем в Западном Крае были захвачены, в них было полно такой древесины." }, { 8.91, "Её использовали для производства наиболее важных решёток и инструментов из-за её жаростойкости и сопротивляемости нагрузкам." }, { 16.81, "Дуб завезли туда откуда-то из-за моря." }, { 19.40, "Эта редкая древесина достаточно прочна, чтобы использовать её при создании твоего оружия." }, { 25.30, "Если хотя бы немного её осталось в шахтах, то она найдётся у гоблинских резчиков по дереву." } } } },
    ["0d6586b7"] = { d = 36.4, v = "narrator", c = { x = { { 0.00, "В юго-восточных холмах Лок Модана стоит охотничий домик, построенный в изящном стиле высших эльфов, хотя из эльфов здесь остался лишь один." }, { 11.36, "Приютом Странников заправляет седой дворф Марек Железносерд, а вместе с ним тут живут люди, гномы и дворфы, промышляющие охотой." }, { 21.70, "Гости приезжают ради знаменитых кроколисков озера Лок: их шкуры и мясо охотно скупают торговцы." }, { 29.49, "Молодой Дэрил Юный любит похвастать своими подвигами и охотно бросает вызов новичкам." } } } },
    ["0d76e849"] = { d = 31.7, v = "narrator", c = { x = { { 0.00, "Пещера Итара – уединённый грот в самом юго-западном углу болота." }, { 5.29, "Здесь под личиной высшего эльфа живёт Итар, зелёный дракон, брат Эраникуса, супруга Изеры." }, { 12.57, "Вокруг пещеры резвятся зелёные дракончики, за которыми Итар присматривает, пока они не подрастут." }, { 20.51, "Он пришёл сюда ради затонувшего храма: драконов, стерёгших его, поглотил кошмар, и Итар ищет способ освободить своих сородичей от скверны." } } } },
    ["0d7d5a01"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "После долгих лет странствий высшие эльфы, наконец, нашли земли, напоминавшие Калимдор." }, { 6.61, "В глуши северных лесов они основали королевство Кель'Талас и поклялись создать могущественную империю, которая будет во всём превосходить цивилизацию их собратьев, калдорай." }, { 19.62, "К сожалению, эльфы вскоре узнали, что основали Кель'Талас на развалинах древнего города троллей, который те до сих пор считали священным." }, { 29.91, "Тролли почти сразу же начали атаковать эльфийские поселения." } } } },
    ["0d91990a"] = { d = 17.2, v = "narrator", c = { x = { { 0.00, "Глава третья: ЗАПАДНЫЙ ПИЛОН." }, { 2.53, "Западный пилон принимает красные, зелёные и синие кристаллы." }, { 7.52, "Пилон фокусирует энергию, которая создаётся при использовании красных кристаллов в качестве основного источника энергии." } } } },
    ["0d984456"] = { d = 17.3, v = "narrator", c = { x = { { 0.00, "Глава три: ЗАПАДНЫЙ ПИЛОН." }, { 2.28, "Западный пилон принимает красные, зелёные и синие кристаллы." }, { 7.39, "Пилон фокусирует энергию, которая создаётся при использовании красных кристаллов в качестве основного источника энергии." } } } },
    ["0da34f7e"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Приближённые слуги Азшары, которых она называла Кель'дорай или высокорождёнными, выполняли каждое её желание и считали себя выше своих собратьев." }, { 11.55, "И хотя королеву Азшару одинаково любили все её подданные, ревнивые массы эльфов втайне ненавидели высокорождённых." }, { 20.58, "Разделяя стремление жрецов познать тайны Источника Вечности, Азшара приказала мудрецам из числа Высокорождённых проникнуть в его секреты и раскрыть миру его истинное назначение." } } } },
    ["0dbbd136"] = { d = 26.5, v = "narrator", c = { x = { { 0.00, "От капитана Крассена порча перекинулась и на других защитников Дарроушира, которые после этого предавали и убивали своих бывших союзников." }, { 10.57, "Потом они вошли в поселение и перерезали всех, кто укрылся в домах." }, { 15.72, "Остатки армии Плети вместе с чёрной тенью Редпата покинули разорённое поселение и ворвались в Лордерон, неся с собой боль и смерть Второй войны." } } } },
    ["0dd4980c"] = { d = 25.0, v = "human-male", c = { x = { { 0.00, "Для немедленного распространения среди всех членов Сумеречного Молота." }, { 4.75, "В связи с текущим положением дел в Силитусе, всякое распространение текстов Истинно Верующего отныне должно проводиться в сопровождении не менее чем четырёх вооружённых бойцов Сумеречного Молота." }, { 17.89, "Все, уличённые в нарушении этого нового приказа, будут без промедления наказаны." }, { 23.31, "-Д'Сак Сумеречный Владыка." } } } },
    ["0de1feba"] = { d = 25.4, v = "gnome-male", c = { x = { { 0.00, "Вступление, продолжение." }, { 1.59, "Жаровню нужно использовать так же, как и Жаровню Призыва." }, { 5.30, "Просто помести её в любом из пяти мест с привидениями, и в ней пробудятся духи мертвецов." }, { 11.08, "Думаю, тебе будет интересно знать, что Знамя Вызова можно также использовать на арене в глубинах Чёрной горы." }, { 18.27, "Преподай Телдрену и этим болванам хороший урок, когда будешь там." }, { 22.63, "Если тебя это заинтересовало, читай дальше." } } } },
    ["0e029920"] = { d = 18.6, v = "human-male" },
    ["0e66dfe2"] = { d = 29.5, v = "scourge-male", c = { x = { { 0.00, "Рука Дагуна." }, { 1.20, "Дагун – существо из глубины, которому поклоняются мурлоки в Пылевых топях." }, { 7.86, "Они заманивают его на поверхность при помощи особенных морских водорослей, зачарованных их шаманами." }, { 16.77, "Найди мурлоков, собери их зачарованные водоросли, затем помести их на Алтарь Мурлоков." }, { 24.47, "Дагун придёт, когда будешь ждать его." }, { 27.84, "Мне нужна эта рука." } } } },
    ["0e71278f"] = { d = 35.3, v = "narrator", c = { x = { { 0.00, "Воющая долина — глухая лощина на севере Ясеневого леса, у самой границы с Осквернённым лесом." }, { 7.74, "В её глубине стоит древнее святилище с надписью, восхваляющей Элуну, и ночные эльфы чтут это место как священное." }, { 17.12, "Но теперь в долине поселились воргены, и по ночам отсюда доносится их вой, а древние, что охраняли святилище, иссохли и обезумели." }, { 27.77, "Говорят, здесь когда-то была спрятана Коса Элуны, и жрица, отыскавшая её, бесследно исчезла." } } } },
    ["0e8c5eec"] = { d = 34.1, v = "human-male", c = { x = { { 0.00, "В память о моём дорогом учителе, Горацио М." }, { 3.50, "Монтгомери, докторе медицины, целителе, учителе, друге." }, { 8.03, "Пятьдесят би-ти-эф-ти – двадцать пять эй-ти-эф-ти" }, { 11.82, "\"Мир полон боли и тягот." }, { 13.87, "Наша задача как целителей, НЕТ – мужчин или женщин, отдавших себя медицине, очистить его от всех болезней.\"" }, { 22.63, "- Почётный работник медицины, доктор медицины, доктор философии, доктор юридических наук, Великий Фермер, Экстраординарный Танцор, Друг Животных" } } } },
    ["0ea393cc"] = { d = 7.0, v = "narrator" },
    ["0ec17625"] = { d = 25.5, v = "human-male", c = { x = { { 0.00, "Малигос:" }, { 0.61, "Малигос известен как Управитель магии или Заклинатель." }, { 4.34, "Его естественное обличье не типично для драконов, и говорят, что он может изменять свой внешний вид по желанию." }, { 11.79, "Его редко видят после ухода далеко на север, а если и видят, то чаще всего в образе насекомоподобного создания, но, принимая форму драконов, он и его сородичи отливают различными оттенками синего цвета." } } } },
    ["0ec5ec7f"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Восточные ворота — боковой вход в Стратхольм с северо-востока Чумных земель." }, { 5.90, "За ними лежит площадь Старейшин и часовня, где ещё держится горстка живых." }, { 11.74, "Ворота заперты, и открыть их можно лишь ключом от города или искусной отмычкой; изнутри же их отворяет рычаг." } } } },
    ["0ec99be0"] = { d = 32.6, v = "narrator", c = { x = { { 0.00, "В восточных скалах Мулгора гоблины Торговой компании вырыли огромный рудник." }, { 5.79, "Таурены отказали им в праве на добычу, но компания не приняла отказа: руду и минералы вывозят караванами, а бригадир Шумовик, управляющий работами, строит планы, как изгнать тауренов с их земель." }, { 20.33, "У рудника три входа, но пешком можно пройти лишь через главный; в глубине скрыт небольшой лагерь лесорубов, куда компания собирается доставить свои новейшие крошшеры." } } } },
    ["0f2a3289"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Промёрзшая пещера — логово горных йети в центральной части Альтеракских гор." }, { 6.20, "Для этих свирепых созданий пещера — священное место: в её глубине горит древний ритуальный костёр, некогда сложенный чернокнижником Гелькуларом." }, { 17.94, "Говорят, что если сжечь на этом огне мясо, из глубин гор на запах явится самый могучий из йети." } } } },
    ["0f2ddc4d"] = { d = 35.3, v = "narrator", c = { x = { { 0.00, "Бастион — последний рубеж Отрёкшихся на границе с Западными Чумными землями." }, { 5.95, "У частокола стражи смерти несут дозор плечом к плечу с воинами Серебряного Рассвета: общая угроза Плети заставила на время забыть о разногласиях." }, { 17.50, "Ворота на восток ведут прямо в чумную мглу, и отсюда опытных бойцов Орды отправляют сражаться с приспешниками Короля-лича." }, { 27.21, "Защитники всегда начеку, но, как говорят в Брилле, порой Плеть всё же проскальзывает мимо них в Тирисфаль." } } } },
    ["0f3cb32d"] = { d = 26.3, v = "human-male", c = { x = { { 0.00, "Малигос:" }, { 0.63, "Малигос известен как Управитель или хранитель магии." }, { 4.37, "Его естественное обличье не типично для драконов, и говорят, что он может изменять свой внешний вид по желанию." }, { 12.09, "Его редко видят после ухода далеко на север, а если и видят, то чаще всего в образе насекомоподобного создания, но, принимая форму драконов, он и его сородичи отливают различными оттенками синего цвета." } } } },
    ["0f5db7cd"] = { d = 23.5, v = "narrator", c = { x = { { 0.00, "Высокогорье Блёклых Перьев — вотчина диких гиппогрифов, что вьют гнёзда на скалистых уступах." }, { 7.43, "Грифоноподобные птицы с оленьими рогами кружат над лесом, и подходить к их кладкам опасно." }, { 14.78, "Гоблины из Прибамбасска, впрочем, готовы щедро заплатить за яйца из этих гнёзд для своих сомнительных опытов." } } } },
    ["0f850155"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "Залив Бурь — часть Великого моря у восточного берега Азшары, где грозы не утихают почти никогда." }, { 7.63, "На дне залива лежит затонувшая половина Эльдарата, и наги Злобного Прибоя стекаются сюда за зачарованными кораллами." }, { 16.83, "У берегов залива находятся Гнездо Хетайры, храм Арккоран и островок с пещерой Чешуеборода, а среди волн торчат острые скалы и лабиринт рифов, делающий плавание почти невозможным." } } } },
    ["0fa6317d"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Пещера у Вязкой топи – большая пещера у края гор на востоке болота." }, { 5.43, "Её заняли мурлоки Болотного племени: внутри сыро, пахнет тиной и рыбой, а в глубине сидит их вожак – Болотный говорун." }, { 14.94, "Орки с Тростниковой заставы считают этих мурлоков угрозой и рады любому, кто согласится пройтись по пещере с оружием." } } } },
    ["0fb68c2b"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Лагерь Алого ордена — небольшое укрепление с баррикадами на восточном берегу озера Мерельдар, неподалёку от Длани Тира." }, { 8.75, "Здесь стоят солдаты и инквизиторы Алого ордена, охраняющие подступы к своей крепости." }, { 15.05, "Орден не делает различий между нежитью и живыми чужаками, так что путнику стоит обходить лагерь стороной." } } } },
    ["0fc6a728"] = { d = 33.1, v = "narrator", c = { x = { { 0.00, "Его старый друг Дуротан, вернувшийся из изгнания, напомнил ему о предательстве Гул'дана." }, { 7.14, "По приказу мстительного Гул'дана Дуротан и вся его семья были убиты, в живых оставили лишь его юного сына." }, { 15.87, "Но Молот Рока не знал о том, что сын Дуротана попал в плен к Адэласу Блэкмуру, одному из командиров армии людей, и стал его рабом." }, { 26.28, "Именно этому юному орку суждено было стать величайшим вождём в истории своего народа." } } } },
    ["0fdab607"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Судьба Мардука Чёрного." }, { 2.04, "Мардук пережил Вторую войну, сея смерть и страдания своим руническим мечом." }, { 8.72, "Хотя Мардук жив и сейчас, его меч был утерян в битве при Перекрёстке Корина." }, { 15.32, "Храбрый капитан дворфов разбил его своим зачарованным щитом, обратив Мардука в бегство и обеспечив победу Альянсу." }, { 25.45, "Сломанный меч погрузился в землю и осквернил её, образовав впадину, которую в наши дни называют Чумным Шрамом." } } } },
    ["0ff4cbaf"] = { d = 32.3, v = "narrator", c = { x = { { 0.00, "Бухта Барадин — часть Великого моря, омывающая западный берег Болотины." }, { 5.85, "Её воды простираются от северных утёсов Дун Морога до дальних берегов Лордерона, и именно по ним ходят корабли из Гавани Менетилов." }, { 16.38, "У побережья до сих пор видны остовы Третьей флотилии Кул-Тираса, сожжённой и потопленной красными драконами во Вторую войну." }, { 26.33, "На прибрежных отмелях промышляют мурлоки, а по мелководью бродят кроколиски." } } } },
    ["0ff8f3a9"] = { d = 37.7, v = "human-male", c = { x = { { 0.00, "Любезная Гелиана!" }, { 1.30, "Жаль вас разочаровывать, но я, Варгус, всё ещё пребываю в добром здравии." }, { 6.42, "Мне надоело быть посмешищем для всех и бродить по деревням в этих шутовских доспехах." }, { 12.46, "Теперь нам приказали отправиться в Андорал за зерном или ещё за чем-то там." }, { 17.84, "Скажите, пожалуйста, какое мне дело до зерна в Андорале?" }, { 21.93, "Да вся эта служба в армии – просто бред сумасшедшего." }, { 25.76, "Будьте уверены, тётя Гелиана, что я вернусь, и ваше наследство будет моим; даже если я буду истекать кровью и умирать от голода, моя злоба не даст мне умереть." }, { 37.31, "Варгус" } } } },
    ["1028bb54"] = { d = 37.6, v = "narrator", c = { x = { { 0.00, "Покинутая усадьба – холм на северном краю кладбища Вороньего холма, окутанный особенно густой тьмой." }, { 8.07, "На его вершине стоит дом некроманта Морбента Скверна, союзника тёмных всадников, который поднял мертвецов Сумеречного леса и правит ими из своего жилища." }, { 20.51, "Его охраняют не только приспешники из нежити, но и защитная магия, против которой бессильно обычное оружие." }, { 29.24, "Свен из лагеря на северо-западе леса ищет способ пробить эту защиту, а Штормград сюда солдат не пришлёт." } } } },
    ["10453677"] = { d = 29.4, v = "orc-male", c = { x = { { 0.00, "Джин'Зил," }, { 0.74, "Прошло немало времени, но я подумал, что ты захочешь узнать, что были убиты последние представители Кровавого Пера." }, { 9.41, "Но не благодари меня, убил человек, доставивший тебе это письмо." }, { 14.35, "Если хочешь, я могу прислать тебе их головы, после того как караван пройдёт через Степи." }, { 21.12, "Я знаю, что ты любишь использовать такие вещи в своей магии вуду." }, { 26.13, "Береги себя, старый друг." }, { 28.10, "-Дарсок Быстрый Нож" } } } },
    ["10536602"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "Красные скалы — природное образование из красного песчаника на северо-востоке Мулгора." }, { 7.04, "Это тихое, священное место: здесь павших героев тауренов через очищающее пламя провожают к Матери-Земле и Отцу-Небу, и сюда приводит юных тауренов один из обрядов Матери-Земли." }, { 21.72, "Недавно свинобразы из племени Дыбогривов вторглись на Красные скалы и осквернили святыню." }, { 28.98, "На утёсах над скалами стоит небольшая хижина, а под ней скрыта пещера." } } } },
    ["1072ecd3"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Великое море омывает южный берег предгорий." }, { 3.94, "Его воды у Хилсбрада холодны и неспокойны: у берега кормятся черепахи, а дальше в глубине ходят акулы." }, { 13.01, "С пристани Южнобережья в ясный день виден Остров Очищения, а вдоль побережья тянутся стоянки мурлоков и наг." } } } },
    ["107339c9"] = { d = 25.0, v = "dwarf-male", c = { x = { { 0.00, "Некоторое время назад в штабе Лиги Исследователей в Стальгорне нам читал лекцию главный археолог Седой Ус." }, { 7.58, "Старикан упоминал такое божество, почитаемое странными эльфами Дарнаса за его, по слухам, бескорыстную натуру..." }, { 15.55, "Ба!" }, { 15.80, "Один момент." }, { 16.76, "Я слышу хрюканье за моей палаткой." }, { 19.24, "Наверняка это просто щетинистые вепри пытаются добраться до моего запаса яблок..." } } } },
    ["10b514f6"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Объединившиеся эльфийские и человеческие армии вступили в схватку с огромной армией троллей у подножья Альтеракских гор." }, { 9.69, "Битва продолжалась много дней, но неослабевавшая армия Аратора не уставала и не отступала под натиском троллей." }, { 18.65, "Эльфийские властители решили, что пришло время ниспослать силы магии на врага." } } } },
    ["10b520d9"] = { d = 30.2, g = 1, v = "human-female", c = { m = { { 0.00, "Секрет успеха жреца – в его связи с миром." }, { 3.28, "Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред." }, { 13.92, "Но к этому ты должен прийти сам." }, { 16.33, "Когда ты это осознаешь, тебе понадобятся новые способности и заклинания." }, { 21.75, "Вот с этим я могу тебе помочь." }, { 24.10, "Приходи в библиотечное крыло Аббатства Североземья." }, { 27.91, "-Жрица Анетта, наставница жрецов" } }, f = { { 0.00, "Секрет успеха жреца – в его связи с миром." }, { 3.26, "Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред." }, { 13.82, "Но к этому ты должна прийти сама." }, { 16.35, "Когда ты это осознаешь, тебе понадобятся новые способности и заклинания." }, { 21.73, "Вот с этим я могу тебе помочь." }, { 24.06, "Приходи в библиотечное крыло Аббатства Североземья." }, { 27.85, "-Жрица Анетта, наставница жрецов" } } } },
    ["10d17b4d"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Война бушевала на просторах Каз Модана, Лордерона и самого Азерота." }, { 5.41, "Свирепая Орда сожгла дотла пограничные земли Кель'Таласа, после чего эльфы наконец-таки присоединились к Альянсу." }, { 14.58, "Война разрушила и разорила некогда процветавшие города Лордерона." }, { 19.85, "Несмотря на превосходящие силы врага, Лотар и его союзники сумели сдержать наступление Орды." } } } },
    ["10e9d768"] = { d = 29.3, v = "narrator", c = { x = { { 0.00, "Долина Ренда лежит на юго-востоке Красногорья, за озером и рекой, вдали от дорог." }, { 6.55, "Здесь орки клана Чёрной Горы разбили второй лагерь, поменьше и послабее северного, но вести о нём уже дошли до Приозёрья, и маршал Маррис велит бить орков без колебаний, где бы они ни встретились." }, { 21.76, "К югу от озера летают чёрные дракончики, и кузнец Вернер Осгуд охотно платит за чешую с их брюха." } } } },
    ["110e1822"] = { d = 23.7, v = "narrator", c = { x = { { 0.00, "Изера Дремлющая тоже зачаровала Древо Жизни, связав его со своим миром, астральным измерением, известным как Изумрудный Сон." }, { 10.35, "Этот огромный мир, населённый духами, не подчинялся законам физического мира." }, { 16.68, "Из своего Сна Изера могла управлять жизнью природы и развитием всего остального мира." } } } },
    ["11483c60"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "Сад Мальдена — небольшой заброшенный фруктовый сад на севере леса, у подножия холмов." }, { 6.83, "Хозяев здесь давно нет, деревья одичали, а по дорогам к саду бродят стаи воргов." }, { 13.37, "Аптекари Отрёкшихся ценят их обесцвеченные сердца: из них варят целительные зелья." } } } },
    ["114d27c9"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "Объединённые армии Стальгорна и Грим Батола отправились на юг с целью уничтожить Тауриссана и клан Чёрного Железа раз и навсегда." }, { 10.03, "Они не успели далеко уйти, когда гнев Тауриссана вызвал заклинание, приведшее к катаклизму." }, { 17.38, "Желая призвать сверхъестественное существо, которое поможет ему победить, Тауриссан призвал древние силы, спавшие в глубинах мира, и к своему ужасу он обнаружил, что появившееся существо было ужаснее самых страшных ночных кошмаров." } } } },
    ["11991a3a"] = { d = 36.7, v = "human-male", c = { x = { { 0.00, "Спустя несколько дней после того, как я начал прятаться в сарае, Свен отправился со своей фермы в Темнолесье." }, { 7.52, "Он поцеловал жену и улыбнулся детям, и обещал вскоре вернуться с игрушками и сладостями." }, { 13.61, "Несчастный человек." }, { 14.98, "То был последний раз, когда он видел свою семью живой." }, { 18.77, "По крайней мере, они расстались счастливыми." }, { 21.88, "И по крайней мере, его жена умерла первой, и ей не пришлось смотреть, как убивали её детей." }, { 28.22, "Но этот малый жест благоволения судьбы мне ничем не помог." }, { 32.26, "Я видел всё, что случилось, и это преследует меня в моих кошмарах." } } } },
    ["119bd7b1"] = { d = 16.7, v = "narrator", c = { x = { { 0.00, "Затем Нер'зул создал артефакты, чтобы распространить чуму среди народов Лордерона." }, { 6.51, "Он отдал их Кел'Тузаду и повелел волшебнику разнести их по земле." }, { 11.55, "А служителям своего культа приказал защищать артефакты любой ценой." } } } },
    ["11cc3b12"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Из древнего подземного королевства Азжол-Неруб, основанного расой зловещих пауков-гуманоидов, был послан элитный отряд воинов." }, { 9.44, "Они должны были напасть на Ледяную Корону и остановить помешанного на абсолютном господстве Короля-лича." }, { 17.33, "К своему разочарованию, Нер'зул обнаружил, что воины Неруба невосприимчивы не только к чуме, но и к его телепатии." } } } },
    ["11d64d3c"] = { d = 33.5, v = "narrator", c = { x = { { 0.00, "Когда измождённые ночные эльфы высадились на берег, они увидели, что священная гора Хиджал не пострадала при взрыве." }, { 9.32, "В поисках места для нового дома Малфурион и остальные эльфы поднялись на горные склоны и остановились на овеваемой всеми ветрами вершине." }, { 20.38, "Спустившись в поросшую лесом низину между двумя огромными пиками, они обнаружили там маленькое тихое озеро и, к своему ужасу, поняли, что воды его светятся магией." } } } },
    ["1217ec81"] = { d = 12.2, v = "creature/furbolg", c = { x = { { 0.58, "Снег ослепляет…" }, { 2.43, "Племя нужно защитить." }, { 5.14, "Дать им силу." }, { 6.77, "Быть сильным." }, { 8.40, "Не знаю…" } } } },
    ["12411654"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Эгвин никогда так и не узнала, что она поступила именно так, как хотел Саргерас." }, { 6.57, "Она неосознанно подписала приговор смертному миру, так как Саргерас во время своей физической смерти вселился духом в ослабленное тело Эгвин." }, { 18.24, "Без ведома юной Хранительницы Саргерас оставался скрытым в тёмных уголках её души многие годы." } } } },
    ["12417e11"] = { d = 24.4, v = "skyborne-male" },
    ["125471d8"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "Поле Валгана — ещё одна из заброшенных ферм севера Серебряного бора, к западу от Сияющего берега и к востоку от главной дороги." }, { 9.79, "Она названа по имени прежнего хозяина, который погиб или бежал, когда в лес пришла Плеть." }, { 16.81, "Теперь по заросшим полям бродят воргены Лунной Ярости." }, { 21.11, "В лучшие времена отсюда открывался прекрасный вид на озеро Лордамер." } } } },
    ["12bb485f"] = { d = 42.9, v = "narrator", c = { x = { { 0.00, "Одинокая башня Алталакса стоит на севере Тёмных берегов, к северо-востоку от Аубердина." }, { 6.95, "В дни расцвета высокорождённых в ней проводил свои дни Атрикус Нарассин — маг, которого сама королева Азшара поставила править Амет'Араном и Башал'Араном." }, { 18.97, "Спустя десять тысяч лет вокруг башни собрались чернокнижники клана Тёмной Нити, и среди них замечен даже сатир." }, { 27.92, "Из Аубердина сюда послали Балтула Удар Тени наблюдать за ними, и он прячется в лесу неподалёку." }, { 35.51, "Внутрь башни соваться не советуют: те, кто засел наверху, куда сильнее тех, что бродят снаружи." } } } },
    ["12bc35e8"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "В поисках правды о своих предках Тралл отправился на север, где обнаружил легендарный клан Северного Волка." }, { 8.56, "Там ему рассказали, как Гул'дан отправил Северного Волка в изгнание в самом начале Первой войны." }, { 16.39, "Тралл также узнал, что он – сын и наследник храброго орка Дуротана, вождя Северного Волка, погибшего на этих пустынных просторах почти двадцать лет назад." } } } },
    ["12dc504a"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Улей Регал лежит на юго-востоке Силитуса, у развалин Деревни Южного Ветра." }, { 6.02, "Это один из самых опасных ульев пустыни: его тоннели уходят глубоко под скалы, а на поверхности снуют рабовладельцы, роющие силитиды и тяжёлые стражи гнезда." }, { 18.48, "Неподалёку разбили лагеря дворфы Стальгорна и воины Орды под началом генерала Кирики: обе стороны добывают силитист, крупицы редкого кристалла, и не собираются уступать друг другу богатства пустыни." } } } },
    ["12e55f9b"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Был создан огромный заслон, питаемый энергией как ночных эльфов, так и драконов, – магический барьер, которому под силу было удержать силитидов и их повелителей в пределах стен Ан'Киража и выдерживать напор снаружи." }, { 17.32, "Ан'Кираж сам стал тюрьмой для врагов." } } } },
    ["12faddf2"] = { d = 28.2, v = "dwarf-female", c = { x = { { 0.00, "Мы спрятались в укромной пещере; похоже, это достаточно безопасное место." }, { 5.27, "Но мы всё равно находимся в ловушке до тех пор, пока не прибудет подкрепление." }, { 10.74, "Вельгар пытается продолжать работу, но, похоже, он всё ещё слишком напуган." }, { 16.08, "Мы находимся в тяжёлом положении, Таррел." }, { 18.98, "Пожалуйста, поторопи Длинную Косу со сбором дополнительных сил." }, { 23.48, "Я всё также сильно тебя люблю, даже в эти ужасные времена." }, { 27.79, "Меррин" } } } },
    ["1301758a"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Когда Иллидан, сопровождаемый нагами, отправился в путь, его начала преследовать Майев Песнь Теней." }, { 8.52, "Майев была тюремным стражником Иллидана десять тысяч лет и страстно желала вернуть его в заточение." }, { 16.79, "Но Иллидан, перехитрив Майев и её Смотрящих, сумел завладеть Оком Саргераса." }, { 23.87, "Найдя могущественное Око, Иллидан отправился в бывший город волшебников – Даларан." } } } },
    ["13222d7d"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Удел Страданий лежит сразу к востоку от руин Андорала." }, { 4.33, "Когда-то и эта ферма кормила людей, но теперь посреди поля бурлит чумной котёл, а вокруг него бродят гниющие и ледяные вурдалаки да зловонные зомби." }, { 16.00, "Кто-то из живых ещё прячется в уцелевшем доме, но лучше не задерживаться здесь надолго." } } } },
    ["1339b671"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Чёрная трясина — заболоченный край к востоку от бухты Менетил, у самой дороги в Гавань Менетилов." }, { 7.74, "Здесь много логовищ ящеров, и самые голодные твари выходят к обочине, так что даже короткий путь от гавани требует осторожности." }, { 18.02, "Среди кочек и чёрной воды бродят кроколиски, а в тумане легко сбиться с тропы." } } } },
    ["13583586"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Тенистая Крона стоит в самом северо-восточном углу Ясеневого леса, за Лесной Песнью." }, { 6.89, "Здесь растёт одно из Великих Древ, в котором открыт портал в Изумрудный Сон, и его охраняют зелёные драконы." }, { 15.37, "Зелёные дракониды ходят дозором по трое, и в их числе оракулы, стражи ветвей и хранители деревьев." }, { 23.20, "Говорят, порой из портала выходят драконы, поражённые Кошмаром, и тогда лучше держаться от Тенистой Кроны подальше." } } } },
    ["135f34d4"] = { d = 28.3, v = "narrator", c = { x = { { 0.00, "Врата Стальгорна ведут из снегов Дун Морога в дворфийскую столицу." }, { 5.37, "Их видно издалека: к ним поднимается широкий пандус с северной дороги, обставленный штандартами." }, { 13.07, "За воротами, в первом зале, стоит огромная статуя древнего верховного короля дворфов." }, { 20.04, "Здесь всегда людно: торговцы, послы и беженцы-гномы идут под своды горы, где правит Магни Бронзобород." } } } },
    ["1361dbce"] = { d = 32.4, v = "human-female", c = { x = { { 0.00, "Ни один из моих тестов не пролил свет на загадку происхождения кровавого камня." }, { 5.49, "В то время единственной загадкой, что мне удалось разгадать, было то, что кровавый камень – ни живое, ни мёртвое существо!" }, { 13.78, "Но тогда, на грани поражения, я сделала прорыв." }, { 17.08, "В моём последнем тесте не последнюю роль сыграла стеклянная колба с отколотым горлышком." }, { 23.13, "Когда я закончила свой тест, опять ничего не обнаружив, я убирала инструменты со своего рабочего стола и порезалась об острый край колбы." } } } },
    ["13620e52"] = { d = 15.1, v = "narrator", c = { x = { { 0.00, "Один." }, { 0.75, "Добыть один или восемь человек" }, { 4.60, "Два." }, { 5.14, "Бить человек сильно" }, { 7.49, "Три." }, { 8.03, "Бить человек ещё" }, { 9.95, "Четыре." }, { 10.92, "Класть его в огонь" }, { 13.17, "Пять." }, { 13.81, "Есть человек" } } } },
    ["1396562e"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Северное поместье стоит на северо-западной окраине нагорья, у дороги, ведущей к Стене Торадина." }, { 7.24, "Когда-то это была обычная ферма подданных Стромгарда, но после падения столицы её захватил Синдикат и превратил в свой форпост." }, { 16.84, "Отсюда разбойники перехватывают обозы, которые Южнобережье отправляет защитникам Стромгарда." }, { 23.74, "Ходят слухи, что в поместье творится и нечто похуже грабежа: на земле здесь находили амулеты из кровавого камня, какими пользуются при призыве демонов." } } } },
    ["139e1638"] = { d = 35.6, v = "human-male", c = { x = { { 0.00, "Тем временем я посылаю лейтенанта Элверолда в экспедицию вокруг континента Калимдор." }, { 5.72, "После того как его силы завершат экспедицию, им следует воссоединиться с нашими силами в крепости Тирагард." }, { 13.11, "По расчётам, экспедиция лейтенанта Элверолда должна занять довольно много времени." }, { 18.70, "Новый материк выглядит обширным и опасным." }, { 21.66, "Но если со мной или Бенедиктом стрясётся какая-либо беда, войска Элверолда сумеют снова захватить крепость." }, { 28.98, "Мы будем посылать одну экспедицию за другой, пока Тирагард не станет нашим!" }, { 33.86, "--Адмирал Праудмур" } } } },
    ["13a28dcd"] = { d = 29.5, v = "narrator", c = { x = { { 0.00, "Руины Зул'Кунды — обширный троллиный город на северо-западе долины, ныне вотчина племени Кровавого Скальпа." }, { 8.80, "Здесь живут их вожди и знахари, и отсюда племя совершает набеги на путников." }, { 14.98, "Кровавый Скальп охраняет священные для них кристаллы в холмах и люто ненавидит гоблинов, что жаждут наживы." }, { 23.56, "Ходят слухи, что за необычной магией племени стоит могущественный дух воды." } } } },
    ["13c72669"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Озеро, которое позже назовут Источником Вечности, было подлинным средоточием магических и природных сил мира." }, { 9.18, "Черпая энергию из Великой Запредельной Тьмы, Источник был как мистический ключ, питающий этой энергией мир и поддерживающий жизнь во всём её удивительном многообразии." }, { 22.73, "Со временем до берегов завораживающего колдовского озера добралось примитивное племя гуманоидов, ведущих ночной образ жизни." } } } },
    ["13ccc917"] = { d = 24.6, v = "dwarf-male", c = { x = { { 0.00, "Этим чудищем был самец тигра Тернистой долины." }, { 3.42, "Прежде чем мне удалось взвести винтовку, Эрлгедин поднял свой арбалет и выстрелил в зверя." }, { 9.87, "Стрела ушла немного в сторону и вонзилась в левый бок тигра." }, { 14.26, "Зверь попытался убежать, но его рана была слишком глубокой." }, { 18.58, "Он сумел сделать лишь несколько шагов, а затем его настиг метательный топор Барнила." } } } },
    ["13e1ddf5"] = { d = 28.4, v = "human-male", c = { x = { { 0.00, "Для немедленного распространения среди всех членов Сумеречного Молота." }, { 4.80, "Поиски предателя Ортелла продвигаются наилучшим образом." }, { 8.72, "Наши разведчики узнали, что он скрывается в лабиринте пещер Западного Края." }, { 13.96, "Предательство Ортелла прощать нельзя, а его побег ставит под угрозу всю нашу организацию." }, { 20.19, "Любой, кто станет утаивать сведения о местонахождении Ортелла, будет должным образом наказан." }, { 26.67, "-Эверан Сумеречный Владыка" } } } },
    ["1415d36a"] = { d = 53.6, v = "human-male" },
    ["146a9e66"] = { d = 38.6, v = "narrator", c = { x = { { 0.00, "Демоны-чернокнижники призвали инферналов, которые обрушились на изящные шпили калимдорских храмов будто адские пылающие метеоры." }, { 10.58, "Армия кровожадных убийц, называемых стражниками ужаса, прошла по калимдорским полям, уничтожая всё живое на своём пути." }, { 20.35, "Демонические гончие Скверны наводнили сельскую местность." }, { 25.09, "Разумеется, храбрые воины-калдорай пытались защитить свои родные земли, но они не могли сдержать всю ярость Пылающего Легиона, и им пришлось шаг за шагом отступать." } } } },
    ["14769c08"] = { d = 22.1, v = "narrator", c = { x = { { 0.00, "Когда последние очаги войны были ликвидированы, Альянс предпринял жёсткие меры для предотвращения угрозы со стороны орков." }, { 9.16, "На юге Лордерона были построены несколько лагерей специально для пленных орков." }, { 15.16, "Лагеря, охраняемые паладинами и опытными воинами Альянса, успешно справились со своей задачей." } } } },
    ["14a7630e"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Долина Клыков — узкая долина между двумя громадами скал в самом сердце Бесплодных земель." }, { 7.34, "Путь через неё небезопасен: здесь охотятся волки и хищные кошки, а над скалами кружат стервятники." }, { 15.19, "И всё же тут разбита одна из немногих стоянок в пустыне: у костра работает кузнец-изгнанник Мартек, мастер по металлу, к которому за помощью обращаются даже гонщики из далёкой Тысячи Игл." }, { 30.17, "Соседствуют с ним гном-изобретатель и гоблин-торговец, и вместе они держатся у огня посреди враждебной пустыни." } } } },
    ["14b30b07"] = { d = 20.2, v = "dwarf-male", c = { x = { { 0.00, "Ажек и сэр Эрлгедин вскинули своё оружие, прикрывая меня с боков, спиной к морю." }, { 5.93, "Барнил обречённо вздохнул и обнажил свой топор." }, { 9.36, "Кнутохвосты были практически рядом с нами." }, { 12.53, "Их уверенные шаги замедлились." }, { 14.77, "Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку." } } } },
    ["14b69adf"] = { d = 24.3, v = "human-male", c = { x = { { 0.00, "Дорогая Иветта, я доверяю это письмо нашему самому быстрому бегуну." }, { 4.83, "Я молюсь, чтобы он смог пробраться сквозь кольцо окруживших нас сил." }, { 9.47, "И молюсь, что ты прочитаешь мои слова, поскольку это последнее, что ты услышишь от меня." }, { 15.62, "Единственное, что меня успокаивает в эти мрачные дни, – это чувство облегчения от того, что я знаю: ты не разделишь мою участь." } } } },
    ["14c95a45"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "Судьба Мардука Чёрного" }, { 1.96, "Мардук пережил Вторую войну, сея смерть и страдания своим рунным мечом." }, { 8.33, "Хотя Мардук жив и сейчас, его меч был утерян в битве при Перекрёстке Корина." }, { 14.92, "Храбрый капитан дворфов разбил его своим зачарованным щитом, обратив Мардука в бегство и обеспечив победу Альянсу." }, { 25.06, "Сломанный меч погрузился в землю и осквернил её, образовав впадину, которую в наши дни называют Чумным Шрамом." } } } },
    ["14eac230"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Разбитая Колонна — несколько тролльских руин к югу от Прибамбасска, восточнее Безбрежных Песков." }, { 7.50, "Здесь разбил лагерь Марвон Клепальщик, гоблин-учёный и искатель сокровищ из Кабестана, оставивший свою мастерскую ради тайн пустыни." }, { 17.73, "Его интересуют газ'рилловые украшения — древние тролльские безделушки, разбросанные по всему Танарису." }, { 25.65, "Марвон повидал немало древних мест и, говорят, однажды едва выбрался из затонувшего храма в Болоте Печали." } } } },
    ["14f4891d"] = { d = 37.6, v = "nightelf-male", c = { x = { { 0.00, "Несса, рад был получить от тебя весточку." }, { 3.31, "Коллекция костей и чешуек, которую ты послала мне, превосходна." }, { 8.34, "Никогда ещё я не видел за пределами материка рыб такого размера." }, { 13.45, "Должно быть, рыбаки деревни Руттеран с лёгкостью выуживают по тонне за день!" }, { 19.42, "Я хоть и завидую размеру их добычи, но всё же немного обеспокоен." }, { 24.52, "Может ли наше новое древо Жизни сделать так, чтобы наша рыба дорастала до таких же размеров?" }, { 32.07, "И если может, то чего ещё следует ожидать?" }, { 35.52, "Это стоит обдумать." }, { 37.18, "— Лайрд" } } } },
    ["15047cee"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Благородные кланы орков странствовали по необъятным степям и охотились – больше ради развлечения, а дренеи начинали возводить города среди скал и горных вершин." }, { 12.61, "Кил'джеден решил, что, приложив немного усилий, из жителей Дренора можно сделать превосходных солдат для Пылающего Легиона." } } } },
    ["1511d9f0"] = { d = 11.5, v = "narrator", c = { x = { { 0.00, "Пленные орки жаждали сражений, но начальники лагерей, обосновавшиеся в крепости-тюрьме Дарнхольде, поддерживали среди них видимость порядка и спокойствия." } } } },
    ["152bd50b"] = { d = 31.1, v = "narrator", c = { x = { { 0.00, "Овраг Мёртвого Ветра — каменистая расселина, уводящая от главной дороги на юг, в сторону Каражана." }, { 7.64, "Западный путь идёт по её верхнему краю, между голых скал и окаменевших стволов, и обрывистые склоны хорошо заметны с тропы." }, { 17.26, "Ветер здесь бьёт особенно зло: он мечется между стенами оврага и стонет, как живой." }, { 23.77, "В конце расселины дорога выходит к южному мосту, за которым уже виднеется тёмный силуэт башни." } } } },
    ["154af50e"] = { d = 33.5, v = "narrator", c = { x = { { 0.00, "Стена Торадина отделяет нагорье Арати от предгорий Хилсбрада." }, { 4.93, "Король Торадин повелел возвести её вскоре после основания Строма, чтобы заслонить людей от набегов троллей Амани." }, { 14.08, "Многие века стена стояла стражем над этими землями, но теперь она сильно повреждена и зияет широким проломом, через который проходит дорога из Хилсбрада." }, { 26.45, "Обломки укреплений рассыпаны по холмам, а неподалёку от стены лежит Западный Круг Обуздания." } } } },
    ["154d9075"] = { d = 18.7, v = "dwarf-male", c = { x = { { 0.00, "Сара, моя любовь к тебе бессмертна, она словно связывает меня мощными путами, которые не разорвало бы ничто, кроме Всемогущества." }, { 9.73, "А любовь к королевству подхватывает меня, словно ураган, и необоримо влечёт меня вместе со всеми этими цепями на поле боя." } } } },
    ["154f400d"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Крепость Северной Стражи стоит на Торговом побережье к югу от Кабестана." }, { 5.60, "Её построили люди Терамора, и гарнизон Альянса встречает выстрелами всё, что движется: подозрительность здесь давно перешла все границы." }, { 15.90, "Пушки крепости захватывают гоблинские корабли, а уцелевших моряков держат в застенках, за что капитан Тало'тас Сияющий из Кабестана затаил на крепость обиду." }, { 27.93, "Для Орды это ближайший оплот Альянса в Степях." } } } },
    ["15799408"] = { d = 11.7, v = "narrator", c = { x = { { 0.00, "Рассказ о добродетели его" }, { 2.44, "Со смертью рыцаря не будет завершён." }, { 5.80, "Его мы чтим и воздаём хвалу!" }, { 8.40, "Пусть Утер в славе почиет и в Свете!" } } } },
    ["158d33e3"] = { d = 18.3, v = "narrator", c = { x = { { 0.00, "Иллидан потревожил своих старых должников высокорождённых и выманил из подводных убежищ змееподобных существ – наг." }, { 8.82, "Наги во главе с леди Вайш помогли Иллидану добраться до Таинственных островов, где, по слухам, находилась Гробница Саргераса." } } } },
    ["15eaaca8"] = { d = 25.0, v = "tauren-male", c = { x = { { 0.00, "Зверь, который правит этим островом, действительно ужасен." }, { 4.87, "Другие существа трепещут перед ним – и небогривые гориллы, и жагуары." }, { 10.65, "Его рёв постоянно звучит у меня в ушах и заставляет съёживаться от страха." }, { 16.79, "Эти существа наверняка остановят любого, кто придёт на остров." }, { 21.97, "Но придётся довериться воле предков..." } } } },
    ["160154b0"] = { d = 2.6, v = "narrator", c = { x = { { 0.00, "ДИАГРАММА ВОСТОЧНОГО ПИЛОНА" } } } },
    ["1609f3a1"] = { d = 26.9, v = "orc-male", c = { x = { { 0.00, "Глава два – Башни-близнецы" }, { 2.24, "Учти: Вандар Грозовая Вершина – враг умный и хитрый." }, { 6.65, "Разрушив передовые укрепления, надо помнить о том, что впереди ещё вторая линия обороны." }, { 13.97, "Это – башни-близнецы Каменный Очаг и Ледяное Крыло, из которых командиры управляют стражниками Грозовой Вершины вне Дун Болдара и патрулями Грозовой Вершины." } } } },
    ["1611f36f"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Наследники Арати, оставшиеся в ветшающих стенах древнего Строма, решили отправиться на юг, за каменистые горы Каз Модана." }, { 9.51, "Их странствия длились не один год, но наконец путешествие окончилось, и они поселились в северном регионе континента, который позднее назовут Азерот." }, { 21.22, "В плодородной долине они основали королевство Штормград, быстро ставшее независимой силой." } } } },
    ["162b468e"] = { d = 35.1, v = "narrator", c = { x = { { 0.00, "Бухта Менетил — залив между Гаванью Менетилов и северными утёсами Дун Морога, часть большой бухты Барадин." }, { 8.44, "Вода здесь мутная и тихая, и в ней в изобилии водятся кроколиски всех возрастов, чьи шкуры высоко ценят кожевники гавани." }, { 18.03, "К югу от порта, на дне залива, покоится эльфийский корабль «Орлик», шедший вместе с Третьей флотилией Кул-Тираса и потопленный теми же драконами, от которых пытался спастись." }, { 31.84, "Восточнее берега начинается Чёрная трясина." } } } },
    ["163afccc"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Анналы Дарроушира" }, { 1.52, "Поселение Дарроушир, названное в честь озёра Дарроумир, находится к востоку от этого озера на южной границе Лордерона." }, { 11.43, "Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война." }, { 22.56, "Герои появляются во время войны, а после неё их забывают." } } } },
    ["16676797"] = { d = 40.2, v = "narrator", c = { x = { { 0.00, "Непроглядная Пучина — затопленные пещеры под Зорамским взморьем, вход в которые скрыт под водой." }, { 7.54, "В давние времена здесь стоял великолепный храм Элуны, но Великий Раскол утопил его в Сокрытом Море." }, { 15.52, "Тысячелетия спустя порча Древнего бога осквернила священный лунный колодец, и из глубин поднялась Аку'май — чудовищная гидра, любимица Древних богов." }, { 27.52, "Сектанты Сумеречного Молота во главе с Келрисом сошлись здесь с нагами и приносят гидре невинные жертвы." }, { 35.93, "Разведчик Талрид ушёл в пещеры и до сих пор не вернулся." } } } },
    ["168bae3f"] = { d = 24.8, v = "narrator", c = { x = { { 0.00, "К тому времени, как безумие Саргераса поглотило остатки его некогда отважного духа, он уверовал в то, что титаны сами несут ответственность за ошибки своих созданий." }, { 13.08, "Решив, в конечном счёте, уничтожить плоды их трудов во всей вселенной, он захотел создать несокрушимую армию, которая огнём и мечом пройдёт по вселенной." } } } },
    ["169321be"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Роща Среброкрылых лежит на юге Ясеневого леса, к юго-западу от Аванпоста Среброкрылых и к западу от озера Зеркало Небес." }, { 9.92, "Это стан часовых Среброкрылых — ночных эльфов, поклявшихся изгнать орков клана Песни Войны из Ущелья Песни Войны, где те продолжают валить лес вопреки воле Тралла и шаманов." }, { 24.18, "Отсюда открыт вход в само ущелье, и здесь собираются бойцы Альянса, а военачальники раздают награды за отбитые у орков знамёна." } } } },
    ["16e69e3d"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Нам, \"Шмыг Инк.\", неприятно говорить о том, что мы получили несколько жалоб на некоторых жадных охотников за корнями, мало заботящихся о своих милых питомцах и отправляющих их в тёмные, опасные места на поиски корней." }, { 16.25, "Мы не станем мириться с такими безответственными хозяевами, но, желая удовлетворить пожелания клиента, мы выдаём гарантию на каждого проданного шмыгуноса, позволяющую новым владельцам вернуть покупку или получить нового зверька взамен потерянного." }, { 34.90, "Удачной охоты!" } } } },
    ["170a3f37"] = { d = 19.9, v = "narrator", c = { x = { { 0.00, "Спустя десять тысяч лет могучий демон Архимонд вновь ступил на Азерот." }, { 5.90, "Но в Даларане их путешествие не закончилось." }, { 9.48, "По приказу самого Кил'джедена Архимонд и его демоны последовали за Плетью в Калимдор, чтобы уничтожить Нордрассил, Древо Жизни." } } } },
    ["1730f694"] = { d = 41.4, v = "narrator", c = { x = { { 0.00, "Крепость Тёмного Клыка возвышается на холме над деревней Погребальных Костров." }, { 6.06, "Когда-то это был замок гилнеасского барона, но в Третью войну архимаг Аругал, вопреки советам Кирин-Тора, призвал из иного мира воргенов, чтобы обратить их против Плети." }, { 19.45, "Волчьи твари разгромили нежить, а затем набросились на людей: они взяли крепость и перебили барона со всем его домом." }, { 28.75, "Сломленный виной Аругал назвал воргенов своими детьми и затворился с ними в крепости, получившей новое имя." }, { 37.28, "Говорят, призрак барона до сих пор бродит по её залам." } } } },
    ["17349979"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "КОРМЛЕНИЕ И УХОД:" }, { 1.41, "Мы хотим обеспечить вас всем необходимым для ухода за питомцем." }, { 6.28, "Наши клиенты ожидают от «Шмыг Инкорпорейтед» именно такого уровня обслуживания, и мы с ними согласны!" }, { 14.19, "С этой целью мы разработали крепкие ящики для шмыгуносов, чтобы вы могли содержать питомца в безопасности и вне доступа света." }, { 24.07, "Для вашего удобства в каждом ящике находится отделение для корма, пронизанное чарующим ароматом клубней синелиста (любимого лакомства шмыгуносов)!" } } } },
    ["17361e69"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "Наш мир наполнен историей." }, { 2.46, "Историей народов, новых и старых." }, { 5.69, "Историей войн, тех, что давно угасли, и тех, что ещё тлеют." }, { 11.13, "Историей богов юных, что приходят вниз с небес." }, { 15.64, "Историей богов старых, что дремлют в земле." }, { 19.80, "Именно о них мой рассказ, о Древних Богах." }, { 23.80, "О тех, кто жил и бушевал по всему Азероту, когда мир был ещё молод." } } } },
    ["17365ef6"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Пантеон разрушил цитадель Древних Богов и заточил пятерых злых богов глубоко в недрах мира." }, { 7.36, "Элементали, которые не могли сдерживать своё буйство без власти Древних богов, были изгнаны в бездну миров, где они остались сражаться друг с другом на веки вечные." }, { 20.42, "С исчезновением элементалей природа смягчилась, и в мире наступила полная гармония." }, { 26.99, "Титаны увидели, что с угрозой покончено, и принялись за работу." } } } },
    ["17539ac3"] = { d = 39.3, v = "narrator", c = { x = { { 0.00, "Крепость Кенария стоит в сердце Силитуса на месте древнего поселения ночных эльфов и остаётся одним из крупнейших оплотов друидов в Калимдоре." }, { 11.14, "Круг Кенария держит здесь гарнизон со времён Войны Зыбучих песков, наблюдая за ульями силитидов и за тем, что заперто за Стеной Скарабея." }, { 21.73, "В крепости есть таверна, торговцы и площадка для грифонов и виверн, сюда стекаются гонцы из Стальгорна и Оргриммара." }, { 30.75, "А командующий крепости с тревогой ждёт вестей о пропавшей жене, которую в последний раз видели среди силитидов." } } } },
    ["17540869"] = { d = 64.6, v = "narrator", c = { x = { { 0.00, "Нагорье Арати — сухая холмистая равнина на юго-востоке Лордерона, между Стеной Торадина на севере и мостом Тандола на юге." }, { 10.06, "Это колыбель человеческой цивилизации: король Торадин основал здесь Стром, столицу империи Аратор, и отсюда люди вместе с эльфами сокрушили троллей." }, { 22.08, "На месте распавшейся империи выросло королевство Стромгард, чьи солдаты во Вторую войну стали опорой Альянса." }, { 30.97, "После Третьей войны оно пало: столицу захватили огры клана Тяжёлого Кулака и разбойники Синдиката, а остатки армии укрылись в Опорном пункте." }, { 42.56, "Орда заняла бывший лагерь для пленных орков и назвала его Павшим Молотом в честь вождя Оргрима." }, { 50.43, "В Низине Арати Лига Аратора и Осквернители Отрёкшихся сражаются за рудники и поля." }, { 57.06, "Между ними лежат древние круги Обуздания, а по холмам рыщут тролли, кобольды и хищные ящеры." } } } },
    ["1787b0ae"] = { d = 32.6, v = "nightelf-male", c = { x = { { 0.00, "В любом случае, по-видимому, его действия сопровождались определённым успехом." }, { 5.72, "Хотел ли он потренироваться на фурболгах перед тем, как заняться моим народом?" }, { 11.43, "Было ли у фурболгов что-то, чем он желал завладеть?" }, { 15.22, "Кто знает?" }, { 16.02, "Используя созданную им вещь (какой-то жезл или посох), он попытался проникнуть в племена фурболгов Ясеневого леса." }, { 24.40, "В какой-то момент – и именно здесь многое всё ещё не ясно – его обнаружили фурболги когда он пытался натравить их" } } } },
    ["17a79f0b"] = { d = 30.8, v = "narrator", c = { x = { { 0.00, "Лагерь у Кривой Сосны занимает дальний юго-западный угол Тельдрассила." }, { 5.79, "Это родовое поселение фурболгов племени Кривой Сосны, некогда мирных соседей ночных эльфов и покровителей леса." }, { 14.90, "Их вождь Урсал Изверг затмевает разум соплеменников мхом Скверны, и отсюда отряды фурболгов расходятся по всему острову." }, { 24.52, "Именно Урсала друиды Доланаара винят в беде, постигшей спящих друидов-воронов." } } } },
    ["17be48f2"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Пелвер Вмятина" }, { 1.27, "Тёмный хранитель Пелвер – наш наиболее почётный последователь." }, { 6.28, "Он хранит ключ гораздо дольше других, и это стоило ему многого." }, { 11.66, "Когда его ноша взывает к нему, он содержится под стражей в Жилом квартале." }, { 17.94, "Мы склоняемся пред его жертвой, и он останется в наших сердцах на многие годы... после того как его поглотит тьма." } } } },
    ["17c770b2"] = { d = 18.6, v = "narrator", c = { x = { { 0.00, "Хотя битвы с людьми заканчивались довольно быстро, обе расы успели выяснить сильные и слабые стороны соперников." }, { 8.31, "Ллейну и Лотару не удавалось получить точные сведения о численности орков, и они могли лишь догадываться о том, насколько могуч был их противник." } } } },
    ["17e24057"] = { d = 18.2, v = "human-male", c = { x = { { 0.00, "За то, что ты нашёл для меня бутылочку старого доброго виски, я скажу, где находится сокровище!" }, { 6.48, "Иди вдоль берега, двигаясь на запад от бутылки." }, { 9.78, "Дойдёшь до воды – плыви дальше на запад." }, { 12.59, "Через некоторое время ты приплывёшь на остров, где и найдёшь мой сундук с сокровищами!" } } } },
    ["17f3eac0"] = { d = 36.1, v = "narrator", c = { x = { { 0.00, "С тяжёлым сердцем, обуянный жаждой мести, могучий Фэндрал Олений Шлем усилил натиск." }, { 7.16, "Поражение в Силитусе стало бы великой бедой для ночных эльфов и, вполне возможно, для всего мира." }, { 15.45, "Битва кипела несколько месяцев." }, { 18.19, "Весь Силитус был захвачен киражами." }, { 21.16, "Оленьего Шлема и его армию отбросили к Танарису." }, { 25.35, "Видя, как уменьшилось его войско и сколько невинных жертв погибло, Фэндрал Олений Шлем утратил ту самонадеянность, что двигала им." } } } },
    ["18350ed7"] = { d = 27.8, v = "narrator", c = { x = { { 0.00, "Скалистое озеро лежит в верхней части Утёса Ветрорезов, и отсюда берёт начало Волчья река." }, { 7.09, "Над водой Торговая компания возвела громадное водяное колесо, к которому ведёт башня шатких лесов, и с этой высоты Геренцо надзирает за всей вырубкой." }, { 18.80, "Подняться туда непросто, а внизу, у самой воды, гоблинские механизмы день и ночь перемалывают то, что осталось от леса." } } } },
    ["185c0c5c"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Рассветные острова — цепочка низких островков у восточного берега, к югу от острова Фенриса." }, { 7.38, "Когда-то они поднимались из прозрачной воды озера Лордамер и считались чудесным местом, но чума нежити добралась и до них." }, { 18.00, "Деревья здесь растут больные и чахлые, а по берегам хозяйничают мурлоки и болотные твари." } } } },
    ["186112c3"] = { d = 25.1, v = "narrator", c = { x = { { 0.00, "Большинство этих встреч с демонами были отдельными случаями, и правившие магократы делали всё, что могли, чтобы хранить такие происшествия в тайне от народа." }, { 12.53, "Самые могущественные маги были посланы на борьбу с неуловимыми демонами, но нередко они обнаруживали, что безнадёжно уступают одиноким шпионам могучего Легиона." } } } },
    ["18663cb2"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "К востоку от Гавани Менетилов Лига Исследователей ведёт раскопки под началом геолога Вельгара." }, { 7.07, "Дворфы искали в этой земле древние окаменелости и каменные скрижали, но раскоп заполонили крапчатые ящеры, и учёным пришлось укрыться на уступе над ямой." }, { 18.63, "Внизу среди костей и обломков бродят ящеры и ожившие окаменелости, а в рыхлой земле по-прежнему лежит то, что дворфы не успели вынести на поверхность." } } } },
    ["1879666e"] = { d = 30.8, v = "gnome-male", c = { x = { { 0.00, "*Цитаты*" }, { 1.12, "\"Ты хочешь узнать о гоблинском инженерном деле?" }, { 4.65, "Спроси об этом одного из их лучших и талантливейших инженеров – мне кажется, его имя Набби Толстопал." }, { 12.18, "Хочешь знать, почему его так зовут?" }, { 14.84, "Таково гоблинское инженерное дело.\"" }, { 17.51, "-- Ринго Трагедикс, гномский инженер." }, { 20.24, "*\"Говори, что хочешь, о нас, гоблинах, но я скажу тебе вот что: У НАС ЕСТЬ ВЗРЫВЧАТКА!\" - Блямс Динамиттер, гоблинский бомбардир*" } } } },
    ["18871cb6"] = { d = 40.3, v = "human-male", c = { x = { { 0.00, "В эти месяцы у меня было достаточно времени для раздумий о моих старых верованиях и фанатизме." }, { 7.11, "Альянс?" }, { 7.72, "Орда?" }, { 8.19, "Добро?" }, { 8.72, "Зло?" }, { 9.06, "Значение этих слов, когда-то таких простых, теперь расплывалось перед моим взором, устремлённым на бескрайнее море." }, { 17.65, "Теперь я знаю, в чём причина." }, { 19.86, "Эти бананы следят за мной." }, { 21.88, "Сидят высоко и недоброжелательно следят за мной своими глазками." }, { 26.64, "И когда последний раз я пытался съесть один из них, он чуть не задушил меня!" }, { 32.21, "Я почти слышал его крик, когда я размазал его, наполовину откушенного, по камням." }, { 38.32, "Это – война, и я её выиграю." } } } },
    ["18c11d76"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Ревущий водопад скрыт в узком ущелье среди гор на северо-западе Элвинна." }, { 5.37, "Крутая тропа поднимается к нему справа от водопада Зеркального озера." }, { 10.54, "Наверху стоит одинокая хижина с наковальней и костром, у маленького причала качается лодка, а вокруг обосновалась горстка бандитов." }, { 20.22, "Ущелье замыкают водопады с обеих сторон, и река отсюда уходит к границе Западного Края." } } } },
    ["18e81031"] = { d = 41.9, v = "narrator", c = { x = { { 0.00, "Серадан — священная роща на северо-востоке Внутренних земель, посреди которой растёт великое древо." }, { 8.03, "В его корнях открыт круглый портал в Изумрудный Сон — один из четырёх на всём Азероте, наряду с порталами Ясеневого леса, Сумеречного леса и Фераласа." }, { 20.16, "Рощу оберегает зелёный род драконов: по тропам ходят дозоры драконоподобных стражей и оракулов, а в кронах отдыхают зелёные драконы." }, { 30.75, "Изредка из портала выходят и куда более древние и могучие создания Сна, и тогда даже бывалые путники предпочитают обойти Серадан стороной." } } } },
    ["18fb848d"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Утёс Треснувшего Копыта — крепость кентавров племени Галак у северной стены каньона, к востоку от Пика Тёмного Облака." }, { 9.47, "Среди шатров и костров здесь собираются мародёры, погонщики и заклинатели ветра, отсюда отряды уходят в набеги на караваны и на заставу тауренов." }, { 21.04, "В сердце утёса, в пещере, называемой Оплотом Треснувшего Копыта, племя хранит свою величайшую реликвию." } } } },
    ["1903ff99"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Магократы предложили решение – дать отдельным смертным воинам огромную силу, чтобы они использовали её для вечной тайной борьбы с Легионом." }, { 11.17, "Они настаивали на том, чтобы большая часть человечества никогда не узнала о Хранителях или угрозе нападения Легиона, поскольку иначе воцарится ужас и хаос." }, { 23.64, "Эльфы согласились с предложением и основали тайное общество, наблюдавшее за отбором Хранителей и помогавшее сдерживать хаос." } } } },
    ["191085ea"] = { d = 34.1, v = "nightelf-male", c = { x = { { 0.00, "Друг на друга." }, { 1.09, "Эльфы на месте фурболгов очень разозлились бы, но те отреагировали гораздо сильнее и убили Дартола." }, { 8.56, "Фурболги, по крайней мере в то время, не были теми порчеными существами, которыми они стали." }, { 15.62, "Они были всё ещё рациональными и умными – их отношения с нашим народом были дружественными." }, { 22.48, "Я надеюсь, что, если я смогу воссоздать жезл с помощью дриады по имени Шаэл'дрин, я смогу использовать его силу, чтобы помочь нашему народу... и фурболгам." } } } },
    ["1913aaf2"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Великое море омывает весь западный берег края." }, { 3.88, "Здесь опасные рифы, о которые разбился не один корабль, — их остовы до сих пор лежат у берега, а в тёмной воде ходят акулы." }, { 13.84, "Ночью над волнами кружит луч маяка, единственный ориентир для тех, кто идёт вдоль этого побережья." } } } },
    ["1913b9d4"] = { d = 23.2, v = "narrator", c = { x = { { 0.00, "Сокрытое Море — бескрайний океан, омывающий западный берег Пустошей." }, { 5.64, "Его штормовые волны бьют о Побережье Сар'Терис, а ветер поднимает над водой смерчи." }, { 12.44, "В глубинах у берега скрыты затопленные руины высокорождённых, где обосновались наги, и обломки кораблей, так и не доплывших до Фераласа." } } } },
    ["19180e2d"] = { d = 33.6, v = "narrator", c = { x = { { 0.00, "Они были первыми хозяевами мира и правили железной рукой." }, { 5.18, "И хотя теперь они закованы в цепи и спят, их слуги ещё на свободе, а нам, жалким смертным, с мощью этих слуг не совладать." }, { 15.78, "Те, кто пытался это сделать, изничтожены." }, { 19.39, "Те же, кто знает своё место, кто склоняет колени в мольбе перед прислужниками Древних Богов, кто без раздумий жертвует им душу и разум... лишь они обретут их милость." } } } },
    ["1919521c"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Горячие источники Голакка лежат на западе кратера, к северу от Пути Ужаса." }, { 6.03, "Вода здесь кипит и бьёт из земли гейзерами: неглубокие жилы магмы, идущие от вулкана Огненного Венца, греют озёра, и над ними круглые сутки стоит пар." }, { 18.02, "У берегов бродят элементали, рождённые кипятком и жаром, а исследователь Кракл, забравшись сюда с термометром, вычисляет, как связаны источники с вулканом." }, { 30.15, "Тёплая вода, говорят, годится и для любовных зелий — если кому-то хватит смелости её зачерпнуть." } } } },
    ["1927ecc2"] = { d = 71.6, v = "narrator", c = { x = { { 0.00, "Тлеющее ущелье — выжженная котловина на юге Каз Модана, между Лок Моданом, Бесплодными землями и Чёрной горой." }, { 9.04, "Когда-то здесь стояли зелёные горы Красногорья, но в Войну Трёх Молотов колдун-тан Тауриссан призвал Рагнароса, и взрыв разорвал землю: к югу от нового вулкана легли Пылающие степи, а к северу — провал, который назвали Тлеющим ущельем." }, { 28.39, "Ныне здесь хозяйничают дворфы Чёрного Железа, служащие Повелителю Огня: посреди ущелья они вырыли исполинский Котлован, где невольники добывают руду для их кузниц." }, { 41.81, "Гарнизоны Стальгорна давно отступили в Лок Модан и заперли ворота Подгорной тропы, а Орда прорубила к ущелью узкий проход из Каргата." }, { 52.78, "Единственное убежище для путников — Лагерь Братства Тория на северных утёсах, где живут дворфы Чёрного Железа, порвавшие со своим кланом." }, { 63.97, "Здесь нет ни воды, ни травы: лишь пепел, лава, боевые големы, лавовые пауки и элементали огня." } } } },
    ["1928d0de"] = { d = 30.0, v = "human-male", c = { x = { { 0.00, "День два" }, { 0.58, "Мы долго спорили о том, где следует возводить Ветровой Камень." }, { 5.01, "Даже мудрейшие из нас не могут сказать наверняка, что за место описано в древнем пророчестве." }, { 11.63, "Я примкнул к тем, кто считает, что строить надо на севере, и время несомненно докажет нашу правоту." }, { 18.70, "Доводы, что энергетические линии якобы пересекаются там под плохим углом, наивны и глупы." }, { 25.07, "Мы уже собираем с великой поспешностью всё, что нужно для строительства." } } } },
    ["1937cfdd"] = { d = 21.7, v = "human-male", c = { x = { { 0.00, "Но он был прав." }, { 1.18, "Мы обречены." }, { 2.22, "Линия семьи Агамондов прервётся." }, { 4.88, "Несмотря на то что я всё ещё жив, скоро я погибну." }, { 8.88, "Я не боюсь, и не сожалею о том, что остался со своей семьёй." }, { 13.69, "Но мои последние мысли – о тебе." }, { 16.43, "Продолжай жить, моя возлюбленная Иветта, и я обрету покой." }, { 21.24, "Тармен" } } } },
    ["193cb88b"] = { d = 24.0, v = "human-male", c = { x = { { 0.00, "Лорд Сильноплечий -" }, { 1.35, "Возглавляемое Эдвином ван Клифом братство Каменщиков состояло из лучших строителей среди людей." }, { 8.16, "Каменщики помогали восстанавливать Штормград, разрушенный до основания орками во время Первой войны. ван Клиф и его товарищи были непревзойдёнными зодчими." }, { 19.07, "Их вкус и чутьё отразились в величии Собора Света и Крепости Штормграда." } } } },
    ["194a20c0"] = { d = 16.7, v = "narrator", c = { x = { { 0.00, "Красноватый песчаник Мулгора на закате будто горит, и, быть может, отсюда пришло название плато Огненного Камня." }, { 9.33, "Это одно из тихих плато долины: здесь лишь ветер, трава и редкие звери, спустившиеся с гор." } } } },
    ["1994c7ee"] = { d = 69.6, v = "narrator", c = { x = { { 0.00, "Бесплодные земли лежат на юго-востоке Каз Модана, между Лок Моданом на севере и Тлеющим ущельем на западе." }, { 8.79, "Это растрескавшаяся пустыня бурого камня и сухих равнин, где палит солнце и гуляют суровые ветры; здесь нет ни озёр, ни ручьёв, и воду берут из глубоких колодцев да редких кактусов." }, { 23.70, "Выживают тут лишь самые стойкие: койоты, хищные кошки, стервятники и каменные элементали." }, { 31.08, "На севере из-под земли показались своды Ульдамана, древнего хранилища титанов, где дворфы Стальгорна нашли первые ключи к тайне своего происхождения." }, { 43.52, "Раскопки потревожили троггов, а следом в руины пришли дворфы Чёрного Железа, укрепившиеся в крепости Ангор." }, { 52.39, "По раскалённым пескам рыщут огры-Гнилобрюхи, на западной окраине стоит Каргат, единственная застава Орды в этих краях, а на востоке, в долине Летлор, живут чёрные драконы, откуда разведчики уже не возвращаются." } } } },
    ["199607fa"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Земли Ящеров — небольшая долина к югу от Кабестана, к западу от крепости Северной Стражи." }, { 7.13, "Её облюбовали яркочешуйчатые ящеры, необычайно смышлёные для своего рода: они строят из веток кривые хижины, мастерят подобие орудий и тащат в гнёзда всё блестящее." }, { 20.05, "Из-за этой страсти к сокровищам ящеры воруют у поселений Орды, и караванщики не раз недосчитывались серебра, ушедшего в эти гнёзда." } } } },
    ["19b24059"] = { d = 30.5, v = "narrator", c = { x = { { 0.00, "Рабочий лагерь Песни Войны — небольшой лагерь на юго-востоке леса, к востоку от озера Зеркало Небес и к юго-западу от обители Дор'Данил." }, { 11.00, "Здесь трудятся лесорубы и сборщики клана Песни Войны под охраной орочьих стражей, и отсюда орк Торек ведёт своих бойцов на Аванпост Среброкрылых." }, { 22.49, "Лагерь стоит на отшибе, и Альянс нередко нападает на него, зная, что помощь с заставы придёт не скоро." } } } },
    ["19d25213"] = { d = 39.4, v = "narrator", c = { x = { { 0.00, "Зияющая бездна — один из малых силитидских ульев на юго-востоке Танариса." }, { 6.05, "Песок здесь изрыт ходами, из которых торчат хитиновые своды, и всё вокруг кишит членистоногами улья Хаззали: рабочими, жалоносцами и целыми роями." }, { 18.06, "Водная компания Прибамбасска посылала сюда младшего геодезиста, но он так и не вернулся." }, { 25.21, "Старший геодезист Рудознатец подозревает, что эти твари выпивают воду пустыни и что ими управляет какая-то чуждая сила, грозящая не только Прибамбасску, но и всему Калимдору." } } } },
    ["19dd955d"] = { d = 8.6, v = "narrator", c = { x = { { 0.00, "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ ОРДЫ." }, { 3.51, "Высший сержант." }, { 5.13, "Старший сержант." }, { 6.84, "Рубака." }, { 7.65, "Разведчик." } } } },
    ["1a0990fd"] = { d = 66.7, v = "narrator", c = { x = { { 0.00, "Восточные Чумные земли — самая израненная часть павшего Лордерона." }, { 5.04, "Когда-то здесь стояли богатые сёла и Стратхольм, второй по величине город королевства." }, { 11.52, "Чума нежити пришла сюда с заражённым зерном, принц Артас предал Стратхольм огню вместе с его жителями, и с тех пор город горит и служит Плети столицей в Лордероне, а над Проклятым лесом парит некрополь Наксрамас." }, { 27.60, "Земля побурела, деревья обратились в исполинские грибы, и по дорогам бродят вурдалаки, скелеты и служители Культа Проклятых." }, { 37.01, "С ними воюет Алый орден, засевший в Длани Тира и в западных кварталах Стратхольма, но для чужаков рьяные крестоносцы опасны не меньше нежити." }, { 47.77, "На севере доживают свой век лесные тролли Зул'Машара, а у перевала в Кель'Талас держат сторожку высшие эльфы." }, { 56.02, "Единственное пристанище для путников — часовня Последней Надежды, где Серебряный Рассвет принимает всех, кто готов поднять оружие против Плети." } } } },
    ["1a512c85"] = { d = 15.9, v = "tauren-male", c = { x = { { 0.00, "Корень жизни:" }, { 1.22, "Он встречается в природе, а также может быть извлечён из тварей Сухой Лозы в Пылевых топях." }, { 8.96, "Его сила будет необходима для привлечения жизненной эссенции Циклониана в этот мир." } } } },
    ["1a63203b"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Берлога Бен'Таллоу — курганная берлога ночных эльфов позади Деревни Звездопада." }, { 6.64, "Такие подземелья друиды устраивают для долгого сна, но эта берлога пустует: в её тёмных проходах никто не спит и никто не сторожит покой спящих." }, { 18.50, "Лишь холод да тишина встречают того, кто заглянет внутрь." } } } },
    ["1a825f54"] = { d = 25.8, v = "dwarf-male", c = { x = { { 0.00, "Эпилог" }, { 0.54, "\"Сдобрить сердцевину артишока маслом с чесноком и майонезом." }, { 5.06, "Запивать блюдо лучше крепким, выдержанным элем.\"" }, { 8.77, "Теперь Дрек'Тар совсем один, если не считать двух болванов-подопечных по обе руки." }, { 15.04, "Захвати Приют Северного Волка и убей Дрек'Тара." }, { 18.68, "Когда Генерал падёт, его земли наконец-то перейдут к их истинному владельцу – Грозовой Вершине." } } } },
    ["1ab146f2"] = { d = 31.1, v = "narrator", c = { x = { { 0.00, "Судьба Хоргуса Опустошителя" }, { 2.30, "Хоргус Опустошитель погиб в битве за Дарроушир." }, { 6.23, "Но зло, которое он нёс в себе, не умерло вместе с ним." }, { 10.60, "Победившие воины Плети отрезали его голову и забрали её с собой, чтобы наводить ужас на всё живое." }, { 18.82, "Через несколько дней отряд Плети, у которого была голова Хоргуса, был уничтожен паладинами Серебряной Длани, а саму голову утопили в озере Чернолесья." } } } },
    ["1ae46ec8"] = { d = 32.4, v = "narrator", c = { x = { { 0.00, "Ферма Го'Шека лежит на востоке нагорья, недалеко от деревни Сухокожих." }, { 5.29, "Прежде здесь хозяйствовали люди, и ветеран Второй войны растил хлеб на этих полях." }, { 11.45, "После Третьей войны ферму заняли орки и Отрёкшиеся из Павшего Молота." }, { 16.68, "Орки свозят отсюда припасы для гарнизона, а аптекари Отрёкшихся устроили в амбарах место для своих тёмных опытов." }, { 25.05, "Ферму стерегут рубаки Павшего Молота, и разведчики Альянса присматриваются к ней с растущей тревогой." } } } },
    ["1b03d204"] = { d = 19.8, v = "dwarf-male", c = { x = { { 0.00, "Я вёл отряд по направлению к морю в надежде, что вода остановит ящеров." }, { 5.09, "Но в спешке мы зашли слишком далеко на север, на возвышенность." }, { 9.61, "Исправлять ошибку было уже поздно." }, { 12.18, "И вина была в этом моя." }, { 13.99, "Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас." } } } },
    ["1b27aeee"] = { d = 31.1, v = "human-male", c = { x = { { 0.00, "День пять:" }, { 0.69, "Торсен был сегодня очень взволнован." }, { 3.24, "Кого бы или что бы он ни встретил на своей вчерашней прогулке, это его, должно быть, испугало." }, { 9.78, "Мне думалось, что с ним говорили наши агенты, но на мой вопрос, куда он ходил, Торсен ничего не ответил." }, { 16.94, "Он считает, что я его друг, и думает, будто мне безопаснее не знать его тайны." }, { 22.29, "Он служит не тем, кому следовало бы, но его преданность крепка." }, { 26.65, "Когда он вернётся к нам, он станет ценным приобретением для Курцена." } } } },
    ["1b34e773"] = { d = 42.8, v = "narrator", c = { x = { { 0.00, "Каэр Дарроу — остров и древняя крепость посреди озера Дарроумир." }, { 5.17, "Во Вторую войну Орда разграбила её и вывезла священный эльфийский рунический камень, из обломков которого чернокнижники Орды сложили свои алтари." }, { 16.66, "После войны крепость стала родовым гнездом Баровых, но перед Третьей войной жадные аристократы заключили сделку с Кел'Тузадом, и под усадьбой возник Некроситет." }, { 29.34, "Вскоре мор выкосил весь остров, а его жители обречены бродить призраками, вновь и вновь переживая последний день." }, { 38.13, "Наследники дома Баровых и ныне спорят о праве на эти руины." } } } },
    ["1b3a077f"] = { d = 28.2, v = "dwarf-male", c = { x = { { 0.00, "Бедный Гералат бледен, точно смерть." }, { 2.58, "Его с каждой минутой лихорадит всё сильнее." }, { 5.66, "А свинолюди без устали готовятся к какому-то крупному военному походу." }, { 10.57, "Боюсь, что если я не попытаюсь вскоре бежать, мне будет уготована та же судьба, что и моему сотоварищу эльфу." }, { 18.19, "Я планирую тайком пробраться наружу, когда свинолюди в очередной раз уйдут на охоту." }, { 24.10, "Стражники, охраняющие меня, ленивы и то и дело спят на посту." } } } },
    ["1b4724bf"] = { d = 39.8, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Одни боятся нас больше, чем драконов." }, { 2.82, "Другие завидуют нам больше, чем самым искусным кузнецам." }, { 7.05, "Третьи превозносят нас за подвиги на поле боя." }, { 10.54, "Четвёртые преклоняются перед нашей верой." }, { 13.62, "А пятым просто обидно, что мы можем с лёгкостью перепить любого из них!" }, { 18.86, "Но помни, герой," }, { 20.13, "Что на самом деле мы – величайшие защитники Азерота." }, { 24.03, "Божественный Свет даёт нам тем больше силы, чем больше мы служим ему." }, { 29.13, "Я расскажу тебе больше, когда ты освоишься." }, { 32.41, "Ищи меня в Старой Наковальне над долиной." }, { 35.57, "-Бромос Груммнер, наставник паладинов" } }, f = { { 0.00, "Одни боятся нас больше, чем драконов." }, { 2.92, "Другие завидуют нам больше, чем самым искусным кузнецам." }, { 7.30, "Третьи превозносят нас за подвиги на поле боя." }, { 10.92, "Четвёртые преклоняются перед нашей верой." }, { 14.11, "А пятым просто обидно, что мы можем с лёгкостью перепить любого из них!" }, { 19.54, "Но помни, героиня," }, { 21.00, "Что на самом деле мы – величайшие защитники Азерота." }, { 25.03, "Божественный Свет даёт нам тем больше силы, чем больше мы служим ему." }, { 30.31, "Я расскажу тебе больше, когда ты освоишься." }, { 33.72, "Ищи меня в Старой Наковальне над долиной." }, { 36.99, "-Бромос Груммнер, наставник паладинов" } } } },
    ["1b4a5f0a"] = { d = 20.2, v = "nightelf-male", c = { x = { { 0.00, "Лайо, мы получили щедрую помощь от этого доброго странника." }, { 4.95, "Я направил его к тебе в Силитус." }, { 7.68, "Используй его способности во благо себе и раскрой все нужные тебе тайны." }, { 13.74, "Круг с нетерпением ждёт новостей о твоих успехах." }, { 17.73, "Да убережёт тебя Кенарий…" }, { 19.80, "Рабин" } } } },
    ["1b625972"] = { d = 27.0, v = "dwarf-male", c = { x = { { 0.00, "После очередного неверного шага Барнила Эрлгедин положил свою тяжёлую руку ему на плечо." }, { 6.58, "Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность." }, { 14.54, "Но вместо этого Эрлгедин кивнул головой в сторону лежащего неподалёку дерева." }, { 20.20, "Оттуда на нас пристально смотрели два чёрных глаза, а под ними была пасть, полная острых зубов." } } } },
    ["1b6f0ef6"] = { d = 23.1, v = "narrator", c = { x = { { 0.00, "Битва продолжалась, и капитан Редпат со своим ополчением твёрдо держал оборону." }, { 6.59, "Они бы победили, если бы не магия рыцаря смерти Мардука Чёрного." }, { 11.97, "В самом разгаре битвы Мардук приблизился к Редпату и своей чёрной магией растерзал его душу, обратив отважного капитана в злобную тень." } } } },
    ["1b748dd3"] = { d = 14.0, v = "narrator", c = { x = { { 0.00, "Торадин, не доверявший любой магии, согласился помочь эльфам исключительно по необходимости." }, { 6.81, "Практически немедленно эльфийские волшебники прибыли в Аратор и начали обучать группу людей магии." } } } },
    ["1b750542"] = { d = 2.6, v = "narrator", c = { x = { { 0.00, "ДИАГРАММА ВОСТОЧНОГО ПИЛОНА" } } } },
    ["1b76b56f"] = { d = 24.9, v = "narrator", c = { x = { { 0.00, "Планируя нанести удар Альянсу силами своей армии и могучих красных драконов, Некрос надеялся вновь объединить Орду и продолжить завоевание Азерота." }, { 11.63, "Но его надеждам не суждено было сбыться: небольшая группа бойцов сопротивления, возглавляемая магом Ронином, смогла уничтожить Душу Демона и освободить королеву драконов." } } } },
    ["1b82e395"] = { d = 30.8, v = "dwarf-male", c = { x = { { 0.00, "Мы отправились на запад через дикие непроходимые джунгли." }, { 4.23, "В поисках добычи мы медленно, но верно прокладывали себе путь сквозь густую растительность." }, { 10.84, "К нашему сожалению, утром всё было тихо." }, { 13.89, "Даже ветер не шумел в кронах деревьев." }, { 16.80, "К полудню мы начали волноваться." }, { 19.18, "Шаги Барнила уже не были столь осторожными и тихими, как раньше." }, { 23.94, "Теперь он неуклюже переваливался с ноги на ногу, с треском ломая упавшие на землю сухие ветки." } } } },
    ["1b8b6c65"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Терраса Творца — обширный раскоп у самого входа в Ульдаман, на севере Бесплодных земель." }, { 7.05, "Для тех, кто спускается сюда из Лок Модана, это первое, что встречает их в пустыне: колонны и ступени, высеченные ещё в древности, и вырытые дворфами траншеи." }, { 19.37, "Ныне террасу патрулируют дворфы Чёрного Железа: их землекопы и надсмотрщики ведут раскопки, надеясь добраться до сокровищ титанов раньше Стальгорна." }, { 31.05, "Здесь же начинаются внешние залы Ульдамана." } } } },
    ["1be54298"] = { d = 28.5, v = "narrator", c = { x = { { 0.00, "Закатное болото — самая глубокая часть Болотины на северо-западе." }, { 5.16, "Посреди топи стоит небольшой каменный дом с ветряной мельницей, где живут гном и дворфийка, торгующие странными находками из болота и редкими рецептами." }, { 17.04, "Вокруг же на все стороны тянется трясина, полная кроколисков, гноллов, ящеров, болотных чудищ и слизнюков, так что неопытные путники сюда не суются." } } } },
    ["1bfa8e68"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Озеро Мерельдар — большое озеро на юге Восточных Чумных земель, к югу от Перекрёстка Корина." }, { 7.47, "Вода здесь давно отравлена чумой, и над гладью поднимаются осквернённые водные элементали." }, { 14.64, "На берегу стоят развалины старого дома, паром и рыбацкая хибара — всё, что осталось от прежнего хозяйства." } } } },
    ["1c18c8a0"] = { d = 26.6, v = "dwarf-male", c = { x = { { 0.00, "Я медленно шагнул вперёд, держа ружьё наготове." }, { 3.55, "Я привёл этих отважных охотников к гибели." }, { 6.76, "И готов был погибнуть сам, защищая их." }, { 9.63, "Ящеры-кнутохвосты известны своей свирепостью и неумолимой жаждой крови." }, { 15.03, "Их было намного больше нас." }, { 17.15, "Но я бы себе не простил, если бы позволил расправиться с собой и моими товарищами, не прикончив сначала несколько этих тварей!" } } } },
    ["1c2254af"] = { d = 31.8, v = "dwarf-male", c = { x = { { 0.00, "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Холодной долины." }, { 5.71, "Подготовлен Грелином Белобородом, особым посланником Сената." }, { 9.92, "Я потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе." }, { 22.23, "Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии." }, { 28.20, "Учитывая помощь горных пехотинцев, уже находящихся в" } } } },
    ["1c2293e5"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Логово Легкоперых — небольшая пещера в глубине Каньона Визга, гнездо стаи гарпий." }, { 6.61, "Здесь обитают заклинательницы ветра и разбойницы стаи, а в дальнем конце логова гарпии ревниво стерегут свои запасы — всё, что удалось стащить с караванов и у неосторожных путников." }, { 20.97, "Чужака они не убивают сразу: сперва переглянутся и повизжат меж собой, а уж потом бросаются в бой." } } } },
    ["1c2743d1"] = { d = 30.3, v = "human-male", c = { x = { { 0.00, "Лорд Сильноплечий -- Городской совет Озёр смиренно просит у вас военной помощи." }, { 5.62, "В то время как я пишу эти строки, нас держат в осаде орки Чёрной Горы и гноллы из стаи Темношкуров, прислуживающие Морганту." }, { 14.52, "Я бы никогда не попросил о помощи, но мы в тяжёлом положении." }, { 18.78, "Мы ожидаем подкрепление из Штормграда, но пока оно прибудет, я прошу вас оказать нам поддержку." }, { 25.56, "Падёт королевство – и все люди будут обречены." }, { 28.85, "Мировой судья Соломон" } } } },
    ["1c749423"] = { d = 17.0, v = "human-male", c = { x = { { 0.00, "Совет поступил мудро, назначив вас главой Недремлющего Аргуса, исполнителем их предначертаний в землях людей и дворфов." }, { 9.07, "И для меня большая честь служить проводником вашей воли в Альтераке." }, { 14.29, "Во имя Саргераса!" }, { 15.67, "Нагаз," }, { 16.22, "Жрец Аргуса" } } } },
    ["1c7db7be"] = { d = 46.3, v = "narrator", c = { x = { { 0.00, "Крепость Бандариона стоит на утёсах Северной скалы к северо-западу от фермы Соллидена, отделяя Шепчущий лес от остального Тирисфаля." }, { 10.10, "Во время Третьей войны твердыню удерживал Серебряный Рассвет, пока не отступил в Чумные земли." }, { 17.43, "Теперь Отрёкшиеся собирают здесь новый орден паладинов — восставших из мёртвых рыцарей, не отрёкшихся от Света." }, { 25.72, "Крепость названа в честь капитана Гарека Бандариона, павшего при обороне Подгорода от тварей Наксрамаса; возглавляет орден Данита Морр." }, { 36.03, "Стены обветшали, припасов не хватает, а из окрестного озера на крепость то и дело нападают мурлоки, некогда устроившие в ней нерестилище." } } } },
    ["1caa17fa"] = { d = 34.0, v = "narrator", c = { x = { { 0.00, "Вершина Багрового Тумана — окутанная мглой гора к северо-западу от Перекрёстка." }, { 6.01, "На её склонах собрались орки-чернокнижники культа Пылающего Клинка: они проводят тёмные обряды и, как подозревают шаманы, отравляют озёра на самой вершине, от которых зависит погода в Степях." }, { 20.60, "Здесь же засел Сарилус Грязнорожденный, маг из нежити, насылающий порчу на духов воды." }, { 27.17, "Даже в полдень над горой висит багровый туман, и мало кто поднимается сюда по своей воле." } } } },
    ["1cc42f48"] = { d = 38.2, v = "narrator", c = { x = { { 0.00, "Убежище Батрана лежит на самом севере Ясеневого леса, у границы с Тёмными берегами." }, { 6.70, "От древнего поселения ночных эльфов здесь остались лишь поваленные колонны и куски мрамора в траве." }, { 14.62, "Теперь среди руин хозяйничают Отрёкшиеся: травники и их громилы разбили здесь лабораторию и обирают местные травы, а земля под их ногами буреет, и цветы вянут." }, { 27.30, "Только тут растёт Батранов волос — редкая травка, которой, по преданию, лечили болезни души, и лекари до сих пор посылают за ней смельчаков." } } } },
    ["1cc69bac"] = { d = 24.3, v = "human-male", c = { x = { { 0.00, "Приветствую вас, Господин," }, { 1.74, "Приношу свои извинения за то, как моё послание попало к вам." }, { 5.71, "Тёмные маги в Альтераке сосредоточили все свои силы на выполнении поставленной задачи, и я был вынужден передать вам сообщение с этим гонцом – новобранцем из рядов наших новых \"союзников\"." }, { 18.15, "Однако я зашифровал послание самым тайным из наших шифром." }, { 22.12, "Эта деревенщина не поймёт ни слова." } } } },
    ["1cf4cd73"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "Когда мир раскололся после взрыва Источника Вечности, это очень сильно задело земельников." }, { 7.75, "Ошеломлённые болью самой земли, земельники сделались непохожи на самих себя и закрылись в каменных чертогах, где некогда были созданы." }, { 19.06, "Ульдаман, Ульдум, Ульдуар… это имена древних городов титанов, где земельники впервые обрели свой облик." }, { 27.87, "Погребённые в недрах мира, земельники спокойно отдыхали почти восемь тысяч лет." } } } },
    ["1cf6df83"] = { d = 29.3, v = "human-female" },
    ["1d0233c2"] = { d = 76.3, v = "narrator", c = { x = { { 0.00, "Подгород лежит глубоко под руинами Лордерона, некогда гордой столицы людей." }, { 6.22, "Здесь, в тронном зале, король Теренас Менетил пал от руки собственного сына Артаса, и с того дня дворец наверху стоит пустым, а жизнь ушла вниз — в древние склепы, темницы и сточные каналы." }, { 21.59, "Плеть начала прокладывать эти катакомбы, но Артаса отозвали в Нордскол, и когда воля Короля-лича ослабла, часть нежити вырвалась из-под его власти." }, { 33.66, "Их возглавила Сильвана Ветрокрылая, Тёмная Госпожа, и своих свободных мертвецов она назвала Отрёкшимися." }, { 42.01, "Они заняли брошенные подземелья и годами достраивали лабиринт зелёных каналов и тёмных залов." }, { 49.54, "В Королевском квартале Сильвана держит совет, и рядом с ней стоит натрезим Вариматрас, склонивший перед ней голову." }, { 58.91, "Королевское фармацевтическое общество в Районе Фармацевтов варит новую чуму, а в Квартале Магов и Квартале Разбойников Отрёкшиеся готовятся к войне с Плетью." }, { 71.57, "Подгород — дом тех, кого отверг мир, и они ничего не забыли." } } } },
    ["1d153c67"] = { d = 32.6, v = "human-male" },
    ["1d1cad2d"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Штормовое озеро лежит у самого Лагеря Мохаче, и таурены построили свои шатры на его берегу." }, { 7.50, "Ручей, бегущий через деревню, впадает здесь в спокойную воду, а над гладью по вечерам стелется туман от джунглей." }, { 16.59, "Несмотря на грозное имя, это одно из самых мирных мест Фераласа — здесь ловят рыбу, поят зверей и отдыхают после дороги." } } } },
    ["1d51638e"] = { d = 42.8, v = "narrator", c = { x = { { 0.00, "Поселение Песчаного Молота — стойбище огров на юге Танариса: хижины вокруг одного из немногих водоёмов пустыни." }, { 9.09, "Клан Песчаного Молота, бронзовокожие кочевники, пришёл в Танарис недавно и держится особняком: переход через пески требует больше воды, чем огры могут выделить, а гостей они не любят." }, { 24.04, "В пещере правит Гор'марок Опустошитель, вожак клана, а вокруг него — громилы, головорезы, чернокнижники и огры-маги." }, { 33.57, "Южнее, в Руинах Южной Луны, тоже хозяйничают огры этого клана, а порой их одиночки забредают и в дальние барханы." } } } },
    ["1da37708"] = { d = 15.5, v = "narrator", c = { x = { { 0.00, "Лагерь Ванндир — тихий уголок среди осенних холмов Азшары, где нет ни огней, ни дорог." }, { 7.00, "Только ветер с залива Бурь шумит в рыжей листве, и никто не помнит, кто и зачем собирался здесь поселиться." } } } },
    ["1da55dad"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "Руины Зул'Мамбве лежат в котловине среди гор к югу от холма Мош'Огг, открытой лишь с севера." }, { 7.35, "Здесь обосновался клан Дробителей Черепов — второе великое племя долины, воюющее с Кровавым Скальпом за каждую пядь джунглей." }, { 17.19, "Тролли достраивают древние стены Гурубаши под нужды растущего племени, а их знахарь держит при себе околдованных людей из экспедиции Курцена." }, { 28.38, "Чужаков здесь встречают копьями." } } } },
    ["1da6ac2b"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Желая восстановить отношения и торговлю со своими собратьями, дворфы Стальгорна построили две огромные арки, называемые Мост Тандола, между Каз Моданом и Лордероном." }, { 13.43, "Поддерживаемые обоюдной торговлей, два королевства процветали." }, { 18.45, "После смерти Мадорана и Кардроса их сыновья вместе построили две большие статуи в честь своих отцов." } } } },
    ["1dc1f511"] = { d = 24.0, v = "human-male", c = { x = { { 0.00, "Изера:" }, { 0.54, "Изера Спящая представляет подсознание смертных." }, { 4.14, "Она олицетворяет Изумрудный Сон..." }, { 6.72, "Она благоволит к искусствам и амбициям смертных народов, но в то же время считает, как и все её драконы, что настоящий мир – это лишь иллюзия." }, { 17.23, "Изера – одно из самых могучих и грациозных созданий, которое только может узреть смертный." } } } },
    ["1dd1bb4c"] = { d = 35.4, v = "human-male" },
    ["1ded0e3c"] = { d = 23.0, v = "dwarf-female", c = { x = { { 0.00, "Моему досточтимому королю:" }, { 2.07, "Не пристало скромной жене солдата подвергать сомнению действия великих военачальников, таких как вы." }, { 9.73, "Битвы, бушующие в наших землях, ведутся, чтобы сохранить прекрасную жизнь, которую мы знаем и любим, – от прохладных вод озёра Лок Модан до острых заснеженных пиков Дун Морога." } } } },
    ["1e03910b"] = { d = 41.4, v = "narrator", c = { x = { { 0.00, "Странбрад — городок на северо-восточных склонах гор, у самой границы с Чумными землями." }, { 6.70, "Он принадлежал королевству Альтерак, а после его падения отошёл к Лордерону; накануне Третьей войны его разоряли орки Чёрной Горы, уводя жителей в рабство." }, { 18.65, "Когда чума опустошила Лордерон, брошенный город заняли разбойники Синдиката, и теперь среди пустых домов, заброшенной ратуши и кузни хозяйничают их бойцы и чародеи." }, { 31.36, "В одном из домов они держат пленников — среди них и орк Гол'дир, вождь отряда, посланного с мельницы Таррен разведать силы Синдиката." } } } },
    ["1e45b263"] = { d = 27.5, v = "narrator", c = { x = { { 0.00, "В центре континента титаны поместили озеро искрящейся энергии." }, { 4.99, "Озеро, которое они назвали Источником Вечности, было источником жизни в мире." }, { 11.27, "Его могущественная энергия питала корни мира и давала возможность жизни пустить побеги в его плодородной почве." }, { 20.25, "Со временем травы, деревья, монстры и создания всех видов появились на первобытном континенте." } } } },
    ["1e6013ca"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Зная, что Кил'джеден будет недоволен его неудавшейся попыткой разрушить Ледяной Трон, Иллидан бежал в безжизненный мир, называемый Запределье: последние остатки Дренора, бывшей родины орков." }, { 14.48, "Там он хотел укрыться от гнева Кил'джедена и обдумать свои дальнейшие планы." } } } },
    ["1e6ee0fa"] = { d = 33.6, v = "narrator", c = { x = { { 0.00, "Водопад Скалистый низвергается с гор к востоку и чуть севернее Аубердина." }, { 5.77, "Отсюда берёт начало река Скалистая, и это главный источник питьевой воды для всех Тёмных берегов." }, { 13.56, "За водопадом скрыта пещера, где растут редкие грибы, но в последнее время в ней обосновались наги, а Древа из Рощи Древних чувствуют там незнакомое зло." }, { 25.67, "Друиды подозревают, что именно отсюда расходится отрава, от которой болеют олени по всему побережью." } } } },
    ["1e7f0358"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Упрямые эльфы, не желавшие отдавать свои новые владения, использовали магию, оставшуюся от Источника Вечности, и заставили свирепых троллей отступить." }, { 11.21, "Под командой Дат'Ремара они сумели победить отряды Амани, которые десятикратно превосходили их числом." }, { 18.87, "Некоторые эльфы, помнившие древние предупреждения калдорай, почувствовали, что использование магии может привлечь внимание изгнанного Пылающего Легиона." } } } },
    ["1ef45b69"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Сотворение зверя:" }, { 1.45, "Чтобы создать ищейку Скверны, необходимо использовать выданную сферу Скверны." }, { 7.74, "Примечания:" }, { 8.68, "Сотворённая ищейка Скверны сможет существовать в этом мире лишь тридцать минут." }, { 15.04, "Сотворённая ищейка Скверны будет помогать лишь в поиске отложений азшарита." }, { 21.05, "Сотворённая ищейка Скверны НЕ БУДЕТ делать следующее: фокусы, нападать на кого-либо, помогать в чём-либо, танцевать, уничтожать магических существ." }, { 32.69, "Пожалуйста, переверните страницу..." } } } },
    ["1ef4f307"] = { d = 6.1, v = "narrator", c = { x = { { 0.00, "Энтони Рэй Старк." }, { 1.46, "Одна тысяча девятьсот шестьдесят один – две тысячи пять" } } } },
    ["1f1dd3ee"] = { d = 25.3, v = "narrator", c = { x = { { 0.00, "Судьба Дейвила Лёгкого Горна" }, { 2.35, "Дейвил Лёгкий Горн погиб в битве за Дарроушир, но его храбрость вдохновляла воинов Альянса до самого окончания войны." }, { 11.87, "Написанный им манускрипт паладина был найден армией Алого ордена." }, { 17.22, "Теперь она хранится в ратуше Дольного Очага, где воины Алых черпают из неё силу и мудрость Дейвила." } } } },
    ["1f374b7c"] = { d = 18.2, v = "narrator", c = { x = { { 0.00, "Ценарион научил детей земли разговаривать с деревьями и травами." }, { 5.19, "Шу'хало стали друидами и совершили множество чудес, приносящих земле здоровье." }, { 11.54, "Многие поколения Шу'хало охотились вместе с Ценарионом и хранили землю от тёмных сил." } } } },
    ["1f3ddf10"] = { d = 19.2, v = "named/thrall", c = { x = { { 0.00, "Командир!" }, { 0.83, "Возвращайтесь в Оргриммар." }, { 3.01, "Ваши войска несостоятельны." }, { 5.35, "Следует пересмотреть наше положение на основании поступившей новой информации." }, { 11.90, "Крупные силы Приверженцев Тени и огров." }, { 15.29, "Демоны охраняют Тёмный портал." }, { 17.85, "-Тралл, Вождь Орды" } } } },
    ["1f592458"] = { d = 77.4, v = "narrator", c = { x = { { 0.00, "Дарнасс — столица ночных эльфов, выросшая в кроне Тельдрассила, нового Мирового Древа, которое друиды взрастили у северных берегов Калимдора после Третьей войны." }, { 12.81, "Лишившись бессмертия, калдорай нашли здесь новое пристанище среди лунного света и тихой воды." }, { 20.24, "Городом правит верховная жрица Тиранда Шелест Ветра, чей престол — Храм Луны, где Сестринство Элуны возносит молитвы богине." }, { 30.08, "Малфурион Ярость Бури так и не вернулся из Изумрудного Сна, и друидов возглавляет верховный друид Фэндрал Олений Шлем — тот, кто настоял на посадке нового древа." }, { 42.61, "Город разделён на террасы: воины и Часовые несут стражу на Террасе Воинов, мастера и купцы заняли свои террасы, а друиды собираются в Анклаве Кенария." }, { 54.51, "Посреди Храмовых садов лежит озеро с островами, и вода здесь так же спокойна, как и сама столица." }, { 62.15, "Попасть сюда с большой земли можно лишь через Деревню Рут'теран у подножия древа, откуда светящийся портал ведёт наверх." }, { 71.71, "Дарнасс — тихое свидетельство всему, что ночные эльфы почитают священным." } } } },
    ["1f5a2b03"] = { d = 41.8, v = "narrator", c = { x = { { 0.00, "Пещера Лишайников — большой грот в северо-восточной стене кратера, недалеко от Укрытия Маршалла." }, { 7.51, "Его своды поросли светящимися грибами, а в полумраке живут обезьяны Ун'Горо — одни из немногих зверей кратера, не покрытых чешуёй." }, { 17.69, "Они яростно защищают своё логово и гонят прочь всякого ящера, а вожак Уча, огромная рыжая обезьяна с зубами-кинжалами, считается самым грозным зверем этих пещер." }, { 30.47, "У входа, возле маленького водопада, стоит механическая обезьяна Чи-Та три — творение гномки Карны, которая мечтает изучить племя обезьян изнутри." } } } },
    ["1f68bdaf"] = { d = 16.6, v = "narrator", c = { x = { { 0.00, "Могущественный Архимонд также избрал для себя агентов." }, { 4.38, "Призвав зловредных разрушителей и их жестокого предводителя, Маннорота Разрушителя, Архимонд надеялся создать военную элиту, которая искореняла бы всё живое." } } } },
    ["1fa3e3d1"] = { d = 29.4, v = "creature/dreadlord" },
    ["1fac7210"] = { d = 24.3, v = "narrator", c = { x = { { 0.00, "Разъярённые драконы Алекстразы разрушили Грим Батол и сожгли большую часть орков Драконьей Пасти." }, { 8.21, "Грандиозные планы Некросса рухнули; войска Альянса окружили уцелевших орков и заключили их в лагерь для военнопленных." }, { 18.26, "Поражение Драконьей Пасти ознаменовало конец Орды и кровожадности орков." } } } },
    ["202f4cf3"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "Башня Аратора возвышается в юго-западной части Стромгарда, в бывшем квартале магов, и носит имя древней империи." }, { 9.33, "Когда-то здесь работал архимаг, создавший для башни магическую защиту, которую пробуждал зачарованный самоцвет." }, { 18.38, "При осаде города он пытался отстоять башню, но не сумел и бежал из Стромгарда." }, { 24.77, "Теперь башню и квартал вокруг заняли огры клана Тяжёлого Кулака, и в её залах засел огр-маг." }, { 32.41, "В сундуках башни до сих пор лежат вещи, оставленные прежним хозяином." } } } },
    ["205ba79a"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Мерцающий хребет тянется на севере Дун Морога, к западу от Врат Стальгорна." }, { 5.79, "На нём разбили два лагеря тролли Мерзлогривы, соединив их мостом, и здесь же они держат приручённых вепрей." }, { 13.95, "Тролли выращивают звездолист, траву для своих ритуалов, а дворфы-пивовары зарятся на неё ради необычного вкуса нового портера." }, { 23.79, "Отсюда тролли следят за дорогой на Стальгорн." } } } },
    ["2069de8e"] = { d = 25.0, v = "human-male", c = { x = { { 0.00, "День один" }, { 0.73, "Наше странствие закончено." }, { 2.73, "Мы наконец-то дошли до Силитуса, где и свяжемся с ними." }, { 6.80, "Мы пришли сюда из самых разных мест, чтобы сообща свершить великое дело." }, { 12.26, "Воздух весь наполнен предвкушениями." }, { 14.93, "Завтра мы целиком посвятим себя строительству сооружения, которое позволит нам общаться с НИМИ." }, { 21.99, "Завтра мы будем возводить ветровой камень!" } } } },
    ["207142d7"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Домик Пероборода — одинокая хижина дворфа из клана Громового Молота у дороги неподалёку от Заоблачного Пика." }, { 8.51, "Она стоит на самом краю леса, где лесные тролли уже чувствуют себя как дома, и хозяин её бывает здесь не всегда." }, { 17.51, "Внутри тесно, пахнет дымом и перьями грифонов." } } } },
    ["20927901"] = { d = 9.4, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ." }, { 2.60, "Часть вторая." }, { 4.05, "Центурион." }, { 5.20, "Легионер." }, { 6.26, "Кровавый страж." }, { 7.90, "Каменный страж." } } } },
    ["20a12f09"] = { d = 31.7, v = "narrator", c = { x = { { 0.00, "Затихший берег – полоса Сумеречного леса вдоль западной реки, от места, где сходятся границы Западного Края, Элвиннского леса и Сумеречного леса, на юг до самой Тернистой долины." }, { 13.67, "Здесь стоит крытый мост, по которому дорога уходит в Западный Край." }, { 18.78, "Среди деревьев по берегу плетут сети ядовитые кругопряды и рыщут лютые волки, и дозорный Додс на западной границе рад любому, кто согласится проредить восьминогих тварей." } } } },
    ["211b04d5"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "\"Легенды троллей\", том третий." }, { 2.52, "\"Камень Приливов\"." }, { 4.07, "Принадлежит перу верховного мага Ансарема Руноплета," }, { 8.43, "Даларан." }, { 9.17, "Вступление." }, { 10.13, "Древняя империя Гурубаши была источником многих завораживающих и интригующих легенд, которые, без сомнения, основаны на пристальных наблюдениях за живой природой, поскольку исследования верований и традиций этих троллей указывают на благоговение перед своей естественной средой обитания." }, { 33.58, "В то время как я исследовал многие" } } } },
    ["21235792"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Гильнеас и Альтерак были надёжными союзниками Строма." }, { 4.20, "Они отправили свои могучие армии изучать гористые южные земли Каз Модана." }, { 10.17, "Именно тогда люди впервые столкнулись с древней расой дворфов и пришли в их подземный город Стальгорн." }, { 18.28, "Люди и дворфы делились друг с другом секретами обработки металлов и инженерного дела." }, { 25.03, "К тому же оба народа одинаково любили битвы и древние предания." } } } },
    ["216414ef"] = { d = 15.8, v = "narrator", c = { x = { { 0.00, "В первый раз за почти три тысячи лет разрозненные народы Аратора объединились под одним знаменем." }, { 7.63, "Лорд Лотар был назначен главнокомандующим войск Альянса и начал подготовку своих воинов к нашествию Орды." } } } },
    ["216c6ef7"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Логово Огнебора — просторная пещера в Драконьих топях, где обитает древний чёрный дракон Огнебор." }, { 7.68, "Он служит привратником чёрной стаи: молодые драконы проходят у него суровые испытания, и лишь сильнейшие удостаиваются права войти в свиту Ониксии." }, { 19.27, "Вход стерегут чешуйчатые стражи, а внутри воздух дрожит от жара драконьего дыхания, и мало кто из смертных решается заглянуть в эту тьму." } } } },
    ["21704780"] = { d = 35.5, v = "human-male", c = { x = { { 0.00, "\"Но это далеко отсюда, а у меня на руках дети." }, { 3.38, "Мы должны оставить их здесь.\"" }, { 5.42, "Её уловка была проста, но лишь простая уловка могла увенчаться успехом." }, { 10.53, "Если бы она сработала, она бы увела всадников далеко от фермы." }, { 15.06, "Она была бы убита, но её дети были бы спасены." }, { 18.44, "Это было бы так, если бы всадники поверили её благородной лжи." }, { 22.84, "Несмотря на то что я никогда не был последователем Света, я яростно молился за жену Свена, когда она стояла перед ужасными всадниками." }, { 32.35, "\"Пожалуйста, – молился я. – Пусть они поверят\"." } } } },
    ["21af6493"] = { d = 37.6, v = "narrator", c = { x = { { 0.00, "Тролльских развалин в Тернистой долине, позволили обнаружить упоминания о предмете, известном как Камень Приливов." }, { 8.73, "Объединяя различные фрагменты тролльских преданий, мы получим достаточно сложную картину представлений о Камне и его значении для древней империи Гурубаши." }, { 20.64, "Складывается впечатление, что Камень Приливов позволял своему владельцу повелевать водой в любых её видах: реками, дождями, приливами." }, { 30.96, "На основании легенд, связанных с использованием Камня Приливов, я пришёл к выводу, что он," } } } },
    ["21d2b347"] = { d = 3.1, v = "narrator", c = { x = { { 0.00, "На добрую память о Джесс Моралес" } } } },
    ["21d88e76"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Как только всё было готово, Саргерас начал вторжение в Азерот." }, { 4.94, "Демоны Пылающего Легиона ворвались в мир через источник Вечности и осадили мирно спящие города ночных эльфов." }, { 13.61, "Под предводительством Маннорота и Архимонда Легион промчался по землям Калимдора, оставляя за собой лишь боль и пепел." } } } },
    ["21e505d9"] = { d = 27.1, v = "dwarf-male", c = { x = { { 0.00, "ПЕРВЫЙ ДЕНЬ." }, { 0.90, "Мы с учеником приехали сегодня в Холодную Долину." }, { 4.46, "Путешествие мимо пещеры прошло без приключений." }, { 7.88, "Мы разбили лагерь подальше от неё, так как нас предупредили, что там водятся тролли." }, { 13.76, "ВТОРОЙ ДЕНЬ." }, { 14.67, "Проклятый волчий вой не давал мне спать всю ночь." }, { 18.09, "Не пройдёт и нескольких дней, как у меня будет накидка из шкуры этой твари." }, { 23.45, "Паренёк столкнулся сегодня с троггом, ввязался в бой и" } } } },
    ["21e80606"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Общество людей Аратора росло и процветало, но Торадин, боявшийся, что его королевство расколется, если оно будет расти дальше, сохранял Стром центром Араторской империи." }, { 13.06, "Через много лет спокойного развития и торговли могучий Торадин умер от старости, давая юному поколению Аратора возможность распространить власть империи дальше земель Строма." } } } },
    ["21ee1bd9"] = { d = 17.8, v = "narrator", c = { x = { { 0.00, "Четвёртое: регуляторы потока." }, { 2.43, "Увеличивают или уменьшают скорость потока." }, { 6.07, "Это автоматически регулируется управляющим механизмом самофланжа." }, { 11.54, "Пятое: индикатор температуры." }, { 14.05, "Отображает температуру внутри системы в целом." } } } },
    ["21f55d32"] = { d = 29.0, v = "human-male", c = { x = { { 0.00, "\"Коса?\" – спросила она спокойным голосом." }, { 2.98, "\"Конечно, знаю." }, { 4.14, "А кто о ней здесь не знает?\" Она посмотрела на всадников твёрдым взглядом, и я бы поклялся, что она говорит правду, если бы не знал, что это не так." }, { 14.50, "Она не могла знать ничего о косе." }, { 16.95, "Её уловка сработала." }, { 18.44, "Тот же всадник, что задал вопрос, нагнулся к ней и проскрежетал: \"Где?\"" }, { 23.43, "\"Я отведу вас." }, { 24.46, "Всех вас,\" – сказала она, и я увидел проблеск надежды в её глазах." } } } },
    ["21f8364e"] = { d = 33.9, v = "narrator", c = { x = { { 0.00, "Агама'гор — большое поселение свинобразов племени Дыбогривов к северу от дороги, уходящей на запад от Лагеря Таурахо." }, { 9.25, "Здесь среди шипов и хижин племя выкапывает кроваво-красные камни: свинобразы носят их как тотемы, черпая в них силу для боя и заклинаний." }, { 20.13, "Эти же осколки ищет Кривозуб, пленник Таурахо, обещающий за них благословение Агамаггана." }, { 27.17, "Дыбогривы ведут войну с соседями Иглогривыми, и колючие заросли здесь пропитаны кровью." } } } },
    ["2210287d"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Аман-Тул, Великий Отец Пантеона, отдал часть своей вселенской силы огромному бронзовому дракону, Ноздорму." }, { 9.07, "Великий Отец велел Ноздорму защищать само время и управлять извечными потоками рока и судьбы." }, { 17.15, "Мужественный и благородный Ноздорму стал известен как Вневременный." } } } },
    ["22193fe9"] = { d = 23.1, v = "narrator", c = { x = { { 0.00, "Аман-Тул, Великий Отец Пантеона, отдал часть своей вселенской силы огромному бронзовому дракону, Ноздорму." }, { 9.30, "Великий Отец велел Ноздорму защищать само время и управлять извечными потоками рока и судьбы." }, { 17.58, "Мужественный и благородный Ноздорму стал известен как Вневременной." } } } },
    ["221d8124"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Ферма Сальдена — единственное хозяйство Западного Края, которое Братство Справедливости так и не сумело отобрать целиком." }, { 9.39, "По полям бродят механические големы, дозорные полей, но фермер Сальден и его жена Сальма упрямо отказываются уезжать." }, { 18.63, "Их дом давно стал приютом для тех, кого война и разбой лишили крова, а Сальма кормит гостей знаменитой похлёбкой Западного Края — из того, что удаётся собрать в округе." } } } },
    ["223e4521"] = { d = 35.0, v = "human-male", c = { x = { { 0.00, "Эл Эф приказал увеличить давление на дураков из Альянса." }, { 4.08, "Ниже – список материалов, необходимых для важной миссии против Южнобережья:" }, { 9.60, "Недельные походные рационы для двадцати человек" }, { 13.09, "Двадцать чёрных ночных костюмов" }, { 15.39, "Двадцать новых пар туфель" }, { 17.30, "Двадцать пять новых мечей" }, { 19.20, "Тридцать метательных ножей" }, { 21.18, "Двадцать чёрных масок" }, { 22.76, "Десять склянок зажигательного масла" }, { 25.39, "Пятьдесят доз парализующего яда" }, { 27.69, "Пять украденных униформ стражников Южнобережья, если есть" }, { 31.83, "Сто серебряных монет" }, { 33.34, "Барон Вэ," }, { 34.07, "Квартирмейстер." } } } },
    ["22486c4b"] = { d = 40.8, v = "narrator", c = { x = { { 0.00, "Котлован — исполинская выемка в сердце Тлеющего ущелья, вырытая дворфами Чёрного Железа." }, { 6.91, "По его краям стоят огромные горные машины клана, а внизу, среди трещин, из которых сочится лава, бродят элементали огня и магмы." }, { 17.20, "Здесь день и ночь трудятся невольники — всё, кого Чёрное Железо сумело захватить." }, { 23.40, "Жар, плети надсмотрщиков и нескончаемая работа давно свели их с ума, и они бросаются на любого, кто помешает им копать, даже на своих освободителей." }, { 34.96, "В глубине Котлована открывается вход в Шлаковую Яму, подземный рудник клана." } } } },
    ["225dc153"] = { d = 23.5, v = "narrator", c = { x = { { 0.00, "Эти барельефы с бегунами – возможно, наиболее значительная находка в первых залах Ульдамана." }, { 6.99, "Барельеф ясно показывает связь между големоподобными землевиками и расой дворфов." }, { 13.09, "Если в дальнейшем обнаружатся ещё подобные свидетельства, теория нашего предполагаемого создания мифическими титанами может оказаться верной." } } } },
    ["226b99b4"] = { d = 44.8, v = "narrator", c = { x = { { 0.00, "Темнолесье – единственный уцелевший город Сумеречного леса, некогда тихая лесная деревня, а ныне осаждённый тьмой посёлок за частоколом." }, { 10.70, "Городом правит мэр лорд Элло Чернодрев с советом, а командир Алтея Чернодрев возглавляет Ночной дозор – ополчение из местных жителей, созданное после того, как Штормград отозвал своих солдат." }, { 25.99, "В ратуше клерк Далтри ведёт записи обо-всех, кто живёт здесь или проезжает мимо, а на площади раскладывает карты мадам Ева." }, { 35.76, "В таверне «Алый ворон» шеф-повар Груаль печёт тёмные пирожки с «крабами», а хозяин Смиттс наливает путникам самогон." } } } },
    ["226d9773"] = { d = 42.9, v = "narrator", c = { x = { { 0.00, "Руины Амет'Арана лежат к востоку от главной дороги, к югу от Аубердина." }, { 5.61, "Когда-то здесь, среди базаров и храмов Элуны, слуги королевы Азшары свободно упражнялись в своей могучей магии, но Раскол погубил город вместе с жителями." }, { 17.73, "Теперь среди колонн бродят неупокоенные духи высокорождённых, всё ещё сжимающие древние магические приспособления." }, { 26.49, "В руинах стоят две каменные таблички с историей Амет'Арана и его падения, и до сих пор горит древний синий огонь." }, { 35.32, "Один из друидов Аубердина, переживший те времена, узнал среди здешних призраков свою возлюбленную." } } } },
    ["227598f7"] = { d = 30.6, v = "human-male", c = { x = { { 0.00, "*Здесь покоится Утер Светоносный –*" }, { 3.12, "Первый паладин и основатель ордена Серебряной Длани" }, { 7.12, "Утер жил и умер, защищая королевство Лордерон." }, { 10.71, "Его предал любимый ученик, но мы верим, что дух Утера всё ещё жив." }, { 15.74, "Он по-прежнему наблюдает за нами теперь, когда вокруг нашей разорённой земли сгущаются тени." }, { 22.85, "Его свет – свет всего человечества, и пока мы чтим пример Утера, этот свет никогда не угаснет." }, { 30.02, "- Аноним" } } } },
    ["229e99d4"] = { d = 29.8, v = "human-male" },
    ["22a98799"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Крепость Тирагард — белокаменная твердыня на восточном берегу Дуротара, чужая среди красных скал." }, { 7.40, "Её наспех возвёл адмирал Праудмур, лорд Кул-Тираса и отец Джайны, когда его флот вторгся в Дуротар, нарушив договор, заключённый Траллом с Джайной Праудмур." }, { 19.93, "Штурм крепости и гибель адмирала должны были положить конец войне, но подкрепление под командой лейтенанта Бенедикта вновь заняло руины." }, { 30.29, "Солдаты Кул-Тираса продолжают дело адмирала, и Колючий Холм не может выбить их с этого плацдарма." } } } },
    ["22ae4cab"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "К востоку от Мельницы Таррен, за рекой, лежат руины Дарнхольда." }, { 5.23, "После Второй войны отсюда управляли лагерями для пленных орков, и правил крепостью Аделас Блэкмур." }, { 13.42, "Здесь вырос его раб, орчонок по имени Тралл; повзрослев, он бежал, собрал свободных орков и вернулся, чтобы сравнять крепость с землёй." }, { 24.40, "Теперь в развалинах засел Синдикат: его сторожа, головорезы и тёмные маги совершают отсюда набеги на фермы Хилсбрада, а леди Сильвана объявила их всех вне закона." } } } },
    ["22b3a6f2"] = { d = 24.2, v = "tauren-male", c = { x = { { 0.00, "Убежать от Занзила в этой гниющей лодке в то время казалось хорошей идеей, но я начинаю думать, что смерть могла быть лучшей судьбой." }, { 11.28, "Мне казалось, будто мне повезло, что предки позволили мне спастись от своего гнева." }, { 18.29, "Но сейчас я не понимаю, какую мудрость обрету, если переживу свой плен." } } } },
    ["22ef9c21"] = { d = 32.5, v = "narrator", c = { x = { { 0.00, "Земля Драконов — южная часть болота, где чёрная стая чувствует себя хозяйкой." }, { 6.41, "Среди тёмных заводей бродят драконоиды, а над ними носятся стаи молодых дракончиков, вылупившихся в топях: Ониксия избрала эти края для своих кладок." }, { 18.85, "Землю Драконов окружают Огненное логово и руины Деревни Каменного Молота, отнятые у огров, и всякий, кто идёт этой дорогой на юг, слышит шипение из-за каждого камня." } } } },
    ["230ac9b1"] = { d = 27.8, v = "narrator", c = { x = { { 0.00, "Король-лич был доволен новобранцем." }, { 2.84, "Он пообещал Кел'Тузаду бессмертие и невиданную силу в обмен на преданность и покорность." }, { 9.91, "Кел'Тузад жаждал получить эту силу и знание тёмных искусств и с радостью принял свою первую великую миссию – отправиться в мир людей и основать новую религию, последователи которой должны поклоняться Королю-личу как богу." } } } },
    ["23174463"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Мглистая роща лежит в самом сердце Сумеречного леса, в кратере давно потухшего вулкана." }, { 7.39, "Здесь, в отличие от остального леса, царит не мрак, а тихие сумерки: посреди рощи возвышается огромное древнее дерево с порталом в Изумрудный Сон, а рядом с ним – лунный колодец и беседка ночных эльфов." }, { 24.04, "Говорят, именно сила этого дерева не даёт лесу умереть окончательно." }, { 29.78, "Но с недавних пор из портала выходят зелёные драконы, поражённые кошмаром, и встречи с ними не пережить в одиночку." } } } },
    ["23254677"] = { d = 16.0, v = "narrator", c = { x = { { 0.00, "Сердце Медива заполняла тьма, и Саргерас был доволен: почти всё было готово для его повторного вторжения в этот мир, а последний Страж должен был помочь ему с лёгкостью осуществить все свои планы." } } } },
    ["232f76bf"] = { d = 27.2, v = "human-male", c = { x = { { 0.00, "Официальный приказ флоту Кул-Тираса" }, { 2.38, "Я, адмирал Праудмур, буду лично командовать первой высадкой на берега Калимдора." }, { 7.73, "Лейтенант Бенедикт назначается моим заместителем на время моего отсутствия." }, { 12.72, "Все вопросы обороны Кул-Тираса будут решаться им." }, { 15.99, "Если от меня не поступит вестей из крепости Тирагард в течение двенадцати месяцев, лейтенант Бенедикт возглавит вторую экспедицию, которая должна будет захватить крепость." } } } },
    ["235536a3"] = { d = 24.0, v = "human-male", c = { x = { { 0.00, "Досточтимый директор Криллиан!" }, { 2.08, "Наставник, я пишу вам затем, чтобы поведать о своей нынешней жизни." }, { 6.72, "Прислушавшись к вашему совету, я покинул наш любимый Штормград в поисках знаний." }, { 12.16, "Во время своих странствий я побывал во многих местах, но решил остановиться в славном городке Луноречье." }, { 19.25, "С приближением жатвы поля Западного Края становятся особенно красивы..." } } } },
    ["23c183a5"] = { d = 22.8, v = "narrator", c = { x = { { 0.00, "Поместье Алекстона лежит к западу от Сторожевого холма." }, { 4.22, "Хозяева бежали, когда Братство Справедливости захватило ферму, а дом был разграблен и сожжён; по полям остались бродить лишь механические дозорные." }, { 15.19, "Отсюда родом Барос Алекстон, ныне архитектор Штормграда, — мальчишкой он работал на этой самой земле." } } } },
    ["23fcb834"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "На западной окраине топей, у дороги в Степи, люди Терамора когда-то поставили одну из своих сторожевых башен, чтобы охранять путь от Степей к морю." }, { 11.28, "Здесь болото ещё мелкое, но кроколиски и пауки подбираются к самым стенам." }, { 16.88, "Гарнизон Терамора давно уже не держит эти места так крепко, как прежде, и башня стоит скорее памятником былым притязаниям, чем оплотом." } } } },
    ["2461818d"] = { d = 37.3, v = "narrator", c = { x = { { 0.00, "Руины Кел'Терила — остатки великого города ночных эльфов на берегах озера Кел'Терил." }, { 6.62, "Город погиб во время Великого Раскола, и с тех пор здесь бродят страдающие духи высокорождённых, не переживших катастрофы." }, { 15.89, "Их проклятие связано с кристаллом Зин-Малора: высокорождённые некогда похитили его из храма в Азшаре, и осколки кристалла до сих пор лежат где-то во льду." }, { 27.60, "Среди неупокоенных есть один раскаявшийся дух, понимающий, что прошлого не изменить, но всё ещё надеющийся на покой для сородичей." } } } },
    ["249ca7ff"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Лагерь Кровавого Паруса — стоянка пиратов на западном побережье долины, у дороги на Пиратскую бухту." }, { 7.74, "Здесь собрались воины и чернокнижники Кровавого Паруса, готовящие удар по городу Разбойников Черноводья." }, { 15.69, "Обе стороны охотно нанимают чужаков, и путнику предстоит выбрать, кому служить." } } } },
    ["24a0169a"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Тыквенное поле Бреквеллов лежит на юго-востоке Элвиннского леса." }, { 4.84, "Когда-то это была спокойная ферма, но семья Бреквеллов пропала, а в доме и на грядках поселились бандиты Братства Справедливости." }, { 14.39, "По донесениям стражи, здесь скрывается их главарь по прозвищу Вымогатель, который ждёт партию золота из рудников Элвинна." }, { 23.21, "Между тыквенных гряд по-прежнему бродит призовая свинья Бреквеллов по кличке Принцесса, разжиревшая на овощах с соседней фермы Стоунфилдов." } } } },
    ["24bb707f"] = { d = 11.5, v = "human-male", c = { x = { { 0.00, "Агашам!" }, { 0.59, "Скоро наши агенты из Лордерона встретятся с вашими посланниками." }, { 5.34, "Мы сообщим вам, как только найдём подходящее место для встречи." }, { 9.89, "Подпись:" }, { 10.55, "Вестник Гракус" } } } },
    ["24d50158"] = { d = 32.2, g = 1, v = "human-male", c = { m = { { 0.00, "Скажи-ка мне, герой," }, { 1.47, "Ты когда-нибудь слышал боевой клич орков?" }, { 4.41, "А может быть, ты защищал свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким?" }, { 11.05, "Жутковато звучит, не правда ли?" }, { 13.29, "Что ж, тебе пригодится моя помощь." }, { 15.78, "Меня можно найти в североземском аббатстве." }, { 18.91, "Мои знания стоят недёшево, но если ты достаточно опытен, я могу научить тебя приёмам и хитростям, которые помогут тебе защищать Штормград и наши земли." }, { 29.70, "Ллан Бишер, наставник воинов" } }, f = { { 0.00, "Скажи-ка мне, героиня," }, { 1.61, "Ты когда-нибудь слышала боевой клич орков?" }, { 4.64, "А может быть, ты защищала свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким?" }, { 11.41, "Жутковато звучит, не правда ли?" }, { 13.67, "Что ж, тебе пригодится моя помощь." }, { 16.18, "Меня можно найти в североземском аббатстве." }, { 19.34, "Мои знания стоят недёшево, но если ты достаточно опытна, я могу научить тебя приёмам и хитростям, которые помогут тебе защищать Штормград и наши земли." }, { 30.24, "Ллан Бишер, наставник воинов" } } } },
    ["24e07d79"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Сумеречной долиной называют южные леса Тёмных берегов — от руин Амет'Арана до границы с Ясеневым лесом." }, { 8.79, "Под тёмными кронами бродят одичавшие саблезубы, взбесившиеся медведи и фурболги Чернолесья, поражённые порчей, так что путникам советуют держаться дороги." }, { 21.62, "Вдоль неё, к югу от Аубердина, стоят лагеря фурболгов, а на востоке, у гор, прячется Роща Древних." }, { 29.87, "Здесь же встречаются больные олени, которых пытаются исцелить друиды." } } } },
    ["24f47ac6"] = { d = 33.7, v = "narrator", c = { x = { { 0.00, "Он хотел знать как можно больше о мире магии и тёмных чудес, но ограниченность и старомодность взглядов коллег разочаровывала его." }, { 10.36, "Когда верховный маг услышал таинственный голос из Нордскола, он приложил все свои силы, чтобы ответить на этот зов." }, { 19.63, "Кел'Тузад был убеждён, что Кирин-Тор слишком слаб, чтобы овладеть силой и знаниями, заключёнными в тёмных искусствах, и поэтому сам решил стать учеником могущественного Короля-лича." } } } },
    ["2512f820"] = { d = 39.3, v = "narrator", c = { x = { { 0.00, "Ползучая трясина – сердце Болота Печали, широкая топь между развилкой дорог и озером Слёз." }, { 7.67, "Грязь здесь и впрямь будто ползёт под ногами, и с дороги лучше не сходить." }, { 13.75, "В трясине водятся молодые острозубые кроколиски, болотные ягуары и ткачи скорби, а между кочками бродят шайки Заблудших: их вожак Нобору Дубина месяцами наводил страх на изгнанников из Убежища." }, { 30.09, "Недалеко от дороги разбил лагерь дозорный Биггс – единственный уцелевший из каравана, разграбленного Заблудшими." } } } },
    ["251d8cb5"] = { d = 32.7, g = 1, v = "nightelf-male", c = { m = { { 0.00, "Сал'ах, друг мой." }, { 1.36, "Я надеюсь, ты получил мой знак." }, { 3.81, "Меня попросили помочь тебе." }, { 6.10, "Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила." }, { 11.28, "Если тебе нужны знания, обращайся ко мне." }, { 14.65, "В наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга." }, { 22.26, "По-другому мы не сможем сохранить Тельдрассил и наше ремесло." }, { 27.15, "Приходи, когда сможешь." }, { 29.09, "-Фрагун Шёпот Тени, наставник разбойников" } }, f = { { 0.00, "Сал'ах, друг мой." }, { 1.38, "Я надеюсь, ты получила мой знак." }, { 3.93, "Меня попросили помочь тебе." }, { 6.25, "Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила." }, { 11.49, "Если тебе нужны знания, обращайся ко мне." }, { 14.91, "В наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга." }, { 22.62, "По-другому мы не сможем сохранить Тельдрассил и наше ремесло." }, { 27.56, "Приходи, когда сможешь." }, { 29.53, "-Фрагун Шёпот Тени, наставник разбойников" } } } },
    ["25309c1b"] = { d = 18.5, v = "narrator", c = { x = { { 0.00, "Король Ллейн сильно недооценил мощь Орды и мог лишь беспомощно смотреть на то, как его королевство рассыпалось под натиском зеленокожих захватчиков." }, { 11.41, "Вскоре и сам король был убит одним из лучших наёмных убийц Совета Теней, полуорком Гароной." } } } },
    ["253b6b24"] = { d = 24.2, v = "human-male", c = { x = { { 0.00, "Группа из Братства Справедливости встретится с Собирателем, после чего он переправит собранное золото." }, { 6.82, "Убедитесь, что этот процесс произойдёт без ошибок и в условиях строжайшей секретности." }, { 12.49, "Собиратель ответственен за переправку золота, но в конечном счёте каждый член Братства Справедливости должен убедиться, что его роль будет выполнена со всем тщанием и осторожностью." } } } },
    ["253c12f1"] = { d = 32.6, v = "dwarf-male", c = { x = { { 0.00, "Укрощение зверей, меткая стрельба, чтение следов – как научиться всему этому за такую короткую жизнь?" }, { 7.57, "Умение охотника требует недюжинной смекалки и огромного терпения." }, { 12.47, "Путь охотника не из лёгких, это точно." }, { 15.28, "Тебе нужно много тренироваться, чтобы достичь уровня самого неуклюжего ружейника из нашего народа." }, { 22.72, "Потому я тебе и пишу." }, { 24.40, "Приходи в Старую Наковальню, что в Холодной долине." }, { 28.22, "Я буду ждать тебя там." }, { 29.89, "-Торгас Угрюмсон, наставник охотников" } } } },
    ["256b89eb"] = { d = 27.0, v = "human-male", c = { x = { { 0.00, "*Данат Троллебой.*" }, { 1.84, "Командир ополчения Стромгарда." }, { 4.15, "Советник генерала Туралиона, командир армии экспедиции Альянса, которая отправилась в Дренор, родной мир орков." }, { 12.58, "Предположительно погиб." }, { 14.34, "Мы чтим твою память и твою жертву, племянник." }, { 17.81, "Со дня основания нашей славной империи путь к доблести всегда был залит кровью героев." }, { 24.33, "- Торас Троллебой, владыка Стромгарда" } } } },
    ["256c1b08"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "На самом севере Тёмных берегов, за башней Алталакса, лежат руины Матистры." }, { 6.17, "До Великого Раскола здесь стоял город ночных эльфов, но гибель Источника Вечности стёрла его с лица земли, и эльфы навсегда ушли отсюда в прибрежные поселения южнее." }, { 19.91, "В траве и среди разбитых камней до сих пор попадаются реликвии высокорождённых, и молодые эльфы порой отправляются сюда на их поиски." }, { 30.76, "Теперь же в руинах поселились наги, которые ревностно охраняют их от любых чужаков." } } } },
    ["257dbd53"] = { d = 34.8, v = "human-male", c = { x = { { 0.00, "После того как я выжил в побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен." }, { 7.84, "Я провёл в нём несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза." }, { 16.01, "Но оттуда, с моего места, я мог видеть, что эти фермеры – славные ребята." }, { 21.23, "Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять." }, { 29.01, "И стало ещё тяжелее после случившегося ужаса в шахте." }, { 32.84, "Так что я оставался в укрытии." } } } },
    ["257ec00b"] = { d = 27.4, v = "human-female", c = { x = { { 0.00, "Кеган Мракмар, лидер небольшой группы нежити, пришедший к нам в поисках убежища для его \"братьев\", опроверг все обычные представления о таких, как он." }, { 9.90, "Может быть, его кожа гнила, и кровь не течёт по его жилам, но он держал себя очень достойно, и, похоже, заботился больше о безопасности своих товарищей, чем о самом себе." }, { 21.18, "В действительности, признаюсь честно, в нём было больше человечности, чем в некоторых окружающих." } } } },
    ["257f38a0"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "О страшной войне между слугами Хаккара и остальными троллями Гурубаши говорят только шёпотом." }, { 7.51, "От магии, которую обрушивали друг на друга злой бог и его мятежные дети, содрогалась земля." }, { 14.81, "В самый последний момент троллям удалось изгнать Хаккара из мира, убив его аватару." } } } },
    ["2580c8bb"] = { d = 32.2, v = "human-male", c = { x = { { 0.00, "Дневник – день четыре" }, { 1.55, "Я сижу на этом острове наедине со своими мыслями уже четыре дня." }, { 6.25, "Бананы очень вкусные, вот только лазать за ними приходится высоко." }, { 11.07, "В свободное от добывания еды или укрывания от дождя время я думаю лишь о спасении." }, { 17.00, "Я не питал бы такой радостной надежды, если бы на берег вместе со мной не выбросило ящики с бумагой и бутылки." }, { 24.85, "Теперь мне смешно вспоминать о том, как недоволен я был, что застрял на корабле, полном алхимиков и писцов." } } } },
    ["258b0719"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Тефрис-Аран — развалины древнего поселения ночных эльфов на севере Пустошей, чуть севернее Крепости Громового Топора." }, { 9.02, "Город, стоявший здесь, погиб, по всей видимости, в Великий Раскол, и теперь среди разбитых колонн бродят только дикие звери — ни культисты, ни кентавры сюда не заходят." } } } },
    ["262cda96"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Чтобы встретиться с Ледочревом, его надо приманить мясом любимой добычи." }, { 6.18, "Отравляйся в Альтеракские горы, что на Азероте, и поохоться там на крупных горных львов." }, { 13.50, "Убей одного из них и отнеси тушу в Промёрзшую пещеру, святое место для жестоких йети." }, { 20.66, "Положи тушу на Пламя Узеля, и из пещеры потянет ароматом жарящегося мяса." }, { 26.92, "И тогда, в свой черёд, появится Ледочрев." } } } },
    ["264237bc"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Руины Тахонды — остатки древней деревни тауренов на юге Мерцающей равнины, у тропы, ведущей через горы в Танарис." }, { 9.28, "О её жителях не осталось ни преданий, ни имён: солёные ветра давно засыпали покосившиеся шатры, а в кожаных стенах видны следы огромных когтей." }, { 20.73, "Теперь между развалинами бродят лишь солекаменные василиски." } } } },
    ["26542a62"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "С неспешным течением времени росла как территория ночных эльфов, так и их культура." }, { 6.97, "Храмы, дороги и жилища протянулись по всему тёмному континенту." }, { 12.28, "Азшара, прекрасная и талантливая королева ночных эльфов, воздвигла на берегу Источника Вечности огромный, изумительный дворец, в роскошных залах которого проживали её любимые слуги." } } } },
    ["266166d8"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Цветущий оазис раскинулся к югу от Перекрёстка, у подножия холмов, скрывающих вход в Пещеры Стенаний." }, { 8.14, "Среди деревьев бродят кентавры клана Колкар: отсюда их вождь Хэрзул Кровавая Отметина правит своими всадниками и отсюда посылает их в набеги." }, { 19.73, "В воде водятся зубастые черепахи с изменёнными панцирями — порча из пещер добралась и до водопоя." }, { 27.57, "И всё же оазис остаётся одним из немногих зелёных мест среди сухих равнин." } } } },
    ["26656570"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Сенной долгоносик." }, { 1.59, "Отряд: жесткокрылые." }, { 3.34, "Климат: умеренный." }, { 4.93, "Грозная напасть в крошечном панцире." }, { 8.04, "Один-единственный долгоносик меньше чем за час способен сжевать целый тюк сена." }, { 14.71, "Нашествия случаются редко, но чаще всего о них сообщают с севера Восточных королевств." } } } },
    ["2691208a"] = { d = 10.6, v = "narrator", c = { x = { { 0.00, "Валея Два Клинка." }, { 1.61, "Воительница Алого ордена." }, { 3.95, "Жительница Альтерака." }, { 5.88, "Последний раз была замечена в Восточных Чумных землях." } } } },
    ["26954594"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Застава Мейстры — маленький лагерь ночных эльфов на западной дороге Ясеневого леса, между руинами Ордил'Арана и Астранааром: башня, один большой дом и горстка часовых." }, { 13.37, "Здесь живут единственные в лесу люди — паладин Делгрен Очиститель и его спутник, пришедшие помочь эльфам против демонов и нежити и ведущие своё расследование о клане Тёмной Нити." }, { 27.53, "Лекарь Орендил Широколист готовит тут снадобья для больных Астранаара, а Лиладрис Лунная Река встречает путников с Тёмных берегов." } } } },
    ["26bc30e0"] = { d = 19.0, v = "narrator", c = { x = { { 0.00, "Хотя битвы с людьми заканчивались довольно быстро, обе расы успели выяснить сильные и слабые стороны соперников." }, { 8.49, "Ллейну и Лотару не удавалось получить точные сведения о численности орков, и они могли лишь догадываться о том, насколько могуч был их противник." } } } },
    ["26d8899f"] = { d = 9.4, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ." }, { 2.71, "Часть два." }, { 3.82, "Центурион." }, { 5.02, "Легионер." }, { 6.13, "Кровавый страж." }, { 7.83, "Каменный страж." } } } },
    ["26d98e4c"] = { d = 17.7, v = "narrator", c = { x = { { 0.00, "Глава вторая: ВОСТОЧНЫЙ ПИЛОН." }, { 2.58, "Восточный пилон принимает синие, жёлтые и зелёные кристаллы." }, { 7.44, "Пилон фокусирует энергию, которая может быть создана при использовании синих кристаллов в качестве основного источника энергии." } } } },
    ["26f15567"] = { d = 13.3, v = "tauren-male", c = { x = { { 0.00, "Ниже ты найдёшь список того, что мне понадобится для заклинания призыва великого Циклониана." }, { 8.76, "Да сопутствует тебе удача." }, { 11.36, "--Бар-ра Страж Ветра." } } } },
    ["26f3c7f9"] = { d = 50.1, v = "narrator", c = { x = { { 0.00, "Утёс Осквернителя — скалистый кряж посреди пустыни, логово повелителя демонов Выжженных земель." }, { 7.90, "Разелих Осквернитель, самый грозный из подручных Каззака, получил приказ подчинить эту землю и связал клятвой трёх могущественных слуг, отдав каждому по трети своего амулета." }, { 22.49, "Пока осколки остаются в пределах Выжженных земель, ни слуг, ни их хозяина не берёт обычное оружие." }, { 30.61, "На вершине утёса вырезаны руны телепортации, и путь туда открыт лишь тому, кто соберёт амулет воедино." }, { 39.03, "У подножия, среди обгоревших купольных построек, ютятся Заблудшие — дренеи-изгнанники, собирающие дренетист в надежде вернуться домой." } } } },
    ["270a39b3"] = { d = 23.8, v = "human-male", c = { x = { { 0.00, "РАПОРТ: Кобольды." }, { 1.26, "Рядом с Долиной Североземья наблюдается повышенная активность кобольдов." }, { 6.29, "Огромное количество этих существ было замечено к северу от аббатства и на Руднике Горного Эха." }, { 12.96, "Я нашёл добровольцев среди паладинов, воинов и всех, кто был готов помочь нам в борьбе с этой напастью." }, { 20.07, "Пока дела идут хорошо." }, { 21.76, "Желающих помочь предостаточно." } } } },
    ["275921e3"] = { d = 16.8, v = "narrator", c = { x = { { 0.00, "Клан Бронзобородов вернулся в Стальгорн и восстановил свой славный город." }, { 5.85, "Громовой Молот также вернулся домой, в Грим Батол." }, { 10.01, "Но смерть Модгуд осквернила крепость, и дворфы Громового Молота не могли уже там жить." } } } },
    ["27645e60"] = { d = 27.8, v = "narrator", c = { x = { { 0.00, "Чумной овраг тянется к западу от Перекрёстка Корина." }, { 4.31, "В отличие от Морового оврага, эта расселина — не творение природы, а след тёмной магии: когда рунный клинок рыцаря смерти Мардука Чёрного сломался о щит дворфийского капитана в бою у перекрёстка, обломок лезвия ушёл в землю и разверз её." }, { 23.61, "Рукоять Мардук забрал с собой, а расселина осталась." } } } },
    ["2769f251"] = { d = 37.8, v = "narrator", c = { x = { { 0.00, "Фермерша Калаба" }, { 1.41, "Крупный долг." }, { 2.58, "Выплата сельскохозяйственной продукцией обещана в урожай." }, { 7.51, "Гражданин Уилкс" }, { 8.91, "Все задолженности выплачены." }, { 11.34, "Гражданин Боноан" }, { 12.82, "Все задолженности выплачены." }, { 15.25, "Шахтёр Веллти" }, { 16.42, "Крупный долг." }, { 17.59, "Выплата состоится после поставки руды из Лазурного рудника." }, { 22.83, "Шахтёр Сидней" }, { 24.00, "Крупный долг." }, { 25.18, "Выплата состоится после поставки руды из Лазурного рудника." }, { 30.41, "Шахтёр Хакетт" }, { 31.59, "Крупный долг." }, { 32.76, "Выплата состоится после поставки руды из Лазурного рудника." } } } },
    ["27795f78"] = { d = 49.4, v = "narrator", c = { x = { { 0.00, "Прибамбасск — столица картеля Хитрая Шестерёнка, гоблинский город за высокими стенами посреди северного Танариса." }, { 8.47, "Здесь торгуют лучшие инженеры, рудокопы и алхимики Калимдора, а на нейтральном аукционе сходятся купцы Орды и Альянса: гоблины ценят прибыль выше верности, и любой с тугим кошельком здесь желанный гость." }, { 23.70, "За порядком следят прибамбасские костоломы, готовые утихомирить каждого, кто мешает торговле." }, { 30.68, "Отсюда Водная компания Прибамбасска управляет колодцами в пустыне, а гоблин Синь Гогельмогель мечтает разбогатеть на эликсире собственного изобретения." }, { 41.92, "Дороги от ворот ведут к Порту Картеля на востоке, к Зул'Фарраку на западе и через горы в Тысячу Игл." } } } },
    ["27874b94"] = { d = 29.3, v = "narrator", c = { x = { { 0.00, "Огненное логово к западу от руин Деревни Каменного Молота — бывший огрский курган, крупнейшая постройка клана." }, { 8.79, "После падения деревни его захватили драконоиды чёрной стаи, и теперь у входа стоят на страже чешуйчатые воины Ониксии, а внутри тлеет огонь." }, { 20.00, "Огры помнят, что где-то в этом кургане остались их святыни, но пробиться к ним сквозь драконью стражу под силу немногим." } } } },
    ["27907660"] = { d = 30.5, v = "narrator", c = { x = { { 0.00, "Каньон Визга — ущелье на юге Тысячи Игл, названное за пронзительные крики гарпий, не смолкающие здесь ни днём, ни ночью." }, { 9.67, "Гарпии кружат над скалами и бросаются на всякого, кто ступит на дно каньона; таурены Заставы Вольного Ветра считают их меньшей бедой, чем кентавров, но и с них не спускают глаз." }, { 23.89, "В дальнем конце ущелья скрыт вход в Логово Легкопёрых, где стая прячет награбленное." } } } },
    ["2792a71c"] = { d = 12.9, v = "narrator", c = { x = { { 0.00, "Имя его не умрёт." }, { 1.72, "Жертва его всегда" }, { 3.52, "Нам будет указывать путь." }, { 5.92, "Оковы, что крепко держали" }, { 8.41, "Честь, отвагу и смелость," }, { 10.81, "Нас не стесняют теперь." } } } },
    ["27c4eb1b"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Утёс Колкара — каменистое ущелье на юге Дуротара, названное по племени кентавров, что засели в нём." }, { 7.62, "Колкары совершают набеги на окрестности, и разведчики Орды уже перехватывали их замыслы — тройной удар по позициям троллей и орков." }, { 17.83, "Ущелье лежит недалеко от деревни Сен'джин, и её жители первыми ощущают на себе жестокость кентавров." } } } },
    ["27c8d057"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Форт у северных врат — самое северо-восточное поселение дворфов в Дун Мороге, застава посреди северного перевала." }, { 8.71, "Горные пехотинцы здесь без конца отбиваются от зверья, а несколько дворфов пропали в горах, отправившись на охоту за самыми свирепыми хищниками." }, { 19.78, "Пилот осадного орудия Мори Хилдельв ушёл в холмы искать редкую руду и не вернулся." }, { 26.26, "Молодым дворфам и гномам поручают искать следы пропавших." } } } },
    ["27ec8074"] = { d = 14.9, v = "creature/ancient", c = { x = { { 0.00, "Соленор Душегуб:" }, { 1.77, "В безводных землях Силитуса рыщет наш враг." }, { 6.23, "Он дьявольски хитёр и очень опасен." }, { 9.85, "Подберись к нему и вынуди его принять свой облик." } } } },
    ["27f4d76a"] = { d = 36.4, v = "narrator", c = { x = { { 0.00, "Панель управления самофланжа можно использовать, чтобы автоматически регулировать поток топлива, газов, жидкостей и связанные с этим механизмы." }, { 11.07, "После завершения исходной регулировки она должна оперировать без проблем при минимальной поддержке." }, { 17.50, "Краткий список компонентов элементов панели управления (слева направо)." }, { 23.99, "Первое: тумблер включения." }, { 25.99, "Позиция \"включено\" задействует самофланж." }, { 29.05, "Контрольный механизм не отключится автоматически при переводе рычага в положение \"выключено\"." }, { 35.84, "Это лишь" } } } },
    ["28033208"] = { d = 25.6, v = "narrator", c = { x = { { 0.00, "ВОИНСКИЕ ЗВАНИЯ ОРДЫ И АЛЬЯНСА." }, { 2.74, "Тром'ка!" }, { 3.51, "В этой книге ты найдёшь подробный перечень воинских званий Орды и жалкого Альянса." }, { 10.52, "Сначала в списках идёт Орда, а затем Альянс, и для обеих сторон перечислены офицерские и рядовые звания." }, { 19.36, "Как и подобает, вверху списка располагаются старшие чины, а младшие – ниже." } } } },
    ["2831ce36"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Титан Каз'горот, ваятель и кузнец мира, даровал часть своей огромной силы могучему чёрному змею Нелтариону." }, { 8.97, "Великодушный Нелтарион, позже известный как Хранитель Земли, получил власть над почвой, камнем и подземными недрами." }, { 18.54, "Воплотив в себе силу мира, он стал самым могущественным сторонником Алекстразы." } } } },
    ["283251fc"] = { d = 18.9, v = "tauren-male", c = { x = { { 0.00, "*Призыв на службу в Орду Этот человек показал невероятные достижения силы и навыка во имя Орды.*" }, { 7.69, "*Его следует немедленно назначить на работу на Перекрёсток.*" }, { 12.30, "*Почтительно ваш:*" }, { 13.52, "Мне кажется, неплохо." }, { 16.13, "- Такрин Торитель Путей" } } } },
    ["28326bfa"] = { d = 37.2, v = "narrator", c = { x = { { 0.00, "Лощина Вул'Гол – низина на юге Сумеречного леса, чуть западнее того места, где главная дорога поворачивает на юг, к Тернистой долине." }, { 10.51, "Когда-то здесь жили люди, о чём напоминают развалины ферм, но теперь низину целиком заняли огры клана Дробящего Кулака во главе с Ззарк'Вулом, по имени которого и назван курган." }, { 24.50, "В пещере огров валяются туши чёрных медведей – их припасы." }, { 29.11, "Именно у этого кургана огры напали на старика-травника Аберкромби и отняли у него ящик с инструментами." } } } },
    ["28651e89"] = { d = 19.7, v = "human-female", c = { x = { { 0.00, "Кровь, что я пролила возле подвески Кровавого камня, медленно двигалась по направлению к драгоценности, как если бы её притягивала к камню некая сила." }, { 10.32, "А кровь, что попала на подвеску, похоже, исчезла, и красный цвет камня стал ещё более насыщенным, когда тот всосал ещё немного моей крови." } } } },
    ["287d48a3"] = { d = 44.2, v = "gnome-male", c = { x = { { 0.00, "Лорд Вальтхалак, продолжение." }, { 1.96, "Мы разделили амулет на части и сосредоточились на спасении собственных жизней от призрака Вальтхалака и его воинов." }, { 9.76, "К несчастью, весь этот шум привлёк внимание остальных защитников Пика." }, { 14.48, "С небольшими потерями нам удалось-таки выбраться из Чёрной горы, и мы думали, что оказались в безопасности." }, { 21.60, "Но мы ошибались: даже с того света Вальтхалак безошибочно указывал своим воинам, где мы скрываемся." }, { 28.35, "Общество Тайных клинков вскоре распалось, и поодиночке мы стали ещё более лёгкой добычей." }, { 34.42, "Как ты уже, должно быть, знаешь, логово Вальтхалака, теперь известное как чертог Зверя в Пике Чёрной горы, и есть последнее из мест с привидениями." } } } },
    ["2889aba4"] = { d = 20.0, v = "human-male", c = { x = { { 0.00, "Здравствуй, Морган!" }, { 1.28, "Дела в Златоземье идут бойко, так бойко, что у меня не было времени отправить тебе товар!" }, { 7.16, "Я нанял человека, который принесёт эту записку, доставить тебе пачку больших восковых свечей (тех, что кобольды обычно носят на голове)." }, { 16.01, "Будь добр, отблагодари этого человека и заплати ему как следует." } } } },
    ["288d706a"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "Аванпост Среброкрылых стоит на юге Ясеневого леса, на восточном берегу реки Фалфаррен, к юго-западу от заставы Расщеплённого Дерева." }, { 10.28, "Это восточный оплот Альянса, и, поскольку он стоит на орочьем берегу реки, часовые здесь отбивают постоянные атаки: воины клана Песни Войны поклялись избавить лес от Среброкрылых раз и навсегда." }, { 25.38, "Гарнизоном командует Дариэль Лунное Пламя, а вестницы аванпоста разведывают лес до самой заставы орков." }, { 33.41, "Орк Торек уже собирает бойцов для налёта." } } } },
    ["28d022b9"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Хранительница Эгвин с течением времени становилась всё могущественнее, используя энергии Тирисфаля, чтобы продлить свою жизнь." }, { 9.92, "Самоуверенно надеясь, что она победила Саргераса, она продолжала охранять мир от приспешников короля демонов почти девятьсот лет." }, { 20.12, "Но в конце концов Совет Тирисфаля объявил, что время её службы подошло к концу." } } } },
    ["295ec870"] = { d = 24.8, v = "human-male", c = { x = { { 0.00, "Обращаюсь ко всем мужчинам и женщинам, способным держать в руках оружие:" }, { 5.04, "Плеть вновь объединила свои силы, и мы вместе должны дать ей достойный отпор, отбросив в сторону все наши разногласия." }, { 13.23, "Каждый, кто готов сражаться, должен прийти на сбор к часовне Последней Надежды, что в Восточных чумных землях." }, { 20.91, "Вместе мы победим." }, { 22.23, "Хранитель архивов" }, { 23.49, "Серебряного Рассвета" } } } },
    ["29a1a82b"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Одним из таких вождей был Дуротан из клана Северного Волка; он указал оркам на то, что они начали терять контроль над собой и поддаваться гневу и ненависти." }, { 12.22, "Но они были глухи к его предостережениям, да и многие более могущественные вожди, среди которых был Гром Адский Крик из клана Песни Войны, выступили в поддержку новой эры войны и господства." } } } },
    ["29b8a603"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Чиновник Резерфорд Бернсайд" }, { 2.49, "Все задолженности выплачены." }, { 4.97, "Кузнец Эйвери Веррингтан" }, { 7.22, "Все задолженности выплачены." }, { 9.70, "Клерк Гораций Белоконь" }, { 11.71, "Все задолженности выплачены." }, { 14.19, "Советник Гиллис" }, { 15.63, "Все задолженности выплачены." }, { 18.12, "Советник Крюкс" }, { 19.40, "Все задолженности выплачены." }, { 21.89, "Фермер Гетц" }, { 22.93, "Все задолженности выплачены." }, { 25.41, "Фермер Рей" }, { 26.38, "Крупный долг." }, { 27.58, "Выплата долга сельскохозяйственной продукцией обещана в урожай." }, { 33.19, "Фермер Лаийон" }, { 34.47, "Крупный долг." }, { 35.68, "Выселен с земли." } } } },
    ["29e26c12"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Титан Каз'горот, ваятель и кузнец мира, даровал часть своей огромной силы могучему чёрному змею Нелтариону." }, { 8.84, "Великодушный Нелтарион, позже известный как Землестраж, получил власть над почвой, камнем и подземными недрами." }, { 17.83, "Воплотив в себе силу мира, он стал самым могущественным сторонником Алекстразы." } } } },
    ["2a7d0b54"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Но втайне от Альянса, большая группа орков продолжала странствовать по пустошам Каз Модана." }, { 6.98, "Клан Драконьей Пасти, возглавляемый коварным чернокнижником Некросом, с помощью могущественного артефакта под названием \"Душа Демона\" подчинил себе королеву драконов Алекстразу и её подданных." }, { 21.55, "Удерживая королеву в заложниках, Некрос собрал тайную армию в заброшенной цитадели Громового Молота, которую многие считали проклятой." } } } },
    ["2a97ebbb"] = { d = 16.5, v = "narrator", c = { x = { { 0.00, "Этот скелет птерадона был найден в Кратере Ун'Горо." }, { 4.04, "Глядя на его структуру, мы можем сделать вывод, что перед нами новый, неизвестный науке вид." }, { 11.27, "Скелет мог пролежать под слоем богатой почвы Ун'Горо много столетий." } } } },
    ["2aaee008"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Хребет Седых Лап поднимается к югу от Телсамара и к востоку от Долины Камнедробов." }, { 6.52, "Эти скалы облюбовала большая стая медведей, и самый грозный из них — Старина Черношкур, огромный зверь, который порой спускается из своего логова к подножию долины." }, { 19.63, "Год назад весь Приют Странников выходил на него на охоту, но никому не посчастливилось его одолеть." } } } },
    ["2acebbf4"] = { d = 29.3, v = "narrator", c = { x = { { 0.00, "Чтобы Кел'Тузаду было легче справиться со своим заданием, Нер'зул оставил ему человеческую внешность." }, { 7.86, "Престарелому, но тем не менее умевшему привлечь к себе сторонников магу предстояло использовать свой дар убеждения и иллюзии, чтобы внушить угнетённым жителям Лордерона веру и надежду." }, { 21.78, "После этого он должен был показать им, насколько лучше они могли бы жить под властью нового короля." } } } },
    ["2afcdf12"] = { d = 19.3, v = "human-male", c = { x = { { 0.00, "Исследуя окаменелости, я пришёл к выводу, что в древние времена великая чума свирепствовала у озера Лордамер." }, { 7.72, "Что послужило её причиной?" }, { 9.54, "Мы никогда не узнаем." }, { 11.04, "Но уровень загрязнения весьма высок, исходя из насыщенной концентрации останков, представленных в залежах озёрного пласта." } } } },
    ["2b07f3c0"] = { d = 26.3, v = "orc-male", c = { x = { { 0.00, "В этом самом зале ты найдёшь Вол'джина из племени Чёрного Копья." }, { 5.50, "Тролли Чёрного Копья – верные друзья орков; наш союз скреплён кровью в жарких боях во время бегства из земель людей на восточном континенте." }, { 17.57, "Отнесись к нему с уважением – и он ответит тем же." }, { 21.83, "А если проявишь неуважение... в общем, лучше не надо." } } } },
    ["2b168c03"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "На самом юге Тёмных берегов, у границы с Ясеневым лесом, укрылась Берлога в Чернолесье — несколько стойбищ фурболгов клана Чернолесья и небольшая пещера." }, { 12.37, "Когда-то эти фурболги были дружелюбны к ночным эльфам, но сатиры подчинили их при помощи талисманов, и порча превратила лесной народ в свирепых врагов." }, { 24.67, "В пещере, окружённой их лагерями, скрывается раненый ночной эльф Волкор, а его верный медведь Мрачнокоготь ждёт у дороги, надеясь привести помощь." } } } },
    ["2b1cbdc5"] = { d = 22.3, v = "narrator", c = { x = { { 0.00, "Военные звания Орды." }, { 2.29, "Офицеры: Верховный Вождь, Вождь, Генерал, Лейтенант-генерал, Защитник, Центурион, Легионер, Кровавый Страж, Каменный Страж." }, { 15.06, "Рядовые: Высший Сержант, Старший сержант, Сержант, Рубака, Разведчик." } } } },
    ["2b23fa06"] = { d = 19.4, v = "narrator", c = { x = { { 0.00, "Оргрим, разгневанный убийством Дуротана, решил освободить Орду от ужасного проклятья и, чтобы стать новым вождём Орды, убил Чернорука, марионетку Гул'дана." }, { 12.67, "Под его твёрдым руководством безжалостная Орда наконец окружила Крепость Штормграда." } } } },
    ["2b24888c"] = { d = 27.7, v = "orc-male", c = { x = { { 0.00, "Круг большего Единения" }, { 1.89, "Создавать Круг Большего Единения нужно там, где сильна магия." }, { 7.02, "Такое место есть в глубине развалин Эльдре'Таласа, называемого также Забытым Городом." }, { 14.18, "В Эльдре'Таласе пленено существо великой силы, Бессмер'тер; именно у подножия его темницы и надо создавать Круг." }, { 23.61, "Проберись к Подножию и выпусти Д'жииви на свободу." } } } },
    ["2b46d48f"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Змеиные Кольца — извилистая пещера на востоке пустыни, у обгоревших остовов орочьих построек, оставшихся со времён Второй войны." }, { 10.47, "В её петляющих ходах свили гнездо чернокнижники из Приверженцев Тени, служащие демонам Выжженных земель." }, { 19.02, "Здесь творят тёмные ритуалы, и здесь же, по слухам, укрывается один из трёх могущественных слуг Разелиха Осквернителя, чья жизнь связана с осколком демонического амулета." }, { 32.51, "Тьма пещеры ревниво хранит свои тайны." } } } },
    ["2b593b35"] = { d = 10.8, v = "creature/furbolg", c = { x = { { 0.58, "Больше." }, { 1.77, "Ещё больше…" }, { 3.50, "Клан Зимней Спячки… не… слабый…" } } } },
    ["2b62f998"] = { d = 17.1, v = "narrator", c = { x = { { 0.00, "Когда Саргерас увидел юный мир Азерота и почуял энергию источника Вечности, в нём проснулся неутолимый голод, и великий тёмный бог Безымянной Бездны решил уничтожить этот мир и завладеть его силой." } } } },
    ["2b869c7c"] = { d = 10.0, v = "dwarf-male", c = { x = { { 0.00, "На следующих страницах ты найдёшь список материалов, необходимых для изготовления закалённого оружия." }, { 7.42, "Удачи, воин." }, { 8.45, "-Фьюрен Длиннобородый." } } } },
    ["2ba020b9"] = { d = 19.0, v = "human-female", c = { x = { { 0.00, "Несмотря на то что мои коллеги в Даларане настороженно отнеслись к идее изучения кровавых камней, что Кеган и его спутники принесли с собой, заключив в карантин четырёх беженцев и оставив их кровавые камни при них, искренность Кегана обязала меня изучить его подвеску Кровавого камня." } } } },
    ["2baf1653"] = { d = 42.2, v = "narrator", c = { x = { { 0.00, "Память о доблести." }, { 1.62, "Повесть о роде Вэлор и их служении Вороньему Холму." }, { 6.08, "Во всех Восточных королевствах не было рода славнее, чем род Вэлор." }, { 11.77, "Их деяния во благо тех, кого они поклялись защищать, были поистине чудом, и их утрата – утрата для всего Вороньего Холма." }, { 22.24, "Я пишу эту повесть, чтобы воздать им по справедливости и рассказать о том, какими удивительными людьми были Брант, Ира, Сильвия и Меррик." }, { 33.93, "Пусть эти строки станут хоть малым утешением – ведь мне бесконечно горько, что их больше нет с нами." } } } },
    ["2bc36e8a"] = { d = 35.9, v = "narrator", c = { x = { { 0.00, "Лагерь Кровавого Клыка стоит к западу от реки Фалфаррен, к югу от главной дороги, близ южного лунного колодца." }, { 8.70, "Здесь живёт племя фурболгов под началом Рэна Кровавого Клыка — жадного и властолюбивого вождя, которого порча лишь сделала сильнее." }, { 18.88, "Его воины нападают на путников на дороге, что сворачивает на восток перед рекой, и часовые Астранаара просят отплатить им той же монетой." }, { 29.54, "Даже фурболг Кролг, не тронутый порчей, считает Рэна злом, которое надо остановить." } } } },
    ["2bc5024c"] = { d = 24.4, v = "narrator", c = { x = { { 0.00, "Объединившиеся эльфийские и людские армии вступили в схватку с огромной армией троллей у подножья Альтеракских гор." }, { 9.25, "Битва продолжалась много дней, но неослабевавшая армия Аратора не уставала и не отступала под натиском троллей." }, { 18.14, "Эльфийские властители решили, что пришло время ниспослать силы магии на врага." } } } },
    ["2bfd85e2"] = { d = 45.0, v = "narrator", c = { x = { { 0.00, "На севере Бесплодных земель, к югу от Ульдамана, стоит крепость Ангор, главный оплот дворфов Чёрного Железа в этом краю." }, { 9.76, "Отсюда клан Тенегорна ведёт вылазки в древние своды: дворфы верят, что в Ульдамане сокрыты тайны титанов, которые пригодятся их огненному владыке Рагнаросу." }, { 22.27, "В крепости пребывает и посланник самого Рагнароса, огненный элементаль, надзирающий за усердием его слуг." }, { 30.66, "Стены стерегут воины и чтецы заклинаний, а по дворам тяжело ступают каменные големы." }, { 37.53, "Говорят, что силы Тенегорна в Ульдамане рассеются, если ударить по крепости, в самое их сердце." } } } },
    ["2c189c1b"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Нептулон восстал из океана огромной водяной башней и наслал на обречённый И'лалай огромных краккенов." }, { 8.30, "Столь огромны были эти твари, что со щупальцев их свисал лес водорослей, и левиафаны проплывали сквозь них." }, { 16.98, "Самый громадный из краккенов воздел конечности и обрушил их на море, подняв волны." }, { 23.80, "И волны эти яростно устремились к И'лалаю." } } } },
    ["2c238468"] = { d = 26.9, v = "narrator", c = { x = { { 0.00, "Холмистые равнины занимают большую часть южного Мулгора, от деревни Кровавого Копыта до границы со Степями." }, { 8.67, "Здесь живёт множество зверей: волки прерий, кодо, долгоноги и пумы." }, { 14.14, "Это единственное место в Мулгоре, куда сумели проникнуть кентавры — их всадники порой бродят по этим травам." }, { 23.03, "На востоке равнин гнездятся гарпии Ярости Ветра." } } } },
    ["2c482863"] = { d = 30.3, v = "human-male", c = { x = { { 0.00, "*Генерал Туралион*" }, { 1.92, "." }, { 2.05, "Бывший наместник лорда Андуина Лотара." }, { 5.00, "Рыцарь Серебряной Длани." }, { 6.87, "Верховный генерал экспедиции Альянса, которая отправилась в Дренор, родной мир орков." }, { 13.22, "Предположительно погиб." }, { 14.96, "Эзарус тар-но Дарадор – Кровью и честью мы служим." }, { 18.77, "Ты был правой рукой справедливости и добродетели, старый друг." }, { 23.31, "Твоё имя всегда будет почитаться в наших залах." }, { 26.92, "- Лорд Утер Светоносец, рыцарь Серебряной Длани" } } } },
    ["2c4f66a7"] = { d = 13.8, v = "narrator", c = { x = { { 0.00, "Заклятый солнцем и луной," }, { 2.39, "Оставь сей камень роковой," }, { 4.86, "Нетленны рока письмена:" }, { 7.08, "В гробнице Смерть заточена," }, { 9.55, "Хранит недрогнувшей рукой" }, { 11.94, "Она властителя покой." } } } },
    ["2c99c5ff"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Лагерь Легаши раскинулся на севере Азшары, восточнее Урсолана." }, { 5.08, "Среди обломков эльфийских построек засели сатиры Легаши — порождения Пылающего Легиона, некогда бывшие высокорождёнными." }, { 14.74, "Они творят здесь тёмные обряды, и говорят, что в их лагере хранились книги демонической магии, которыми интересовался даже верховный маг Ксилем." }, { 26.29, "Тому, кто чтит Элуну, здесь не рады." } } } },
    ["2cab5939"] = { d = 26.6, v = "dwarf-male", c = { x = { { 0.00, "Глава один – Линия фронта" }, { 2.05, "Передние линии обороны Клана Северного Волка состоят из воинов клана." }, { 7.46, "Эти воины отправляются на передовую из крепости капитана Гальвангара под названием гарнизон Стылой Крови." }, { 15.48, "Проще всего расправиться с этой линией обороны, разрушив гарнизон." }, { 20.61, "Осади крепость и убей капитана Гальвангара." }, { 23.97, "После этого передовые линии падут." } } } },
    ["2cba589e"] = { d = 22.1, v = "narrator", c = { x = { { 0.00, "Странствуя по полям рассвета, дети земли слышали мрачный шёпот из подземных недр." }, { 6.88, "Этот шёпот рассказывал им про войну и обман." }, { 10.62, "Многие Шу'хало попали под его чары и впустили зло в свои души." }, { 16.05, "Они отвернулись от своих добрых братьев и утратили первозданную чистоту." } } } },
    ["2cc23018"] = { d = 40.9, g = 1, v = "tauren-male", c = { m = { { 0.00, "Могучие воины защищают наши дома." }, { 3.28, "Мудрые шаманы охраняют наши души и ведут нас по дороге предков." }, { 9.34, "Друиды сообщают нам волю Матери-Земли." }, { 13.05, "Но ты – охотник, а это призвание объединяет в себе умения воинов, шаманов и друидов." }, { 20.96, "Такие, как ты, являются сердцем нашего народа." }, { 25.34, "К тебе будут обращаться за советом и защитой." }, { 29.63, "Я должен удостовериться, что ты готов к этому." }, { 33.92, "Приходи в Лагерь Нараче." }, { 36.28, "-Ланко Дальний Выстрел, наставник охотников" } }, f = { { 0.00, "Могучие воины защищают наши дома." }, { 3.32, "Мудрые шаманы охраняют наши души и ведут нас по дороге предков." }, { 9.45, "Друиды сообщают нам волю Матери-Земли." }, { 13.20, "Но ты – охотница, а это призвание объединяет в себе умения воинов, шаманов и друидов." }, { 21.29, "Такие, как ты, являются сердцем нашего народа." }, { 25.72, "К тебе будут обращаться за советом и защитой." }, { 30.06, "Я должен удостовериться, что ты готова к этому." }, { 34.49, "Приходи в Лагерь Нараче." }, { 36.87, "-Ланко Дальний Выстрел, наставник охотников" } } } },
    ["2d277fbf"] = { d = 9.5, v = "narrator", c = { x = { { 0.00, "Спиральные символы и пиктограммы, которыми испещрены страницы этого пособия, настолько запутанны, что их невозможно разобрать." } } } },
    ["2d27b686"] = { d = 29.2, v = "dwarf-male", c = { x = { { 0.00, "День четвёртый." }, { 1.06, "Мои запасы подходят к концу." }, { 3.26, "У меня всё ещё очень много еды, но я не планировал столь долго оставаться в лесу, так далеко от моего танка, и взял с собой лишь два кега эля." }, { 13.71, "Я не спал обе прошлые ночи, прислушиваюсь к этому проклятому рёву, и практически до дна выпил оба кега!" }, { 21.29, "Завтра мне придётся повернуть назад к Молотоногу и нашим паровым танкам." }, { 26.62, "Я не хочу здесь пропасть без выпивки." } } } },
    ["2d486493"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Услыхав от магократов вести о действиях демонов в Даларане, эльфы немедленно послали своих самых могущественных волшебников к людям." }, { 10.10, "Эльфийские волшебники изучили течение энергии в Даларане и составили детальные отчёты о действиях демонов." }, { 18.15, "Они заключили, что, хотя в мире пока не так много демонов, сам Легион будет по-прежнему представлять огромную угрозу, пока люди используют магию." } } } },
    ["2d6589a2"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Долина Кристаллов лежит в дальнем северо-западном углу Силитуса, среди скал, богатых ториевой рудой." }, { 7.87, "Здесь бродят духи земли и воздуха, и воздух гудит от их гнева." }, { 12.74, "По рассказам сектантов, честолюбивый чернокнижник Демитриан из Сумеречного Молота попытался поработить в этой долине могучего повелителя ветра и сам угодил к нему в услужение." }, { 26.18, "Теперь от его лагеря остались лишь обгорелые развалины, а сам Демитриан всё ещё скитается среди кристаллов." } } } },
    ["2d9e6132"] = { d = 33.3, v = "human-male", c = { x = { { 0.00, "Собирая образцы мха, я случайно стал свидетелем сцены кровавой битвы." }, { 4.91, "Клан мурлоков Коварного Плавника подвергся нападению мародёрствующих банд гноллов." }, { 10.59, "Трупы и гноллов, и мурлоков были разбросаны по всему полю боя." }, { 15.12, "Когда я проходил мимо растерзанного тела мурлока, я заметил странно затвердевшую опухоль, выступающую из раны." }, { 22.96, "Когда я начал изучать её, стало ясно, что похожие свойства я обнаружил у мха, который собирал." }, { 29.66, "К сожалению, больше я не смог найти ни одной опухоли." } } } },
    ["2dce3d41"] = { d = 22.3, g = 1, v = "nightelf-male", c = { m = { { 0.00, "Доставил бы это письмо тебе сам, но боюсь отлучиться, поскольку могу пропустить нечто очень важное." }, { 7.83, "Если ты желаешь побольше узнать о моих наблюдениях за Башней Алталакса, знай, что податель сего письма немало мне помог и ему вполне можно доверять." }, { 19.44, "Спешно заканчиваю," }, { 20.91, "Балтул Удар Тени" } }, f = { { 0.00, "Доставил бы это письмо тебе сам, но боюсь отлучиться, поскольку могу пропустить нечто очень важное." }, { 7.79, "Если ты желаешь побольше узнать о моих наблюдениях за Башней Алталакса, знай, что подательница сего письма немало мне помогла и ей вполне можно доверять." }, { 19.62, "Спешно заканчиваю," }, { 21.08, "Балтул Удар Тени" } } } },
    ["2df3ec67"] = { d = 15.4, v = "narrator", c = { x = { { 0.00, "Следующие месяцы он провёл, испытывая чуму нежити на оставшихся людях Нордскола, пока не поработил их всех." }, { 8.52, "Армия нежити росла с каждым днём, и он понял, что пришло время для настоящего испытания." } } } },
    ["2e3ac48b"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "На юго-востоке Болотины, недалеко от дворфийских врат Дун Альгаза, раскинулось Болото Мохошкуров — земля гноллов одноимённой стаи." }, { 10.46, "Долгие годы они жили здесь тихо, но стая разрослась: гноллы вытаптывают луга, рубят лес на дрова и жгут костры по всему болоту." }, { 20.92, "Их стоянки разбросаны между деревьев, и Зелёный Страж, хранитель здешних мест, давно смотрит на них с неприязнью." } } } },
    ["2e590a0c"] = { d = 37.2, v = "narrator", c = { x = { { 0.00, "Деревня Маграм — стойбище кентавров на юго-востоке Пустошей, разбросанное по берегам и островкам жёлтых ядовитых озёр, связанным грубыми мостами." }, { 11.98, "Маграм признают только силу: они не поклоняются Терадрас, как их братья Гелкис, и верят, что племя выживет лишь боевым духом." }, { 22.46, "Вождь Джехн ведёт их в бесконечной войне с Гелкис, а старейшины охотно принимают помощь чужаков — если те докажут силу, пролив кровь врагов." }, { 33.99, "Слабых же Маграм не слушают: их убивают." } } } },
    ["2e796f58"] = { d = 18.0, v = "narrator", c = { x = { { 0.00, "Форт Галак — владения кентавров племени Галак в северной части Тысячи Игл." }, { 6.05, "У подножия игл стоят их шатры и горят костры, а по дну каньона рыщут разведчики и мародёры племени, готовые напасть на всякого, кто спустится с мостов." } } } },
    ["2e7cf3ec"] = { d = 30.7, v = "human-male" },
    ["2e84ad33"] = { d = 31.1, v = "narrator", c = { x = { { 0.00, "Прошло время, и Эгвин родила сына в укромной роще." }, { 4.37, "Назвав мальчика Медив, что означало \"хранитель секретов\" на языке высших эльфов, Эгвин верила, что мальчик будет готов к тому, чтобы стать Хранителем." }, { 17.03, "К сожалению, злой дух Саргераса, таившийся в ней, вселился в дитя, ещё находившееся в её чреве." }, { 24.79, "Эгвин не знала, что новый Хранитель мира уже одержим его величайшим врагом." } } } },
    ["2e8668bb"] = { d = 2.3, v = "narrator", c = { x = { { 0.00, "Диаграмма северного пилона." } } } },
    ["2e8d211e"] = { d = 22.2, v = "human-male", c = { x = { { 0.00, "Добрый день, Шнайдер!" }, { 1.42, "Надеюсь, дела в районе каналов идут хорошо." }, { 4.39, "У нас тут, в торговом квартале, большой наплыв покупателей." }, { 8.24, "Нам нужно побольше вязаной одежды, наши запасы на исходе." }, { 12.10, "Пожалуйста, пришлите мне стандартную партию при первой же возможности." }, { 16.67, "Удачи." }, { 17.14, "Надеюсь, занятия вашего сына Тармена тоже продвигаются неплохо." }, { 21.41, "Харлан Багли" } } } },
    ["2eae9c9d"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Северные врата — тоннель, пробитый сквозь горы между высокогорным Дун Морогом на западе и Лок Моданом на востоке." }, { 8.49, "Этим путём чаще всего идут те, кто направляется к Болотине: отсюда ближе всего до спуска с озёрных высот." }, { 16.43, "На дун-морогской стороне прохода стоит застава горных пехотинцев, а на восточном выходе дорога ведёт к станции Альгаз и рудникам северного берега." } } } },
    ["2ede0c0b"] = { d = 25.3, v = "scourge-male", c = { x = { { 0.00, "Сердце Наследия." }, { 1.61, "Старые тексты говорят, что тот, кто обладает сердцем Наследия, не боится могилы." }, { 9.16, "Возможно, это правда, ведь владелец сердца, Тролль Могх, известен как Могх Неумирающий." }, { 17.22, "Знахарь клана Дробителей Черепов, Могх, обитает в Тернистой долине на Руинах Зул'Мамве." } } } },
    ["2f3aaabf"] = { d = 19.6, v = "human-female", c = { x = { { 0.00, "Зато Кеган очень охотно говорил о других вещах, особенно о своём детстве, проведённом в Лордероне до его падения." }, { 7.56, "Он по-прежнему полон любви к этому потерянному королевству, хотя оно сейчас разрушено и мертво." }, { 13.98, "Растущая привязанность к Кегану придавала мне терпения в ожидании результатов анализов." } } } },
    ["2f41143f"] = { d = 29.5, v = "human-male", c = { x = { { 0.00, "Тело жены Свена стояло прямо, как доска, а её глаза распахнулись." }, { 4.90, "И хотя её губы широко открылись в крике, не раздалось ни звука." }, { 9.60, "После нескольких секунд этой пытки рука отпустила её, и она упала на колени." }, { 15.36, "Всадник, державший драгоценность, сел прямо в своём седле и громкий голос раздался из камня." }, { 22.12, "\"Эта женщина лжёт,\" – раздался голос, пугающий меня теперь в кошмарах." }, { 27.35, "\"Она никогда не видела косу\".\"" } } } },
    ["2f67aef2"] = { d = 28.8, v = "dwarf-male", c = { x = { { 0.00, "День второй." }, { 0.93, "Степи бескрайни." }, { 2.19, "Мой поход был долог и утомителен, но пока что не дал никаких результатов, могущих заинтересовать Лигу Исследователей." }, { 10.69, "Единственный примечательный инцидент произошёл возле Золотого Пути." }, { 15.60, "Вдали я заметил каких-то странных существ." }, { 18.79, "Наполовину свиньи, наполовину люди – так мне показалось." }, { 22.90, "Я быстро спрятался и дал мерзким животным пройти." }, { 26.56, "Ну и вонь они оставили за собой!" } } } },
    ["2f6c466f"] = { d = 30.9, v = "orc-male", c = { x = { { 0.00, "Джин'Зил!" }, { 0.76, "Прошло немало времени, но я подумал, что ты захочешь узнать, что были убиты последние представители племени Кровавого Пера." }, { 10.27, "Но не благодари меня, убила их та, что доставила тебе это письмо." }, { 15.34, "Если хочешь, я могу прислать тебе её голову, после того как караван пройдёт через Степи." }, { 22.28, "Я знаю, что ты любишь использовать такие вещи в своей магии вуду." }, { 27.41, "Береги себя, старый друг." }, { 29.42, "-Дарсок Быстрый Нож" } } } },
    ["2f6fc9cd"] = { d = 17.0, v = "narrator", c = { x = { { 0.00, "Через несколько лет большая часть Орды перебралась на Азерот, и Гул'дан решил, что настало время нанести сокрушительный удар по человечеству." }, { 10.73, "Орда обрушила всю свою мощь на ничего не подозревающих жителей королевства Штормград." } } } },
    ["2f72fc0f"] = { d = 31.1, v = "narrator", c = { x = { { 0.00, "Лесопилка Альтера стоит у дороги к северо-востоку от Приозёрья, среди сосен на склоне холма." }, { 7.56, "Работа здесь давно остановилась: пилы молчат, брёвна гниют, а по двору бродят гноллы да шныряют пауки." }, { 15.93, "Заброшенное место облюбовали и люди с сомнительной репутацией: старый плут Люций, что проводит дни на пристани Приозёрья, хранит здесь сундук и посылает сюда учеников оттачивать ловкость рук." } } } },
    ["2f7cc967"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Был Астерион, живший среди народа Башал'Арана и много раз отправлявшийся в Амет'Аран, чтобы обеспечить нужды его людей." }, { 10.03, "Итак, оно было на берегах Источника Вечности, города-близнецы росли и процветали, пока мир под звёздами медленно скатывался в безумие." } } } },
    ["2fd89fb3"] = { d = 31.5, v = "narrator", c = { x = { { 0.00, "Королева Азшара, которую магия привела в состояние безумной эйфории, подчинилась невероятному могуществу Саргераса и согласилась пропустить его в свой мир." }, { 11.62, "Перед разлагающим действием магии не устояли даже её служители-высокорожденные, которые начали поклоняться Саргерасу, как богу." }, { 21.20, "Для того чтобы доказать свою верность Легиону, Высокорождённые помогли своей королеве открыть огромный портал в недрах источника Вечности." } } } },
    ["2ffcba82"] = { d = 23.2, v = "dwarf-male", c = { x = { { 0.00, "День первый." }, { 0.94, "Мой танк сломался, но я знаю, что залежи руды хирона – где-то в этих холмах." }, { 6.64, "Я велел Молотоногу оставаться и присматривать за нашими танками." }, { 11.40, "Продолжил поиск в одиночку." }, { 13.48, "Если я не смогу вернуться назад, то журнал останется моим последним завещанием." }, { 19.45, "Бурон Хилдельв, пилот." }, { 21.19, "Паровая бригада Стальгорна." } } } },
    ["3007a27e"] = { d = 67.4, v = "narrator", c = { x = { { 0.00, "Когтистые горы поднимаются между Ясеневым лесом на севере, Степями на востоке и Пустошами на юге." }, { 8.17, "Когда-то здесь были пологие холмы, но Раскол вздыбил песчаник и вознёс к небу острые пики, а ветер и воды Волчьей реки прорезали в камне сеть каньонов." }, { 20.83, "Ветер тут не стихает почти никогда: то бриз с океана, то шквал, поднимающий тучи пыли." }, { 27.94, "Испокон веков горы были родиной гарпий, а Пик Каменного Когтя равно чтили ночные эльфы и таурены: в Третью войну сюда, к Оракулу, приходили и Тралл, и Джайна Праудмур." }, { 42.38, "Ныне гоблины Торговой компании свели лес на Утёсе Ветрорезов и отравили реку, а Обугленная долина выжжена и кишит гарпиями и элементалями." }, { 53.85, "Таурены и орки держат Приют у Солнечного Камня, тролли живут в Малака'джине, ночные эльфы укрепились на Пике, а на юго-востоке бесчинствует племя Зловещего Тотема." } } } },
    ["30084621"] = { d = 25.3, v = "human-male", c = { x = { { 0.00, "Алекстраза:" }, { 0.86, "Алекстраза, древняя и могущественная царица драконов, была названа титанами Связующей Жизнь." }, { 7.58, "Её первую создали титаны для защиты мира после их ухода." }, { 11.79, "Говорят, что она видела зарождение всех народов в мире Азерота." }, { 16.47, "Предводительствуемые ею красные драконы, известные своим гордым нравом, некогда правили всем остальным драконьим племенем." } } } },
    ["30130950"] = { d = 45.3, v = "narrator", c = { x = { { 0.00, "Дольный Очаг стоит на севере Чумных земель и выглядит удивительно мирно посреди отравленного края." }, { 7.90, "Некогда это была столица княжества, которым правил паладин Тирион Фордринг, а во Вторую войну его стены так и не покорились Орде." }, { 18.30, "В Третью войну сюда пришло заражённое зерно из Андорала, и город устоял лишь потому, что принц Артас с Утером Светоносным отбили осаду Плети." }, { 29.48, "Теперь за стенами хозяйничает Алый орден, а командует им верховный лорд Таэлан Фордринг, сын Тириона." }, { 37.46, "Чужаков крестоносцы встречают сталью, и разведчики Альянса и Орды наблюдают за городом лишь издалека." } } } },
    ["302af387"] = { d = 38.6, v = "narrator", c = { x = { { 0.00, "Катакомбы Утреннего Леса тянутся под кладбищем Вороньего холма, и в них обитает самая опасная нежить Сумеречного леса." }, { 9.86, "Внутрь ведут два мавзолея: восточный открывается в логово вурдалаков и распространителей чумы, самых заразных и свирепых, а западный – в залы, где скелеты-налётчики, скелеты-лекари и скелеты-хранители стерегут гробницы своих собратьев." }, { 29.14, "Ночной дозор и Свен посылают сюда лишь тех, кто уже доказал свою силу, и спускаться в темноту лучше не в одиночку." } } } },
    ["303f6fd9"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Долина ядовитых пауков лежит на востоке Тирисфаля, к югу от Монастыря Алого ордена." }, { 6.80, "Прежде здесь охотились на оленей и кроликов среди зелёных деревьев, теперь же долина отравлена и кишит ядовитыми пауками, давшими ей новое имя." }, { 18.29, "Аптекари Брилла ценят яд здешних злобных ночных кругопрядов." }, { 23.21, "В северной части долины бродят псы тьмы, а рядом стоит лагерь Алого ордена." } } } },
    ["30472be2"] = { d = 39.9, v = "narrator", c = { x = { { 0.00, "Сумеречная Излучина — южный отрезок побережья, от Длинного пролива до самого Ясеневого леса." }, { 7.49, "Это самая суровая часть берега: серые пляжи здесь разбиты отвесными скалами, а у южной оконечности в воде разбросаны мелкие островки." }, { 18.33, "На отмелях селятся мурлоки, а в волнах ходят злобные крепкозубы, готовые броситься на любого, кто плывёт к берегу." }, { 27.49, "На одной из отмелей лежат останки исполинского крепкозуба, каких на Тёмных берегах никогда не видели." }, { 35.64, "В глубине суши, за скалами, возвышается Меч Властителя." } } } },
    ["3093ff3c"] = { d = 39.7, v = "narrator", c = { x = { { 0.00, "Тёмный берег тянется вдоль всего северного края Сумеречного леса, по южному берегу реки, за которой лежит Элвиннский лес, от западной границы до моста в Красногорье." }, { 12.95, "На западном конце берега, у самой реки, стоит лагерь Свена и его спутника Ларса – единственных, кто живёт вне городских стен, и именно отсюда чаще всего начинают знакомство с этим лесом." }, { 27.59, "Между холмами и рекой плетут паутину ядовитые кругопряды, а вдоль воды рыщут голодные лютые волки, которые увязываются за каждым, кто несёт добычу в лагерь." } } } },
    ["30a1d09d"] = { d = 24.7, v = "human-male", c = { x = { { 0.00, "Сейчас я прошу Его Величество помочь в эти трудные времена добрым гражданам Озёр." }, { 5.81, "Нам нужны люди для защиты нашей земли и боевые орудия взамен разрушенных на поле боя." }, { 11.93, "Запасы еды и питья истощились." }, { 14.14, "Умоляю, государь, окажите нам поддержку в защите последнего бастиона на пути ненавистных орков!" }, { 20.82, "Враг должен быть изгнан за пределы королевства Штормграда!" } } } },
    ["30f8d0e3"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Титаны наделили силой многие расы, чтобы те смогли помочь им придавать миру форму." }, { 6.60, "Для создания бездонных подземных пещер титаны сотворили дворфоподобных существ из магического живого камня." }, { 14.95, "Чтобы помочь им осушить моря и поднять землю над уровнем моря, титаны создали огромных, но кротких морских великанов." }, { 24.22, "Многие столетия титаны придавали форму землям, пока не смогли сотворить совершённый континент." } } } },
    ["311c515e"] = { d = 40.5, v = "narrator", c = { x = { { 0.00, "Водопад Отравленной Крови шумит в самом центре леса, и от него берут начало все отравленные воды этих мест." }, { 9.17, "Когда-то его питали чистые родники, а теперь из земли сочится ядовитая жижа и падает с уступа в бурлящий зеленоватый омут." }, { 19.64, "Ночные эльфы говорят, что глоток этой воды убивает, а брызги жгут, словно кислота." }, { 26.69, "У воды копошатся слизнюки и ядовитые ужасы, рождённые самой порчей, и сколько их ни истребляй, меньше не становится." }, { 36.39, "К северу от водопада начинается долина Рваных Ран." } } } },
    ["311eb48b"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Нер'зул и его последователи оказались в Круговерти Пустоты, астральной среде между мирами, разбросанными по Великой запредельной тьме." }, { 10.60, "К несчастью, там его поджидал Кил'джеден со своими воинами-демонами." }, { 16.04, "Кил'джеден, поклявшийся отомстить Нер'зулу за его неповиновение, медленно терзал старого шамана, разрывая на части его тело." } } } },
    ["3121a6dd"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Развилка Расщеплённого Копья – место, где единственная дорога через Болото Печали расходится надвое." }, { 7.95, "Северная ветка ведёт мимо Убежища к Болотному пристанищу, южная – к Каменору и дальше, к перевалу в Выжженные земли." }, { 17.19, "У развилки стоит старая орочья сторожевая башня, а по дороге ходят патрули каменорских рубак, так что путникам Альянса здесь стоит быть настороже." } } } },
    ["31a8cb6d"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Тыквенная ферма Хмуроброва на севере края — одно из хозяйств, доставшихся Братству Справедливости." }, { 7.41, "Бандиты заняли постройки, а по грядкам вышагивают их механические големы." }, { 12.91, "Фермер Теодор Хмуробров и его жена Верна бежали, но их повозка сломалась на дороге у Владения Янсена." }, { 20.66, "Документ на владение фермой Братство силой отняло у хозяина — чтобы потом присвоить землю." } } } },
    ["31fd6103"] = { d = 25.9, v = "gnome-male", c = { x = { { 0.00, "Документы Торговой Компании снаружи шахты..." }, { 3.27, "Я думаю, лежат на каких-нибудь ящиках на нижнем уровне." }, { 7.32, "Удачи, и помни..." }, { 8.62, "Синий заряд – лесопилка" }, { 10.39, "Красный заряд – шахта" }, { 12.02, "А, и уничтожь это письмо, после того как выполнишь своё задание." }, { 16.72, "Хм, может быть мне стоит поискать способ заставить эти штуки самоуничтожаться, после того как их прочитают." }, { 24.50, "Это неплохая идея..." } } } },
    ["32105e5f"] = { d = 29.0, g = 1, v = "orc-male", c = { m = { { 0.00, "Тром-ка, воин." }, { 1.18, "Меня не интересуют твои подвиги – это все дела прошлого." }, { 5.65, "Когда ты последний раз убивал человека?" }, { 8.71, "Наверняка давно." }, { 10.04, "Ты теряешь хватку без дела." }, { 12.20, "Мне нужен напарник." }, { 13.73, "А взамен я дам тебе то, что тебе нужно, – полезную тренировку." }, { 18.54, "Когда до тебя дойдёт, что я дело говорю, – приходи." }, { 22.51, "Я буду ждать тебя под навесом прямо возле Логова." }, { 26.42, "Франг, наставник воинов" } }, f = { { 0.00, "Тром-ка, воин." }, { 1.22, "Меня не интересуют твои подвиги – это все дела прошлого." }, { 5.81, "Когда ты последний раз убивала человека?" }, { 9.04, "Наверняка давно." }, { 10.40, "Ты теряешь хватку без дела." }, { 12.62, "Мне нужна напарница." }, { 14.27, "А взамен я дам тебе то, что тебе нужно, – полезную тренировку." }, { 19.22, "Когда до тебя дойдёт, что я дело говорю, – приходи." }, { 23.31, "Я буду ждать тебя под навесом прямо возле Логова." }, { 27.33, "Франг, наставник воинов" } } } },
    ["32108036"] = { d = 60.3, v = "narrator", c = { x = { { 0.00, "Болотина — холодная сырая низина к северу от Лок Модана, с трёх сторон зажатая горами Каз Модана и открытая морю с запада." }, { 9.68, "Туман стелется по земле, серое небо редко проясняется, а между озёрами и протоками бродят кроколиски, крапчатые ящеры, гноллы и мурлоки." }, { 20.49, "Когда-то здесь стояли крепости дворфов Стальгорна, но войны обратили их в руины, и теперь в топях хозяйничают дикие звери и орки клана Драконьей Пасти, потерявшие Грим Батол." }, { 34.29, "Единственный оплот Альянса в этом краю — Гавань Менетилов, порт на западном берегу, названный в честь короля Теренаса Менетила." }, { 44.32, "С юга в Болотину ведёт перевал Дун Альгаз, с севера — мост Тандола, и обе дороги сейчас неспокойны." }, { 52.15, "На востоке над болотами возвышается запечатанный Грим Батол, к вратам которого не пускают красные драконы." } } } },
    ["323442d2"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "Нам, «Шмыг Инкорпорейтед», неприятно говорить о том, что мы получили несколько жалоб на некоторых жадных охотников за корнями, мало заботящихся о своих милых питомцах и отправляющих их в тёмные, опасные места на поиски корней." }, { 16.55, "Мы не станем мириться с такими безответственными хозяевами, но, желая удовлетворить пожелания клиента, мы выдаём гарантию на каждого проданного шмыгуноса, позволяющую новым владельцам вернуть покупку или получить нового зверька взамен потерянного." }, { 34.77, "Удачной охоты!" } } } },
    ["32411630"] = { d = 21.6, v = "human-male", c = { x = { { 0.00, "Наш первый план уже провалился!" }, { 2.05, "Кулаку удалось поменять распорядок дежурства охранников в тоннелях, но из-за непредвиденного вмешательства некоторых жителей Штормграда объект смог улизнуть прежде, чем нам удалось его поймать." }, { 14.49, "Но мы были готовы к неожиданностям." }, { 16.77, "Сейчас мы действуем по плану два, и всё шло хорошо ещё до засады в Штормграде." } } } },
    ["324aa4b2"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Убежище Шалзару — большая извилистая пещера на северной оконечности Острова Ужаса, к югу от Крепости Оперённой Луны." }, { 9.62, "Здесь, в глубине, обитает лорд Шалзару, повелитель наг клана Гребня Ненависти, и здесь же он изучает найденную им реликвию." }, { 19.60, "Пещера состоит из двух залов, соединённых подводным ходом, и её коридоры стерегут колдуньи и змеиные стражи наг." }, { 28.77, "Генерал Шандриса считает эту нору главной угрозой для Часовых на островах." } } } },
    ["3256e109"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Рудник Подземных Глубин – заброшенная золотая шахта к югу от Златоземья, между фермами Стоунфилдов и Маклуров." }, { 8.63, "Некогда её отбили у орков после Первой войны, а теперь штольни заняло целое племя кобольдов." }, { 15.99, "Они носят с собой золотую пыль и большие свечи, за которые в Златоземье дают неплохую цену." }, { 23.22, "По слухам, где-то в глубине прячется здоровенный кобольд с золотыми зубами." } } } },
    ["32753307"] = { d = 32.6, v = "narrator", c = { x = { { 0.00, "Король Теренас из Лордерона, будучи уверенным, что Нер'зул замышляет новое нападение на силы Альянса, послал свои войска на Дренор, чтобы раз и навсегда покончить с орочьей угрозой." }, { 13.97, "Силы Альянса, ведомые Кадгаром и генералом Туралионом, сошлись с орками среди пылающих земель." }, { 21.24, "Даже с помощью Аллерии из числа Высших эльфов, дворфа Курдрана и опытного воина Даната Кадгар не смог помешать Нер'зулу открыть врата в другие миры." } } } },
    ["3288d404"] = { d = 15.3, v = "human-male", c = { x = { { 0.00, "План два довольно прост, но потребует от нас большего терпения." }, { 4.26, "Нашему сообщнику в Менетиле уже заплачено, и свою работу он выполнил блестяще." }, { 9.78, "Теперь мы наверняка с лёгкостью захватим объект, как только отправимся в плаванье." } } } },
    ["329e244f"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Остров Сардор лежит у западного побережья Фераласа, к северу от Острова Ужаса." }, { 6.17, "На его северной оконечности стоит Крепость Оперённой Луны, а южнее — руины Соларсаля, где обосновались наги." }, { 14.59, "Между ними по лесу бродят волки и водятся гиппогрифы." }, { 18.87, "С материка на остров ходит лодка от пристани на Забытом берегу, и для многих путников Альянса это первая земля Фераласа, на которую они ступают." } } } },
    ["32c2a21b"] = { d = 32.4, v = "narrator", c = { x = { { 0.00, "Эти дикие кочевники, которых притягивала энергия Источника, построили на его безмятежных берегах свои хижины." }, { 8.86, "Со временем космическая энергия Источника изменила племя, сделав его сильным, мудрым и практически бессмертным." }, { 17.79, "Племя стало называть себя \"кальдорай\", что на их родном языке означало \"дети звёзд\"." }, { 24.56, "Прославляя расцвет своего общества, поселенцы воздвигли по берегам озера большие постройки и храмы." } } } },
    ["32c7b0d6"] = { d = 26.6, v = "human-male", c = { x = { { 0.00, "Я хочу, чтобы капитан Кильватель привёл \"Бурун\" к берегу с юго-востока." }, { 4.90, "Мы отправим его команду по суше, когда будет дан сигнал." }, { 8.82, "Этот здоровый увалень, Солёное Копыто, может повести ребят в атаку." }, { 13.47, "На Ревилгазе и Морском Роге я ставлю чёрную метку." }, { 16.90, "Шлите их прямиком на дно моря." }, { 18.98, "А вы, парни, отвечаете за то, чтобы спасти всё, что может пригодиться для нашей затеи с ван Клифом в Мёртвых копях." } } } },
    ["33018b01"] = { d = 20.4, v = "human-male" },
    ["3370595e"] = { d = 25.2, v = "narrator", c = { x = { { 0.00, "«Пьяный дворф» — небольшое дворфийское заведение на юге Болотины, недалеко от дороги к перевалу Дун Альгаз." }, { 8.33, "Здесь гонят и разливают крепкие настойки, и дворфийка за стойкой рада любому гостю, будь он из Стальгорна или из самых дальних краёв." }, { 18.71, "После сырого болота кружка горячительного и сухая крыша кажутся особенно желанными." } } } },
    ["337bdfc1"] = { d = 29.6, g = 1, v = "human-male", c = { m = { { 0.00, "Надеюсь, это письмо дошло до тебя, паладин." }, { 3.12, "Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота." }, { 12.43, "Никогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несёт порчу в наши дома." }, { 19.99, "Меня назначили твоим наставником на первое время." }, { 23.49, "Когда будешь готов, ищи меня в аббатстве Североземья." }, { 27.31, "-Брат Самуэль, наставник паладинов." } }, f = { { 0.00, "Надеюсь, это письмо дошло до тебя, паладин." }, { 3.06, "Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота." }, { 12.17, "Никогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несёт порчу в наши дома." }, { 19.58, "Меня назначили твоим наставником на первое время." }, { 23.00, "Когда будешь готова, ищи меня в аббатстве Североземья." }, { 26.80, "-Брат Самуэль, наставник паладинов." } } } },
    ["33f7ed04"] = { d = 21.2, v = "narrator", c = { x = { { 0.00, "Пещера Тельгена уходит глубоко в горы на юге Болотины." }, { 4.41, "Её ходы кишат ядовитыми пауками, и алхимики говорят, что отрава здесь пропитала саму землю." }, { 11.67, "В глубине залегает редкая руда, ради которой сюда спускаются рудокопы и искатели, несмотря на паутину и шорохи в темноте." } } } },
    ["340602ba"] = { d = 16.9, v = "dwarf-male", c = { x = { { 0.00, "Сэр Эс Джей Эрлгедин принадлежит к знатному людскому роду." }, { 4.05, "Его отец, граф Эрлгедин, славился своей щедростью." }, { 7.66, "Именно граф выступал за улучшение условий труда для Гильдии каменщиков во время восстановления Штормграда после Второй Великой войны." } } } },
    ["342767e7"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Холмы Тандрид лежат в южной части Дун Морога, к западу от карьера Гол'Болар." }, { 6.24, "Здесь водятся снежные леопарды, скальные вепри и ледолапые медведи, и без оружия сюда лучше не ходить." }, { 14.52, "По холмам рыщут и тролли Мерзлогривы." }, { 17.57, "Иные путники срезают через эти холмы путь из Холодной долины на восток, но дорога через Каранос куда безопаснее." } } } },
    ["3493e5dc"] = { d = 13.4, v = "narrator", c = { x = { { 0.00, "Хартал Проницательный." }, { 1.82, "Предводитель паладинов Алого ордена." }, { 4.80, "Гражданин Азерота – рыцарь Серебряной Длани." }, { 8.43, "Последний раз был замечен входящим в проклятый город Стратхольм." } } } },
    ["34d37e73"] = { d = 36.1, v = "nightelf-male", c = { x = { { 0.00, "Брат Хаалиен!" }, { 1.09, "Пора доказать свою преданность Ал'акету." }, { 4.43, "Иди в Теневейный лес и найди там столп." }, { 7.55, "Ты докладывал о своих опасениях по поводу друидов, и высшая ложа ордена оценила твою проницательность." }, { 15.83, "Возьми верных солдат и исполни этот благородный долг." }, { 20.19, "Убей друидов как можно скорее, дабы они не расстроили наши планы." }, { 25.63, "Наши глаза и уши в Валанааре подтвердят, когда дело будет сделано." }, { 31.15, "Час возмездия настал!" }, { 32.89, "Никто не остановит рассвет новой эры!" }, { 36.01, "Н." } } } },
    ["34dbb356"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Страх и решимость Артаса привели его к погибели." }, { 4.13, "Он желал уничтожить угрозу своей земле и ради этого добрался до источника чумы в Нордсколе, но сам пал жертвой могущества Короля-лича." }, { 15.61, "Надеясь спасти свой народ, Артас взял в руки проклятый рунный клинок, Ледяную Скорбь." } } } },
    ["34f98c0a"] = { d = 41.0, v = "narrator", c = { x = { { 0.00, "Железнолесье раскинулось на севере леса, между водопадом Отравленной Крови и горами." }, { 7.09, "Когда-то это была тихая роща, а теперь по ней бродят обезумевшие древни-криводревы, топотуны и бродяги Железнолесья и ядовитые ужасы." }, { 18.33, "Здесь окаменели трое древних — Хастат, Стома и Вартус, великие живые деревья ночных эльфов: они стоят среди руин на юге, и, по слухам, дух их не угас." }, { 31.09, "Говорят, если заиграть в этих руинах на флейте сатира, можно призвать духов осквернённых Дерев, что когда-то здесь жили." } } } },
    ["353fcccc"] = { d = 53.0, v = "narrator", c = { x = { { 0.00, "Забытый Город — колоссальные руины в самом сердце Фераласа." }, { 4.95, "Двенадцать тысяч лет назад тайный орден чародеев Высокорождённых построил здесь город Эльдре'Талас, чтобы хранить самые ценные секреты королевы Азшары." }, { 17.36, "Раскол не сумел разрушить его: принц Тортелдрин и его приближённые, Шен'дралар, сплели заклятие, укрывшее город, а потом, лишившись Источника Вечности, заточили демона и стали тянуть из него силу." }, { 33.46, "Когда пленник ослаб, принц обратил магию против собственных подданных, и от Шен'дралар осталась лишь горстка." }, { 42.40, "Ныне восток руин держит сатир Алззин Перевёртень, север — огры клана Гордок, а на западе среди призраков всё ещё бродит сам принц." } } } },
    ["355d9635"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Совет Луносвета, правивший эльфами Кель'Таласа, заключил секретный пакт с магократами, владыками Даларана." }, { 8.21, "Эльфы рассказали лордам-магам об истории древнего Калимдора и Пылающем Легионе, который всё ещё угрожал миру." }, { 16.78, "Они сообщили людям, что, пока те используют магию, им придётся защищать своих граждан от коварных посланцев Легиона." } } } },
    ["3568e860"] = { d = 9.6, v = "creature/ogre" },
    ["357ab1cc"] = { d = 17.3, v = "narrator", c = { x = { { 0.00, "Король Ллейн рассказал об этом Андуину Лотару, последнему потомку рода Арати, которого он сделал своим военачальником." }, { 9.20, "Но никто из них не мог предположить, что беда, случившаяся с Медивом, станет причиной столь ужасных событий." } } } },
    ["358c8048"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Орки и люди, враждовавшие не одно поколение, не хотели и слушать его." }, { 5.70, "Медиву пришлось общаться с каждой расой по отдельности, обманом заставить их пересечь море и ступить на легендарную землю Калимдора." }, { 16.44, "Вскоре орки и люди обнаружили скрывавшуюся долгое время цивилизацию калдорай." } } } },
    ["35a3f006"] = { d = 17.9, v = "narrator", c = { x = { { 0.00, "Возвышенность Гэвина — самый западный из холмов, что выступают из гор к югу, в сторону Хилсбрада." }, { 7.44, "По его травянистым склонам бродят горные львы, а с вершины видно дорогу от Южнобережья." }, { 14.18, "Тихое место, где о людях напоминает лишь название." } } } },
    ["3659b8ed"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Серая берлога — большая пещера к западу от Караноса, где живут стаи вендиго." }, { 5.96, "Эти косматые твари дышат морозом и набрасываются на чужаков все разом." }, { 11.44, "Дворфы ходят сюда за гривами вендиго: пилот Камнекожец мечтает обить ими кабину своего Троллеукладчика." }, { 19.55, "В глубине пещеры поблёскивают медные жилы, а у входа не так давно вендиго разграбили лагерь курьера с боеприпасами для Хегнара Громострела." } } } },
    ["36623720"] = { d = 25.2, v = "narrator", c = { x = { { 0.00, "Но пять родов главенствовали над своими собратьями." }, { 4.30, "Титаны избрали эти пять стай, чтобы те присматривали за расцветающим миром." }, { 10.68, "Величайшие члены Пантеона отдали часть своей силы каждому из лидеров стай." }, { 17.06, "Эти магические драконы (указанные ниже) стали известны как Великие аспекты или Великие драконы." } } } },
    ["36b59bf4"] = { d = 35.3, v = "narrator", c = { x = { { 0.00, "Кладбище кодо — широкая котловина в сердце Пустошей, куда испокон веков приходят умирать старые кодо." }, { 8.21, "Никто не знает почему, но огромные скелеты лежат здесь повсюду, наполовину засыпанные серой пылью, и многие принадлежат исполинам, каких ныне уже не встретишь." }, { 20.93, "Между костями бродят изнурённые кодо, а на слабых слетаются падальщики." }, { 26.57, "Говорят, духи павших зверей не покидают этих мест, и тот, кто тревожит их кости, может увидеть призрачных кодо." } } } },
    ["36df7378"] = { d = 65.8, v = "narrator", c = { x = { { 0.00, "Внутренние земли — лесистый горный край на востоке Лордерона, между нагорьем Арати и Чумными землями, обрывающийся на востоке в Зловещее море." }, { 11.15, "Когда-то здесь билось сердце империи Амани, и руины троллей до сих пор стоят среди сосен и папоротников." }, { 19.34, "После войны Трёх Кланов сюда пришли дворфы клана Громового Молота: они построили Заоблачный Пик над землёй и приручили местных грифонов." }, { 30.06, "Лесные тролли считают дворфов захватчиками: племя Порочной Ветви держит древний Джинта'Алор и Алтарь Зула, Сухокожие живут у храмов Шадра'Алора, а малое племя Сломанного Клыка, вставшее на сторону Орды, укрылось в деревне на побережье." }, { 48.62, "На западе, в сторожке Кель'Данил, держатся высшие эльфы, а на севере растёт великое древо Серадан с порталом в Изумрудный Сон." }, { 58.43, "В лесах между ними бродят волки, медведи и совухи, и путник здесь редко остаётся один надолго." } } } },
    ["36f3c408"] = { d = 11.0, v = "narrator", c = { x = { { 0.00, "Сначала он воззвал к Выводку Изеры." }, { 3.20, "Меритра из Сна ответила на его зов, и затем весть дошла до выводков Алекстразы и Малигоса." } } } },
    ["371662ea"] = { d = 19.6, v = "human-male", c = { x = { { 0.00, "РЕКОМЕНДАЦИЯ:" }, { 1.00, "Носитель данного документа, послуживший Североземью с рвением и отличием, должен быть награждён званием делегата в армии Штормграда." }, { 10.64, "Я уверяю вас, что вы найдёте его полезным в Элвиннском лесу." }, { 15.03, "Подпись:" }, { 15.69, "Маршал Дуглас Макбрайд," }, { 17.49, "Армия Штормграда, Североземья." } } } },
    ["3727934b"] = { d = 28.4, v = "human-male" },
    ["3741ff60"] = { d = 21.9, v = "narrator", c = { x = { { 0.00, "Северные врата — перевал на северо-востоке Дун Морога, ведущий в Лок Модан." }, { 5.72, "Через него идут те, кто направляется к Болотине, ведь этот путь ближе всего к спуску с озера." }, { 12.80, "На перевале стоит застава горных пехотинцев." }, { 16.21, "Дорога вьётся между заснеженных скал, и в стороне от неё бродят опасные звери." } } } },
    ["37457ac1"] = { d = 32.5, v = "narrator", c = { x = { { 0.00, "Долина Высокого леса лежит в предгорьях на востоке, там, где Когтистые горы спускаются к Степям." }, { 7.85, "Среди редких сосен здесь ещё сохранился настоящий лес, и именно через эту долину идёт дорога с Перекрёстка." }, { 16.50, "У её края стоит лагерем шаманка Орды Сирит Камнелом, слышащая стенания духов этих гор." }, { 23.69, "Но покоя в долине нет: по ней рыщут отступники племени Зловещего Тотема, разорившие соседнюю деревню тауренов." } } } },
    ["3756362e"] = { d = 14.6, v = "human-male", c = { x = { { 0.00, "Ульдаман, День шестой" }, { 1.67, "…страшно есть хочется." }, { 3.40, "У меня кончились припасы, я полагаю, придётся доедать заплесневелый хлеб." }, { 8.95, "Голова проходящего мимо трогга на моих глазах превратилась в сочный стейк…" } } } },
    ["37666140"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Без вести пропавший: капрал Кеешан" }, { 2.62, "В последний раз его видели во время кровавого сражения за Башню Каменной Стражи, из докладов стало известно, что его утащили орки Чёрной Горы." }, { 13.29, "Полагают, что он содержится в плену в качестве военного заложника в лагере Чёрной Горы, севернее Приозёрья, южнее дороги, ведущей в Пылающие степи." }, { 24.17, "В соответствии с приказом мирового судьи Соломона – любому, кто поможет спасти капрала Кеешана, будет выдана награда маршалом Маррисом." } } } },
    ["3769c9c6"] = { d = 35.1, v = "narrator", c = { x = { { 0.00, "После долгих лет странствий высшие эльфы, наконец, нашли земли, напоминавшие Калимдор." }, { 6.73, "В глуши северных лесов они основали королевство Кель'Талас и поклялись создать могущественную империю, которая будет во всём превосходить цивилизацию их собратьев, кальдорай." }, { 20.06, "К сожалению, эльфы вскоре узнали, что основали Кель'Талас на развалинах древнего города троллей, который те до сих пор считали священным." }, { 30.55, "Тролли почти сразу же начали атаковать эльфийские поселения." } } } },
    ["37847f11"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Кенарий жил на священных Лунных полянах на горе Хиджал." }, { 4.19, "Он согласился помочь ночным эльфам, найти древних драконов и обратиться к ним за помощью." }, { 10.88, "Драконы, в свою очередь, тоже решили не оставаться в стороне и, ведомые исполинской красной Алекстразой, отправились на войну с демонами и их адскими предводителями." } } } },
    ["3798327b"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Онейрос — руины ночных эльфов к югу от Нефритового озера, заросшие лианами и мхом." }, { 6.78, "Само их имя созвучно древнему слову о снах, и не случайно: между колонн здесь патрулируют зелёные драконьи отпрыски, стражи Дремлющей Изеры." }, { 18.20, "Они не терпят чужаков, и путнику лучше обходить разрушенные арки стороной." } } } },
    ["379c29a1"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Каменная Плотина перегородила северную оконечность озера и вдвое увеличила его размеры, а излишки воды превратили низины Болотины в топи." }, { 10.62, "Дворфы считают её одним из чудес света, хотя мало кто помнит, что способ каменной кладки для неё придумал зодчий из клана Чёрного Железа." }, { 21.18, "Ныне плотину охраняют хуже прежнего: большая часть стражи ушла воевать за Альянс, а по восточной стороне дамбы всё чаще крадутся дворфы Чёрного Железа, и главному инженеру не до сна." } } } },
    ["37af1856"] = { d = 10.6, v = "human-male", c = { x = { { 0.00, "Торговая компания..." }, { 1.59, "Неразборчиво." }, { 2.63, "Похоже, эти глупцы сорвали всю свою операцию в попытке стабилизировать зелье." }, { 8.64, "Несколько страниц вырвано." } } } },
    ["38202186"] = { d = 36.4, v = "narrator", c = { x = { { 0.00, "Лагерь Таурахо — стойбище охотников-тауренов на Золотом Пути к югу от Перекрёстка." }, { 6.77, "Здесь Джорн Заклинатель Небес учит молодых следопытов читать следы великих зверей Степей — Ишамухала, Лакота'мани, Оватанки и Ваште Пауни." }, { 18.24, "Лагерь живёт в вечной осаде свинобразов: дозорные не спускают глаз с холмов, а в клетке у частокола сидит пленный Кривозуб из племени Иглогривых, охотно делящийся силой Агамаггана с теми, кто приносит ему кровавые осколки." } } } },
    ["382e04a8"] = { d = 36.6, v = "narrator", c = { x = { { 0.00, "Деревня Колючего Меха стоит прямо к северу от Астранаара, у дороги, что огибает город." }, { 6.55, "Здесь живёт племя фурболгов Колючего Меха, поражённое порчей: они нападают на всякого, кто подойдёт слишком близко." }, { 15.05, "Разведчики Раэны Волкопас доносят, что за последние месяцы фурболги чрезвычайно умножились числом, и Астранаар боится их набега." }, { 24.63, "Орде деревня тоже мешает, преграждая дорогу к заставе Расщеплённого Дерева." }, { 30.30, "В глубине пещер фурболги держат в клетке таурена Руула, которого приняли за медведя." } } } },
    ["383cc6b9"] = { d = 34.3, v = "orc-male", c = { x = { { 0.00, "Приветствую тебя." }, { 1.43, "Я был погружён в размышления, когда мне в голову пришла мысль тебе написать." }, { 7.37, "Многие наши соплеменники считают духовными лидерами шаманов, подобных нашему Вождю." }, { 14.09, "Другие предпочитают поклоняться мечу и топору." }, { 17.81, "Но не стоит забывать, что на исход битв и даже целых войн влияют совсем другие силы." }, { 24.53, "Вот об этом я и хочу поговорить с тобой." }, { 27.75, "Ты можешь найти меня в Логове, что в Долине Испытаний." }, { 32.11, "-Руаг, наставник разбойников." } } } },
    ["38483911"] = { d = 27.9, v = "narrator", c = { x = { { 0.00, "Восточное побережье — полоса пляжей к юго-востоку от Южнобережья, между городом и холмами Дун Гарока." }, { 7.89, "На песке и в прибрежных водах хозяйничают наги: чешуйчатые воины и колдуньи выходят из моря и стоят лагерем прямо у кромки воды." }, { 17.95, "Рыбакам Южнобережья сюда лучше не соваться, и маршал Редпат неспроста поручил одному из своих людей разобраться с угрозой с моря." } } } },
    ["3854392c"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Руины Звёздной Пыли лежат на юге леса, у гряды, отделяющей Ясеневый лес от Когтистых гор." }, { 7.28, "Древнее святилище ночных эльфов стоит на острове посреди озера; когда-то это было священное место, и в его центре до сих пор бьёт маленький фонтан." }, { 19.40, "Но порча добралась и сюда: вода стала мутной, желтовато-зелёной, и по руинам бродят болотные твари." }, { 27.56, "Лишь кусты звёздной пыли на берегах не тронуты порчей, и лекари ценят собранную с них пыль, способную унять лихорадку." } } } },
    ["38b027a0"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Великое море простирается на запад от берегов Болотины и отделяет Восточные королевства от Калимдора." }, { 8.10, "По его водам из Гавани Менетилов уходят корабли в Аубердин и Терамор." }, { 13.75, "У побережья на дне покоятся суда, потопленные в былые войны, а над волнами кружат чайки и стелется вечный туман." } } } },
    ["38d3124d"] = { d = 43.3, g = 1, v = "tauren-male" },
    ["38e5f845"] = { d = 31.5, v = "narrator", c = { x = { { 0.00, "Деревня Сухокожих раскинулась вокруг небольшого озера на юго-востоке нагорья." }, { 5.87, "Здесь живут лесные тролли племени Сухокожих, а в большой пещере за деревней собираются их вожди и знахари." }, { 13.84, "Тролли заключили союз с ограми клана Тяжёлого Кулака и вместе с ними удерживают часть Стромгарда." }, { 21.13, "Небольшие отряды Сухокожих то и дело выходят из деревни и бегут по дороге к воротам Павшего Молота, чтобы испытать на прочность его стражу." } } } },
    ["390beb4b"] = { d = 23.8, v = "orc-male", c = { x = { { 0.00, "Вурмталак!" }, { 0.99, "Твой господин Нефариан дал мне повеление наказать тебя так, как я посчитаю нужным, если ещё хоть кто-нибудь проберётся внутрь крепости." }, { 13.08, "Не забывай, кому ты подчиняешься, рептилия." }, { 17.05, "Сыну Чернорука: Мастеру меча и битвы." }, { 20.61, "Единственному истинному Вождю." }, { 23.43, "-Ренд" } } } },
    ["392bcbac"] = { d = 32.5, v = "narrator", c = { x = { { 0.00, "Торговое побережье — полоса берега Великого моря на востоке Степей, названная так за прибыльную торговлю гоблинов Кабестана." }, { 9.75, "Здесь стоят и сам порт, и крепость Северной Стражи, а у самой воды догнивает остов разбитого корабля." }, { 17.66, "Южнее Кабестана разбили лагерь флибустьеры Южных морей: их канониры и головорезы грабят суда, а капитан «Безрассудной» барон Дольноберег объявлен в розыск." }, { 29.88, "Напротив берега лежит Остров Битв." } } } },
    ["3940bbab"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "Лощина Бен'этиль — тесное ущелье к югу от дороги, соединяющей Доланаар с Дарнассом." }, { 6.77, "Здесь собралось больше всего фурболгов Кривой Сосны на острове; время от времени они выходят из лощины и нападают на путников." }, { 17.03, "В глубине ущелья скрыт вход в обитель Бен'этиль, где покоятся спящие друиды." }, { 23.14, "Часовые назначили награду за клыки этих фурболгов, ибо Скверна лишила их рассудка." } } } },
    ["395d7006"] = { d = 31.6, v = "narrator", c = { x = { { 0.00, "Южные степи — самая дальняя и глухая часть края, где сухая трава сменяется колючими зарослями." }, { 7.77, "Здесь лежат владения свинобразов: Хребет Чёрных Шипов и Лабиринты Иглошкурых, где сходятся тропы племён Иглогривых и Дыбогривов." }, { 18.04, "С юга к равнине подступают дворфы Бейл Модана, а дорога сворачивает к Великому Подъёмнику и Тысяче Игл." }, { 26.33, "Форпостов Орды здесь нет, и путник может рассчитывать лишь на себя." } } } },
    ["3964b0c7"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Ферма Гроль'дома — орочье хозяйство на Золотом Пути к северу от Перекрёстка." }, { 5.71, "За частоколом здесь держат кодо, а вокруг пасётся скот — небогатая, но упорная попытка орков прокормиться на сухой земле." }, { 14.76, "Слишком близко от фермы лежит Тернистый холм, и свинобразы Иглогривых не раз спускались сюда за добычей." }, { 22.58, "Неподалёку у дороги стоит Кранал Фисс, направляющий бойцов на север, к заставе Мор'шан." } } } },
    ["39a4f09f"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Внезапное предательство Смертокрыла повлекло за собой столь губительные последствия, что остальные драконы так никогда и не смогли оправиться от потрясения." }, { 11.71, "Израненная и убитая горем Алекстраза и её пятеро собратьев покинули поле боя, оставив своих смертных союзников один на один с многократно превосходящей их армией демонов." }, { 24.81, "Малфуриону и его соратникам едва удалось выжить в последовавшем натиске." } } } },
    ["39b1b1cf"] = { d = 38.9, v = "narrator", c = { x = { { 0.00, "Леса Ночной Песни — восточная часть Ясеневого леса, от Приюта в Ночных Лесах и дороги в Осквернённый лес до самой Азшары." }, { 9.70, "Именно здесь идут самые жаркие бои между Ордой и Альянсом: река Фалфаррен делит эти леса на западную половину, где стоят эльфы, и восточную, где хозяйничает клан Песни Войны." }, { 23.90, "Дальше на восток за землю спорят сатиры Сатирнаара и Ксавиана, лесозаготовки орков и демоны Холма Демонического Огня." }, { 33.38, "Южные чащи здесь заметно поредели: орки вырубили их для своих строек." } } } },
    ["39c30831"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Потайная тропа — скрытый путь через горы, окружающие Долину Испытаний." }, { 5.74, "Начинающие шаманы должны отыскать его сами, чтобы подняться к Священному Камню." }, { 12.27, "С самой высокой точки тропы открывается вид на Степи." }, { 16.63, "Тропа известна немногим, и для большинства новичков она так и остаётся тайной." } } } },
    ["39db3315"] = { d = 18.2, v = "human-male", c = { x = { { 0.00, "Пребывание в брюхе великана способствует размышлению." }, { 4.02, "Пока моё тело кристаллизовалось, я пришёл к выводу, что, возможно, в этом мире достаточно героев." }, { 11.31, "Если я как-нибудь отсюда выберусь, я здорово врежу этому орку по призрачной шее!" }, { 17.50, "-Уинден Шей" } } } },
    ["3a267ba7"] = { d = 36.9, v = "narrator", c = { x = { { 0.00, "Побережье Сар'Терис — полоса берега вдоль всего западного края Пустошей." }, { 5.98, "В отличие от серых внутренних земель, здесь светит солнце и зеленеет трава, а волны Сокрытого Моря набегают на песок." }, { 15.64, "Но берег небезопасен: у воды хозяйничают наги и морские великаны, в прибое роются макруры, а по холмам гуляют смерчи." }, { 25.30, "У северной части побережья лежат обломки корабля Карнитола, разграбленного нагами, а на юге берег выводит к рыбацкой Деревне Ночных Охотников." } } } },
    ["3a6696db"] = { d = 25.1, v = "narrator", c = { x = { { 0.00, "Кел'Тузад оставил учение Кирин-Тора и навсегда покинул Даларан, отказавшись от всех своих богатств и высокого положения в обществе." }, { 10.07, "Повинуясь голосу Короля-лича, звучащему в его мыслях, он продал всё, что у него было, и спрятал свои богатства." }, { 18.74, "Он проделал долгий путь по суше и морю – и наконец достиг ледяных берегов Нордскола." } } } },
    ["3a66a1d9"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Деревня Гелкис — поселение кентавров на юге Пустошей, кольцом обступившее ущелье у дороги на Фералас." }, { 8.52, "Утёсы внутри ущелья соединены мостами и ведут к Пещере Болгана, где укрылся вождь Шак." }, { 15.68, "Гелкис — самое разумное из племён: они чтут землю и свою мать Терадрас, их шаманы слышат голос камня, и они знают общий язык." }, { 26.30, "Их извечные враги — Маграм, и ради победы Гелкис готовы принять чужака, доказавшего дружбу кровью врага." } } } },
    ["3a6a210e"] = { d = 33.7, v = "narrator", c = { x = { { 0.00, "Ведьмин холм поднимается над болотом на полпути от Степей к Терамору, и дурная слава его не случайна: по склонам бродят зомби и беспокойные духи, а ночью среди могил мерещатся тени." }, { 14.60, "Люди Терамора не знают, откуда взялась эта скверна; шепчутся, что над холмом тяготеет чья-то злая воля." }, { 23.06, "У подножия расположились стойбища мурлоков, а на вершине стоит сторожка отшельника, который упрямо не желает покидать проклятое место." } } } },
    ["3a7ba2d9"] = { d = 23.1, v = "narrator", c = { x = { { 0.00, "Южные врата — перевал, ведущий из высоких гор Дун Морога вниз, к озеру Лок Модан." }, { 6.80, "Этим путём чаще всего ходят в Телсамар и обратно." }, { 11.03, "Посреди перевала стоит сторожевая застава горных пехотинцев." }, { 16.17, "Снег здесь лежит до самой границы, а дальше начинаются более тёплые холмы Лок Модана." } } } },
    ["3a7f250f"] = { d = 20.7, v = "tauren-male", c = { x = { { 0.00, "*Призыв на службу в Орду*" }, { 2.00, "." }, { 2.15, "Этот человек показал невероятные достижения силы и навыка во имя Орды." }, { 8.36, "Его следует немедленно назначить на работу в Перекрёсток." }, { 13.16, "*С глубоким почтением,*" }, { 15.20, "Мне кажется, неплохо." }, { 17.66, "- Такрин Торитель Путей" } } } },
    ["3a7f43af"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "На западном краю Выжженных земель стоит Алтарь Бурь — мрачное святилище, какие возводили в дни Второй войны, чтобы превращать бездумных великанов в огров-магов." }, { 13.06, "Этот алтарь построила одна из слуг Разелиха Осквернителя, и вокруг него по сей день собираются Приверженцы Тени и их демонические подручные." }, { 24.29, "Сюда же приходят чернокнижники, готовые заплатить кровью и золотом за ритуал призыва коня погибели." }, { 32.39, "Ветер над алтарём пахнёт серой." } } } },
    ["3a912801"] = { d = 10.8, v = "human-male" },
    ["3abb2221"] = { d = 18.8, v = "narrator", c = { x = { { 0.00, "Руины Кал'аи — полузатопленные троллиные развалины на побережье северной части долины." }, { 6.94, "Море давно поглотило нижние ярусы города, и в них поселилось племя мурлоков." }, { 13.17, "Их бормотание разносится над водой среди обломков былой славы Гурубаши." } } } },
    ["3ac45788"] = { d = 20.7, v = "narrator", c = { x = { { 0.00, "Алекстраза красная, Изера зелёная и Ноздорму бронзовый опустились на тихие поляны ночных эльфов и посмотрели на плоды их трудов." }, { 10.82, "Малфурион, ставший могущественным верховным друидом, поприветствовал драконов и рассказал им о новом Источнике Вечности." } } } },
    ["3ade48c2"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Зеркальное озеро – небольшое озеро в западной части Элвинна, к юго-западу от врат Штормграда, с красивым водопадом на северном берегу." }, { 10.10, "Оно могло бы стать славным местом для рыбалки и купания, если бы не бандиты Братства Справедливости, что заняли сад на его берегу." }, { 19.87, "Маги Штормграда опасаются, что после недавних магических потрясений течение волшебных потоков изменилось, и присматриваются к здешней воде." } } } },
    ["3ae8efe5"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "Святилище — уголок разрушенного Стромгарда, который до сих пор удерживают верные королевству солдаты." }, { 7.62, "Здесь держит свой штаб принц Гален Троллебой, наследник павшего дома, а вокруг стоят последние защитники столицы." }, { 16.20, "Отсюда рукой подать до склепа Троллебоев, где заперт Трол'калар, а печати от его гробницы разделены между надёжными людьми." }, { 25.60, "Пока Синдикат и огры делят остальной город, в Святилище ждут дня, когда над Стромгардом снова взовьётся королевское знамя." } } } },
    ["3b16e517"] = { d = 28.4, v = "orc-male", c = { x = { { 0.00, "*Как очистить луковицу Подробное руководство по сражению с Грозовой Вершиной Написано Дрек'Таром*" }, { 8.32, "На этих страницах читатель найдёт обширные сведения о политике и боевой тактике." }, { 15.09, "Хороший солдат – это тот солдат, что понимает важность накопленного опыта." }, { 21.40, "Пусть же эта книга послужит читателю руководством по сражению за Альтеракскую Долину." } } } },
    ["3b1a4de4"] = { d = 18.3, v = "human-male", c = { x = { { 0.00, "...я более чем уверен, что она испытывает те же чувства, что и я." }, { 4.46, "Она даже взяла меня за руку сегодня утром." }, { 7.60, "Когда она смеётся, её глаза сверкают как бриллианты." }, { 11.24, "Столько невысказанных слов между нами." }, { 13.94, "Моё сердце стучит, как сумасшедшее, и огонь разливается по венам." } } } },
    ["3b1f78c3"] = { d = 23.8, v = "human-male", c = { x = { { 0.00, "Азерот – страна нескончаемых чудес." }, { 2.94, "Здесь многообразно всё – флора, фауна, культура, магия." }, { 7.43, "Жаждущий знаний может многое здесь найти." }, { 10.89, "Надо лишь внимательно смотреть." }, { 13.47, "И если заглянуть достаточно глубоко, то увидишь окна в новые миры, в каждом из которых есть свои чудеса." }, { 22.08, "А есть и свои бедствия." } } } },
    ["3b2e0ce5"] = { d = 34.6, g = 1, v = "scourge-male", c = { m = { { 0.00, "Рад, что твоя душа не попала в Пустоту." }, { 3.57, "Я полагаю, ты стоишь усилий, затраченных на написание этого свитка." }, { 9.65, "Помни: людей, которых ты знал и любил, больше нет в живых!" }, { 14.93, "Ты должен пронести этот груз через всё своё дальнейшее существование." }, { 21.09, "Советую тебе смириться с этим с самого начала." }, { 25.39, "Если ты готов к испытаниям, найди меня в церкви Могильника." }, { 30.83, "- Тёмный священник Дьюстен, наставник жрецов" } }, f = { { 0.00, "Рад, что твоя душа не попала в Пустоту." }, { 3.49, "Я полагаю, ты стоишь усилий, затраченных на написание этого свитка." }, { 9.43, "Помни: людей, которых ты знала и любила, больше нет в живых!" }, { 14.82, "Ты должна пронести этот груз через всё своё дальнейшее существование." }, { 20.85, "Советую тебе смириться с этим с самого начала." }, { 25.05, "Если ты готова к испытаниям, найди меня в церкви Могильника." }, { 30.44, "- Тёмный священник Дьюстен, наставник жрецов" } } } },
    ["3b4e173b"] = { d = 15.8, v = "narrator", c = { x = { { 0.00, "Озеро Тихого Ветра — небольшая заводь в чаще Фераласа, о которой почти не говорят на картах." }, { 7.77, "Воздух здесь и вправду неподвижен: ни ветра, ни птичьих криков, лишь плеск воды под тяжёлыми ветвями." } } } },
    ["3b63fc15"] = { d = 37.0, v = "human-male", c = { x = { { 0.00, "Привет тебе, Элло Чернодрев, мэр Темнолесья." }, { 3.48, "Боюсь, у меня плохие вести для вашего города." }, { 7.09, "Видишь ли, я создатель." }, { 8.90, "Я обманом заставил того, кто доставил это письмо, помочь мне в создании моего последнего, самого ужасного творения – демона из плоти, костей и металла!" }, { 20.65, "Когда ты читаешь эти строки, он находится рядом с моим скромным жилищем, скрежеща зубами." }, { 27.67, "Одно моё слово – и он начнёт убивать и крушить всё на своём пути." }, { 32.60, "И в скором времени вы испытаете это на себе." }, { 36.08, "Бальзамировщик" } } } },
    ["3b642004"] = { d = 19.8, v = "tauren-male", c = { x = { { 0.00, "*Призыв на службу в Орду Этот человек показал невероятные достижения силы и навыка во имя Орды.*" }, { 8.20, "*Его следует немедленно назначить на работу на Перекрёсток.*" }, { 13.10, "*Почтительно ваш:*" }, { 14.40, "Мне кажется, неплохо." }, { 17.05, "- Такрин Торитель Путей" } } } },
    ["3b6b3ec8"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Одинокая вершина — гора на юго-западе Азшары, что возвышается над окрестными холмами." }, { 7.04, "Её склоны видны отовсюду, и от тихих лесов у её подножия веет покоем, редким для этой земли." }, { 14.83, "Говорят, в кольце её хребтов скрыт огромный кратер, куда путникам нет дороги." } } } },
    ["3b6d4bf2"] = { d = 22.9, v = "tauren-male", c = { x = { { 0.00, "Срочное сообщение для дозорного утёсов Долгорога" }, { 4.30, "Огромные силы кентавров из Лагеря Э'ток напали на один из наших торговых караванов." }, { 11.93, "Все члены каравана были убиты, а весь товар потерян." }, { 16.71, "Это было наглое и беспрецедентное нападение, и, я боюсь, не последнее." } } } },
    ["3b96616f"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Застава Расщеплённого Дерева — главный оплот Орды в Ясеневом лесу, стоящий на восточной дороге." }, { 7.59, "Её основал Гром Адский Крик со своим кланом Песни Войны в дни Третьей войны, когда орки впервые пришли в эти леса." }, { 16.83, "За частоколом живут в основном орки и таурены — разведчики и стражи; есть таверна и ветрокрылы для полётов." }, { 25.21, "Отсюда Сенани Громосерд отправляет молодых охотников на Большую охоту за зверями леса." }, { 32.16, "Ночные эльфы помнят дела вождя Песни Войны, и застава нередко подвергается их ударам." } } } },
    ["3bae8678"] = { d = 31.2, v = "dwarf-male", c = { x = { { 0.00, "День первый." }, { 0.89, "Наконец-то я из Стальгорна добрался до Калимдора!" }, { 4.31, "Геолог Хазгорм из Бейл Модана отлично продвигается." }, { 7.91, "Он сегодня раскопал окаменелость, которую местные учёные считают фрагментом кости древнего бога." }, { 14.69, "Хазгорм уверен, что окаменелость – часть великой загадки." }, { 18.68, "Пока он приглядывает за раскопками, но поручил мне найти ещё окаменелостей, чтобы собрать эту историю воедино." }, { 26.40, "Моё задание: отправиться на юг в поисках дополнительных ключей к тайне." } } } },
    ["3bc690c2"] = { d = 9.3, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ." }, { 2.58, "Часть вторая." }, { 4.01, "Центурион." }, { 5.16, "Легионер." }, { 6.21, "Кровавый страж." }, { 7.83, "Каменный Страж." } } } },
    ["3c08fc79"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "Восточный круг Обуздания — кольцо древних камней на востоке нагорья." }, { 5.15, "Это один из четырёх кругов, которыми горные великаны когда-то сковали принцессу земли глубоко под холмами." }, { 13.22, "Восточный камень стерегут элементали воды, и над кругом стоит тихий плеск, словно ручей течёт сквозь сухую траву." }, { 21.77, "Тому, кто попытается подойти к камню, придётся иметь дело с водяным изгнанником, что кружит среди монолитов." } } } },
    ["3c124407"] = { d = 27.4, v = "dwarf-male", c = { x = { { 0.00, "Попытался проучить монстра, но в итоге получил глубокий порез на руке." }, { 5.37, "Похоже, придётся накладывать швы." }, { 7.81, "ТРЕТИЙ ДЕНЬ." }, { 8.77, "Похолодало." }, { 9.65, "Ночью выпало немного снега." }, { 11.82, "ЧЕТВЁРТЫЙ ДЕНЬ." }, { 12.91, "Ученик поправился и пребывает в хорошем расположении духа, поэтому мы рискнули посмотреть на троллей." }, { 20.52, "Судя по отметкам на их коже и различным амулетам, которые они носят, это племя Мерзлогривов." } } } },
    ["3c5f29ed"] = { d = 3.9, v = "narrator", c = { x = { { 0.00, "Дальше страница испещрена нулями и единицами." } } } },
    ["3c781dce"] = { d = 61.9, v = "narrator", c = { x = { { 0.00, "Лок Модан лежит к востоку от Дун Морога, в восточной части Каз Модана." }, { 5.56, "Здесь теплее, чем в заснеженных горах у Стальгорна: серые скалистые хребты обступают долину со всех сторон, а склоны поросли сосной и берёзой." }, { 16.68, "Сердце этих земель — огромное озеро Лок, чьи воды удерживает Каменная Плотина, одно из величайших творений дворфийских зодчих." }, { 26.72, "Край видел немало крови: во Вторую войну орки Орды захватили Лок Модан, и дворфы Стальгорна отвоевали его лишь после долгих боёв." }, { 37.06, "Ныне главную угрозу несут трогги, потревоженные раскопками и расселившиеся по окрестным пещерам, кобольды в старых шахтах и огры клана Мо'грош на северо-восточном берегу." }, { 50.60, "На юге всё чаще замечают дворфов Чёрного Железа." }, { 54.45, "Единственный город здесь — Телсамар, откуда горные пехотинцы несут дозор на дорогах и перевалах." } } } },
    ["3c822d00"] = { d = 30.5, v = "narrator", c = { x = { { 0.00, "Берег Промозглого Ветра — невысокая возвышенность на восточной окраине Альтеракских гор." }, { 7.01, "Здесь стоят древние тролльские руины, а из ущелья с севера, из Западных Чумных земель, задувает ледяной ветер, давший месту имя." }, { 17.41, "Среди камней поселился одинокий тролль из джунглей, миролюбивый мистик, знающий толк в старинных клинках." }, { 25.79, "Дальше на север дорога ведёт прямо к границе Чумных земель." } } } },
    ["3c986874"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Паучья низина — небольшая лощина с золотым рудником к северо-западу от Могильника." }, { 6.61, "И сама долина, и штольни кишат ночными кругопрядами: молодые пауки снуют снаружи, взрослые прячутся в затянутых паутиной углах шахты, а в самой её глубине сидит паучья матка." }, { 20.71, "Отрёкшимся отчаянно нужно здешнее золото, но добывать его нельзя, пока рудник не расчищен, и молодых мертвецов из Могильника посылают сюда испытать свои силы." } } } },
    ["3cb7a7c1"] = { d = 30.1, v = "human-male", c = { x = { { 0.00, "Дела культа, том двести тридцать три" }, { 2.64, "Нам снова выпала редкая возможность, о братья мои и сёстры!" }, { 6.88, "Круг Кенария, мерзостный культ почитателей природы, посылает на нас своих приспешников." }, { 12.99, "Они хотят воспрепятствовать нам добыть красные камни-приманки." }, { 17.49, "Мы не можем этого допустить!" }, { 19.55, "Красные камни очень нужны нашим новым союзникам." }, { 23.15, "Нельзя, чтобы шавки из Круга Кенария добились своего." }, { 27.07, "Держитесь, преданные друзья мои." }, { 29.45, "Держитесь!" } } } },
    ["3ccf68dc"] = { d = 35.7, v = "creature/falstad", c = { x = { { 0.00, "*Курдран Громовой Молот*" }, { 2.00, "." }, { 2.15, "Знаменитый драконобоец." }, { 4.10, "Укротитель грифонов Заоблачного пика." }, { 7.25, "Командир подразделения всадников на грифонах при экспедиции Альянса, которая отправилась в Дренор, родной мир орков." }, { 16.84, "Предположительно погиб." }, { 18.79, "Ветер донесёт до нас клич Скайри." }, { 21.49, "Мы услышим грохот твоего молота по ту сторону гор." }, { 25.69, "Вступай в загробную жизнь без опасений, брат." }, { 29.36, "Залы наших предков ожидают тебя." }, { 32.21, "- Верховный тан Фалстад Громовой Молот" } } } },
    ["3cd1f4ea"] = { d = 43.5, v = "narrator", c = { x = { { 0.00, "Пик Каменного Когтя, высочайшая вершина гряды, издревле священен и для ночных эльфов, и для тауренов." }, { 8.26, "В Третью войну сюда приходили Джайна Праудмур и Тралл, ища в пещерах горы совета Оракула." }, { 16.59, "Ныне в зелёной долине на вершине, среди древних эльфийских руин, стоит единственная застава Альянса в горах: её хранит Хранитель Албагорм, гостей принимает таверна Фаралии, а гиппогрифы уносят путников в Аубердин, Астранаар и Пустоши." }, { 35.77, "Эльфам помогают дриады и хранители рощи, а в недрах горы скрыта Пещера Когтей, где спят друиды." } } } },
    ["3cd7e36c"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Эонар также даровала младшей сестре Алекстразы, изящной зелёной драконице Изере, определённую власть над природой." }, { 9.53, "Изера впала в вечный транс, именуемый \"Сном Творения\"." }, { 14.11, "Известная под именем Спящей, она следит за природой мира из царства Изумрудного Сна." } } } },
    ["3ce8da78"] = { d = 33.4, v = "human-male", c = { x = { { 0.00, "Но несмотря на то что я был бессилен и не мог остановить это ужасное убийство, одно истинное сожаление всё же остаётся: ведь это я привёл чёрных всадников к ферме Свена." }, { 11.23, "Моя находка не только высвободила воргенов по всему Сумеречному лесу – она привлекла всадников из Мёртвого Ветра." }, { 18.96, "Я знаю это, потому что прежде чем они начали убивать, они задали жене Свена один вопрос в тот момент, когда она прижимала к себе своих детей, пытаясь успокоить их и ободрить, зная, что вскоре их ожидает смерть." } } } },
    ["3cec3656"] = { d = 23.2, v = "narrator", c = { x = { { 0.00, "Тиранда, ставшая Верховной жрицей Элуны, умоляла своего возлюбленного Малфуриона не уходить в Изумрудный Сон Изеры." }, { 9.03, "Но Малфурион, считавший своим долгом вступить на изменчивые тропы Спящей, попрощался со жрицей и поклялся, что они никогда не разлучатся, до тех пор пока хранят верность своей любви." } } } },
    ["3cfd532a"] = { d = 69.2, v = "narrator" },
    ["3d174885"] = { d = 53.7, v = "human-male", c = { x = { { 0.00, "Моя дорогая Эмили!" }, { 1.36, "Несколько дней назад мы снялись с лагеря в этом покинутом Светом месте и по приказу короля отправились домой." }, { 8.88, "Даже эти мрачные пейзажи не могли омрачить моей радости, ибо я знал, что после тяжёлого путешествия ты наконец-то сможешь заключить меня в объятья." }, { 18.99, "Сегодня мы добрались до берега, но обнаружили, что от наших кораблей остались одни лишь дымящиеся угли; лишённые единственного шанса вернуться домой, мы вынуждены идти в самое сердце этой бескрайней пустыни." }, { 33.11, "Эмили, ради тебя я отправлялся в самые дальние уголки этого мира, а теперь… теперь я всей душой желаю повернуть время вспять и вновь оказаться рядом с тобой." }, { 43.96, "Каждое мгновение я думаю о тебе." }, { 46.24, "Любимая, мысли о тебе согревают мою душу в этом ледяном краю, и никто никогда не отнимет их у меня." }, { 53.21, "Максвелл" } } } },
    ["3d26348d"] = { d = 29.5, v = "nightelf-female", c = { x = { { 0.00, "Элуна услышала мои молитвы." }, { 2.14, "Мои товарищи пали недаром, и коса Элуны поможет мне отомстить за них." }, { 7.37, "Это древняя вещь, ветка, изогнутая и искорёженная, из дерева, которое, должно быть, старше самих кальдорай." }, { 15.27, "Много часов я исследовала дар богини." }, { 18.08, "С первого взгляда понятно, что это не обычное оружие и не простое магическое устройство." }, { 24.64, "С ним... словно барьеры времени и пространства ослабели." }, { 28.80, "Держа Косу" } } } },
    ["3d30cfc5"] = { d = 41.4, v = "orc-female", c = { x = { { 0.00, "Бесплодные земли кишат врагами." }, { 2.50, "Огры рыщут по раскалённым пескам, нападая на неосторожных путников." }, { 7.65, "Дворфы из клана Чёрного Железа, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан." }, { 18.70, "Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени." }, { 25.93, "А в Восточных Бесплодных землях, в долине Летлор, живут драконы." }, { 30.94, "Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются." } } } },
    ["3d6a7c8c"] = { d = 24.0, v = "narrator", c = { x = { { 0.00, "Белая башня маяка стоит на скалистом островке у самого южного края побережья, и ночью её луч медленно кружит над рифами Великого моря." }, { 11.19, "Когда-то здесь жила семья смотрителя, но теперь у подножия слышен лишь прибой да возня мурлоков на берегу." }, { 19.93, "Огонь всё же горит — есть кому за ним присматривать." } } } },
    ["3d924b80"] = { d = 27.5, v = "orc-female", c = { x = { { 0.00, "Хелгрум, передай мою похвалу тому, кто приказал основать нашу базу в Каргате среди Бесплодных Земель." }, { 8.18, "Это место идеально подходит для обучения наших войск." }, { 12.45, "Тамошний суровый климат, злобные звери, воинственные аборигены и полное отсутствие помощи извне сделают так, что выйдут оттуда лишь лучшие из воинов и разведчиков." }, { 25.32, "Хорошая задумка." }, { 26.68, "Превосходно." } } } },
    ["3db68ad9"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Восточнее Забытого Города, среди холмов, стоит поселение тауренов Зловещего Тотема — отступников, не признающих власть Громового Утёса." }, { 11.20, "Лагерь разделён на две части, и в южной из них высится большая клетка, где томятся пойманные волшебные дракончики." }, { 20.59, "Здесь правит Грундиг Тёмное Облако, и в Лагере Мохаче не забыли о его злодеяниях." }, { 27.36, "К востоку от северной части лагеря тянутся стоянки гноллов, с которыми Зловещий Тотем делит эти холмы." } } } },
    ["3dc804ff"] = { d = 13.6, v = "dwarf-male", c = { x = { { 0.00, "Ажек и сэр Эрлгедин страстно желали научиться стрелять из дворфийских винтовок." }, { 5.52, "Я велел им оставить своё примитивное оружие в лагере." }, { 9.22, "Мы с Барнилом снарядили их лучшими образцами стальгорнских ружей." } } } },
    ["3dedbd2c"] = { d = 28.2, v = "bloodelf-female", c = { x = { { 0.00, "Дата занесения: нет данных" }, { 2.00, "Имя: Натанос Маррис, человек, предводитель следопытов Лордерона." }, { 6.80, "Тема:" }, { 7.26, "Хочу отметить несогласие Кель'таса Солнечного Скитальца с моим решением принять Натаноса Марриса в наши ряды." }, { 15.46, "Следует отметить, что Натанос, несмотря на своё человеческое происхождение, является одним из самых талантливых следопытов, которых мне доводилось обучать." }, { 26.79, "(продолжение следует)" } } } },
    ["3e2b9c83"] = { d = 30.4, v = "narrator", c = { x = { { 0.00, "Застава Мор'шан — укреплённый вал с башнями на самом севере Степей, где Золотой Путь уходит в Ясеневый лес." }, { 8.45, "Стену возвели орки клана Песни Войны, и отсюда Кадрак руководит кампанией Орды в лесу, набирая новобранцев для защиты новых рубежей." }, { 19.28, "Ниже по дороге раскинулся лагерь всадников Песни Войны, а совсем рядом лежит вход в ущелье, где Орда и Альянс сходятся в бесконечной битве." } } } },
    ["3e2eea5f"] = { d = 10.9, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ." }, { 2.74, "Часть первая." }, { 4.26, "Верховный Вождь." }, { 6.09, "Вождь." }, { 6.80, "Генерал." }, { 7.81, "Лейтенант-генерал." }, { 9.95, "Защитник." } } } },
    ["3e43f384"] = { d = 23.9, v = "narrator", c = { x = { { 0.00, "Зловещий холм лежит на северо-востоке Болотины, юго-восточнее Дун Модра." }, { 5.75, "Здесь дворфы Чёрного Железа разбили большой лагерь, откуда их отряды выходят к мосту Тандола и к захваченному городу." }, { 14.98, "Между палаток горят кузнечные огни, а на подступах стоят стрелки и сапёры, так что случайному путнику здесь не рады." } } } },
    ["3e52b688"] = { d = 40.2, v = "narrator", c = { x = { { 0.00, "Стена Скарабея тянется вдоль южной кромки Силитуса от края до края, отделяя пустыню от крепости Ан'Кираж." }, { 9.08, "Её возвели в конце Войны Зыбучих песков: ночные эльфы подняли стену из самого песка, а выше неё магия бронзовых драконов создала незримый заслон во много раз выше камня." }, { 23.78, "Этот барьер тысячу лет удерживает силитидов и их повелителей-киражей внутри стен Ан'Киража." }, { 31.55, "У самых врат ждёт своего часа Гонг Скарабея, а рядом несут вахту бронзовые драконы из выводка Ноздорму." } } } },
    ["3e693f37"] = { d = 28.6, v = "human-male", c = { x = { { 0.00, "Валлик," }, { 0.53, "Охраняй раба до нашего возвращения." }, { 2.90, "Теперь здесь небезопасно, мы не можем больше хранить его тут." }, { 6.93, "Мы отправимся на север, обходя стороной любые места, где нас могли бы заметить." }, { 12.14, "Они – животные, но животные безжалостные – мы достаточно от них натерпелись, у нас есть причины для беспокойства." }, { 19.36, "Лучше спрятать любые знаки, что могли бы заставить собраться их вместе." }, { 24.10, "Меньше всего мы бы хотели дать им повод воссоединиться и напасть на нас." } } } },
    ["3e972b4d"] = { d = 34.2, v = "human-male", c = { x = { { 0.00, "Дорогая Памела!" }, { 1.24, "Завтра мы доберёмся до Андорала, и, боюсь, я не буду тебе больше писать." }, { 6.77, "Нежить не знает усталости, а мы… мы – всего лишь люди." }, { 10.91, "Нам их не победить." }, { 12.36, "Но не надо печалиться, любовь моя: хотя нам и суждено погибнуть, наша надежда остаётся." }, { 19.05, "Свет победит!" }, { 20.09, "И мне греет душу мысль о том, что, когда наша защита падёт и враг сокрушит нас, страх смерти не будет терзать меня." }, { 28.79, "Все мои мысли будут о тебе, дорогая, и моя душа обретёт покой." }, { 33.69, "Кристоф" } } } },
    ["3ed5ffc8"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Двое заключили между собой пакт." }, { 2.65, "Кел'Тузад получил бессмертие и великую силу в обмен на верность Королю-личу." }, { 8.82, "Перво-наперво он должен был употребить в Лордероне всё своё богатство и влияние, чтобы основать там Культ Проклятых." }, { 17.85, "Этот культ обещал всем своим приверженцам равенство и вечную жизнь, если они присягнут на верность Нер'зулу, богу Культа Проклятых." } } } },
    ["3ef8b786"] = { d = 36.7, v = "orc-male", c = { x = { { 0.00, "-День тринадцать" }, { 1.27, "Движение войск у Терамора усилилось." }, { 4.08, "Крупные отряды людей оставили город и спешно идут на запад." }, { 8.87, "--День четырнадцать" }, { 10.34, "Из города уходят все новые отряды." }, { 13.09, "Я проследил за одной маленькой группой и видел, как всё в ней сняли униформу, удалившись от Терамора на расстояние полёта стрелы." }, { 23.56, "Может быть, они дезертиры?" }, { 25.67, "--День пятнадцать" }, { 27.01, "Сегодня я слышал, как солдаты в Тераморе говорили о часовых, оставляющих посты." }, { 33.20, "Должно быть, мои подозрения о дезертирах верны" } } } },
    ["3f1825e4"] = { d = 41.7, g = 1, v = "orc-male" },
    ["3f76d70f"] = { d = 41.8, v = "narrator", c = { x = { { 0.00, "Родниковое озеро — небольшой водоём к северо-востоку от Дарнасса, питаемый источником из недр Древа Жизни; из него вытекает Родниковая река." }, { 11.75, "Когда-то здесь любили рыбачить, но теперь у воды бродят древесники, поражённые порчей сильнее всех на острове, а в окрестностях рыщут ночные саблезубы и пауки." }, { 25.01, "Близ озера обитает леди Сатра — паучиха, некогда дорогая Элуне: она ткала серебряные нити под луной, и капли тумана с её паутины хранили в храме Луны как целебное средство." }, { 39.72, "Ныне её постигло безумие." } } } },
    ["3f9b85e1"] = { d = 32.6, g = 1, v = "troll-male", c = { m = { { 0.00, "Надеюсь, духи исправно тебя защищали." }, { 3.06, "Тебе предстоит ещё много испытаний, поэтому я хочу вот обучить тебя тому, что сам знаю." }, { 10.05, "Сам решай, хочешь ли обладать нашими силами, и если да, то приходи." }, { 15.39, "Выбирать тебе – я могу только вести тебя." }, { 18.81, "Ну, одни-то, конечно, учатся быстро, а другие вот… помедленней." }, { 23.80, "Но ты не волнуйся заранее." }, { 25.86, "Как захочешь меня увидеть – приходи, поговорим." }, { 29.64, "-Кен'джай, наставница Жрецов." } }, f = { { 0.00, "Надеюсь, духи исправно тебя защищали." }, { 3.12, "Тебе предстоит ещё много испытаний, поэтому я хочу вот обучить тебя тому, что сам знаю." }, { 10.23, "Сама решай, хочешь ли обладать нашими силами, и если да, то приходи." }, { 15.81, "Выбирать тебе – я могу только вести тебя." }, { 19.29, "Ну, одни-то, конечно, учатся быстро, а другие вот… помедленней." }, { 24.37, "Но ты не волнуйся заранее." }, { 26.47, "Как захочешь меня увидеть – приходи, поговорим." }, { 30.32, "-Кен'джай, наставница Жрецов." } } } },
    ["3f9fba90"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "Титан Норганнон, хранитель знаний и владыка магии, даровал синему дракону Малигосу часть своей великой силы." }, { 9.62, "С того времени Малигос, известный как Маготкач, хранит магию и тайные знания." } } } },
    ["3fa4ae6a"] = { d = 26.9, v = "narrator", c = { x = { { 0.00, "Вершина Духов поднимается к северо-западу от центрального утёса." }, { 5.02, "Это средоточие шаманских знаний тауренов: здесь учат говорить с духами земли, огня и ветра." }, { 12.31, "Верёвочные мосты связывают вершину с нижним и средним ярусами города." }, { 17.76, "У края утёса причаливает дирижабль, летящий в Оргриммар, а под самой вершиной, в пещерах, прячутся тёплые Пруды Видений." } } } },
    ["3fb1abb3"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Зловещее море омывает восточный берег нагорья, но горы почти не пускают к нему путников." }, { 7.43, "Это неисследованные, не нанесённые на карты воды, и моряки говорят, что за их пределами нет ничего." }, { 15.46, "С крутого берега видно лишь серую воду до самого горизонта да птиц над волнами." } } } },
    ["3fd00d3f"] = { d = 17.3, v = "narrator", c = { x = { { 0.00, "Глава первая: СЕВЕРНЫЙ ПИЛОН." }, { 2.56, "Северный пилон принимает жёлтые, красные и зелёные кристаллы." }, { 7.59, "Пилон фокусирует энергию, которая возникает при использовании жёлтых кристаллов в качестве основного источника энергии." } } } },
    ["3fee4a71"] = { d = 25.2, v = "narrator", c = { x = { { 0.00, "Озеро Меннар — одно из немногих мест за пределами Нордскола, где можно встретить синих драконов." }, { 7.43, "Все берега озера заняты их выводком: драконьи отродья и синие дракончики стерегут подходы к воде, и только самые сильные пробьются к ней." }, { 18.06, "Само же озеро тихо и безопасно, и тот, кто добрался до его берега, может отдохнуть в прохладе." } } } },
    ["40221831"] = { d = 50.5, v = "narrator", c = { x = { { 0.00, "Крепость Древобрюхов вырыта в горах на северо-востоке леса, и через её туннели лежит единственный путь на Лунную поляну и в Зимние Ключи." }, { 11.02, "Здесь живут фурболги Древобрюхи — одно из немногих племён, избежавших порчи Легиона, когда их сородичи по всему Калимдору сходили с ума." }, { 21.89, "Они видели, как любимый лес гниёт заживо, и теперь не доверяют никому: чужака принимают за осквернённого и встречают копьями." }, { 31.76, "У входа со стороны леса стоит на страже Нафиэн, со стороны Зимних Ключей — Сальфа; внутри живут Горн Одноглаз, Мелиош и Кернда." }, { 42.06, "Кто докажет верность в бою с фурболгами Мёртвого Леса, узнаёт, что Древобрюхи ценят друзей превыше сокровищ." } } } },
    ["406123c7"] = { d = 72.0, v = "narrator", c = { x = { { 0.00, "Осквернённый лес лежит на севере Калимдора, между Тёмными берегами и Ясеневым лесом, у подножия горы Хиджал." }, { 8.83, "Когда-то это была цветущая земля ночных эльфов, но в Третью войну здесь прошёл Пылающий Легион, и порча Черепа Гул'дана въелась в саму землю." }, { 20.64, "Иллидан поглотил череп, а повелитель ужаса Тихондрий пал, но лес не исцелился: деревья гниют стоя, реки отравлены, а звери, фурболги и даже древни сошли с ума." }, { 33.85, "В руинах Джеденара засели чернокнижники Совета Теней, по холмам расселились сатиры Нефритового Пламени, а в долине Рваных Ран до сих пор дымятся кратеры инферналов." }, { 47.29, "Друиды Изумрудного Круга с юга и фурболги Древобрюхи с севера пытаются вернуть лесу прежний облик, но пока лишь сдерживают порчу." }, { 58.05, "Главная дорога ведёт к единственному проходу на Лунную поляну и в Зимние Ключи; днём по ней можно пройти спокойно, но сходить с тропы и задерживаться до темноты не советуют." } } } },
    ["406474c0"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Прошло время, и Кенарий стал сильным, как его великий отец." }, { 5.18, "Брат деревьев и звёзд, этот великий охотник странствовал по миру, напевая умиротворяющую песню рассвета." }, { 14.08, "Всё живое склонялось перед его грацией и красотой." }, { 18.49, "Никого на свете не было мудрее сына луны и белого оленя." } } } },
    ["4093d5a0"] = { d = 23.8, v = "narrator", c = { x = { { 0.00, "Разъярённые драконы Алекстразы разрушили Грим Батол и сожгли большую часть орков Драконьей Пасти." }, { 8.07, "Грандиозные планы Некроса рухнули; войска Альянса окружили уцелевших орков и заключили их в лагерь для военнопленных." }, { 17.88, "Поражение Драконьей Пасти ознаменовало конец Орды и кровожадности орков." } } } },
    ["409490f5"] = { d = 25.1, v = "narrator", c = { x = { { 0.00, "Малфурион и друиды не слушали речей Дат'Ремара и объявили высокорождённым, что любое использование магии будет караться смертью." }, { 10.42, "Однако Дат'Ремар и его последователи всё же попытались нарушить закон друидов, но попытка эта закончилась крахом, и в результате в Ясеневом лесу разразилась ужасная магическая буря." } } } },
    ["40beb82c"] = { d = 39.1, v = "narrator", c = { x = { { 0.00, "Башня Каменной Стражи стоит при одноимённой крепости, вторая часть старого людского укрепления на восточном берегу озера." }, { 9.59, "Прежде её держали стражники Приозёрья, но вместе с крепостью башня досталась оркам клана Чёрной Горы, и теперь на её ярусах несут дозор подручные Гат'Илзогга." }, { 22.10, "Это единственная уцелевшая башня рядом с крепостью, и с её вершины видны и озеро, и восточные долины." }, { 30.19, "Чародей Теокрит из башни Азоры знает, что Моргант враждует с орками крепости, и ищет способ подслушать их отсюда." } } } },
    ["40c68efc"] = { d = 40.5, v = "narrator", c = { x = { { 0.00, "Уступ Ледопардов — высокая скала на севере Зимних Ключей, где обитает прайд белых ледопардов: детёныши, охотницы и стражи прайда." }, { 10.70, "Ночные эльфы почитают этих зверей, и на самой вершине скалы живёт наставник, обучающий доверенных друзей Альянса приручать ледопардов и ездить на них верхом." }, { 23.80, "Такое доверие нужно заслужить — и у него, и у самих кошек, самых диких и своенравных из всех саблезубов." }, { 32.48, "По преданию, прайдом правит могучая Шай-Ротам, и тому, кто увидит её, суждена удача до конца дней." } } } },
    ["41047c9a"] = { d = 26.7, v = "narrator", c = { x = { { 0.00, "Побережье Чёрного Копья — полоса песка у деревни Сен'джин." }, { 4.41, "Именно сюда высадились тролли Чёрного Копья, когда Залазан вынудил их покинуть острова Эха, и здесь Вол'джин собрал уцелевших." }, { 14.12, "Отсюда видны родные острова, до которых рукой подать и куда племя пока не может вернуться." }, { 21.22, "По берегу ползают крабы, а в прибрежных водах ловят рыбу жители деревни." } } } },
    ["4133bbde"] = { d = 30.3, v = "narrator", c = { x = { { 0.00, "Разорённый Сумеречный лагерь лежит в Долине Кристаллов, среди северо-западных скал Силитуса." }, { 7.10, "Когда-то здесь стоял северный стан Сумеречного Молота, но лагерь был разгромлен, и в свитках культа о его судьбе говорят как об испытании веры." }, { 18.09, "Среди обугленных шатров теперь скрывается Демитриан, бывший верховный лорд культа, дрожащий перед каждым путником и бормочущий о том, что ему довелось пережить." } } } },
    ["419c2e4f"] = { d = 25.9, v = "gnome-male", c = { x = { { 0.00, "Добрый мой Мартек, я в затруднении, мне нужна твоя помощь." }, { 4.16, "Мы с братом собираем гоночный автомобиль, и нам требуются крепкие поршни." }, { 9.35, "Все поршни, что я пробую, недостаточно крепки." }, { 12.62, "Ни один из них не может выдержать скорость нашей новой машины." }, { 17.10, "И поэтому у нас то и дело ломается двигатель!" }, { 20.30, "Ты мастер по работе с металлом." }, { 22.54, "Ты должен помочь." }, { 23.82, "Ты – единственная наша надежда." } } } },
    ["41a36456"] = { d = 33.9, v = "narrator", c = { x = { { 0.00, "Кормление и уход:" }, { 1.38, "Мы хотим обеспечить вас всем необходимым для ухода за питомцем." }, { 6.15, "Наши клиенты ожидают от \"Шмыг Инк.\" именно такого уровня обслуживания, и мы с ними согласны!" }, { 13.20, "С этой целью мы разработали крепкие ящики для шмыгуносов, чтобы вы могли содержать питомца в безопасности и вне доступа света." }, { 22.87, "Для вашего удобства в каждом ящике находится отделение для корма, пронизанное чарующим ароматом клубней синелиста (любимого лакомства шмыгуносов)!" } } } },
    ["41aa1804"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Озеро Ирис лежит к востоку от Астранаара, у дороги, ведущей на восток к лунному колодцу." }, { 6.84, "Когда-то это было чистое лесное озеро, но порча из Осквернённого леса дошла и до него: вода стала мутной, желтовато-зелёной, а по берегам бродят болотные твари, готовые броситься на любого, кто подойдёт к воде." }, { 22.93, "На острове посреди озера лежит Слеза Элуны — камень, который, как говорят лекари, снимает порчу, и ради него сюда всё ещё приходят смельчаки." } } } },
    ["4205404d"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Зловещий берег — полоса побережья и цепочка островков между Терамором и крепостью Северной Стражи в Степях." }, { 8.71, "Эти солёные заводи давно облюбовали мурлоки: их стойбища теснятся на каждой отмели, а из воды выползают морские черепахи." }, { 18.52, "Люди Терамора ходят сюда за черепашьим мясом и рыбой, но всегда с оглядкой: мурлоки ревниво берегут свой берег." } } } },
    ["420d6407"] = { d = 31.0, v = "human-male", c = { x = { { 0.00, "Каменщиков из Штормграда, он воспользовался относительно незащищённым статусом Западного Края и использовал своё превосходство в силе, чтобы выгнать оттуда множество фермеров и захватить несколько золотых рудников." }, { 13.56, "Воспользовавшись ресурсами, оказавшимися в его распоряжении, ван Клиф составил план возмездия правительству Штормграда." }, { 21.04, "Эта информация стала известна лишь недавно благодаря помощи носителя этого документа, который сыграл важную роль в пролитии света на этот громадный заговор." } } } },
    ["4217bc33"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Титаны наделили силой многие расы, чтобы те смогли помочь им придавать миру форму." }, { 6.52, "Для создания бездонных подземных пещер титаны сотворили дворфоподобных земельников из магического живого камня." }, { 15.06, "Чтобы помочь им осушить моря и поднять землю над уровнем моря, титаны создали огромных, но кротких морских великанов." }, { 24.22, "Многие столетия титаны придавали форму землям, пока не смогли сотворить совершённый континент." } } } },
    ["4234992a"] = { d = 27.7, v = "narrator", c = { x = { { 0.00, "Охрана Ясеневого леса занимала всё время Тиранды, но она тосковала без Малфуриона." }, { 6.74, "Шли века, друиды спали, а её опасения насчёт нового вторжения демонов росли." }, { 12.96, "Она не могла избавиться от тревожного ощущения, что, возможно, Пылающий Легион всё ещё здесь, за пределами Великой тьмы неба, и что он готовится отомстить ночным эльфам и всему Азероту." } } } },
    ["4241d159"] = { d = 15.1, v = "narrator", c = { x = { { 0.00, "Чтобы добыть энергию, необходимую для порталов, ему нужно было несколько мощных артефактов с Азерота." }, { 7.70, "Нер'зул снова открыл Тёмный портал и послал туда своих верных слуг, чтобы они нашли эти артефакты." } } } },
    ["42459b0c"] = { d = 17.2, v = "narrator", c = { x = { { 0.00, "ПИЛОНЫ: ИНСТРУКЦИЯ ПО ЭКСПЛУАТАЦИИ" }, { 3.05, "\"Руководство по сбору и использованию кристаллов силы Кратера Ун'Горо\"" }, { 9.32, "Глава первая: Северный пилон" }, { 11.98, "Глава вторая: Восточный пилон" }, { 14.71, "Глава третья: Западный пилон" } } } },
    ["4248e9d3"] = { d = 32.5, v = "human-male", c = { x = { { 0.00, "Родина воргенов – тёмное место, обитель кошмаров." }, { 3.44, "Если в том мире и есть места, куда не могут добраться проклятые воргены, то мне о таких бастионах не известно." }, { 11.08, "Если же лицезреть воочию ярость и злобу воргенов, то на ум приходит, что быть таких мест не может." }, { 17.85, "Есть мнение, что воргенов вполне устраивает их собственный мир: ведь, хотя некоторые из них владеют очень сильной магией, они не предпринимали попыток перенестись в Азерот самостоятельно." }, { 30.68, "И для нас это очень хорошо." } } } },
    ["4285d512"] = { d = 17.7, v = "narrator", c = { x = { { 0.00, "Алекстраза Хранительница Жизни опустила в источник зачарованный жёлудь." }, { 5.72, "Пробуждённый могущественными водами, он вырос в огромное дерево, корни которого тянулись в самые недра Источника, а крона, казалось, достигала небес." } } } },
    ["429c2fcd"] = { d = 8.4, v = "narrator", c = { x = { { 0.00, "Доргар Камнелоб" }, { 1.34, "Воин Алого ордена" }, { 2.90, "Властитель Красных пещер" }, { 4.98, "Последний раз был замечен в горах Альтерака" } } } },
    ["42a045fa"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Они назвали свои земли Каз Модан, или \"Гора Каза\", в честь титана-кузнеца Каз'горота." }, { 7.67, "Соорудив алтарь своему отцу-титану, дворфы создали огромную кузницу в самом сердце горы." }, { 15.66, "И город, росший вокруг кузницы, стал называться Стальгорн." } } } },
    ["42c4dc88"] = { d = 8.7, v = "narrator", c = { x = { { 0.00, "Холия Солнечный Щит" }, { 1.86, "Защитница Алого ордена" }, { 4.06, "Погибла при покушении на повелителя ужаса Белтериса" } } } },
    ["42f45475"] = { d = 24.6, v = "human-male", c = { x = { { 0.00, "Должна быть собрана об организации нежити в Брилле." }, { 3.40, "Капитан Вакон, похоже, что передвижения нежити около северной башни возросли." }, { 8.59, "Эти волнения должны быть быстро и решительно подавлены." }, { 12.29, "Капитан Мелроуз, меня беспокоит уровень организованности нежити около границ с Лихоземьем." }, { 18.32, "Новая группа солдат будет доставлена в ваше распоряжение в ближайшие недели." }, { 23.45, "Да прославится Свет" } } } },
    ["42f70d39"] = { d = 32.1, v = "narrator", c = { x = { { 0.00, "Лесная Песнь — древние руины ночных эльфов на северо-востоке леса, к северу от лесозаготовок Песни Войны и к востоку от Сатирнаара." }, { 10.79, "Некогда это было поселение, а теперь среди разбитых колонн живёт лишь один друид, последний из народа калдорей в этих местах." }, { 21.22, "Отсюда он следит за Отрёкшимися, что орудуют в округе, и за курганом Дор'Данил, и радуется каждому голосу, что снова звучит среди руин." } } } },
    ["431ad588"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Меррик Вэлор, дозорный Темнолесья." }, { 2.73, "Меррик был младшим сыном в семье Вэлор." }, { 5.88, "Видя, как скверна подступает к родным краям, он вступил в Ночной дозор, отчаянно желая уберечь своих близких." }, { 14.50, "Пусть он и был самым неопытным в семье, но вскоре заслужил добрую славу среди дозорных." }, { 21.29, "У него был дар к стрельбе из лука, и очень скоро он стал одним из самых стойких защитников Темнолесья." }, { 29.21, "Своим долгом он считал охрану дорог от тварей, что все свирепее наводняли здешние леса." } } } },
    ["4352bac4"] = { d = 30.8, v = "narrator", c = { x = { { 0.00, "Шахтёр Оруэлл" }, { 1.18, "Крупный долг." }, { 2.35, "Выплата состоится после поставки руды из Лазурного рудника." }, { 7.60, "Шахтёр Фитцджеральд" }, { 9.25, "Крупный долг." }, { 10.42, "Выплата состоится после поставки руды из Лазурного рудника." }, { 15.68, "Гражданин Недранд" }, { 17.24, "Все задолженности выплачены." }, { 19.67, "Гражданин Мэй" }, { 20.85, "Все задолженности выплачены." }, { 23.28, "Старшина Бондс" }, { 24.53, "Крупный долг." }, { 25.71, "Выплата состоится после поставки руды из Лазурного рудника." } } } },
    ["435c0b16"] = { d = 20.5, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Брат, я надеюсь, ты получил эту руну." }, { 2.74, "Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине." }, { 7.76, "Я знаю, как важно для нас держаться вместе, особенно в такое неспокойное время." }, { 13.49, "Загляни ко мне, когда будет свободное время." }, { 16.75, "-Сольм Харгрин, наставник разбойников" } }, f = { { 0.00, "Сестра, я надеюсь, ты получила эту руну." }, { 3.14, "Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине." }, { 8.40, "Я знаю, как важно для нас держаться вместе, особенно в такое неспокойное время." }, { 14.41, "Загляни ко мне, когда будет свободное время." }, { 17.83, "-Сольм Харгрин, наставник разбойников" } } } },
    ["43673aca"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Шепчущий берег — короткий отрезок побережья на западе Тирисфаля, к северу от фермы Соллидена." }, { 7.06, "Когда-то сюда приходили рыбачить, но ныне вода здесь холодна и темна, а от былого изобилия не осталось и следа." }, { 15.47, "Берег заняла стая мурлоков, которая яростно бросается на всякого, кто подойдёт к воде." } } } },
    ["43858bc6"] = { d = 41.8, v = "narrator", c = { x = { { 0.00, "Вулкан Огненного Венца возвышается в самом сердце кратера." }, { 4.77, "По его склонам стекает лава, среди обугленных камней бродят элементали огня, а на вершине, в пещере, обитает сильнейший из них — Яропламень, к чьему логову не решаются подходить даже исследователи: многие смельчаки сгинули в расщелинах сердца кратера." }, { 24.94, "Жар вулкана греет всю чашу Ун'Горо: неглубокие жилы магмы тянутся под землёй и питают гейзеры источников Голакка." }, { 34.04, "В пещере у южного подножия укрылся гном Ринго, забредший сюда из любопытства и едва живой от зноя." } } } },
    ["4390446e"] = { d = 27.6, v = "nightelf-male", c = { x = { { 0.00, "Я начал вести этот журнал, чтобы делать заметки о своих попытках помочь Ясеневому лесу." }, { 7.08, "Некоторые из недавних событий исполнены тайн, и я надеюсь, что смогу пролить свет на часть из них, чтобы помочь своему народу." }, { 16.85, "Начну с того, что запишу некоторые факты, чтобы не забыть их потом." }, { 22.23, "Недавно я нашёл подтверждение слухам о деятельности волшебника Дартола." } } } },
    ["43a916ba"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Гробница когда-то была лишь кладбищем при дороге, пересекающей Серебряный бор." }, { 6.03, "После Третьей войны Отрёкшиеся превратили старый склеп в свою базу в этих краях." }, { 12.33, "Отсюда верховный палач Хадрик рассылает стражей смерти, аптекарь Ренферрел ищет ингредиенты для новой чумы, а Далар Ткач Рассвета изучает магию Аругала." }, { 24.31, "Воргены на юге, Плеть на востоке и Кирин-Тор на юго-востоке делают Гробницу едва ли не единственным безопасным местом во всём лесу." } } } },
    ["43b543bf"] = { d = 21.4, v = "dwarf-male", c = { x = { { 0.00, "День четвёртый." }, { 1.12, "Я в плену!" }, { 1.96, "Нужно... писать... быстро." }, { 4.07, "На меня напали свинолюди из племени Иглошкурых." }, { 7.78, "Я думал, что они ведут меня к кабаньим останкам павшего бога." }, { 12.69, "Вместо этого они обогнули окаменелость и направились прямо к западу от гигантского черепа, пересекая Золотой Путь." } } } },
    ["43d67a54"] = { d = 44.9, v = "orc-female", c = { x = { { 0.00, "Дорогой Заргх, мясо, которое ты прислал, очень вкусное." }, { 4.56, "Оно с прожилками жира, нарезано толстыми кусками и обёрнуто в кабанье сало – как раз по моему вкусу." }, { 12.73, "Когда я съем его и разгрызу последние кости, то обязательно буду думать о тебе." }, { 19.28, "Я закрою глаза и буду представлять, как ты рубишь и режешь это мясо своими сильными, покрытыми шрамами руками…" }, { 28.40, "Ха!" }, { 28.70, "Я сразу вспомнила о том случае, когда ты лишился пальца…" }, { 33.33, "О, Заргх!" }, { 34.07, "Когда мне на память приходит тот день, я всякий раз хихикаю, будто маленькая девчонка." }, { 41.06, "Ты такой милый, когда истекаешь кровью!" }, { 44.37, "-Гришка" } } } },
    ["4400d3f3"] = { d = 23.4, v = "dwarf-male", c = { x = { { 0.00, "На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел." }, { 10.19, "Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места." }, { 15.80, "Она издала ещё один ужасный рык, громче прошлого, и исчезла." }, { 20.24, "Мы собрали вещи и мрачно двинулись в лагерь." } } } },
    ["443b5d6c"] = { d = 76.2, v = "narrator" },
    ["4441d2e2"] = { d = 37.2, v = "narrator", c = { x = { { 0.00, "Деревня Кровавого Копыта лежит в самом сердце Мулгора, в подкове озёра Каменного Быка, и названа в честь племени Кровавого Копыта." }, { 10.22, "Здесь правит Бейн, сын Кэрна, и сюда приходят молодые таурены, спустившиеся с плато Красного Облака." }, { 18.04, "В деревне приручают диких кодо и продают их как ездовых животных." }, { 23.19, "Мулл Громовой Рог создаёт тотемы для очищения отравленных колодцев, Зарельман Две Луны хранит обряд Прозрения, а на дороге к востоку Морин Ловец Облаков следит за Торговой компанией." } } } },
    ["449e93c5"] = { d = 33.4, v = "dwarf-male", c = { x = { { 0.00, "Твой драгоценный зверь не очень-то хорошо себя чувствует в обжигающем жаре Тлеющего ущелья… лучше тебе незамедлительно выполнить наши требования." }, { 10.75, "Ты принесёшь нам пять звёздных рубинов и семьсот золотых, и положишь всё это в один пакет без пометок." }, { 18.16, "Пакет не позже чем через неделю оставь у входа на Подгорную тропу." }, { 23.16, "Если наши требования не будут выполнены, Метцен украсит собой традиционный дворфийский стол на Праздник Зимнего Покрова." }, { 32.11, "Олень… вкуснятина…" } } } },
    ["44bab9bb"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Колодец Громового Рога стоит посреди трав, у северной дороги между деревней Кровавого Копыта и Громовым Утёсом." }, { 8.55, "Как и другие священные колодцы Мулгора, его захватили и отравили гоблины Торговой компании, желавшие управлять водой долины." }, { 18.14, "Для его очищения нужен тотем из когтей охотников прерий и пум плоскогорья, и Мулл Громовой Рог, носящий то же имя, что и колодец, ведёт эту работу из деревни." } } } },
    ["44bd3fb4"] = { d = 22.3, v = "narrator", c = { x = { { 0.00, "Северная комбинация кристаллов" }, { 2.56, "Есть два возможных эффекта: наносящий урон и нейтрализующий его." }, { 7.89, "КРИСТАЛЬНЫЙ ЗАРЯД: требует жёлтых и красных кристаллов." }, { 12.48, "Провоцирует сильный взрыв." }, { 14.66, "КРИСТАЛЬНОЕ ВОССТАНОВЛЕНИЕ: требует жёлтых и зелёных кристаллов." }, { 19.84, "Наделяет вас целительной аурой." } } } },
    ["44bdd380"] = { d = 14.6, v = "bloodelf-female", c = { x = { { 0.00, "Настоящим я отказываю Кел'Тасу в просьбах касательно Натаноса Марриса." }, { 5.60, "Он будет бесценным союзником." }, { 7.97, "Помяните моё слово." }, { 9.55, "Подписано:" }, { 10.41, "Сильвана Ветрокрылая" }, { 12.06, "Предводитель следопытов Луносвета." } } } },
    ["44d0de02"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "После изгнания коварных насекомых две империи вернулись к обычной жизни." }, { 5.71, "Победа в войне практически не изменила их границ." }, { 9.58, "Впрочем, в древних рукописях упоминается некое племя, покинувшее в те годы империю Амани и основавшее собственное поселение в самом сердце тёмного континента." } } } },
    ["44d8523b"] = { d = 13.8, v = "narrator", c = { x = { { 0.00, "Далеко на севере, в области, сейчас известной под названием Нордскол, жили малочисленные племена, образовавшие государство Гундрак, но так и не сравнившиеся со своими южными сородичами." } } } },
    ["450ef2f7"] = { d = 8.2, v = "human-male", c = { x = { { 0.00, "Этот побочный эффект невероятно смертоносен." }, { 3.55, "Только представь, что..." }, { 5.47, "Текст невозможно прочесть." }, { 7.53, "Ха-ха-ха!" } } } },
    ["453b1580"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Ферма Соллидена — тыквенная ферма на западе Тирисфаля, к северу от Могильника." }, { 5.88, "Это одно из немногих мест на севере Лордерона, где живые крестьяне пережили чуму: их защищает башня Алого ордена, стоящая за полями." }, { 15.88, "Люди здесь враждебны ко всем чужакам, а Отрёкшиеся смотрят на них как на плесень, расползающуюся по их земле." }, { 23.78, "Королевское фармацевтическое общество, впрочем, проявляет интерес к здешним тыквам: в Брилле их используют в опытах с Новой чумой." } } } },
    ["455c73a8"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Вязкая топь – густые болота на юго-востоке, к югу от озера Слёз, у подножия южных гор." }, { 7.36, "Это самая непроходимая часть болота: ни дорог, ни жилья, только вода по колено, коряги и туман." }, { 15.56, "В зарослях охотятся острозубые кроколиски и пантеры Тени, а у края гор чернеет вход в пещеру, которую заняли мурлоки." } } } },
    ["4569dfce"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Логово Кровавой Топи — пещера в юго-западной части болота, где гнездится целая стая ящеров." }, { 7.53, "Перед входом видны остатки чьего-то поселения, растерзанного хищниками: ящеры не оставили здесь ни живых, ни целых стен." }, { 17.15, "Их крики разносятся над водой далеко, и путник, услышавший визг стаи, делает крюк, каким бы долгим он ни был." } } } },
    ["457bf475"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Деревня Южного Ветра — руины ночноэльфийской заставы в юго-восточном Силитусе, у самой кромки Улья Регал." }, { 8.46, "Тысячу лет назад Фэндрал Олений Шлем приказал своему сыну Вальстану оборонять эту деревню, и в тот же день она пала под натиском армий Ан'Киража, а Вальстан расстался с жизнью." }, { 22.38, "С тех пор селение так и осталось лежать в песке: между разрушенных стен роятся силитиды, а по улицам бродят неупокоенные духи друидов и часовых, павших в ту ночь." } } } },
    ["45c2f389"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Безбрежные Пески — бескрайнее море дюн в сердце Танариса, между Прибамбасском и южными горами." }, { 7.93, "Здесь нет ни воды, ни тени: лишь хромоногие гиены, скорпиды и стеклошкурые василиски, а над раскалёнными барханами кружат огненные рухи." }, { 19.11, "Говорят, под самой поверхностью песка тянутся ходы силитидов, поджидающих неосторожного путника." } } } },
    ["45eb5cbb"] = { d = 27.7, v = "human-male", c = { x = { { 0.00, "В попытке понять прошлое я начал изучать создания настоящего, надеясь обнаружить недостающие ключи к загадке." }, { 7.83, "Озёрные тихоходы и озёрные ползуны – древние создания, населяющие остров в центре озера Лордамер." }, { 15.52, "Мох, растущий на них, содержит следы частиц тех самых окаменелостей." }, { 20.33, "Необходимо провести больше исследований, прежде чем я смог бы сделать выводы о том, что означает эта связь." } } } },
    ["46000e55"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Озеро Дарроумир, одно из крупнейших в Восточных королевствах, лежит у юго-западной границы края." }, { 7.59, "За его водами, уже в Западных Чумных землях, виден остров Каэр Дарроу с башнями рода Баровых, под которыми скрыт Некроситет." }, { 17.42, "В годы Второй войны на озере гремели морские сражения, а теперь его воды отравлены Плетью, и к берегу выносит мёртвую рыбу." } } } },
    ["4602fbe5"] = { d = 16.8, v = "dwarf-male", c = { x = { { 0.00, "Мастер Длиннобородый, как тебе известно, мы в клане Грозовой Вершины разбираемся в отличной работе, так что качество твоих щитов для нас не новость." }, { 10.38, "Именно поэтому я хотел бы заказать у тебя щит." }, { 13.70, "Описание его я привожу на следующей странице:" } } } },
    ["46538822"] = { d = 26.7, v = "narrator", c = { x = { { 0.00, "Руины Восточной Луны — обломки древнего тролльского поселения к западу от Зияющей бездны." }, { 7.24, "Тролли оставили эти камни задолго до прихода гоблинов, и теперь среди колонн хозяйничают огры клана Песчаного Молота, забредшие сюда с юга." }, { 18.69, "Никаких дел у Прибамбасска в этих руинах нет — лишь ветер, песок и тени огров между обвалившихся стен." } } } },
    ["465970a6"] = { d = 18.6, v = "tauren-male", c = { x = { { 0.00, "*Призыв на службу в Орду Держатель этого письма показал невероятные достижения силы и навыка во имя Орды.*" }, { 8.28, "*Его следует немедленно назначить на работу в Перекрёсток.*" }, { 12.71, "*С глубоким почтением,*" }, { 14.32, "Не возражаю." }, { 15.83, "- Такрин Торитель Путей" } } } },
    ["4661b983"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Улей Аши — обширное гнездо силитидов в северной части Силитуса, у дороги на Крепость Кенария." }, { 7.46, "Из земли торчат костяные шпили и уступы, а под ними уходят вглубь тоннели, где насекомые откладывают яйца." }, { 15.84, "Именно отсюда рои силитидов расползаются к Роящейся вершине." }, { 20.66, "Друиды Круга Кенария следят за этим гнездом и отправляют разведчиков к самому входу в улей, чтобы узнать, как далеко успели прокопаться насекомые." } } } },
    ["46680378"] = { d = 31.8, v = "gnome-male", c = { x = { { 0.00, "Хорошо, у тебя должны быть заряды и детонаторы эн-джи-пять." }, { 4.05, "Я их пометил для тебя..." }, { 5.71, "Синий – для лесопилки." }, { 7.24, "Красный – для Рудника Ветрорезов." }, { 9.51, "Я кое-что разведал и выяснил, что на Утёсе Ветрорезов достаточно взрывчатки, чтобы тебе не было сложно зайти туда, установить детонаторы и выйти оттуда, перед тем как взрывать." }, { 21.47, "Помни, это отвлекающий манёвр." }, { 23.56, "Отойди далеко от вагонов перед тем, как гоблины доберутся туда, чтобы проверить, что случилось, затем проскользни за ними." } } } },
    ["4689fa4a"] = { d = 17.7, v = "narrator", c = { x = { { 0.00, "Дренил'дур – старое название одного из поселений Заблудших на севере болота." }, { 6.32, "Здесь такие же хижины из прутьев и дымящие костры, как в Болотном пристанище, и такие же настороженные взгляды: чужаков в этих краях не ждут." } } } },
    ["468e7779"] = { d = 20.1, v = "narrator", c = { x = { { 0.00, "Рыцари смерти и последователи Призрачной Луны, верные Нер'зулу, также подверглись трансформации: их разорвали на части, а затем превратили в костяных Королей Мёртвых." }, { 12.51, "Демоны позаботились о том, чтобы даже после смерти последователи Нер'зула беспрекословно служили ему." } } } },
    ["46caa2b4"] = { d = 38.5, v = "narrator", c = { x = { { 0.00, "Необратимость выбора" }, { 1.61, "Предыдущий раздел осветил весьма важные моменты о двух направлениях инженерного дела, которые надо усвоить, чтобы начать обучение." }, { 11.81, "Решение заняться тем или иным направлением науки означает, что схемы противоположного направления никогда не будут доступны для изучения." }, { 22.42, "Хотя такая окончательность выбора может отпугнуть непрофессионала, опытный инженер понимает, что гномы и гоблины оберегают свои секреты с великим пылом и что знание о чём-то – всё же лучше, чем никакого знания." } } } },
    ["47001514"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "Тростниковый берег – унылая полоса побережья, тянущаяся вдоль всего восточного края болота." }, { 7.44, "На песке лишь плавник, обломки и следы прилива; в прибое роются иловые и чудовищные крабы, у воды греются кроколиски." }, { 17.00, "Берег и прибрежные пещеры держат мурлоки Болотного племени, и орки с Тростниковой заставы то и дело посылают охотников проредить их ряды." }, { 28.16, "Здесь же собирают плавник те, кому нужно чинить повозку, чтобы выбраться с болота." } } } },
    ["470aa761"] = { d = 18.7, v = "narrator", c = { x = { { 0.00, "Когда на Азероте родился Медив, Кил'джеден Искуситель и его последователи из Круговерти Пустоты погрузились в размышления." }, { 9.43, "По приказу своего хозяина Саргераса, коварный великий демон готовил зловещие планы по захвату Пылающим Легионом Азерота." } } } },
    ["470b6e45"] = { d = 33.7, v = "narrator", c = { x = { { 0.00, "Саргерас выжидал подходящего момента, когда таящаяся в юноше сила даст о себе знать." }, { 6.54, "Уже будучи подростком, Медив заработал себе популярность среди жителей Азерота своими выдающимися магическими способностями и часто отправлялся на поиски приключений вместе со своими друзьями – принцем Азерота Ллейном и Андуином Лотаром, одним из последних сыновей рода Арати." }, { 27.98, "Трое мальчишек постоянно попадали в переделки, но горожане их очень любили." } } } },
    ["47430023"] = { d = 15.8, v = "narrator", c = { x = { { 0.00, "Гремящая Клеть — гоблинская забава Прибамбасска: железная клеть, где под рёв толпы сходятся бойцы, а зрители делают ставки на исход." }, { 11.10, "Как и всё в городе картеля, здесь ничто не достаётся даром." } } } },
    ["4760c8bc"] = { d = 15.2, v = "narrator", c = { x = { { 0.00, "Орки, уступавшие противнику числом и обезумевшие от собственной жажды крови, пали пред гневом Альянса." }, { 8.37, "Молот Рока был взят в плен и препровождён обратно в Лордерон, как и его разбитые кланы." } } } },
    ["4761db5f"] = { d = 43.5, v = "narrator", c = { x = { { 0.00, "Ночная Гавань — главное селение Лунной поляны, стоящее на берегу озера Элуне'ара." }, { 6.76, "Это посёлок ночных эльфов с каменными стенами и лунными колодцами, и живут здесь друиды Круга Кенария." }, { 15.15, "Обычно Гавань закрыта для чужих: попасть сюда легко лишь друидам, которые переносятся сюда заклинанием, а гиппогрифы отсюда летают только в Рут'теран и Громовой Утёс." }, { 28.75, "Здесь наставляет молодых друидов Дендрит Блеск Звёзд." }, { 33.01, "Раз в год селение оживает: на Лунный фестиваль друиды принимают и Альянс, и Орду, и над озером гремят фейерверки — знак силы Элуны." } } } },
    ["47a9b388"] = { d = 20.7, v = "narrator", c = { x = { { 0.00, "Огромная тень появилась в небе Нордскола." }, { 3.60, "Саргерас, король демонов и повелитель Пылающего Легиона, явился перед Эгвин, горя адским пламенем." }, { 12.28, "Он сказал юной Хранительнице, что время Тирисфаля истекло и мир скоро падёт перед натиском Легиона." } } } },
    ["47b0e790"] = { d = 32.8, v = "narrator", c = { x = { { 0.00, "Приют Бродяги – заброшенная сторожевая башня стражи Штормграда на северо-востоке Сумеречного леса, у дороги, ведущей на перевал Мёртвого Ветра." }, { 11.10, "Солдаты давно покинули её, и теперь в башне обосновались двое агентов Отрёкшихся, которые ведут здесь свои тайные дела и не жалуют чужаков." }, { 21.92, "Извилистая тропа спускается от башни к небольшому пруду с водопадом, где стоит безымянная могила, а неподалёку от башни есть маленькое кладбище." } } } },
    ["47bad38b"] = { d = 11.4, v = "narrator", c = { x = { { 0.00, "Антонидас предположил, что спокойствие орков вызвано не болезнью, а отсутствием чёрной магии, которая превращала их в грозных и безжалостных воинов." } } } },
    ["47bcb482"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Шадра'Алор — главное поселение троллей племени Сухокожих на юго-западе Внутренних земель." }, { 7.31, "Три ступенчатых храма стоят вокруг озера, и всё здесь посвящено Шадре, богине-паучихе, чьё имя носит город." }, { 16.08, "Тролли разводят у алтарей её выводок, а знахари, как говорят, умеют по имени призвать её дитя, Элорту но Шадру, и одно это имя приводит духов в смятение." }, { 28.66, "Сухокожие слабее Порочной Ветви, но чужаков у своих храмов не терпят, и меж колонн здесь караулят охотники за головами и ворожеи." } } } },
    ["47d55e19"] = { d = 28.8, v = "narrator", c = { x = { { 0.00, "Древо Жизни связывало всех ночных эльфов-друидов, включая Малфуриона, с Изумрудным Сном." }, { 6.97, "Заключая договор с драконами, они согласились периодически засыпать на целые века, чтобы их духи могли блуждать по бесконечным тропам сна Изеры." }, { 18.42, "Конечно, друидов печалило то, что придётся потерять столько лет своей жизни, но, тем не менее, они самоотверженно пошли на эту сделку." } } } },
    ["47fa99d9"] = { d = 37.8, v = "narrator", c = { x = { { 0.00, "Гниющий Шрам — низина на западе Выжженных земель, глубже всего отравленная энергиями Тёмного портала." }, { 8.10, "Земля здесь цвета крови, воздух пропитан Скверной, а над дымящимися кратерами стелется ядовитая мгла." }, { 16.21, "После Третьей войны сюда отступили уцелевшие силы Пылающего Легиона, и ныне Шрамом правит Владыка Каззак, могучий демон, окружённый своей чудовищной свитой." }, { 28.94, "Лишь отряды самых отчаянных героев решаются войти сюда, и немногие возвращаются, чтобы рассказать об увиденном." } } } },
    ["4800b43e"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Грим Батол — горная крепость на востоке Болотины, некогда возведённая дворфами." }, { 6.27, "В Войну Трёх Молотов она была проклята и покинута, а во Вторую войну её заняли орки клана Драконьей Пасти, державшие здесь в плену саму Королеву драконов." }, { 18.74, "Когда драконы вырвались на свободу, они разорили лагеря орков, а после сами запечатали крепость." }, { 26.60, "Теперь к её огромным закрытым вратам ведёт лишь горная дорога, и красные драконы не пускают внутрь никого." } } } },
    ["480a651a"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Лагерь Заржавня — крошечная стоянка гоблинов у дороги неподалёку от Кладбища кодо." }, { 6.19, "Здесь хозяйничает предприимчивый Смид Заржавень: он скупает приручённых кодо и снаряжает караван, что ходит через Пустоши, и ему позарез нужны новые звери, пока караван не пришёл." }, { 19.58, "Со своим соседом Биббли из Хижины Кормека он давно соперничает, кто первым разбогатеет на кодо." } } } },
    ["480d04bb"] = { d = 24.2, v = "dwarf-male", c = { x = { { 0.00, "Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев." }, { 8.68, "Полуденное солнце нещадно палило." }, { 11.19, "Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок." }, { 16.69, "В момент щелчка из кустов на поляну выпрыгнула огромная чёрная пантера – невероятно грациозное животное." } } } },
    ["4844c416"] = { d = 41.0, v = "narrator", c = { x = { { 0.00, "Каньон Гибели Демона лежит на юго-востоке Ясеневого леса, к югу от Холма Демонического Огня." }, { 7.95, "Здесь Гром Адский Крик и Тралл вышли против владыки преисподней Маннорота — того, чья кровь наложила проклятие на орков." }, { 17.87, "Демон сразил Тралла, но Гром успел вонзить топор ему в грудь, и взрыв огня и света, унёсший жизнь Маннорота, забрал и его." }, { 28.09, "Орки назвали это место в память о жертве вождя и приходят сюда поклониться его памятнику." }, { 35.82, "Но скверна не ушла: по каньону до сих пор рыщут младшие демоны." } } } },
    ["484c1445"] = { d = 27.6, v = "tauren-male", c = { x = { { 0.00, "Субстанция изгнанников:" }, { 2.06, "Эта субстанция может быть получена путём слияния трёх оберегов элементалей – изгнанников с Нагорий Арати." }, { 11.23, "Собери с духов Громовой, Пылающий обереги и оберег Гребня, а затем помести по восемь штук каждой разновидности амулетов в мой котёл." }, { 22.78, "Из смеси этих оберегов получится субстанция изгнанников." } } } },
    ["485e23fb"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Холм Нефритового Пламени поднимается на северо-западе леса, недалеко от деревни Сквернолапов." }, { 6.81, "Это главный лагерь сатиров Нефритового Пламени, и здесь собрались сильнейшие из них — призыватели огня, предатели и плуты во главе с Ксавариком, чья флейта, по слухам, связана с духами древних Дерев." }, { 21.36, "Отсюда сатиры сеют порчу среди соседних фурболгов и, как считают, готовят набеги на Крепость Древобрюхов." }, { 29.17, "Эридана Грусть Ветра просит смельчаков добраться сюда и положить конец Ксаварику." } } } },
    ["4869d6d3"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Владение Нетандера — заброшенная ферма к востоку от Южнобережья, некогда виноградник, а теперь гниющие лозы и пустые постройки." }, { 9.80, "Землю захватили гноллы Грязного Рыла — единственное место в предгорьях, где их можно встретить." }, { 17.17, "На запущенных полях разрослись огромные белые грибы, цветки Грязного Рыла: аптекарь Лидон с Мельницы Таррен интересовался ими как сырьём для смертоносного эликсира." }, { 29.81, "На возвышенности к северу от фермы держит наблюдательный пост страж смерти Масодж." } } } },
    ["486f3f7e"] = { d = 27.5, v = "narrator", c = { x = { { 0.00, "Келю и его подданным не оставалось ничего, кроме как отправиться в Запределье вслед за леди Вайш и сразиться с Майев, которой удалось снова поймать Иллидана." }, { 11.64, "Объединив силы, наги и эльфы крови справились с Майев и освободили его." }, { 18.31, "Обосновавшись в Запределье, Иллидан начал копить силы для следующего удара по Королю-личу и его цитадели Ледяной Короны." } } } },
    ["48842cca"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "На южной оконечности Азшары, на утёсах над Великим морем, лежат руины исполинской статуи ночных эльфов." }, { 8.33, "От колосса остались лишь ноги на постаменте, прочее разбросано вокруг или давно ушло под воду." }, { 16.00, "Говорят, памятник воздвигли в честь лорда Чёрного Ворона, водившего войска смертных в Войне Древних, но точно этого никто не знает." }, { 26.58, "Ныне среди обломков обосновались наги Злобного Прибоя, а с моря к памятнику не подойти — сюда ведёт лишь мост с суши." } } } },
    ["48917cf2"] = { d = 38.8, v = "narrator", c = { x = { { 0.00, "Колючий Холм — орочье поселение на перекрёстке дорог в сердце Дуротара." }, { 5.63, "Южный путь ведёт к деревне Сен'джин и Долине Испытаний, северный — к воротам Оргриммара, а западный уходит через реку Строптивую в Степи." }, { 16.52, "Над низкими хижинами возвышаются казармы, самое большое здание посёлка." }, { 22.22, "Здесь Оргнил Душегрыз ведёт расследование против культа Пылающего Клинка, чьи последователи всё смелее хозяйничают в окрестных каньонах." }, { 32.97, "Для многих молодых воинов Орды именно отсюда начинается настоящая служба." } } } },
    ["48bde706"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Ежевичный овраг — стойбище свинобразов племени Дыбогривов к югу от Перекрёстка, по восточную сторону Золотого Пути." }, { 8.91, "Среди колючих зарослей их геоманты, водоискатели и терноплёты ткут свою земляную магию, а через дорогу, в Агама'горе, стоит второе стойбище того же племени." }, { 21.04, "Дыбогривы нападают на всякого, кто подходит к их логову, и на их совести немало разграбленных обозов." }, { 28.83, "Именно этих свинобразов день за днём высматривает у ворот Перекрёстка Манкрик." } } } },
    ["48cfe23f"] = { d = 9.7, v = "narrator", c = { x = { { 0.00, "Адмирал Бареан Вествинд." }, { 2.12, "Командующий флотом Алого марша." }, { 4.84, "Гражданин Кул-Тираса." }, { 6.66, "Пропал без вести у берегов Нордскола." } } } },
    ["48dafba3"] = { d = 14.2, v = "narrator", c = { x = { { 0.00, "Со временем Ценарион стал другом Шу'хало и рассказывал им о мире." }, { 5.03, "Дети земли назвали его своим братом и поклялись помогать ему в заботе о полях жизни и любимых созданиях Матери-Земли." } } } },
    ["48fc54fe"] = { d = 8.0, v = "narrator", c = { x = { { 0.00, "РЯДОВЫЕ ЗВАНИЯ ОРДЫ." }, { 2.39, "Высший Сержант." }, { 4.19, "Старший Сержант." }, { 6.08, "Рубака." }, { 6.98, "Разведчик." } } } },
    ["4913db8f"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Сообщество собиралось на тенистых Тирисфальских лесах, где высшие эльфы впервые поселились в Лордероне." }, { 7.53, "Поэтому секта была названа \"Хранители Тирисфаля\"." }, { 11.23, "Смертные поборники, избранные быть Хранителями, получали огромную силу эльфийской и людской магии." }, { 18.44, "Хотя одновременно мог существовать только один такой поборник, Хранители были настолько могущественны, что могли и в одиночку расправиться со шпионами Легиона, где бы они их ни находили." } } } },
    ["4955a294"] = { d = 25.2, v = "narrator", c = { x = { { 0.00, "Король-лич Нер'зул знал, что времени у него мало." }, { 3.87, "Заключённый в Ледяном Троне, он подозревал что Кил'джеден попытается уничтожить его." }, { 10.35, "Заклятие Иллидана необратимо повредило Трон, и с каждым днём Король-лич становился всё слабее." }, { 17.60, "В надежде на спасение он призвал к себе своего величайшего смертного слугу – рыцаря смерти Артаса." } } } },
    ["495d3c94"] = { d = 47.1, v = "narrator", c = { x = { { 0.00, "Утёс Ветрорезов некогда был долиной вековых деревьев, а теперь это пни, чад и скрежет механизмов." }, { 8.19, "Торговая компания валит здесь лес с невиданной жадностью: по вырубкам ходят механические измельчители, а за лесопилкой у Скалистого озера присматривает прокажённый гном Геренцо, чьё тело наполовину заменено железом." }, { 26.09, "Нечистоты стекают в Волчью реку, и духи земли вопиют от боли." }, { 31.44, "Кела Копьё Тени и Гаксим Ржавошиппи стоят лагерем к западу от долины, а гоблин Зиз Физзикс по своим причинам жаждет гибели Геренцо." }, { 42.69, "На севере скрыт Туннель Когтя, ведущий в Ясеневый лес." } } } },
    ["4962c875"] = { d = 50.3, v = "narrator", c = { x = { { 0.00, "Крепость Каменной Стражи стоит на восточном берегу Озера Безмолвия, там, где река покидает озеро." }, { 7.98, "Её выстроили люди Приозёрья для защиты края, но орки клана Чёрной Горы, спустившиеся из Пылающих степей, взяли её штурмом с невиданной яростью: им помогала тёмная магия чародея Морганта." }, { 23.00, "Теперь здесь засел вождь орков Гат'Илзогг, отсюда его воины грабят земли к северу от озера, а отступники Тарил'зуна устраивают засады на дороге между городом и крепостью." }, { 36.92, "Чародеи Чёрной Горы принесли сюда полуночные сферы, источники тёмной силы." }, { 43.00, "Мировой судья Соломон объявил Гат'Илзогга в розыск, и награда за его голову ждёт смельчака." } } } },
    ["498141c9"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Праздник Зимнего Покрова." }, { 1.97, "Окончание года среди многих народов Азерота считается временем перемен." }, { 7.46, "Дворфы и Таурены особенно любят отмечать появление Зимнего Покрова, когда земля покрывается белым убранством, провозглашая тем самым время обновления." }, { 18.86, "И хотя сами сказания, сложенные по этому поводу разными народами Азерота, не слишком различны, способы, которыми они воздают почести этим легендам, многообразны, как и придумавшие их народности." } } } },
    ["499c55ab"] = { d = 21.4, v = "narrator", c = { x = { { 0.00, "Южный пляж лежит в сердце Азшары, по южному краю залива Бурь." }, { 5.46, "Его населяют наги, а с ними макрура, гидры, мурлоки и изредка морские великаны." }, { 12.58, "Весь берег усеян обломками колонн и стен — это остатки некогда великого Эльдарата, ушедшего под воду." } } } },
    ["49c9da85"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Сумеречный форт стоит в дальнем юго-западном углу Силитуса, к северо-западу от Стены Скарабея." }, { 7.49, "Это самый большой из лагерей Сумеречного Молота: среди палаток и алтарей сектанты вызывают через Ветровые Камни повелителей стихий, чтобы приблизить Последние Дни, о которых говорит их вера." }, { 22.53, "Стражи из камня и пламени, повелители земли и вихрей — все они слуги Совета Бездны, откликающиеся на зов культа." }, { 31.35, "Друиды Крепости Кенария давно следят за этим местом." } } } },
    ["49f6706d"] = { d = 33.5, v = "narrator", c = { x = { { 0.00, "Деревня Колкар — стойбище племени Колкар на восточной окраине Пустошей, между руинами Саргерона и озёрами Маграм." }, { 8.99, "Колкар — самое многочисленное племя кентавров Калимдора: их отряды грабят караваны в Степях и Дуротаре, и именно с ними первыми схлестнулась Орда." }, { 20.62, "Здесь, в родовых землях, правит вождь Дез'хеп, и Орда шлёт воинов ударить в самое сердце племени." }, { 28.32, "Другие племена тоже не любят Колкар и рады любому, кто их ослабит." } } } },
    ["4a43d995"] = { d = 16.1, v = "narrator", c = { x = { { 0.00, "Легенда гласит, что эти храбрые первопроходцы обнаружили источник Вечности, наделивший их невероятной силой." }, { 9.02, "Есть предположение, что именно от них произошли ночные эльфы, но точно это не известно." } } } },
    ["4a59379f"] = { d = 17.1, v = "narrator", c = { x = { { 0.00, "Эгвин, девушка из народа людей, заслужила одобрение Ордена и получила титул Хранителя." }, { 6.84, "Эгвин эффективно выслеживала и уничтожала демонов, но она очень часто подвергала сомнениям действия патриархального совета Тирисфаля." } } } },
    ["4a817487"] = { d = 26.9, v = "narrator", c = { x = { { 0.00, "Крипта — старое захоронение на юго-западе Восточных Чумных земель." }, { 5.04, "Здесь обосновалась шайка нежити-троллей под началом дикого тролля-изгоя, и они время от времени совершают вылазки к Часовне Последней Надежды за телами из могильника Серебряного Рассвета." }, { 19.20, "Здесь же стоит и могила, которую многие считают могилой паладина Тириона Фордринга, хотя сам он ещё жив." } } } },
    ["4a8935df"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "Скала Ренда, большая пещера в северо-западных горах Красногорья, лежит рядом с лагерем орков у перевала в Пылающие степи." }, { 9.37, "Внутри засели сильные воины клана Чёрной Горы, и соваться сюда в одиночку не стоит." }, { 15.76, "В этой пещере орки держат пленных: среди них капрал Кеешан, тяжело раненный солдат Штормграда, чей отряд попал в окружение." }, { 25.20, "Он ждёт, что кто-нибудь из сторонников Альянса поможет ему добраться до города." } } } },
    ["4ac44743"] = { d = 27.3, v = "human-male", c = { x = { { 0.00, "О чём я думал?" }, { 1.09, "Возможно, более лучшим был бы вопрос: о чём я думаю, когда пишу письмо, находясь в брюхе великана?" }, { 8.55, "Оба вопроса хороши, и ни на один у меня нет сейчас ответа…" }, { 13.04, "Следует признать, что моя миссия была не миссией доброй воли." }, { 17.79, "Я пришёл сюда в поисках азшарита, уникального кристалла из южной Азшары." }, { 23.22, "О, я был бы так богат!" }, { 24.85, "Ба!" }, { 25.12, "А теперь посмотрите на меня..." } } } },
    ["4ad39e62"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "Кроме того, они стали ниже ростом, а их кожа потеряла характерный фиолетовый оттенок." }, { 6.85, "Несмотря на трудности, они смогли противостоять многим неведомым существам, каких в Калимдоре и не видывали." }, { 15.33, "Они нашли племена диких людей, которые охотились в древних чащах." }, { 20.63, "Но самую большую угрозу представляли собой алчные и хитрые лесные тролли Зул'Амана." } } } },
    ["4adce818"] = { d = 24.5, v = "human-male", c = { x = { { 0.00, "Лорд Сильноплечий!" }, { 1.32, "Возглавляемое Эдвином ван Клифом братство Каменщиков состояло из лучших строителей среди людей." }, { 8.30, "Каменщики помогали восстанавливать Штормград, разрушенный до основания орками во время Первой войны. ван Клиф и его товарищи были непревзойдёнными зодчими." }, { 19.49, "Их вкус и чутьё отразились в величии Храма Света и Крепости Штормграда." } } } },
    ["4add203c"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Волчья река берёт начало у Скалистого озера и течёт через весь Утёс Ветрорезов до Рудника Ветрорезов." }, { 8.23, "Некогда её воды точили песчаник, вырезая в горах каньоны; теперь в неё сливают масло и отходы гоблинских лесопилок, и река стала чёрной и зловонной." }, { 20.45, "Таурены и орки говорят, что земля кричит от этой отравы." } } } },
    ["4af8fc91"] = { d = 45.4, v = "narrator", c = { x = { { 0.00, "Маззорил — огромная ледяная пещера в центральной части Зимних Ключей, к югу от Круговзора и недалеко от озера Кел'Терил." }, { 9.57, "Здесь обитают синие драконы, потомство Малигоса: в туннелях несут стражу драконьи отпрыски-чародеи и юные дракончики, а могучие драконы охраняют руны в глубине пещеры." }, { 22.93, "Хозяйка выводка — затворница, которую видят лишь в облике высшей эльфийки на вершине пещеры, куда ведёт руна-портал в полу." }, { 32.79, "Говорят, синие драконы держат здесь стражу с тех пор, как над вторым Источником Вечности выросло Древо Жизни, — они оберегают Нордрассил снизу, со склонов горы." } } } },
    ["4b053a3a"] = { d = 21.4, v = "dwarf-male", c = { x = { { 0.00, "Идеально круглый, от центра до края – локоть длины." }, { 4.39, "-По краю – заклёпки." }, { 6.06, "Серебряные." }, { 7.05, "-В центре – большой шип, диаметр основания – три пальца." }, { 11.75, "Серебряный." }, { 12.73, "-Сам щит из дуба, укреплённый железом." }, { 15.84, "-На наружном ободе выгравировать моё имя – Грингер Грозовая Вершина." } } } },
    ["4b064ba6"] = { d = 26.1, v = "human-male", c = { x = { { 0.00, "Достопочтенный мировой судья Соломон!" }, { 2.66, "Оплакиваю павших вместе с вами." }, { 4.94, "Я лично доложу королю о случившемся и надеюсь, что смогу убедить его отправить в Приозёрье подкрепление." }, { 12.22, "Его Величество в последнее время совершенно удалился от дел, и его поступки, признаться, меня удивляют." }, { 19.51, "Надеюсь, это останется между нами." }, { 22.04, "Искренне ваш," }, { 22.99, "Генерал Маркус Джонатан" }, { 24.70, "Королевство Штормград" } } } },
    ["4b11c92c"] = { d = 47.6, v = "narrator", c = { x = { { 0.00, "Приют у Солнечного Камня укрыт среди скал в сердце Когтистых гор, к югу от Мутного озера." }, { 7.37, "Говорят, в незапамятные времена сам Ан'ше коснулся этой горы, и таурены издревле совершали сюда паломничества: здесь тонка грань между миром живых и миром духов." }, { 20.63, "Ныне это главная застава Орды в горах, где таурены и орки пытаются исцелить землю, изувеченную Торговой компанией." }, { 30.14, "Маггран посылает отсюда воинов против гарпий, Таммра Поле Ветров растит семена Геи, а Мор'рогал тревожится о том, что скрыто под горами." }, { 41.42, "Ветрокрылы летают в Громовой Утёс, на Перекрёсток и в Деревню Ночных Охотников." } } } },
    ["4b337be2"] = { d = 40.6, v = "narrator", c = { x = { { 0.00, "Златоземье – главный посёлок Элвиннского леса, стоящий на перекрёстке дорог: к Штормграду, к аббатству Североземья, к Западному Краю и к Красногорью." }, { 11.46, "Деревня возникла ещё на заре королевства, в Первую войну одной из последних пала под натиском Орды, а после Второй войны была отстроена вместе со столицей." }, { 23.69, "Порядок здесь держит маршал Дугхан, чей стол завален донесениями о кобольдах, гноллах, мурлоках и бандитах." }, { 31.99, "Путники со всего королевства отдыхают в таверне «Гордость льва», одном из самых славных питейных домов Азерота." } } } },
    ["4b470376"] = { d = 18.6, v = "narrator", c = { x = { { 0.00, "Шли месяцы, и всё больше орков попадали в лагеря для военнопленных." }, { 5.13, "В них стало не хватать места, и Альянс был вынужден строить новые лагеря на равнинах к югу от Альтеракских гор." }, { 13.66, "Чтобы содержать их, королю Теренасу пришлось ввести новые налоги." } } } },
    ["4b512d6e"] = { d = 38.1, v = "narrator", c = { x = { { 0.00, "Долина Рваных Ран лежит к северу от водопада Отравленной Крови." }, { 5.23, "В Третью войну сюда с неба падали инферналы Пылающего Легиона, и до сих пор земля здесь изрыта дымящимися кратерами, залитыми осквернённой водой." }, { 17.02, "По долине бродят караульные-инферналы и энтропические звери и ужасы — порождения Скверны, не дающие земле зажить." }, { 26.30, "Друиды Изумрудного святилища шлют сюда разведчиков проверить, не высохли ли кратеры, а чернокнижники ищут среди камней останки инфернала Крошиуса." } } } },
    ["4bc467c6"] = { d = 35.5, v = "human-male", c = { x = { { 0.00, "После того как я вытащил косу, волна изменений прокатилась по шахте." }, { 4.62, "Свет от наших мерцающих факелов заметался, и казалось, что мы больше не контролируем силу нашего голоса." }, { 11.53, "То шёпот звучал, как рёв, мечущийся по туннелям, заставляя зажимать уши руками, то наши крики на расстоянии нескольких шагов переставали быть слышны и становились подобны лёгкому дуновению ветра." }, { 24.37, "Это нервировало, да, но недолго мы пытались понять странную природу этих явлений." }, { 29.84, "Это стало лишь предвестником того, что в действительности изгнало нас из шахты." }, { 35.06, "Воргены." } } } },
    ["4bcdcf4b"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Вулкан, известный как Чёрная гора, был окружён Тлеющим ущельем с севера и Пылающими степями с юга." }, { 7.82, "И хотя Тауриссан был убит силами, которые он призвал, его выжившие собратья были полностью порабощены Рагнаросом и его элементалями." }, { 18.55, "До сих пор они остаются в глубинах Чёрной горы." } } } },
    ["4bcee569"] = { d = 23.9, v = "human-male", c = { x = { { 0.00, "Самому мне, наверное, никогда не удалось бы достичь нынешних вершин знания." }, { 5.32, "Я очень благодарен ночным эльфам: без них я мало что сумел бы узнать." }, { 10.20, "Из своего опыта могу заключить, что Аспекты значат для них много больше, чем я предполагал." }, { 16.59, "Однако ночные эльфы бережно оберегают свои тайны, и даже я не могу быть до конца уверен в своей правоте." } } } },
    ["4c15bbdf"] = { d = 21.3, v = "dwarf-male", c = { x = { { 0.00, "Я знаю, насколько судьба королевства Стальгорн зависит от победы или поражения Альянса и насколько велик наш долг перед теми, кто раньше нас прошёл через кровь и страдания Великих войн." }, { 13.57, "И я готов полностью отказаться от всех радостей жизни, чтобы помочь поддержать Альянс и вернуть этот долг." } } } },
    ["4c25bc59"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Он всё-таки решил зайти на кладбище Вороньего Холма." }, { 4.48, "Морган несколько часов бродил среди могил." }, { 8.26, "Многие имена на надгробиях были ему знакомы, и чувство отчаяния захлёстывало его всё больше и больше." }, { 16.98, "И вдруг он увидел маленький неухоженный участок с тремя небольшими надгробиями." }, { 23.70, "Ужас обуял его, когда он подошёл поближе." }, { 27.33, "Морган смахнул пыль с самого большого надгробия, чтобы прочесть имя." }, { 33.27, "На камне были высечены буквы, которые сложились в" } } } },
    ["4c30e057"] = { d = 25.9, v = "narrator", c = { x = { { 0.00, "Могила Фаола лежит на востоке Тирисфаля, к юго-западу от Монастыря Алого ордена." }, { 6.41, "Здесь был похоронен почитаемый архиепископ Фаол, умерший ещё до прихода Плети." }, { 12.47, "В прежние времена к его могиле приходили паломники, ныне же она стоит заброшенной и почти забытой, а из разрушенной башни за холмом совершают вылазки люди капитана Мелраша." } } } },
    ["4ca92aa6"] = { d = 14.6, v = "narrator", c = { x = { { 0.00, "Но даже при поддержке высшего эльфа Аллерии Ветрокрылой, дворфа Курдрана Громового Молота и опытного воина Даната Троллебоя Кадгар не смог помешать Нер'зулу открыть порталы в другие миры." } } } },
    ["4cbd5b74"] = { d = 28.5, v = "narrator", c = { x = { { 0.00, "Колодец Буйногривых — самый северный из священных колодцев тауренов; он стоит чуть севернее Громового Утёса, там, где по равнине рыщут могучие волки прерий." }, { 11.87, "Назван он в честь племени Буйногривых." }, { 14.76, "Гоблины Торговой компании захватили и этот источник, и для его очищения нужен тотем из зубов лютых хищников." }, { 23.18, "Это последний колодец в цепи очищений, которые ведёт Мулл Громовой Рог." } } } },
    ["4d037978"] = { d = 16.8, v = "narrator", c = { x = { { 0.00, "Остановив Иллидана, Малфурион и Тиранда вернулись на родину, в Ясеневый лес, дабы охранять свой народ." }, { 7.98, "Однако Майев не согласилась отступить так просто – она последовала за Иллиданом в Запределье, чтобы покарать его." } } } },
    ["4d231d01"] = { d = 48.8, v = "scourge-male" },
    ["4d37559b"] = { d = 38.3, v = "narrator", c = { x = { { 0.00, "Луноречье на юго-западе края было шахтёрским городком, но теперь это лишь тень былого." }, { 6.88, "Жители давно бежали, и по опустевшим улицам расхаживают бандиты Братства Справедливости." }, { 13.90, "Именно здесь, под городом, лежат Мёртвые копи — заброшенная сеть штолен, которую Эдвин ван Клиф сделал своей цитаделью." }, { 23.28, "Шахтёры из Союза шахтёров погибли тут при обвале, устроенном Братством, и их беспокойные тени, говорят, до сих пор бродят в штольнях." }, { 33.60, "Дальше к югу поднимается гряда Холмов Разбойничьих Кинжалов." } } } },
    ["4d3bed70"] = { d = 30.8, v = "narrator", c = { x = { { 0.00, "Высокогорные дебри — огромный лес, покрывающий запад Фераласа от Забытого берега до реки Вердантис." }, { 8.24, "Под пологом древних деревьев водятся медведи и волки, кружат гиппогрифы, бродят древни, а в пещерах на склонах живут йети." }, { 18.51, "Здесь же, в юго-западной части дебрей, лежат руины Исильдиэна, занятые ограми Гордунни." }, { 25.78, "Тропы в этой чаще коварны, и путнику стоит держаться дороги." } } } },
    ["4d90c329"] = { d = 12.2, v = "orc-male" },
    ["4d9a00c1"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "ПАЛОЧКА-ПОГОНЯЛОЧКА ДЛЯ ШМЫГУНОСОВ" }, { 2.58, "Шмыгунос – поразительное животное." }, { 5.23, "Мало того что к нему может привязаться и полюбить его даже самый злобный долгоног, он может почуять запах корней синелиста за пятьдесят метров!" }, { 16.54, "Если вы пожелаете отправить вашего шмыгуноса на поиски корней, то вам понадобится ваша (продаётся отдельно) запатентованная палочка-погонялочка для шмыгуносов." }, { 28.68, "Инструкция по применению на следующей странице." } } } },
    ["4db0cfc1"] = { d = 23.7, v = "human-male", c = { x = { { 0.00, "Досточтимый господин!" }, { 1.41, "До меня дошли слухи, что вы ищете учителя для своих детей." }, { 5.29, "Сейчас я остановился в Златоземье, в таверне \"Гордость льва\" – из-за произошедших в регионе событий мне пришлось покинуть пост директора школы в Луноречье." }, { 15.29, "Я хотел бы стать учителем ваших детей." }, { 17.82, "При необходимости вы можете поговорить с директором Академии Крилланом о моей компетентности." } } } },
    ["4db19fee"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Немало могущественных людей услышали зов Короля-лича из Нордскола." }, { 5.34, "Среди них оказался Кел'Тузад, верховный даларанский маг, один из старейшин Кирин-Тора, совета Даларана." }, { 13.56, "В течение многих лет его считали отступником за желание изучать запретные искусства некромантии." } } } },
    ["4dcb7fc1"] = { d = 7.7, v = "narrator", c = { x = { { 0.00, "СУПЕРВАЖНАЯ КАРТА ДАННЫХ С ТРОЙНЫМ КОДОМ" }, { 3.72, "Дальше страница испещрена нулями и единицами." } } } },
    ["4ddae784"] = { d = 66.1, v = "narrator", c = { x = { { 0.00, "Азшара лежит на северо-востоке Калимдора, между Ясеневым лесом и Великим морем, южнее Зимних Ключей и севернее Дуротара." }, { 10.00, "Здесь царит вечная осень: листва рыжая и багряная, утёсы обрываются к пляжам, а над заливом Бурь гремят грозы." }, { 18.97, "Десять тысяч лет назад тут стоял Эльдарат, великий город высокорождённых; в Войне Древних и Великом Расколе большая его часть обрушилась в море, и ныне лишь обломки колонн цепляются за скалы, а остальное лежит под волнами." }, { 37.05, "Ночные эльфы считают эту землю проклятой: в руинах бродят призраки высокорождённых, в лагерях засели сатиры, а побережье держат наги Злобного Прибоя." }, { 49.33, "Реликвии Эльдарата стерегут синие драконы во главе с Азурегосом." }, { 54.62, "Орда держит на западе заставу Храбростан, Альянс — заставу Талрендис у моста через Строптивую, но дальше их костров Азшара пуста и безмолвна." } } } },
    ["4e1ceee5"] = { d = 30.2, v = "human-male", c = { x = { { 0.00, "Лорд Сильноплечий!" }, { 1.29, "Городской совет Озёр смиренно просит у вас военной помощи." }, { 5.47, "В то время как я пишу эти строки, нас держат в осаде орки Чёрной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту." }, { 14.41, "Я бы никогда не попросил о помощи, но мы в тяжёлом положении." }, { 18.66, "Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу вас оказать нам поддержку." }, { 25.41, "Падёт королевство – и все люди будут обречены." }, { 28.70, "Мировой судья Соломон" } } } },
    ["4e2e204c"] = { d = 19.0, v = "narrator", c = { x = { { 0.00, "Река Вердантис — небольшая быстрая река, что петляет по центру Фераласа к юго-востоку от Забытого Города." }, { 8.13, "Её прозрачная вода бежит по камням меж мшистых берегов, и рыбаки шепчут, что нигде больше в Азероте не водится такой рыбы, как в этих струях." } } } },
    ["4e3ca86c"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Кенарий призвал на помощь духов из зачарованного леса и собрал армию древних энтов, которые двинулись на Легион." }, { 8.74, "Когда союзники ночных эльфов встретились возле храма Азшары и источника Вечности, там завязалась ужасная битва." }, { 17.41, "Однако, несмотря на всю помощь своих новых союзников, Малфурион и его соратники поняли, что даже этих сил не хватит на то, чтобы остановить Легион." } } } },
    ["4e6a1fb2"] = { d = 28.6, v = "dwarf-male", c = { x = { { 0.00, "День шестой." }, { 0.98, "Медведь ещё не вернулся; должно быть, я задал ему хорошую трёпку!" }, { 6.02, "Но я всё ещё слышу его рычание." }, { 8.47, "Я думаю, он ждёт, когда я умру!" }, { 10.92, "Кто бы ни нашёл эту книгу, я прошу тебя." }, { 14.07, "Убей этого грязного медведя." }, { 16.39, "Убей его и отнеси книгу моему другу Молотоногу." }, { 20.24, "Он захочет узнать, что произошло." }, { 22.83, "И возьми мою броню." }, { 24.44, "Она понадобится тебе в бою со старым Паршивым Когтем!" } } } },
    ["4e9389e5"] = { d = 16.6, v = "narrator", c = { x = { { 0.00, "Орки были обречены на вечную неутолимую жажду крови и обрушивали свою ярость на любого, кто стоял у них на пути." }, { 9.32, "Гул'дан почувствовал, что время пришло, и объединил воюющие кланы в одну неудержимую Орду." } } } },
    ["4ec0830e"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Тем временем в дьявольском мире Дренора новая армия орков готовилась к нападению на ничего не подозревающий Альянс." }, { 8.96, "Бывший наставник Гул'дана Нер'зул собирал оставшиеся кланы орков под своими знамёнами." }, { 15.69, "С помощью клана Призрачной Луны он намеревался открыть на Дреноре несколько порталов, позволяющих Орде проникнуть в новые нетронутые миры." } } } },
    ["4ece7411"] = { d = 8.2, v = "narrator", c = { x = { { 0.00, "Принеси мне эти вещи, Звезду, Руку и Сердце, и Книга Йагина будет твоей." }, { 7.51, "— Джи Би." } } } },
    ["4eff26d4"] = { d = 38.0, v = "narrator", c = { x = { { 0.00, "Во все времена демонические существа пытались проникнуть в мир Титанов из Круговерти Пустоты, и Пантеон выбрал своего самого великого, Саргераса, чтобы он охранял границы миров." }, { 13.87, "Благородный гигант из расплавленной бронзы, Саргерас выполнял свои обязательства несчётное количество тысячелетий, находя и уничтожая демонов везде, где возможно." }, { 26.47, "Спустя века Саргерас столкнулся с двумя мощными демоническими расами, которые были помешаны на получении силы и господства над физической вселенной." } } } },
    ["4f1c3943"] = { d = 24.8, v = "narrator", c = { x = { { 0.00, "Долина Стражей лежит на юге Танариса, у самых ворот Ульдума." }, { 4.98, "Между отвесных скал бродят дюнные крушители — исполинские горные великаны, будто поставленные стеречь подступы к городу титанов." }, { 15.29, "Здесь, у запертых ворот, в одиночку несёт вахту геолог Ганстен из Лиги исследователей, ожидая дня, когда врата откроются." } } } },
    ["4f1c77b0"] = { d = 34.4, v = "human-male" },
    ["4f456546"] = { d = 12.9, v = "orc-male" },
    ["4f557657"] = { d = 29.7, v = "human-male", c = { x = { { 0.00, "От Бароса Алекстона," }, { 1.45, "Городского архитектора," }, { 3.08, "Штормград." }, { 3.84, "Ваше Величество," }, { 5.03, "Есть множество причин, по которым, мне кажется, должен быть составлен и предоставлен рапорт о недавних аферах \"Братства Справедливости\" и их активности в королевстве." }, { 16.42, "Для начала немного истории." }, { 18.37, "Как вы можете знать – а может быть, и нет – моё служение городу Штормград началось в качестве члена гильдии Каменщиков." }, { 26.55, "Спустя годы работы мы закончили восстановление" } } } },
    ["4f761f7e"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Ферма Стоунфилдов стоит на юге Элвинна, у самого рудника Подземных Глубин." }, { 5.99, "Стоунфилды давно враждуют с соседями Маклурами, и семьи не упускают случая уколоть друг друга." }, { 13.48, "Тем не менее, Томми Джо Стоунфилд и Мэйбелл Маклур полюбили друг друга, и есть надежда, что эта любовь помирит два дома." }, { 22.96, "Тётушка Бернис славится пирогами со свининой, а кабанов вокруг ферм водится видимо-невидимо." } } } },
    ["4f788679"] = { d = 27.0, v = "tauren-male", c = { x = { { 0.00, "Я скучаю по своему племени и по дому." }, { 3.88, "Как я тоскую по вольному ветру над равниной, по закатам над Громовым Утёсом!" }, { 11.54, "Но кругом только жаркие джунгли..." }, { 15.14, "Я вижу поблизости океан, но эти волны не охлаждают ни моё тело, ни мою тоску." }, { 23.16, "Они только напоминают мне о заточении." } } } },
    ["4f797df1"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Гоблинское инженерное дело" }, { 2.13, "Будучи расой, нейтрально относящейся практически ко всем конфликтам, гоблины сумели сделать науку доходным делом." }, { 11.07, "Они нашли практическое применение инженерному делу, столь очевидное в их великолепно разработанной взрывчатке, огнестрельном оружии и машинах." }, { 22.13, "Гоблинское инженерное дело не слишком заинтересовано в теории, их изобретения обычно не имеют тенденции не работать, скорее уж работают слишком хорошо." }, { 33.98, "Они точно не для слабонервных." } } } },
    ["4f7edb81"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "За шесть лет хитрые Арати победили и перехитрили все вражеские племена." }, { 5.80, "После каждой победы Арати предлагали завоёванным людям мир и равноправие, таким образом получая верность побеждённых." }, { 15.39, "В конце концов племя Арати включило в себя много других племён, а мощь их армии росла с огромной скоростью." } } } },
    ["4fb07193"] = { d = 10.0, v = "narrator", c = { x = { { 0.00, "Уровень секретности десять в степени десять тысяч." }, { 4.35, "Суперсекретные данные!" }, { 6.26, "Дальше страница испещрена нулями и единицами." } } } },
    ["50007b90"] = { d = 52.2, v = "narrator", c = { x = { { 0.00, "Чёрная гора — исполинский вулкан на северо-западе степей, рождённый в тот день, когда чародей-тан Тауриссан призвал в мир повелителя огня Рагнароса." }, { 12.07, "Во Вторую войну Орда сделала Пик Чёрной горы своей цитаделью, и у его подножия Оргрим Молот Рока сразил сэра Андуина Лотара." }, { 22.58, "Ныне гора поделена между врагами: в глубинах Тенегорна правят дворфы Чёрного Железа, ещё ниже, в Огненных Недрах, дремлет сам Рагнарос, а на вершине, в Логове Крыла Тьмы, чёрный дракон Нефариан плетёт свои замыслы." }, { 40.25, "Между ними стоят орки Ренда Чернорука, называющие себя истинной Ордой." }, { 46.28, "Через недра горы проходит и единственный путь из степей в Тлеющее ущелье." } } } },
    ["5000b58d"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "На островке посреди Нефритового озера растёт великое дерево Сонных Ветвей — одно из четырёх деревьев Азерота, у корней которых открыт портал в Изумрудный Сон." }, { 12.67, "Три других стоят в Ясеневом лесу, Сумеречном лесу и Внутренних землях." }, { 18.39, "Портал охраняют зелёные драконы и их драконьи отпрыски, не подпускающие чужих к священному месту." }, { 26.13, "Говорят, что с недавних пор сквозь такие порталы порой вырываются драконы, поражённые порчей, и тогда лес вокруг замирает в тревоге." } } } },
    ["50963d2b"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Нефритовое озеро — большое спокойное озеро на севере Фераласа, чья вода отливает зеленью." }, { 7.08, "В самой его середине лежит островок с великим деревом Сонных Ветвей, и потому берега стерегут зелёные драконьи отпрыски, охраняющие путь в Изумрудный Сон." }, { 19.18, "На северо-западном берегу встречаются заражённые дракончики — тревожный знак того, что даже здесь порча нашла лазейку." } } } },
    ["50ab55ad"] = { d = 21.2, v = "narrator", c = { x = { { 0.00, "Река Тондрорил течёт с севера и впадает в озеро Дарроумир, служа границей между Западными и Восточными Чумными землями." }, { 9.97, "Её берега облюбовали чумные медведи, летучие мыши-кровососы и пауки." }, { 15.74, "Мутная вода несёт с собой ту же заразу, что отравила всю эту землю." } } } },
    ["50d0f30e"] = { d = 25.1, v = "narrator", c = { x = { { 0.00, "Сторожевой пост — дозорная башня Терамора на материковом берегу, прямо напротив моста, ведущего к островному городу." }, { 8.86, "Отсюда стража следит за всеми, кто идёт по дороге к Терамору, и первой встречает и торговцев, и лазутчиков." }, { 16.96, "Место тихое, но караульные не дремлют: по эту сторону моста уже начинается болото со всеми его опасностями." } } } },
    ["50e706e3"] = { d = 26.8, v = "narrator", c = { x = { { 0.00, "Пылевая бухта — часть Великого моря между болотистым берегом и островом Терамор." }, { 6.38, "Её воды бурые от ила, что несёт болото, но именно сюда приходят корабли из Гавани Менетилов, ведь подводные скалы делают путь из Кабестана слишком опасным." }, { 18.58, "У берегов плавают черепахи и мурлоки, а к югу бухта переходит в залив, где живёт знаменитый рыбак Нэт Пэгл." } } } },
    ["5103fffd"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Крепость Бейл'дан — каменная твердыня дворфов, нависающая над раскопом Бейл Модана." }, { 6.55, "Гарнизон Стальгорна стережёт древние руины титанов и всё, что в них найдено, и встречает Орду огнём." }, { 14.23, "За её стенами дворфы чувствуют себя как дома, и лишь одинокий таурен Ганн Каменное Копьё напоминает, что земля эта прежде принадлежала его племени." } } } },
    ["513f53b2"] = { d = 42.6, v = "narrator", c = { x = { { 0.00, "Поместье Маррисов стоит на невысокой гряде у главной дороги, недалеко от границы с Западными Чумными землями." }, { 8.76, "Здесь жила семья следопыта Натаноса, единственного человека, которого эльфы Кель'Таласа приняли в ряды своих следопытов." }, { 18.38, "Когда Плеть захлестнула Лордерон, он погиб у собственного дома и был поднят как безвольный раб Короля-лича." }, { 26.85, "Ныне Натанос вернулся сюда уже Отрёкшимся, защитником Тёмной Госпожи, и его двор стерегут чумные псы." }, { 34.89, "Орде он даёт поручения против Плети и Алого ордена, а слухи о нём дошли и до ШРУ в Штормграде." } } } },
    ["5146732a"] = { d = 17.0, v = "narrator", c = { x = { { 0.00, "Увидев ужасное разрушение и огонь, распространившийся по южным горам, король Мадоран и король Кардрос остановили свои армии и спешно вернулись назад в свои королевства, не желая пасть жертвами ужасного гнева Рагнароса." } } } },
    ["516f3e6e"] = { d = 2.3, v = "narrator", c = { x = { { 0.00, "ДИАГРАММА ЗАПАДНОГО ПИЛОНА" } } } },
    ["5176e410"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Горемрак – глухая часть болота к востоку от озера Слёз и затонувшего храма." }, { 6.07, "Земля здесь принадлежит зелёным драконидам: они несут стражу вдоль берегов, а над топью кружит зелёный дракон, и путников тут не ждут." }, { 16.75, "Даже опытные охотники обходят Горемрак стороной – сюда идут лишь те, кто готов встретить драконью стражу лицом к лицу." } } } },
    ["51a1bd43"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Хилсбрад — городок в сердце Хилсбрадских полей, выросший вокруг ратуши." }, { 5.54, "Отсюда мировой судья Бернсайд и городской совет управляют окрестными фермами и Лазуритовым рудником." }, { 13.29, "Стражники здесь до сих пор носят цвета Лордерона: Хилсбрад и Южнобережье — единственные земли павшего королевства, которые не были разорены Третьей войной и не ушли под знамёна Алого ордена." }, { 27.75, "Верховный палач Дарталия считает город уязвимым и посылает сюда своих агентов." } } } },
    ["51ba14ce"] = { d = 30.7, v = "narrator", c = { x = { { 0.00, "Эти тролли, с кожей цвета мха, умели восстанавливать утраченные конечности и залечивать самые ужасные раны." }, { 8.56, "Но это был варварский, злой народ." }, { 11.26, "Империя Амани растянулась по большей части северного Лордерона, и тролли яростно боролись за свои земли, стараясь держать незваных гостей подальше от своих границ." }, { 24.31, "Эльфы всей душой ненавидели злобных троллей и убивали их при любом удобном случае." } } } },
    ["51c65e1d"] = { d = 28.9, v = "dwarf-male", c = { x = { { 0.00, "В эту экспедицию со мной отправились Ажек Руак и сэр Эс Джей Эрлгедин, а также мой верный слуга Барнил Каменный Кубок." }, { 8.82, "С отцом Ажек мы когда-то сражались за Альянс плечом к плечу." }, { 13.40, "Удивительно, как она выросла за это время." }, { 16.64, "Отец хорошо обучил её искусству владения оружием." }, { 20.41, "Её навыки стрельбы из лука настолько хороши, что невольно заставляют задуматься, не течёт ли в её жилах кровь эльфов." } } } },
    ["51c9f5b2"] = { d = 32.9, v = "narrator", c = { x = { { 0.00, "Лагерь О'Брина — стоянка пиратов Черноводья на песке бухты Фальдира." }, { 5.06, "Здесь под началом капитана О'Брина собрались выжившие моряки с единственного уцелевшего корабля экспедиции." }, { 12.80, "Наги с подводного рифа не дают им выйти в море, и команда коротает дни у костров, ожидая, когда найдётся кто-нибудь, кто поможет вернуть судовые журналы с затонувших судов." }, { 25.34, "При лагере возятся и двое гномов-инженеров с прибором, который учуял эльфийские самоцветы в камнях рифа." } } } },
    ["51d2e257"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "Кратер Криворука — глубокая воронка в северной части Мерцающей равнины." }, { 5.43, "Откуда она взялась, точно никто не скажет: то ли названа по имени того, кто её нашёл, то ли того, кто её сотворил, — а глядя на разбросанные вокруг обломки ракетных болидов, нетрудно догадаться, чьё изобретение здесь могло рвануть." }, { 22.66, "Теперь на дне кратера греются на соли солекаменные василиски." } } } },
    ["52234d91"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Вулкан, известный как Чёрная гора, был окружён Выжженной тесниной с севера и Пылающими степями с юга." }, { 7.99, "И хотя Тауриссан был убит силами, которые он призвал, его выжившие собратья были полностью порабощены Рагнаросом и его элементалями." }, { 18.65, "До сих пор они остаются в глубинах Чёрной горы." } } } },
    ["52c553d5"] = { d = 33.6, v = "narrator", c = { x = { { 0.00, "Но краккены – древние, очень древние твари." }, { 3.77, "Они помнили времена, когда земля впервые родилась из моря." }, { 8.92, "Они помнили владычество Древних Богов, они помнили, как явились Титаны и низвергли их." }, { 16.38, "Они помнили времена, когда магия была новой." }, { 20.38, "Они стары и помнят много тайн." }, { 23.07, "И хотя заклинание Мин'лота было могущественно, оно, подобно самим троллям, всё же было смертным." }, { 31.37, "И поэтому оно не сработало." } } } },
    ["52fc3d20"] = { d = 15.8, v = "tauren-male", c = { x = { { 0.00, "Жизнекорень:" }, { 1.07, "Он встречается в природе, а также может быть извлечён из тварей Сухой Лозы в Пылевых топях." }, { 8.80, "Его сила будет необходима для привлечения жизненной эссенции Циклониана в этот мир." } } } },
    ["530680db"] = { d = 25.3, v = "human-male", c = { x = { { 0.00, "Распространение сведений производите на своё усмотрение." }, { 3.56, "Тирисфальское региональное командование." }, { 6.14, "Капитан Мелроуз, капитан Вакон, капитан Перрин." }, { 9.29, "Указания даны самим верховным лордом." }, { 11.80, "Капитан Перрин, продолжайте укреплять позицию на юго-западной башне (как уже было сказано)." }, { 17.82, "Припасы подвезут позднее." }, { 19.52, "Материалы можно добывать на близлежащих фермах." }, { 22.61, "Не забывайте о разведке и сборе информации." } } } },
    ["5335e398"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Страх и решимость Артаса привели его к погибели." }, { 4.08, "Он желал уничтожить угрозу своей земле и ради этого добрался до источника чумы в Нордсколе, но сам пал жертвой могущества Короля-лича." }, { 15.40, "Надеясь спасти свой народ, Артас взял в руки проклятый рунический клинок, Ледяную Скорбь." } } } },
    ["53389c15"] = { d = 41.3, v = "narrator", c = { x = { { 0.00, "Гавань Менетилов стоит на острове в бухте Барадин и носит имя короля Теренаса Менетила Второго." }, { 7.78, "Дворфы Стальгорна и их союзники-люди отстроили здесь порт и крепость, и сегодня это единственное пристанище Альянса среди болот." }, { 18.01, "От причалов уходят корабли на запад, в Аубердин и в Терамор, а по дорогам из гавани расходятся торговцы и гонцы." }, { 26.95, "Над крышами возвышается крепость Менетил, а в таверне «Большая вода» у огня сходятся моряки, солдаты и странники." }, { 36.03, "Город невелик, но именно он связывает Каз Модан с далёкими берегами." } } } },
    ["537c101f"] = { d = 40.6, v = "gnome-male", c = { x = { { 0.00, "Джариен и Сотос, продолжение." }, { 2.07, "И вот они, наконец, начали проходить испытания, обязательные для всех, кто желает присоединиться к Алому маршу." }, { 9.72, "Они хотели, чтобы их приняли в рыцари, а для этого, по-видимому, и испытания были более сложными." }, { 16.56, "И Сотос не смог справиться со своим последним заданием." }, { 20.38, "Но Джариен заступилась за брата и настаивала на том, чтобы ему также позволили стать рыцарем." }, { 26.84, "По нашим сведениям, за такую дерзость Верховный рыцарь Датрохан лишил их жизни прямо у себя в покоях." }, { 33.99, "Посему Кровавый трон в Бастионе Алого ордена, что в Стратхольме, – ещё одно место с привидениями." } } } },
    ["538de565"] = { d = 35.4, v = "gnome-male", c = { x = { { 0.00, "Журнал механика." }, { 1.19, "(Небольшой журнал в кожаной обложке вымазан маслом и жиром." }, { 5.38, "Наброски чертежей и механических приспособлений сопровождаются подписями и объяснениями." }, { 11.40, "Вы открываете страницу наобум.) Этот заказ прокормит меня на годы вперёд." }, { 16.53, "Только доработаю нейтрализатор колебаний, который то перегревается, то истирается в металлическую стружку." }, { 23.79, "Надо отвести избыток тепла по воронке в ядро сгорания, но я откладываю и откладываю, потому что придётся вскрывать мехаход и разбирать весь двигатель." }, { 34.13, "Страница семнадцать" } } } },
    ["5397822e"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Долина Солевого Тумана — небольшая низина на северо-западе Болотины, между Болотами Синежабрых и Гробницей Железноборода, открытая бухте Барадин." }, { 11.10, "Своё имя она получила за то, что при сильном ветре с залива море забрасывает солёные брызги далеко вглубь суши." }, { 19.53, "Как и на других болотах, здесь гнездятся ящеры, и их следы видны на мокрой земле повсюду." } } } },
    ["53d342f6"] = { d = 33.2, v = "narrator", c = { x = { { 0.00, "Мин'лот ревел, его магия вобрала силу заклинаний его помощников, и Мин'лот направил её на приближающихся краккенов." }, { 9.85, "Море расступилось, и заклинание Мин'лота устремилось к слугам Нептулона." }, { 15.95, "Молния разорвала небо, и заклинание поразило их, и тысячи огненных стрел рухнули вниз." }, { 23.20, "Вода закипела, дно покрылось кратерами." }, { 26.56, "Мин'лот торжествующе вскричал, зная, что его заклинание сразит огромных тварей." } } } },
    ["53fd752d"] = { d = 22.9, v = "dwarf-male", c = { x = { { 0.00, "Покинув Вотчину, я направлюсь в Тысячу Игл, а затем на запад в сторону Таланаара, к границе с таинственным лесом Фералас." }, { 8.89, "Там я найду друида, известного как Хранитель дорог Фалфиндел." }, { 13.40, "Пытаясь узнать прошлое моего народа, я, кажется, наткнулся на что-то большее." }, { 19.18, "Теперь в моих руках – безопасность всего Альянса..." } } } },
    ["54020e2f"] = { d = 32.4, v = "narrator", c = { x = { { 0.00, "Несмотря на то что практически бесконечной силы Саргераса с избытком хватало, чтобы победить зловещих эредаров, он был весьма обеспокоен разрушением и всепоглощающим злом, распространяемыми этими созданиями." }, { 16.13, "Неспособный понять такую развращённость, великий титан начал погружаться в отчаяние." }, { 22.77, "Несмотря на свою растущую тревогу, Саргерас всё же избавил вселенную от колдунов, заманив их в ловушку в Круговерти Пустоты." } } } },
    ["541b4985"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "Хрустальное озеро лежит к востоку от Златоземья, и его чистые воды издавна кормили рыбаков и фермеров округи." }, { 8.60, "Сюда несёт свои воды река из Североземья." }, { 11.89, "Ныне на берегах расселились мурлоки, и неопытному путнику здесь может быть опасно." }, { 18.25, "Впрочем, эти существа иногда приносят из океана редкие водоросли, которые ценит аптекарь Вильям Пест из Златоземья." } } } },
    ["5469f284"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Пока Тралл был занят освобождением своих собратьев в Лордероне, Нер'зул продолжал строить базу в Нордсколе." }, { 8.46, "Над Ледяной Короной он возвёл огромную крепость, в которой трудились легионы мертвецов." }, { 15.28, "Но нашлась одна империя, готовая противостоять растущему могуществу Короля-лича." } } } },
    ["54deafbb"] = { d = 31.4, v = "human-female", c = { x = { { 0.00, "Частенько последователи Священного Света запугивают тех, кто интересуется настоящей силой, пытаясь убедить их, что тайная магия непознаваема." }, { 10.05, "Но не всё, что приходит извне, является злом." }, { 13.23, "Не всё сущности стремятся подчинить себе других." }, { 16.73, "Если у тебя будет достаточно силы, те же самые сущности станут твоими слугами." }, { 22.51, "Об этом я хотела бы поговорить с тобой." }, { 25.36, "Жду тебя на кладбище справа от аббатства." }, { 28.34, "-Друзилла ла Салле, наставница чернокнижников" } } } },
    ["54e11849"] = { d = 23.0, v = "human-female", c = { x = { { 0.00, "Когда представилась возможность, я всадила нож ему в спину!" }, { 4.33, "Его лёгкие не выдержали силы удара, и его тело упало на землю с глухим звуком." }, { 10.18, "Это было такое быстрое и молниеносное нападение, что бедный глупец даже не успел закричать от боли." }, { 17.54, "Странно, но когда я вынула нож из его спины, из раны хлынул зловонный запах." } } } },
    ["54ee13b9"] = { d = 25.9, v = "narrator", c = { x = { { 0.00, "Гордая Эгвин хотела родить сына, которому она передаст свою силу." }, { 5.33, "Она не хотела, чтобы Тирисфальский орден манипулировал её преемником так же, как они пытались манипулировать ей." }, { 13.95, "Отправившись в южное государство Азерот, Эгвин нашла идеального мужчину, который мог бы стать отцом её сына – искусного человека-мага по имени Ниелас Аран." } } } },
    ["5526c6eb"] = { d = 13.4, v = "dwarf-male", c = { x = { { 0.00, "Оплата будет произведена обычным способом." }, { 3.09, "И расплатись с подателем сего письма за доставку." }, { 6.62, "Эти деньги можешь прибавить к цене щита." }, { 9.65, "Премного тебе благодарен," }, { 11.51, "--Грингер Грозовая Вершина." } } } },
    ["555f4459"] = { d = 21.8, v = "human-male", c = { x = { { 0.00, "...какое странное и неконтролируемое чувство." }, { 3.04, "Я никогда ещё не чувствовал ничего подобного." }, { 6.09, "Пока я занимался с Джайлсом историей, Тиллоа прогуливалась в палисаднике снаружи." }, { 11.57, "Через несколько минут она вернулась к нам, положила мне в ладонь ярко-красную бегонию и так улыбнулась мне, что у меня чуть сердце не выскочило из груди..." } } } },
    ["5565a54b"] = { d = 9.0, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ." }, { 2.49, "Часть один." }, { 3.68, "Верховный Вождь." }, { 5.34, "Генерал." }, { 6.26, "Лейтенант-генерал." }, { 8.20, "Защитник." } } } },
    ["55d39a6a"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Сухая лощина — узкий каньон на севере Дуротара, куда с земли можно попасть лишь через небольшую пещеру из Каньона Колючего Ветра." }, { 10.12, "Здесь свили гнёзда гарпии Пыльного Ветра." }, { 13.31, "Они промышляют разбоем, грабят караваны Орды и стаскивают добычу на высокие уступы." }, { 19.82, "Самые сильные из гарпий стерегут кладки яиц, и чужаков здесь встречают когтями." } } } },
    ["55e5af02"] = { d = 32.7, v = "human-male", c = { x = { { 0.00, "Йорген, мои худшие ожидания оправдались, сбылось то, чего я и представить не мог." }, { 5.49, "Я никогда не думал, что они подберутся так близко, но это случилось." }, { 10.12, "Пожалуйста, помоги подателю сего письма и отправь его к НЕМУ." }, { 14.39, "Откровенно говоря, я думаю, что он поможет нам из-за серьёзности этого дела." }, { 19.51, "Если бы нам грозило что-то другое, он, возможно, так и не обратил бы внимания на нас и на проблемы нашего славного города." }, { 27.68, "Спасибо тебе, старый рыбак." }, { 29.63, "Я, как обычно, у тебя в долгу." }, { 31.70, "Твой друг" }, { 32.31, "Делавей" } } } },
    ["56189a7e"] = { d = 32.6, v = "narrator", c = { x = { { 0.00, "Долина Промозглого Ветра лежит между Гномреганом на западе и Караносом на востоке." }, { 6.81, "По её широкой части проходит оживлённая дорога, а вот в узкий южный отрог заглядывают немногие: снег там залит кровью, а вокруг разбросаны растерзанные туши." }, { 19.61, "В тамошних пещерах обитают вендиго, и не всякий, кто отправился на охоту за ними, вернулся назад." }, { 27.61, "Ветер в долине действительно промозглый, как и обещает её имя." } } } },
    ["567c7025"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Когда Кель понял, что не сможет найти средство от магической зависимости своего народа, он совершил непоправимое." }, { 8.82, "Вспомнив об общих предках-высокорожденных, он встал на сторону Иллидана и его спутников-наг." }, { 15.95, "Остальные предводители Альянса объявили эльфов крови предателями и изгнали их навсегда." } } } },
    ["568be502"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Башня Северного перевала — самая северная из дозорных башен края, у дороги, что ведёт к перевалу в Кель'Талас." }, { 8.47, "Плеть разрушила её при вторжении, и от башни остались руины." }, { 13.06, "Теперь Альянс и Орда оспаривают их друг у друга: тот, кто удержит башню, получает преимущество на землях вокруг." } } } },
    ["569c2df1"] = { d = 33.0, v = "human-male", c = { x = { { 0.00, "В память о моём дорогом учителе, Горацио М." }, { 3.39, "Монтгомери, докторе медицины, целителе, учителе, друге." }, { 7.77, "Пятьдесят би-ти-эф-ти – двадцать пять эй-ти-эф-ти" }, { 11.44, "\"Мир полон боли и тягот." }, { 13.41, "Наша задача как целителей, НЕТ – мужчин или женщин, отдавших себя медицине, очистить его от всех болезней.\"" }, { 21.89, "- Почётный работник медицины, доктор медицины, доктор философии, доктор юридических наук, Великий Фермер, Экстраординарный Танцор, Друг Животных" } } } },
    ["569ebc60"] = { d = 28.5, v = "narrator", c = { x = { { 0.00, "Холм Демонического Огня возвышается к юго-востоку от заставы Расщеплённого Дерева." }, { 6.35, "В Третью войну сюда с неба обрушились инферналы Пылающего Легиона, и с тех пор земля здесь выжжена, а по склонам бродят демоны всех мастей." }, { 17.21, "Орда укрепила оба моста, ведущие к холму, чтобы демоны не добрались до её лагерей." }, { 23.76, "Отсюда скверна тянется дальше на юг, к Каньону Гибели Демона." } } } },
    ["56a8f44a"] = { d = 19.0, v = "human-male", c = { x = { { 0.00, "Тому, Кого Это Касается." }, { 1.80, "Если ты читаешь это письмо, то я могу лишь предположить, что ты в двух местах:" }, { 7.13, "(один) На южном полуострове Азшары." }, { 9.61, "(два) В брюхе скального великана." }, { 11.91, "И то, и другое одинаково нежелательно." }, { 14.51, "Следует заметить, что я некогда был в первом, а теперь – во втором." } } } },
    ["56b6c2f1"] = { d = 17.8, v = "narrator", c = { x = { { 0.00, "Глава один: СЕВЕРНЫЙ ПИЛОН." }, { 2.49, "Северный пилон принимает жёлтые, красные и зелёные кристаллы." }, { 7.71, "Пилон фокусирует энергию, которая возникает при использовании жёлтых кристаллов в качестве основного источника энергии." } } } },
    ["56e87c2e"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Озеро Безмолвия раскинулось в самом сердце Красногорья, и его прозрачные лазурные воды отражают красные склоны гор." }, { 9.16, "На западном берегу стоит Приозёрье, а с востока озеро вытекает рекой, что бежит мимо тёмной крепости Каменной Стражи." }, { 18.33, "Когда-то эти воды славились рыбной ловлей, но теперь по берегам селятся всё новые племена мурлоков." }, { 26.22, "Дети Приозёрья по-прежнему удят рыбу с причала, хотя родители и пугают их чудовищами, живущими в глубине." } } } },
    ["56ef770e"] = { d = 2.5, v = "narrator", c = { x = { { 0.00, "ДИАГРАММА ЗАПАДНОГО ПИЛОНА" } } } },
    ["5706573b"] = { d = 54.5, v = "narrator", c = { x = { { 0.00, "Зул'Фаррак — выжженный солнцем город троллей племени Песчаной Бури на северо-западе Танариса." }, { 7.43, "Когда-то он стоял среди джунглей империи Гурубаши, но после Раскола тролли оказались отрезаны в пустыне и приспособились к ней, став песчаными троллями, известными жестокостью и тёмной магией." }, { 22.36, "Вождь Укорз Песчаный Череп мечтает вернуть племени былое величие, а знахари поднимают мертвецов из городских могил." }, { 31.49, "Легенды говорят о клинке, разрубленном надвое и спрятанном в этих стенах, и о наёмниках из Прибамбасска, попавших здесь в плен." }, { 41.26, "Страшнее всего шёпот о древнем существе в священном пруду в сердце города: тролли поклоняются гидре Газ'рилле как божеству и будят её лишь тогда, когда есть чем накормить." } } } },
    ["57193d7b"] = { d = 26.4, v = "human-male", c = { x = { { 0.00, "Зная Эдвина ван Клифа всю свою жизнь, я могу сказать, что видеть в нём своего врага мне неприятно." }, { 7.27, "Понимаете, он был моим другом детства, и я лично наставлял его в магии Теней, надеясь, что однажды он будет работать вместе со мной." }, { 17.08, "Если ван Клиф стоит во главе Братства Справедливости, то да помилует Свет наши души!" }, { 23.28, "Мастер Матиас Шоу" }, { 24.68, "Гильдия убийц Штормграда" } } } },
    ["572508fd"] = { d = 32.1, v = "dwarf-male", c = { x = { { 0.00, "Ажек не понадобилось много времени, чтобы выследить пантеру; она ушла на юго-запад." }, { 6.09, "Мы шли быстрым шагом, с оружием наготове, и уже предвкушали успех." }, { 10.83, "Треск веток, донёсшийся из рощи неподалёку, немедленно привлёк наше внимание." }, { 16.14, "Там кто-то был." }, { 17.23, "Одного взгляда на Барнила хватило, чтобы он понял меня." }, { 21.27, "Он медленно опустил винтовку." }, { 23.38, "Эта добыча – не для нас, а для наших спутников-людей." }, { 27.16, "Сколько пантер уже погибло от наших пуль!" }, { 30.17, "Нет, эта добыча – не для нас." } } } },
    ["57963e57"] = { d = 14.7, v = "narrator", c = { x = { { 0.00, "Когда Медиву было четырнадцать, в нём проснулась великая сила, которая не могла ужиться с дремлющим внутри него духом Саргераса." }, { 10.66, "Медив впал в глубокий сон, продлившийся не один год." } } } },
    ["57ca42d2"] = { d = 17.8, v = "human-male", c = { x = { { 0.00, "Агашам!" }, { 0.62, "Вместе мы будем гораздо сильнее, чем все племена тауренов вместе взятые!" }, { 6.25, "Всё же мы настаиваем на вашем полном подчинении." }, { 9.93, "Помните, ваш народ получит вознаграждение только после воплощения наших замыслов!" }, { 16.24, "Подпись:" }, { 16.94, "Вестник Рекс" } } } },
    ["58241b0b"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Светлая роща лежит к западу от Темнолесья, по обе стороны дороги." }, { 5.13, "Название осталось от прежних времён: сейчас немногие дома на краю рощи лежат в развалинах, а по тёмным полям рыщут воргены из стаи Ночной Погибели, разбивая грубые стоянки и набрасываясь на всякого, кто подойдёт слишком близко." }, { 22.52, "Ночной дозор посылает сюда новичков прореживать стаю, чтобы воргены не подступали к городским стенам." }, { 30.42, "Среди руин порой попадаются забытые сундуки, за которыми стоит поглядывать." } } } },
    ["5827e1ac"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Крепость Чёрной горы раскинулась на севере степей, у самого входа в вулкан." }, { 5.84, "Это главное поселение орков клана Чёрной горы за пределами Пика — они не признали перемирия Тралла с Альянсом и живут по старым обычаям Первой и Второй войн." }, { 18.07, "Орки добывают в окрестных горах руду, куют оружие и доспехи и постоянно готовятся к походу на юг." }, { 25.64, "Крепость укрыта от дороги, но дозорные всегда следят за подступами, и всякого чужака здесь ждёт бой с рубаками и чародеями клана." } } } },
    ["583fbecd"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Остров Алькац лежит у северо-восточного побережья топей и не похож на них: здесь растут пальмы, как на Островах Эха." }, { 9.48, "Некогда на острове жили люди, но их сменили наги Страшаза, а в водах вокруг кишат гидры." }, { 16.84, "Наги словно охраняют нечто спрятанное в подземных ходах острова, и никто не знает, что именно." }, { 24.63, "Недавно на Алькац прилетел на летающей машине безумный гном-изобретатель со своими послушными прислужниками, и остров стал ещё опаснее." } } } },
    ["5862a323"] = { d = 17.2, v = "narrator", c = { x = { { 0.00, "Моровой овраг — глубокое ущелье в отравленной земле к западу от часовни Последней Надежды." }, { 7.27, "Похоже, некогда здесь было озеро, высохшее, когда пришла чума." }, { 12.38, "По дну расселины ползают слизни, и путники обходят её по краю." } } } },
    ["5876b562"] = { d = 30.3, v = "narrator", c = { x = { { 0.00, "Великий Подъёмник — огромная деревянная машина, построенная тауренами на северной стене каньона." }, { 7.60, "Она соединяет Тысячу Игл с южным обрывом Степей: с верхней площадки видны вершины игл, а внизу начинается дорога к Заставе Вольного Ветра." }, { 18.71, "Подъёмник стерегут таурены-стражи, но путь к нему сверху год от года становится опаснее — свинобразы Южных Степей всё шире раздвигают свои владения." } } } },
    ["58894742"] = { d = 32.1, v = "goblin-male", c = { x = { { 0.00, "Сбалансированная шпага Сталлинна-" }, { 2.40, "И последнее: я хочу вернуть одну из моих лучших кузнечных работ." }, { 7.13, "Эта шпага – невероятное оружие, и я подарил его тому, кого я считал весьма благородным и великим воином." }, { 14.78, "В общем, его побил мурлок по имени... как его там, Джаркай?" }, { 19.13, "Как-то так." }, { 19.97, "Он подвергся атаке этого чудища во время своего путешествия по берегу Болота Печали." }, { 26.13, "Он проиграл сражение и, видимо, обратился в бегство, оставив оружие в лапах мурлока." } } } },
    ["58941db2"] = { d = 31.1, v = "human-male", c = { x = { { 0.00, "...меня переполняют гнев и ярость!" }, { 2.51, "Да как она смеет!" }, { 3.83, "Пока я занимался с Джайлсом арифметикой, вошла Тиллоа с каким-то ухажёром, они невинно держались за руки!" }, { 11.57, "Какой-то неотёсанный молодой человек." }, { 14.28, "Вместо того чтобы представить меня как подобает, Тиллоа просто сказала: \"О, это мой учитель, дядя Сталван\"." }, { 22.28, "Дядя!" }, { 22.74, "Услышав такое, я почувствовал как пылают мои щёки." }, { 26.44, "Я всего лишь на несколько лет старше!" }, { 29.15, "И ещё... это предательство..." } } } },
    ["5894686a"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Руины Жубуваля лежат к востоку от Арены Гурубаши, у главной дороги, что тянется через всю долину." }, { 7.71, "Их населяют слуги Занзила Отверженного — наги, тролли и мертвецы, одурманенные его зельем." }, { 14.85, "Среди них скрываются и должники сурового капитана МакКинли из Пиратской бухты, прозванного Морским волком." } } } },
    ["589d62ed"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Холм Мош'Огг — логово огров племени Мош'Огг к югу от Зул'Гуруба." }, { 5.31, "В глубине пещеры правит огр-маг, владеющий могущественной реликвией, с помощью которой он подчинил разум полковника Курцена." }, { 15.50, "Огры грабят караваны Орды, идущие в Каменор, и держат в страхе окрестные джунгли." }, { 22.29, "Задолго до огров эта пещера была святилищем троллей." } } } },
    ["58c3faec"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Грандиозные битвы Второй войны сотрясали море и воздух." }, { 4.66, "Каким-то образом Орде удалось завладеть могущественным артефактом – Душой Демона – и с его помощью подчинить себе Алекстразу, древнюю королеву драконов." }, { 17.23, "Угрожая уничтожить отложенные ею яйца, Орда заставила Алекстразу отправить своих детей на войну." }, { 25.30, "Благородные красные драконы были вынуждены сражаться на стороне Орды, и сражались они превосходно." } } } },
    ["58cb2d7a"] = { d = 23.8, v = "narrator", c = { x = { { 0.00, "Поэтому они решили скрыть свои земли защитным барьером, который позволял бы им спокойно заниматься магией." }, { 8.01, "Они установили в разных точках Кель'Таласа, на границах магического барьера, цепь Рунических камней." }, { 15.49, "Рунические камни не только скрывали магию эльфов от внеземных угроз, но и помогали отпугивать суеверных троллей." } } } },
    ["58e6eb6d"] = { d = 17.9, v = "narrator", c = { x = { { 0.00, "Даже практически оставшись без сил, Артас сумел опередить Иллидана и первым добраться до Ледяного Трона." }, { 8.12, "Своим рунным мечом, Ледяной Скорбью, Артас разрушил ледяную тюрьму, а потом забрал из неё зачарованный шлем и доспехи Нер'зула." } } } },
    ["59142c7a"] = { d = 39.3, v = "narrator", c = { x = { { 0.00, "Болотное пристанище – деревня Заблудших на севере Болота Печали, в виду гор Красногорья." }, { 7.18, "Здесь живут те, кого путь через Тёмный портал и тоска по утраченной родине довели до безумия: они одичали и нападают на всякого, кто подойдёт к их хижинам и кострам." }, { 20.30, "Заблудшие грабят караваны на дороге и воруют у своих бывших братьев из Убежища священные для тех кристаллы." }, { 28.92, "В клетке посреди селения томится пленник – человек по имени Гален Добростраж, отчаянно ждущий, что кто-нибудь выведет его отсюда." } } } },
    ["59288f69"] = { d = 19.4, v = "human-male", c = { x = { { 0.00, "Наши планы продвигаются споро; как я уже упоминал, мы заключили союз с группой людей, называющих себя Синдикатом." }, { 8.38, "Их лидеры когда-то принадлежали к Альтеракской знати, и они жаждут вновь править там." }, { 14.57, "Итак, они заключили с нами сделку." }, { 17.21, "Сделку, о которой они пожалеют." } } } },
    ["59645b1d"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Лощина Тьмы — потайное убежище культа Пылающего Клинка в горах на юго-востоке Пустошей, за землями Маграм." }, { 8.66, "Среди исполинских грибов и скал культисты выстроили круг призыва, опутанный огромными цепями, и здесь, вдали от чужих глаз, свободно творят обряды призыва демонов." }, { 21.76, "Чернокнижники культа охраняют лощину вместе с призванными тварями, и мало кто из путников знает, что за этими перевалами зреет угроза для всех Пустошей." } } } },
    ["5974f518"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Перекрёсток Висельников — развилка дорог у подножия руин Альтерака, где над старым трактом стоит разрушенная сторожевая башня." }, { 9.82, "Земля здесь принадлежит ограм Раздробленного Хребта: их дозоры кружат вокруг башни и стерегут путь из Хилсбрада к северным перевалам." }, { 20.21, "Мрачное имя перекрёстка напоминает о временах, когда здесь вершился суд павшего королевства." } } } },
    ["597b7256"] = { d = 33.1, g = 1, v = "human-male", c = { m = { { 0.00, "Скажи-ка мне, герой, ты когда-нибудь слышал боевой клич орков?" }, { 4.41, "А может быть, ты защищал свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким?" }, { 11.05, "Жутковато звучит, не правда ли?" }, { 13.29, "Что ж, тебе пригодится моя помощь." }, { 15.78, "Меня можно найти в североземском аббатстве." }, { 18.91, "Мои знания стоят недёшево, но если ты достаточно опытен, я могу научить тебя приёмам и хитростям, которые помогут тебе защищать Штормград и наши земли." }, { 29.70, "Ллан Бишер, наставник воинов" } }, f = { { 0.00, "Скажи-ка мне, героиня, ты когда-нибудь слышала боевой клич орков?" }, { 4.78, "А может быть, ты защищала свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким?" }, { 11.75, "Жутковато звучит, не правда ли?" }, { 14.08, "Что ж, тебе пригодится моя помощь." }, { 16.67, "Меня можно найти в североземском аббатстве." }, { 19.92, "Мои знания стоят недёшево, но если ты достаточно опытна, я могу научить тебя приёмам и хитростям, которые помогут тебе защищать Штормград и наши земли." }, { 31.14, "Ллан Бишер, наставник воинов" } } } },
    ["59993071"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Лагерь Оленьего Шлема — ночноэльфийская башня на вершине пика в северо-восточном Силитусе." }, { 7.32, "Она носит имя рода Оленьего Шлема: верховного друида Фэндрала, что вёл ночных эльфов в Войне Зыбучих песков, и его сына Вальстана, павшего в ней." }, { 19.22, "На вершине несёт вахту страж ночных эльфов, а над башней кружит бронзовый дракон из выводка Ноздорму." }, { 27.34, "У подножия горы, чуть ниже по дороге, зияет вход в Сумеречную пещеру, и с башни за ним следят неотступно." } } } },
    ["59a6f36e"] = { d = 35.5, v = "human-male", c = { x = { { 0.00, "*(Из-за пятен возможно прочесть лишь часть журнала.)*" }, { 4.32, "Ульдаман, День три" }, { 5.65, "Поверить не могу, как я был глуп." }, { 8.05, "Эти злобные дворфы Кузни теней провели меня, как простачка." }, { 12.59, "Мои раны заживают медленно, я безусловно отравлен ядом." }, { 16.79, "Я чувствую, как мои силы тают." }, { 19.13, "Несмотря на это я должен двигаться вперёд..." }, { 22.39, "...хуже того, ожерелье, что сделал для меня гном, треснуло!" }, { 26.80, "Три его самых больших драгоценных камня потеряны." }, { 30.53, "Я должен найти их, без них ожерелье будет лишено всей своей силы....." } } } },
    ["59c5c67e"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Прошло время, и Ценарион стал сильным, как его великий отец." }, { 5.24, "Брат деревьев и звёзд, этот великий охотник странствовал по миру, напевая умиротворяющую песню рассвета." }, { 14.11, "Всё живое склонялось перед его грацией и красотой." }, { 18.51, "Никого на свете не было мудрее сына луны и белого оленя." } } } },
    ["59ec350a"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Два королевства некоторое время поддерживали довольно тесную связь, но на клан Громового Молота слишком сильно повлияли ужасы, свидетелями которых дворфы стали у Грим Батола." }, { 13.05, "Вместо того чтобы создать огромное подземное царство, они обжили склоны Заоблачного пика." }, { 19.98, "Идеологические различия между двумя оставшимися кланами дворфов в конце концов привели к отчуждению." } } } },
    ["59f0be2a"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Подгорная тропа — тоннель в северо-восточных горах, соединяющий Тлеющее ущелье с Долиной Королей в Лок Модане." }, { 8.17, "Его, как и великую плотину Лок Модана, спроектировал древний дворфийский зодчий, создатель подгорного стиля строительства." }, { 17.13, "С обеих сторон тоннель заперт коваными воротами: когда Чёрное Железо захватило ущелье, гарнизоны Стальгорна отступили и закрыли проход." }, { 27.09, "Ключ хранит горный пехотинец Щебеночка, стерегущая ворота со стороны Лок Модана, и отдаёт его лишь тем, кто докажет, что одолел Маргола Яростня." } } } },
    ["5a025a0e"] = { d = 12.4, v = "creature/ancient", c = { x = { { 0.00, "Клинфран Безумный:" }, { 1.94, "Он блуждает по Пылающим степям." }, { 5.18, "Приближайся к нему с осторожностью и вынуди его показать истинное лицо." } } } },
    ["5a02a832"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Озёрный тракт, старая дорога, огибает Озеро Безмолвия с юга." }, { 4.92, "До Первой войны по ней шли обозы и путники, но с тех пор как орки взяли крепость Каменной Стражи, тракт опустел." }, { 13.96, "Теперь вдоль южной дороги стоят лагеря гноллов стаи Красногорья: браконьеры и полукровки подстерегают редких прохожих." }, { 23.74, "Заместитель судьи Фелдон обходит участок к югу от моста, но людей у города не хватает, и дорога считается небезопасной." } } } },
    ["5a0f9d47"] = { d = 25.1, v = "narrator", c = { x = { { 0.00, "Коварный риф — полоса пёстрых кораллов у западного берега долины, близ лагеря Гром'гол." }, { 6.65, "Под водой лежат затонувшие троллиные руины, где среди развалин живут мурлоки, а между кораллами прячутся гигантские моллюски, в которых, по слухам, зреет голубой жемчуг." }, { 19.73, "Волны прибивают сюда обломки кораблей, а с берега на риф приходят наги." } } } },
    ["5a163554"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Ночные эльфы разрушали укрепления троллей и препятствовали снабжению их войск." }, { 5.92, "Бессильные перед магией, тролли проигрывали битву за битвой." }, { 10.60, "Сравнившись в жестокости и хитрости с троллями, ночные эльфы навлекли на себя вековечную ненависть последних." }, { 18.94, "Прошло несколько лет, и от империй Амани и Гурубаши остались жалкие осколки." } } } },
    ["5a524ed4"] = { d = 39.3, v = "narrator", c = { x = { { 0.00, "Гномское инженерное дело" }, { 1.89, "Раса гномов достигла несравненных успехов в разработке предметов, манипулирующих и управляющих окружающим их миром." }, { 10.46, "Несмотря на то что они обычно стремятся к совершенствованию взрывчатых веществ и оружия, их инженерное дело также сосредоточено на предметах, которые, буквально говоря, делают жизнь проще и удобнее." }, { 25.18, "Эта наука о теоретических возможностях переделки реальности в соответствии с технологией гномских ноу-хау." }, { 33.15, "Некоторые возможности, как бы то ни было, никогда не получится полностью реализовать." } } } },
    ["5a792831"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Архиепископ Алонсус Фаол." }, { 1.97, "Благосклонный покровитель Храма Света." }, { 4.89, "Несмотря на то что архиепископ Фаол начал свой светлый путь в лордеронском Стратхольме, он всегда был другом Штормграда." }, { 13.79, "В тёмные времена после Второй войны он помогал монастырю в Североземье и жертвовал значительные средства на восстановление самого города." }, { 24.04, "Сей храм стоит не только как бастион Света, но и как памятник благородному духу и щедрости этого человека." } } } },
    ["5aa4c38e"] = { d = 34.1, v = "human-male", c = { x = { { 0.00, "Они стояли, замерев, а она спокойно смотрела им в глаза." }, { 4.15, "И тогда один из всадников посмотрел вверх, как будто услышал далёкий зов." }, { 9.33, "Он вытащил из-под одежды небольшой камень и заглянул в него." }, { 13.74, "Затем он жестом указал на него жене Свена." }, { 16.92, "Свет полился из всадника в сторону женщины, формируясь в страшную белую руку." }, { 22.49, "Она решительно смотрела на этот свет, но я видел неуверенность за её маской спокойствия." }, { 28.78, "Когда рука достигла её, она обхватила пальцами голову женщины." }, { 33.38, "И сжала её." } } } },
    ["5aaf18e4"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Со временем любопытство ночных эльфов привело к тому, что они повстречали и подружились с самыми разными могущественными существами, не последним из которых был Кенарий, могучий полубог древних лесов." }, { 15.02, "Благородному Кенарию пришлись по нраву любознательные ночные эльфы, и он потратил много времени на то, чтобы рассказать им о силах природы." }, { 25.48, "Мирные кальдорай прониклись большим сочувствием к живым лесам Калимдора и наслаждались гармонией природы." } } } },
    ["5ad13e00"] = { d = 30.7, v = "goblin-male", c = { x = { { 0.00, "Привет и поклон вам, искатели приключений!" }, { 2.97, "Мне, Кринкелю Сталлинну, необходима помощь желающих рискнуть своей жизнью ради выполнения некоторых моих трудных поручений." }, { 11.70, "Поскольку у меня множество обязанностей и я загружен взвалившейся на меня работой, я уверяю, что любому, достаточно смелому, чтобы собрать необходимые предметы из данного списка и принести их мне, будет выплачена солидная премия." }, { 27.70, "Список включает в себя следующие страницы..." } } } },
    ["5ad78d9b"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Морган Ладимор был известным и благородным рыцарем, защищавшим невинных, бедных и страждущих." }, { 7.66, "Многие годы он усердно сражался в отдалённых районах Азерота, помогая угнетённым и творя правосудие над их угнетателями." }, { 17.41, "Когда ему исполнилось восемнадцать лет, он женился на молодой девушке по имени Лиис." }, { 24.40, "Они очень любили друг друга, у них было трое детей: сын и две дочери." }, { 30.20, "Моргану было тридцать два года, когда в Лордероне началась" } } } },
    ["5b06f155"] = { d = 11.8, v = "human-male", c = { x = { { 0.00, "Если какой-нибудь представитель разумной формы жизни найдёт это письмо, пусть он спросит себя:\"Какого черта они возятся с этими злобными десятиметровыми великанами?\"" }, { 11.54, "-Муук" } } } },
    ["5b1c790e"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Утёс Бледногривов — пещера в западных горах Мулгора, где поселились гноллы племени Бледногривов." }, { 7.35, "Они живут и в лагере снаружи, и в глубине пещеры, уходящей далеко в недра горы." }, { 13.59, "Гноллы не отвечают на попытки договориться, нападают на всякого, кто подойдёт близко, и без жалости истребляют зверей Мулгора." }, { 23.17, "Бейн Кровавое Копыто просит молодых тауренов искоренить эту угрозу, пока она не разрослась." } } } },
    ["5b3743d5"] = { d = 38.3, v = "narrator", c = { x = { { 0.00, "Длань Тира на юго-востоке края — укреплённый город, названный в честь легендарного Тира." }, { 6.72, "Это одно из древнейших святых мест Церкви Света, «город церквей», с Алой Базиликой и аббатством." }, { 14.21, "Когда Лордерон пал, Длань Тира выстояла под почти ежедневными атаками нежити и стала главной твердыней Алого ордена в Чумных землях: отсюда в Стратхольм идут обозы и подкрепления, а гонцы под усиленной охраной везут донесения." }, { 31.68, "Здесь же пребывает Алый Оракул, прорицательница ордена." }, { 35.90, "Чужаков за этими стенами не ждут." } } } },
    ["5b446fd5"] = { d = 42.2, v = "narrator", c = { x = { { 0.00, "На северо-восточной окраине Лунной поляны лежат священные кельи, названные в честь Малфуриона Ярость Бури." }, { 8.74, "Под курганами спят друиды ночных эльфов, чей дух странствует в Изумрудном Сне." }, { 14.99, "В Третью войну Плеть Тикондруса рвалась сюда, чтобы добраться до спящего Малфуриона, но Тиранда успела разбудить его, и он повёл друидов на защиту Хиджала." }, { 27.63, "После войны верховный друид вновь ушёл в Сон и не вернулся: его тело покоится здесь, под охраной Круга Кенария и Сестринства Элуны, а руководство друидами принял Фэндрал Олений Шлем." } } } },
    ["5b64f572"] = { d = 5.8, v = "human-male", c = { x = { { 0.00, "Эта наковальня является собственностью Джордана Стивелла – Просьба НЕ трогать!" }, { 5.31, "- Джордан" } } } },
    ["5b6cfa38"] = { d = 21.0, v = "troll-female", c = { x = { { 0.00, "Теперь ты в хороших руках." }, { 2.10, "Джен'шан знает, что ты любишь охотиться, и готова тебя научить… если ты будешь слушать." }, { 8.95, "Приходи в Долину Испытаний." }, { 11.11, "Джен'шан будет учить тебя охотиться и покажет, какими могущественными бывают настоящие охотники." }, { 18.66, "-Джен'шан, наставница охотников" } } } },
    ["5b70d970"] = { d = 20.3, v = "human-male", c = { x = { { 0.00, "Тварь, о которой я пишу, – это ворген." }, { 2.64, "О воргенах часто рассказывают в сёлах – какой же ребёнок с фермы не слышал сказок о людях-волках, бродящих по лесам и болотам у его родной деревни?" }, { 12.66, "В таких сказках может скрываться и правда – возможно, так нас предупреждают о воргенах, пугая страшными небылицами." } } } },
    ["5b7c6905"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Посёлок Сталежара лежит сразу за поворотом к северо-востоку от Караноса." }, { 5.48, "Это небольшое поселение горняков и инженеров, каменная мастерская под деревянными навесами, где чинят осадные машины." }, { 14.39, "Хозяин её, Белдин Сталежар, слывёт лучшим техником по паровикам, а его тангенциальные вращатели выходят из строя быстрее, чем их успевают привозить." }, { 25.55, "Здесь любят собираться ветераны-водители осадных машин, и в снегу вокруг ржавеют остовы недостроенных танков." } } } },
    ["5b7f5f0c"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Поместье Мистмантла стоит на северо-востоке Сумеречного леса, к северу от Темнолесья и западнее Приюта Бродяги." }, { 9.21, "Некогда здесь жил учитель и домашний наставник по имени Сталван, но усадьба давно заброшена: земля вокруг прогнила, а по саду бродят вурдалаки." }, { 21.02, "Единственный признак жизни – один-единственный цветок в саду." }, { 26.15, "В Темнолесье о хозяине поместья говорят неохотно, а мадам Ева, разложив карты, увидела в них его имя и Смерть – и с тех пор боится за всех." } } } },
    ["5baa8c26"] = { d = 35.5, g = 1, v = "tauren-female", c = { m = { { 0.00, "Приветствую тебя, молодой герой." }, { 2.96, "Ветер нашептал мне, что ты пришёл." }, { 5.92, "Земля рассказала о твоей силе." }, { 8.72, "И теперь древние духи говорят о том, что ты готов учиться." }, { 13.92, "Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас." }, { 21.20, "Если хочешь, я научу тебя большему." }, { 24.48, "Ищи меня в Лагере Нараче на плато Красного Облака – нам есть, о чём поговорить." }, { 31.52, "-Мила Рассветная Странница, наставница шаманов" } }, f = { { 0.00, "Приветствую тебя, молодая героиня." }, { 3.09, "Ветер нашептал мне, что ты пришла." }, { 6.11, "Земля рассказала о твоей силе." }, { 8.88, "И теперь древние духи говорят о том, что ты готова учиться." }, { 14.11, "Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас." }, { 21.33, "Если хочешь, я научу тебя большему." }, { 24.58, "Ищи меня в Лагере Нараче на плато Красного Облака – нам есть, о чём поговорить." }, { 31.56, "-Мила Рассветная Странница, наставница шаманов" } } } },
    ["5bb0c5be"] = { d = 21.2, v = "human-male", c = { x = { { 0.00, "Чернокоготь--" }, { 1.03, "Море ждёт нас." }, { 2.12, "Нам нужны ресурсы с севера." }, { 4.24, "Несите все: рельсы, вёдра." }, { 6.23, "Нам нужен металл." }, { 7.60, "Ожидается прибытие груза из Пиратской бухты, но поставка задерживается." }, { 13.00, "Потрудитесь как следует, Чернокоготь!" }, { 15.81, "В этот раз посылайте припасы прямо в \"амбар\"." }, { 19.30, "Времени в обрез." }, { 20.60, "--ван Клиф" } } } },
    ["5c26e202"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Когда пришло время, Кил'джеден объяснил Королю-личу, зачем тот был создан." }, { 6.13, "Нер'зул должен был распространить в Азероте смертоносную чуму, которая истребила бы расу людей." }, { 13.88, "Заразившиеся этой чумой умирали и превращались в нежить, отдавая свои души во власть железной воли Нер'зула." } } } },
    ["5c27b66e"] = { d = 23.2, v = "narrator", c = { x = { { 0.00, "Нер'зул и верный ему клан Призрачной Луны прошли через самый большой из открытых ими порталов, в то время как извержения вулканов начали разрывать континенты Дренора на части." }, { 14.08, "Кипящие моря вознеслись к небу и обрушились на землю: мир орков исчез во всепоглощающем пламени гигантского взрыва." } } } },
    ["5c364fc7"] = { d = 73.8, v = "narrator", c = { x = { { 0.00, "Болото Печали лежит на юго-востоке Восточных королевств: с запада его запирает перевал Мёртвого Ветра, на юге начинаются Выжженные земли, а восточный берег омывает Зловещее море." }, { 14.30, "Когда-то это была северная половина огромных Чёрных топей; когда в конце Второй войны рухнул Тёмный портал, юг обратился в пустошь, а север так и остался болотом." }, { 27.23, "Здесь стоячая солоноватая вода, покрытые солью коряги и плакучие деревья, а единственная дорога едва поднимается над трясиной, где охотятся кроколиски и ягуары." }, { 39.89, "В древности сюда бежали тролли Атал'ай, жрецы Хаккара, и воздвигли свой храм, но Изера утопила его в озере Слёз, и с тех пор зелёные драконы стерегут затонувшие руины." }, { 53.04, "Орки Старой Орды заложили здесь Каменор ещё в Первую войну, а при Тралле отстроили заново – это единственный город на всём болоте." }, { 63.40, "По окраинам ютятся Заблудшие, которых путь через портал лишил разума, и лишь горстка изгнанников в Убежище ещё помнит, кем они были." } } } },
    ["5c95d3d7"] = { d = 35.4, g = 1, v = "gnome-male", c = { m = { { 0.00, "Жаровня вызывания духов: инструкция к использованию." }, { 3.71, "Где найти места с привидениями" }, { 5.88, "Вступление." }, { 6.71, "На этих страницах написано, где можно найти падших духов и призраков, участвовавших в событии, связанном с амулетом Лорда Вальтхалака." }, { 16.24, "Ты уже спас моих бывших товарищей, но, боюсь, отголоски того зла, что поработило их души, ещё не покинули эти места." }, { 24.49, "Таково могущество злобного духа Лорда Вальтхалака." }, { 28.13, "С помощью жаровни также можно вызвать Лорда Вальтхалака, но нужно соблюдать крайнюю осторожность." } }, f = { { 0.00, "Жаровня вызывания духов: инструкция к использованию." }, { 3.73, "Где найти места с привидениями" }, { 5.92, "Вступление." }, { 6.75, "На этих страницах написано, где можно найти падших духов и призраков, участвовавших в событии, связанном с амулетом Лорда Вальтхалака." }, { 16.34, "Ты уже спасла моих бывших товарищей, но, боюсь, отголоски того зла, что поработило их души, ещё не покинули эти места." }, { 24.83, "Таково могущество злобного духа Лорда Вальтхалака." }, { 28.49, "С помощью жаровни также можно вызвать Лорда Вальтхалака, но нужно соблюдать крайнюю осторожность." } } } },
    ["5cb460c7"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "На западной окраине Мулгора дворфы вырыли в склоне горы большой карьер — раскопки Бейл'дана." }, { 7.97, "Экспедиция ищет в земле следы своего тёмного прошлого, и Бейн Кровавое Копыто видит в этих бесконечных ямах оскорбление Матери-Земли: у земли нужно учиться, а не осквернять её." }, { 22.99, "Уговоры не помогли, и племя Кровавого Копыта решило иначе — собирать и ломать кирки геологов, чтобы дворфы поняли, что им здесь не рады." } } } },
    ["5d009188"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "Лагерь Э'Ток — стоянка кентавров племени Галак на северо-западе Тысячи Игл, у дороги, ведущей на запад." }, { 7.89, "Отсюда кентавры выходят в набеги на караваны: один из обозов был разграблен здесь дочиста, а погонщики перебиты." }, { 16.32, "Единственное, что грабители не сумели забрать, — драгоценный прибор гоблина Визло, который тот на свою беду повесил на шею своей свирепой пантере; зверь до сих пор в ярости мечется среди шатров." } } } },
    ["5d0497aa"] = { d = 29.1, v = "narrator", c = { x = { { 0.00, "Громовой хребет — глухая долина на северо-западе Дуротара, одно из немногих зелёных мест этой земли." }, { 7.82, "Здесь водятся громовые ящеры, чьи стада не дают покоя всей округе." }, { 12.99, "В последнее время в долине обосновалась горстка сектантов Пылающего Клинка во главе с гоблином-чернокнижником Пшиксом Черношквалом, и Оргнил Душегрыз из Колючего Холма ищет тех, кто положит конец их бесчинствам." } } } },
    ["5d18afb3"] = { d = 17.6, v = "narrator", c = { x = { { 0.00, "К сожалению, адмирал Праудмур умер в бою, не успев помириться с Джайной и узнать, что орки перестали быть кровожадными чудовищами." }, { 10.32, "В награду за помощь орки позволили Джайне и её подданным беспрепятственно вернуться в Терамор." } } } },
    ["5d4b9bb6"] = { d = 34.2, g = 1, v = "human-male" },
    ["5d684197"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Мастерские Гарнизона — рудник неподалёку от Крепости Стражей Пустоты, где шахтёры и инженеры гарнизона добывают руду и камень для крепости." }, { 9.88, "Часть добытого отправляют караванами в Штормград в обмен на припасы, без которых крепости не выстоять." }, { 17.15, "Стук кирок в этих штольнях — едва ли не единственный мирный звук во всех Выжженных землях." } } } },
    ["5d68b59e"] = { d = 29.6, v = "narrator", c = { x = { { 0.00, "Стена Торадина замыкает предгорья с востока, отделяя их от нагорья Арати." }, { 6.05, "Её возвёл король Торадин в дни империи Аратор, чтобы прикрыть молодые города людей от набегов троллей Амани." }, { 14.99, "Прошли века; стена обветшала и во многих местах обрушилась, но её громада по-прежнему тянется через холмы, а дорога из Южнобережья проходит сквозь уцелевшие ворота в нагорье Арати." } } } },
    ["5d783e95"] = { d = 67.4, v = "narrator", c = { x = { { 0.00, "Альтеракские горы — высокий лесистый край в сердце Лордерона, где часто идут дожди, а небо почти всегда затянуто тучами." }, { 9.49, "Когда-то здесь стояло королевство Альтерак, но во Вторую войну его правители предали Альянс, сговорившись с Ордой, и армии людей обратили столицу в руины." }, { 21.58, "Ныне развалины заняли огры клана Раздробленного Хребта, а потомки альтеракской знати сколотили Синдикат — шайку разбойников, засевшую в Странбраде и на холмах Высокогорья; обе стороны без конца воюют за эту землю." }, { 38.10, "На берегу озера Лордамер под магическим куполом укрылся Даларан, город магов Кирин-Тора, переживший Третью войну." }, { 48.54, "В заснеженной долине в глубине гор дворфы Грозовой Вершины сражаются с орками клана Северного Волка, а по пещерам бродят свирепые йети." }, { 59.15, "Ни у Альянса, ни у Орды здесь нет своих поселений: путники приходят сюда из Южнобережья и с мельницы Таррен." } } } },
    ["5d82d969"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Войско Плети под предводительством Артаса вторглось в Кель'Талас и окружило немногочисленную армию эльфов." }, { 8.20, "Сильвана Ветрокрылая, предводительница следопытов Луносвета, храбро вступила в неравный бой с врагом, но Артас истребил всю армию высших эльфов и добрался до Солнечного Колодца." }, { 21.87, "В подтверждение своего превосходства безжалостный Артас воскресил Сильвану как банши, чтобы она вечно служила поработителю Кель'Таласа." } } } },
    ["5d87c16d"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Глядя правым оком на золотой рассвет, Мать-Земля распростёрла свои нежные руки над золотыми равнинами." }, { 8.68, "Там, где легла тень от её рук, из земли восстал благородный народ." }, { 14.16, "Это Шу'хало, наречённые тауренами, вышли вознести благодарность и молитвы своей любящей матери." }, { 22.23, "Там, в бескрайних полях рассвета, дети земли поклялись восхвалять её имя до скончания времён." } } } },
    ["5d8c01f6"] = { d = 10.2, v = "narrator", c = { x = { { 0.00, "Орман из Стромгарда." }, { 1.72, "Первый капитан-генерал Алого ордена." }, { 4.86, "Гражданин Стромгарда." }, { 6.65, "Пропал без вести на леднике Ледяной Короны." } } } },
    ["5d990727"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Полчища нежити продолжали своё шествие по землям Лордерона, и принц Артас, единственный сын Теренаса, решил выступить против них." }, { 10.18, "Артасу удалось убить Кел'Тузада, но ряды нежити пополнялись с каждым павшим солдатом, защищавшим свои земли." }, { 18.92, "Враги казались непобедимыми, и Артас впал в отчаяние; ему пришлось идти на крайние меры." }, { 26.01, "В конце концов он узнал от солдат, что начал терять свои человеческие качества." } } } },
    ["5d9be801"] = { d = 37.6, v = "dwarf-male", c = { x = { { 0.00, "Вчера он впервые сумел заговорить." }, { 2.61, "Он, друид по имени Гералат, послан в эти земли, чтобы проверить слухи о павшем боге-вепре." }, { 9.50, "Слабеющим голосом он поведал мне, что считал, будто бы огромный кабаний череп лежит на том самом месте, где великий бог-вепрь Агамагган пал в битве с Пылающим Легионом примерно десять тысяч лет тому назад, во время Войны Древних." }, { 26.57, "Земля превратилась в равнину там, где рухнула его массивная туша, а кровь бога-вепря впиталась в почву – и там, куда пала кровь, растут острые шипы..." } } } },
    ["5e04ab3e"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Грот Богена — небольшая пещера в скалах на юго-западе Внутренних земель, к югу от дороги на Заоблачный Пик." }, { 8.44, "Внутри сыро и темно, а вход прикрывают заросли, так что найти его непросто." }, { 14.45, "В окрестностях бродят волки и медведи, а с юга к гроту подступают земли троллей Сухокожих." } } } },
    ["5e0e196c"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Тростниковая застава – маленький орочий пост Каменора между Вязкой топью и южной частью Тростникового берега." }, { 8.71, "Здесь нет ни стен, ни башни – только костёр, бочонок медовухи и горстка каменорских охотников с шаманом под началом Ток'Кара; рядом с ним держится и Катор." }, { 20.78, "Ток'Кар мечтает, что однажды здесь поставят хоть землянку, а пока отсюда посылают охотников на мурлоков побережья." }, { 29.78, "Гриф сюда не летает: добираться придётся пешком через трясину." } } } },
    ["5e1952d8"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Именно Гул'дан повинен в том, что шаманские знания в кланах пошли на убыль." }, { 6.10, "Он обещал всем могущество и власть над врагами, и его охотно слушали." }, { 11.62, "С помощью Кил'джедена Гул'дан начал манипулировать кланами." }, { 16.42, "Орки, некогда благородные, превратились в злобных и неразумных дикарей." }, { 22.16, "Когда же в их жилы попала кровь демонов, орки стали ещё более безжалостными и одержимыми." } } } },
    ["5e2bcd28"] = { d = 21.9, v = "narrator", c = { x = { { 0.00, "Ядовитая поляна прячется на холме к северу от часовни Последней Надежды." }, { 6.06, "Даже по меркам Чумных земель это гиблое место: воздух здесь густой, тошнотворно-зелёный, а земля темна, как запёкшаяся кровь." }, { 16.39, "Плеть возвела на поляне свои зиккураты, и во мгле копошатся её твари." } } } },
    ["5e45fd44"] = { d = 23.6, v = "human-male", c = { x = { { 0.00, "Пребывание в брюхе великана способствует размышлению." }, { 3.91, "Пока моё тело постепенно кристаллизируется, я размышляю над своей жизнью в Вечной Песне, вспоминая бесконечные приключения на диких просторах великого моря." }, { 15.39, "Я был молод." }, { 16.32, "И глуп." }, { 16.85, "Если я как-нибудь отсюда выберусь, то займусь фермерством или резьбой по дереву." }, { 22.82, "- Ветран Шей" } } } },
    ["5e6885c0"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Заточённый в ледяной тюрьме Нер'зул почувствовал, что возможности его разума возросли тысячекратно." }, { 8.75, "Наделённый огромной силой демона, он стал невероятно могущественным духом." }, { 15.25, "В этот момент орк по имени Нер'зул перестал существовать, и на свет явился Король-лич." } } } },
    ["5e945e20"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Шахтёр Оруэлл" }, { 1.17, "Крупный долг." }, { 2.33, "Выплата долга состоится после поставки руды из Лазурного рудника." }, { 8.08, "Шахтёр Фитцджеральд" }, { 9.71, "Крупный долг." }, { 10.88, "Выплата долга состоится после поставки руды из Лазурного рудника." }, { 16.62, "Гражданин Недранд" }, { 18.18, "Все задолженности выплачены." }, { 20.59, "Гражданин Мэй" }, { 21.75, "Все задолженности выплачены." }, { 24.16, "Старшина Бондс" }, { 25.40, "Крупный долг." }, { 26.57, "Выплата долга состоится после поставки руды из Лазурного рудника." } } } },
    ["5e9e831a"] = { d = 21.6, v = "narrator", c = { x = { { 0.00, "Сила Хранителя была столь велика, что только Совет Тирисфаля мог отбирать достойных этого титула." }, { 7.23, "Когда Хранитель становился слишком стар или уставал от этой тайной войны против хаоса, Совет выбирал нового защитника и при определённых условиях формально передавал силу старого Хранителя новому." } } } },
    ["5ea0c698"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Лесопилка Восточной долины – сердце лесного промысла Элвинна, ряд пилорам и жилых домов на востоке леса, у дороги в Красногорье." }, { 10.11, "Заказы на древесину идут сплошным потоком, и начальница лесорубов Раэлен вечно не укладывается в сроки." }, { 18.18, "Работу осложняют волки и медведи: чем дальше от Златоземья, тем злее звери." }, { 24.07, "В усадьбе неподалёку доживает свой век маршал Хаггард, некогда возглавлявший стражу Штормграда, а кожевница Сара Тимберлейн шьёт для лесорубов броню." } } } },
    ["5ea8f88c"] = { d = 26.4, v = "human-male", c = { x = { { 0.00, "Ваша честь--" }, { 0.90, "С сожалением сообщаю, что в настоящее время Ночной Дозор не может покинуть свой пост в Темнолесье." }, { 7.80, "Возможно, вы ещё не знаете, но Штормград больше не оказывает военной поддержки нашему региону." }, { 14.46, "Ночной Дозор был создан и подготовлен для защиты Темнолесья в отсутствие поддержки Штормграда." }, { 21.11, "Без защиты Дозора город будет уничтожен." }, { 24.05, "Желаю удачи." }, { 25.01, "--Лорд Элло Чернодрев" } } } },
    ["5ec865b5"] = { d = 9.0, v = "narrator", c = { x = { { 0.00, "РЯДОВЫЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.65, "Старший Сержант." }, { 4.51, "Сержант." }, { 5.49, "Младший Сержант." }, { 7.35, "Капрал." }, { 8.24, "Рядовой." } } } },
    ["5ecf7057"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "Озеро Мистраль — самое большое озеро Ясеневого леса, лежащее на юге, между Приютом Серебряного Ветра и Туннелем Когтя." }, { 9.52, "Его воды кишат элементалями воды: прежде они были верны ночным эльфам, но Сарилус Грязнорождённый, маг из нежити с Вершины Багрового Тумана в Степях, наслал на них порчу, и теперь они бросаются на всех, кто подойдёт к берегу." }, { 27.20, "К юго-востоку от озера живёт фурболг Кролг — один из немногих, кого не тронула порча Мха Скверны." } } } },
    ["5edf0565"] = { d = 31.1, v = "narrator", c = { x = { { 0.00, "Часовые Вечности – каменное кольцо в сердце острова посреди Озера Каменных Столбов." }, { 6.68, "Здесь стоит памятный камень в честь павших, когда орки в Первую войну разорили Златоземье и окрестные земли." }, { 15.28, "Когда-то сюда приходили паломники, но ныне остров захватили чародеи, связанные с Братством Справедливости, и путнику здесь грозит опасность." }, { 26.30, "Сами бандиты называют это место забытой всеми обителью веры." } } } },
    ["5f011647"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Южный Гибельный берег — пляжи и отмели на западной стороне мыса, где Южные моря омывают сушу." }, { 7.40, "Он тянется от Коварного рифа до Пиратской бухты и острова Жанейро, где переходит в Гибельный берег." }, { 15.09, "Здесь на песке разбили лагерь пираты Кровавого Паруса, и отсюда флотоводец Фираллон грозит обстрелять Пиратскую бухту." } } } },
    ["5f3c16fe"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Этот неповреждённый скелет птерадона был найден в далёком Кратере Ун'Горо." }, { 5.50, "Исходя из структуры скелета, был сделан вывод, что подобный вид существ никогда раньше не встречался." }, { 13.10, "Этот скелет, вероятно, был погребён под слоями плодородной земли этого региона много столетий назад." } } } },
    ["5f4039c1"] = { d = 16.2, v = "narrator", c = { x = { { 0.00, "Кел'Тузад спустился глубоко под замёрзшую землю и добрался до сердца ледника." }, { 6.39, "Там, в бесконечных ледяных пещерах, он преклонился перед Ледяным Троном и преподнёс свою душу тёмному повелителю нежити." } } } },
    ["5f42b007"] = { d = 38.5, v = "narrator", c = { x = { { 0.00, "Лесозаготовки Песни Войны раскинулись на востоке леса, к югу от Лесной Песни и к северу от Холма Демонического Огня." }, { 9.77, "Здесь орки клана Песни Войны валят вековые деревья для строек Орды, и от чащи остаются лишь пни да штабеля брёвен." }, { 19.32, "Лесорубов охраняют стражи и шаманы, а на восточном краю лагеря стоит крепость Каргатия." }, { 26.68, "Припасы вечно в недостаче: верёвки и масло крадут фурболги и сатиры." }, { 32.40, "Часовые Среброкрылых поклялись остановить рубку, и стычки здесь не утихают." } } } },
    ["5f53ed57"] = { d = 17.1, v = "narrator", c = { x = { { 0.00, "Назвав себя дворфами, последние земельники покинули Ульдаман и отправились исследовать мир." }, { 7.39, "Их по-прежнему влекли уютные и безопасные подземелья, а потому они основали огромное королевство под самой высокой горой." } } } },
    ["5f978d39"] = { d = 23.8, v = "narrator", c = { x = { { 0.00, "Пытаясь спастись, великий олень прыгнул на небо, но зацепился могучими рогами за звёзды." }, { 7.08, "Как ни старался Апа'ро вырваться, ничего у него не вышло." }, { 11.70, "И тогда его нашла Му'ша, которая гналась за своим братом Ан'ше." }, { 16.98, "Она увидела, как могучий олень борется за свою свободу, и тотчас же влюбилась в него." } } } },
    ["6009ca82"] = { d = 10.3, v = "narrator", c = { x = { { 0.00, "Из-за предательства Гул'дана Молот Рока потерял почти половину своих воинов и был вынужден отступить, выпустив из рук столь близкую победу." } } } },
    ["60139ee2"] = { d = 16.8, v = "narrator", c = { x = { { 0.00, "Это ростовая копия скелета Щелкозуба." }, { 2.97, "Легендарный баран был чудом Каз Модана и объектом многих историй дворфийского фольклора." }, { 9.75, "До сих пор экологи не способны объяснить огромный размер барана и его физическую выносливость." } } } },
    ["60458278"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "Некоторые считали, что виной этому какое-то заболевание, которому подвержены только орки." }, { 6.98, "Но верховный маг Антонидас из Даларана предложил другое объяснение." }, { 12.14, "Изучив те немногие материалы по истории орков, которые ему удалось найти, Антонидас узнал, что несколько поколений этого народа находилось под влиянием демонов." } } } },
    ["604f4712"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "Пещера Бесов лежит к северу от Доланаара." }, { 3.49, "Некогда это был красивый грот, но теперь его наводнили грелли — мелкие злобные духи, что стайками роятся во тьме." }, { 12.86, "В глубине пещеры устроил логово сатир лорд Меленас, собравший вокруг себя шайку греллей-воинов; сердце его, по словам друидов, чернее ночи." }, { 24.60, "То, что сатир поселился так близко к деревне, тревожит Таллонкая Гибкого Корня, и он ищет того, кто положит этому конец." } } } },
    ["608214c3"] = { d = 23.2, v = "dwarf-male", c = { x = { { 0.00, "День первый." }, { 0.94, "Мой танк сломался, но я знаю, что залежи руды хирона – где-то в этих холмах." }, { 6.64, "Я велел Большеногу оставаться и присматривать за нашими танками." }, { 11.40, "Продолжил поиск в одиночку." }, { 13.48, "Если я не смогу вернуться назад, то журнал останется моим последним завещанием." }, { 19.45, "Бурон Хилдельв, пилот." }, { 21.19, "Паровая бригада Стальгорна." } } } },
    ["608bc22b"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "Иллидан тоже пережил Раскол и добрался до вершины Хиджала намного раньше Малфуриона и ночных эльфов." }, { 7.95, "Он был одержим идеей сохранить в этом мире магию, поэтому вылил в горное озеро драгоценную воду из Источника Жизни, которую хранил в нескольких сосудах." } } } },
    ["60e8c3b0"] = { d = 28.9, v = "narrator", c = { x = { { 0.00, "Скоро Анахронос понял, что даже могущественные Бронзовые драконы не смогут сдержать напор киражских войск." }, { 8.31, "На место каждой полусотни насекомых, изничтоженных его дыханием, вставала сотня новых." }, { 15.15, "Видя, как трудно приходится ночным эльфам, и понимая, что перед ними маячит угроза отступления на север, в глушь Фераласа, Анахронос решил, что надо предупредить детей Аспектов." } } } },
    ["60ffa902"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Под контролем Гул'дана и Совета Теней орки стали грубыми и жестокими." }, { 5.67, "Они построили огромные арены, где соревновались друг с другом в умении сражаться и убивать." }, { 13.01, "В это время вожди некоторых кланов решили высказать своё негодование по поводу упадка их расы." } } } },
    ["610e2c26"] = { d = 30.0, v = "human-male", c = { x = { { 0.00, "Нелтарион:" }, { 0.78, "Нелтарион, названный при рождении Землестражем, был предан Азероту сильнее, чем кто-либо из других Аспектов." }, { 8.51, "Его чёрные драконы создали горы и прочие возвышенности, включая и границы между землями смертных народов." }, { 16.18, "До сих пор неизвестно, что толкнуло его в пучину зла: внешнее ли влияние, внутренняя ли слабость." }, { 23.06, "Интересно знать, причастны ли к этой порче, которой подвергся великий чёрный дракон, Древние Боги." } } } },
    ["618a3efc"] = { d = 33.9, v = "narrator", c = { x = { { 0.00, "Изучение инженерного дела" }, { 1.98, "Гномы и гоблины столь яростно защищают свои знания друг от друга, что невозможно получить доступ к обоим направлениям этой науки одновременно." }, { 12.74, "Каждая раса, независимо от её политических союзов, даёт доступ к знаниям лишь тем, кто согласен отказаться от стремления заняться другим направлением науки." }, { 24.39, "Если ученик выбирает гномское инженерное дело, например, то ни одного урока гоблинского инженерного дела он никогда не получит." } } } },
    ["619c203e"] = { d = 35.7, v = "narrator", c = { x = { { 0.00, "Деревня Зелёной Лапы лежит в центре Ясеневого леса, к югу от Приюта в Ночных Лесах и к северо-востоку от Приюта Серебряного Ветра." }, { 10.16, "Здесь живёт племя фурболгов Гиблой Чащи под началом вождя и шаманов, и порча сделала их врагами всему живому." }, { 18.65, "Они воруют припасы у орков с лесозаготовок и нападают на всех подряд, так что и Орда, и Альянс нередко приходят сюда с оружием." }, { 28.45, "Орочьи командиры из Зорам'гара считают, что лишь показательный удар по деревне остановит угрозу." } } } },
    ["61eeb0d7"] = { d = 18.9, v = "dwarf-male", c = { x = { { 0.00, "Меня грубо затащили в какие-то жутко колючие заросли под названием Лабиринты Иглошкурых." }, { 6.49, "Меня бросили в убогую хижину и держали в плену вместе с умирающим ночным эльфом." }, { 12.47, "У меня не осталось ничего, кроме этого дневника, пера и карманных часов..." }, { 17.98, "Кто-то идёт..." } } } },
    ["6204b0d4"] = { d = 32.9, v = "narrator", c = { x = { { 0.00, "Сокрытая роща — лесистая котловина на северо-востоке Зимних Ключей, со всех сторон окружённая отвесными скалами; попасть внутрь можно лишь через пещеру на юго-восточном склоне гряды." }, { 14.17, "Когда-то здесь водились лишь безобидные белые зайцы, теперь же рощу заполонили обезумевшие совухи, яростно нападающие на любого чужака." }, { 24.68, "Ночные эльфы считают это место священным: друиды помнят, что совухов поставила Элуна охранять её святыни." } } } },
    ["622a9ca6"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Логово — большое строение в глубине Долины Испытаний, сердце тренировочного лагеря Орды." }, { 7.06, "Под его сводами ждут наставники, оружейники и мясники, обучающие новобранцев ремёслам войны." }, { 14.26, "У входа стоят стражники, а вокруг снуют ленивые батраки, которым вечно нужен окрик надсмотрщика." }, { 22.02, "Именно сюда молодые орки и тролли возвращаются с каждым выполненным поручением, прежде чем получить следующее." } } } },
    ["62500869"] = { d = 36.8, v = "narrator", c = { x = { { 0.00, "Долина Королей лежит в юго-западном углу Лок Модана, у выхода из Южных врат." }, { 6.18, "Над зелёной долиной возвышаются две огромные статуи дворфийских королей из кланов Бронзобородов и Громового Молота: после смерти отцов их сыновья вместе заказали эти изваяния, чтобы те вечно стерегли проход в южные земли." }, { 23.87, "Отсюда же начинается путь в Тлеющее ущелье, но ворота туда заперты и охраняются." }, { 30.27, "В сторожевой башне капитан Ругельфасс собирает молодых дворфов на войну с троггами." } } } },
    ["62e87b70"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "Святилище Павшего Воина стоит на вершине холма к западу от Перекрёстка, куда ведёт узкая тропа по гребню." }, { 8.48, "На каменном постаменте застыла фигура орка-воина, а у подножия обелиска высечены руны." }, { 15.50, "Перед святилищем несёт вечную вахту целительница духов." } } } },
    ["6308ee67"] = { d = 23.6, v = "narrator", c = { x = { { 0.00, "Хрустальное взморье — песчаный берег на юго-востоке долины, о который бьются волны Южных морей." }, { 7.20, "От джунглей его отделяет крутой хребет, сквозь который ведут лишь две тропы, одна из них — в Мглистую долину." }, { 15.34, "Над южными водами высятся буровые вышки Торговой компании, а на северной оконечности пляжа стоят руины Абораза." } } } },
    ["6317149e"] = { d = 40.8, v = "narrator", c = { x = { { 0.00, "Долина Кактусов лежит на юго-западной окраине Танариса, у самого подъёма в кратер Ун'Горо." }, { 7.27, "Это одно из самых низких мест пустыни, и здесь, единственные на весь Танарис, растут исполинские живые кактусы — верный знак воды глубоко под песком." }, { 19.14, "Долину стерегут терновые собиратели росы и бугристые шипокожи, существа из живых лоз, нападающие на всякого, кто подойдёт близко." }, { 29.36, "Синь Гогельмогель из Прибамбасска уверен, что в железах этих созданий хранится влага, из которой можно сварить чудесный эликсир, утоляющий жажду." } } } },
    ["632311f0"] = { d = 17.2, v = "narrator", c = { x = { { 0.00, "Мрачная вершина поднимается там, где горы смыкаются вокруг Мулгора." }, { 5.63, "Тень здесь ложится раньше, чем на равнинах, а вместо трав — камень и редкие сосны." }, { 12.40, "Это безлюдная высота, куда нечасто заходят даже охотники." } } } },
    ["6371906b"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "Грот Слёз — сырая пещера на северо-востоке Чумных земель, у самой реки Тондрорил." }, { 6.84, "Здесь, во тьме и гнили, копошатся болотные твари и разъедающие слизни." }, { 12.63, "Немногие рискуют заходить внутрь, хотя знахари ценят то, что можно найти в этих недрах." } } } },
    ["639ddb6c"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Старая Наковальня — первое пристанище молодых дворфов в Холодной долине." }, { 5.75, "Это не город, а укреплённый дом в скале, и в самом его сердце гудит большая кузница." }, { 12.41, "Здесь учат военному делу, торгуют снаряжением и раздают первые поручения новобранцам." }, { 19.15, "После падения Гномрегана сюда добрались и беженцы-гномы, растерявшие по дороге всё своё добро." }, { 26.60, "От дверей Старой Наковальни дорога ведёт на восток, к тоннелю, за которым лежит остальной Дун Морог." } } } },
    ["639fc24e"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "По мере того как могущество Высокорождённых и самой Азшары росло, в их характере наметились явственные изменения." }, { 9.10, "И без того высокомерные и холодные, представители высшего класса становились всё более чванливыми и жестокими по отношению к соплеменникам." }, { 20.25, "Некогда завораживающую красоту Азшары окутал тёмный покров." }, { 25.09, "Она начала отдаляться от любящих подданных и не хотела общаться ни с кем, кроме своих доверенных жрецов из числа Высокорождённых." } } } },
    ["63bd1fc9"] = { d = 41.2, v = "narrator", c = { x = { { 0.00, "Аллея Героев лежит перед вратами Штормграда, и каждый, кто входит в город по суше, проходит через неё." }, { 8.30, "Каменный мост перекинут через узкий ров, а по обе стороны дороги высятся статуи пяти героев Альянса — тех, кто ушёл за Тёмный портал и разрушил его, спасая Азерот." }, { 21.36, "Стражи у моста несут службу под их каменными взглядами." }, { 25.84, "Здесь же, верхом на коне, встречает гостей генерал Маркус Джонатан, командующий обороной города." }, { 33.56, "Аллея задумана и как приветствие, и как предостережение всякому, кто пришёл с недобрыми намерениями." } } } },
    ["63bebeb0"] = { d = 24.9, v = "human-female", c = { x = { { 0.00, "Мне нужен заряженный молнией жезл." }, { 2.44, "Чтобы заполучить такой, собери десять тотемных палочек у троллей из племени Сухокожих в Нагорьях Арати." }, { 9.88, "Принеси палочки к Внешнему Кругу, кругу из камней на этом самом нагорье." }, { 15.14, "Положи палочки на центральный камень круга и подожди, когда в них ударит молния." }, { 20.92, "Когда это случится, заряженный молнией жезл будет готов." } } } },
    ["63f480b5"] = { d = 15.1, v = "narrator", c = { x = { { 0.00, "Угодья — участок кратера, вытоптанный исполинскими ящерами Ун'Горо." }, { 5.62, "Земля здесь утрамбована тяжёлыми шагами, трава примята, и тот, кто прислушается, различит далёкий гул — стадо на марше." } } } },
    ["6424f0f1"] = { d = 31.0, v = "troll-male", c = { x = { { 0.00, "Ну что, друг, доставь-ка вот письмо Франгу в Долину Испытаний." }, { 4.78, "Он обычно рядом с Логовом, гоняет там новобранцев, чтобы стали достойными воинами Орды." }, { 11.66, "Ему нужны ловкие бойцы вроде тебя, чтобы показать оркам, как можно драться без грубой силы." }, { 19.04, "Ты быстрее и ловчее многих там, но не очень-то бахвалься – орки оскорблений не любят." }, { 25.64, "Друзья они хорошие, может, ещё и научат тебя чему полезному." }, { 30.49, "-Тар-сир" } } } },
    ["642c19be"] = { d = 8.2, v = "narrator", c = { x = { { 0.00, "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ АЛЬЯНСА." }, { 3.88, "Старшина." }, { 4.90, "Старший сержант." }, { 6.66, "Капрал." }, { 7.49, "Рядовой." } } } },
    ["646499dc"] = { d = 28.4, v = "gnome-male", c = { x = { { 0.00, "Дорогой дневник, я обнял прислужника и сказал, что очень им доволен." }, { 5.01, "Теперь мне лучше." }, { 6.33, "Только никому ни слова, дневничок." }, { 8.90, "Так о чём я?" }, { 9.76, "Ах, да, НАРАЙН!" }, { 10.88, "Р-р-р!!!" }, { 11.47, "Ненавижу его." }, { 12.53, "Ведь это он так выделывался на каждом экзамене, когда мы учились в Гномреганском Институте Механики." }, { 19.78, "Отчислили меня, значит?" }, { 21.56, "Гномреган, насколько мне известно, получил по заслугам!" }, { 25.58, "На сегодня всё." }, { 26.70, "Спокойной ночи, дневник!" } } } },
    ["64766fed"] = { d = 65.7, v = "narrator", c = { x = { { 0.00, "Степи — огромная сухая саванна в сердце Калимдора, раскинувшаяся между рекой Строптивой и Когтистыми горами." }, { 8.87, "Когда-то эта земля была цветущим садом, но войны обратили её в пыль, и лишь оазисы, питаемые подземными водами, напоминают о былом." }, { 19.57, "После Третьей войны сюда пришла Орда Тралла: орки вместе с тауренами Кровавого Копыта прошли через Степи, отбиваясь от кентавров." }, { 30.35, "Теперь по Золотому Пути тянутся караваны, а Перекрёсток стал главным узлом Орды в этих краях." }, { 37.98, "Покоя здесь нет: свинобразы, кентавры клана Колкар и гарпии Зачарованного Крыла грабят обозы, Торговая Компания качает нефть на севере, а на Вершине Багрового Тумана собирается культ Пылающего Клинка." }, { 54.18, "В Пещерах Стенаний друиды Клыка предались кошмару, а на юге люди Терамора и дворфы Бейл Модана напоминают, что Альянс тоже пришёл в эти земли." } } } },
    ["6494dd63"] = { d = 26.1, v = "narrator", c = { x = { { 0.00, "Терраса Покоя лежит у самого входа в Монастырь Алого ордена." }, { 4.96, "Это одно из редких мест на севере Лордерона, куда не дотянулась Чума нежити: здесь зеленеют подстриженные живые изгороди, а в фонтане плещется свежая вода, а не стоячая гниль, как повсюду в Тирисфале." }, { 20.84, "Орден бережёт этот уголок как напоминание о том, за что он сражается." } } } },
    ["64be8481"] = { d = 14.4, v = "creature/ancient", c = { x = { { 0.00, "Симон Совратительница:" }, { 2.14, "Ты застанешь её за осквернением Кратера Ун'Горо." }, { 6.68, "Не поддавайся на её уловки." }, { 9.25, "Приближайся к ней с осторожностью, а потом вступай в бой." } } } },
    ["64e3d67c"] = { d = 30.3, v = "narrator", c = { x = { { 0.00, "Долина Камнедробов врезается в горы на юго-западе Лок Модана." }, { 4.79, "Когда-то это было тихое место, но теперь склоны и пещеры кишат троггами клана Камнедробов, которых потревожили дворфийские раскопки." }, { 15.13, "Разведчики выяснили, что тварей привёл к озеру вождь по имени Громаг, и его ни на шаг не покидают два стража, Скрежетун и Буян." }, { 24.78, "Дворфы надеются, что без вождя троггов удастся загнать обратно под землю." } } } },
    ["64f19997"] = { d = 18.8, v = "narrator", c = { x = { { 0.00, "Острыми рифами зовут северное побережье Азшары: полосы песка, разбитые скальными гребнями и узкими заливчиками." }, { 9.08, "Плавать здесь опасно из-за коварных мелей и подводных камней, а по берегу бродят в поисках пищи мурлоки, гидры и макрура." } } } },
    ["64ff1aea"] = { d = 15.4, v = "narrator", c = { x = { { 0.00, "С уходом своих своевольных собратьев ночные эльфы вновь стали оберегать свою зачарованную родину." }, { 7.62, "Друиды, чувствуя, что скоро должны уснуть, готовились ко сну и прощались со своими родными и близкими." } } } },
    ["6517e09a"] = { d = 35.0, v = "dwarf-male", c = { x = { { 0.00, "Глава три – Четыре командора" }, { 2.10, "Если ты следовал мудрым советам этого руководства, то сейчас двое из командоров Дрек'Тара уже мертвы." }, { 9.56, "Так держать, солдат!" }, { 11.07, "Решимость врага уже пошатнулась." }, { 13.49, "Теперь нужно окончательно разделаться с командным звеном неприятеля и убить двух оставшихся командоров." }, { 20.96, "Когда будут убиты все четыре командора, в рядах легионеров Северного Волка, охраняющих Крепость Северного Волка наступит сумятица – ведь командовать ими будет некому." }, { 33.14, "Можно брать голыми руками!" } } } },
    ["652566a6"] = { d = 24.3, v = "narrator", c = { x = { { 0.00, "После битвы в Крепости Штормграда лорд Лотар собрал остатки армий Азерота и организовал отступление к берегам северного королевства Лордерона." }, { 11.27, "Главы семи человеческих народов решили, что если Орду не остановить, то она уничтожит всё человечество, и создали союз, позже получивший название Лордеронский Альянс." } } } },
    ["6525caaa"] = { d = 30.0, v = "human-male", c = { x = { { 0.00, "Ульдаман, День семь" }, { 1.33, "...последний шанс исправить мои ошибки." }, { 4.12, "Мне кажется, рубин находится за последней баррикадой дворфов, которую они построили против троггов." }, { 11.15, "Несомненно, они сражаются за камень и другие артефакты, найденные здесь, и их постоянно атакуют." }, { 17.86, "Похоже, эти презренные дворфы прячут его где-то у себя." }, { 21.91, "Как бы то ни было, я должен выбрать, куда мне идти дальше." }, { 26.03, "Возможно, бешеный рывок к выходу – самый лучший способ..." } } } },
    ["654e8b42"] = { d = 29.5, v = "dwarf-male", c = { x = { { 0.00, "Не представляют для нас реальной угрозы до тех пор, пока мы не нарушаем их границ." }, { 5.79, "Возможно, народу дворфов неприятна сложившаяся ситуация, но, учитывая дефицит военных сил, будет благоразумнее перенести решение этой проблемы на более поздний срок и бросить все усилия на борьбу с троггами и дворфами Чёрного Железа." }, { 22.51, "В письме вы также найдёте отчёт моего брата Грелина о Старой Наковальне." }, { 27.71, "Подписано:" }, { 28.49, "Сенир Белобород" } } } },
    ["6562370c"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Тем временем остатки Орды боролись за выживание в истерзанных войной южных землях." }, { 6.59, "Гром Адский Крик со своим кланом Песни Войны сумел избежать плена, а вот клан Кровавой Глазницы в полном составе, вместе с вождём Мёртвым Глазом, был заключён в лордеронские лагеря для военнопленных." }, { 22.15, "Последовала череда бунтов, но начальникам лагерей вскоре удалось восстановить порядок среди заключённых." } } } },
    ["6588dd77"] = { d = 14.2, v = "narrator", c = { x = { { 0.00, "Он полагал, что орки подверглись пагубному влиянию ещё до первого вторжения на Азерот." }, { 7.20, "Демоны ввели что-то в их кровь, и те стали невероятно сильны, выносливы и агрессивны." } } } },
    ["65a7d675"] = { d = 36.9, v = "narrator", c = { x = { { 0.00, "Застава Древобрюхов — небольшой лагерь фурболгов на западе Зимних Ключей, через дорогу к юго-востоку от Источников Ледяного Пламени." }, { 10.22, "Название напоминает о временах, когда здесь стояли Древобрюхи, но ныне заставу целиком удерживают их падшие сородичи из племени Зимней Спячки: следопыты, тотемники и стражи берлоги." }, { 24.11, "Древобрюхи из крепости у прохода в Осквернённый лес с горечью говорят, что бывшие союзники обратились против них, и принимают помощь лишь от тех, кто доказал свою верность." } } } },
    ["65c5b1bf"] = { d = 39.4, v = "narrator", c = { x = { { 0.00, "Тенистая долина — укромная поляна на северо-востоке Тельдрассила, окружённая горами и залитая вечными сумерками." }, { 9.30, "Единственный выход лежит на юг, к Доланаару, а в центре высится древо Альдрассил." }, { 16.05, "Здесь ночные эльфы делают первые шаги, и Опекун Илталайн следит за равновесием: после обильных дождей ночные саблезубы и щетинистые вепри расплодились сверх меры." }, { 29.62, "В долину вернулась дриада Тариндрелла, которую много лет не видели в Калимдоре, и старшие считают это тревожным знаком." } } } },
    ["65c75dd9"] = { d = 18.6, v = "human-male", c = { x = { { 0.00, "Как уже упоминалось выше, некоторые воргены хорошо владеют тайными искусствами, и их магия – магия тьмы и зла." }, { 7.90, "Для них обычны проклятия и жуткие яды, так что пусть читатель знает заранее: те, кто столкнётся с воргенскими магами, должны уметь оградить себя от тьмы." } } } },
    ["65cd26b0"] = { d = 48.2, v = "narrator", c = { x = { { 0.00, "Стратхольм — некогда северная жемчужина Лордерона, второй по величине город королевства и место, где архиепископ Алонсус Фаол основал орден Серебряной Длани." }, { 12.42, "Заражённое зерно из Андорала принесло в город чуму, и принц Артас, отвергнув Утера, вырезал жителей и предал Стратхольм огню." }, { 22.28, "Город горит по сей день." }, { 24.20, "Восточную его половину держит Плеть во главе с бароном Ривендером, рыцарем смерти на гнилой кобыле; западные кварталы заняли крестоносцы Алого ордена под командой Верховного рыцаря Датрохана." }, { 39.31, "Говорят, впрочем, что под его личиной скрывается повелитель ужаса, и обе стороны ведут в руинах бесконечную резню." } } } },
    ["65fe0dfb"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Лагерь Нараче стоит на северном краю плато Красного Облака — это селение племени Соколиного Ветра, где начинают свой путь юные таурены." }, { 10.94, "Вождь Соколиный Ветер посылает молодых на первые испытания, а его сын Грулл ведёт охоту на равнинных долгоногов." }, { 19.79, "Здесь же начинаются Обряды Матери-Земли — три испытания, которыми юный таурен заслуживает уважение старейшин Громового Утёса." }, { 29.72, "Провидица Воронье Перо ведёт молодых шаманов к зову земли." } } } },
    ["661bff24"] = { d = 28.0, v = "narrator", c = { x = { { 0.00, "Дольмен Кодо — природный памятник на плато Красного Облака, на полпути между Лагерем Нараче и Ежевичной лощиной." }, { 9.14, "Заметить его можно лишь с близкого расстояния." }, { 12.92, "Для тауренов это шаманское святилище: сюда юные шаманы приносят сапту — напиток, соединяющий дух со стихией, — и пьют её только здесь, в священном месте, чтобы впервые услышать голос земли." } } } },
    ["66303fc6"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Деревня Звёздного Ветра лежит на востоке Тельдрассила, между Тенистой долиной и Доланааром." }, { 7.10, "Прежде это было тихое поселение ночных эльфов из нескольких домов, и здесь жил Гэролас Талветрен, Великий смотритель за спящими друидами обители Бен'этиль." }, { 19.26, "Теперь деревню разграбили и заняли обезумевшие фурболги племени Кривой Сосны." }, { 25.38, "К северу от неё засела шайка мистиков во главе с Фероситасом Пожирателем Снов, чьё ожерелье светится зелёным в ночи." } } } },
    ["66338386"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Процветание и прошедшие годы не уменьшили ненависти клана Чёрного Железа к своим собратьям." }, { 7.38, "Тауриссан и его жена-волшебница Модгуд начали войну на два фронта против Стальгорна и Грим Батола." }, { 15.42, "Клан Чёрного Железа хотел заполучить весь Каз Модан для себя." } } } },
    ["666840ad"] = { d = 29.9, v = "human-female", c = { x = { { 0.00, "Стражники этой башни, похоже, ослаблены и не могут противостоять моим атакам." }, { 5.38, "При разведке с задней стороны башни патрулирующая её стражница заметила меня и напала." }, { 11.32, "Мне удалось легко её зарезать, своевременно уклонившись и затем ударив её в спину." }, { 16.95, "На шум пришёл её напарник." }, { 18.68, "Стражник подошёл прямо к тем кустам, куда мне пришлось оттащить труп и обыскать его." }, { 24.43, "Мне пришлось подкрадываться к нему медленно и осторожно, чтобы меня не обнаружили." } } } },
    ["668f0d0a"] = { d = 25.5, v = "narrator", c = { x = { { 0.00, "Мрачный склеп — усыпальница на вершине склона над кладбищем Могильника, у самых гор." }, { 6.73, "Именно здесь, среди гробов, приходят в себя те, кого чума подняла из мёртвых, но кто сумел вырваться из-под воли Короля-лича." }, { 16.97, "Смотритель склепа Мордо встречает их первым и отправляет вниз по тропе, к часовне, где ждёт жрец Тьмы Сарвис." } } } },
    ["66969951"] = { d = 19.1, v = "narrator", c = { x = { { 0.00, "Ферма Каменного Клыка стоит у западной дороги, сразу за воротами Оргриммара." }, { 6.12, "Это свиноферма, и её хозяева чувствуют себя в безопасности под стенами столицы." }, { 12.37, "Свиньи с этой фермы кормят Орду, а рядом, у пруда, всегда стоит кто-нибудь из стражи." } } } },
    ["669f9f2a"] = { d = 28.4, v = "narrator", c = { x = { { 0.00, "Остров Йоджамба — крошечная группа островков в северо-западном углу долины, у самой границы с Западным Краем." }, { 8.91, "Здесь высадилось племя Зандалар, вернувшееся в джунгли из-за возрождения Хаккара." }, { 15.44, "Зандалары не понимают чужаков, но зовут и Орду, и Альянс на бой со Свежевателем Душ, награждая героев печатями и талисманами." }, { 25.36, "С острова открывается путь к Зул'Гурубу." } } } },
    ["67211580"] = { d = 32.8, v = "narrator", c = { x = { { 0.00, "Река Скалистая начинается у водопада Скалистого в горах и течёт к северу от Аубердина через лес к морю, впадая в Туманный Предел." }, { 10.43, "Дорога пересекает её по высокому мосту." }, { 13.63, "Прежде это была чистая вода, но теперь река исполнилась порчи: звери, что пьют из неё, заболевают, и особенно страдают олени." }, { 23.84, "В верховьях стоят лагеря фурболгов Чернолесья, и в Аубердине опасаются, что зараза скоро дойдёт до самой деревни." } } } },
    ["67706253"] = { d = 13.4, v = "human-male", c = { x = { { 0.00, "После этого всадник поник, как будто чей-то дух покинул его." }, { 4.83, "И тогда прежним визгливым голосом старика он произнёс последние слова:" }, { 10.29, "\"Повелитель сказал своё слово." }, { 12.67, "Убить их\"." } } } },
    ["67d1e602"] = { d = 37.6, v = "narrator", c = { x = { { 0.00, "Павший Молот стоит на северо-востоке нагорья." }, { 3.68, "После Второй войны Альянс держал здесь один из крупнейших лагерей для пленных орков, и именно здесь при освобождении соплеменников погиб вождь Оргрим Молот Рока." }, { 16.33, "После Третьей войны Орда вернулась в руины лагеря и назвала заставу в память о павшем вожде." }, { 23.75, "Отсюда Осквернители Отрёкшихся держат путь в Низину Арати." }, { 28.28, "Огры Тяжёлого Кулака и тролли Сухокожие сговорились стереть Павший Молот с лица земли, и стража у ворот не знает покоя." } } } },
    ["67d1ec3f"] = { d = 34.0, v = "scourge-male", c = { x = { { 0.00, "Постарайся принять мои слова во внимание." }, { 3.90, "В наше время хитрость и обман распространены везде… даже в нашем славном Подгороде." }, { 11.69, "Каждый, кто сохраняет верность Сильване, вносит свой вклад в славное будущее Отрёкшихся." }, { 19.65, "Мы не владеем магией и не охраняем границы – наше ремесло иного рода." }, { 26.12, "Найди меня в таверне в Могильнике." }, { 29.35, "Там и поговорим." }, { 30.85, "-Давид Триас, наставник разбойников" } } } },
    ["67dd208a"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Сейчас Король-лич Артас пребывает в Нордсколе." }, { 3.50, "Говорят, что он собирается восстановить Ледяную Корону." }, { 7.60, "Его верный помощник Кел'Тузад командует силами Плети в Чумных землях." }, { 12.92, "Сильвана же со своими Отрёкшимися удерживает лишь Тирисфальские леса – небольшую часть растерзанного войной королевства." } } } },
    ["67df2eba"] = { d = 17.4, v = "dwarf-male", c = { x = { { 0.00, "Наших суматошных выстрелов оказалось достаточно, чтобы дать Барнилу время убежать." }, { 6.01, "Барнил скатился с холма и присоединился к нашей группе." }, { 10.06, "Мы побежали в джунгли, преследуемые стаей свирепых ящеров-кнутохвостов." }, { 15.22, "Охотники превратились в добычу." } } } },
    ["67ef3b98"] = { d = 23.1, v = "human-male", c = { x = { { 0.00, "Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений." }, { 7.19, "С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного." }, { 14.44, "Будет лучше, если они останутся в своём мире." }, { 17.72, "Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна..." } } } },
    ["67f9cf0e"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Сторожка Кель'Данил на западе Внутренних земель — одно из последних поселений высших эльфов в Лордероне." }, { 8.01, "Отсюда послы высших эльфов сносились с другими народами Альянса и делились тем, что знали о троллях Сухокожих, живущих южнее." }, { 17.67, "Со временем эльфы заключили союз с дворфами Громового Молота и навлекли на себя ненависть общих врагов, а Орда не раз посылала сюда своих лазутчиков." }, { 29.19, "Среди деревянных построек на склоне по-прежнему стоят на страже следопыты и магистры." } } } },
    ["6803b208"] = { d = 17.7, v = "narrator", c = { x = { { 0.00, "Но даже ослепнув, Мать-Земля не могла оставаться безучастной." }, { 5.10, "Ветер доносил до её ушей вести обо-всём, что происходило на рассветных равнинах." }, { 11.69, "Её любящее сердце всегда пребывало с её детьми, как и её великая мудрость." } } } },
    ["6817574c"] = { d = 20.2, v = "gnome-male", c = { x = { { 0.00, "Я в это время уже начал уставать – и потому развернул ветролет и направился домой, но по пути сделал ещё две остановки." }, { 9.28, "Я пролетел мимо Владыки Каззака и его демонов в Гниющем Шраме (он этого терпеть не может) и сбросил груз в трубу Ониксии." }, { 18.77, "Устал." }, { 19.33, "Пойду спать." } } } },
    ["68304e7e"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Даэ'ган раскинулся в сердце горы, в долине к северу от Святилища Авианы." }, { 5.87, "Даже имя этого места звучит чуждо: здесь укрепились демоны, оставшиеся на Хиджале после гибели Архимонда." }, { 14.50, "Не все слуги Легиона бежали в Теснину Зловещего Шёпота — часть их осела на самой горе, и с тех пор Даэ'ган остаётся гнездом Скверны посреди исцеляющегося леса." }, { 27.12, "Друиды не могут считать Хиджал очищенным, пока здесь горят демонические огни." } } } },
    ["683202e3"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Хотя смертные расы и одержали победу, их мир был растерзан войной." }, { 5.69, "Плеть и Пылающий Легион практически уничтожили все народы Лордерона и почти закончили свою работу в Калимдоре." }, { 15.08, "Леса нуждались в восстановлении, обиды – в забвении, а разорённые земли – в новых жителях." }, { 22.69, "Война нанесла тяжёлые раны каждой из рас, но все они нашли силы объединиться и начать новую жизнь." }, { 31.08, "Первым шагом к ней было перемирие между Альянсом и Ордой." } } } },
    ["683527eb"] = { d = 13.5, v = "human-male", c = { x = { { 0.00, "То, что я узнал об Аспектах, я привожу здесь для того, чтобы на это могли ссылаться другие." }, { 6.30, "Я знаю, что от моих изысканий будет польза и что эти драконы со временем ещё во многом повлияют на наш мир." } } } },
    ["686349ec"] = { d = 38.1, v = "narrator", c = { x = { { 0.00, "Убежище – маленькое поселение на севере болота, к западу от Болотного пристанища." }, { 6.29, "Здесь живёт горстка Заблудших, сохранивших рассудок, – изгнанники, которых ведёт Магтур." }, { 13.00, "Они называют себя дренеями и помнят, кем были до перехода через Тёмный портал; их обезумевшие сородичи из Болотного пристанища стали для них врагами и грабителями." }, { 25.58, "Больше всего изгнанники дорожат дренетистовыми кристаллами: без них, говорят они, и сами могут сбиться с пути." }, { 34.18, "Убежище держится в стороне от войны Орды и Альянса." } } } },
    ["686fd2ac"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Несмотря на то что практически бесконечной силы Саргераса с избытком хватало, чтобы победить зловещих эредаров, он был весьма обеспокоен разрушением и всепоглощающим злом, распространяемыми этими созданиями." }, { 16.39, "Неспособный понять такую развращённость, великий титан начал погружаться в отчаяние." }, { 23.14, "Несмотря на свою растущую тревогу, Саргерас всё же избавил вселенную от чернокнижников, заманив их в ловушку в Круговерти Пустоты." } } } },
    ["68849bb2"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "Калдорай или ночные эльфы, как их стали называть позже, поклоняются богине Луны, Элуне, и верят, что в дневное время она спит в мерцающей глубине Колодца." }, { 11.93, "В стародавние времена жрецы и провидцы ночных эльфов изучали Колодец с неиссякаемым энтузиазмом, пытаясь раскрыть его тайны и завладеть его силой." }, { 23.23, "Численность ночных эльфов постепенно увеличивалась, и они открывали для себя бескрайние просторы Калимдора, налаживали связи с многочисленными жителями этого материка." } } } },
    ["688a6d98"] = { d = 33.6, v = "nightelf-male", c = { x = { { 0.00, "После смерти Дартола фурболги разделили жезл на три части, чтобы уберечь себя от его воздействия." }, { 7.88, "Найти их будет нелегко, но я знаю, где находится каждая из частей." }, { 13.23, "Самоцвет" }, { 13.95, "Первая часть жезла – сверкающий драгоценный камень – была спрятана в святилище на северо-западе Ясеневого леса." }, { 22.91, "От этого святилища остались только развалины, расположенные посреди озера Фалатим." }, { 29.56, "Стражи сообщили мне, что сейчас там обитают мурлоки." } } } },
    ["68aa210a"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Трёх служителей кладбища." }, { 2.11, "Когда они попытались его успокоить, он перенёс свой гнев на них и, обвинив их во всех своих несчастьях, убил всех троих." }, { 11.96, "Позже Морган пришёл в себя и увидел свой меч в груди одного из служащих." }, { 17.98, "Осознание произошедшего привело его в отчаяние – он выхватил из ножен кинжал и вонзил его в своё сердце." }, { 26.70, "Тело Моргана Ладимора и тела трёх его жертв были найдены" } } } },
    ["68ef7cd6"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Деревня Рут'теран лежит у самого подножия Тельдрассила, среди его корней, на берегу Сокрытого Моря." }, { 8.10, "Это гавань острова: отсюда паром и гиппогрифы укротителя Весприста возят путников в Аубердин на Тёмных берегах, а мерцающий портал ведёт наверх, в Дарнасс." }, { 20.55, "Рыбаки здесь живут в достатке — рыба в этих водах крупная, и её много, как охотно рассказывает торговка Несса Песня Теней." }, { 30.46, "Для прибывающих с материка Рут'теран — первые ворота в край ночных эльфов." } } } },
    ["68f8ec02"] = { d = 18.8, v = "narrator", c = { x = { { 0.00, "Похлёбка Западного Края" }, { 2.15, "Три куска жилистого мяса стервятника" }, { 5.55, "Три рыла кровоклыка" }, { 7.37, "Три глаза мурлока" }, { 9.03, "Три окры" }, { 9.85, "Смешать и довести до кипения." }, { 12.59, "Тушить на медленном огне по крайней мере часа два и подавать на стол." } } } },
    ["692eef01"] = { d = 18.1, v = "narrator", c = { x = { { 0.00, "Небольшой раскоп в топях Болотины, где искатели древностей копаются в сырой земле." }, { 6.40, "Болотный грунт хранит кости давно вымерших тварей и обломки дворфийской старины, но каждую яму быстро затягивает водой, и работа продвигается медленно." } } } },
    ["6932466e"] = { d = 28.4, v = "scourge-male", c = { x = { { 0.00, "Следует отметить, что податель сего не только помог нам выполнить поставленную задачу, но также участвовал в ликвидации Ивара Нечистого, спасении Эрланда и в доставке данного отчёта." }, { 14.99, "Мы безгранично благодарны ему и хотим, чтобы командование по заслугам вознаградило его за огромный вклад в наш общий успех." }, { 25.13, "Страж смерти Ран Йорик," }, { 27.06, "Командир операции" } } } },
    ["6933a220"] = { d = 34.0, v = "scourge-male", c = { x = { { 0.00, "Постарайся принять мои слова во внимание." }, { 3.90, "В наше время хитрость и обман распространены везде… даже в нашем славном Подгороде." }, { 11.69, "Каждый, кто сохраняет верность Сильване, вносит свой вклад в славное будущее Отрёкшихся." }, { 19.65, "Мы не владеем магией и не охраняем границы – наше ремесло иного рода." }, { 26.12, "Найди меня в таверне в Могильнике." }, { 29.35, "Там и поговорим." }, { 30.85, "-Давид Триас, наставник разбойников" } } } },
    ["69590b9a"] = { d = 35.0, v = "gnome-male", c = { x = { { 0.00, "*(Вы пролистываете ещё несколько скреплённых страниц и попадаете на диаграмму, которая занимает целый разворот.)*" }, { 8.00, "Модификации оружейных систем." }, { 10.34, "Ледяная турель – опытный образец." }, { 13.04, "Огнемёт – опытный образец." }, { 15.10, "Электрический пульсатор – опытный образец." }, { 18.43, "Радиационный распылитель – опытный образец." }, { 21.84, "Автоматическое ружьё – опытный образец." }, { 24.89, "Лазерный резак – ПРОТОТИП." }, { 27.02, "Звуковая пушка – ПРОТОТИП." }, { 29.15, "Фазовый луч – В РАЗРАБОТКЕ." }, { 31.28, "Страница тридцать четыре." }, { 33.34, "Страница тридцать пять" } } } },
    ["699c8e4f"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Тралл взял легендарный боевой молот Молота Рока и надел свои чёрные доспехи; теперь он стал новым предводителем Орды." }, { 9.24, "Следующие несколько месяцев его маленькое неуловимое войско совершало набеги на лагеря военнопленных Альянса; войско Альянса было бессильно против него." }, { 21.39, "Под руководством своего лучшего друга и наставника, Грома Адского Крика, Тралл делал всё возможное, чтобы его народ никогда больше не испытал на себе гнёта рабства." } } } },
    ["699e28d5"] = { d = 30.1, g = 1, v = "nightelf-female", c = { m = { { 0.00, "Надеюсь, этот знак застанет тебя в добром здравии." }, { 3.31, "Духи поведали мне о твоём приходе, и я сразу же стала писать это письмо." }, { 8.01, "Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел." }, { 16.95, "После всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи." }, { 23.92, "Когда будешь готов, разыщи меня в Альдрассиле, на втором уровне." }, { 28.16, "-Шанда, наставница жрецов." } }, f = { { 0.00, "Надеюсь, этот знак застанет тебя в добром здравии." }, { 3.34, "Духи поведали мне о твоём приходе, и я сразу же стала писать это письмо." }, { 8.08, "Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел." }, { 17.10, "После всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи." }, { 24.13, "Когда будешь готова, разыщи меня в Альдрассиле, на втором уровне." }, { 28.46, "-Шанда, наставница жрецов." } } } },
    ["69a0ed61"] = { d = 38.6, v = "narrator", c = { x = { { 0.00, "Святилище Огненной Расщелины лежит на юго-западе Ясеневого леса, к югу от святилища Эссины." }, { 7.77, "Когда-то это было святое место ночных эльфов, но теперь его зовут местом великого зла: сюда пришли демоны, и земля вокруг выжжена и опалена." }, { 19.85, "В святилище поселился Илкруд Магтрулл — могучий орочий чернокнижник, служащий клану Тёмной Нити и его хозяину Атрикусу Нарассину." }, { 30.72, "Паладин Делгрен Очиститель с заставы Мейстры давно следит за ним и ждёт случая с ним разобраться." } } } },
    ["69a24409"] = { d = 36.6, v = "narrator", c = { x = { { 0.00, "Холодная долина — укромный уголок на юго-западе Дун Морога, отрезанный от остального края горами." }, { 7.79, "Долгие годы здесь было тихо, и молодые дворфы учились охотиться на скальных вепрей да ледолапых медведей." }, { 16.22, "Теперь в южной пещере обосновались тролли Мерзлогривы, а трогги напали на лагерь у замёрзшего озера, где стоит охотник Талин Остроглаз." }, { 26.93, "Грелин Белобород послан сюда разведать, насколько серьёзна угроза." }, { 32.22, "Единственный выход из долины — тоннель на северо-востоке." } } } },
    ["69ad8c03"] = { d = 32.5, v = "dwarf-female", c = { x = { { 0.00, "Не пристало скромной жене солдата задавать такие вопросы." }, { 4.36, "Но теперь я пишу вам как скромная вдова солдата." }, { 7.99, "Возможно, для вас мой муж был всего лишь одним солдатом из тысяч." }, { 12.76, "Для меня он был моим ненаглядным Салли Баллу, отцом моих детей и моим единственным спутником в этой жизни." }, { 20.81, "Простите меня, о великий владыка, если мои вопросы кажутся вам неуместными." }, { 26.52, "Но мёртвые не могут сами задать эти вопросы..." }, { 30.01, "Ваша верная подданная," }, { 31.75, "Сара Баллу" } } } },
    ["69b36293"] = { d = 24.8, v = "narrator", c = { x = { { 0.00, "В качестве последней награды Саргерас пообещал Гул'дану огромную силу в обмен на его согласие повести Орду на Азерот." }, { 9.89, "Через Медива Саргерас сказал чернокнижнику, что может сделать его богом во плоти, если тот найдёт подводную могилу, в которой Страж Эгвин тысячу лет назад укрыла останки Саргераса." } } } },
    ["69b41bc2"] = { d = 13.8, v = "dwarf-male", c = { x = { { 0.00, "Холодной долине и наёмников (нанятых на деньги, выделенные мне старейшиной Сената)," }, { 6.00, "Я уверен, что проблема будет решена в ближайшее время." }, { 10.03, "Вся кампания официально одобрена королём Бронзобородом." } } } },
    ["69e91bab"] = { d = 11.4, v = "human-male", c = { x = { { 0.00, "Я приеду, чтобы лично с вами встретиться, когда зимние ливни закончатся и по дорогам снова станет можно ездить." }, { 8.02, "С уважением," }, { 8.91, "Сталван Мистмантл из Серебряного бора" } } } },
    ["69ff2582"] = { d = 29.4, v = "dwarf-male", c = { x = { { 0.00, "Глава два – Стылая Кровь и Смотровая башня" }, { 3.08, "Когда ты разделаешься с первым слоем \"артишока\", тебе будет открыт второй." }, { 8.59, "Если уничтожить Башни Северного Волка, стоящие у линии фронта, то ослабнут вражеские легионеры и патрули с задних флангов." }, { 17.58, "Эти башни сильно укреплены, и в каждой из них находится по одному из элитных командоров Дрек'Тара." }, { 24.73, "Их надо убить." }, { 25.85, "Так ты ускоришь крах обороны клана Северного Волка." } } } },
    ["6a14d240"] = { d = 32.3, v = "narrator", c = { x = { { 0.00, "Эти дикие кочевники, которых притягивала энергия Источника, построили на его безмятежных берегах свои хижины." }, { 8.86, "Со временем космическая энергия Источника изменила племя, сделав его сильным, мудрым и практически бессмертным." }, { 17.78, "Племя стало называть себя \"калдорай\", что на их родном языке означало \"дети звёзд\"." }, { 24.48, "Прославляя расцвет своего общества, поселенцы воздвигли по берегам озера большие постройки и храмы." } } } },
    ["6a18c991"] = { d = 18.2, v = "dwarf-male", c = { x = { { 0.00, "Грелин, у меня мало времени и много забот; надеюсь, ваш интерес к троллям не сильно отвлечёт меня от моих дел." }, { 7.88, "Тем не менее я разрешаю вам ссылаться на меня при необходимости, если вы, разумеется, не станете выходить за рамки целесообразности." }, { 17.10, "Магни Бронзобород" } } } },
    ["6a2084ac"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Святилище Искусителя — осквернённый курган в Джеденаре, названный в честь Кил'джедена Искусителя, повелителя Пылающего Легиона." }, { 9.82, "Внутри собираются чернокнижники Совета Теней, и для неподготовленного путника это одно из самых опасных мест в лесу." }, { 18.99, "Тьма здесь густая, а воздух пропитан запахом Скверны." } } } },
    ["6a3af636"] = { d = 33.4, v = "orc-male", c = { x = { { 0.00, "Глава три – Четыре Командора" }, { 2.40, "Третий слой луковицы под названием Грозовая Вершина – четыре Командора." }, { 8.32, "В этом отношении Вандар перенял нашу славную тактику обороны Северного Волка." }, { 14.92, "Сам он, конечно, считает по-другому…" }, { 17.92, "Но я отвлёкся." }, { 19.04, "Четыре Командора повелевают Стражниками Грозовой Вершины, неусыпно охраняющими Дун Болдар." }, { 26.54, "Устрани их всех, и Стражники падут." }, { 29.47, "После этого останется лишь один, последний слой." } } } },
    ["6a67e918"] = { d = 15.8, v = "narrator", c = { x = { { 0.00, "Дворфы, от природы любившие придавать формы самоцветам и камню, начали добывать в близлежащих горах драгоценные минералы." }, { 9.22, "Довольные своими подземными трудами, дворфы не стремились общаться с наземными соседями." } } } },
    ["6a7b8a5e"] = { d = 63.3, v = "narrator", c = { x = { { 0.00, "Ясеневый лес — древняя чаща на севере Калимдора, между Тёмными берегами и Степями, от Сокрытого Моря до реки Строптивой." }, { 9.84, "Тысячи лет эти леса были владениями ночных эльфов, и они до сих пор держат здесь Астранаар и Приют Серебряного Ветра." }, { 19.54, "Но после Третьей войны в лес пришли орки клана Песни Войны: они основали заставу Расщеплённого Дерева и валят вековые деревья на востоке, а часовые Среброкрылых поклялись изгнать их из Ущелья Песни Войны." }, { 36.42, "Порча из Осквернённого леса отравила озёра и свела с ума фурболгов Колючего Меха и Гиблой Чащи." }, { 44.26, "В руинах Ксавиана и Сатирнаара укрылись сатиры, на Зорамском взморье хозяйничают наги, а над Каньоном Гибели Демона всё ещё чувствуется дыхание Пылающего Легиона." }, { 57.51, "Дожди здесь почти не прекращаются, но густые кроны не пропускают их вниз." } } } },
    ["6a83eed8"] = { d = 18.6, v = "narrator", c = { x = { { 0.00, "Пруд Стенделя — небольшой водоём к юго-западу от Сторожевого холма." }, { 5.15, "Вода здесь мутная, а по берегу расположились гноллы; кости и две старые могилы у кромки намекают, что пить из пруда не стоит." }, { 14.75, "Впрочем, рыбаки всё равно не обходят его стороной." } } } },
    ["6aa26b69"] = { d = 19.4, v = "dwarf-male", c = { x = { { 0.00, "Обугленные рога:" }, { 1.24, "Как и клыки пауков, обугленные рога химер, которые живут в Обугленной долине, что в Когтистых горах в Калимдоре, обладают весьма ценным свойством." }, { 11.88, "Расплющенные и должным образом обработанные, они становятся чрезвычайно стойкими к физическому воздействию." } } } },
    ["6acf2587"] = { d = 26.1, v = "narrator", c = { x = { { 0.00, "Сиширский каньон целиком захвачен пауками из густого мха." }, { 4.98, "Стены и дно затянуты паутиной, повсюду лежат кладки яиц, а в глубине каньона ждёт Бесселет, самая крупная и злобная из здешних тварей." }, { 16.66, "Маггран из Приюта у Солнечного Камня назначил за неё награду, но дорога сюда опасна даже для бывалого путника." } } } },
    ["6ae3f1b1"] = { d = 36.4, v = "narrator", c = { x = { { 0.00, "Застава Скитающихся Духов — небольшой лагерь Орды у самого края Кладбища кодо." }, { 6.44, "Здесь нет ни таверны, ни ветрокрылов, лишь шатры, торговцы да храбрецы-таурены на страже." }, { 13.46, "Шаманы заставы провожают умирающих кодо в иной мир и говорят с духами павших зверей — отсюда и её название." }, { 22.15, "Отсюда же Орда ведёт войну с кентаврами Колкар и демонами Пылающего Клинка, а чернокнижник из Отрёкшихся по имени Муарин ищет способ добраться до повелителя демонов лорда Азретока." } } } },
    ["6aecd243"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "В своей ярости Саргерас разрушил темницы, в которых были заперты эредары и Натрезим, и выпустил отвратительных демонов на свободу." }, { 10.30, "Эти коварные существа склонились пред необъятным гневом тёмного титана и предложили служить ему всеми доступными им злокозненными способами." }, { 21.31, "Из рядов могучих эредаров Саргерас выбрал двух предводителей, которых поставил во главе своей демонической армии разрушения." } } } },
    ["6af36ad3"] = { d = 27.8, v = "narrator", c = { x = { { 0.00, "Анналы Дарроушира." }, { 1.60, "Поселение Дарроушир, названное в честь озёра Дарроумир, находится к западу от этого озера на южной границе Лордерона." }, { 11.44, "Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война." }, { 22.58, "В ту войну появилось множество героев." }, { 25.86, "И потеряно было немало." } } } },
    ["6b0ae199"] = { d = 29.3, v = "dwarf-male", c = { x = { { 0.00, "Пантера понеслась вдоль опушки леса, а люди ни на секунду не спускали с неё взгляда." }, { 5.97, "Стволы их ружей медленно двигались, оставаясь идеально параллельными друг другу." }, { 11.69, "Барнил посмотрел на меня нетерпеливым взглядом, но я отрицательно покачал головой." }, { 17.54, "Это была охота людей, а не наша." }, { 19.98, "Эрлгедин выстрелил." }, { 21.39, "Раздался оглушительный грохот, но пантера осталась цела." }, { 25.44, "Вероятно, Эрлгедин не был готов к такой мощной отдаче." } } } },
    ["6b0bc572"] = { d = 29.5, v = "nightelf-female", c = { x = { { 0.00, "Элуна услышала мои молитвы." }, { 2.15, "Мои товарищи пали недаром, и коса Элуны поможет мне отомстить за них." }, { 7.38, "Это древняя вещь, ветка, изогнутая и искорёженная, из дерева, которое, должно быть, старше самих калдорай." }, { 15.24, "Много часов я исследовала дар богини." }, { 18.06, "С первого взгляда понятно, что это не обычное оружие и не простое магическое устройство." }, { 24.63, "С ним... словно барьеры времени и пространства ослабели." }, { 28.79, "Держа Косу" } } } },
    ["6b237133"] = { d = 27.8, v = "human-male", c = { x = { { 0.00, "Вэллик," }, { 0.52, "Охраняй раба до нашего возвращения." }, { 2.82, "Теперь здесь небезопасно, мы не можем больше хранить его тут." }, { 6.74, "Мы отправимся на север, обходя стороной любые места, где нас могли бы заметить." }, { 11.80, "Они – животные, но животные безжалостные – мы достаточно от них натерпелись, у нас есть причины для беспокойства." }, { 18.82, "Лучше спрятать любые знаки, что могли бы заставить собраться их вместе." }, { 23.43, "Меньше всего мы бы хотели дать им повод воссоединиться и напасть на нас." } } } },
    ["6b4464fe"] = { d = 27.3, g = 1, v = "scourge-male", c = { m = { { 0.00, "Лорд Бетор Ледострел," }, { 1.85, "Следуя вашим инструкциям, я отправляю вам агента, которого вы искали." }, { 7.78, "Он и принёс это письмо." }, { 9.79, "Он показал себя заслуживающим доверия и способным следовать приказам, показав себя в бою с силами Плети, и я выбираю его для вашей миссии." }, { 21.73, "Да будет Владычица властвовать безраздельно," }, { 25.51, "Мировой судья Севрен" } }, f = { { 0.00, "Лорд Бетор Ледострел," }, { 1.87, "Следуя вашим инструкциям, я отправляю вам агента, которого вы искали." }, { 7.85, "Он и принёс это письмо." }, { 9.87, "Он показал себя заслуживающим доверия и способной следовать приказам, показав себя в бою с силами Плети, и я выбираю её для вашей миссии." }, { 21.76, "Да будет Владычица властвовать безраздельно," }, { 25.57, "Мировой судья Севрен" } } } },
    ["6b5bec3a"] = { d = 38.3, v = "nightelf-male", c = { x = { { 0.00, "Хотя когда-то предположение, что человек может прийти в наши земли и учиться у нас, казалось мне смехотворным, этот волшебник, этот злой человек, пришёл сюда и не только выжил, но и обрёл часть наших знаний." }, { 15.78, "Я всё ещё не понимаю, как..." }, { 17.85, "Я так и не понял, сам план довольно прост: с помощью магии друидов он хотел подружиться с фурболгами, а затем подчинить их себе." }, { 27.54, "Если это была попытка повредить моим сородичам или совершить что-нибудь зловредное, я надеюсь узнать об этом прежде, чем закончится мой путь." } } } },
    ["6b7536ca"] = { d = 13.8, v = "dwarf-male", c = { x = { { 0.00, "Холодной долине и наёмников (нанятых на деньги, выделенные мне старейшиной Сената), я уверен, что проблема будет решена в ближайшее время." }, { 10.03, "Вся кампания официально одобрена королём Бронзобородом." } } } },
    ["6b872f84"] = { d = 4.8, v = "narrator", c = { x = { { 0.00, "(Глядя на эти страницы, вы чувствуете жгучую боль.)" } } } },
    ["6b8d5803"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Каменный карьер — рудник на северо-восточной окраине Степей, у самой границы с Дуротаром." }, { 6.66, "Орочьи постройки и знамёна говорят, что когда-то он принадлежал Орде, но теперь здесь хозяйничает Торговая Компания под началом начальника Медноклина, ревниво хранящего секреты самофланжа." }, { 20.38, "По слухам, что ходят на пристани Кабестана, один из шахтёров нашёл здесь изумруд величиной с кулак, и охотников до такой добычи хватает." } } } },
    ["6b982ced"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "На северном берегу Болотины, у Болот Синежабрых, лежат остовы Третьей флотилии Кул-Тираса — Погибший Флот." }, { 8.06, "Корабли вышли из Лордерона во время Второй войны и были сожжены и потоплены красными драконами, которых тогда держали в рабстве орки Драконьей Пасти." }, { 19.53, "Экипажи не нашли покоя: по разбитым палубам бродят призраки и скелеты моряков, а в трюме одного из судов, говорят, до сих пор спрятан проклятый груз." }, { 30.79, "Немногие отваживаются подниматься на эти обломки." } } } },
    ["6bca6653"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Пиршество" }, { 0.76, "Обычай устраивать на этот праздник пиршества тянется корнями в глубь самой легенды." }, { 7.22, "Она гласит, что, когда Дедушка Зима шёл по Азероту, укрывая его снегами, тех, кто приветствовал его появление, он осыпал дарами." }, { 17.15, "И потому традиция пировать на Зимний Покров объединила между собой общины, члены которых совместно вкушали на пиру разные яства." }, { 27.22, "Обычно обновление и перерождение земли приветствовали весельем и празднеством в течение целого дня." } } } },
    ["6be5457f"] = { d = 24.0, v = "narrator", c = { x = { { 0.00, "Обугленная пещера прячется в юго-западном углу ущелья, у самого подножия Чёрной горы." }, { 7.18, "Вход в неё завален камнем, и что скрывают её глубины, никто не знает." }, { 12.86, "Говорят лишь, что в пору, когда год обновляется и луна светит ярко, у пещеры пробуждается дух древнего старейшины из племени земельников." } } } },
    ["6c5028b0"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Битва за Дарроушир" }, { 1.45, "Битва за Дарроушир произошла в середине Второй войны, когда силы Плети бесчинствовали по всему Лордерону." }, { 9.61, "Хотя поселение Дарроушир было отрезано от основных сил Альянса, в нём был отряд собственных войск, подразделение паладинов Серебряной Длани, а также местное ополчение, которое возглавлял капитан Джозеф Редпат." } } } },
    ["6c508208"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Вершина Старейшин лежит к востоку от центрального утёса и соединена с ним верёвочными мостами." }, { 7.49, "Здесь живут друиды и жрецы тауренов, здесь собирается совет старейшин и держит слово верховный друид Хамуул Рунический Тотем, старший из друидов Круга Кенария в Громовом Утёсе." }, { 21.89, "В шатре между двумя мостами обитает Магата из племени Зловещего Тотема, старая и много знающая о духах." }, { 30.48, "Не все в городе доверяют ей, но никто не смеет прогнать." } } } },
    ["6c6217e2"] = { d = 31.0, v = "human-male", c = { x = { { 0.00, "Я отдам приказ Многоглазу открыть огонь." }, { 2.68, "Артиллерийский обстрел помешает кораблям Черноводья выходить из гавани и входить в неё." }, { 8.29, "После того как \"Багровый Парус\" разрядит свои пушки, я поставлю его рядом с \"Буруном\" для поддержки и обеспечения резервов, если это понадобится." }, { 17.80, "Когда Солёное Копыто и его парни вычистят город и все наши будут на борту, мы поднимем паруса и ещё разок обстреляем Пиратскую Бухту со стороны Гибельного берега, для очистки совести." }, { 29.70, "--Флотоводец Фираллон" } } } },
    ["6c8a2696"] = { d = 42.6, v = "narrator", c = { x = { { 0.00, "Сильвия Вэлор, стражница Вороньего Холма." }, { 3.37, "Сильвия Вэлор прослыла местной героиней задолго до того, как ей предложили вступить в стражу." }, { 10.82, "Больше всего на свете она не терпела тех, кто наживается на чужой беде." }, { 16.56, "Разбойники, мошенники, смутьяны – ей было всё равно." }, { 20.71, "Каждый, кто пытался посеять смуту в её любимом доме, падал от её меча." }, { 26.38, "Неудивительно, что ей доверили настоящую власть, чтобы она вершила правосудие так, как его понимала." }, { 34.26, "Говорят, до последнего вздоха она не покидала фермы и дома Сумеречного леса." }, { 40.43, "А может, не покинула и после." } } } },
    ["6c969d31"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Рыцари смерти и последователи клана Призрачной Луны, верные Нер'зулу, также подверглись трансформации: их разорвали на части, а затем превратили в костяных Королей Мёртвых." }, { 13.74, "Демоны позаботились о том, чтобы даже после смерти последователи Нер'зула беспрекословно служили ему." } } } },
    ["6c99452b"] = { d = 30.0, g = 1, v = "nightelf-female", c = { m = { { 0.00, "Надеюсь, этот знак застанет тебя в добром здравии." }, { 3.31, "Духи поведали мне о твоём приходе, и я сразу же стала писать это письмо." }, { 8.01, "Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел." }, { 16.95, "После всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи." }, { 23.92, "Когда будешь готов, разыщи меня в Альдрассиле, на втором уровне." }, { 28.16, "-Шанда, наставница жрецов." } }, f = { { 0.00, "Надеюсь, этот знак застанет тебя в добром здравии." }, { 3.33, "Духи поведали мне о твоём приходе, и я сразу же стала писать это письмо." }, { 8.06, "Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел." }, { 17.06, "После всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи." }, { 24.06, "Когда будешь готова, разыщи меня в Альдрассиле, на втором уровне." }, { 28.39, "-Шанда, наставница жрецов." } } } },
    ["6c9fdadd"] = { d = 34.2, v = "nightelf-male", c = { x = { { 0.00, "Мастер Делгрен!" }, { 1.25, "Всё так, как ты опасался." }, { 3.13, "Твоя теория о башне Алталакса оказалась верной." }, { 6.89, "В башне собрался культ, среди них много чернокнижников, есть даже сатиры." }, { 12.53, "Они называют себя кланом Тёмной Нити." }, { 15.52, "Я не могу представить себе, какая недобрая цель свела их друг с другом, но это беспокоит меня." }, { 22.83, "Пожалуйста, прости краткость и резкость этого сообщения, но опасность таится в лесу вокруг, и я не могу посвятить много слов описанию происходящего." }, { 34.25, "Я" } } } },
    ["6ca4e3e1"] = { d = 20.8, v = "human-male", c = { x = { { 0.00, "*На обратной стороне договора было написано быстрым почерком*" }, { 4.56, "Мы припугнули Хмуроброва и получили этот договор." }, { 7.85, "Он может пригодиться, если нам вдруг понадобится их участок." }, { 11.79, "Хмуробровы нам уже не помеха." }, { 13.77, "Последний раз, когда я их видел, они уезжали из Западного Края и остановились, чтобы починить свою повозку." } } } },
    ["6cf1099c"] = { d = 28.7, v = "orc-male", c = { x = { { 0.00, "Глава четыре – Укрытия Дун Болдара" }, { 3.06, "Как ты, несомненно, заметил, линии обороны Грозовой Вершины выстроены так, чтобы не дать массированному удару сокрушить сразу всю армию." }, { 14.83, "Сразу отвечу на твои вопросы." }, { 17.50, "Да, именно так организована и наша оборона, и нет, менять её расположение я не стану." }, { 24.80, "Они переняли всё у нас, с чего бы нам меняться?" } } } },
    ["6cf1eb16"] = { d = 30.5, v = "narrator", c = { x = { { 0.00, "Некоторое время три фракции поддерживали хрупкий мир, однако напряжение возросло, когда король Старая Наковальня скончался от старости." }, { 10.89, "Три правящих клана вступили в войну за контроль над Стальгорном." }, { 16.04, "Гражданская война дворфов многие годы пылала под землёй." }, { 20.62, "В конце концов клан Бронзобородов, имевший самую большую армию, изгнал кланы Чёрного Железа и Громового Молота из-под горы." } } } },
    ["6d0d17d6"] = { d = 44.6, v = "narrator", c = { x = { { 0.00, "Под усадьбой дома Баровых на острове Каэр Дарроу укрылся Некроситет, школа некромантии." }, { 7.36, "Перед Третьей войной Кел'Тузад заключил с Баровыми сделку, и в катакомбах древней крепости обосновался Культ Проклятых." }, { 17.28, "Здесь послушники учились поднимать мёртвых, а слуг семьи использовали для опытов с Чумой нежити." }, { 25.18, "Ныне школой заправляет тёмный магистр Гандлинг, а среди его наставников лич Рас Снегошёпот." }, { 32.69, "У ворот стерегут вход стражи Плети, и ключ к этим дверям достаётся нелегко." }, { 38.93, "Ходят слухи, что здесь выращивают даже зачумлённых драконьих детёнышей." } } } },
    ["6d263a59"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Грибная долина к северу от поместья Маррисов и Башни королевской стражи — одно из самых поражённых чумой мест края." }, { 9.39, "Земля здесь потемнела до лилового, над ней висит мутная дымка, а между исполинскими грибами тянутся тропы Плети." }, { 18.56, "В долине хозяйничают вурдалаки и служители Культа Проклятых, и путнику лучше держаться дороги, не углубляясь в эту мглу." } } } },
    ["6d3f78aa"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Власть Эгвин над космическими силами Тирисфаля росла, и однажды она узнала, что на ледяном северном континенте Нордскол обитает несколько могущественных демонов." }, { 12.56, "Отправившись на дальний север, Эгвин выследила демонов в горах." }, { 17.58, "Там она обнаружила, что демоны охотились на последних драконов и вытягивали из древних существ их магическую силу." } } } },
    ["6d4776d9"] = { d = 25.7, v = "human-male", c = { x = { { 0.00, "Потеря крепости Каменной Стражи стала для нас сильным ударом." }, { 4.55, "Я уже сообщал ранее о союзе между кланом Чёрной горы и чернокнижником Моргантом." }, { 10.48, "Эти орки сражаются с наводящим ужас неистовством, и, похоже, здесь не обошлось без чёрной магии Морганта." }, { 18.12, "Храбрейшие из воинов его величества отдали свои жизни при обороне крепости, но поражение было неминуемо." } } } },
    ["6d4f8ac5"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Со временем Нер'зул осознал, что судьба кланов – в руках Пылающего Легиона, и тогда шаман бросил вызов Кил'джедену." }, { 9.36, "Демон, разъярённый поступком Нер'зула, обратился к ученику шамана, Гул'дану, склонить которого ко злу оказалось куда проще, чем Нер'зула." } } } },
    ["6d5f999d"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Саргерон — руины древнего города ночных эльфов на северо-востоке Пустошей, разрушенного ещё в Войну Древних." }, { 8.76, "Его истинное имя забыто; сатиры, поселившиеся среди колонн, назвали его Саргероном в честь своего хозяина Саргераса." }, { 18.31, "Когда-то здесь стояли святилища Элуны, и в развалинах ещё можно найти её реликвии — жаровню, чашу и древние рунные камни." }, { 28.16, "Теперь между ними крадутся сатиры, связанные с Пылающим Клинком, и Элуну здесь давно не чтут." } } } },
    ["6d796b00"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Храбростан — маленькая застава Орды на северо-западе Азшары, прижатая к горам." }, { 6.30, "Орде эта земля мало интересна, и лагерь беден и плохо защищён." }, { 11.38, "Когда-то здесь стояло больше воинов, но большинство погибли по вине волхва Римтори — эльфийки крови, которую Белгром прислал из Оргриммара за сокровищами высокорождённых." }, { 24.69, "Сюда же в наказание сослана Джедига: она ищет древние таблички, чтобы выбраться из Азшары." }, { 31.99, "Отсюда летают ветрокрылы в Оргриммар и Ясеневый лес." } } } },
    ["6d8593d5"] = { d = 24.7, v = "narrator", c = { x = { { 0.00, "Терраса Ремесленников занимает север Дарнасса." }, { 3.66, "Здесь живут и учат мастера всех ремёсел, здесь же стоит одна из главных таверн города." }, { 10.36, "Свои дела ведут гильдии, а посланники Серебряного Рассвета принимают тех, кто хочет помочь в борьбе с Плетью." }, { 18.95, "Отсюда дороги ведут на юг, к Террасе Воинов, и на запад, к Анклаву Кенария." } } } },
    ["6d8ad5b9"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "Несмотря на тяжёлое детство, Тралл вырос сильным и умным орком; он осознавал, что участь раба – не для него." }, { 8.50, "Повзрослев, он узнал многое об истории своего народа, представителей которого он почти не видел: после поражения в войне практически все орки попали в лагеря для военнопленных." }, { 22.42, "Ходили слухи, что вождю Молоту Рока удалось бежать из Лордерона." }, { 27.63, "И лишь один клан орков всё ещё оставался на свободе, скрываясь от бдительных глаз Альянса." } } } },
    ["6d8e6e76"] = { d = 24.1, v = "narrator", c = { x = { { 0.00, "Воровской лагерь – одно из тех мест, что значатся лишь на старых картах королевства." }, { 6.26, "Лагеря Братства Справедливости и вправду разбросаны по всему Элвиннскому лесу: бандиты в красных повязках жмутся к опушкам и брошенным фермам, деля добычу у костров." }, { 18.78, "Стража Штормграда знает о них, но людей, чтобы очистить лес, не хватает." } } } },
    ["6e111cd7"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Война." }, { 0.62, "Морган служил под командованием легендарного паладина Утера Светоносного, который сражался с орками и нежитью." }, { 10.09, "Оставив жену и детей, Морган отправился на войну." }, { 14.44, "Шли годы, война затягивалась." }, { 17.00, "Морган стал свидетелем ужаснейших событий, включая расформирование паладинов Серебряной Длани, гибель Утера и эпидемию чумы." }, { 27.72, "Единственная причина, по которой он не сошёл с ума, была уверенность в том, что" } } } },
    ["6e215fa1"] = { d = 22.5, v = "narrator", c = { x = { { 0.00, "Башня Эльдары стоит на самой оконечности мыса к северо-востоку от залива Бурь." }, { 6.52, "Когда-то она была частью обширных владений ночных эльфов, что простирались по всей Азшаре, а теперь стоит запертой и заброшенной." }, { 17.31, "Песчаные пляжи вокруг неё патрулируют мурлоки, макрура и гидры." } } } },
    ["6e24726d"] = { d = 20.6, v = "skyborne-male" },
    ["6e2ff1d5"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Пустынный берег тянется вдоль западного побережья северной части долины — от границы с Западным Краем до лагеря Гром'гол." }, { 9.76, "Песчаные отмели и скалы облюбовали кроколиски и василиски, а по берегу разбросаны троллиные руины, занятые племенем Кровавого Скальпа." }, { 20.53, "У побережья лежит Коварный риф, где среди затонувших развалин живут мурлоки." }, { 26.68, "Это дикое место, где джунгли выходят прямо к Великому морю." } } } },
    ["6e4ce9f5"] = { d = 63.5, v = "narrator", c = { x = { { 0.00, "Красногорье лежит к востоку от Элвиннского леса, там, где земли Штормграда упираются в красные скалы предгорий, а на севере за перевалом дымятся Пылающие степи." }, { 12.75, "В сердце края лежит Озеро Безмолвия, а на его берегу стоит Приозёрье, единственный оплот людей в этих горах." }, { 21.49, "Времена тревожные: орки клана Чёрной Горы спустились из степей и захватили крепость Каменной Стражи, а беженцы с северных земель набились в город." }, { 33.16, "Подкрепления из Штормграда так и не пришли, и мировой судья Соломон шлёт гонцов к соседям в надежде на помощь." }, { 41.83, "В холмах воют гноллы стаи Красногорья, на востоке чародей Моргант из башни Илгалара повелевает гноллами Темношкурами, а в озере расплодились мурлоки." }, { 53.79, "И всё же город держится: маршал Маррис у моста собирает добровольцев, а кузнец Вернер Осгуд куёт оружие для защитников края." } } } },
    ["6e4f9a34"] = { d = 32.2, v = "gnome-male", c = { x = { { 0.00, "Джариен и Сотос." }, { 1.24, "Брат и сестра, последователи Алого ордена" }, { 4.24, "Я не знаю людей более нетерпимых, чем Джариен и Сотос." }, { 8.22, "Но воины они, надо признать, непревзойдённые, если им хорошо платят; думаю, именно поэтому Антион, глава Тайных клинков, их так ценит." }, { 18.01, "Этих двоих завораживали учения Алого ордена." }, { 21.34, "Мы всегда подозревали, что их родители имели какое-то отношение к этой организации; да и они сами с необыкновенным рвением вступали в сражения с Плетью." } } } },
    ["6e68ae32"] = { d = 34.9, g = 1, v = "scourge-male", c = { m = { { 0.00, "Рад, что твоя душа не попала в Пустоту." }, { 3.41, "Я полагаю, ты стоишь усилий, затраченных на написание этого свитка." }, { 9.23, "Помни: людей, которых ты знал и любил, больше нет в живых!" }, { 14.27, "Ты должен пронести этот груз через всё своё дальнейшее существование." }, { 20.17, "Советую тебе смириться с этим с самого начала." }, { 24.28, "Если ты готов к испытаниям, найди меня в церкви Могильника." }, { 29.48, "- Тёмный священник Дьюстен, наставник жрецов" } }, f = { { 0.00, "Рад, что твоя душа не попала в Пустоту." }, { 3.56, "Я полагаю, ты стоишь усилий, затраченных на написание этого свитка." }, { 9.63, "Помни: людей, которых ты знала и любила, больше нет в живых!" }, { 15.13, "Ты должна пронести этот груз через всё своё дальнейшее существование." }, { 21.28, "Советую тебе смириться с этим с самого начала." }, { 25.57, "Если ты готова к испытаниям, найди меня в церкви Могильника." }, { 31.08, "- Тёмный священник Дьюстен, наставник жрецов" } } } },
    ["6e88d8e1"] = { d = 68.6, v = "narrator", c = { x = { { 0.00, "Выжженные земли — мёртвая красная пустыня на самом юге Восточных королевств." }, { 6.33, "Когда-то здесь была глухая топь, но магия Тёмного портала, через который на Азерот хлынула Орда, навсегда искалечила эту землю: почва спеклась в багровую глину, вода ушла, и лишь василиски, скорпионы и гиены живут среди раскалённых скал." }, { 25.91, "После Второй войны врата были разрушены, и по настоянию архимага Кадгара на единственной дороге сюда поднялась Крепость Стражей Пустоты, чтобы никто больше не пришёл из Дренора." }, { 40.65, "Двадцать лет Портал молчит, но покоя здесь нет: на западе, в Гниющем Шраме, засели демоны Пылающего Легиона во главе с Владыкой Каззаком, а по пустыне бродят огры клана Молота Ужаса." }, { 55.76, "Днём здесь сухо и жарко, ночью — пронизывающе холодно, и лишь молнии да ветер тревожат тишину." }, { 63.50, "Путнику здесь никто не рад, даже суровые маги Стражей Пустоты." } } } },
    ["6e929800"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Северное побережье — полоса каменистого пляжа вдоль Великого моря на северной кромке Тирисфаля." }, { 7.39, "С тех пор как чума отравила эти земли, берег стал тёмным и холодным: у кромки воды гниют выброшенные морем туши, а среди хижин копошатся мурлоки и их головастики — нерестилища этих тварей совсем недалеко от берега." }, { 23.97, "Здесь же лежат обломки старого кораблекрушения." } } } },
    ["6e94870f"] = { d = 35.5, v = "narrator", c = { x = { { 0.00, "Пока в самом сердце Азшары гремела битва, одурманенная королева с нетерпением дожидалась прибытия Саргераса, который готовился пройти сквозь источник Вечности и самолично ступить на землю Азерота." }, { 15.22, "Его исполинская тень медленно приближалась к поверхности Источника, а Азшара тем временем собрала своих самых могущественных служителей, чтобы они объединили свои силы, прочитали одно заклинание и расширили портал настолько, чтобы Саргерас смог пройти через него." } } } },
    ["6e9c107b"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Лагерь Алого ордена — небольшое укрепление за частоколом на восточном берегу озера Мерельдар, невдалеке от Длани Тира." }, { 9.40, "Отсюда крестоносцы выходят в дозоры по южным дорогам и встречают гонцов, что идут в Стратхольм и обратно." }, { 17.74, "Путнику стоит помнить: для Алых любой чужак — возможный разносчик чумы." } } } },
    ["6ed9d6c1"] = { d = 25.4, g = 1, v = "human-male", c = { m = { { 0.00, "Мастер Кэрвин!" }, { 1.08, "Принёсший это сообщение осенён благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Кэрвин на их пути к Свету." }, { 14.45, "В моём послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света." }, { 24.25, "С уважением," }, { 25.14, "Калор" } }, f = { { 0.00, "Мастер Кэрвин!" }, { 1.07, "Принёсшая это сообщение осенена благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Кэрвин на их пути к Свету." }, { 14.37, "В моём послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света." }, { 24.03, "С уважением," }, { 24.90, "Калор" } } } },
    ["6edb582d"] = { d = 37.0, v = "orc-male", c = { x = { { 0.00, "Колокол, Колесо и Свеча" }, { 1.92, "Освободившись, Д'жииви разместит Колокол, Колесо и Свечу, после чего появится круг." }, { 8.53, "Так начинается ритуал." }, { 10.31, "Нужно сохранять бдительность: упомянутые предметы испускают мощные потоки энергии и могут разрушиться." }, { 18.41, "Если это случится, скорее используй Чёрный магнит, чтобы восстановить их, прежде чем весь ритуал пойдёт насмарку." }, { 27.30, "Если все три предмета разрушатся прежде, чем ты сумеешь их восстановить, ритуал закончится и его надо будет начинать заново." } } } },
    ["6ee42c86"] = { d = 27.8, v = "human-male", c = { x = { { 0.00, "*Верховный маг Кадгар из Кирин-Тора Бывший ученик Медива.*" }, { 4.62, "*Верховный главнокомандующий экспедиции Альянса, которая отправилась на Дренор, родной мир орков.*" }, { 12.40, "*Предположительно погиб.*" }, { 14.24, "Никто и никогда так самоотверженно не погружался в тёмные глубины магии и искусства войны." }, { 21.05, "Мы желаем тебе добра, смелый странник." }, { 24.07, "Где бы ты ни был." }, { 25.31, "- Антонидас, верховный маг Даларана" } } } },
    ["6f2e823e"] = { d = 17.5, v = "narrator", c = { x = { { 0.00, "Глава два: ВОСТОЧНЫЙ ПИЛОН." }, { 2.30, "Восточный пилон принимает синие, жёлтые и зелёные кристаллы." }, { 7.20, "Пилон фокусирует энергию, которая может быть создана при использовании синих кристаллов в качестве основного источника энергии." } } } },
    ["6f335465"] = { d = 24.2, v = "human-male", c = { x = { { 0.00, "Высокий Совет Лордов Бездны" }, { 1.94, "Обращаться к Принцу Скальдреноксу, Верховному маршалу Круговерту, Барону Казуму или Лорду Скволу позволено лишь Сумеречным Лордам." }, { 10.75, "Ни при каких обстоятельствах нижние чины Сумеречного Молота не могут начать общение с Высоким Советом." }, { 17.68, "Любой чужак, застигнутый за использованием с этой целью ветровых камней, будет испепелён на месте." } } } },
    ["6f572019"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Сторожка Кель'Литиен у самого входа в Кель'Талас — охотничий приют высших эльфов, одна из двух крупных общин их народа в Лордероне." }, { 9.92, "Некогда следопыты радушно принимали здесь гостей из Луносвета и хранили в стенах сторожки эльфийские летописи." }, { 18.20, "После нашествия Плети сторожка осталась отрезанной от родины, и её обитатели ожесточились: они не доверяют никому и встречают чужаков стрелами." }, { 29.00, "С владыкой следопытов, что правит сторожкой, есть свои счёты и у Натаноса из поместья Маррисов." } } } },
    ["6f64e6b1"] = { d = 29.8, v = "dwarf-male", c = { x = { { 0.00, "За одним лишь исключением." }, { 1.72, "Странно высеченные идолы, что мы обнаружили недавно (краткое их описание прилагалось к моему последнему докладу), похоже, возымели побочный эффект на троггов на месте раскопок." }, { 13.27, "Их притягивают эти высеченные фигуры, и некоторые трогги впадают из-за них в ярость!" }, { 18.84, "Необходимо изучить этих идолов внимательнее, чтобы сделать по поводу них какие либо выводы, но я всё ещё надеюсь, что они прольют свет на связь между троггами и титанами." } } } },
    ["6f71986d"] = { d = 37.3, v = "narrator", c = { x = { { 0.00, "На северо-западе пустыни, у подножия гор, стоит Форт Молота Ужаса — крепость, некогда заложенная орками как одно из первых их поселений на Азероте." }, { 12.23, "После войн её захватили огры клана Молота Ужаса: они пришли сквозь Тёмный портал вместе с Ордой, но, в отличие от орков, так и остались в Выжженных землях." }, { 25.21, "Отсюда огры и их маги совершают набеги на Крепость Стражей Пустоты, а в обгоревших орочьих строениях гремят их грубые пиры." }, { 35.62, "Чужаку здесь не рады." } } } },
    ["6fa5800f"] = { d = 37.8, v = "narrator", c = { x = { { 0.00, "Дозор Моргана — последний оплот Альянса в степях, укрывшийся в юго-восточном углу зоны." }, { 7.03, "Когда-то это была деревня с каменной башней мага, но от неё остались лишь обгорелые стены; ныне жители ютятся в палатках между развалин." }, { 17.89, "Гарнизоном командует маршал Максвелл, а вместе с ним здесь несут службу разведчики и учёные, следящие за кланом Чёрной горы и чёрными драконами." }, { 29.04, "Отсюда грифоны летят в Штормград, и для героев Альянса это единственное место в степях, где можно перевести дух." } } } },
    ["6fb10b04"] = { d = 26.9, v = "narrator", c = { x = { { 0.00, "От капитана Редпата порча перекинулась и на других защитников Дарроушира, которые после этого предавали и убивали своих бывших союзников." }, { 10.69, "Потом они вошли в поселение и перерезали всех, кто укрылся в домах." }, { 15.92, "Остатки армии Плети вместе с чёрной тенью Редпата покинули разорённое поселение и ворвались в Лордерон, неся с собой боль и смерть Второй войны." } } } },
    ["6fb2900e"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Высокогорье — холмистая земля на северо-востоке Альтеракских гор." }, { 5.04, "Когда-то это была житница королевства Альтерак, но после гибели государства здесь укрепился Синдикат: на холмах стоят его лагеря, и нигде разбойники не чувствуют себя так вольготно." }, { 19.16, "Среди их главарей известен барон Вардус, чьи головорезы нападают на Южнобережье." }, { 25.39, "На западной окраине Высокогорья, у самого озера, прячется Овчарня Дандреда — убежище вожаков Синдиката." } } } },
    ["6fb82be0"] = { d = 43.0, v = "narrator", c = { x = { { 0.00, "Лагерь Промозглого Ветра стоит на самом юге, там, где дорога из Альтерака входит в Чумные земли." }, { 7.21, "Это последнее безопасное место для путников Альянса: здесь держится небольшой отряд Серебряного Рассвета, сюда же присылают на закалку молодых паладинов Серебряной Длани." }, { 19.82, "Сил у лагеря немного, поэтому Рассвет полагается на наёмников и добровольцев, ведя тайную войну против Андорала и чумных котлов." }, { 29.29, "Высшая жрица Макдонелл собирает образцы отравы из котлов, надеясь обратить их против самой Плети." }, { 36.63, "Отсюда же грифоны уносят гонцов в Стальгорн, Южнобережье и к часовне Последней Надежды." } } } },
    ["6fc94cce"] = { d = 28.1, v = "narrator", c = { x = { { 0.00, "Поднятая из затопленных руин Сурамара, эта всё ещё работающая астролябия, была создана высокорождёнными эльфами около двенадцати тысяч лет назад." }, { 11.02, "Высокорождённые, одержимые магией, оккультными науками и астрономией, создали множество гениальных инструментов." }, { 19.42, "Это приспособление позволяет нам получить неоценимое представление об уровне развития наук у древних ночных эльфов." } } } },
    ["6fcad6df"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Пруды Арлитриэна — россыпь малых водоёмов на западе Тельдрассила, к юго-востоку от входа в Дарнасс." }, { 7.25, "Когда-то здесь было спокойно, но теперь у воды хозяйничают злобные твари." }, { 12.66, "На берегу стоит одинокий лунный колодец, который ночные эльфы оставили без присмотра: Часовым всё труднее наблюдать за этими местами из-за участившихся нападений фурболгов Кривой Сосны." } } } },
    ["6fd72302"] = { d = 19.2, v = "narrator", c = { x = { { 0.00, "Горькими плёсами называют северо-восток Азшары." }, { 3.77, "Здесь во множестве водятся гиппогрифы, слизнюки и химеры, а по северному краю бродят горные великаны, вытеснившие прочую живность." }, { 14.21, "Среди осенних трав изредка попадается горный серебряный шалфей." } } } },
    ["6ff4e44b"] = { d = 17.0, v = "narrator", c = { x = { { 0.00, "Жители Даларана спокойно отнеслись к деятельности магов и создали бурную экономику под их защитой." }, { 7.71, "Но чем больше и больше магов практиковало свои искусства, тем больше ткань реальности вокруг Даларана слабела и рвалась." } } } },
    ["6ffb323a"] = { d = 46.0, v = "narrator", c = { x = { { 0.00, "На северо-востоке горы, выше всех её хребтов, поднимается Вершина Вечности: здесь стоит Нордрассил, Древо Жизни, а под его корнями скрыт новый Источник Вечности." }, { 14.32, "Сюда в конце Третьей войны прорвался Архимонд, чтобы вырвать древо и завладеть Источником." }, { 22.48, "Малфурион призвал к Нордрассилу тысячи огоньков, и их жертва испепелила демона, но опалила и само древо, а с чарами драконов ушло и бессмертие калдорай." }, { 36.00, "Нордрассил медленно залечивает раны под присмотром друидов, а у его подножия по сей день белеют кости Осквернителя." } } } },
    ["6ffb4d64"] = { d = 32.6, v = "narrator", c = { x = { { 0.00, "Внутренний Круг Обуздания лежит на юге нагорья, неподалёку от Стромгарда." }, { 6.02, "Здесь стоит сильнейший из камней Обуздания — тот самый, что держит на замке темницу принцессы земли." }, { 14.36, "Круг охраняют элементали земли, а между кругами нагорья бродит огромный каменный великан, один из её тюремщиков." }, { 23.77, "Именно через осколок этого камня заточённая принцесса научилась говорить с путниками, что подходят к кругу." } } } },
    ["70238d1a"] = { d = 15.9, v = "narrator", c = { x = { { 0.00, "Призвав на помощь Малфуриона Ярость Бури, свою давнюю любовь, Тиранда укрепила оборону и вынудила Легион отступить." }, { 9.95, "Малфурион заставил саму природу восстать против армий Легиона и Плети." } } } },
    ["703b43d4"] = { d = 25.7, v = "human-male", c = { x = { { 0.00, "Не следует давать новых сведений Торсену." }, { 3.06, "Его нужно убить." }, { 4.36, "Он больше не принесёт пользы нашему полковнику." }, { 7.74, "Я прикончу Торсена, если будет возможность, но если вы получите это письмо, знайте, что пока у меня такой возможности не было." }, { 16.98, "В этом случае я рекомендую, чтобы следующая встреча Торсена с нашими агентами закончилась его смертью." }, { 24.46, "Слава Курцену!" }, { 25.56, "Эм." } } } },
    ["70b59b37"] = { d = 37.6, v = "human-male", c = { x = { { 0.00, "Я могу лишь гадать, как я смог выжить в ту ночь." }, { 3.25, "Я всегда был осторожен, всегда быстро уворачивался от ударов и не раздумывая спрыгивал с обрывов." }, { 9.95, "Моё прозвище, Трясунчик, досталось мне из-за этой моей черты." }, { 14.27, "Так что, возможно, лишь эта способность всегда быть настороже спасла меня..." }, { 19.53, "Или, возможно, коса, что я вытянул из-под груды щебня." }, { 23.41, "Это не могла быть сама коса, её я потерял во время моего безумного бегства." }, { 28.73, "Но если это я привёл воргенов в Сумеречный лес, то, возможно, воргены отплатили мне неслыханной любезностью." }, { 36.12, "Да будут они прокляты." } } } },
    ["71180245"] = { d = 31.2, v = "narrator", c = { x = { { 0.00, "Деревня Сен'джин — рыбацкое поселение троллей Чёрного Копья на южном побережье Дуротара." }, { 6.62, "Вол'джин основал её, когда племени пришлось бежать с островов Эха, и назвал в честь своего отца Сен'джина, вождя и знахаря, погибшего в Третью войну, когда он спасал соплеменников от мурлоков." }, { 21.17, "Здесь живут алхимики и травники, а делами деревни ведает Мастер Гадрин." }, { 26.64, "Тролли не забыли о родных островах и мечтают вернуть их себе." } } } },
    ["71288409"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Хрустальная шахта лежит близ Зул'Мамбве." }, { 3.15, "В её недрах растут поющие кристаллы — редкость, встречающаяся только в Тернистой долине." }, { 10.00, "Местные василиски питаются ими, отчего их шкура становится твёрдой как камень, а у входа стоят окаменевшие фигуры троллей и людей." }, { 20.14, "Торговая компания мечтает разработать шахту, но василиски не пускают гоблинов внутрь." } } } },
    ["7159e9df"] = { d = 9.8, v = "narrator", c = { x = { { 0.00, "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ ОРДЫ." }, { 3.62, "Высший сержант." }, { 5.29, "Старший сержант." }, { 7.06, "Сержант." }, { 7.98, "Рубака." }, { 8.82, "Разведчик." } } } },
    ["716c43bf"] = { d = 28.9, v = "narrator", c = { x = { { 0.00, "Озеро Ясноводное — самое большое озеро Тирисфаля, лежащее к северо-востоку от Брилла, между Северным побережьем и постами Алого ордена." }, { 10.95, "Его воды по-прежнему широки и спокойны, хотя берега давно отравлены чумой, а в камышах бродят псы тьмы." }, { 19.31, "Посреди озера поднимается большой остров, на котором укрылся лич Гюнтер, и его прислужники не подпускают к берегу никого." } } } },
    ["717b07da"] = { d = 30.7, g = 1, v = "human-male", c = { m = { { 0.00, "Прежде чем я продолжу, позволь мне поблагодарить тебя ещё раз за то, что ты сделал для меня и моей жены." }, { 7.30, "Ты спас ей жизнь, и за это я обязан тебе большим, чем смогу отплатить за сотни жизней." }, { 13.38, "Она – всё для меня." }, { 14.79, "Если бы она умерла... ну, я не знаю, что бы я сделал." }, { 18.57, "Вот список того, что тебе нужно собрать, если ты хочешь, чтобы я сковал тебе оружие Света." }, { 25.17, "Я записал их по порядку, от простого к сложному – надеюсь, так тебе будет проще." } }, f = { { 0.00, "Прежде чем я продолжу, позволь мне поблагодарить тебя ещё раз за то, что ты сделала для меня и моей жены." }, { 7.13, "Ты спасла ей жизнь, и за это я обязан тебе большим, чем смогу отплатить за сотни жизней." }, { 13.21, "Она – всё для меня." }, { 14.57, "Если бы она умерла... ну, я не знаю, что бы я сделал." }, { 18.23, "Вот список того, что тебе нужно собрать, если ты хочешь, чтобы я сковал тебе оружие Света." }, { 24.62, "Я записал их по порядку, от простого к сложному – надеюсь, так тебе будет проще." } } } },
    ["71c5cd6d"] = { d = 36.8, v = "human-male", c = { x = { { 0.00, "Сильноплечий --" }, { 1.04, "Однако же нужно обладать немалой наглостью, чтобы посылать чужака обсуждать дела Братства Справедливости!" }, { 8.27, "Некогда тебе удалось спасти мне жизнь, а вот теперь ты подвергаешь её серьёзной опасности." }, { 14.27, "Однако я перед тобой в долгу." }, { 16.36, "Братство Справедливости сильнее, чем ты думаешь." }, { 19.60, "Любой рудник от Западного Края до леса находится под их контролем." }, { 24.14, "Кобольды и гноллы делают за них всю грязную работу." }, { 27.63, "У них также есть созданные гоблинами металлические монстры, которые расхаживают по полям Западного Края и вселяют ужас в местных жителей." } } } },
    ["71ca503c"] = { d = 13.5, v = "narrator", c = { x = { { 0.00, "Совет приказал Эгвин вернуться в Даларан, чтобы они могли избрать нового носителя силы Хранителя." }, { 7.59, "Но Эгвин, никогда не доверявшая Совету до конца, решила сама выбрать преемника." } } } },
    ["71f9be68"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "На следующий день." }, { 1.52, "Его быстро похоронили, без обряда, в спешно выкопанной могиле на окраине кладбища." }, { 8.51, "Из-за того, что Морган убил невинных, что противоречило его убеждениям, а также из-за горя, которое он испытал, так как не смог спасти свою семью, Морган не смог уйти в мир иной и остался в этом мире в облике неупокоенного мертвеца." }, { 28.11, "Через несколько дней его могила была обнаружена пустой, тело так и не было найдено." }, { 35.25, "Существо, в которое превратился Морган, бродит" } } } },
    ["7216328c"] = { d = 18.9, v = "creature/furbolg", c = { x = { { 0.58, "Враги… со всех сторон." }, { 3.03, "По глазам вижу." }, { 4.80, "Древобрюхи – зло." }, { 6.67, "Враг." }, { 7.26, "Нужно защитить племя." }, { 9.71, "Защитить клан Зимней Спячки." }, { 12.86, "Выгнать врагов с нашей земли." } } } },
    ["7219e69d"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Святилище Дремлющего Пламени венчает одну из высочайших гор Дуротара, к северо-западу от Долины Испытаний." }, { 8.44, "К нему ведёт тайная тропа, спиралью обвивающая вершину; начинается она у реки Строптивой." }, { 15.60, "Святилище хранит одинокий Телф Джулам, наставник шаманов на пути Огня." }, { 21.25, "Жаровню на вершине зажигают углём поверженного духа огня в знак того, что шаман овладел стихией." }, { 28.91, "С вершины виден весь Дуротар, но неверный шаг здесь стоит жизни." } } } },
    ["7235fe55"] = { d = 42.7, v = "narrator", c = { x = { { 0.00, "Руины Ан'Киража лежат за Стеной Скарабея, на самом юге Силитуса." }, { 5.36, "Тысячу лет назад армии ночных эльфов и четырёх драконьих выводков дошли до ворот этой крепости киражей, но полчища силитидов оказались неисчислимы: врагов лишь заперли внутри магическим барьером, и война оставила город в руинах." }, { 24.01, "Драконы заметили, что из большого храма на юге города исходит странная сила, которой подчиняются даже киражи, но проникнуть в него так и не сумели." }, { 36.05, "Внутри стен, среди песка и обломков, до сих пор ждут своего часа тысячи воинов роя." } } } },
    ["72460b39"] = { d = 15.1, v = "narrator", c = { x = { { 0.00, "Тралл привёл орков на материк Калимдор, где они обрели новую родину с помощью своих братьев-тауренов." }, { 7.99, "Стремясь вернуть былое величие, орки назвали свой дом Дуротаром в честь убитого отца Тралла." } } } },
    ["725c1463"] = { d = 15.9, v = "dwarf-male", c = { x = { { 0.00, "Третий день." }, { 0.95, "Рычание не прекращалось всю ночь и преследует меня даже днём." }, { 5.51, "Я не могу сосредоточиться на добыче руды." }, { 8.65, "Думаю, это медведь!" }, { 10.21, "Пусть только подойдёт поближе, мне уже не терпится всадить кирку в его череп!" } } } },
    ["728165d6"] = { d = 26.7, v = "dwarf-male", c = { x = { { 0.00, "В последующие годы, после того как Штормград предал братство Каменщиков, сэр Эрлгедин разочаровался в аристократии королевства." }, { 8.79, "Он больше не хотел принадлежать к благородным домам, хотя право это унаследовал от отца." }, { 15.00, "Но не будем отвлекаться." }, { 16.70, "Моё повествование не политический трактат и не биография." }, { 20.59, "Я всего лишь делюсь опытом участия в большой охоте среди зелёных холмов Тернистой долины." } } } },
    ["728622ef"] = { d = 39.5, v = "gnome-male", c = { x = { { 0.00, "Кормок, продолжение." }, { 1.41, "Путешествуя вместе с нами, Кормок стал всё больше интересоваться некромантией." }, { 6.66, "Его жутковатой голове очень нравилось возвращать к жизни духи умерших; наибольшее удовольствие ему доставляло пробуждать духов острова Очищения и командовать ими." }, { 17.78, "После того как наша компания распалась, Кормок отправился в Некроситет, чтобы продолжить там своё \"обучение\"." }, { 25.18, "Призрачные убийцы с лёгкостью нашли эту школу и убили Кормока прямо на глазах у его нового учителя, Раса Снегошёпота." }, { 33.18, "Так вот, покои Раса Снегошёпота – ещё одно из мест с привидениями, где можно использовать жаровню." } } } },
    ["72d2a370"] = { d = 37.1, v = "dwarf-male", c = { x = { { 0.00, "Я знаю, что у меня немного оснований претендовать на благосклонность высших сил, но что-то мне подсказывает – может быть, до меня доносятся молитвы моего маленького Эдгара, – что я вернусь невредимым к тем, кого люблю." }, { 15.93, "Если же я не вернусь, никогда не забывай, моя дорогая Сара, как сильно я любил тебя, и знай, что, умирая на поле боя, с последним вздохом я прошептал твоё имя." }, { 27.73, "Прости мне мои многочисленные недостатки и всю боль, которую мне случалось тебе причинить." }, { 34.33, "Как бездумен, как глуп я зачастую бывал!" } } } },
    ["72d85907"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Озеро Хельмово Ложе — небольшое озеро на юго-востоке Дун Морога." }, { 5.12, "Оно почти всегда затянуто льдом, лишь одну прорубь держат открытой ради пресной воды." }, { 11.92, "По льду ходить безопасно, но берега кишат зверьём и отбившимися от стаи троггами." }, { 18.16, "Хуже того, к югу от озера окопались дворфы Чёрного Железа, и разведчик Нарм Фолк заплатил жизнью, подобравшись к ним слишком близко." } } } },
    ["73576714"] = { d = 32.0, v = "narrator", c = { x = { { 0.00, "Внешний Круг Обуздания стоит в центре нагорья, недалеко от Опорного пункта." }, { 6.03, "Камень здесь стерегут элементали воздуха, и вокруг круга не смолкает свист ветра и вьются маленькие смерчи." }, { 14.57, "Это один из четырёх кругов, которыми горные великаны сковали принцессу земли." }, { 20.81, "Воины, что ищут силу вихря, приносят к этому кругу тотемные палочки троллей Сухокожих, чтобы вызвать сюда Циклониана — могучего духа ветра." } } } },
    ["736c7c47"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Город-государство Кул-Тирас, основанный на большом острове к югу от Лордерона, имел процветающую экономику, основанную на рыболовстве и мореплавании." }, { 11.38, "Со временем у Кул-Тираса появился могучий флот торговых судов, плававших по всему известному миру в поисках экзотических товаров." }, { 21.31, "Но в то время как экономика Аратора процветала, наиболее мощные её элементы начали рушиться." } } } },
    ["7392bd85"] = { d = 33.6, v = "narrator", c = { x = { { 0.00, "Озеро Каменных Столбов лежит на северо-востоке Элвинна, и большой остров посредине придаёт ему форму кольца." }, { 8.56, "Своё имя озеро получило от каменного памятника на острове, воздвигнутого в честь павших в Первой войне с орками." }, { 17.26, "Когда-то сюда ходили паломники, но теперь остров заняли чародеи-отступники, на южном берегу мурлоки выстроили хижины, а на северном раскинули лагерь гноллы." }, { 29.54, "По берегам озера богаче всего в Элвинне залежи меди." } } } },
    ["73f82b66"] = { d = 24.4, v = "narrator", c = { x = { { 0.00, "Когда сомнения и отчаяние полностью овладели Саргерасом, он потерял веру не только в свою миссию, но отказался от мыслей титанов об упорядоченной вселенной." }, { 12.13, "В конечном счёте он пришёл к выводу, что сам порядок является глупостью и что хаос и порочность – единственно абсолютные понятия в этой тёмной, одинокой вселенной." } } } },
    ["74162c91"] = { d = 28.9, v = "narrator", c = { x = { { 0.00, "Хижина Кормека — одинокая лачуга посреди голой равнины в северной части Пустошей, недалеко от Кладбища кодо." }, { 8.62, "Кто такой Кормек, никто уже не помнит; ныне здесь обитает странная парочка: хозяйка хижины, о которой мало что известно, и гоблин Биббли, который приплясывает в загоне среди костей кодо, мечтая разбогатеть на них и утереть нос своему сопернику Смиду Заржавню." } } } },
    ["74227a60"] = { d = 36.3, v = "narrator", c = { x = { { 0.00, "Крепость Фенриса стоит на острове посреди озера Лордамер и не была пощажена, когда Плеть захлестнула Лордерон." }, { 8.75, "Тул Коготь Ворона, честолюбивый молодой маг из Кирин-Тора, перешёл на сторону Плети, подчинил себе местных гноллов и создал из них стаю гнилошкуров." }, { 20.85, "Он сделался хозяином крепости, а гноллы устроились у её стен." }, { 25.82, "В её дворе, у стойл, лежит в безымянной могиле тело Аларика, бывшего телохранителя Тула, которого хозяин обезглавил ради забавы." } } } },
    ["74506442"] = { d = 3.4, v = "narrator" },
    ["745153d0"] = { d = 36.6, v = "narrator", c = { x = { { 0.00, "Озеро Кел'Терил — небольшое замёрзшее озеро в сердце Зимних Ключей." }, { 5.37, "Когда-то здесь стоял город высокорождённых; Великий Раскол обратил его в озеро, которое затем сковало льдом, и теперь из-подо льда торчат лишь верхушки колонн, а большая часть города покоится на дне." }, { 21.04, "Над льдом бродят измученные призраки высокорождённых — они до сих пор ищут осколки реликвии, из-за которой прокляты и навеки прикованы к Кел'Терилу." }, { 32.64, "Это самое большое озеро долины, и самое печальное." } } } },
    ["74a33b58"] = { d = 33.3, v = "human-male", c = { x = { { 0.00, "Чёрный дракон прошёл через полное преображение, после чего Нелтариона уже не существовало." }, { 7.02, "Он стал Смертокрылом – злобным и яростным созданием." }, { 11.03, "Он больше не был Землестражем в глазах Высших эльфов, теперь, вместо имени, данному ему титанами, его стали называть Аспектом Смерти и Заккасом." }, { 22.47, "Смертокрыл – воплощение зла и хаоса, вечно алчущее разрушения." }, { 27.32, "Возможно, он – первое зло Азерота, что появилось после изгнания Древних Богов." } } } },
    ["74c655b1"] = { d = 29.3, v = "nightelf-female", c = { x = { { 0.00, "И понимали меня." }, { 1.21, "Передав часть своей силы Косе, я ослабила барьеры мироздания настолько, что смогла привести воргенов в наш мир." }, { 9.04, "С первой попытки мне удалось призвать тридцатерых." }, { 12.61, "Они последовали в сражение за мной, и с их грубой силой в моём распоряжении мы вступили в бой с демонами Осквернённого леса." }, { 21.14, "Элуна исполнила мои желания." }, { 23.25, "Лес будет очищен." }, { 24.52, "Да пребудет со мной благословение Элуны, пока я не сделаю, что должно." } } } },
    ["752c93ed"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Застава Ганстена — крошечный лагерь дворфа у самых ворот Ульдума, к югу от Руин Южной Луны." }, { 7.30, "Геолог Ганстен из Лиги исследователей поставил здесь палатку и в одиночестве ведёт дозор за запертыми вратами города титанов, записывая всё, что удаётся разглядеть на древних камнях." } } } },
    ["752fb4f1"] = { d = 22.0, v = "narrator", c = { x = { { 0.00, "Взморье Мёртвого Глаза — пустынный участок восточного побережья Дуротара, к востоку от Сухой лощины." }, { 7.98, "Берег назван в честь Килрогга Мёртвого Глаза, вождя клана Кровавой Глазницы и героя старой Орды." }, { 15.75, "Путников здесь почти не бывает, зато среди дюн бродят ящеры, скорпиды и кабаны." } } } },
    ["7536a437"] = { d = 23.9, v = "narrator", c = { x = { { 0.00, "Ночные эльфы собрались с силами и, полные решимости, вступили в сражение с Пылающим Легионом." }, { 7.19, "Легион всегда желал завладеть Источником Вечности, который питал Древо Жизни и был сердцем королевства ночных эльфов." }, { 16.32, "Если бы Легиону удалось захватить Древо, демоны могли бы в буквальном смысле разорвать мир на части." } } } },
    ["75627e49"] = { d = 34.2, v = "tauren-male", c = { x = { { 0.00, "Прошлой ночью мне во сне явились духи." }, { 3.76, "Они сообщили мне о твоём прибытии и о том, что я должен помогать тебе." }, { 10.48, "Нам нужно о многом поговорить: о природе, духах, Матери-Земле и ночных эльфах." }, { 18.17, "Но для этого нужна личная встреча." }, { 21.57, "Мой долг – подготовить тебя к грядущим испытаниям." }, { 26.38, "Моя мудрость поможет тебе." }, { 29.09, "Я буду ждать." }, { 30.40, "-Гарт Вестник Туманов, наставник друидов" } } } },
    ["7579a858"] = { d = 20.3, v = "narrator", c = { x = { { 0.00, "Северная приливная низина — небольшая ложбина у северо-западного берега, рядом с Берегом Северного прилива." }, { 8.33, "Воргены Аругала устроили здесь грубые стоянки, где есть лишь самое необходимое для выживания." }, { 15.40, "Место глухое и безлюдное, и забредать сюда стоит с осторожностью." } } } },
    ["759b64a9"] = { d = 28.1, v = "narrator", c = { x = { { 0.00, "Главный лагерь Торговой компании стоит на берегу озера Назферити." }, { 5.24, "Гоблины валят лес, крошилки ревут среди пней, а геологи обрабатывают поющие кристаллы, свезённые из холмов у Хрустальной шахты." }, { 15.14, "Компания вытеснила отсюда прочих гоблинов, и барон Ревилгаз из Пиратской бухты видит в ней соперника." }, { 23.14, "Рядом, посреди озера, высится штаб-квартира — буровая платформа." } } } },
    ["75f62053"] = { d = 43.4, v = "narrator", c = { x = { { 0.00, "Могильник — маленькая деревня в укрытой горами долине на юго-западе Тирисфаля." }, { 6.38, "Именно здесь пробуждаются те, кого чума подняла из могил, но кто сумел вырваться из-под воли Короля-лича." }, { 14.94, "Прежде селение носило иное, человеческое имя, но Отрёкшиеся нарекли его заново." }, { 21.39, "Северную часть деревни вместе с кузницей заняли безмозглые твари Плети, и жители держат оборону у часовни, где жрец Тьмы Сарвис встречает новопробуждённых." }, { 33.72, "Не хватает всего, особенно золота: рудник на северо-западе кишит пауками, а неподалёку разбил лагерь отряд Алого ордена." } } } },
    ["75febc24"] = { d = 19.2, v = "human-male", c = { x = { { 0.00, "Воплотив наш замысел в жизнь, мы сможем перейти к следующему этапу плана." }, { 5.04, "Необходимо сплотиться вместе и закрепиться в этом регионе, после этого мы сможем начать приготовления к Третьему Походу." }, { 13.37, "Скоро владыки Легиона вознаградят нас за наши труды и снова низвергнут огонь с небес!" } } } },
    ["760507c7"] = { d = 24.3, v = "dwarf-male", c = { x = { { 0.00, "День второй." }, { 0.96, "Мой поиск продолжается, но до сих пор нет следов руды." }, { 5.02, "Интересно, не пошутил ли Каменный Убор по поводу этой руды." }, { 9.62, "Если так, то он получит хорошую затрещину от меня, когда я вернусь в Посёлок Сталежара!" }, { 16.22, "Когда я размещал свой лагерь, то услышал эхо рычания в каньонах." }, { 21.17, "Это был не волк." }, { 22.41, "Это, должно быть, медведь." } } } },
    ["762eeb31"] = { d = 28.1, v = "narrator", c = { x = { { 0.00, "Из баков с горючим (их должно быть три) к дымовой трубе." }, { 4.51, "Наконец, РЕГУЛИРУЮЩИЙ КЛАПАН можно найти на нижнем из двух больших цилиндрических баков, соединённых с дымовой трубой." }, { 13.97, "Второе: индикаторы топлива." }, { 16.23, "Отображают текущее давление в первом, втором и третьем топливном баке." }, { 21.97, "Третье: индикатор потока." }, { 24.09, "Отображает текущую скорость потока внутри системы." } } } },
    ["762f6221"] = { d = 35.9, g = 1, v = "gnome-male", c = { m = { { 0.00, "Жаровня вызывания духов: инструкция к использованию." }, { 3.74, "Где найти места с привидениями." }, { 5.99, "Вступление." }, { 6.83, "На этих страницах написано, где можно найти падших духов и призраков, участвовавших в событии, связанном с амулетом Лорда Вальтхалака." }, { 16.42, "Ты уже спас моих бывших товарищей, но, боюсь, отголоски того зла, что поработило их души, ещё не покинули эти места." }, { 24.73, "Таково могущество злобного духа Лорда Вальтхалака." }, { 28.40, "С помощью жаровни также можно вызвать Лорда Вальтхалака, но нужно соблюдать крайнюю осторожность." } }, f = { { 0.00, "Жаровня вызывания духов: инструкция к использованию." }, { 3.78, "Где найти места с привидениями." }, { 6.07, "Вступление." }, { 6.91, "На этих страницах написано, где можно найти падших духов и призраков, участвовавших в событии, связанном с амулетом Лорда Вальтхалака." }, { 16.63, "Ты уже спасла моих бывших товарищей, но, боюсь, отголоски того зла, что поработило их души, ещё не покинули эти места." }, { 25.24, "Таково могущество злобного духа Лорда Вальтхалака." }, { 28.96, "С помощью жаровни также можно вызвать Лорда Вальтхалака, но нужно соблюдать крайнюю осторожность." } } } },
    ["763cd087"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Увидев падение своих детей, Мать-Земля не выдержала такого горя." }, { 5.86, "Она вырвала свои глаза и бросила их на бескрайний небосвод." }, { 11.24, "С тех пор Ан'ше и Му'ша, словно бы желая утешить друг друга, гоняются друг за другом по небу." }, { 19.51, "Поэтому день и сменяет ночь." } } } },
    ["765ef3f1"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Родниковая река берёт начало из источника, бьющего в глубине самого Тельдрассила." }, { 6.34, "Она вытекает из Родникового озера и течёт на север, пока не срывается с края великого древа огромным водопадом в море далеко внизу." }, { 16.68, "По её берегам бродят обезумевшие древесники, бросающиеся на всякого, кто подойдёт к воде." } } } },
    ["766a3e44"] = { d = 16.8, v = "narrator", c = { x = { { 0.00, "В конечном итоге Адский Крик сумел восстановить свою честь, победив вместе с Траллом Маннорота – демона, обрёкшего орков на вечную жажду крови." }, { 12.09, "Смерть Маннорота положила конец ужасному проклятию орков." } } } },
    ["76824686"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Владение Янсена — самая северная ферма Западного Края, у моста из Элвиннского леса." }, { 6.38, "Хозяев давно прогнало Братство Справедливости, и на полях теперь дежурят их механические големы да сами бандиты." }, { 14.87, "На дороге рядом стоит сломанная повозка Хмуробровых: старая кобыла Савраска ждёт, пока фермер починит колесо." }, { 23.22, "Для многих путников с востока это первое, что они видят в Западном Крае." } } } },
    ["76c936eb"] = { d = 23.9, v = "narrator", c = { x = { { 0.00, "Река Североземья рождается в горах к востоку от Штормграда, пробегает через всю долину мимо аббатства и виноградников и, миновав стену, впадает в Хрустальное озеро." }, { 12.88, "Её берега поросли высокой травой, где бродят волки и кабаны." }, { 17.70, "Для послушников аббатства это первая вода, у которой они учатся держать оружие." } } } },
    ["76edfb30"] = { d = 13.0, v = "human-male", c = { x = { { 0.00, "Ван Клиф..." }, { 0.85, "(неразборчиво)." }, { 2.05, "Вызывает МЕНЯ?" }, { 3.24, "ДА КЕМ ОН СЕБЯ ВОЗОМНИЛ?!" }, { 5.22, "Я – Клавьен Мортвейк!" }, { 6.91, "И чтобы какое-то насекомое ещё мне указывало?!" }, { 10.51, "Остальные страницы книги утеряны." } } } },
    ["771254dc"] = { d = 26.1, v = "narrator", c = { x = { { 0.00, "ВНИМАНИЕ:" }, { 0.73, "Немедленно свяжись с Траном Корманом." }, { 3.51, "Он находится на объекте Атри, известном местному населению как \"Старая Наковальня\"." }, { 9.60, "После успешного контакта с Корманом продолжай подготовку к войне за возвращение нашего Гномрегана!" }, { 16.82, "Все твои действия и усилия должны быть направлены на выполнение этих указаний." }, { 22.58, "Сделав всё, что нужно, ты получишь новое задание." } } } },
    ["7755c8be"] = { d = 19.9, v = "narrator", c = { x = { { 0.00, "Схрон — пещера в глубине лагеря Курцена, где бойцы полковника хранят оружие и снаряжение для войны." }, { 7.75, "Здесь укрываются его приближённые командиры и сам Курцен." }, { 12.11, "Вход стерегут лучшие воины лагеря, и повстанцы считают Схрон самым опасным местом на севере джунглей." } } } },
    ["778a8994"] = { d = 39.1, v = "nightelf-male", c = { x = { { 0.00, "Тут могут потребоваться дальнейшие исследования." }, { 3.37, "Не знаю, хватит ли мне сил, чтобы сражаться с духами своих мёртвых сородичей... не говоря уже о том, чтобы в одиночку отправиться в Дор'Данил и отыскать это навершие." }, { 14.99, "(Примечание: не так давно во время подготовки в Астранааре мне повстречался дворф-охотник, который провёл много времени в Ясеневом лесу, пытаясь помочь моему народу." }, { 26.56, "Он пришёл из места под названием Штормград." }, { 29.54, "Однажды вечером мы неплохо посидели за несколькими кружками эля, и его рассказ внушил мне надежду, что отыскать навершие всё же удастся..." } } } },
    ["778c0fe9"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "В качестве последней награды Саргерас пообещал Гул'дану огромную силу в обмен на его согласие повести Орду на Азерот." }, { 9.55, "Саргерас сказал волшебнику, что может сделать его богом во плоти, если тот найдёт подводную могилу, в которой Страж Эгвин тысячу лет назад укрыла останки Саргераса." } } } },
    ["77a12fc5"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Лагерь Халдарр стоит на западе Азшары, к северо-востоку от святилища Песни Теней, среди эльфийских руин." }, { 8.26, "Здесь густо обосновались сатиры Халдарр, и часовые с заставы Талрендис платят за их головы." }, { 15.32, "Всякий, кто идёт из Ясеневого леса вглубь Азшары, проходит мимо их костров, и мало кому это сходит с рук." } } } },
    ["77e2034e"] = { d = 50.3, v = "narrator", c = { x = { { 0.00, "Заоблачный Пик — столица дворфов клана Громового Молота, вырубленная в горе на северо-западе Внутренних земель." }, { 8.81, "После войны Трёх Кланов и потери Грим Батола клан осёл здесь, отказавшись от жизни под землёй: слишком памятны были подземные битвы с дворфами Чёрного Железа." }, { 21.19, "Здесь Громовые Молоты сблизились с природой и приручили могучих грифонов, а в знак этой связи высекли над входом исполинскую статую грифона." }, { 32.29, "Во Вторую войну всадники на грифонах под началом тана Курдрана громили Орду с небес, и с тех пор отсюда поднимаются в небо лучшие грифоны Азерота." }, { 43.96, "Тролли не оставляют попыток напасть на гнездовья, и дозор на Пике не смыкает глаз." } } } },
    ["77f4b6a1"] = { d = 40.2, v = "narrator", c = { x = { { 0.00, "Гряда Огненной стражи тянется по западу ущелья и нависает над Котлованом." }, { 5.91, "Здесь стоит главный лагерь дворфов Чёрного Железа в этих землях: паровые кузнецы, дозорные и геологи клана, а рядом бродят тяжёлые боевые големы и огромные лавовые пауки." }, { 19.62, "В холмах на северо-западе гряды скрыта пещера, где обосновались служители Сумеречного Молота — культисты, что приносят жертвы Рагнаросу и стерегут в своём святилище странную реликвию." }, { 34.19, "Это одно из самых опасных мест ущелья, и ходить сюда в одиночку не советуют." } } } },
    ["78190c92"] = { d = 34.0, v = "narrator", c = { x = { { 0.00, "По сути представляет собой материальное воплощение силы Повелителя вод, могущественного морского элементаля." }, { 8.56, "Как и почему подобный предмет вышел из-под власти Повелителя вод и попал в руки троллей – другой вопрос, ответ на который мне неизвестен." }, { 19.56, "Владыка Приливов." }, { 20.99, "Подобно самим приливам, Камень Приливов был непостоянен: он появлялся в мире троллей и исчезал снова, никогда не оставаясь в их руках дольше жизни одного поколения." } } } },
    ["7826e3b5"] = { d = 9.8, v = "scourge-male", c = { x = { { 0.00, "Принеси мне эти вещи, Звезду, Руку и Сердце, и я дам тебе копию Книги Йагина." }, { 8.82, "-Хранитель" } } } },
    ["78313a37"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "«Госпожа Удача» — восточный из трёх фрегатов Кровавого Паруса у Гибельного берега." }, { 6.85, "Пираты здесь пьют, спорят и точат сабли, ожидая нападения на Пиратскую бухту." }, { 13.32, "Говорят, никто не выживает после нападения Кровавого Паруса, оттого пираты и небогаты: грабить им некого дважды." } } } },
    ["7847d9ee"] = { d = 37.2, v = "narrator", c = { x = { { 0.00, "Земля задрожала, когда выкорчевали и повалили древние деревья зачарованного леса." }, { 7.41, "Рощи и лужайки, обихоженные сыновьями и дочерьми Кенария, и каменные башни детей звёзд обрушились на землю." }, { 17.09, "Там была наша королева, яркая даже в отчаянии, в хаосе сражения." }, { 23.04, "Зачарованное небо меняло цвет с каждым новым всплеском магии, со взрывами, которые угрожали разорвать мир на части." }, { 33.45, "Брат сражался с братом." }, { 35.57, "Избранные сражались" } } } },
    ["786c5e65"] = { d = 41.1, v = "narrator", c = { x = { { 0.00, "Деревня Зимней Спячки — большое поселение фурболгов на востоке Зимних Ключей, к северо-востоку от Круговзора." }, { 8.59, "Племя Зимней Спячки некогда дружило с Древобрюхами, но по странным велениям своего верховного вождя стало нападать на всех, кого встречает; сам вождь укрылся в пещере на вершине деревни." }, { 23.09, "Фурболги пьют «огненную воду» — зелёное зелье, от которого они становятся крупнее и злее, а гонцы носят её сюда из лагеря Мёртвого Леса." }, { 33.73, "Древобрюхи верят, что за порчей сородичей стоит демон, и надеются найти способ исцелить племя." } } } },
    ["7877961a"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Собрав свою армию – великий Пылающий Легион, – Саргерас пошёл на мирный Азерот войной." }, { 7.26, "Легион состоял из миллионов кровожадных демонов, слетевшихся со всех концов Вселенной, и этим демонам не терпелось начать вторжение." }, { 18.19, "Ближайшие помощники Саргераса, Архимонд Осквернитель и Маннорот Разрушитель, подготовили своих зловещих воинов к решительному удару." } } } },
    ["788b82b1"] = { d = 27.9, v = "narrator", c = { x = { { 0.00, "Забрав энергию силовых линий города, Иллидан воспользовался Оком, чтобы нанести магический удар по цитадели Ледяной Короны в далёком Нордсколе." }, { 10.99, "Этот удар сокрушил защиту Короля-лича и поставил под угрозу саму крышу мироздания." }, { 17.45, "В последний момент разрушительное заклятие Иллидана было остановлено, когда его брат Малфурион и жрица Тиранда пришли на помощь Майев." } } } },
    ["78924f91"] = { d = 28.3, v = "narrator", c = { x = { { 0.00, "Урсолан назван в честь Урсола, медвежьего полубога Калимдора, которого чтят фурболги." }, { 6.72, "Он лежит на севере Азшары, к востоку от прохода в крепость Древобрюхов, и посреди него зияет глубокая расселина." }, { 15.66, "Здесь раскинулось обширное поселение фурболгов Древобрюхов, тянущееся на юг до Медвежьего угла; чужакам, не заслужившим доверия племени, лучше держаться подальше." } } } },
    ["78963b6a"] = { d = 26.4, g = 1, v = "troll-male", c = { m = { { 0.00, "Привет тебе, брат." }, { 1.48, "Духи говорят, ты готов нам помочь." }, { 4.23, "Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня." }, { 12.04, "Ступай к Шикрик, наставнице орочьих шаманов в Долине Испытаний." }, { 17.04, "Она уже знает о тебе." }, { 18.87, "Пусть наши предки гордятся тобой." }, { 21.55, "Да согреет тебя огонь, и да будет тебе попутный ветер." }, { 25.92, "-Иши-йо" } }, f = { { 0.00, "Привет тебе, сестра." }, { 1.67, "Духи говорят, ты готова нам помочь." }, { 4.46, "Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня." }, { 12.19, "Ступай к Шикрик, наставнице орочьих шаманов в Долине Испытаний." }, { 17.14, "Она уже знает о тебе." }, { 18.95, "Пусть наши предки гордятся тобой." }, { 21.60, "Да согреет тебя огонь, и да будет тебе попутный ветер." }, { 25.92, "-Иши-йо" } } } },
    ["78972325"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Потайная бухта — укромный уголок на скалистом побережье возле Терамора, где мутная вода болота смешивается с морской." }, { 9.70, "Прибой вымыл в камне ниши и гроты, и говорят, что некоторые из них уходят под самый остров." }, { 17.24, "Сюда заглядывают разве что рыбаки да морские черепахи, а в тени скал тихо, как в подземелье." } } } },
    ["78bba869"] = { d = 25.4, v = "creature/furbolg", c = { x = { { 0.43, "Найди наконечник Грубой силы в лагере Изрубленного Щита." }, { 5.02, "Эти глупцы часто прячут их под свои лежанки возле входа во владения Чёрной Вершины." }, { 11.76, "Когда у тебя будет наконечник, иди к вождю Омокку, убей его, а потом насади на наконечник его голову." }, { 20.08, "Тогда ты будешь готов к настоящему делу." } } } },
    ["78c1163f"] = { d = 39.5, v = "narrator", c = { x = { { 0.00, "Долина Испытаний — замкнутая котловина среди красных скал на юго-западе Дуротара, куда приходят молодые орки и тролли, чтобы доказать, что достойны Орды." }, { 12.41, "Обряды посвящения просты и суровы: охота на кабанов и скорпидов, поручения наставников и, наконец, поход в пещеру на севере долины, где поселились демоны." }, { 24.74, "Здесь нет ни роскоши, ни покоя, лишь кактусы, пыль и учителя, следящие за каждым шагом новичков." }, { 32.31, "Тот, кто выдержал испытания, получает право покинуть долину и отправиться в деревню Сен'джин." } } } },
    ["78d83d30"] = { d = 26.2, v = "human-male", c = { x = { { 0.00, "Ульдаман, День четыре" }, { 1.53, "...первым ключом к разгадке, что я обнаружил в глубинах Ульдамана, стал один из наиболее свирепых из виденных мною троггов, охранявший огромный сапфир, – один из тех, держу пари, что идеально бы подошёл в ожерелье." }, { 16.50, "Я слышал, как один из дворфов Кузни Теней произнёс имя этого чудища: Гримлок." }, { 22.04, "И у этого свирепого Гримлока телохранители те ещё, я скажу..." } } } },
    ["78dc2010"] = { d = 10.9, v = "narrator", c = { x = { { 0.00, "Похоже, всё было напрасно." }, { 2.57, "Мгновения спустя жрицу поглотила толпа окруживших её мёртвых крестьян..." }, { 9.42, "Павшие восстали." } } } },
    ["78f200ab"] = { d = 35.0, v = "creature/falstad", c = { x = { { 0.00, "*Курдран Громовой Молот Знаменитый драконобоец.*" }, { 3.77, "*Укротитель грифонов Заоблачного пика.*" }, { 6.82, "*Командир подразделения воздушных всадников при экспедиции Альянса, которая отправилась на Дренор, родной мир орков.*" }, { 16.03, "*Предположительно погиб.*" }, { 17.84, "Ветер донесёт до нас клич Скайри." }, { 20.58, "Мы услышим грохот твоего молота по ту сторону гор." }, { 24.83, "Вступай в загробную жизнь без опасений, брат." }, { 28.56, "Залы наших предков ожидают тебя." }, { 31.45, "- Верховный тан Фалстад Громовой Молот" } } } },
    ["78f5874a"] = { d = 26.8, v = "narrator", c = { x = { { 0.00, "Благодаря успеху Кел'Тузада в Лордероне Король-лич завершил последние приготовления к атаке на человеческую цивилизацию." }, { 8.68, "Нер'зул поместил вызывающие чуму сгустки энергии в несколько переносных артефактов, так называемых чумных котлов, и приказал Кел'Тузаду доставить их в Лордерон, где они должны были быть спрятаны в различных селениях, находящихся под властью культистов." } } } },
    ["78fd077c"] = { d = 14.2, v = "narrator", c = { x = { { 0.00, "Ракушечный пляж — тихая полоса песка на северном побережье долины, куда прибой выносит раковины и обломки." }, { 8.65, "Здесь редко ступает нога путника, и лишь крики чаек нарушают шум волн." } } } },
    ["791568ef"] = { d = 69.4, v = "narrator" },
    ["792879ae"] = { d = 29.3, v = "narrator", c = { x = { { 0.00, "Озеро Фалатим лежит на западе Ясеневого леса, к юго-востоку от Зорамского взморья и к юго-западу от заставы Мейстры." }, { 9.22, "Когда-то ночные эльфы приходили сюда купаться и ловить рыбу, но теперь озеро кишит свирепыми мурлоками." }, { 17.46, "Здесь в последний раз видели учёного Терониса, друга Раэны Волкопас: он отправился искать предмет, способный ослабить порчу леса, и до сих пор не вернулся." } } } },
    ["79297bb8"] = { d = 33.9, v = "narrator", c = { x = { { 0.00, "Когда мир раскололся после взрыва Источника Вечности, это очень сильно задело земельников." }, { 7.64, "Ошеломлённые болью самой земли, земельники сделались непохожи на самих себя и закрылись в каменных чертогах, где некогда были созданы." }, { 18.80, "Ульдаман, Ульдум, Ульдуар… это имена древних городов титанов, где земельники впервые обрели свой облик." }, { 27.48, "Погребённые в недрах мира, земельники спокойно отдыхали почти восемь тысяч лет." } } } },
    ["7952799c"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Пещера Пыльного Ветра — небольшой грот на скалах Каньона Колючего Ветра, к северо-востоку от Колючего Холма." }, { 8.40, "Несмотря на название, гарпий здесь нет: пещеру заняли сектанты Пылающего Клинка, и старшие культисты обучают здесь новобранцев тёмным искусствам." }, { 19.44, "Совсем рядом с дорогой на Оргриммар зреет заговор, о котором в Колючем Холме догадываются, но пока не знают всего." } } } },
    ["79bf1ec9"] = { d = 31.5, v = "human-male", c = { x = { { 0.00, "Капитан, удачи тебе в путешествиях." }, { 2.50, "К несчастью, в первой нашей попытке похищения удача нам не благоволила." }, { 7.43, "Когда наша команда вышла на объект в тоннеле между Штормградом и Стальгорном, она обнаружила там лишь приманку." }, { 15.18, "Очевидно, он куда умнее, чем мы о нём думаем." }, { 18.30, "Но теперь уже задействован наш второй план." }, { 21.30, "Агенты Братства Справедливости готовятся захватить объект, как только он приблизится к Терамору." }, { 27.92, "Скоро в Штормграде узнают, как мы умеем кусаться..." }, { 31.48, "М." } } } },
    ["79c9405a"] = { d = 36.8, v = "narrator", c = { x = { { 0.00, "Инженерные дисциплины." }, { 1.74, "Несмотря на то что вопрос о том, какая раса первой в Азероте додумалась до инженерного дела, является спорным, бесспорен тот факт, что лишь две расы преуспели в ней в настоящее время: гномы и гоблины." }, { 16.95, "Их преданность инженерному делу не только вдохновила их на фантастические изобретения в смутный магический Век Изобретений, но и, как результат, породила интенсивную конкуренцию между расами." }, { 31.39, "Нигде она столь очевидно не проявлялась, как на путях развития их науки." } } } },
    ["79d14887"] = { d = 33.5, v = "narrator", c = { x = { { 0.00, "Крепость Оперённой Луны — твердыня ночных эльфов на острове Сардор у западного берега Фераласа." }, { 6.94, "Здесь командует генерал Шандриса Оперённая Луна, предводительница Часовых, а вокруг лунного колодца стоят дома торговцев и гиппогрифьи насесты." }, { 17.29, "Крепость — единственный оплот Альянса в этих джунглях: отсюда Часовые следят за нагами клана Гребня Ненависти, что расползлись по островам под началом лорда Шалзару." }, { 29.34, "С материка сюда ходит лодка от пристани на Забытом берегу." } } } },
    ["79d56bd3"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Новая Орда, возглавляемая такими опытными вождями, как Гром Адский Крик и Килрогг Мёртвый Глаз (из клана Кровавой Глазницы), застала врасплох войска Альянса и напала на близлежащие деревни." }, { 14.87, "Под командованием Нер'зула орки быстро добыли нужные артефакты и вернулись обратно на Дренор." } } } },
    ["79da315e"] = { d = 25.9, v = "human-female", c = { x = { { 0.00, "В действительности она часто реагировала с точностью до наоборот!" }, { 4.58, "Как будто подвеска умышленно искажала результаты моих экспериментов." }, { 9.41, "Как будто камень был думающим, живым существом." }, { 12.78, "Разгневанная, но не сдавшаяся, я прекратила выдвигать предположения о том, что подвеска была инертным куском скалы, и начала считать, что она была живым существом." }, { 24.22, "Но снова я была не права." } } } },
    ["79fdb05e"] = { d = 28.0, v = "narrator", c = { x = { { 0.00, "Поле Маннорок — выжженная земля среди руин ночных эльфов на юге Пустошей, названная в честь владыки преисподней Маннорота." }, { 9.91, "Культисты Пылающего Клинка открыли здесь порталы, и теперь по полю бродят инферналы, гончие Скверны и стражи ужаса." }, { 19.25, "Воздух густ от демонической магии, и путник чувствует, как на плечи ложится тяжесть, едва ступив на эту землю." } } } },
    ["7a1ea5a8"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Гарнизон у Западного ручья – казармы стражи Штормграда на западной окраине Элвинна, у границы с Западным Краем." }, { 8.07, "Пока армия далеко, здесь едва хватает людей, чтобы охранять дороги от гноллов и грабителей, которых становится всё больше." }, { 16.99, "Заместитель судьи Рейнер просил у Златоземья подкрепление, и вместо солдат маршал Дугхан шлёт сюда добровольцев." }, { 25.13, "На стенах гарнизона висят объявления о награде за голову Дробителя, вожака гноллов стаи Речной Лапы, что обитают в лесу к югу от башни." } } } },
    ["7a37624d"] = { d = 34.8, v = "troll-male", c = { x = { { 0.00, "Поздравляю с пробуждением!" }, { 2.13, "Все хитрости и премудрости тайной магии будут твоими – если, конечно, у тебя хватит силёнок их удержать." }, { 10.67, "Как будешь готов, ступай к Май'ах." }, { 13.54, "Она расскажет тебе про такую магию и заклинания, с которыми тебе любой враг не страшен!" }, { 20.75, "Май'ах живёт возле Логова, в Долине Испытаний." }, { 24.58, "Ты придёшь, её найдёшь, а она тебе силу даст." }, { 28.18, "А потом ты покажешь всем остальным, что ты крутишь магией как хочешь, а не наоборот." } } } },
    ["7a3ed96d"] = { d = 30.5, v = "narrator", c = { x = { { 0.00, "Синяя топь — мокрая низина к востоку от Гиблотопи, где болото только начинает набирать силу." }, { 7.81, "По кочкам снуют пауки и ящеры, в воде дремлют кроколиски, а над камышами кружат птицы." }, { 15.17, "Здесь же, среди тростника, скрываются разведчики Терамора, следящие за деревней огров, а дальше к востоку раскинулось стойбище тауренов Зловещего Тотема, чьи замыслы никому не известны." } } } },
    ["7a3f248b"] = { d = 23.8, v = "narrator", c = { x = { { 0.00, "Пыльные равнины — самый южный уголок Западного Края, сухая земля на границе с Сумеречным лесом." }, { 7.92, "Здесь стоят лагеря гноллов, а по равнине рыщут койоты и падальщики." }, { 13.42, "На восточном краю возвышается старая башня мага, и с ней тоже не всё ладно: её обжили люди, связанные с Братством Справедливости." } } } },
    ["7a637e26"] = { d = 14.6, v = "troll-male", c = { x = { { 0.00, "Товар у меня." }, { 1.12, "Я буду прятаться к западу от крепости Тирагард, под деревом с тёмными листьями." }, { 7.18, "Если отправите за добром кого-то из своих агентов, пусть убедится, что его никто не видел!" }, { 14.22, "Ба'со" } } } },
    ["7a6b78e3"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Крипта — старинный склеп на юго-западе края, южнее Дарроушира." }, { 4.97, "В нём укрылась шайка троллей-нежити, чей предводитель, изгнанный своим племенем, устраивает набеги на часовню Последней Надежды и похищает тела из её погребальной ямы." }, { 18.10, "Здесь же стоит могильный камень с именем Тириона Фордринга, хотя паладин, как говорят, вовсе не умер." }, { 26.12, "А где-то за склепом, по слухам, зарыт сундук тролля по имени Хамейя." } } } },
    ["7a71f2ca"] = { d = 30.4, v = "human-male", c = { x = { { 0.00, "Ульдаман, День пятый" }, { 1.36, "...тот трогг, затем взял топаз с тела его убитого \"брата\", побежал в боковую пещеру у внешней стороны зала..." }, { 8.58, "...быстро положил топаз в большую, заметную вазу у задней стены комнаты..." }, { 13.55, "...надо же, дворфы!" }, { 14.86, "К тому же трое." }, { 15.92, "Они забаррикадировались от троггов." }, { 18.23, "Звать их на помощь было бы равносильно самоубийству, поскольку на меня бы тут же напали злобные трогги, а в моём ослабленном состоянии..." }, { 27.05, "Как только я узнаю, где третий камень, мне следует..." } } } },
    ["7aa01438"] = { d = 38.2, v = "narrator", c = { x = { { 0.00, "Застава Отравленной Крови — крохотный лагерь Орды на утёсах западной окраины леса, над обрывом к Тёмным берегам." }, { 8.59, "Судя по постройкам и стражникам, основали её таурены, но заправляет здесь Отрёкшаяся Винна Хеззард, которую осквернённая вода лунных колодцев интересует больше, чем исцеление леса." }, { 22.24, "Рядом Трулл Баловень Судьбы нанимает охотников на совухов, а укротитель ветрокрылов Браккар держит единственный перелёт Орды в этих краях." }, { 32.85, "К заставе ведёт тёмная тропа вдоль южного берега реки Отравленной Крови." } } } },
    ["7aa592c3"] = { d = 26.8, v = "narrator", c = { x = { { 0.00, "Сумеречная застава — стан Сумеречного Молота на северо-западе Силитуса, далеко к западу от Крепости Кенария." }, { 8.08, "Здесь, как и в других лагерях культа, установлен Ветровой Камень, у которого послушники в тёмных одеждах проводят ритуалы призыва." }, { 17.72, "Хранители заставы следят, чтобы никто не обращался к Совету Бездны без разрешения, и наказывают нарушителей без промедления." } } } },
    ["7aa9cba8"] = { d = 43.4, v = "narrator", c = { x = { { 0.00, "Часовня Последней Надежды на восточных склонах края — одно из древнейших святилищ Церкви Света." }, { 8.01, "После падения Лордерона сюда, в освящённую землю, тайно перенесли останки тысячи героев Света, чтобы Король-лич не поднял их в свою армию." }, { 19.62, "Паладины, отвергнувшие фанатизм Алого ордена, основали Серебряный Рассвет и сделали часовню своим оплотом под началом лорда Максвелла." }, { 30.86, "Здесь принимают всех — людей и эльфов, орков и Отрёкшихся, — лишь бы они готовы были сражаться с Плетью." }, { 39.40, "Это последний огонёк Света в краю, укрытом тьмой." } } } },
    ["7ab021a9"] = { d = 22.8, v = "scourge-male", c = { x = { { 0.00, "Сердце Наследия" }, { 1.38, "Старые тексты говорят, что тот, кто обладает Сердцем Наследия, не боится могилы." }, { 8.19, "Возможно, это правда, ведь владелец сердца, Тролль Могх, известен как Могх Неумирающий." }, { 15.46, "Знахарь клана Дробителей Черепов, Могх, обитает в Тернистой долине на Руинах Зул'Мамбве." } } } },
    ["7af2f8fb"] = { d = 22.6, v = "human-male", c = { x = { { 0.00, "ОТЧЁТ: Волки." }, { 0.94, "Атаки животных на Североземье, о которых я сообщал ранее, увеличились." }, { 5.82, "Эоган считает, что появление волков в долине связано с тем, что их спугнули из Сумеречного леса." }, { 12.46, "Несмотря на то что волки редко охотятся на людей, растущее их число привело к нескольким стычкам с фермерами." }, { 20.03, "И пропало очень много домашнего скота." } } } },
    ["7b1f0824"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Долина Североземья со всех сторон укрыта горами, и единственный путь сюда ведёт через южный проход за каменной стеной." }, { 9.17, "Под сенью аббатства начинают свой путь новобранцы короны, а за оборону долины отвечает маршал Макбрайд." }, { 17.15, "В лесах появились волки, бежавшие из Сумеречного леса, рудник на западе заняли кобольды, а на виноградниках хозяйничают бандиты Братства Справедливости." }, { 28.91, "Река, бегущая через долину, уходит за стену и впадает в Хрустальное озеро." } } } },
    ["7b438fff"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Меч дал Артасу невиданную силу, но забрал его душу, превратив принца в одного из самых могущественных рыцарей смерти, подданных Короля-лича." }, { 11.19, "Потеряв душу и рассудок, Артас возглавил Плеть и повёл армию против своего собственного королевства." }, { 19.10, "Артас убил своего отца, короля Теренаса, и бросил поверженное королевство Лордерон к ногам Короля-лича." } } } },
    ["7b56a519"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Помост Скарабея стоит к северо-западу от врат, прямо перед Стеной Скарабея." }, { 5.92, "На этом возвышении висит Гонг Скарабея — древний инструмент, оставленный здесь после Войны Зыбучих песков." }, { 14.13, "По пророчеству, врата Ан'Киража откроются лишь тогда, когда носитель воссозданного Скипетра Зыбучих Песков ударит в гонг." }, { 23.46, "Возле помоста несут вахту бронзовые драконы, и именно здесь, когда придёт время, должны сойтись войска Орды и Альянса для войны в Ан'Кираже." } } } },
    ["7b5e3c55"] = { d = 43.0, v = "narrator", c = { x = { { 0.00, "Озеро Лордамер — одно из величайших озёр Восточных королевств." }, { 5.31, "На его берегах и в окрестных горах выросли три человеческих державы: Лордерон, Даларан и Альтерак." }, { 13.28, "Посреди вод лежат Рассветные острова, а над ними чернеет крепость Фенрис, где обосновались слуги Плети." }, { 21.70, "Аптекари Подгорода поминают древнюю чуму, что когда-то погубила в озере всё живое; ныне на островах водятся озёрные ползуны, а у разрушенной пристани копошатся мурлоки." }, { 35.30, "Для Отрёкшихся озеро — водная граница между Серебряным бором и беспокойными Альтеракскими горами." } } } },
    ["7b9db859"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Троллей удаляться от своих исконных владений, или же об их неумении разработать технологии, необходимые для такого путешествия?" }, { 9.38, "Ответ на этот вопрос потребует дальнейших исследований, выходящих за рамки моей работы." }, { 15.95, "Однако же вряд ли тролли могли игнорировать столь крупный объект." }, { 20.78, "И новые находки в обширных тролльских развалинах в Тернистой долине демонстрируют ранее не известный аспект их взаимоотношений с морем." }, { 30.76, "Камень Приливов." }, { 32.04, "Недавние открытия, произведённые при обследовании" } } } },
    ["7bff7cb7"] = { d = 29.3, v = "human-male", c = { x = { { 0.00, "Ваша честь--" }, { 0.89, "Все жители Западного Края скорбят вместе с вами, но здесь, в Западном Крае, идёт своя война." }, { 7.42, "Крестьяне покидают район из-за воров и механических големов." }, { 11.73, "Штормград отозвал войска, лишив нас всякой защиты." }, { 15.35, "Я организовал местное ополчение на случай, если Штормград не предпримет попыток нас спасти." }, { 21.75, "Направить людей в Красногорье – всё равно что подписать приговор Западному Краю." }, { 27.46, "Сожалею," }, { 28.09, "Гриан Сильноплечий" } } } },
    ["7c0adcc6"] = { d = 10.2, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.81, "Часть вторая." }, { 4.22, "Рыцарь-защитник." }, { 6.00, "Рыцарь-капитан." }, { 7.69, "Рыцарь-лейтенант." }, { 9.57, "Рыцарь." } } } },
    ["7c4f0724"] = { d = 14.2, v = "human-male", c = { x = { { 0.00, "ОТЧЁТ: ОРКИ КЛАНА ЧЁРНОЙ ГОРЫ" }, { 2.17, "Банды орков клана Чёрной горы появились в долине." }, { 5.85, "Похоже, за этой атакой последует что-то ещё более серьёзное." }, { 10.25, "Необходимо известить мирового судью Соломона в Приозёрье." } } } },
    ["7c65b3ab"] = { d = 25.6, g = 1, v = "skyborne-male", c = { m = { { 0.00, "Приветствую!" }, { 1.02, "Ты показал себя как отличный охотник, и мне бы хотелось, чтобы тебя должным образом обучили." }, { 8.51, "В Тендалской роще дикой природе не дают особо разгуляться следопыты, но за её границами... всё несколько иначе." }, { 17.46, "Разыщи меня в центре деревни как можно скорее." }, { 21.32, "Природа зовёт." }, { 22.48, "Тай'ри Дальний Взор, наставник охотников" } }, f = { { 0.00, "Приветствую!" }, { 1.00, "Ты показала себя как отличная охотница, и мне бы хотелось, чтобы тебя должным образом обучили." }, { 8.53, "В Тендалской роще дикой природе не дают особо разгуляться следопыты, но за её границами... всё несколько иначе." }, { 17.34, "Разыщи меня в центре деревни как можно скорее." }, { 21.14, "Природа зовёт." }, { 22.29, "Тай'ри Дальний Взор, наставник охотников" } } } },
    ["7c71356e"] = { d = 35.5, v = "narrator", c = { x = { { 0.00, "Оплот Треснувшего Копыта — пещера в глубине утёса, самая охраняемая часть крепости племени Галак." }, { 7.80, "Кентавры хранят здесь Раздвоенное Копыто — реликвию, уцелевшую ещё со времён сотворения их народа, — и стерегут её священным пламенем, что горит в древней жаровне и не гаснет." }, { 21.59, "Говорят, лишь вода из лунного колодца ночных эльфов способна на краткий миг утишить этот огонь, и шаманы Громового Утёса очень хотели бы разгадать тайну того, что он охраняет." } } } },
    ["7c820fc9"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Мировой судья Резерфорд Бернсайд" }, { 2.98, "Все задолженности выплачены." }, { 5.47, "Кузнец Эйвери Веррингтан" }, { 7.73, "Все задолженности выплачены." }, { 10.22, "Клерк Гораций Белоконь" }, { 12.24, "Все задолженности выплачены." }, { 14.73, "Советник Гиллис" }, { 16.18, "Все задолженности выплачены." }, { 18.68, "Советник Крюкс" }, { 19.97, "Все задолженности выплачены." }, { 22.46, "Фермер Гетц" }, { 23.51, "Все задолженности выплачены." }, { 26.01, "Фермер Рей" }, { 26.97, "Крупный долг." }, { 28.18, "Выплата долга сельскохозяйственной продукцией обещана в урожай." }, { 33.81, "Фермер Лаийон" }, { 35.10, "Крупный долг." }, { 36.31, "Выселен с земли." } } } },
    ["7c8c76bd"] = { d = 25.8, v = "human-male", c = { x = { { 0.00, "Потеря крепости Каменной Стражи стала для нас сильным ударом." }, { 4.62, "Я уже сообщал ранее о союзе между орками Чёрной Горы и колдуном Моргантом." }, { 10.24, "Эти орки сражаются с наводящим ужас неистовством, и, похоже, здесь не обошлось без чёрной магии Морганта." }, { 18.00, "Храбрейшие из воинов его Величества отдали свои жизни при обороне крепости, но поражение было неминуемо." } } } },
    ["7c8f9623"] = { d = 9.7, v = "narrator", c = { x = { { 0.00, "Феллари Быстрая Стрела" }, { 2.01, "Капитан следопытов Алого ордена" }, { 4.80, "Жительница Кель'Таласа" }, { 6.74, "Пропала без вести в Серебряном бору" } } } },
    ["7cc8cae7"] = { d = 76.4, v = "narrator", c = { x = { { 0.00, "Оргриммар — столица орков и всей Орды, город, выстроенный среди рыжих скал на севере Дуротара." }, { 7.74, "После битвы за гору Хиджал вождь Тралл привёл свой народ в эти суровые земли и назвал их Дуротаром в честь отца, а город — Оргриммаром, в память о своём наставнике Оргриме Молоте Рока." }, { 22.77, "Таурены Мулгора и тролли Чёрного Копья помогли оркам возвести новую столицу, и с тех пор здесь живут бок-о-бок все народы Орды." }, { 33.26, "В долине Силы, у самых ворот, кипит торговля и стоит крепость Громмаш, где Тралл держит совет." }, { 41.14, "В долине Мудрости обитают таурены, в долине Духов — тролли, а в долине Чести звенят клинки воинов." }, { 49.40, "По Волоку, узкому ущелью посреди города, тянутся лавки, а под ним лежит Расселина Теней, где чернокнижники и разбойники ведут свои дела в темноте." }, { 61.53, "Ещё ниже уходит Огненная Пропасть, куда спускаются лишь самые отчаянные." }, { 67.55, "Оргриммар — город воинов, и каждый камень его стен помнит, что Орда добыла это место своим трудом и кровью." } } } },
    ["7ccc9812"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Сердце Наследия" }, { 1.34, "Могх Неумирающий – троллий знахарь из Тернистой долины." }, { 5.88, "И он обладает сердцем Наследия, о котором говорят, что оно отвращает смерть от тех, кто открывает его секреты." }, { 14.89, "Ты найдёшь Могха на Руинах Зул'Мамбве." }, { 18.01, "Одержи над ним победу, если сможешь, и принеси мне Сердце Наследия." } } } },
    ["7cd7f4b0"] = { d = 26.4, v = "human-male", c = { x = { { 0.00, "*Верховный маг Кадгар из Кирин-Тора*" }, { 3.04, "." }, { 3.17, "Бывший ученик Медива." }, { 4.84, "Верховный главнокомандующий экспедиции Альянса, которая отправилась в Дренор, родной мир орков." }, { 11.83, "Предположительно погиб." }, { 13.56, "Никто и никогда так самоотверженно не погружался в тёмные глубины магии и войны." }, { 19.42, "Мы желаем тебе добра, смелый странник." }, { 22.35, "Где бы ты ни был." }, { 23.55, "- Антонидас, верховный маг Даларана" } } } },
    ["7cd9e135"] = { d = 33.8, v = "human-male", c = { x = { { 0.00, "Я никогда не знал, как зовут жену Свена, поскольку её всегда звали \"дорогая\", \"любовь моя\" или \"мамочка\"." }, { 7.78, "Но я хотел бы знать." }, { 9.24, "Я – единственный, кто знает о её подвиге в тот день, и несмотря на то, что она лишь простая жена фермера, никогда не видел я женщину или мужчину, действующих столь храбро." }, { 21.57, "Конечно же, она не знала ничего о косе, но она поняла, что всадники ищут её, и мгновенный план сформировался в её голове." }, { 30.41, "Он был прост и ясен." }, { 31.86, "Если бы он только сработал." } } } },
    ["7cf0211d"] = { d = 20.6, v = "human-male", c = { x = { { 0.00, "Хранитель передал мне найденное тобой письмо, и я хочу сообщить тебе кое-какие новости." }, { 5.94, "Последний оставшийся в живых член семьи \"Варгус\" находится в Силитусе, в Крепости Кенария." }, { 11.94, "Зовут его Гарон Хатчинс." }, { 13.68, "Когда в следующий раз будешь в пустыне, навести его." }, { 17.22, "Ему может быть интересно то, что нам удалось узнать." } } } },
    ["7d0d62b4"] = { d = 36.0, g = 1, v = "dwarf-male" },
    ["7d4f0b4d"] = { d = 36.4, v = "narrator", c = { x = { { 0.00, "Кальдорай или ночные эльфы, как их стали называть позже, поклоняются богине Луны, Элуне, и верят, что в дневное время она спит в мерцающей глубине Колодца." }, { 12.16, "В стародавние времена жрецы и провидцы ночных эльфов изучали Колодец с неиссякаемым энтузиазмом, пытаясь раскрыть его тайны и завладеть его силой." }, { 23.62, "Численность ночных эльфов постепенно увеличивалась, и они открывали для себя бескрайние просторы Калимдора, налаживали связи с многочисленными жителями этого материка." } } } },
    ["7dc9ed49"] = { d = 38.8, v = "narrator", c = { x = { { 0.00, "Скала Молота Ужаса возвышается на северо-востоке степей, в стороне от главной дороги." }, { 6.85, "Внутри скалы вырыты запутанные пещеры и норы, а по склонам вьются тропы к самой вершине." }, { 14.07, "Здесь обосновались огры, не признающие никаких союзников, кроме собственного племени, и мечтающие изгнать из степей все прочие народы." }, { 24.74, "Их лагерь хорошо укреплён, и незваного гостя встречают задолго до того, как он увидит хоть одного огра." }, { 32.97, "Среди этих великанов немало огров-магов, чьи чары не уступают их дубинам." } } } },
    ["7dd7df9d"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Святилище Песни Теней — усыпанный руинами холм на западе Азшары, сразу за мостом из Ясеневого леса." }, { 8.01, "Здесь бродят призраки высокорождённых, что жили в этих землях до Раскола, и они стремятся погасить всякую жизнь, вторгшуюся в их владения." }, { 18.92, "Часовые с заставы Талрендис поглядывают на холм с опаской и не советуют путникам сходить с дороги." } } } },
    ["7de76d19"] = { d = 22.9, v = "narrator", c = { x = { { 0.00, "Озеро Чернолесья лежит в центре края, к северу от Чумного оврага." }, { 5.36, "Его воды загрязнены чумой, и в них ходят порчёные элементали." }, { 10.28, "Когда-то на берегу стоял городок Чернолесье, а в Анналах Дарроушира сказано, что именно в этом озере паладины утопили отрубленную голову Хоргуса Опустошителя." } } } },
    ["7e19099d"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Столкнувшись с вражескими воинами, Модгуд использовала свои силы, чтобы вселить страх в их сердца." }, { 7.86, "Тени двигались по её команде, и тёмные существа вылезали из глубин земли, нападая на Громовых Молотов в их собственных дворцах." }, { 17.96, "В конце концов Модгуд прорвалась через ворота и осадила саму крепость." }, { 23.72, "Громовые Молоты сражались отчаянно, сам Кардрос был среди воинов, желая убить королеву-колдунью." } } } },
    ["7e4a1a22"] = { d = 35.9, v = "narrator", c = { x = { { 0.00, "Деревня Погребальных Костров стоит на юге леса, у самого подножия холма с крепостью Тёмного Клыка." }, { 7.83, "Аругал наложил на её жителей проклятие: днём они выглядят обычными людьми, но с заходом солнца обращаются в воргенов Лунной Ярости." }, { 18.21, "Деревенский совет служит архимагу марионеткой, через которую он держит односельчан в повиновении." }, { 25.90, "При свете дня здесь всё ещё торгуют с путниками, а в таверне сохранился кабинет аптекаря Берарда, тоже попавшего под чары Аругала." } } } },
    ["7e50d452"] = { d = 26.0, v = "narrator", c = { x = { { 0.00, "Река Алмазная — единственная вода, пересекающая перевал." }, { 4.90, "Тёмный поток тянется по дну ущелья под мостами и обрывами, и в нём не отражается ничего, кроме серого, вечно грозового неба." }, { 15.57, "Кто назвал реку так и что она значила для тех, кто жил здесь прежде, теперь никто не помнит: земля вокруг неё давно мертва." } } } },
    ["7e5f68e4"] = { d = 29.4, v = "narrator", c = { x = { { 0.00, "Крепость Менетил возвышается над Гаванью Менетилов, и её четыре башни, словно суровые стражи, смотрят на город и бухту." }, { 9.65, "Здесь размещён гарнизон Альянса, отсюда отдают приказы о защите дорог и порта, и сюда докладывают о вылазках орков Драконьей Пасти и о делах у Дун Модра." }, { 21.98, "В залах крепости можно встретить офицеров и посыльных, а в её подвалах хранятся припасы порта." } } } },
    ["7e706464"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Орки оказались неспособны завоевать мир для Пылающего Легиона, и Кил'джеден был вынужден создать новую армию, чтобы сеять хаос в королевствах Азерота." }, { 11.38, "Эта армия не должна была пасть жертвой глупой вражды, подобно Орде." }, { 16.63, "Она должна была быть беспощадной и преданной своему повелителю." }, { 21.47, "В этот раз Кил'джеден не мог позволить себе потерпеть поражение." } } } },
    ["7e7112a0"] = { d = 32.1, v = "narrator", c = { x = { { 0.00, "Терраса Создателя — площадка, вырубленная в скалах кратера, где среди стен стоят машины титанов." }, { 7.72, "Их металл не тронут временем: устройства гудят, по назначению неясные, и с террасы видна вся чаша Ун'Горо." }, { 16.22, "Учёные полагают, что именно отсюда создатели наблюдали за своими творениями и что кратер — древняя лаборатория, где выводили жизнь." }, { 26.54, "Пилоны и кристаллы Силы, рассыпанные внизу, — лишь часть этого замысла." } } } },
    ["7e7a085e"] = { d = 18.2, v = "narrator", c = { x = { { 0.00, "Орда под предводительством вождя Молота Рока привела под свои знамёна огров из родного Дренора и лесных троллей Амани." }, { 9.09, "Продолжая своё наступление, Орда легко подавила сопротивление дворфов из королевства Каз Модан и южных областей Лордерона." } } } },
    ["7e810012"] = { d = 31.9, v = "narrator", c = { x = { { 0.00, "В самой глухой части Трясины, к востоку от хижины Табеты, лежит разбитый гоблинский дирижабль." }, { 7.66, "Он вёз груз на юг, но рухнул в болото; его команда и пилот Бизиль пропали без следа, а по кочкам разбросаны ящики с товаром." }, { 17.55, "Среди обломков ещё можно найти гоблинские взрывные механизмы, за которыми охотятся инженеры, если, конечно, их не опередят кроколиски и болотные чудища, облюбовавшие место крушения." } } } },
    ["7e861a74"] = { d = 21.2, v = "narrator", c = { x = { { 0.00, "Умница луна договорилась с великим оленем, что освободит его в обмен на его любовь." }, { 6.69, "Желание Му'ша исполнилось, и она зачала от Апа'ро ребёнка, который родился тёмной ночью." }, { 13.66, "Он получил имя Кенарий и бродил по звёздной тропе между пробуждающимся миром и небесным царством." } } } },
    ["7ed6de65"] = { d = 27.8, v = "gnome-male", c = { x = { { 0.00, "Когда ты будешь готов, нажми на взрыватель." }, { 2.89, "Я обеспечил сильный сигнал, соединив медные и серебряные провода с рядом мелтузианских антенн внутри коробки." }, { 10.07, "Это должно обеспечить тебе хороший радиус действия." }, { 13.55, "Но будь осторожен с гоблинами, шляющимися поблизости." }, { 16.96, "Они не оценят моё творение, если поймают тебя на своей территории." }, { 21.38, "Да, на случай, если это не очевидно, не находись рядом с вагончиком в момент взрыва... будет больно." } } } },
    ["7ed7a45d"] = { d = 31.7, v = "dwarf-male", c = { x = { { 0.00, "Я помню битву с армией Пылающего Легиона: враги надвигались со всех направлений, а прямо передо-мной возвышался огромный инфернал." }, { 9.31, "Толпа злобных троллей по сравнению с этим кажется безобидной, как заяц в горах Дун Морога." }, { 15.85, "К величайшей радости Барнила, мы миновали руины Ткаши без всяких приключений." }, { 21.41, "Мы продолжали двигаться на запад к Великому морю, обходя руины Зул'Кунды." }, { 26.71, "Взобравшись на высокий утёс над морем, мы увидели нашего первого ящера." } } } },
    ["7f1e4453"] = { d = 29.5, v = "human-male", c = { x = { { 0.00, "У них действует обширная подземная система." }, { 3.04, "Больше, чем тебе кажется, Сильноплечий." }, { 5.82, "От Пиратской бухты до Крепости Штормграда." }, { 8.79, "Ты храбрый паладин, но глупец, если считаешь, что можешь победить их." }, { 13.66, "Они занимаются разработкой оружия массового поражения." }, { 17.52, "В общем, Каменщики знают только, как строить масштабные сооружения." }, { 22.26, "Надеюсь, ты не подумал, что я о фермах и виноградниках?" }, { 26.06, "Я отплатил тебе за услугу." }, { 27.96, "Теперь оставь меня!" }, { 29.41, "--В" } } } },
    ["7f2d28e6"] = { d = 40.6, v = "narrator", c = { x = { { 0.00, "Пламенеющий Стяг стоит на скальном уступе в северной части степей; попасть сюда можно только по шаткому мосту." }, { 8.51, "Это крохотное нейтральное пристанище, где гоблины и горстка отчаянных путников устроили лагерь под самой Чёрной горой." }, { 17.51, "В пещере за лагерем живёт гоблин Киблер, торгующий диковинными зверушками и вечно спорящий со своим попугаем, а гоблинша Тинки изучает здешних драконов." }, { 29.11, "У костра можно встретить и Джона-Оборванца — дворфа, чей рассудок пострадал в странствиях по этим землям." }, { 37.14, "Для многих это последняя стоянка перед горой." } } } },
    ["7f3e9ef5"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Поскольку Кил'джеден не доверял Королю-личу, он послал своих Повелителей ужаса надзирать за духом и следить, чтобы тот выполнял его приказания." }, { 11.06, "Его слуги-вампиры охотно отправились в Азерот, их влекла мощь и ярость Короля-лича, а также возможность изничтожить население целой планеты." } } } },
    ["7f476417"] = { d = 21.0, v = "narrator", c = { x = { { 0.00, "Найденное в отдалённых тропических лесах Кратера Ун'Горо, это яйцо когда-то содержало в себе эмбрион девизавра." }, { 8.24, "Генетический материал этого зверя оказался бесценен для экологов Лиги Исследователей, которые теперь как никогда близки к изобретению сыворотки от лишающего сил яда девизавров." } } } },
    ["7f49c278"] = { d = 35.6, v = "gnome-male", c = { x = { { 0.00, "Мор Серое Копыто." }, { 1.34, "Друид тауренов и Первый из Павших" }, { 3.90, "Мор Серое Копыто всегда был верен Тайным клинкам." }, { 7.66, "Но случилось так, что он первым пал от рук воинов зловещего Лорда Вальтхалака." }, { 13.37, "Когда мы спасались бегством от Вальтхалака, нас преследовала армия его призраков-убийц." }, { 19.89, "Побег из Пика Чёрной горы был настоящим кошмаром." }, { 23.59, "В суматохе Мор оступился и упал (хотя я подозреваю, что его кто-то толкнул)." }, { 29.30, "Но как бы то ни было, он упал на нижний уровень крепости и выбраться оттуда уже не мог." } } } },
    ["801946e5"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Разорённое побережье тянется по северному краю залива Бурь." }, { 4.88, "Его пляжи густо населены гидрами, морскими великанами, макрурами и мурлоками, так что путь вдоль воды опасен." }, { 13.98, "Здесь же стоят храм Арккоран и башня Эльдары — последние следы эльфийской цивилизации на этом берегу." } } } },
    ["802314a5"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Хилсбрадские поля — плодородная житница на западе предгорий, кормящая Южнобережье и весь край." }, { 7.15, "На фермах растут яблони и тыквы, пасутся коровы, а в кузнице Веррингтана куют оружие для местного ополчения." }, { 15.55, "Хозяева здешних земель, такие как фермеры Рей и Гетц, привыкли держать вилы рядом с плугом: Отрёкшиеся с Мельницы Таррен раз за разом совершают налёты на северные фермы, чтобы перерезать снабжение города." }, { 31.17, "Многие крестьяне отвечают засадами, и поля давно стали передовой в битве за Хилсбрад." } } } },
    ["80534c95"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "Регистрационная книга Хилсбрада." }, { 2.66, "Мы, народ Хилсбрада, торжественно клянёмся верой и правдой служить Альянсу, ведомому великими монархами, – королём Стальгорна Магни Бронзобородом и королём Штормграда Андуином Ринном." }, { 17.39, "В этом документе содержатся результаты переписи населения для целей управления этим славным городом у подножия холмов в великих Альтеракских горах, также здесь указаны те, кто платил налоги своим королям и великому и могучему Альянсу." } } } },
    ["80758334"] = { d = 35.1, v = "narrator", c = { x = { { 0.00, "Нер'зулу, наконец, удалось открыть порталы, но он даже не предполагал, какую цену придётся за это заплатить." }, { 8.30, "Колоссальная энергия порталов начала буквально разрывать Дренор на части." }, { 13.97, "Мир орков рушился, и войска Туралиона отчаянно пытались добраться до портала, чтобы вернуться домой." }, { 21.71, "Гром Адский Крик и Килрогг Мёртвый Глаз поняли, что безумные планы Нер'зула вот-вот погубят весь их народ, и, собрав всех оставшихся орков, отправились искать спасение на Азероте." } } } },
    ["8089a029"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "С братьями отправилась юная жрица Тиранда, служительница Элуны." }, { 5.39, "И Малфурион, и Иллидан были влюблены в неё, однако сердце Тиранды принадлежало лишь Малфуриону." }, { 13.35, "Иллидан ревновал девушку к своему брату и завидовал их любви, однако его душевные страдания не шли ни в какое сравнение с муками от магической зависимости." } } } },
    ["80ca76fd"] = { d = 18.4, v = "narrator", c = { x = { { 0.00, "Зловещее море — открытые холодные воды вдали от берегов Болотины, куда редко заходят корабли из гавани." }, { 8.83, "Здесь нет ни причалов, ни маяков, лишь волны и туман, и заплывшему сюда лучше повернуть назад, пока берег ещё виден." } } } },
    ["80cf282d"] = { d = 37.5, g = 1, v = "troll-male" },
    ["80ef818c"] = { d = 26.1, v = "narrator", c = { x = { { 0.00, "С течением времени Кель'Талас сделался сияющим памятником трудам и магическому мастерству высших эльфов." }, { 8.09, "Его прекрасные дворцы были созданы в том же архитектурном стиле, что и древние чертоги Калимдора, однако они великолепно вписывались в естественный ландшафт тех мест." }, { 20.86, "Кель'Талас стал сияющим самоцветом, который так хотели создать эльфы." } } } },
    ["80fd203a"] = { d = 20.7, v = "dwarf-female", c = { x = { { 0.00, "Спустя некоторое время после этой находки мы подверглись нападению ящеров." }, { 5.90, "Батальон Длинной Косы сражался мужественно." }, { 9.35, "Но силы были не равны." }, { 11.17, "Почти все погибли." }, { 12.65, "Спаслись только трое." }, { 14.41, "Рабочий Ормер Сталеплет был самым отважным бойцом, он спас меня и геолога Велгара." } } } },
    ["8128649f"] = { d = 31.5, v = "narrator", c = { x = { { 0.00, "Пруды Видений скрыты в пещерах прямо под Вершиной Духов, и вход в них — у правого края моста, ведущего с нижнего яруса." }, { 9.89, "Здесь, среди тёплой воды и пара, обосновались Отрёкшиеся: их аптекари и заклинатели живут в Громовом Утёсе как гости Орды." }, { 19.78, "Таурены смотрят на них настороженно, но Кэрн принял союз, заключённый Траллом." }, { 26.10, "В тихой воде прудов, говорят, можно увидеть больше, чем в зеркале." } } } },
    ["814972af"] = { d = 31.9, v = "narrator", c = { x = { { 0.00, "Лагерь Ренда раскинулся на северо-западе Красногорья, у самого перевала в Пылающие степи." }, { 6.97, "Это форпост орков клана Чёрной Горы: отсюда они спускаются в долины, устраивают засады на дорогах и грабят земли к северу от озера." }, { 17.17, "Здесь стоят самые сильные орки края, а дорога через лагерь ведёт к выжженным пустошам, над которыми властвует Чёрная гора." }, { 26.55, "Из Приозёрья грифоны летают над этими горами на север, к Дозору Моргана." } } } },
    ["814a431c"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Кель, опытный маг, был обеспокоен слабостью Альянса." }, { 4.21, "Его подданные, высшие эльфы, огорчённые потерей своей родины, назвали себя эльфами крови – в память о своём погибшем народе." }, { 14.48, "Лишённые энергии Солнечного Колодца, они ценой огромных страданий сдерживали дальнейшее наступление Плети." } } } },
    ["814b2693"] = { d = 23.3, v = "narrator", c = { x = { { 0.00, "Сердце Наследия." }, { 1.40, "Могх Неумирающий – троллий знахарь из Тернистой долины." }, { 5.91, "И он обладает сердцем Наследия, о котором говорят, что оно отвращает смерть от тех, кто открывает его секреты." }, { 14.86, "Ты найдёшь Могха на Руинах Зул'Мамве." }, { 17.89, "Одержи над ним победу, если сможешь, и принеси мне Сердце Наследия." } } } },
    ["81515dee"] = { d = 27.8, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Готов спорить, что ты сначала решил, будто это настоящее письмо от короля или кого-то там ещё." }, { 6.68, "Видишь ли, я знаю толк в фальшивых письмах." }, { 9.70, "Мне надо было убедиться, что ты точно прочтёшь это послание, а как ещё этого добиться?" }, { 15.68, "Я нахожусь в Старой Наковальне, рядом с огненной ямой." }, { 19.52, "Как будешь готов, приходи, поговорим." }, { 22.17, "Было бы любопытно с тобой познакомиться." }, { 25.00, "-Сольм Харгрин, наставник разбойников" } }, f = { { 0.00, "Готов спорить, что ты сначала решила, будто это настоящее письмо от короля или кого-то там ещё." }, { 6.81, "Видишь ли, я знаю толк в фальшивых письмах." }, { 9.86, "Мне надо было убедиться, что ты точно прочтёшь это послание, а как ещё этого добиться?" }, { 15.90, "Я нахожусь в Старой Наковальне, рядом с огненной ямой." }, { 19.78, "Как будешь готова, приходи, поговорим." }, { 22.51, "Было бы любопытно с тобой познакомиться." }, { 25.38, "-Сольм Харгрин, наставник разбойников" } } } },
    ["81a4ac66"] = { d = 61.7, v = "narrator", c = { x = { { 0.00, "Западный Край когда-то был житницей королевства Штормград: на этих равнинах к западу от Элвиннского леса растили хлеб для всего юга." }, { 10.04, "Но годы войн и небрежения сделали своё дело: урожаи скудели, рудники пустели, а когда содержание гарнизонов стало слишком дорогим, Штормград отозвал и войска." }, { 22.15, "В беззащитный край пришло Братство Справедливости — бывшие каменщики Эдвина ван Клифа, восстанавливавшие столицу после Первой войны и обманутые знатью." }, { 33.63, "Они заняли брошенные фермы, а по полям бродят их механические големы, вышедшие из-под контроля." }, { 40.99, "К разбойникам примкнули гноллы, побережье кишит мурлоками." }, { 45.46, "Всё, что осталось у здешних людей, — Народное ополчение на Сторожевом холме да несколько упрямых фермеров." }, { 53.51, "А под опустевшим Луноречьем, в Мёртвых копях, ван Клиф готовит нечто, о чём в Штормграде пока лишь догадываются." } } } },
    ["81a4c1c0"] = { d = 22.0, v = "narrator", c = { x = { { 0.00, "Путешествуя по этому девственному миру, по первобытной земле, титаны встречали множество агрессивных элементалей." }, { 8.79, "Эти духи, поклонявшиеся расе невероятно злых существ, известных как Древние Боги, поклялись отбросить титанов и сохранить их мир от металлического прикосновения захватчиков." } } } },
    ["81cf58d9"] = { d = 17.0, v = "narrator", c = { x = { { 0.00, "Отец и сын неистово дрались бок-о-бок, чтобы сдержать напор насекомых в Силитусе." }, { 6.83, "Из крепости Ан'Кираж тёк, казалось, нескончаемый поток силитидов, пополняя ряды захватчиков-киражей." }, { 15.17, "Весь Силитус был осаждён." } } } },
    ["81d51080"] = { d = 27.4, v = "human-male", c = { x = { { 0.00, "*Данат Троллебой.*" }, { 1.39, "*Командир ополчения Стромгарда.*" }, { 3.89, "*Советник генерала Туралиона, боевой командир экспедиции Альянса, которая отправилась на Дренор, родной мир орков.*" }, { 13.13, "*Предположительно погиб.*" }, { 14.96, "Мы чтим твою память и твою жертву, племянник." }, { 18.37, "Со дня основания нашей славной империи путь к доблести всегда был залит кровью героев." }, { 24.78, "- Торас Троллебой, владыка Стромгарда" } } } },
    ["81d5d4f1"] = { d = 21.3, v = "human-female", c = { x = { { 0.00, "Я надеялась доказать моим коллегам, что этот камень обладает магическими свойствами, и если мы, волшебники Даларана, не желаем использовать силу кровавых камней, мы должны по крайней мере изучить их свойства, поскольку однажды наши враги могут использовать их против нас." }, { 19.13, "И так начались мои исследования." } } } },
    ["81f67d36"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "Кил'джеден Искуситель был выбран для поиска самых тёмных рас во вселенной и присоединения их к армии Саргераса." }, { 8.93, "Второй, Архимонд Осквернитель, был избран, чтобы вести огромную армию Саргераса в битву против тех, кто мог воспротивиться воле титана." } } } },
    ["8210a273"] = { d = 42.9, v = "narrator", c = { x = { { 0.00, "Оплот Теней — подземный лабиринт под руинами Джеденара, бывший друидский курган, ставший главной твердыней Совета Теней в Азероте." }, { 10.51, "По коридорам ходят чернокнижники с демонами, а путь вглубь стерегут четыре жаровни защиты, чьё пламя гасит лишь очищенная вода лунного колодца." }, { 21.88, "В глубине правит владыка теней Скверн'дан с суккубами Моорой и Салией, здесь же обитают сатир принц Ксавалис и повелитель ужаса лорд Гиблопуст." }, { 33.25, "В клетках держат пленников: сюда попали ночная эльфийка Арко'нарин и паладин Трей Светогорн, искавшие следы Совета Теней." } } } },
    ["822639f4"] = { d = 27.1, v = "gnome-male", c = { x = { { 0.00, "Это стало неплохой забавой." }, { 2.17, "Мне так понравилось рвать проклятую книгу на куски!" }, { 5.97, "Дальше уже дело пошло просто." }, { 8.34, "Одна глава отправилась в Подгород, обиталище зловонных мертвецов и место, где я пробовал самый, пожалуй, лучший чили." }, { 17.23, "Другая – в Штормград, столицу сыра." }, { 19.94, "Дневник, а ты не пробовал заедать сыром из Штормграда, чили из Подгорода?" }, { 25.44, "Эй?" }, { 25.71, "Там, никак, тревога." } } } },
    ["826516c8"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Среди всего этого хаоса появился таинственный пророк, который стал для смертных спасителем и наставником." }, { 8.81, "Этим пророком оказался не кто иной, как сам Медив, последний Страж, чудесным образом вернувшийся из Бездны, чтобы искупить все свои грехи." }, { 20.32, "Медив поведал Орде и Альянсу о смертельной опасности, которая им грозит, и убеждал их объединить свои силы." } } } },
    ["826f688a"] = { d = 31.7, v = "narrator", c = { x = { { 0.00, "Контроль над зверем:" }, { 1.56, "Ищейка Скверны станет слушаться лишь звериных криков." }, { 5.62, "Чтобы заставить вашу ищейку Скверны искать залежи азшарита, необходимо мощно на неё зарычать!" }, { 12.73, "(Нацельтесь на ищейку Скверны и издайте рычание)." }, { 16.46, "Когда ищейка Скверны обнаружит залежь, она побежит к ней, не обращая внимания на окружающих существ." }, { 24.04, "Хотя вам не нужно защищать ищейку Скверны, возможно, вы захотите быть рядом с ней, чтобы не потерять её." } } } },
    ["82739cad"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Ночные эльфы не стали уничтожать новый Источник Вечности, чтобы не вызвать новой катастрофы." }, { 7.11, "Однако Малфурион объявил, что ночные эльфы больше никогда не будут практиковать магию, после чего они под руководством Кенария стали изучать древнее искусство друидизма, которое помогло бы им исцелить истерзанную землю и вырастить новые леса у подножия горы Хиджал." } } } },
    ["8287378f"] = { d = 33.6, v = "narrator", c = { x = { { 0.00, "Золотой Путь — главная дорога Степей, что тянется с севера на юг через весь край." }, { 6.31, "Он начинается у заставы Мор'шан на границе с Ясеневым лесом, спускается к Перекрёстку, проходит мимо оазисов и Пещер Стенаний, ведёт к Лагерю Таурахо и уходит дальше, к повороту на Мулгор и Великому Подъёмнику." }, { 22.62, "По нему день и ночь идут караваны Орды, и на него же выходят из холмов свинобразы, гарпии и кентавры." }, { 30.56, "Дорога эта не так безопасна, как её имя." } } } },
    ["82a417bc"] = { d = 30.6, v = "orc-female", c = { x = { { 0.00, "Я опишу окружающие земли со слов разведчиков Каргата:" }, { 4.49, "-Бурые каменистые холмы и сухие равнины, малопригодные для жизни." }, { 10.04, "-Палящее солнце и суровые ветры." }, { 12.85, "-Озёр или ручьёв нет." }, { 14.60, "Даже мелких луж нет." }, { 16.35, "Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек." }, { 27.75, "Если вкратце – жарко, жить трудно." } } } },
    ["82bd0890"] = { d = 69.0, v = "narrator", c = { x = { { 0.00, "Перевал Мёртвого Ветра — изломанное ущелье, соединяющее Сумеречный лес на западе с Болотом Печали на востоке." }, { 9.04, "Когда-то эти горы считали частью Красногорья, но теперь здесь всё иначе: деревья стоят окаменевшие и безлистные, небо вечно грозит бурей, а по каньону воет злой, мёртвый ветер, давший перевалу имя." }, { 25.70, "Над южной частью ущелья высится Каражан — Башня из слоновой кости, где некогда жил чародей Медив." }, { 33.92, "С его смерти башня стоит запечатанной, и её проклятие расползлось по округе, отравляя землю." }, { 41.68, "Здесь не растут травы и не находят руды; из живого лишь стервятники да блуждающие огоньки, а в южных пещерах засели огры Мёртвого Ветра." }, { 52.99, "У подножия башни лежит вымершее селение, где бродят беспокойные духи; говорят, именно отсюда спускались в Сумеречный лес тёмные всадники." }, { 64.44, "Дорога через перевал одна, и сходить с неё не советуют." } } } },
    ["834544e4"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "Лунные колодцы — святыни ночных эльфов, наполненные водой, что хранит благословение Элуны." }, { 7.09, "В Ясеневом лесу их несколько: один стоит к востоку от озера Ирис, у дороги на Приют в Ночных Лесах, другой — на западном берегу реки Фалфаррен, к югу от главной дороги." }, { 20.35, "У колодца близ озера Ирис живёт дриада Шаэлдрин; она хранит память о древнях этих краёв и помогает тем, кто ищет способ снять порчу с леса." }, { 31.23, "Даже шаманы других народов приходят сюда за фиалом воды из колодца." } } } },
    ["8356b412"] = { d = 29.2, v = "gnome-male", c = { x = { { 0.00, "Дорогой дневник, наверное, я старею." }, { 2.69, "Я совершенно забыл, что говорил тебе о Нарайне и его обмане." }, { 7.14, "Как бы то ни было, я так разозлился, когда увидел вместо самого Нарайна его копию, что приказал Номеру Два умертвить глупца!" }, { 16.18, "Потом я сел в свой ветролет и начал вырывать страницы из его драгоценной, глупой, идиотской книге на драконьем." }, { 24.24, "Что за бахвальство?" }, { 25.61, "Кто сейчас читает на драконьем?" }, { 27.90, "Как я его ненавижу!" } } } },
    ["83758cbf"] = { d = 39.5, v = "narrator", c = { x = { { 0.00, "Зорамское взморье — полоса пляжей на северо-западе Ясеневого леса, у самого Сокрытого Моря." }, { 7.40, "Некогда здесь стоял эльфийский город Зорам, но Великий Раскол утопил его в волнах, и на много веков он был утрачен и почти забыт." }, { 17.82, "Теперь к затопленным руинам вернулись наги клана Зловещего Хвоста, и никто не знает, зачем; их предводительница Руузель обитает на острове у северного края взморья." }, { 30.98, "На песке лежат разбитые корабли и выброшенные морем твари, а под водой скрывается вход в Непроглядную Пучину." } } } },
    ["837b1163"] = { d = 21.7, v = "narrator", c = { x = { { 0.00, "Зун'вата — небольшие руины лесных троллей на западе Внутренних земель, недалеко от дороги к Заоблачному Пику." }, { 8.04, "Среди замшелых камней и разбитых идолов империи Амани обитают тролли племени Сухокожих." }, { 14.57, "Отсюда ближе всего до гнездовий дворфов, и Громовые Молоты давно держат это место под присмотром." } } } },
    ["8380c346"] = { d = 42.5, v = "narrator", c = { x = { { 0.00, "Деревня Сломанного Клыка — единственное поселение троллей племени Сломанного Клыка, портовая деревня на восточном берегу Внутренних земель." }, { 10.64, "После поражения старой Орды во Вторую войну это малочисленное племя не отреклось от прежних союзников, за что другие лесные тролли объявили их предателями." }, { 22.52, "Столетия скитаний закончились, когда посланцы новой Орды Тралла отыскали племя: тролли заключили с орками договор о дружбе и с их помощью построили свою первую деревню." }, { 35.49, "Порочная Ветвь и сейчас совершает набеги на берег, а рыбакам мешают морские кусачие черепахи." } } } },
    ["83b67325"] = { d = 25.4, v = "human-male", c = { x = { { 0.00, "День пятнадцать" }, { 1.06, "Наше упорство себя оправдало." }, { 3.19, "Мы первыми завершили установку Ветрового Камня." }, { 6.51, "Останься с нами другие глупцы, на это ушло бы меньше недели!" }, { 10.82, "Завтра мы приступим к ритуалам призыва самого Барона Казума." }, { 15.07, "Он потребовал, чтобы его вызвали первым, и перечить ему мы не можем, поскольку в гневе он скор на расправу." }, { 22.52, "Я надеюсь, что он будет очень нами доволен." } } } },
    ["83ba3e2e"] = { d = 12.8, v = "narrator", c = { x = { { 0.00, "Останки гигантского красного дракона были обнаружены в Болотине вскоре после Битвы за Грим Батол." }, { 7.27, "Тираннистрас, по слухам, был старшим консортом Королевы Драконов, Алекстразы." } } } },
    ["83c491e9"] = { d = 35.4, v = "human-female", c = { x = { { 0.00, "Я боюсь, что война между Стоунфилдами и Маклурами убьёт начинающийся роман между Томми Джо и Мэйбелл." }, { 7.13, "В такие времена, когда мрачные новости и слухи о войне доходят до нас, о молодости и любви должно заботиться." }, { 14.90, "Так вот, просьба: я прошу тебя использовать свои умения и создать зелье или эликсир, который бы помог этим молодым влюблённым встретиться друг с другом." }, { 25.65, "Спасибо тебе, Вильям." }, { 27.24, "И пожалуйста, когда найдёшь время оторваться от работы, заходи в гости." }, { 32.27, "У нас есть о чём вспомнить и посмеяться." }, { 35.01, "Милдред" } } } },
    ["83dec8a1"] = { d = 28.1, g = 1, v = "troll-female", c = { m = { { 0.00, "Приятно слышать, что один из братьев Джен'шан явился в долину испытать свои способности." }, { 6.97, "Джен'шан ждёт этого с нетерпением!" }, { 9.64, "Не мне тебе рассказывать, какой ты сильный и ловкий охотник." }, { 14.36, "Дело Джен'шан – сделать тебя ещё более сильным и ловким." }, { 18.87, "Найди Джен'шан в долине Испытаний." }, { 21.61, "Она научит тебя, как укрощать самых сильных зверей." }, { 25.77, "-Джен'шан, наставница охотников" } }, f = { { 0.00, "Приятно слышать, что одна из сестёр Джен'шан явилась в долину испытать свои способности." }, { 6.78, "Джен'шан ждёт этого с нетерпением!" }, { 9.41, "Не мне тебе рассказывать, какая ты сильная и ловкая охотница." }, { 14.12, "Дело Джен'шан – сделать тебя ещё более сильной и ловкой." }, { 18.55, "Найди Джен'шан в долине Испытаний." }, { 21.24, "Она научит тебя, как укрощать самых сильных зверей." }, { 25.33, "-Джен'шан, наставница охотников" } } } },
    ["83eef582"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Терраса Воинов лежит на востоке Дарнасса, у главных ворот, ведущих в леса Тельдрассила." }, { 7.12, "Здесь обучают воинов, здесь несут службу Часовые, и патрули на ночных саблезубах охраняют вход в город." }, { 15.39, "На тренировочных площадках стоят мишени и звенит оружие, а рядом работают кузнецы." }, { 22.08, "Терраса — щит столицы, и всякий, кто входит в Дарнасс, первым видит именно её." } } } },
    ["844c314b"] = { d = 38.3, v = "narrator", c = { x = { { 0.00, "Маяк на южной оконечности Бескрайнего берега предупреждает моряков об опасных прибрежных рифах." }, { 7.80, "Семья смотрителя дважды пережила нападения мурлоков, которых вёл Старый Мрачноглаз; во второй раз не уцелел никто." }, { 17.14, "Огонь, однако, не погас: за ним следит призрак капитана Грейсона — моряка, чей корабль разбился о здешние скалы в ту ночь, когда маяк не светил." }, { 28.91, "Теперь он хранит пламя ради тех, кто ещё ходит по Великому морю, и ищет помощи у путников, чтобы очистить побережье." } } } },
    ["847e8090"] = { d = 17.0, v = "narrator", c = { x = { { 0.00, "Бродит сейчас по Сумеречному лесу, терзаемый горем от потери жены, детей и ненавидящий себя за это." }, { 8.64, "Мор'Ладим, как он теперь себя называет, скитается по Сумеречному лесу и из мести убивает всё живое." } } } },
    ["84883684"] = { d = 34.4, v = "human-male", c = { x = { { 0.00, "Штормграда." }, { 0.81, "К тому времени счета всё ещё не были оплачены, а о вознаграждениях и заработных платах гильдии Каменщиков старательно умалчивалось." }, { 9.84, "В то время Эдвин ван Клиф был избранным главой гильдии Каменщиков, и он в открытую требовал возмещения за нашу работу." }, { 17.99, "В ответ Благородный дом Штормграда приказал распустить гильдию Каменщиков, что, естественно, разозлило ван Клифа." }, { 25.77, "Возглавив бунт, ван Клиф вывел Каменщиков из города." }, { 29.34, "Прежде чем я продолжу, я бы хотел рассказать о других событиях, случившихся" } } } },
    ["849f0d12"] = { d = 30.3, v = "goblin-male", c = { x = { { 0.00, "Бригадир Шумовик, к письму приложен список оборудования, который ты запросил, одобренный Управляющим Раздунком." }, { 7.32, "Он попросил меня напомнить и подчеркнуть для тебя дополнительный интерес Торговой компании в проведении операций по всему Калимдору." }, { 16.00, "Наши бурильные и шахтёрские операции в Степях оказались прибыльными и эффективными, но мы всё ещё ожидаем достаточных норм производительности от Мулгора, который в твоей юрисдикции." }, { 27.66, "Советники сознают всю сложность проведения" } } } },
    ["84b034c9"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "К востоку от озера, среди древних руин, Лига исследователей ведёт обширные раскопки под началом геолога Сталекрута." }, { 9.20, "Из-под земли здесь показались каменные стражи и своды, возведённые задолго до прихода дворфов." }, { 16.67, "Но работы почти остановились: из потревоженных глубин вышли трогги, необычайно крупные и свирепые, и выгнали рудокопов с площадки." }, { 27.02, "Учётчик Магмар Рудокол ведёт отчётность о ходе работ, а припасы из Стальгорна расходуются впустую." } } } },
    ["84b93b1f"] = { d = 24.9, v = "narrator", c = { x = { { 0.00, "Планируя нанести удар Альянсу силами своей армии и могучих красных драконов, Некросс надеялся вновь объединить Орду и продолжить завоевание Азерота." }, { 11.67, "Но его надеждам не суждено было сбыться: небольшая группа бойцов сопротивления, возглавляемая магом Ронином, смогла уничтожить Душу Демона и освободить королеву драконов." } } } },
    ["84bf1ba1"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Кил'джеден поставил беспомощный дух Нер'зула перед последним выбором между службой Легиону и вечными муками." }, { 8.36, "И вновь Нер'зул принял условия демона." }, { 11.33, "Кил'джеден заточил его душу в глыбу прочного как алмаз льда, собранного в самых дальних пределах Круговерти Пустоты." } } } },
    ["84c08e8a"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Петляющая река сбегает с восточных гор на юге Тёмных берегов и вьётся через лес к морю." }, { 7.70, "Это продолжение реки, текущей из Осквернённого леса, и вместе с водой она приносит сюда порчу." }, { 16.20, "На её берегах, у подножия гор, стоит Роща Древних, а в зарослях вдоль русла охотятся лунопарды — крупные кошки, чьи шкуры ценят друиды Аубердина." } } } },
    ["84f0507b"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Плато Красного Облака поднимается над южным Мулгором высокими обрывами, и молодые таурены делают здесь первые шаги, прежде чем спуститься в долину." }, { 11.70, "Охотничье мастерство здесь — предмет особой гордости: племя добывает мясо и перья равнинных долгоногов." }, { 19.90, "С северо-востока на плато напирают свинобразы Дыбогривы из Ежевичной лощины, и юные храбрецы учатся защищать родную землю." }, { 29.67, "Спуск с плато ведёт по тропе на север, к дороге в деревню Кровавого Копыта." } } } },
    ["8545f618"] = { d = 43.4, v = "narrator", c = { x = { { 0.00, "Обугленная долина на западе гор когда-то была цветущей рощей, а ныне от деревьев остался лишь пепел." }, { 8.42, "Торговая компания разорила её и разгневала духов: из-под земли вырвались элементали огня, а почерневшие древние стражи леса обезумели от горя." }, { 20.37, "Здесь гнездится стая гарпий Кровавой Ярости, откуда расселяются гарпии по всему Калимдору, а среди углей рыщут обожжённые василиски и химеры." }, { 32.17, "И всё же таурены Приюта и друиды Пика не теряют надежды: в плодородную землю они сажают семена Геи, чтобы круговорот жизни продолжился." } } } },
    ["85764716"] = { d = 22.2, v = "human-male", c = { x = { { 0.00, "Герцоги Бездны" }, { 1.01, "Только послушникам, имеющим медальон статуса, разрешено обращаться к Герцогам Бездны." }, { 6.63, "Медальоны статуса могут использовать лишь те, кому они были выданы изначально." }, { 11.84, "Члены Сумеречного Молота, замешанные в неправомерном общении с Герцогами бездны либо в использовании без разрешения медальонов статуса будут наказаны мной лично." } } } },
    ["857d29a2"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "На восточной окраине Красногорья возвышается башня Илгалара, обитель чародея Морганта." }, { 6.88, "Некогда он заключил союз с орками Чёрной Горы и помог им взять крепость Каменной Стражи, но вскоре обратился против бывших соратников и укрылся в этой башне." }, { 19.29, "Тайной магией он подчинил себе гноллов стаи Темношкуров, и теперь они стерегут подступы к его жилищу." }, { 27.45, "Из башни Азоры в Элвиннском лесу за Моргантом следит его соперник Теокрит, а у подножия башни стоит статуя льва." } } } },
    ["858e28eb"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Здесь река, вытекающая из Озера Безмолвия, обрывается с уступа под стенами Каменной Стражи и наполняет глубокое озерцо в укромной восточной складке гор." }, { 12.54, "Шум воды не смолкает ни днём, ни ночью, а над ним нависает захваченная орками крепость." }, { 19.63, "У воды поселилось небольшое племя мурлоков: они ловят рыбу в заводи и строят из веток и тростника грубые хижины." }, { 29.12, "Место тихое и красивое, но чужак здесь всегда под чьим-то взглядом." } } } },
    ["8595e6b9"] = { d = 71.4, v = "narrator", c = { x = { { 0.00, "Западные Чумные земли лежат в северном Лордероне, между Тирисфальскими лесами и рекой Тондрорил." }, { 7.93, "Когда-то это была житница королевства: из Андорала зерно расходилось по всем северным провинциям." }, { 15.86, "Этим и воспользовался некромант Кел'Тузад: его Культ Проклятых заразил зерно Чумой нежити, а на четырёх крупнейших фермах поставил громадные чумные котлы." }, { 28.42, "С тех пор земля укрыта серой мглой, звери здесь больны и злобны, а деревья покрыты уродливыми наростами." }, { 36.86, "В руинах Андорала правит лич Арадж Призыватель, и мертвецы стерегут котлы на полях и кладбище на Холме Печали." }, { 45.89, "На севере, в Дольном Очаге, окопался Алый орден, на юге держится горстка бойцов Серебряного Рассвета, а на западной границе стоит Бастион Отрёкшихся." }, { 58.08, "Посреди озера Дарроумир чернеет остров Каэр Дарроу, под которым укрылась школа некромантии, и лишь гробница Утера Светоносного ещё хранит в этом умирающем краю Свет." } } } },
    ["85c732af"] = { d = 30.4, v = "narrator", c = { x = { { 0.00, "Лагерь Выпивохи — стоянка на холмах к северу от Заоблачного Пика, где у костра осел дворф по прозвищу Выпивоха." }, { 8.58, "Он ищет ингредиенты для крепкого коктейля, за которыми посылает всякого проходящего мимо: от фиолетовых грибов с озера Доблести до редких ядов." }, { 19.67, "Компанию ему составляет высший эльф, охотно делящийся местным медовым напитком, и с ним, как говорят, лучше иметь дело, когда он уже выпил." } } } },
    ["85e09566"] = { d = 23.5, v = "narrator", c = { x = { { 0.00, "В сердца своих светлых детей Мать-Земля вложила любовь к охоте, ибо создания первого рассвета были злобными и жестокими." }, { 10.45, "Они прятались от Матери-Земли в тёмных и глухих уголках мира." }, { 15.76, "Шу'хало охотились на них везде, где находили, и укрощали их нрав с благословения Матери Земли." } } } },
    ["85f7a9c9"] = { d = 35.2, v = "narrator", c = { x = { { 0.00, "Теснина Сухоусов прорезает горы на востоке нагорья, к северо-востоку от Павшего Молота." }, { 6.89, "В конце ущелья открывается пещера, где поселились кобольды племени Сухоусов." }, { 12.86, "Они копают в глубине и ревниво стерегут странные светящиеся крупицы, которые находят в породе." }, { 20.31, "В самом дальнем гроте лежит кристальный осколок, из которого доносится голос той, что зовёт себя принцессой земли и просит о помощи, а кобольды, похоже, служат её тюремщикам — горным великанам." } } } },
    ["85ff04cf"] = { d = 25.1, v = "narrator", c = { x = { { 0.00, "Сад у Зеркального озера раскинулся на его южном берегу, в западной части Элвинна." }, { 6.61, "Аккуратные яблони и домик садовника выглядят мирно, но и сюда добрались бандиты Братства Справедливости: они заняли сад и хижину, и хозяев здесь давно не видно." }, { 19.54, "Рядом шумит водопад, а тропа за ним уводит в горы к Ревущему водопаду." } } } },
    ["86057e28"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Лагерь Мохаче — деревня тауренов на востоке Фераласа, раскинувшаяся над тихими водами Штормового озера." }, { 8.01, "Быстрый ручей рассекает поселение надвое, а вдоль его берегов стоят шатры торговцев и кожевников." }, { 15.60, "Отсюда Орда следит за лесом: Хадокен Быстрый Странник собирает воинов против гноллов клана Древолапов, а по приказу из Оргриммара здесь охотятся на тауренов Зловещего Тотема." }, { 29.04, "Главная же забота лагеря — огры Гордунни, чьи набеги подступают всё ближе к его частоколу." } } } },
    ["862d450c"] = { d = 25.7, v = "narrator", c = { x = { { 0.00, "Берег Морского Бродяги тянется вдоль восточного побережья Танариса от Порта Картеля до Бухты Сорванных Парусов." }, { 9.00, "По песку неспешно бродят береговые черепахи и стальноклювые крепкохваты, а в дюнах над берегом шныряют берегоброды." }, { 18.21, "В море напротив берега видны два горящих корабля, сцепившихся в бою, которому не видно конца." } } } },
    ["8632a3e7"] = { d = 14.1, v = "narrator", c = { x = { { 0.00, "Самому могучему и коварному из повелителей ужаса, Тикондрусу, это задание пришлось по душе: его завораживала смертоносная сила чумы и небывалая мощь Короля-лича." } } } },
    ["8633ca37"] = { d = 40.6, v = "narrator", c = { x = { { 0.00, "Страшные слова:" }, { 1.44, "Лиис Ладимор" }, { 2.63, "Любимая жена и мать" }, { 4.39, "Опасения Моргана воплотились в жизнь, горе и печаль охватили его, и он, рыдая, упал на колени." }, { 12.77, "Многие часы он смотрел на могилу, прося у холодного камня прощения." }, { 18.84, "И вдруг через несколько часов что-то в нём сломалось, и он впал в бешенство." }, { 25.47, "Он выхватил свой меч из ножен и, яростно крича, начал осыпать надгробия ударами." }, { 32.58, "Ничего не видя и не слыша вокруг, он продолжал крушить всё на своём пути, чем привлёк внимание" } } } },
    ["8655d007"] = { d = 32.8, v = "narrator", c = { x = { { 0.00, "Оно не смогло сковать краккенов, но разъярило их." }, { 4.23, "Много эпох смертные не причиняли им боли, а заклинание троллей оказалось болезненным!" }, { 11.52, "И вот краккены сбросили оковы заклинания Мин'лота и взревели от ярости." }, { 17.59, "Раздался громовой рокот." }, { 19.74, "Из глубин поднялись большие волны и понеслись к суше." }, { 24.35, "Волны достигли И'лалая и накрыли город тенью." }, { 28.35, "Но прежде чем уничтожить его, краккены на миг замерли." } } } },
    ["866b4ca9"] = { d = 17.4, v = "narrator", c = { x = { { 0.00, "Пещера Духов скрыта на северном краю Мглистой долины." }, { 4.57, "В ней живёт троллиный знахарь, к которому приходят больные лихорадкой джунглей: за клык гориллы он вызывает духов зверей." }, { 14.53, "Стены пещеры помнят древние обряды." } } } },
    ["868cf786"] = { d = 37.6, v = "dwarf-male", c = { x = { { 0.00, "Но знаешь, Сара, если мёртвые могут вернуться на Азерот и незримо витать вокруг тех, кого они любили, я всегда буду возле тебя, в самый светлый день и в самую тёмную ночь, в счастливейшие моменты и в мрачнейшие часы, и если ты ощутишь на своих щеках лёгкое дуновение ветерка, это будет моё дыхание, а когда ты почувствуешь, как прохладный воздух овевает твой горячий лоб, это будет мой дух." }, { 29.74, "Сара, не оплакивай меня, как мёртвого, думай, что я ушёл и жду тебя, ибо мы встретимся снова." }, { 36.78, "--Твой Салли" } } } },
    ["86dacd87"] = { d = 27.4, v = "human-male", c = { x = { { 0.00, "Палач Зуганд!" }, { 1.00, "Я считаю, что в наплыве Плети с глубин территории следует винить не слабую оборону." }, { 6.80, "Я довольно давно наблюдаю за нашими войсками в Бастионе и на восточной базе: чтобы там прорваться, потребовалась бы серьёзная армия." }, { 15.85, "Подозреваю, что сейчас некий неведомый враг в наших границах пополняет их численность." }, { 21.78, "Я продолжу идти по этому следу в надежде отыскать и устранить сам источник." }, { 27.02, "Кристоф" } } } },
    ["86e63eed"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Таверна \"Крепкое пойло\" — сердце Телсамара и самое людное место во всём Лок Модане." }, { 6.36, "Здесь можно снять комнату, отогреться у очага и попробовать местные кровяные колбаски под кружку дворфийского эля." }, { 14.98, "За столами собираются горные пехотинцы после дозора, охотники с озера и путники, идущие между Стальгорном и Гаванью Менетилов, чтобы обменяться новостями и байками." } } } },
    ["86f76499"] = { d = 32.9, v = "narrator", c = { x = { { 0.00, "Война." }, { 0.60, "Морган служил под командованием легендарного паладина Утера Светоносного, который сражался с орками и нежитью." }, { 9.67, "Оставив жену и детей, Морган отправился на войну." }, { 13.84, "Шли годы, война затягивалась." }, { 16.29, "Морган стал свидетелем ужаснейших событий, включая расформирование паладинов Серебряной Длани, гибель Утера и эпидемию чумы." }, { 26.56, "Единственной причиной, по которой он не сошёл с ума, была уверенность в том, что" } } } },
    ["86fd3705"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Годы после Великого Раскола были для троллей самыми тяжёлыми." }, { 5.24, "Их разрозненные королевства были охвачены голодом и страхом." }, { 10.32, "Тролли Гурубаши в отчаянии искали помощи у древних мистических сил." }, { 16.01, "Все тролли имели общих многочисленных богов, но на призывы Гурубаши откликнулся самый тёмный и мрачный из них." } } } },
    ["8710dfbe"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Юго-восточные предгорья Хиджала — те самые склоны, по которым войско Архимонда поднималось к Нордрассилу, и земля здесь до сих пор отравлена Скверной." }, { 11.37, "Отсюда рукой подать до Теснины Зловещего Шёпота, куда после гибели своего повелителя бежали уцелевшие демоны Легиона; из Зимних Ключей на гору ведёт именно эта дорога." }, { 24.40, "Лес в предгорьях искажён и болен, но именно здесь начинается работа по исцелению горы." }, { 30.91, "Для путника это первый привал на Хиджале и ворота ко всему остальному." } } } },
    ["8735c416"] = { d = 19.9, v = "narrator", c = { x = { { 0.00, "Это договор на владение участком земли в Западном Крае." }, { 4.41, "По договору данный участок, включая любую продукцию, полученную на нём, и все строения, находящиеся в его пределах, принадлежит лицам, указанным ниже." }, { 16.01, "Документ подписан:" }, { 17.48, "Теодор Хмуробров" }, { 18.81, "Верна Хмуробров" } } } },
    ["8748d684"] = { d = 31.4, v = "human-female", c = { x = { { 0.00, "Томми Джо -" }, { 0.83, "Моё сердце увядает с каждой минутой, проведённой вдали от тебя." }, { 5.31, "Ах, если бы только наши родственники могли забыть о своей глупой вражде и преступлениях и понять, что единственное настоящее преступление – это их взаимная ненависть!" }, { 17.10, "Ненависть убивает, и, боюсь, в это тяжёлое время она овладеет не только нашими семьями." }, { 23.37, "Если они это поймут, мы сможем быть вместе." }, { 26.57, "Надеюсь, так оно и будет, я живу мечтами об этом." }, { 30.16, "С любовью," }, { 30.93, "Мэйбелл" } } } },
    ["8790dd42"] = { d = 28.3, v = "narrator", c = { x = { { 0.00, "Туннель Холодной долины — единственный проход, связывающий долину с остальным Дун Морогом." }, { 6.96, "Через него новобранцы уходят в Каранос, но в последнее время тоннель кишит троггами, которые нападают на всякого, кто сунется внутрь." }, { 17.26, "У входа несёт дозор горный пехотинец Талос, предупреждая путников об опасности." }, { 23.38, "Иных здесь спасают только быстрые ноги, а иных — крепкий топор." } } } },
    ["879101e8"] = { d = 38.1, v = "narrator", c = { x = { { 0.00, "Деревня Сквернолапов прячется на самом севере леса, у подножия гор, недалеко от входа в Крепость Древобрюхов." }, { 8.78, "Это второе крупное поселение осквернённых фурболгов Мёртвого Леса, и здесь собрались самые сильные из них — дозорные, мстители и шаманы." }, { 19.59, "Вокруг рыщут волки-сквернолапы и падальщики, а по соседству, на Холме Нефритового Пламени, засели сатиры, которых считают виновниками безумия фурболгов." }, { 31.85, "Говорят, здесь же обитает и вождь Кровавая Утроба, окружённый шаманами и стражей." } } } },
    ["880d5d12"] = { d = 46.0, v = "narrator", c = { x = { { 0.00, "Руины Тауриссана лежат посреди степей — всё, что осталось от первой столицы дворфов Чёрного Железа." }, { 7.85, "Изгнанные из Стальгорна после Войны Трёх Молотов, они ушли на юг и построили здесь город, названный в честь чародея-тана Тауриссана." }, { 18.18, "Проигрывая войну, тан попытался призвать на подмогу стихию и вызвал из-под земли самого Рагнароса." }, { 26.03, "Город был уничтожен в одно мгновение, а уцелевшие дворфы стали рабами повелителя огня и ушли под Чёрную гору, где возвели Тенегорн." }, { 36.44, "Ныне среди обломков бродят агенты Чёрного Железа, а учёные Стальгорна ищут здесь реликвии, хранящие память о гибели города." } } } },
    ["881ba0a0"] = { d = 31.7, v = "narrator", c = { x = { { 0.00, "Золотые равнины — широкая котловина к юго-востоку от Громового Утёса, между столицей и деревней Кровавого Копыта." }, { 9.18, "Это одно из самых дорогих сердцу тауренов мест и их излюбленные охотничьи угодья." }, { 15.81, "Здесь пасутся большие стада кодо, и говорят, что в этом зелёном море трав бродит и знаменитый Арра'чея — могучий кодо, чей рог Кэрн Кровавое Копыто просит принести тех, кто прошёл обряды Матери-Земли." } } } },
    ["8838175b"] = { d = 31.9, v = "narrator", c = { x = { { 0.00, "Карьер Ржавой Кувалды — заброшенный раскоп дворфов на юго-западе Мерцающей равнины." }, { 6.54, "Лига Исследователей начала откапывать здесь древние руины, но на лагерь напал боевой отряд Орды и перебил землекопов; в пылу боя кто-то потревожил подземный улей, и из пещеры хлынули силитиды, обратив в бегство и самих нападавших." }, { 24.42, "Теперь среди брошенных палаток и лесов кишат насекомые, а в песке лежит дневник погибшего дворфа." } } } },
    ["88588119"] = { d = 30.2, v = "goblin-male", c = { x = { { 0.00, "Прочная хрустальная нога." }, { 1.78, "Хрустальные пауки из Выжженной теснины сделаны из невероятного кристаллоподобного материала." }, { 7.96, "Из их ног, в том случае если они не повреждены при убийстве их владельцев, получаются замечательные трубки, необходимые в экспериментах моих компаньонов-инженеров." }, { 18.87, "Мне понадобится некоторое их количество, чтобы провести тестирование." }, { 23.52, "У пауков есть восемь ног, так что достать их будет не проблемой для крепкого воина или опытного мага." } } } },
    ["885deee8"] = { d = 22.2, v = "named/13717", c = { x = { { 0.00, "Используй силу Амулета духов, чтобы они выдали себя, и забери у них камни!" }, { 6.43, "Затем вставь камни в Амулет Духов и верни его мне." }, { 10.74, "Когда у меня будет Амулет Соединения, я стану достаточно силён, чтобы изменить жизнь племён, и мы наконец-то сможем жить по заветам предков!" } } } },
    ["885e994b"] = { d = 23.8, v = "narrator", c = { x = { { 0.00, "Могучие драконы, бежавшие от быстро распространявшихся по миру людей, обнаружили, что они не могут противостоять могуществу тёмной магии Легиона." }, { 11.42, "Эгвин сразилась с демонами и с помощью благородных драконов победила их." }, { 17.13, "Но как только последний демон был изгнан из мира, ужасная буря разразилась на севере." } } } },
    ["889c6841"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Военные звания Альянса." }, { 2.58, "Офицеры." }, { 3.53, "Главнокомандующий" }, { 5.35, "Фельдмаршал" }, { 6.59, "Маршал" }, { 7.36, "Командор" }, { 8.31, "Лейтенант-командор" }, { 10.32, "Рыцарь-защитник" }, { 12.04, "Рыцарь-капитан" }, { 13.66, "Рыцарь-лейтенант" }, { 15.48, "Рыцарь." }, { 16.34, "Рядовые." }, { 17.29, "Старший Сержант" }, { 19.01, "Сержант" }, { 19.87, "Младший Сержант" }, { 21.59, "Капрал" }, { 22.36, "Рядовой" } } } },
    ["88b3d91a"] = { d = 74.2, v = "narrator", c = { x = { { 0.00, "Громовой Утёс — столица тауренов, поднятая на вершинах высоких столовых гор посреди зелёного Мулгора." }, { 7.87, "Много поколений таурены кочевали по равнинам, страдая от набегов кентавров, пока в дни Третьей войны вождь Кэрн Кровавое Копыто не заручился помощью Тралла и его Орды." }, { 21.06, "Отбив Мулгор у кентавров, Кэрн возвёл на ветреных утёсах прибежище, где рады тауренам любого племени." }, { 28.93, "Вершины соединены длинными мостами из дерева и канатов, а над пропастями стоят шатры, длинные дома и раскрашенные тотемы." }, { 38.51, "Наверх поднимают подъёмники из верёвок и брёвен — изобретение самих тауренов, а гости прилетают на ветрокрылах или прибывают дирижаблем из Оргриммара." }, { 50.00, "На центральной вершине в своём шатре сидит сам Кэрн, старейшины собираются на Вершине Старейшин, шаманы — на Вершине Духов, а охотники — на Вершине Охотников." }, { 62.26, "Здесь же живёт и старая Магата из племени Зловещего Тотема, чьи замыслы не всем по нраву." }, { 69.14, "Ветер гуляет между шатрами, и город живёт в мире с землёй и небом." } } } },
    ["88bcc8b2"] = { d = 32.0, v = "tauren-female", c = { x = { { 0.00, "Аптекарь Лидон, я надеюсь, что это письмо дойдёт до тебя быстро, а податель его будет в приличном состоянии." }, { 8.70, "В далёком Калимдоре случилось то, что, как я считаю, потребует твоих умений." }, { 14.67, "Буду кратка." }, { 15.75, "В Когтистых горах, недалеко от Мулгора, родины наших союзников тауренов, грядёт несчастье." }, { 22.95, "Торговая компания, управляемая гоблинами, вовсю ведёт в этих горах добычу и вырубает там леса, гневя горных духов." } } } },
    ["88cf928a"] = { d = 63.4, v = "narrator" },
    ["88d9a611"] = { d = 34.3, v = "human-male", c = { x = { { 0.00, "В то же время, к которым я хотел бы привлечь ваше внимание." }, { 3.98, "Во-первых, в то время мне предложили пост городского архитектора с условием, что я не стану присоединяться к ван Клифу." }, { 11.77, "Исходя из явственных идеологических разногласий, я принял решение остаться в Штормграде." }, { 17.62, "Во время восстания лейтенанта и самого доверенного помощника ван Клифа, Базиля Тредда, поймали и заключили в тюрьму." }, { 25.41, "В ожидании суда и следствия Тредд был практически забыт в тюрьме Штормграда." }, { 30.48, "Возвращаясь к ван Клифу: после того как он вывел оставшихся" } } } },
    ["88dcb29e"] = { d = 35.3, v = "narrator", c = { x = { { 0.00, "Хребет Чёрных Шипов — колючая долина на юге Степей, к северу от Лабиринтов Иглошкурых." }, { 7.01, "Здесь хозяйничают следопыты и мистики племени Иглогривых, а среди них скрываются трое главарей — Нак, Куз и Лок Оркобой, вышедшие из Лабиринтов, чтобы вести набеги на Орду." }, { 20.82, "На самом гребне живёт орочья шаманка-отшельница, а под её стоянкой лежит озерцо с удивительно чистой водой." }, { 29.52, "Неподалёку бродит Ганн Каменное Копьё, изгнанный с родных холмов дворфами." } } } },
    ["8930fe6d"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Крепость Каргатия стоит на восточном краю лесозаготовок Песни Войны, у самой реки Строптивой." }, { 7.24, "Это оплот командиров клана Песни Войны в Ясеневом лесу — единственная настоящая орочья крепость в лесу, укреплённая частоколом и шипастыми заграждениями." }, { 18.97, "Отсюда удобно получать подкрепления из Оргриммара, если Альянс решится на большое наступление, и здесь надсмотрщики лесозаготовок держат свой штаб." } } } },
    ["89477057"] = { d = 38.3, v = "narrator", c = { x = { { 0.00, "Было забыто." }, { 1.17, "Годами Владыка Приливов служил империи Гурубаши, заставляя служивших ему элементалей воды сражаться в бою и управляя течением воды в Тернистой долине во благо империи." }, { 15.78, "Но с годами Владыка Приливов стал более склонен к уединению." }, { 20.99, "Он всё чаще и чаще надолго удалялся от двора." }, { 24.95, "Владыка Приливов скрывал от любопытных глаз придворных свою страшную тайну." }, { 31.48, "Способности, которые дал ему Камень Приливов, сопровождало проклятие." }, { 37.47, "С ходом лет" } } } },
    ["894e2936"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Леди Кассандра Вэлор, любящая мать и жена." }, { 3.73, "О Кассандре известно немногое – лишь то, как сильно она любила свою семью." }, { 10.19, "Она вырастила отважных детей и была опорой могучему мужу, и иные даже говорили, что всё величие рода – её заслуга." }, { 20.23, "На такую лесть она всегда с достоинством возражала." }, { 24.66, "Если её не запомнят ни за что иное, пусть хотя бы знают: всё, что она делала, она делала ради своей семьи." } } } },
    ["898ba955"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Драконьи топи — самый юг Пылевых топей, край, где болото становится каменистым и где чёрные драконы водятся в таком множестве, что дали имя всей округе." }, { 12.63, "Между скал разбросаны логова; в одном из них обитает древний дракон Огнебор, а в другом, за пастью, вырезанной в камне, укрылась сама Ониксия." }, { 24.51, "Дракончики и чешуйчатые стражи чёрной стаи нападают на всякого, кто заходит слишком далеко, и даже Альянс и Орда обходят это место стороной." } } } },
    ["89aaa29f"] = { d = 22.5, v = "narrator", c = { x = { { 0.00, "Святилище Песни Теней — холм на западе Азшары, покрытый руинами." }, { 5.60, "Здесь бродят призраки высокорождённых, готовые истребить всякую живую душу, что забредёт в их владения." }, { 14.31, "Святилище носит то же имя, что Джарод и Майев Песнь Теней, но связано ли оно с ними, неведомо." } } } },
    ["89bbeb77"] = { d = 10.5, v = "narrator", c = { x = { { 0.00, "Ворфалк Железнолоб" }, { 1.67, "Ворфалк работает на складе \"Угрюмого обжоры\" и глубоко предан тёмным хранителям." }, { 8.73, "Да укрепится его дух." } } } },
    ["89c222cc"] = { d = 64.2, v = "narrator", c = { x = { { 0.00, "Фералас — густые дождевые джунгли на юго-западе Калимдора, зажатые между пустошами на севере, Тысячей Игл на востоке и кратером Ун'Горо на юге." }, { 11.41, "Под кронами исполинских деревьев скрыты руины древней державы ночных эльфов, и величайшая из них — Забытый Город, некогда столица Высокорождённых Эльдре'Талас." }, { 23.88, "Ныне большую часть леса держат в страхе огры клана Гордунни: они оскверняют землю и с каждым годом теснят соседей." }, { 33.15, "Альянс закрепился на острове Сардор, в Крепости Оперённой Луны под началом генерала Шандрисы, а Орда — в Лагере Мохаче, тауренском поселении у Штормового озера." }, { 45.77, "Между ними бродят гноллы клана Древолапов и таурены Зловещего Тотема, а западные острова кишат нагами." }, { 54.04, "На севере же, на острове посреди Нефритового озера, растёт одно из четырёх великих деревьев, чьи корни уходят в сам Изумрудный Сон." } } } },
    ["89f43bac"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "К северу от заставы Мейстры лежат руины Ордил'Арана — всё, что осталось от древнего города ночных эльфов." }, { 8.55, "Среди разбитых камней обосновались сектанты клана Тёмной Нити, служители высокорождённого Атрикуса Нарассина из башни Алталакса на Тёмных берегах, и они нападают на всякого, кто подойдёт близко." }, { 24.04, "Здесь же растёт Сердцедрево: говорят, оно поднялось на том месте, где во время Войны Древних двое влюблённых пали в битве, сделав последний вздох вместе." } } } },
    ["89fb41c1"] = { d = 26.3, g = 1, v = "troll-male", c = { m = { { 0.00, "Привет тебе, брат." }, { 1.45, "Духи говорят, ты готов нам помочь." }, { 4.14, "Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня." }, { 11.79, "Ступай к Шикрик, наставнице орочьих шаманов в долине Испытаний." }, { 16.68, "Она уже знает о тебе." }, { 18.47, "Пусть наши предки гордятся тобой." }, { 21.09, "Да согреет тебя огонь, и да будет тебе попутный ветер." }, { 25.37, "-Иши-йо" } }, f = { { 0.00, "Привет тебе, сестра." }, { 1.66, "Духи говорят, ты готова нам помочь." }, { 4.43, "Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинала учиться у меня." }, { 12.20, "Ступай к Шикрик, наставнице орочьих шаманов в долине Испытаний." }, { 17.11, "Она уже знает о тебе." }, { 18.92, "Пусть наши предки гордятся тобой." }, { 21.55, "Да согреет тебя огонь, и да будет тебе попутный ветер." }, { 25.85, "-Иши-йо" } } } },
    ["8a04660b"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "К западу от Ночной Гавани, в нескольких минутах пути, стоит Святилище Ремулоса." }, { 6.37, "Здесь обитает хранитель Ремул, сын полубога Кенария и страж Лунной поляны." }, { 12.25, "Он присматривает за друидами, погружёнными в спячку, и наставляет Круг Кенария в деле сохранения природы и равновесия." }, { 21.41, "Молодые друиды приходят к святилищу за советом и за первыми уроками, и само это место считается одной из опор Круга." } } } },
    ["8a055068"] = { d = 46.5, v = "narrator", c = { x = { { 0.00, "Изумрудное святилище стоит на юго-востоке леса, у главной дороги из Ясеневого леса." }, { 6.89, "Это лагерь Изумрудного Круга — ветви Круга Кенария, созданной, чтобы вернуть Осквернённому лесу жизнь; здесь бок-о-бок трудятся друиды ночных эльфов и тауренов." }, { 19.94, "Грета Замшелое Копыто ведёт отсюда войну с Советом Теней, Тарун Красное Перо следит за долиной Рваных Ран, а Эридана Грусть Ветра и Аратандис Серебряное Небо чуть южнее варят кенарийский бальзам для больных растений." }, { 37.61, "Перелёт отсюда открыт и Альянсу, и Орде, а неподалёку фурболг Гразл ищет союзников против осквернённых сородичей." } } } },
    ["8a7a2430"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Опорный пункт — лагерь Альянса в небольшом каньоне в самом сердце нагорья." }, { 5.70, "Когда огры и Синдикат захватили Стромгард, остатки королевской армии отступили сюда и разбили палатки среди скал." }, { 14.43, "Здесь стоят ополчение Стромгарда и Лига Аратора, готовясь к битве за свой великий город." }, { 21.16, "Из Дун Модра приходили гонцы просить подмоги, но капитану нечего было им дать: все силы нужны для возвращения столицы." }, { 30.16, "Отсюда же бойцы Лиги уходят в Низину Арати сражаться с Осквернителями." } } } },
    ["8a82c742"] = { d = 26.7, v = "narrator", c = { x = { { 0.00, "Роящаяся вершина — высокий скалистый пик посреди Силитуса, к югу от Крепости Кенария." }, { 6.68, "Своё имя он получил от бесчисленного роя мелких силитидов, что кружат над гнездом, устроенным в его склонах." }, { 15.12, "Насекомые пришли сюда из Улья Аши и превратили гору в один из своих ульев." }, { 21.10, "Гул крыльев слышен задолго до того, как вершина покажется из-за барханов." } } } },
    ["8aa54f56"] = { d = 36.1, v = "narrator", c = { x = { { 0.00, "Анклав Кенария — роща на северо-западе Дарнасса, где живут и собираются друиды города." }, { 7.20, "Высокие дубы и ясени несут на коре руны, а среди них стоят дома, выращенные из живого дерева и камня." }, { 15.74, "Отсюда верховный друид Фэндрал Олений Шлем направляет своих учеников." }, { 21.53, "В восточном дереве обучают охотников, а в западном, если знать, где искать, скрывается тихое братство разбойников." }, { 30.89, "У подножия деревьев можно научиться ездить на ночных саблезубах." } } } },
    ["8ae67989"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Со временем любопытство ночных эльфов привело к тому, что они повстречали и подружились с самыми разными могущественными существами, не последним из которых был Кенарий, могучий полубог древних лесов." }, { 15.30, "Благородному Кенарию пришлись по нраву любознательные ночные эльфы, и он потратил много времени на то, чтобы рассказать им о силах природы." }, { 25.96, "Мирные калдорай прониклись большим сочувствием к живым лесам Калимдора и наслаждались гармонией природы." } } } },
    ["8af4fea5"] = { d = 36.0, g = 1, v = "tauren-female", c = { m = { { 0.00, "Приветствую тебя, молодой герой." }, { 2.99, "Ветер нашептал мне, что ты пришёл." }, { 5.99, "Земля рассказала о твоей силе." }, { 8.82, "И теперь древние духи говорят о том, что ты готов учиться." }, { 14.08, "Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас." }, { 21.44, "Если хочешь, я научу тебя большему." }, { 24.76, "Ищи меня в Лагере Нараче на плато Красного Облака – нам есть, о чём поговорить." }, { 31.87, "-Мила Рассветная Странница, наставница шаманов" } }, f = { { 0.00, "Приветствую тебя, молодая героиня." }, { 2.97, "Ветер нашептал мне, что ты пришла." }, { 5.86, "Земля рассказала о твоей силе." }, { 8.52, "И теперь древние духи говорят о том, что ты готова учиться." }, { 13.54, "Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас." }, { 20.47, "Если хочешь, я научу тебя большему." }, { 23.58, "Ищи меня в Лагере Нараче на плато Красного Облака – нам есть, о чём поговорить." }, { 30.28, "-Мила Рассветная Странница, наставница шаманов" } } } },
    ["8bbdfeb3"] = { d = 16.8, v = "narrator", c = { x = { { 0.00, "Мок'Гордун — имя, которым огры зовут свои владения в холмах над Павильоном Лорисс." }, { 6.54, "Здесь, среди вытоптанной травы и костров, клан Гордунни живёт по собственному закону, и чужаку лучше не показываться на глаза дозорным." } } } },
    ["8bf34fc6"] = { d = 29.5, v = "narrator", c = { x = { { 0.00, "Лазуритовый рудник лежит к югу от Хилсбрадских полей, на холмах западнее Южнобережья." }, { 6.73, "По записям Хилсбрада, шахта принадлежит Альянсу: здесь трудятся шахтёры из Хилсбрадских полей под началом штейгера Бондса, а стража охраняет входы в штольни." }, { 18.98, "Добытое железо уходит в оружейни Альянса, и потому рудник — заманчивая цель для Отрёкшихся, которые стремятся оставить людей без металла." } } } },
    ["8c368701"] = { d = 15.4, v = "narrator", c = { x = { { 0.00, "Древесный тарантул." }, { 1.72, "Отряд: пауки." }, { 2.98, "Климат: тропический." }, { 4.78, "Вьёт гнёзда в мёртвой и гниющей древесине." }, { 8.31, "Часто встречается там, где идёт рубка леса: тарантул норовит зарыться в свежие пни." } } } },
    ["8c8afa36"] = { d = 36.6, v = "narrator", c = { x = { { 0.00, "Начнёт процесс охлаждения, который в этот момент потребует примерно от одной до двух минут (в зависимости от ситуации) для своего завершения." }, { 10.09, "ВАЖНОЕ ЗАМЕЧАНИЕ: главным силовым рубильником можно манипулировать, только когда три контрольных клапана на самих машинах выключены." }, { 19.65, "Выключать эти клапаны можно в любом порядке." }, { 22.97, "Первый – ГЛАВНЫЙ КОНТРОЛЬНЫЙ КЛАПАН, который можно найти у основания большой вертикальной дымовой трубы." }, { 30.59, "Далее – КЛАПАН УПРАВЛЕНИЯ ТОПЛИВОМ, его можно найти на большой трубе, которая ведёт" } } } },
    ["8cf1833f"] = { d = 41.1, v = "human-male", c = { x = { { 0.00, "Самоцвет Кора – судя по тем историям, что я слышал, эти драгоценные камни используются некоторыми заклинателями для сосредоточения в них энергии, необходимой для их магии, что придаёт им ещё больше смертоносной мощи." }, { 13.71, "Ночной эльф, которому я однажды помог, Тандрис Ветропряд, может рассказать тебе более подробно, если ты скажешь ему, что ты от меня." }, { 22.34, "Я считаю, что один из таких драгоценных камней, хранящих энергию, может быть использован для создания твоего оружия." }, { 29.86, "Когда мы говорили с ним последний раз, Тандрис был в городе Аубердин, на Тёмных берегах, в глубине осквернённого леса, что окаймляет побережье в тени родины этого ночного эльфа." } } } },
    ["8d748a88"] = { d = 16.0, v = "narrator", c = { x = { { 0.00, "Эредары, коварная раса демонических чародеев, использовала магию своих колдунов, чтобы поработить множество миров." }, { 9.23, "Расы тех миров мутировали под влиянием злых сил эредаров и сами превращались в демонов." } } } },
    ["8d7ac2e0"] = { d = 27.3, v = "human-male", c = { x = { { 0.00, "Если хочешь получить оленя в целости и сохранности, советуем не медлить с выкупом." }, { 5.85, "Пираты Южных морей очень плохо относятся к задержкам платежей, а нам известно, как ценен зверь для ТВОЕГО разбоя." }, { 13.87, "Принеси тысячу золотых ко входу в Бухту Сорванных Парусов в Танарисе." }, { 18.83, "Если кто-то попытается спасти оленя, то Метцену придётся прогуляться по очень короткой доске." }, { 25.45, "Да-да…" }, { 25.96, "Пираты Южных морей." } } } },
    ["8d7ed95a"] = { d = 24.9, v = "narrator", c = { x = { { 0.00, "Берег Разбитых Кораблей тянется вдоль Великого моря к юго-востоку от Колючего Холма и к северу от крепости Тирагард." }, { 9.17, "Своё имя он получил из-за кораблей Кул-Тираса, разбитых о скалы в битвах орков с флотом адмирала Праудмура." }, { 18.09, "Остовы судов до сих пор торчат из воды, а по песку среди обломков снуют крабы и макрура." } } } },
    ["8d83dd3c"] = { d = 34.8, v = "narrator", c = { x = { { 0.00, "Прошло больше десяти лет." }, { 2.12, "За это время Король-лич использовал свою огромную мощь, чтобы обрести власть над умами обитателей Нордскола, и повелел им возвести огромную цитадель над его Ледяным Троном." }, { 16.05, "Теперь, когда под его началом был весь Нордскол, Король-лич понял, что настала пора вторгнуться в Лордерон." }, { 24.74, "Находясь в ледяном плену, бывший орочий шаман начал обдумывать новые способы захвата власти." }, { 32.40, "Его призыв достиг всех земель." } } } },
    ["8d970d8e"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Великое море — бескрайний океан, разделяющий континенты Азерота." }, { 5.31, "Оно родилось при Расколе мира, когда древний Калимдор был разорван, а в его центре по сей день бушует Водоворот." }, { 14.54, "Западный берег Тернистой долины смотрит в эти воды: здесь ходят корабли из Пиратской бухты в Кабестан, а под волнами таятся наги и морские чудовища." } } } },
    ["8dbf9a4f"] = { d = 30.9, g = 1, v = "human-male", c = { m = { { 0.00, "Приветствую." }, { 0.85, "Мне, наконец, удалось выкроить время, чтобы изучить послание, которое ты нашёл у Плети." }, { 6.77, "Это было нелегко, и вот результаты моих трудов – информация о живом родственнике погибшего." }, { 13.00, "Сестру Максвелла зовут Зарена Кромвинд, она – кузнец в Пиратской бухте." }, { 17.94, "Не знаю, насколько они с братом были близки, но тебе стоит заглянуть к ней, если вдруг окажешься рядом." }, { 25.02, "Сейчас такая информация выясняется очень редко, так что ты можешь сделать доброе дело." } }, f = { { 0.00, "Приветствую." }, { 0.85, "Мне, наконец, удалось выкроить время, чтобы изучить послание, которое ты нашла у Плети." }, { 6.77, "Это было нелегко, и вот результаты моих трудов – информация о живом родственнике погибшего." }, { 12.93, "Сестру Максвелла зовут Зарена Кромвинд, она – кузнец в Пиратской бухте." }, { 17.83, "Не знаю, насколько они с братом были близки, но тебе стоит заглянуть к ней, если вдруг окажешься рядом." }, { 24.84, "Сейчас такая информация выясняется очень редко, так что ты можешь сделать доброе дело." } } } },
    ["8de07947"] = { d = 25.9, v = "dwarf-male", c = { x = { { 0.00, "День пятый." }, { 0.85, "Мой товарищ по заключению, ночной эльф, страдает от тяжких ран." }, { 5.34, "Свинолюди долго истязали его хлыстом, и, сдаётся мне, он уже скоро испустит дух – если, конечно, в этом зловещем месте каким-то чудом не окажется отряда спасателей." }, { 17.27, "Он то теряет, то вновь обретает сознание." }, { 20.20, "Когда он приходит в себя, я пытаюсь поделиться с ним своим скудным запасом воды." } } } },
    ["8de3a4d5"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Поместье «Остывший Очаг» стоит у главной дороги в центре Тирисфаля." }, { 5.45, "Некогда оно славилось тёплым домом и щедрыми урожаями, но чума забрала всех, кто здесь жил и работал; поля заросли, и по ним теперь бродят безмозглые зомби Плети." }, { 18.28, "Сам дом Отрёкшиеся отвоевали и держат в нём небольшую торговлю для путников, идущих по тракту." } } } },
    ["8e236201"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Великое море — бескрайние воды, омывающие восточный берег Степей и отделяющие Калимдор от Восточных королевств." }, { 8.99, "По нему из Кабестана уходят гоблинские корабли в Пиратскую бухту, а с востока приходят суда Терамора и пиратов Южных морей." }, { 19.00, "В глубинах у побережья, как говорят таурены с Лестницы Прилива, таится исполинская Иша Авак." } } } },
    ["8e573e8b"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Ферма Янтарленов стоит у дороги на Лок Модан, к северу от карьера Гол'Болар." }, { 6.01, "Семья Янтарленов разводит горных баранов, лучших ездовых животных дворфов, и здесь можно обучиться верховой езде." }, { 14.98, "Пока армия короля Магни сражается в дальних краях, ферму некому защищать, и по ночам к отаре подбирается вендиго Вагаш." }, { 24.53, "Рудра Янтарлен обещает награду тому, кто принесёт его клык." } } } },
    ["8e6d7902"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Котлы, которые охраняют верные культисты, должны были действовать как генераторы чумы, рассылая её по поместьям и городам северного Лордерона." }, { 10.69, "План Короля-лича сработал идеально." }, { 13.40, "Многие из северных деревень Лордерона заразились почти сразу же." }, { 18.27, "Как и в Нордсколе, горожане, заболевшие чумой, умерли и возродились уже преданными рабами Короля-лича." } } } },
    ["8e720965"] = { d = 36.3, v = "narrator", c = { x = { { 0.00, "Мутное озеро раскинулось в самом центре Когтистых гор, и от него расходятся дороги во все уголки края: к Пику Каменного Когтя, к Утёсу Ветрорезов и на юг по Паучьему тракту." }, { 13.93, "В его водах плодится слизь, а в скалах над озером гнездятся виверны." }, { 19.48, "Таурены верят, что земля здесь особенно сильна: у самой кромки воды находят семена Геи, способные вернуть жизнь выжженной земле." }, { 29.98, "Ходят слухи, что орки тайно собирают у озера яд виверн для отравленных клинков." } } } },
    ["8e86e046"] = { d = 26.2, v = "dwarf-male", c = { x = { { 0.00, "Если мы сможем сами решать, какой машине быть в отличном состоянии, а какой нет... полагаю, излишне объяснять, какое преимущество это даст нам на ставках." }, { 11.30, "Итак, от вас, милый Шипучка, мы ожидаем средство, которое ослабит прилежание техников." }, { 17.65, "Нет ли в Тернистой долине растений, трав или напитков, что могли бы размягчить мозги гномам и гоблинам?" }, { 25.18, "-- К." }, { 25.58, "Углебород" } } } },
    ["8ea89dba"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Поэтому они решили скрыть свои земли защитным барьером, который позволял бы им спокойно заниматься магией." }, { 8.09, "Они установили в разных точках Кель'Таласа, на границах магического барьера, цепь Рунных камней." }, { 15.36, "Рунные камни не только скрывали магию эльфов от внеземных угроз, но и помогали отпугивать суеверных троллей." } } } },
    ["8ebd722e"] = { d = 46.3, v = "creature/furbolg", c = { x = { { 0.43, "О, я проклят!" }, { 1.63, "Когда-то я был великим магом огров Чёрной Вершины." }, { 6.12, "Но я бросил вызов Арроку Роковому Смертному Воплю – и он украл мою магию, а потом наслал на меня проклятье." }, { 15.82, "Теперь мне приходится скитаться по залам Ордамара, подобно жалкой твари!" }, { 22.31, "Помоги мне!" }, { 23.35, "Найди Аррока и укради у него мою магию!" }, { 27.04, "Это будет нелегко, потому что Аррок прячется." }, { 31.20, "Чтобы выманить его, нужно очень важное событие." }, { 35.61, "Таким событием могла бы быть смерть его ближайшего помощника, вождя Омокка." }, { 42.35, "Прочти, и ты поймёшь." } } } },
    ["8f0c7fa7"] = { d = 34.8, v = "human-male", c = { x = { { 0.00, "\"Коса Элуны,\" – проскрежетал один из всадников голосом одновременно грубым и пронзительным, как звук точильного камня по лезвию секиры." }, { 9.26, "И последнее слово – Элуны – он прокаркал, как будто заглушая звук." }, { 13.80, "Ужас сковал меня, когда я услышал этот голос, и от страшного его звука, и потому что... я знал, о какой косе говорил всадник." }, { 22.57, "Должно быть, это была та самая проклятая вещь, что я вытащил из-под камней в Погибели Роланда несколькими днями раньше." }, { 30.84, "Вот что искали чёрные всадники!" }, { 32.95, "И вот что убило семью Свена." } } } },
    ["8f40de9a"] = { d = 27.5, v = "narrator", c = { x = { { 0.00, "Восточная комбинация кристаллов" }, { 2.61, "Существует два возможных эффекта: один оказывает положительный эффект на дух, второй создаёт щит, наносящий урон." }, { 11.86, "КРИСТАЛЬНАЯ СИЛА: требуются синие и зелёные кристаллы." }, { 16.34, "Повышает вашу характеристику \"дух\"." }, { 19.25, "КРИСТАЛЬНЫЙ ШИП: требует синих и жёлтых кристаллов." }, { 23.42, "Создаёт щит, который будет наносить урон атакующим." } } } },
    ["8f4788c7"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Дети земли не слушали тёмных голосов, но их постигло страшное проклятье." }, { 6.16, "Из тёмных западных земель пришли орды кровожадных существ – кентавров." }, { 12.17, "Каннибалы и разрушители, кентавры набросились на Шу'хало, как саранча." }, { 18.11, "Даже благословение Матери-Земли не помогло смелым охотникам одолеть эту напасть." } } } },
    ["8f4e4d50"] = { d = 41.0, v = "narrator", c = { x = { { 0.00, "Долина Североземья укрыта со всех сторон неприступными горами, и попасть в неё можно лишь через южный проход, защищённый каменной стеной и караулом." }, { 11.78, "Здесь, под сенью аббатства, начинают свой путь новобранцы короны, а маршал Макбрайд отвечает за оборону долины." }, { 20.60, "Спокойствие обманчиво: в леса пришли волки из Сумеречного леса, кобольды заняли рудник на западе, а на виноградниках у самой стены обосновались бандиты Братства Справедливости." }, { 34.69, "Река, что течёт через долину, покидает Североземье и впадает в Хрустальное озеро." } } } },
    ["8f59570b"] = { d = 30.5, v = "human-male", c = { x = { { 0.00, "Нелтарион:" }, { 0.78, "Нелтарион, названный при рождении Хранителем земли, был предан Азероту сильнее, чем кто-либо другой из Аспектов." }, { 8.88, "Его чёрные драконы создали горы и прочие возвышенности, включая и границы между землями смертных народов." }, { 16.59, "До сих пор неизвестно, что толкнуло его в пучину зла: внешнее ли влияние, внутренняя ли слабость." }, { 23.51, "Интересно знать, причастны ли к этой порче, которой подвергся великий чёрный дракон, Древние боги." } } } },
    ["8f9c6a3e"] = { d = 31.7, v = "dwarf-male", c = { x = { { 0.00, "То обстоятельство, что мы здесь имеем дело с различными мошенниками, заставляет меня считать, что нам понадобится поддержка армии короля." }, { 9.01, "Помимо того что раскопки потребуют военной поддержки, на мой неопытный взгляд, Бейл Модана может представлять стратегическую ценность для Альянса, учитывая нестабильность мировой политики в её текущем состоянии." }, { 22.87, "Увы, я отвлекаюсь." }, { 24.14, "Под скалой нужно проделать много работы." }, { 26.90, "Я провёл слишком много времени за письмом и недостаточно – за раскопками..." } } } },
    ["8fb55d46"] = { d = 19.6, v = "narrator", c = { x = { { 0.00, "Руины Бал'лал лежат на северо-западном побережье, к северу от Гром'гола, над Коварным рифом." }, { 7.01, "Остатки древних построек Гурубаши заняли тролли Кровавого Скальпа." }, { 12.12, "Рядом проходит путь между лагерем Орды и северными землями, и потому этот берег особенно неспокоен." } } } },
    ["8fe4dbbf"] = { d = 8.2, v = "narrator", c = { x = { { 0.00, "Эти юные маги начали практиковать магию для собственной пользы, а не ради исполнения долга перед своими сородичами." } } } },
    ["8fed2ac2"] = { d = 51.7, v = "narrator", c = { x = { { 0.00, "Ира Вэлор, лесная охотница." }, { 2.34, "Когда отец Иры занемог, она взяла на себя заботу о том, чтобы добывать в окрестных лесах еду и припасы." }, { 10.95, "Недостатка в дичи не было, но в тех лесах можно было с равным успехом и найти себе пищу, и самому стать чьей-то добычей." }, { 20.81, "С годами она сроднилась с лесом и предпочитала проводить время в тёмной чаще, а не в Вороньем Холме." }, { 28.91, "Путники, заблудившиеся среди деревьев, рассказывали о тени, что будто бы указывала им путь обратно к дороге." }, { 37.60, "Никто так и не узнал наверняка, кто это был, но слухи разлетелись быстро." }, { 43.51, "Говорят, Ира и поныне бродит по лесу, протягивая руку помощи тем, кто стал добычей живущих там зверей." } } } },
    ["9008e78a"] = { d = 30.0, v = "human-male", c = { x = { { 0.00, "Ниже представлена схема и расписание перевозки золота Братством Справедливости из шахт Элвиннского леса в наш штаб в Западном Крае." }, { 9.36, "Расписание:" }, { 10.20, "Воскресенье: в двенадцать тридцать" }, { 12.67, "Среда: в двенадцать тридцать" }, { 14.75, "В указанные дни золото, добытое в шахтах Элвин, будет доставляться на тыквенное поле Бреквеллов." }, { 21.70, "Лицо, отвечающее за весь процесс – \"Собиратель\" – будет носить на пальце специальное кольцо, которое я дал ему лично." } } } },
    ["9011bcc7"] = { d = 27.5, v = "dwarf-male", c = { x = { { 0.00, "Решение, впрочем, весьма просто." }, { 2.22, "Используя мякоть дерева в качестве адсорбента, мы можем соединить следы нитроглицерина с нитратом натрия, чтобы получить сильный взрывной заряд, способный пробиться даже через самые плотные массы." }, { 15.39, "Работа будет шумной и разрушительной, но наши поиски гораздо важнее комфорта местных жителей." }, { 21.67, "На самом деле нам уже пришлось выгнать из этой области стаю рогатых, которые мешали нам." } } } },
    ["9043e36c"] = { d = 25.6, v = "narrator", c = { x = { { 0.00, "Зловещее море омывает восточный берег Болота Печали и всё восточное побережье королевств." }, { 7.90, "Это неизведанные, не нанесённые на карты воды: ни один корабль не уходил далеко на восток, чтобы вернуться с рассказом о том, что там." }, { 19.52, "Для путника здесь кончается земля – дальше только серые волны и туман." } } } },
    ["90445788"] = { d = 29.5, v = "narrator", c = { x = { { 0.00, "Застава Скорбных Песков — обширные земли к западу от Прибамбасска, где среди сожжённых хижин и покосившихся башен хозяйничают тролли Песчаной Бури." }, { 11.80, "Призыватели огня, метатели топоров и шкуродёры стерегут скудные источники воды и не терпят чужаков." }, { 19.76, "Отсюда до стен Зул'Фаррака рукой подать, и всякий, кто идёт к городу троллей с востока, сначала проходит через эту заставу." } } } },
    ["906b0205"] = { d = 25.7, v = "human-male", c = { x = { { 0.00, "Девлин предупреждал нас, что если мы попробуем противостоять Плети, все мы будем обречены." }, { 6.17, "Он говорил нам об этом, когда они только ступили в Тирисфальские леса, задолго до того как они достигли нашего дома." }, { 14.35, "Возможно, он умолял нас покинуть его, а может быть, злорадствовал." }, { 18.90, "Всегда было сложно понять истинные мотивы Девлина." }, { 22.52, "Ещё будучи ребёнком, он был для нас всех загадкой." } } } },
    ["90715028"] = { d = 26.7, v = "creature/furbolg", c = { x = { { 0.43, "Вождь Омокк правит Чёрной Вершиной с помощью магии Аррока." }, { 5.17, "Аррок наложил на Омокка заклятие, которое убивает любого огра, бросившего ему вызов." }, { 12.18, "Омокк применял это заклятье много раз, а черепа его жертв складывал на месте силы над своим жилищем." }, { 20.43, "Вот куда ты должен идти, чтобы встретится с Арроком." } } } },
    ["9074f44e"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Лорды Строма, ища на диком севере чистоту и свет, решили оставить свой древний город." }, { 7.05, "Далеко к северу от Даларана лорды Строма построили новый город-государство, названный Лордерон." }, { 14.92, "Весь континент был назван в честь этого города." }, { 18.74, "Лордерон стал местом религиозного паломничества и укрытием для тех, кто искал спокойствия и безопасности." } } } },
    ["908cfd51"] = { d = 33.1, v = "dwarf-male", c = { x = { { 0.00, "Укрощение зверей, меткая стрельба, чтение следов – как научиться всему этому за такую короткую жизнь?" }, { 7.72, "Умение охотника требует недюжинной смекалки и огромного терпения." }, { 12.71, "Путь охотника не из лёгких, это точно." }, { 15.58, "Тебе нужно много тренироваться, чтобы достичь уровня самого неуклюжего ружейника из нашего народа." }, { 23.16, "Потому я тебе и пишу." }, { 24.87, "Приходи в Старую Наковальню, что в Холодной долине." }, { 28.76, "Я буду ждать тебя там." }, { 30.47, "-Торгас Мрачнон, наставник охотников" } } } },
    ["90b7898a"] = { d = 21.0, v = "skyborne-male" },
    ["90bd36ac"] = { d = 6.5, v = "narrator", c = { x = { { 0.00, "(Письмена на странице кружатся и перемещаются." }, { 3.60, "Вам кажется, будто книга дразнит вас.)" } } } },
    ["90c319d1"] = { d = 19.0, v = "narrator", c = { x = { { 0.00, "Ослабевший, но исполненный решимости спасти своего господина, Артас добрался в Нордскол – и обнаружил там наг Иллидана с эльфами крови." }, { 10.55, "Стремясь опередить обнаруженные силы врага, Артас со своими союзниками из Неруба направился к Ледяному Трону." } } } },
    ["9153922a"] = { d = 26.7, v = "human-male", c = { x = { { 0.00, "Ульдаман, день четвёртый." }, { 1.76, "...первым ключом к разгадке, что я обнаружил в глубинах Ульдамана, стал один из наиболее свирепых из виденных мною троггов, охранявший огромный сапфир, – один из тех, держу пари, что идеально бы подошёл в ожерелье." }, { 17.04, "Я слышал, как один из дворфов Тенегорна произнёс имя этого чудища: Гримлок." }, { 22.51, "И у этого свирепого Гримлока телохранители те ещё, я скажу..." } } } },
    ["915ae2e7"] = { d = 18.5, v = "human-female", c = { x = { { 0.00, "Несмотря на то, что мои коллеги в Даларане настороженно отнеслись к идее изучения кровавых камней, которые принесли с собой Кеган и его спутники, заключив в карантин четырёх беженцев и оставив кровавые камни при них, искренность Кегана обязала меня изучить его подвеску Кровавого камня." } } } },
    ["915df6b2"] = { d = 69.5, v = "narrator", c = { x = { { 0.00, "Пылевые топи — жаркое, вечно сырое болото на восточном побережье Калимдора, между Степями и Тысячей Игл." }, { 8.30, "Когда-то здесь лежала высокая равнина, но Великий Раскол обрушил её вниз, и подземные воды превратили долину в трясину, где кроколиски и мурлоки таятся в каждой заводи." }, { 21.49, "После битвы за гору Хиджал сюда привела своих людей леди Джайна Праудмур: на скалистом острове вырос Терамор, а вдоль дороги в Степи встали сторожевые башни." }, { 34.93, "Затем флот адмирала Даэлина Праудмура попытался подчинить эти земли, и его гибель сделала мир между Альянсом и Ордой хрупким." }, { 45.54, "Огры клана Каменного Молота, союзники Орды, потеряли родную деревню на юге, когда туда пришёл выводок Ониксии, дочери Смертокрыла, и отступили в Гиблотопь." }, { 57.88, "Теперь южные топи зовут Землёй Драконов, на дороге чернеют руины сожжённой таверны, а в глуши прячутся дезертиры Терамора и таурены Зловещего Тотема." } } } },
    ["9165a3ce"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Озеро Аль'Амет — одно из крупнейших озёр Тельдрассила; оно лежит к югу от Доланаара, и на берегу нет ничего, кроме маленького причала." }, { 10.18, "У восточной оконечности разбил лагерь друид Деналан, изучающий растения великого древа." }, { 16.88, "Больше всего его тревожат древесники — духи природы, которые здесь отчего-то впадают в ярость, а у воды прорастают всё новые их ростки." }, { 27.20, "В пещере на южном берегу засел древесник Дубохмур, поражённый чудовищной опухолью и заражающий порчей всё вокруг." } } } },
    ["917e7f10"] = { d = 18.6, v = "narrator", c = { x = { { 0.00, "Даже титаническое тело Саргераса пострадало от порчи, что поразила его когда-то благородное сердце." }, { 7.90, "Его глаза, волосы и борода горели пламенем, а его металлическая бронзовая кожа раскололась, открыв бездонное горнило пылающей ненависти." } } } },
    ["918962b4"] = { d = 12.1, v = "narrator", c = { x = { { 0.00, "Ноздорму Вневременный наложил на Древо Жизни заклятье, которое сделало ночных эльфов бессмертными, вечно молодыми и невосприимчивыми к любым болезням." } } } },
    ["91d4aee5"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Скользкая скала — небольшая пещера в дальнем северо-восточном углу степей, скрытая за Тропой Крылатого Ужаса." }, { 8.66, "Здесь в одиночестве живёт чёрный драконид, который, в отличие от своих сородичей, готов вести дела с чужаками — правда, не скупясь на насмешки и колкости." }, { 20.57, "Добраться до пещеры непросто: путь к ней лежит через долину, где хозяйничают драконы." } } } },
    ["91e4d752"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "Мастерская Сталекрута стоит к югу от озера Хельмово Ложе, на восточной окраине Дун Морога." }, { 6.93, "Когда-то здесь учил кузнечному делу Стурги Сталекрут, лучший из наставников." }, { 12.76, "Однажды ученики принесли ему странную мрачную руду, и вскоре на мастерскую напал отряд дворфов Чёрного Железа, перебивший всех." }, { 22.50, "Теперь в пустых стенах хозяйничают убийцы, и они нападают на любого, кто подойдёт слишком близко." } } } },
    ["91f4d6ee"] = { d = 35.2, v = "narrator", c = { x = { { 0.00, "Бухта Сорванных Парусов, укрытая горами с трёх сторон, — тайная гавань пиратов Южных морей на восточном берегу Танариса." }, { 9.62, "Здесь стоят их корабли и верфь, где строится новое судно, а на причалах толпятся флибустьеры, сорвиголовы и портовые рабочие." }, { 19.39, "Пираты давно досаждают гоблинам Порта Картеля, и начальник отдела безопасности Чепухастер обещает награду каждому, кто вернётся с их шляпами." }, { 30.50, "Здесь же прячется и Андре Огнебородый, разыскиваемый картелем." } } } },
    ["925ceff1"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Рудник Горного Эха уходит в скалы на северо-западе долины Североземья." }, { 5.48, "Некогда здесь добывали руду для нужд королевства, но теперь штольни заняли кобольды со свечами на головах, и они упрямо не желают уходить." }, { 15.97, "Маршал Макбрайд регулярно посылает новобранцев проредить их ряды." }, { 20.97, "Кобольды пугливы и нападают лишь тогда, когда их трогают, а в глубине рудника извилистый ход выводит в просторную пещеру." } } } },
    ["927721b9"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "На северо-восточном берегу Азшары, на Разорённом побережье, стоит древний храм Элуны, ныне известный как храм Арккоран." }, { 9.75, "В его верхних покоях обитает морской великан, которого мурлоки и макрура почитают как божество и стерегут его от чужаков." }, { 19.95, "Говорят, у великана давняя вражда с гидрами залива Бурь и их матерью Хетайрой." } } } },
    ["928c5f41"] = { d = 7.8, v = "narrator", c = { x = { { 0.00, "Король Ллейн Первый из дома Ринн." }, { 3.26, "Властительный лорд Штормграда." }, { 6.17, "Защитник Азерота." } } } },
    ["92b496ea"] = { d = 34.9, g = 1, v = "human-male", c = { m = { { 0.00, "Надеюсь, это письмо дойдёт до тебя." }, { 2.35, "Мне пришлось попотеть, чтобы выяснить хоть что-то об авторах той записки, что ты обнаружил." }, { 8.24, "Отец Самла возглавляет паломничество верующих отрёкшихся и троллей к Громовому Утёсу." }, { 13.71, "Его зовут Майлз Уэльш, а найти его и его друзей-нежить можно на прудах Видений." }, { 19.07, "У Торгала в живых осталась сестра, Элисса Дюма." }, { 22.24, "Насколько мне удалось выяснить, она живёт отшельником в Храме Луны в Дарнассе." }, { 27.36, "Думаю, тебе стоит навестить кого-нибудь из них." }, { 30.48, "Быть может, они не знают о том, что случилось с Торгалом и Самлой." } }, f = { { 0.00, "Надеюсь, это письмо дойдёт до тебя." }, { 2.37, "Мне пришлось попотеть, чтобы выяснить хоть что-то об авторах той записки, что ты обнаружила." }, { 8.34, "Отец Самла возглавляет паломничество верующих отрёкшихся и троллей к Громовому Утёсу." }, { 13.84, "Его зовут Майлз Уэльш, а найти его и его друзей-нежить можно на прудах Видений." }, { 19.23, "У Торгала в живых осталась сестра, Элисса Дюма." }, { 22.42, "Насколько мне удалось выяснить, она живёт отшельником в Храме Луны в Дарнассе." }, { 27.57, "Думаю, тебе стоит навестить кого-нибудь из них." }, { 30.70, "Быть может, они не знают о том, что случилось с Торгалом и Самлой." } } } },
    ["92cc7c65"] = { d = 32.4, v = "narrator", c = { x = { { 0.00, "К западу от дороги на Дун Модр стоит старая дворфийская усыпальница — Гробница Железноборода." }, { 7.35, "Рядом с ней кладбище и каменная статуя дворфа, в честь которого названо это место." }, { 13.97, "Склеп давно осквернён: по его плитам и между могил ползают чёрные и багровые слизнюки, и никто больше не приходит сюда хоронить своих мёртвых." }, { 25.28, "Путники обходят гробницу стороной, разве что ищут вещи, которые слизнюки утащили с собой." } } } },
    ["92ff3a91"] = { d = 34.8, v = "narrator", c = { x = { { 0.00, "В конце концов они ступили на берега королевства, которое люди позднее назовут Лордерон." }, { 7.12, "Продвигаясь в глубь континента, высшие эльфы основали поселение на спокойных Тирисфальских лесах." }, { 14.74, "Но через несколько лет многие из них начали сходить с ума." }, { 19.36, "Возникло предположение, что-то злое спало в недрах тех земель, но эти слухи так и не оправдались." }, { 27.05, "Высшие эльфы собрали всё своё добро и двинулись на север, к землям, богатым энергетическими линиями." } } } },
    ["9310402e"] = { d = 38.8, v = "narrator", c = { x = { { 0.00, "Алтарь Бурь стоит на западной окраине степей, в тени Пика Чёрной горы." }, { 5.58, "Такие алтари орочьи чернокнижники возводили во Вторую войну: здесь они превращали огров в огров-магов, наделяя их разумом и колдовской силой." }, { 16.75, "Камень давно растрескался и оплавился, но остатки его мощи по-прежнему притягивают чернокнижников клана Чёрной горы, творящих у алтаря свои обряды." }, { 28.35, "На холме неподалёку живёт и чернокнижник Мор'зул Вестник Крови — он изучает алтарь и, говорят, знает, как призвать коня из самой Бездны." } } } },
    ["931ee569"] = { d = 27.7, v = "narrator", c = { x = { { 0.00, "Лагерь Бронзоборода — маленькая стоянка дворфов Лиги исследователей в южном Силитусе, к востоку от Стены Скарабея." }, { 8.88, "Здесь учёные изучают глифы, найденные у входов в ульи силитидов, и расспрашивают каждого путника о судьбе знаменитого исследователя Бранна Бронзоборода." }, { 20.56, "Их исследования помогают командующему Крепости Кенария разгадать тайну исчезновения его жены." } } } },
    ["933b0cfd"] = { d = 34.8, v = "narrator", c = { x = { { 0.00, "«Болотный огонёк» — одинокая сторожка на Ведьмином холме, где живёт старый отшельник, знаменитый на всё болото своей похлёбкой." }, { 10.09, "Ему нужны лягушачьи лапки, паучьи глаза и прочие дары трясины, и он охотно делится рецептами с теми, кто не боится бродить по округе." }, { 21.06, "Дом окружён могилами и бродячими мертвецами, так что старик почти не выходит за порог, а в его огородике, говорят, зарыто нечто такое, что интересует и Терамор, и Гиблотопь." } } } },
    ["934058b9"] = { d = 37.6, v = "narrator", c = { x = { { 0.00, "Однако многие из выживших высокорождённых становились всё беспокойнее." }, { 5.55, "Как и Иллидан, они пали жертвами магии, и изо дня в день их снедало искушение, безумное желание вновь почувствовать энергию Источника Вечности и насладиться его магией." }, { 19.13, "Дат'Ремар, вспыльчивый и беззастенчивый предводитель Высокорождённых, начал в открытую насмехаться над друидами и обвинять их в трусости за то, что они отказались от использования магии, которая, как он считал, принадлежала им по праву." } } } },
    ["9380bf10"] = { d = 29.5, v = "narrator", c = { x = { { 0.00, "Находчивый, но неопытный Тралл решил бежать от Блэкмура и отправиться на поиски своих собратьев." }, { 7.35, "Путешествуя от одного лагеря к другому, Тралл обнаружил, что некогда могучие и воинственные орки превратились в совершенно безжизненных существ." }, { 18.30, "Не сумев найти среди них могучих воинов, о которых он так много слышал, Тралл отправился искать последнего непобеждённого вождя Грома Адского Крика." } } } },
    ["93a6a5de"] = { d = 30.3, v = "narrator", c = { x = { { 0.00, "Река Строптивая — самая большая река Калимдора." }, { 3.83, "Она берёт начало в озере на горе Хиджал, водопадами обрушивается в низины и разделяет Ясеневый лес и Азшару, а южнее — Степи и Дуротар." }, { 14.46, "Через неё переброшен мост, по которому дорога из Колючего Холма уходит к Перекрёстку." }, { 21.05, "Река впадает в Великое море к северу от Кабестана." }, { 25.09, "В её водах живут кроколиски, и охота на них не раз кончалась гибелью." } } } },
    ["93b058e6"] = { d = 30.7, v = "narrator", c = { x = { { 0.00, "Крепость Громового Молота — главный зал Заоблачного Пика, высеченный в толще горы." }, { 6.53, "Здесь правит верховный тан Фалстад Громовой Молот, принявший клан после того, как Курдран ушёл с экспедицией Альянса в Дренор." }, { 16.39, "В крепости есть постоялый двор и наковальня, но горна нет: Громовые Молоты живут ближе к небу, чем к кузнице." }, { 24.91, "У очага дворфы охотно рассказывают о грифонах и о старых войнах с троллями." } } } },
    ["93bb5d46"] = { d = 30.5, v = "narrator", c = { x = { { 0.00, "Хотя Азшара вместе с её высокорождёнными понимали, что при безответственном обхождении такая магия может быть опасна, они начали практиковать её с неуёмной страстью." }, { 12.67, "Кенарий и многие из ночных эльфов-мудрецов предупреждали, что безрассудство при обращении со столь неуловимой магической силой неизбежно грозит бедой." }, { 24.29, "Но Азшара и её последователи упрямо продолжали усиливать своё растущее могущество." } } } },
    ["93c4c200"] = { d = 44.2, v = "narrator", c = { x = { { 0.00, "Руины Альтерака — всё, что осталось от столицы горного королевства." }, { 5.23, "Во Вторую войну король Альтерака тайно сговорился с Ордой, и когда измена раскрылась, войска Альянса разрушили город, а его жители разбрелись по свету." }, { 17.24, "Опустевшие стены заняли огры клана Раздробленного Хребта во главе с вождём Муг'толом; здесь же слоняется жадный маг-огр Грел'борг Скряга." }, { 27.99, "Среди обломков ещё лежат бесценные книги погибшей альтеракской библиотеки, и хранители знаний Южнобережья мечтают спасти их из лап огров." }, { 38.73, "Синдикат считает эти камни своими и ведёт с ограми нескончаемую войну." } } } },
    ["93ea570a"] = { d = 27.2, g = 1, v = "troll-female", c = { m = { { 0.00, "Приятно слышать, что один из братьев Джен'шан явился в долину испытать свои способности." }, { 6.75, "Джен'шан ждёт этого с нетерпением!" }, { 9.34, "Не мне тебе рассказывать, какой ты сильный и ловкий охотник." }, { 13.91, "Дело Джен'шан – сделать тебя ещё более сильным и ловким." }, { 18.28, "Найди Джен'шан в Долине Испытаний." }, { 20.94, "Она научит тебя, как укрощать самых сильных зверей." }, { 24.96, "-Джен'шан, наставница охотников" } }, f = { { 0.00, "Приятно слышать, что одна из сестёр Джен'шан явилась в долину испытать свои способности." }, { 6.68, "Джен'шан ждёт этого с нетерпением!" }, { 9.28, "Не мне тебе рассказывать, какая ты сильная и ловкая охотница." }, { 13.91, "Дело Джен'шан – сделать тебя ещё более сильной и ловкой." }, { 18.28, "Найди Джен'шан в Долине Испытаний." }, { 20.94, "Она научит тебя, как укрощать самых сильных зверей." }, { 24.96, "-Джен'шан, наставница охотников" } } } },
    ["93eea41c"] = { d = 34.1, v = "narrator", c = { x = { { 0.00, "Перевал Чёрной горы — главные ворота в степи со стороны Красногорья." }, { 5.50, "За воротами кончаются тихие холмы у озера и начинается выжженная земля: небо краснеет, воздух густеет от пепла, а по обочинам тлеет опалённая трава." }, { 17.29, "Перевал стерегут орки клана Чёрной горы, и им же он служит дорогой для набегов на юг." }, { 24.01, "Тому, кому такой путь не по силам, лучше повернуть обратно, пока не поздно, — за перевалом враг куда сильнее, чем в Красногорье." } } } },
    ["93ff02a2"] = { d = 39.6, v = "human-male" },
    ["9406cf2d"] = { d = 12.5, v = "human-male", c = { x = { { 0.00, "Среди ночных эльфов ходят слухи, будто Алекстраза и полубог Кенарий были близкими друзьями и будто именно Кенарий призвал её во время первого вторжения Пылающего Легиона." } } } },
    ["9424fe8f"] = { d = 68.9, v = "narrator", c = { x = { { 0.00, "Тёмные берега — длинная полоса побережья на северо-западе Калимдора, где над серыми пляжами почти всегда висят тучи, а с моря тянет холодный туман." }, { 11.89, "Между горами и водой растёт сумрачный хвойный лес, и на утёсах крошатся руины древних городов." }, { 19.38, "Когда-то эта земля была одной из самых богатых в империи ночных эльфов, но Великий Раскол разрушил её города и перекроил всё побережье." }, { 30.34, "Тысячи лет спустя эльфы вернулись сюда малым числом и отстроили портовую деревню Аубердин, откуда корабли уходят к Тельдрассилу и в Гавань Менетилов." }, { 42.37, "В опустевших руинах хозяйничают наги, сатиры и беспокойные духи высокорождённых, а на пляжах промышляют мурлоки." }, { 51.23, "Реки, текущие с гор из Осквернённого леса, несут порчу: от неё сходят с ума фурболги и болеют олени." }, { 59.23, "На юге, у Меча Властителя, собирается клан Сумеречного Молота, а в северной башне Алталакса что-то замышляют чернокнижники." } } } },
    ["94378d5c"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Сокрытое Море омывает западный берег Ясеневого леса у Зорамского взморья." }, { 6.08, "Это огромное море к северу и западу от Калимдора, названное так за туман, которым ночные эльфы веками укрывали свой континент от чужаков." }, { 17.28, "После Великого Раскола под его волнами скрылись город Зорам и храм, ставший Непроглядной Пучиной." }, { 25.27, "В его водах живут гигантские черепахи и, как говорят, кракены." } } } },
    ["9449520f"] = { d = 16.6, v = "human-male", c = { x = { { 0.00, "Вера." }, { 0.55, "Вера – вот наш неиссякаемый источник радости порабощения." }, { 5.47, "Вера согреет нас в самые холодные ночи Силитуса." }, { 9.77, "Вера дарует нам благодать Господ, когда настанут Последние Дни." }, { 15.31, "Вера спасёт нас." } } } },
    ["9489878b"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Долина Нефритового Пламени лежит на юго-западе леса, к западу от дороги." }, { 5.80, "Здесь разбили лагерь сатиры Нефритового Пламени — рогатые потомки высокорождённых, проклятых Саргерасом ещё в Войну Древних." }, { 15.42, "Сатиры селятся у осквернённых лунных колодцев и своей магией вгоняют порчу леса всё глубже; поговаривают, что они же служат разведчиками и убийцами Совета Теней." }, { 28.07, "Эридана Грусть Ветра из Изумрудного святилища считает, что за ними стоит нечто большее, и просит путников проредить их ряды." } } } },
    ["94b611be"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Уцелевшие войска Альянса под командованием Джайны Праудмур осели в южном Калимдоре." }, { 6.36, "На восточном краю Пылевых топей они построили укреплённый портовый город Терамор, в котором люди и дворфы объединили усилия ради выживания в этой негостеприимной земле." }, { 19.25, "Хотя жители Дуротара и Терамора и сохраняли непрочное перемирие, оно не могло длиться вечно." } } } },
    ["94e18589"] = { d = 38.0, v = "narrator", c = { x = { { 0.00, "Обитель Бен'этиль — небольшой курган-святилище в глубине лощины Бен'этиль, построенный ночными эльфами для спящих друидов-воронов." }, { 10.56, "В нижнем и верхнем ярусах они покоятся в Изумрудном Сне по уговору с Изерой, а реликвии Пробуждения хранятся в священных ларцах." }, { 20.90, "Ныне обитель захватили фурболги Кривой Сосны: их шаман научился разлучать дух спящего с телом, и тела друидов, лишённые воли, нападают на всякого вошедшего." }, { 33.57, "Дух Обена Яростного Когтя, запертый во Сне, ищет помощи." } } } },
    ["95287d89"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Неизвестно, что именно разбудило земельников, закрывшихся в Ульдамане, но в конце концов они очнулись от сна." }, { 9.20, "Земельники обнаружили, что за время своего забытья сильно изменились." }, { 15.11, "Их каменные шкуры разгладились и сделались мягкой кожей, а их власть над камнем и землёй ослабла." }, { 23.24, "Они стали смертными существами." } } } },
    ["952a1012"] = { d = 32.2, v = "dwarf-male", c = { x = { { 0.00, "Зверь даже не обнаружил нашего присутствия." }, { 3.16, "Если быть честным, единственное приветствие, которое он получил от экспедиции, – это пулю между глаз." }, { 10.55, "Ажек одобрительно кивнула мне, а сэр Эрлгедин радостно крикнул: “Ура!” Настало время отпраздновать успех, выкурив трубку, затерявшуюся в глубинах моего рюкзака." }, { 22.28, "Барнил отправился на вершину утёса за трофеем." }, { 25.65, "Вид поверженного чудища доставлял мне немалое удовольствие, как и любая значительная победа." } } } },
    ["954411e0"] = { d = 20.4, v = "dwarf-male", c = { x = { { 0.00, "Наш первый день прошёл, как обычно проходят первые дни." }, { 4.07, "Большую часть времени мы обустраивали лагерь." }, { 7.46, "Мне удалось найти идеальное место у небольшой чистой заводи." }, { 12.07, "Старые, обветшавшие мостки указывали на то, что в этом месте когда-то жили." }, { 17.77, "Кто именно там жил, мы пока не знали." } } } },
    ["9572b4a3"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Когда натиск армии троллей был сломлен и они попытались сбежать, армия Торадина начала преследование, беспощадно убивая всех троллей, которых удалось настичь." }, { 12.50, "Тролли так никогда и не оправились от этого поражения, а в истории больше не будет единого народа троллей." }, { 20.84, "Убеждённые в том, что Кель'Талас спасён от разрушения, эльфы поклялись в верности и дружбе Аратору и семье его короля Торадина." }, { 30.66, "Люди и эльфы с тех пор были в мирных отношениях." } } } },
    ["95830546"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "Немногие уцелевшие при взрыве эльфы собрались вместе, наспех сколотили несколько плотов и медленно поплыли к далёкой земле." }, { 10.07, "Милостью Элуны Великий Раскол пережили и Малфурион с Тирандой, и Кенарий." }, { 16.10, "Измученные герои согласились стать предводителями своих выживших сородичей и обустроить для них новый дом." } } } },
    ["958ceb72"] = { d = 29.6, v = "narrator", c = { x = { { 0.00, "Старая переправа — обветшалый причал на берегу озера Лордамер к востоку от Гробницы, откуда некогда ходили лодки на остров Фенриса." }, { 10.48, "Теперь переправу стерегут гноллы-гнилошкуры и всякая нежить, а вдоль настила громоздятся кучи чумных трупов." }, { 18.96, "Стражи смерти видели здесь Фенвика Татроса, вожака нежити, поселившейся в лесу, и Отрёкшиеся уверены, что Плеть заняла это место неспроста." } } } },
    ["95d22ade"] = { d = 21.0, v = "narrator", c = { x = { { 0.00, "Эонар также даровала младшей сестре Алекстразы, изящной зелёной драконице Изере, определённую власть над природой." }, { 9.36, "Изера впала в вечный транс, именуемый \"Сном Творения\"." }, { 13.85, "Известная под именем Дремлющей, она следит за природой мира из царства Изумрудного Сна." } } } },
    ["95d947ab"] = { d = 34.4, v = "goblin-male", c = { x = { { 0.00, "Операций в большом масштабе так близко к земле тауренов, но им не кажется, что таурены представляют собой серьёзную угрозу нашему плану в этой местности в целом." }, { 10.56, "Мы рады слышать, что разработки начались в богатых минералами равнинах Мулгора." }, { 15.79, "Из-за этого совет одобрил твой запрос касательно оборудования." }, { 19.94, "Нам кажется, что в Мулгоре можно получить существенную выгоду не только за счёт древесины, но и при добыче минералов, поэтому тебе также предоставят несколько наших новейших резаков и материалы, необходимые для изготовления." } } } },
    ["95e2ff15"] = { d = 32.7, v = "human-female", c = { x = { { 0.00, "После того как я это увидела, моя голова просветлела, возможно, благодаря недавнему порезу (хотя я не верю, что потеряла настолько много крови), а может быть потому, что я, наконец-то, после стольких разочарований, обнаружила одно из свойств кровавого камня." }, { 18.29, "Я добралась до своего стула и села, размышляя." }, { 21.61, "Мысли и вопросы роились в моей голове, вызывая головокружение и угрожая свалить меня наземь." }, { 28.26, "Кровавый камень пьёт кровь?" }, { 30.18, "Ему нужна кровь?" }, { 31.39, "Он притягивает кровь?" } } } },
    ["95f3d2ad"] = { d = 49.7, v = "narrator", c = { x = { { 0.00, "Кладбище Вороньего Холма – огромный погост на северо-западе Сумеречного леса, севернее опустевшего городка." }, { 8.58, "С тех пор как на лес пала тьма, кладбище разрослось и поглотило округу, а покой мёртвых нарушили некромант и его слуги." }, { 17.87, "Между могил бродят вурдалаки, плотояды, костеглоды и распространители чумы, в паутине сидят огромные пауки, а воры разоряют могилы: тела отсюда продавали самому Морбенту Скверну." }, { 32.17, "По дорожкам ходит грозный неупокоенный рыцарь, от которого лучше держаться подальше." }, { 38.89, "На холме в северо-западном углу стоит дом некроманта, два мавзолея ведут в катакомбы, а к северу от ограды – хижина отшельника Аберкромби." } } } },
    ["9606f31f"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Кил'джеден понимал, что Король-лич, его собственное творение, достиг слишком большого могущества, и управлять им уже невозможно, а потому он приказал Иллидану убить Нер'зула, уничтожив Плеть раз и навсегда." }, { 16.75, "Взамен он пообещал Иллидану невиданную силу и почётное место среди повелителей Пылающего Легиона." } } } },
    ["9619332d"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "Приозёрье, небольшой городок людей на берегу Озера Безмолвия, остаётся единственным поселением королевства во всём Красногорье." }, { 9.26, "В ратуше заседает мировой судья Соломон, а в таверне у пристани всегда полно народу." }, { 15.58, "Город переполнен беженцами с северных земель, спасающимися от орков клана Чёрной Горы, а подкрепления из Штормграда так и не пришли." }, { 25.24, "У моста маршал Маррис набирает добровольцев, кузнец Вернер Осгуд куёт оружие, а штейгер Ослоу никак не может достроить Мост Безмолвия: не хватает железа." } } } },
    ["962b10e7"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Руины Яростного Ветра на севере Фераласа — остатки поселения Высокорождённых, таких же древних, как Забытый Город." }, { 9.03, "Ныне их заняли гарпии, гнездящиеся на обломках колонн." }, { 13.40, "В центре руин растёт огромное дерево, которое ревностно берегут зелёные драконы с Нефритового озера." }, { 21.35, "У старого алтаря среди развалин, как говорят в Крепости Оперённой Луны, ещё горят волшебные огни, способные вернуть силу древнему посоху." } } } },
    ["96767602"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Члены Культа, созданного Кел'Тузадом, добровольно желали умереть и стать слугами своего тёмного повелителя." }, { 8.41, "Они жаждали получить бессмертие через нежизнь." }, { 12.18, "По мере распространения чумы северные земли наводняли полчища беспощадных зомби." }, { 18.59, "Кел'Тузад назвал новую армию Плетью Короля-лича." }, { 22.58, "Этой армии предстояло покорить Лордерон и стереть человечество с лица земли." } } } },
    ["96a2b711"] = { d = 80.5, v = "narrator", c = { x = { { 0.00, "Стальгорн — столица дворфов, город, вырубленный в самой высокой горе Дун Морога." }, { 6.74, "Первые дворфы, вышедшие из Ульдамана, врубились в гранит и поставили в сердце горы Великую Кузню, вокруг которой кольцами разошёлся весь город." }, { 18.51, "Некогда здесь правил Модимус Старая Наковальня, чья статуя встречает гостей у ворот, а после Войны Трёх Молотов единственным хозяином Стальгорна остался клан Бронзобородов." }, { 32.65, "Ныне на троне сидит король Магни Бронзобород, верный друг Альянса, потерявший брата Мурадина в далёком Нордсколе." }, { 41.98, "Когда пал Гномреган, король дал беженцам кров: в Городе Механиков поселились гномы во главе с главным механиком Меггакрутом, мечтая вернуть себе дом." }, { 54.20, "Отсюда же уходит Подземный поезд — гномье чудо, связавшее Стальгорн со Штормградом." }, { 61.16, "В Зале Исследователей Лига Исследователей хранит находки со всего мира, в Заброшенном гроте шепчутся те, кто предпочитает тень, а в Военном квартале звенит сталь." }, { 74.34, "Жар Великой Кузни не гаснет ни днём, ни ночью, и весь город живёт её дыханием." } } } },
    ["96bce707"] = { d = 30.7, v = "narrator", c = { x = { { 0.00, "Два Колосса — пара исполинских столовых гор на западе Фераласа, самая высокая точка этих земель." }, { 7.70, "Между ними проходит дорога из Пустошей, и всякий, кто входит в джунгли с севера, первым делом видит их отвесные стены." }, { 17.18, "Склоны кишат зверьём, а на вершине Восточной колонны прячется глубокое озерцо." }, { 23.39, "Отважный дворф Греган уверяет, что придумал способ спуститься с вершины без вреда для здоровья." } } } },
    ["96d5d2d1"] = { d = 15.5, v = "human-male", c = { x = { { 0.00, "Ужас этих последних недель становится невыносимым; и всё же, написав увиденное мною, я чувствую себя немного лучше." }, { 8.70, "И я буду продолжать своё занятие, так как это единственное моё успокоение в эти страшные дни." } } } },
    ["96da5fef"] = { d = 35.2, g = 1, v = "creature/bolvar", c = { m = { { 0.00, "Соломон!" }, { 0.64, "Предъявителю данного приказа дарован официальный статус действующего представителя Штормграда." }, { 7.33, "Вы можете воспользоваться его помощью в поисках доказательства участия чёрных драконов в делах орков Чёрной Горы." }, { 15.36, "В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозёрье." }, { 31.30, "С наилучшими пожеланиями," }, { 33.10, "Верховный лорд Болвар Фордрагон" } }, f = { { 0.00, "Соломон!" }, { 0.63, "Предъявителю данного приказа дарован официальный статус действующего представителя Штормграда." }, { 7.24, "Вы можете воспользоваться её помощью в поисках доказательства участия чёрных драконов в делах орков Чёрной Горы." }, { 15.04, "В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозёрье." }, { 30.78, "С наилучшими пожеланиями," }, { 32.56, "Верховный лорд Болвар Фордрагон" } } } },
    ["970862b3"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Это был Рагнарос – Повелитель Огня, бессмертный повелитель всех элементалей огня, изгнанный титанами, когда мир ещё был юн." }, { 10.66, "Теперь, освобождённый призывом Тауриссана, Рагнарос явился вновь." }, { 16.33, "Возрождение Рагнароса в Азероте сотрясло Красногорье, и посреди руин воздвигся огромный вулкан." } } } },
    ["9719d499"] = { d = 33.2, v = "narrator", c = { x = { { 0.00, "Трясина — обширная топь в самом сердце болота, от Разрушенной башни на западе до Пылевой бухты на востоке." }, { 8.71, "Здесь кроколиски дремлют в каждой заводи, по кочкам ползают пауки и слизни, а на тропах встречаются таурены Зловещего Тотема." }, { 18.96, "В самом глухом углу стоит хижина волшебницы Табеты, которая живёт с двумя учениками и принимает магов, ищущих знаний; неподалёку в трясине лежит разбитый гоблинский дирижабль." } } } },
    ["9722483f"] = { d = 36.6, v = "narrator", c = { x = { { 0.00, "Древние Боги – воля нашего мира." }, { 3.05, "В каждом шторме слышен громовой хохот одного из них." }, { 7.79, "В пламени каждого пожара виден блеск их глаз." }, { 11.81, "Когда Древние Боги ходят, земля дрожит и трескается, а все, кто слабее их, кричат в отчаянии." }, { 20.17, "И одно лишь отчаяние им уготовано: как огонь не жалеет руки неразумного ребёнка, так и Древние Боги не жалеют тех, кто ниже их." }, { 31.34, "В лучшем случае мы для них пешки." }, { 34.31, "В худшем случае – игрушки." } } } },
    ["978991ae"] = { d = 42.0, v = "narrator", c = { x = { { 0.00, "Путь Ужаса тянется по юго-западу кратера, между источниками Голакка и Скользким оврагом." }, { 6.93, "Имя оправдано: здесь водятся самые крупные и свирепые твари Ун'Горо — исполинские панцирные ящеры, диметрадоны, жутедактили и дьявозавры, чьи шаги слышны задолго до того, как покажется сам зверь." }, { 21.99, "Среди зарослей встречаются странные каменные глыбы, которые дворфы экспедиции считали следами титанов, но рассмотреть их вблизи так никто и не сумел." }, { 33.61, "На восточной кромке остался брошенный лагерь экспедиции, а среди камней здесь находят красные кристаллы Силы." } } } },
    ["978b2745"] = { d = 35.7, v = "narrator", c = { x = { { 0.00, "Первым шагом Кил'джедена было порабощение вампирических повелителей ужаса своей чудовищной властью." }, { 7.74, "Повелители ужаса служили его личными агентами по всей вселенной, они находили удовольствие в поиске примитивных рас для своего повелителя, совращали их и сбивали с пути истинного." }, { 21.54, "Первым среди повелителей ужаса был Тикондрус Затмеватель." }, { 26.00, "Тикондрус безукоризненно служил Кил'джедену и согласился распространять пылающую волю Саргераса во всех тёмных уголках вселенной." } } } },
    ["978d6363"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Берег за Южной грядой — широкая тихая полоса песка к югу от Бухты Сорванных Парусов." }, { 6.85, "В прибое бродят береговые черепахи и морские великаны — земляные яростни, а у самой воды попадаются черепахи размером с лодку." }, { 16.91, "Неподалёку от берега лежит крошечный островок, где живёт гномка Однокнопка, ничем не объясняющая своего уединения." } } } },
    ["97d5a0a5"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "Войскам Туралиона удалось уничтожить Тёмный портал – волшебный портал в родной мир орков, Дренор." }, { 7.91, "Орда, лишённая подкрепления и разрываемая на части внутренней враждой, наконец, пала перед мощью Альянса." } } } },
    ["97df6f6b"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Три Угла, перекрёсток на самом западном краю Красногорья, лежит сразу за границей Элвиннского леса." }, { 7.87, "Отсюда три дороги расходятся к трём городкам: на запад в Златоземье, на восток в Приозёрье и на юго-запад через мост в Темнолесье, что в Сумеречном лесу." }, { 19.72, "Посреди перекрёстка стоит сторожевая башня стражи Штормграда, и отсюда путник впервые видит красные скалы." }, { 28.16, "Стражник на посту говорит, что на дороге пока спокойно, но к северу и востоку он замечал лагеря гноллов." } } } },
    ["9802fd4b"] = { d = 22.5, v = "narrator", c = { x = { { 0.00, "Бухта Острорука — часть Великого моря у северо-восточного берега Дуротара, рядом со Скалой Черепа." }, { 7.90, "Она названа в честь Каргата Острорука, вождя клана Изувеченной Длани." }, { 13.51, "Через пролив на севере виден берег Азшары." }, { 17.03, "Пристани здесь нет, лишь пустынный пляж, на котором хозяйничают макрура." } } } },
    ["9821a131"] = { d = 38.1, v = "narrator", c = { x = { { 0.00, "Отправился в деревню в поиске ответов и жены с детьми." }, { 4.65, "Морган спрашивал о судьбе своей семьи, но никто ничего не знал." }, { 10.05, "Жрец из Темнолесья, как теперь называлась деревня, посоветовал ему пойти на кладбище у Вороньего Холма и поискать там." }, { 19.96, "Морган отказывался верить в то, что его семья погибла, и продолжал поиски среди ферм и домов Сумеречного леса, но тщетно." }, { 30.24, "Морган отправился из Темнолесья в соседнее Приозёрье, надеясь, что его семья осела там." }, { 37.55, "По пути" } } } },
    ["9835d869"] = { d = 21.0, v = "orc-male", c = { x = { { 0.00, "Будь осторожен, воин, ведь обе эти башни сильно укреплены и управляются элитными командорами Вандара." }, { 8.40, "И если твои войска прорвут укрепления, сделай так, чтобы командор в башне был… устранён." }, { 15.69, "Это – следующий важный шаг на пути к победе над Грозовой Вершиной." } } } },
    ["983ed938"] = { d = 26.5, v = "narrator", c = { x = { { 0.00, "Застава Белого Плёса — крошечная стоянка Орды у дороги на северо-западе Тысячи Игл, по соседству с Лагерем Э'Ток." }, { 8.63, "Несколько шатров тауренов да костёр — вот и вся застава, и кентавры племени Галак напоминают о себе постоянно." }, { 16.91, "Здесь же нашёл приют гоблин Визло, чей караван разграбили кентавры: он никак не может смириться с потерей своего гипервместителя." } } } },
    ["984b1b4d"] = { d = 22.5, v = "narrator", c = { x = { { 0.00, "Зловещие шпионы Пылающего Легиона, которые были изгнаны во время обрушения Источника Вечности, были привлечены обратно в мир неосторожными заклинаниями магов Даларана." }, { 12.31, "Хотя эти относительно слабые демоны не проявляли себя в полной мере, они создавали довольно большую неразбериху и хаос на улицах Даларана." } } } },
    ["98565af6"] = { d = 9.5, v = "narrator", c = { x = { { 0.00, "РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ АЛЬЯНСА." }, { 3.73, "Старший сержант." }, { 5.42, "Сержант." }, { 6.31, "Младший сержант." }, { 8.00, "Капрал." }, { 8.80, "Рядовой." } } } },
    ["987f7ac1"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Озеро Назферити лежит в сердце северных джунглей, к западу от Зул'Гуруба." }, { 5.59, "Его мутные воды кишат кроколисками и прожорливой рыбой, а по берегам обосновалась Торговая компания: гоблины валят лес, а посреди озера возвели буровую платформу." }, { 17.94, "Здесь же они обрабатывают поющие кристаллы, добытые в холмах у Хрустальной шахты." }, { 24.07, "Через озеро течёт длинная река, чьи истоки лежат далеко на севере." } } } },
    ["9881aa17"] = { d = 22.6, v = "human-male", c = { x = { { 0.00, "Вот цель моей книги: составить список этих существ, этих зловещих созданий, желающих уничтожить наши земли, чтобы те странники, кто на них наткнётся, знали, чего им следует ожидать." }, { 13.97, "Поэтому если ты считаешь себя стражем Азерота, читай дальше." }, { 18.76, "Читай, чтобы знать своего врага." }, { 21.33, "-Ур" }, { 21.61, "Маг из Даларана" } } } },
    ["988ea6f2"] = { d = 3.0, v = "narrator", c = { x = { { 0.00, "Этот трехстраничный документ пуст." } } } },
    ["9893fb8f"] = { d = 28.4, v = "narrator", c = { x = { { 0.00, "Остров Битв — клочок земли у Торгового побережья к югу от Кабестана." }, { 5.77, "Здесь, вдали от чужих глаз, воины всех рас и вер сходятся в поединках, а хозяин острова, старый воин-человек, принимает вызовы всех, кто считает себя достойным." }, { 19.14, "На песке стоят тренировочные чучела, у костров толпятся зрители, а в мутной воде у берега кишат хищные рыбёшки." } } } },
    ["98b1e8ac"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "Эта новость встревожила великих драконов, потому что пока существовал источник, существовала и возможность того, что Пылающий Легион когда-нибудь снова вернётся в этот мир." }, { 12.89, "Малфурион и три дракона договорились вечно охранять Источник и решили сделать всё возможное для того, чтобы демоны никогда больше не появились в этом мире." } } } },
    ["98b2d1f4"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Пещера Бешеного оврага — глубокая нора в скалах западного побережья Фераласа." }, { 6.40, "В ней живут самые злобные йети Фераласа." }, { 9.79, "Странно, но в глубине пещеры находят книги и магические знаки, а дальние залы сложены в манере ночных эльфов — быть может, некогда здесь было эльфийское убежище, чьих хозяев давно никто не видел." } } } },
    ["98ba1278"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "Перекрёсток — крупнейшее поселение Орды в Степях, выросшее там, где Золотой Путь пересекает дорогу из Кабестана в Когтистые горы." }, { 10.42, "Отсюда ветрокрылы летят почти во все форпосты Орды в Калимдоре, а торговцы у кострищ громко расхваливают товар." }, { 19.59, "Заправляет всем шаманка Сергра Чёрный Шип, оборону держит Торк, а друид Тонга Рунический Тотем изучает странную силу, пробуждающую оазисы." }, { 30.90, "У ворот день за днём стоит Манкрик, высматривающий свинобразов: его жена пропала в бою." } } } },
    ["99051d83"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Пещеры Ретбана уходят глубоко в скалы в холмах к северу от Приозёрья." }, { 5.55, "Они названы в честь Барта Ретбана, первооткрывателя тёмной руды: металл из неё мягче железа, зато переписчики делают из неё чернила приятного тёмного цвета." }, { 17.94, "Из-за набегов орков жители города забросили добычу, и теперь в пещерах хозяйничают гноллы стаи Красногорья, а их работяги сами копают руду." }, { 29.32, "В таверне Приозёрья дворф Йорус Ячменовар предлагает смельчакам испытание: дойти до первой развилки пещер и вернуться за час." } } } },
    ["9918a49d"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Вернувшись к жизни, он обнаружил, что уже повзрослел, а его друзья Ллейн и Андуин стали правителями Азерота." }, { 8.80, "Он желал использовать обретённые силы на благо своей родной земли, но злой дух Саргераса овладел его разумом и направил его на путь злодеяний." } } } },
    ["99219746"] = { d = 20.1, v = "narrator", c = { x = { { 0.00, "Символом перерождения орков стал поход Тралла на крепость Дарнхольд и освобождение из лагерей всех пленных; зловещим планам Блэкмура не суждено было сбыться." }, { 12.57, "Но эта победа далась дорогой ценой: во время осады одного из лагерей в бою погиб Молот Рока." } } } },
    ["9943dde2"] = { d = 17.9, v = "narrator", c = { x = { { 0.00, "Зимрел Чернозуб" }, { 1.40, "Когда безумие тёмного ключа овладевает Зимрелом, лишь крики умирающих могут успокоить его." }, { 9.27, "За свою жертву он всегда будет иметь место над ареной." }, { 14.10, "Да смягчит гнев его сердца наш кровавый спорт." } } } },
    ["99525c1c"] = { d = 37.3, v = "narrator", c = { x = { { 0.00, "Бастион — последний рубеж Отрёкшихся на границе Тирисфаля и Чумных земель." }, { 5.77, "Во время Третьей войны здесь стоял лагерь Утера, где он укрывал беженцев из павшей столицы." }, { 12.95, "Ныне у частокола стражи смерти несут дозор вместе с бойцами Серебряного Рассвета: общая угроза Плети заставила забыть о разногласиях." }, { 23.50, "Верховный палач Деррингтон готовит удар по Андоралу, а жрица Тени Вандис изучает чумные котлы." }, { 31.03, "Небо над Бастионом уже затянуто той же желтоватой мглой, что и над Чумными землями." } } } },
    ["9975da69"] = { d = 23.0, v = "scourge-male", c = { x = { { 0.00, "При продолжении прочёсывания наши агенты задержались на ферме Ивара." }, { 5.65, "Сам Ивар вместе с большей частью своей семьи и работников поддался Плети и стал её слугой." }, { 13.25, "Наши агенты попали в засаду и, хотя они победили атакующих, получили серьёзные повреждения, в особенности агент Квинн." } } } },
    ["9998a220"] = { d = 20.7, v = "human-female", c = { x = { { 0.00, "В ожидании результатов мы с Кеганом много беседовали." }, { 3.58, "Мне хотелось побольше узнать от него о кровавых камнях, но он никогда не говорил мне больше, чем в тот день, когда отдал мне свою подвеску." }, { 12.86, "И он нечасто говорил о времени, проведённом им среди тех, кого он называл \"Отрёкшимися\", – так он именует свой клан нежити." } } } },
    ["9998f022"] = { d = 13.8, v = "narrator", c = { x = { { 0.00, "Эти налоги и постоянные споры по поводу границ вызвали недовольство среди населения." }, { 6.48, "Казалось, что хрупкий союз, который люди заключили в тяжёлый час, может развалиться в любой момент." } } } },
    ["999d7ae3"] = { d = 18.2, v = "gnome-male", c = { x = { { 0.00, "Дорогой дневник, написав последнюю запись, я вышел из убежища в сильном гневе." }, { 6.22, "Ох, как же я был зол." }, { 7.78, "Хочу придумать для своих прислужников новую униформу, что отражала бы мою ярость." }, { 14.22, "Мне уже лучше, но чего-то не хватает." }, { 17.19, "Скоро вернусь…" } } } },
    ["99b06ab8"] = { d = 43.4, v = "narrator", c = { x = { { 0.00, "Тенедол — разрушенная деревня на юго-западе Шепчущего леса." }, { 4.82, "До нашествия Плети эта уединённая деревушка славилась шепчущим эликсиром из трав, растущих только в Тирисфале; его запретили продавать в городе, но аптекари, мистики и ценители ядов всё равно платили за него щедро." }, { 21.87, "Ныне в руинах обосновались Омрачённые — восставшие паладины, не смирившиеся с новым существованием и поднявшие клинки на братьев-Отрёкшихся, а рядом бродят безмозглые мертвецы, среди которых рассеяны осколки некротического кристалла, разбитого в битве Наксрамаса с Подгородом." } } } },
    ["99e0f1ee"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "На холме к югу от лагеря Легаши разбили палатки эльфы крови из Кель'Таласа." }, { 6.12, "Экспедицию привела волхв Римтори: она выпросила у Орды деньги и охрану под обещание поделиться находками, а затем перебила орочьих воинов и оставила всё найденное себе." }, { 19.57, "Пока Римтори бродит по Азшаре в поисках рун высокорождённых, её магистры сторожат лагерь, и над ним витает запах демонической волшбы." } } } },
    ["9a05ea09"] = { d = 25.0, v = "gnome-male", c = { x = { { 0.00, "План бета – Рудник Ветрорезов:" }, { 1.97, "Я видел, как гоблины используют другой вагончик со взрывчаткой к северу от входа на шахту." }, { 7.77, "Я думаю, поместить заряд эн-джи-пять (красный) там – это хорошая идея." }, { 12.36, "Установив заряд за вагончиком, отойди на какое-то расстояние и нажми на кнопку." }, { 17.46, "Если гоблины не прибегут, чтобы проверить, что случилось, – скорее всего, это потому, что гора обрушилась им на головы." } } } },
    ["9a0d9fd3"] = { d = 25.1, v = "narrator", c = { x = { { 0.00, "Серебряный рудник уходит в холмы к юго-востоку от Гробницы." }, { 4.76, "Магия Аругала дотянулась и сюда: бывший старшина рудника Мрачнон Белёсый обратился в воргена и теперь ведёт стаю таких же тварей в тёмных штольнях." }, { 16.33, "Для Отрёкшихся рудник мог бы стать ценным ресурсом, и Далар Ткач Рассвета не оставил надежды однажды его отвоевать." } } } },
    ["9a1bfcd7"] = { d = 31.0, v = "human-male" },
    ["9a70c4ef"] = { d = 20.3, v = "narrator", c = { x = { { 0.00, "Ущелье Камнепадов — тихая расселина к востоку от Паучьего тракта, ведущая к Пещере Камнепадов." }, { 7.44, "Здесь бродят горные бараны, в скалах попадаются жилы руды, а напротив пещеры темнеет заброшенный грот с бочками и грубыми росписями на стенах, похожими на тауренские." } } } },
    ["9a7f334e"] = { d = 27.9, v = "narrator", c = { x = { { 0.00, "Заледеневшее озеро на западе Дун Морога сковано льдом почти круглый год." }, { 5.73, "Дворфы из Посёлка Пивоваров держат во льду прорубь, чтобы брать пресную воду и рыбачить." }, { 12.68, "Посреди озера лежат два больших острова, но ходить туда не советуют: там хозяйничает стая голодных волков во главе с матёрым воргом." }, { 23.20, "Вдоль замёрзшей реки к северу от озера идёт дорога к Караносу." } } } },
    ["9a8c5d17"] = { d = 33.9, v = "narrator", c = { x = { { 0.00, "Приют Серебряного Ветра — поселение ночных эльфов на юге Ясеневого леса, к северу от озера Мистраль." }, { 7.87, "Это вторая по величине застава Альянса в лесу после Астранаара: здесь есть уютная таверна, наставники охотников, травников и алхимиков, торговцы и часовые." }, { 19.86, "Отсюда часовые следят за дорогой на юг, в Степи, и за озером, элементали которого с недавних пор нападают на всех подряд." }, { 29.12, "Название приюта не обманывает: путников здесь встречают радушно." } } } },
    ["9ac25dec"] = { d = 26.4, v = "narrator", c = { x = { { 0.00, "Семейная усыпальница Агамондов стоит чуть севернее мельниц — самое укреплённое место во всём поместье." }, { 7.97, "Здесь устроил штаб капитан Даргол, скелет на службе Плети." }, { 12.60, "С помощью некромантии он поднял из гробов предков рода Агамондов, и теперь стенающие и гниющие мертвецы набрасываются на всякого, кто войдёт в тёмные пыльные залы без приглашения." } } } },
    ["9ad834cb"] = { d = 23.1, v = "human-male", c = { x = { { 0.00, "Как узнать, что они любят нас?" }, { 2.33, "Некоторым непонятно, как могут Древние Боги и их приспешники любить нас." }, { 7.80, "Не они ли нас убивают?" }, { 9.51, "Не они ли причиняют всем нам боль и страдания?" }, { 12.93, "Разве есть в сердцах таких жестоких существ место любви?" }, { 17.31, "Ответ на эти вопросы очень прост." }, { 19.92, "Так прост, что его излишне даже произносить." } } } },
    ["9ad93fb0"] = { d = 31.5, v = "narrator", c = { x = { { 0.00, "Гоблин Назз Паровой Котёл на самом деле сын богатого гоблина-купца (какого купца?" }, { 6.32, "Ответ на этот вопрос дорогого стоит)." }, { 9.31, "Похоже, что ему больше нравится тратить заработанное семьёй, а не зарабатывать самому." }, { 15.90, "Поэтому он запустил руку в семейную казну и теперь прячется на Мерцающей равнине." }, { 22.22, "Если бы его отец знал, где он скрывается, то наверняка бы нашёл его и отволок домой... отрезав за нахальство палец на ноге." } } } },
    ["9af8c59c"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Орки со всего мира были собраны вместе и помещены в лагеря для военнопленных." }, { 6.12, "Но, хотя с Ордой было покончено, многие сомневались, что мир удастся сохранить надолго." }, { 12.95, "Кадгар, ставший верховным магом, убедил глав Альянса построить Крепость Стражей Пустоты, чтобы охранять руины Тёмного портала и не допустить повторного вторжения из Дренора." } } } },
    ["9b13ba3f"] = { d = 25.3, v = "narrator", c = { x = { { 0.00, "Аран был придворным чародеем и советником короля Азерота." }, { 4.46, "Эгвин соблазнила волшебника и забеременела от него." }, { 8.43, "Ещё не рождённое дитя получило природную способность Ниеласа к магии, что позже определит трагическую судьбу этого ребёнка." }, { 17.84, "Ребёнок также получил силу Тирисфаля, хотя она не проявилась до того, как он стал совершеннолетним." } } } },
    ["9b2308e1"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Паучий тракт — главная дорога юга Когтистых гор, тянущаяся от Малака'джина на север до Мутного озера." }, { 7.97, "Название своё она заслужила честно: по обочинам бродят моховые пауки, а деревья над тропой оплетены их сетями." }, { 16.73, "Тролли Малака'джина жалуются, что по ночам восьминогие твари пробираются к их стоянкам и воруют добычу." }, { 24.84, "От тракта ответвляются тропы в Сиширский каньон и в Ущелье Камнепадов." } } } },
    ["9b27d101"] = { d = 17.5, v = "narrator", c = { x = { { 0.00, "Нечестивые, коварные повелители ужаса обращали друг против друга целые народы, манипулируя их бездумной ненавистью и недоверием друг к другу." }, { 11.63, "Саргерас легко победил Натрезим, но их порча глубоко запала в его душу." } } } },
    ["9b86d117"] = { d = 36.1, v = "orc-male", c = { x = { { 0.00, "Глава один – Линия фронта" }, { 2.22, "Атаковать армию Грозовой Вершины – всё равно что снимать кожицу с луковицы." }, { 8.43, "Чтобы пробраться к сердцевине, нужно сперва разделаться с внешними слоями." }, { 14.57, "Передняя линия обороны, состоящая в основном из горных пехотинцев Грозовой Вершины и Часовых Альянса, связана с Капитанским Укрытием." }, { 25.51, "Снабжает войска и посылает им в случае осады подкрепление Капитан Балинда Каменный Очаг." }, { 32.83, "Срази капитана, и передовые линии падут." } } } },
    ["9ba19460"] = { d = 18.1, v = "narrator", c = { x = { { 0.00, "Гул'дан согласился сделать это и решил, что, как только Азерот будет повержен, он направится на поиски легендарной могилы и получит свою награду." }, { 11.22, "Саргерас, уверенный в том, что Орда будет покорно служить ему, приказал начать вторжение." } } } },
    ["9be353f8"] = { d = 21.0, v = "human-male", c = { x = { { 0.00, "Но он был прав." }, { 1.19, "Мы обречены." }, { 2.23, "Род Агамондов прервётся." }, { 4.16, "Несмотря на то что я всё ещё жив, скоро я погибну." }, { 8.18, "Я не боюсь, и не сожалею о том, что остался со своей семьёй." }, { 13.01, "Но мои последние мысли – о тебе." }, { 15.77, "Продолжай жить, моя возлюбленная Иветта, и я обрету покой." }, { 20.60, "Турман" } } } },
    ["9be7f7ec"] = { d = 35.8, v = "orc-male", c = { x = { { 0.00, "Завершение ритуала" }, { 1.56, "Ход ритуала можно проследить по волшебным рунам на краю круга." }, { 6.77, "Когда там проступят девять рун, ритуал полностью завершится, и ты увидишь, как из заряженного Круга исходит энергия." }, { 16.29, "Затем ты сможешь использовать Ксоротианские Иероглифы, чтобы открыть портал в Ксорот и вывести через него коня погибели." }, { 26.33, "Победи коня и выпусти его дух." }, { 28.93, "Одержи победу над духом, и тогда он будет порабощён, а ты узнаешь секрет его призыва." } } } },
    ["9bf60938"] = { d = 68.1, v = "narrator", c = { x = { { 0.00, "Пустоши — серая мёртвая земля на западе Калимдора." }, { 4.30, "Когда-то здесь зеленела степь, но пробудившаяся от долгого сна принцесса Терадрас выпила из неё жизнь, и таурены назвали этот край Пустошами." }, { 16.04, "От её союза с Зейтаром, первенцем Кенария, родились кентавры; первые ханы — Колк, Гелк, Магра, Мародос и Венг — дали начало племенам, воюющим друг с другом и со всеми пришлыми." }, { 30.93, "Из пепла торчат кости кодо и мёртвые деревья, а над равниной вечно висят грозовые тучи." }, { 38.46, "В руинах высокорождённых, разбитых Великим Расколом, поселились сатиры и наги, а культ Пылающего Клинка открывает порталы для демонов." }, { 49.74, "Альянс держится на Высоте Найджела, Орда — в Деревне Ночных Охотников, и обе стороны ищут союзников среди племён Маграм и Гелкис." }, { 60.87, "А в западных каньонах лежит Мародон — осквернённая гробница Зейтара, святыня кентавров." } } } },
    ["9bfc3257"] = { d = 32.6, v = "narrator", c = { x = { { 0.00, "Бухта Фальдира — небольшая природная гавань на южном берегу нагорья, неподалёку от Стромгарда и подводного рифа." }, { 8.26, "По преданию, она названа в честь Фальдира, который отсюда вместе со своими сподвижниками отплыл через море, чтобы основать королевство Штормград." }, { 19.06, "Ныне в бухте стоит на якоре единственный уцелевший корабль пиратов Черноводья, а на берегу раскинулся лагерь его команды." }, { 28.12, "Наги с рифа управляют приливами и не выпускают моряков в море." } } } },
    ["9c2eb823"] = { d = 24.9, v = "narrator", c = { x = { { 0.00, "Горы Штормграда – скалистая гряда, что замыкает Элвиннский лес с севера и тянется к самой столице, отделяя лес от Пылающих степей и Чёрной горы." }, { 11.67, "Здесь не селятся люди: лишь снега, крутые склоны да орлы над обрывами." }, { 17.40, "Из-за этих гор в Элвинн не пробраться иначе, как через перевалы и дороги, охраняемые стражей." } } } },
    ["9c3006d0"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Врата Драконьей Пасти — подступы к Грим Батолу на юго-востоке Болотины." }, { 5.52, "У подножия горной дороги орки клана Драконьей Пасти держат укреплённую стоянку, откуда мечтают вернуть утраченную крепость, но выше по склону путь стерегут красные драконы и их отродья, не пропускающие никого к запечатанным вратам." }, { 23.17, "Это самое опасное место в Болотине, и дозорные из гавани советуют обходить его стороной." } } } },
    ["9c50b3e0"] = { d = 40.6, v = "narrator", c = { x = { { 0.00, "Пиратская бухта — гоблинский портовый город, вырубленный в утёсах вокруг лагуны на южной оконечности долины." }, { 8.44, "Путник входит в город через выбеленные челюсти исполинской акулы и попадает в лабиринт деревянных настилов, таверн и лавок над водой." }, { 18.91, "Городом правит барон Ревилгаз, а порядок держат Разбойники Черноводья — пираты, которые убивают лишь по необходимости." }, { 28.12, "Порт открыт для всех, кто платит, и отсюда ходят корабли в Кабестан." }, { 33.40, "Но жизнь здесь дешева, доверять никому нельзя, а над городом нависает угроза Кровавого Паруса." } } } },
    ["9c6399a4"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Туннель Когтя — извилистый проход в горах на юге Ясеневого леса, к западу от озера Мистраль." }, { 7.45, "Он ведёт из лесной чащи к Утёсу Ветрорезов в Когтистых горах, где среди штормовых каньонов гнездятся гарпии." }, { 15.98, "В туннеле много тупиков и странных дыр в стенах, но не живёт никто — ни друзей, ни врагов здесь не встретишь, и это единственный путь для тех, кто идёт из леса к Пику Каменного Когтя." } } } },
    ["9ca6275f"] = { d = 18.2, v = "narrator", c = { x = { { 0.00, "Руины Зуулдая стоят на северной части западного побережья, над Пустынным берегом." }, { 6.49, "Некогда здесь жили Гурубаши, а теперь среди камней хозяйничают тролли Кровавого Скальпа." }, { 13.54, "Отсюда тропа ведёт на восток, к Зул'Кунде, сердцу их племени." } } } },
    ["9ca9fa0c"] = { d = 7.7, v = "narrator", c = { x = { { 0.00, "Не дай этой информации попасть в руки врага!" }, { 3.88, "Дальше страница испещрена нулями и единицами." } } } },
    ["9ccc88a7"] = { d = 36.4, v = "narrator", c = { x = { { 0.00, "Чудовищные магические штормы, вызванные скапливающейся энергией портала, начали разрывать опустошённый мир на части." }, { 8.72, "Нер'зул, за которым пошли лишь самые преданные его слуги, смог убежать через один такой портал, пока Кадгар отчаянно сражался, чтобы вернуть своих товарищей в Азерот." }, { 21.64, "Поняв, что они окажутся в ловушке в этом гибнущем мире, Кадгар и его спутники приняли самоотверженное решение уничтожить Тёмный портал, чтобы Азерот не пострадал от кошмарного разрушения Дренора." } } } },
    ["9ce5a069"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Слёзы Далсона — заброшенная ферма в самом сердце Чумных земель." }, { 5.24, "Когда-то здесь был фруктовый сад, но Плеть поставила посреди поля чумной котёл, и теперь его охраняют Хранитель котла, гниющие трупы и ходячие мертвецы." }, { 17.64, "Хозяева фермы так и не покинули её: миссис Далсон бродит по двору скелетом, а фермер Далсон заперт где-то в постройках и давно уже не человек." }, { 29.37, "В доме ещё сохранились её дневник и запертый шкаф." } } } },
    ["9cee5721"] = { d = 64.9, v = "narrator", c = { x = { { 0.00, "Тысяча Игл — огромный сухой каньон на юге Калимдора, между Степями, Фераласом и Танарисом." }, { 7.26, "До Раскола здесь текла река, и её воды выточили из песчаника десятки огромных столбов; потом земля вздыбилась, вода ушла, и остались лишь иглы, торчащие со дна ущелья, будто каменный лес." }, { 22.20, "По их вершинам протянуты верёвочные мосты — так таурены пересекают каньон, не спускаясь на дно, где рыщут кентавры племени Галак." }, { 32.34, "Таурены Орды держат Заставу Вольного Ветра на высокой столовой горе, а их мятежные сородичи из племени Зловещего Тотема засели на Пике Тёмного Облака." }, { 44.41, "На западе, в Скальном гнездовье, гнездятся виверны, в южных ущельях кричат гарпии, в пещерах роются кобольды." }, { 53.18, "На востоке каньон раскрывается в Мерцающую равнину — слепящую соляную пустошь, где гоблины и гномы день за днём выясняют на гонках, чей болид быстрее." } } } },
    ["9cffd6dd"] = { d = 8.2, v = "narrator", c = { x = { { 0.00, "Этот знак брони можно обменять на изделие из кожи или ткани у Тимберлейнов на Лесопилке Восточной долины." } } } },
    ["9d0c5313"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "В то время как жители Азерота и Орда бились друг с другом по всему королевству, внутри обеих армий разгорались конфликты." }, { 8.94, "Король Ллейн, убеждённый в том, что звероподобные орки не в состоянии завоевать Азерот, упрямо отказывался покидать столицу Штормграда; Лотар же был уверен, что бой следует перенести на территорию, занятую противником, так что ему пришлось выбирать между своими убеждениями и верностью королю." } } } },
    ["9d4c709e"] = { d = 34.5, v = "nightelf-male", c = { x = { { 0.00, "Не все фурболги подверглись порче." }, { 2.60, "Некоторые ещё живы и стараются защитить лес." }, { 5.95, "Когда пришла порча, некоторые фурболги спаслись бегством, многие были убиты, а других изгнали из кланов." }, { 14.03, "Я нашёл почтенного фурболга из клана Гиблой Чащи, живущего над озером Мистраль, – его зовут Кролг." }, { 21.49, "Я наблюдал за ним несколько дней, и мне кажется, что, приблизившись к нему в обличье фурболга, я мог бы помочь ему и найти способ снова установить связь между нашими народами." } } } },
    ["9d704fd9"] = { d = 34.8, v = "narrator", c = { x = { { 0.00, "Шлаковая Яма — подземный рудник в глубине Котлована, богатый рудой." }, { 5.30, "Работают здесь невольники под плетьми рабовладельцев и надсмотрщиков Чёрного Железа, а в лавовых озёрах нижних штолен водятся прожорливые огненные ящеры." }, { 16.95, "Командует рудником перебежчик из Братства Тория, которого клан поставил надзирателем, и Братство назначило награду за его голову." }, { 26.93, "В самом низу, у алтаря Сунтары, порабощённые археологи Стальгорна собирают что-то по воле новых хозяев." } } } },
    ["9d878ca7"] = { d = 17.9, v = "narrator", c = { x = { { 0.00, "Алекстраза Связующая Жизнь опустила в источник зачарованный жёлудь." }, { 5.54, "Пробуждённый могущественными водами, он вырос в огромное дерево, корни которого тянулись в самые недра Источника, а крона, казалось, достигала небес." } } } },
    ["9dbc89bd"] = { d = 23.2, v = "human-male", c = { x = { { 0.00, "О нежити в Брилле." }, { 1.28, "Капитан Вакон, похоже, что передвижения нежити около северной башни возросли." }, { 6.56, "Эти поползновения должны быть быстро и решительно подавлены." }, { 10.63, "Капитан Мелроуз, меня беспокоит уровень организованности нежити около границ с Чумными землями." }, { 17.13, "Новая группа солдат будет доставлена в ваше распоряжение в ближайшие недели." }, { 22.35, "Хвала Свету!" } } } },
    ["9df28b4b"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Лесопилка Северного Кряжа стоит у самой границы Дольного Очага и снабжает лесом Алый орден." }, { 7.60, "Здесь ещё сохранились живые деревья, а на дворе не смолкают пилы." }, { 12.87, "Крестоносцы дорожат этим местом, и потому Серебряный Рассвет ищет способы лишить их запасов древесины." } } } },
    ["9e35aabc"] = { d = 36.9, v = "narrator", c = { x = { { 0.00, "Бескрайний берег тянется вдоль всего западного побережья края — один из самых длинных пляжей Азерота." }, { 8.43, "Тишина здесь обманчива: песок кишит мурлоками, а среди них появляется и Старый Мрачноглаз, которого боятся даже сородичи." }, { 18.41, "У кромки воды лежат обломки разбитых кораблей, и говорят, что у ржавого якоря зарыт сундучок покойного капитана Сандерса." }, { 28.46, "На дальнем юго-западе одиноко стоит ферма Дафны Стилвелл, а над южной оконечностью берега светит маяк." } } } },
    ["9e4817e3"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Форт Зорам'гар — небольшая застава Орды на южном конце Зорамского взморья, единственный оплот Орды на западном побережье леса." }, { 10.10, "Орда поставила её недавно, и ей постоянно нужны новобранцы: с моря заставу атакует гидра Ворша Хлестунья, в честь которой наги жгут огонь на жаровне на прибрежном острове." }, { 23.72, "Здесь стоят орк Муглаш, готовый выйти против гидры, тролль Марукайя, платящая за головы наг, и шаман Дже'неу Санкри, следящий за Сумеречным Молотом в Непроглядной Пучине." } } } },
    ["9e615870"] = { d = 28.4, v = "narrator", c = { x = { { 0.00, "Выжженная долина — продуваемая ветрами лощина на северо-востоке ущелья, ведущая к воротам Подгорной тропы и дальше, в Лок Модан." }, { 9.89, "У верхнего конца долины разбит лагерь дворфов Чёрного Железа: отсюда клан следит за запертыми воротами и за всеми, кто спускается из Лок Модана в ущелье." }, { 21.57, "По склонам бродят боевые големы и элементали пламени, а ветер несёт по долине пыль и пепел." } } } },
    ["9e680ed9"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Прииск на Золотом Берегу — старый золотой карьер неподалёку от побережья, к западу от башни на Сторожевом холме." }, { 8.09, "Он приносил королевству неплохой доход, пока край не пришёл в упадок." }, { 13.04, "Сейчас карьер занят Братством Справедливости: здесь бесчинствуют погромщики и мошенники Братства, и Народное ополчение считает это место одним из главных их гнёзд." } } } },
    ["9ea73b80"] = { d = 24.0, v = "narrator", c = { x = { { 0.00, "Кил'джеден бросил в Азерот через иные измерения глыбу льда, и она упала на континенте Нордскол, принеся в наш мир великое зло." }, { 10.28, "Нер'зул исчез навсегда, вместо него там образовался Ледяной Трон, средоточие ненависти." }, { 17.40, "Некогда уважаемый предводитель шаманов стал невероятно могущественным королём-личом." } } } },
    ["9eb026a9"] = { d = 27.4, v = "dwarf-male", c = { x = { { 0.00, "В последующие годы, после того как Штормград обманул братство Каменщиков, сэр Эрлгедин разочаровался в аристократии Королевства." }, { 9.04, "Он больше не хотел принадлежать к Благородным Домам, хотя право это унаследовал от отца." }, { 15.39, "Но не будем отвлекаться." }, { 17.12, "Моё повествование не политический трактат и не биография." }, { 21.09, "Я всего лишь делюсь опытом участия в большой охоте среди зелёных холмов Тернистой долины." } } } },
    ["9eb90f3d"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "Армии Чёрного Железа атаковали крепости своих собратьев и практически захватили оба королевства." }, { 7.38, "Но Мадоран Бронзобород в конце концов привёл свой клан к окончательной победе над колдовской армией Тауриссана." }, { 15.73, "Тауриссан и его слуги бежали в свой безопасный город, не зная о том, что происходило в Грим Батоле, где армия Модгуд тоже не особо успешно сражалась с Кардросом и его воинами из клана Громового Молота." } } } },
    ["9ebbbb39"] = { d = 46.6, v = "human-male", c = { x = { { 0.00, "День один:" }, { 0.78, "С шести до одиннадцати утра – верхний лагерь" }, { 4.02, "С одиннадцати до одиннадцати тридцати утра – перерыв, обед" }, { 8.23, "С одиннадцати тридцати утра до четырёх дня – проход через каньон" }, { 12.83, "С четырёх дня до семи тридцати вечера – верхний лагерь" }, { 16.72, "День два:" }, { 17.37, "То же расписание, что в день один" }, { 19.70, "День три:" }, { 20.35, "То же расписание" }, { 21.51, "День четыре:" }, { 22.42, "То же расписание, с одним исключением." }, { 25.14, "Перед самым закатом Торсен приказал мне прикрыть его, пока он пробирался по проходу через каньон." }, { 32.27, "Ну, думаю, отправился встречаться с нашими агентами." }, { 36.03, "Но он вернулся через час." }, { 37.84, "Это меня удивило." }, { 39.20, "Я-то думаю: сейчас встретится с нашими агентами, снова присоединится к Курцену..." }, { 45.10, "Но что-то пошло не так." } } } },
    ["9ed11fb6"] = { d = 16.2, v = "narrator", c = { x = { { 0.00, "Козни нежити на земле Азерота начались не с падения принца Артаса, они начались задолго до того, как и события, вызвавшие падение Лордерона." }, { 10.85, "Началом всему послужило пришествие орочьих кланов и Пылающего Легиона." } } } },
    ["9f83003a"] = { d = 24.2, g = 1, v = "gnome-male", c = { m = { { 0.00, "ВНИМАНИЕ:" }, { 0.74, "Ничего не говори!" }, { 2.08, "Не оглядывайся!" }, { 3.22, "За тобой могут следить." }, { 5.02, "Меня зовут Аламар Гримм." }, { 6.90, "Я обучаю тех, кого интересует мудрость и сила из… из других миров." }, { 11.86, "Меня попросили связаться с тобой и предложить тебе услуги учителя." }, { 16.88, "Когда будешь готов, ищи меня на задворках Старой Наковальни." }, { 21.51, "-Аламар Гримм, наставник чернокнижников" } }, f = { { 0.00, "ВНИМАНИЕ:" }, { 0.73, "Ничего не говори!" }, { 2.06, "Не оглядывайся!" }, { 3.20, "За тобой могут следить." }, { 4.99, "Меня зовут Аламар Гримм." }, { 6.86, "Я обучаю тех, кого интересует мудрость и сила из… из других миров." }, { 11.79, "Меня попросили связаться с тобой и предложить тебе услуги учителя." }, { 16.78, "Когда будешь готова, ищи меня на задворках Старой Наковальни." }, { 21.44, "-Аламар Гримм, наставник чернокнижников" } } } },
    ["9fcea13e"] = { d = 26.0, v = "goblin-male", c = { x = { { 0.00, "Спасибо тебе ещё раз от имени Пастбищ Дымного Леса за твою помощь." }, { 4.74, "Мы не уверены, у кого именно Метцен, и потому определённо стоит проверить обе банды!" }, { 10.67, "Время – деньги, и сейчас нам его очень не хватает." }, { 14.27, "Пожалуйста, постарайся спасти оленя скорее, ведь недооценивать жестокость этих бандитов нельзя." }, { 20.97, "Дальше идут две записки с требованием выкупа, которые мы получили." }, { 25.64, "Удачи…" } } } },
    ["a00d8043"] = { d = 24.8, v = "dwarf-male", c = { x = { { 0.00, "Мы проснулись чуть свет." }, { 1.67, "Барнил занялся приготовлением завтрака." }, { 4.50, "Мне показалось, что мысли Ажек в этот момент были где-то далеко." }, { 9.19, "Впереди нас ждал долгий день и немало опасностей." }, { 12.67, "Нужна была полная сосредоточенность, иначе последствия могли быть печальными." }, { 18.19, "Но Ажек была не в состоянии отвести взгляд от Барнила, занятого мытьём столовых принадлежностей." } } } },
    ["a01e6a26"] = { d = 19.3, v = "narrator", c = { x = { { 0.00, "Оргрим, разгневанный убийством Дуротана, решил освободить Орду от ужасного проклятья и, чтобы стать новым вождём Орды, убил Чернорука, марионетку Гул'дана." }, { 12.61, "Под его твёрдым руководством безжалостная Орда наконец окружила крепость Штормграда." } } } },
    ["a0230f4e"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Стремясь укрепить свою власть над орками, Кил'джеден помог Гул'дану основать тайную секту под названием Совет Теней, чтобы манипулировать кланами и разносить по Дренору слухи о новой колдовской силе." }, { 16.13, "Всё больше орков овладевали искусством наложения чар, и безмятежные просторы Дренора окутывал мрак." }, { 24.04, "Со временем бескрайние степи, служившие домом для орков не одно поколение, поблёкли и превратились в безжизненные пустоши." }, { 33.78, "Энергия демона медленно убивала этот мир." } } } },
    ["a027b07d"] = { d = 17.3, v = "narrator", c = { x = { { 0.00, "Это было невероятно, но орки, некогда считавшиеся самой воинственной расой, ступавшей на земли Азерота, потеряли желание сражаться." }, { 10.59, "Они становились всё более вялыми, чем совершенно сбили с толку предводителей Альянса." } } } },
    ["a036e8d8"] = { d = 20.5, v = "narrator", c = { x = { { 0.00, "Хотя Медив был повержен, Орда по-прежнему брала верх над защитниками Штормграда." }, { 6.35, "Но когда победа была уже у Орды в руках, один из самых могучих вождей орков, Оргрим Молот Рока, стал понимать, насколько изменились некогда миролюбивые кланы, жившие на Дреноре." } } } },
    ["a044be2f"] = { d = 38.8, v = "narrator", c = { x = { { 0.00, "Шепчущий лес — большой лес, запертый в горах на западе Тирисфаля, за Северной скалой и крепостью Бандариона." }, { 8.78, "Чума не пощадила и его: среди деревьев бродят больные олени с оленятами, крысы и одинокий медведь, а в лесном озере обитает неупокоенный ящер." }, { 20.58, "Посреди леса стоит странное кольцо гигантских грибов, над которым висит туман и порой вспыхивает непонятное сияние, а рядом бродит призрачный рыцарь, связанный клятвой." }, { 34.53, "К юго-западу от озера лежат руины деревушки Тенедол." } } } },
    ["a0649ad3"] = { d = 11.0, v = "narrator", c = { x = { { 0.00, "Ареллас Огненный Лист." }, { 1.99, "Главный волшебник Алого ордена." }, { 4.85, "Гражданин Кель'Таласа." }, { 6.83, "Обречён на вечную битву с некромантом Дисальвеном." } } } },
    ["a0a5761e"] = { d = 19.2, v = "narrator", c = { x = { { 0.00, "И вождь Вар'газул, который находился в безопасности за горами, в Зул'Гурубе, спустился в джунгли и обнаружил, что его народа больше нет." }, { 11.09, "И он пришёл в отчаяние, так как его мечты о завоеваниях потерпели крах." }, { 16.82, "А Мин'лота-Змея так и не нашли." } } } },
    ["a0d3a94d"] = { d = 18.8, v = "narrator", c = { x = { { 0.00, "Получив могущество, пять Аспектов были уполномочены охранять мир в отсутствие титанов." }, { 6.90, "Оставив драконов, готовых защищать их творение, титаны покинули Азерот навеки." }, { 13.29, "К сожалению, Саргерас очень быстро узнал о существовании нового мира…" } } } },
    ["a0e2f558"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "На юго-западе Хиджала, в укромной долине, лежит Укрытие Малорна." }, { 5.52, "Малорн — Древний в облике огромного белого оленя, отец Кенария и возлюбленный самой Элуны; таурены зовут его Апа'ро." }, { 15.51, "В Войну Древних он вышел против Пылающего Легиона и погиб от руки Архимонда — того самого демона, чьи кости ныне лежат под Нордрассилом." }, { 27.09, "Место, названное в его честь, друиды берегут как святыню: здесь чтят память Древнего, чья власть над природой перешла к его сыну." } } } },
    ["a0f71cc0"] = { d = 23.3, v = "scourge-male", c = { x = { { 0.00, "Звезда Ксиль'и" }, { 1.29, "Огр в долине Альтерака, Грел'борг Скряга был последним известным владельцем этого камня, по слухам дававшего своему владельцу умение сообщаться с другими мирами." }, { 14.82, "По нашим сведениям, Грел'борг бродит по руинам Альтерака в одноимённых горах в поисках других реликвий." } } } },
    ["a104bc8f"] = { d = 36.5, g = 1, v = "tauren-male", c = { m = { { 0.00, "Во многих племенах способность разговаривать с умершими предками считается очень ценным даром." }, { 8.63, "Но ты, герой, должен помнить, что твой дар не менее ценен." }, { 13.89, "Те, кто говорит с духами, не могут поднять тяжёлое оружие или вытерпеть телесные страдания, причиняемые тайной магией." }, { 24.66, "Ты – можешь." }, { 25.81, "Ты сильный." }, { 26.88, "Я помогу тебе стать ещё сильнее." }, { 29.84, "Ищи меня в Лагере Нараче." }, { 32.31, "-Харутт Громовой Рог, наставник воинов" } }, f = { { 0.00, "Во многих племенах способность разговаривать с умершими предками считается очень ценным даром." }, { 8.78, "Но ты, героиня, должна помнить, что твой дар не менее ценен." }, { 14.31, "Те, кто говорит с духами, не могут поднять тяжёлое оружие или вытерпеть телесные страдания, причиняемые тайной магией." }, { 25.27, "Ты – можешь." }, { 26.44, "Ты сильная." }, { 27.52, "Я помогу тебе стать ещё сильнее." }, { 30.54, "Ищи меня в Лагере Нараче." }, { 33.05, "-Харутт Громовой Рог, наставник воинов" } } } },
    ["a10e5cf9"] = { d = 27.8, v = "narrator", c = { x = { { 0.00, "Западные комбинации кристаллов" }, { 2.50, "Существует два возможных эффекта: один повышает вашу защиту от урона, второй ослабляет защиту противника." }, { 11.19, "КРИСТАЛЛ-ХРАНИТЕЛЬ: Требуются красные и зелёные кристаллы." }, { 15.91, "Повышает вашу характеристику \"броня\"." }, { 19.00, "КРИСТАЛЛ-ГУБИТЕЛЬ: Требуются синие и красные кристаллы." }, { 23.57, "Может снизить характеристику \"броня\" выбранной цели." } } } },
    ["a1189dc1"] = { d = 10.2, v = "narrator", c = { x = { { 0.00, "Инвар Однорукий." }, { 1.43, "Первый предводитель убийц Алого ордена." }, { 4.82, "Гражданин Даларана." }, { 6.48, "Последний раз был замечен на берегах Нордскола." } } } },
    ["a121f897"] = { d = 36.1, v = "narrator", c = { x = { { 0.00, "Крепость Громового Топора — оплот культа Пылающего Клинка на северо-западе: двор, казармы, башни и пещера в скале." }, { 9.22, "Чернокнижники хранят здесь краденое: за красным кристаллом в пещере спрятана Демоническая шкатулка с Рукой Ируксоса, которой открывают порталы демонов на Поле Маннорок, а по слухам, здесь же скрыт Скипетр Света, похищенный у нагов." }, { 27.52, "Сюда ушёл ночной эльф Тиранис, соблазнённый магией демонов, а его сестра Далинда томится в клетке культистов." } } } },
    ["a13f99c5"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Бешеный Воробей: Декларация груза и пассажиров." }, { 4.01, "Двадцать бочонков рома." }, { 6.05, "Пункт назначения: Терамор." }, { 8.24, "Пятьдесят мешков муки." }, { 10.21, "Пункт назначения: Терамор." }, { 12.40, "Два ящика с гномскими инструментами." }, { 15.42, "Пункт назначения: Кабестан." }, { 17.69, "Тридцать рулонов хлопчатой ткани." }, { 20.56, "Пункт назначения: Терамор." }, { 22.76, "Четыре ящика пряностей." }, { 24.80, "Пункт назначения: Терамор." }, { 26.99, "Три пассажира." }, { 28.20, "Пункт назначения: Терамор" } } } },
    ["a1998947"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Руины Балиа'ма стоят на восточном берегу реки, к юго-востоку от лагеря Гром'гол и к юго-западу от холма Мош'Огг." }, { 8.89, "Здесь живут тролли клана Дробителей Черепов, и их охотники за головами стерегут развалины." }, { 15.88, "Джунгли здесь особенно густы, а дорога проходит совсем рядом." } } } },
    ["a1a7d423"] = { d = 29.7, v = "narrator", c = { x = { { 0.00, "Мглистая пещера на северо-западе топей когда-то была небольшой шахтой: у входа до сих пор стоят развалины домиков, где жили рудокопы." }, { 10.31, "Теперь штольни принадлежат громадным паукам, чья паутина затягивает каждый проход, и никто уже не помнит, пещеру ли назвали в честь пауков или пауков в честь пещеры." }, { 23.05, "Только отшельник с Ведьминого холма зачем-то ищет глаза этих тварей для своей похлёбки." } } } },
    ["a1c9ee42"] = { d = 29.0, v = "human-male" },
    ["a23f5ab5"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Река Тондрорил служит естественной границей между Западными и Восточными Чумными землями." }, { 7.38, "Она начинается в закрытых северных горах, у выхода из Туннеля Ужаса, и впадает в озеро Дарроумир на юге." }, { 16.02, "По её берегам ползают личинки, кружат летучие мыши и бродят чумные медведи." }, { 22.29, "У разрушенной фермы на восточном берегу нашёл приют Тирион Фордринг, некогда лорд Марденхольдский, лишённый ордена и изгнанный из Альянса." } } } },
    ["a23fe733"] = { d = 28.7, v = "human-male", c = { x = { { 0.00, "День шесть:" }, { 0.75, "Рано утром Торсен долго говорил с сержантом Йохвой." }, { 4.45, "Мне пришлось притворяться, что сплю, так что подойти поближе мне не удалось." }, { 9.58, "Но я думаю, что они говорили о том, куда ходил Торсен." }, { 13.40, "Я за ним пристально слежу – кстати, Йохва тоже." }, { 16.72, "Позднее Торсена вызвал Дорен." }, { 18.85, "У этих троих какая-то общая тайна." }, { 21.35, "Дорен и Йохва, должно быть, знают, что Торсен встречается с вашими агентами." }, { 26.67, "Он шпионит в пользу мятежников." } } } },
    ["a240f042"] = { d = 17.5, v = "scourge-male", c = { x = { { 0.00, "Отчёт о миссии стражей смерти." }, { 2.68, "Агенты: Ран Йорик, Квинн Йорик, Эрнанд МакКри." }, { 6.79, "Основная цель: произвести рекогносцировку в северном Серебряном бору и определить уровень угрозы от местной фауны и от Плети." } } } },
    ["a25d119b"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Виражи на Миражах — гоночная трасса, проложенная по соляной корке Мерцающей равнины." }, { 6.39, "Её построили гоблин Поззик, некогда один из лучших механиков Нижней шахты, и его вечные соперники — братья-гномы: каждая команда хочет доказать, что её народ строит самые быстрые машины." }, { 20.68, "Гонки ракетных болидов идут здесь день за днём, а пилот гоблинов Раззерик мечтает обогнать гномов на два круга." }, { 29.04, "На трибунах — зеваки из Орды и Альянса, и немало золота ставится на победителя." } } } },
    ["a2a7624d"] = { d = 24.1, v = "narrator", c = { x = { { 0.00, "Молот Зул'Фаррака" }, { 1.40, "Чтобы создать молот Зул'Фаррака, следует отправиться к алтарю Зула и заполучить священный молот, хранящийся у тролля-хранителя." }, { 11.38, "Далее следует принести молот к алтарю в городе троллей Джинта'Алор." }, { 16.72, "Если ударить молотом по алтарю, алтарь наполнит его силой и превратит его в молот Зул'Фаррака." } } } },
    ["a2bab701"] = { d = 13.4, v = "human-male", c = { x = { { 0.00, "Помните, мои братья, когда-то мы были гордыми ремесленниками." }, { 4.57, "Мы будем исполнять наши сегодняшние обязанности с тем же тщанием, что когда-то использовали в нашем ремесле." }, { 12.45, "Эдвин ван Клиф" } } } },
    ["a2d2e5f0"] = { d = 26.9, v = "human-male", c = { x = { { 0.00, "К несчастью, эти вонючие орки, кажется, всерьёз принялись за истребление подданных Его Величества." }, { 7.00, "Две недели назад клан Чёрной Горы устроил безжалостную резню в Приозёрье." }, { 12.13, "Много отважных воинов полегло в тот ужасный день." }, { 15.66, "Орки пошли на штурм с таким напором и яростью, что мост через Озеро Безмолвия был разрушен до основания." }, { 23.04, "Наши запасы истощены." }, { 24.65, "Нечем даже перевязывать раненых." } } } },
    ["a315881f"] = { d = 25.7, v = "narrator", c = { x = { { 0.00, "Руины Южной Луны — древние тролльские развалины на юге Танариса, чуть севернее Долины Стражей." }, { 7.40, "Между обрушенных колонн и статуй расположились огры клана Песчаного Молота, ушедшие сюда из своего поселения." }, { 15.99, "Кто и когда возвёл эти стены, помнят разве что тролли Зул'Фаррака, а гоблины Прибамбасска предпочитают обходить руины стороной." } } } },
    ["a3525def"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Уверенная в том, что её дитя здорово и невредимо, Эгвин отправила юного Медива ко двору Азерота и оставила его там, чтобы его взрастил его смертный отец и его народ." }, { 13.01, "Сама же она ушла в глушь, готовая встретить всё, что её могло ожидать в загробной жизни." }, { 19.87, "Медив вырос сильным пареньком, но не имел никакого представления о потенциальной мощи силы Тирисфаля, принадлежавшей ему по праву рождения." } } } },
    ["a3698f70"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Лощина Суховея — пыльный, обточенный ветром распадок к западу от долины Летлор." }, { 6.56, "Здесь среди камней устроили логово трогги, а по склонам крадутся хищные кошки." }, { 13.05, "Через лощину ветер несёт песок к драконьему каньону, и путники редко задерживаются в её тени." } } } },
    ["a36f1a06"] = { d = 33.2, v = "narrator", c = { x = { { 0.00, "Тралл взял легендарный Молот Рока и надел свои чёрные доспехи; теперь он стал новым предводителем Орды." }, { 8.12, "Следующие несколько месяцев его маленькое неуловимое войско совершало набеги на лагеря военнопленных Альянса; войско Альянса было бессильно против него." }, { 20.31, "Под руководством своего лучшего друга и наставника, Грома Адского Крика, Тралл делал всё возможное, чтобы его народ никогда больше не испытал на себе гнёта рабства." } } } },
    ["a3968620"] = { d = 40.7, g = 1, v = "scourge-male", c = { m = { { 0.00, "С возвращением." }, { 1.33, "Я прекрасно понимаю, что ситуация, в которой ты оказался, несколько шокирует." }, { 7.96, "Тот факт, что тебе удалось продвинуться так далеко, уже делает тебя непохожим на других недавно восставших паладинов." }, { 18.10, "Скоро ты поймёшь, что самая тяжёлая часть твоей новой жизни – понимать, чего ты лишился... и терпеть боль, которую это доставляет." }, { 29.25, "Приходи в Похоронный Звон, и я помогу тебе найти силы, необходимые, чтобы сделать первые шаги." }, { 37.52, "Арамис Хаммерхенд, наставник паладинов" } }, f = { { 0.00, "С возвращением." }, { 1.29, "Я прекрасно понимаю, что ситуация, в которой ты оказалась, несколько шокирует." }, { 7.80, "Тот факт, что тебе удалось продвинуться так далеко, уже делает тебя непохожей на других недавно восставших паладинов." }, { 17.65, "Скоро ты поймёшь, что самая тяжёлая часть твоей новой жизни – понимать, чего ты лишилась... и терпеть боль, которую это доставляет." }, { 28.55, "Приходи в Похоронный Звон, и я помогу тебе найти силы, необходимые, чтобы сделать первые шаги." }, { 36.58, "Арамис Хаммерхенд, наставник паладинов" } } } },
    ["a3a5732f"] = { d = 26.4, v = "narrator", c = { x = { { 0.00, "Шепчущие сады раскинулись на холме к югу от входа в Монастырь Алого ордена." }, { 6.25, "Когда-то здесь произошла большая битва между теми, кто позже стал Алым орденом, и полчищами Плети." }, { 14.34, "Духи павших так и не покинули это место: в сумерках их голоса слышны как тихий шёпот среди деревьев." }, { 22.58, "Ныне сады охраняют разведчики и чародеи ордена." } } } },
    ["a3ac4488"] = { d = 36.7, v = "creature/furbolg", c = { x = { { 0.56, "Найди место силы над владениями Чёрной Вершины, за Паучим лабиринтом." }, { 6.71, "Там навалены черепа врагов и соперников Аррока." }, { 10.94, "Вот туда-то ты и должен воткнуть наконечник с головой Омокка!" }, { 16.37, "Когда голова будет на месте, Аррок точно придёт… но сначала он пришлёт своих приспешников." }, { 24.35, "Убей их – и он придёт сам." }, { 26.58, "Убей Аррока и возьми мою магию обратно." }, { 30.25, "Когда я вновь обрету её, я тебя вознагражу." } } } },
    ["a3b1cb47"] = { d = 27.2, v = "dwarf-male", c = { x = { { 0.00, "Я нашёл способ проникнуть в Чертог Хаз-Мула!" }, { 3.18, "Возьми медальон Гни'кива из моего сундука." }, { 6.30, "Победи трогга Ревлоша в зале перед комнатой с картой и забери у него стержень Тсола." }, { 12.54, "Соедини медальон и стержень – и получишь посох Древнейшей Истории." }, { 17.34, "Используй посох в комнате с картой, чтобы открыть двери, ведущие в чертог Хаз-Мула." }, { 23.45, "Сделай это, и комната будет принадлежать нам!" }, { 26.76, "-Бейлог" } } } },
    ["a3e149bc"] = { d = 33.7, v = "narrator", c = { x = { { 0.00, "Доланаар — тихая деревня ночных эльфов в сердце Тельдрассила, на дороге из Тенистой долины к Дарнассу." }, { 8.35, "Здесь есть таверна, где хозяйничает Кельдамир, и лунный колодец, у которого несёт стражу Коритрас Лунный Гнев." }, { 17.14, "Друиды Атридас Медвежья Шкура и Таллонкай Гибкий Корень отсюда руководят борьбой с обезумевшими фурболгами и сатирами." }, { 26.80, "У обочины ошивается сатир Зенн Грязное Копыто, а к северу чернеет вход в Пещеру Бесов." } } } },
    ["a3f5a820"] = { d = 15.4, v = "dwarf-male", c = { x = { { 0.00, "Гальванизированный рог:" }, { 1.57, "Редкостная твёрдость гальванизированного рога – основа всей детали доспеха, который я намереваюсь создать, так что его тоже надо добыть." }, { 10.98, "Его можно добыть у редких матриархов химер в Обугленной долине." } } } },
    ["a40fe30e"] = { d = 31.0, v = "goblin-male", c = { x = { { 0.00, "Привет и поклон вам, искатели приключений!" }, { 3.01, "Мне, Кринкелю Сталлеру, необходима помощь желающих рискнуть своей жизнью ради выполнения некоторых моих трудных поручений." }, { 11.78, "Поскольку у меня множество обязанностей и я загружен взвалившейся на меня работой, я уверяю, что любому, достаточно смелому, чтобы собрать необходимые предметы из данного списка и принести их мне, будет выплачена солидная премия." }, { 27.98, "Список включает в себя следующие страницы..." } } } },
    ["a41bca2c"] = { d = 28.8, v = "narrator", c = { x = { { 0.00, "Мыс Тернистой долины — южная оконечность джунглей, полуостров, выступающий в Южные моря." }, { 7.24, "На его утёсах стоит Пиратская бухта, к северу от неё лежит Арена Гурубаши, а по берегам разбросаны троллиные руины и песчаные пляжи." }, { 18.10, "Здесь разворачивается противостояние Разбойников Черноводья и пиратов Кровавого Паруса, и здесь же прячутся слуги Занзила Отверженного." } } } },
    ["a43bfed7"] = { d = 19.5, v = "narrator", c = { x = { { 0.00, "Спустя десять тысяч лет могучий демон Архимонд вновь ступил на Азерот." }, { 5.78, "Но в Даларане их путешествие не закончилось." }, { 9.29, "По приказу самого Кил'джедена Архимонд и его демоны последовали за Плетью в Калимдор, чтобы уничтожить Нордрассил, Древо Жизни." } } } },
    ["a4563750"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Врата Альгаза — верхняя часть тоннеля, прорубленного дворфами в северных горах Лок Модана." }, { 6.94, "Отсюда дорога уходит вниз, к Болотине и Гавани Менетилов, единственному порту дворфийских земель." }, { 14.44, "Когда орки клана Драконьей Пасти заняли нижний перевал, горные пехотинцы отступили именно сюда, к верхней части тоннеля, и держат здесь заслон." }, { 25.69, "Путникам советуют не сходить с дороги и не задерживаться." } } } },
    ["a46d2f69"] = { d = 22.8, g = 1, v = "nightelf-male", c = { m = { { 0.00, "Доставил бы это письмо тебе сам, но боюсь отлучиться, поскольку могу пропустить нечто очень важное." }, { 7.95, "Если ты желаешь побольше узнать о моих наблюдениях за Башней Алталакса, знай, что податель сего письма немало мне помог и ему вполне можно доверять." }, { 19.72, "Спешно заканчиваю," }, { 21.21, "Балтул Удар Тени" } }, f = { { 0.00, "Доставил бы это письмо тебе сам, но боюсь отлучиться, поскольку могу пропустить нечто очень важное." }, { 7.96, "Если ты желаешь побольше узнать о моих наблюдениях за Башней Алталакса, знай, что подательница сего письма немало мне помогла и ей вполне можно доверять." }, { 20.04, "Спешно заканчиваю," }, { 21.53, "Балтул Удар Тени" } } } },
    ["a470a0ed"] = { d = 39.0, v = "narrator", c = { x = { { 0.00, "Поместье Чёрного Ворона прячется в восточных горах, и путь к нему ведёт по извилистой тропе через тесную пещеру над крепостью Дарнхольд." }, { 10.73, "Это дом братства убийц Чёрного Ворона: здесь есть свой сад, тренировочная площадка и мастера, обучающие разбойников тонкостям ремесла." }, { 21.17, "Хозяин поместья — лорд, возглавляющий лигу ассасинов; чужаков здесь не любят, а с Синдикатом братство враждует не на жизнь, а на смерть." }, { 31.68, "Оранжевые крыши поместья напоминают, что эти земли когда-то принадлежали королевству Альтерак." } } } },
    ["a48017e0"] = { d = 48.6, v = "narrator", c = { x = { { 0.00, "Теснина Зловещего Шёпота — сеть тоннелей и пропастей на самом юге Зимних Ключей, на склонах, за которыми лежит вершина Хиджала." }, { 10.92, "Воздух здесь тяжёлый и душный, небо темнеет, а из ям поднимаются ядовитые испарения." }, { 18.17, "В теснине засели демоны Пылающего Легиона — остатки войска, штурмовавшего гору Хиджал в Третью войну и бежавшего после гибели Архимонда; ими верховодит демоница Хедерин, чьи слуги источают яд, застывающий в тёмные кристаллы." }, { 37.45, "В одной из пещер прячется бес-торговец экзотическими реагентами, а в глубине ущелья стоит высший эльф, изучающий стихии этого мира." } } } },
    ["a4a27081"] = { d = 28.5, v = "human-male", c = { x = { { 0.00, "Кузнечный молот – до прихода Чумы и предательства Артаса мы жили в деревне Погребальных Костров, в глубине прекрасного Серебряного бора." }, { 9.06, "Теперь леса далеко не так красивы, как были раньше, и крепость, где меня обучали секретам литья стали, давно превратилась в руины, и её наводнили злобные твари." }, { 19.80, "Когда я с женой убежал из этого места, что теперь называется крепостью Тёмного Клыка, мы оставили там некоторые дорогие для нас вещи." } } } },
    ["a4af8f07"] = { d = 31.6, g = 1, v = "nightelf-male", c = { m = { { 0.00, "Как только мне стало известно, что ты готов к обучению, я тотчас же послал тебе знак." }, { 6.76, "Друиды Кенария рады любому пополнению своих рядов." }, { 10.93, "Даже духи становятся сильнее, когда нас больше." }, { 14.82, "Рано или поздно, проявив должное терпение, мы вернём былое величие." }, { 20.28, "Найди меня возле верхушки Альдрассила." }, { 23.45, "Я буду твоим проводником, пока ты живёшь в Тенистой долине." }, { 28.20, "- Мардант Крепкий Дуб, наставник друидов" } }, f = { { 0.00, "Как только мне стало известно, что ты готова к обучению, я тотчас же послал тебе знак." }, { 6.89, "Друиды Кенария рады любому пополнению своих рядов." }, { 11.09, "Даже духи становятся сильнее, когда нас больше." }, { 15.01, "Рано или поздно, проявив должное терпение, мы вернём былое величие." }, { 20.52, "Найди меня возле верхушки Альдрассила." }, { 23.71, "Я буду твоим проводником, пока ты живёшь в Тенистой долине." }, { 28.49, "- Мардант Крепкий Дуб, наставник друидов" } } } },
    ["a4b58164"] = { d = 37.4, v = "skyborne-male" },
    ["a4ca93e5"] = { d = 27.8, v = "narrator", c = { x = { { 0.00, "Озеро Зеркало Небес лежит на юго-востоке от Астранаара, к югу от Аванпоста Среброкрылых." }, { 7.03, "Это небольшое тихое озеро с островком посередине, и раньше ночные эльфы собирали на его берегах лунный камень." }, { 15.91, "Но потом сюда пришли чащобники — ожившие древесные твари, и их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и укрыл их на острове." } } } },
    ["a4cf6413"] = { d = 21.7, v = "narrator", c = { x = { { 0.00, "Ниже приведён список учеников, получивших Платиновую звезду в школе горного дела и геодезии Брока и заработавших Почётную шахтную кирку:" }, { 12.40, "Мелия Потрясательница Камней." }, { 15.11, "Бардин Железняк." }, { 16.67, "Юми Триггервольт." }, { 18.31, "Руми Триггервольт." }, { 20.04, "Ворел Стальной Шип." } } } },
    ["a4f89aba"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Иллидан согласился и тотчас отправился на поиски Ледяного Трона, чтобы уничтожить этот ледяной сосуд, в котором хранилась душа Короля-лича." }, { 10.99, "Иллидан знал, что для этого ему понадобится могущественный артефакт." }, { 16.24, "Использовав знания, перешедшие к нему с воспоминаниями Гул'дана, Иллидан отправился к Гробнице Саргераса за останками Титана Мрака." } } } },
    ["a4fc07e7"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "Морлос'Аран — руины на южной окраине леса, к востоку от дороги." }, { 5.16, "Задолго до Великого Раскола здесь стоял большой город ночных эльфов, такой же, как Амет'Аран и Башал'Аран на Тёмных берегах или Ордил'Аран в Ясеневом лесу." }, { 17.67, "От него остались лишь колонны и разбитые арки среди больных деревьев — напоминание о золотом веке, который ушёл десять тысяч лет назад." }, { 28.65, "Теперь среди камней бродят медведи злобных когтей и волки-сквернолапы." } } } },
    ["a52aa118"] = { d = 41.8, v = "narrator", c = { x = { { 0.00, "Перекрёсток Корина лежит в сердце южных равнин, между Чумным оврагом и озером Мерельдар, там, где сходятся дороги на Андорал, Дарроушир, Стратхольм и Длань Тира." }, { 13.54, "Некогда оживлённый городок с ратушей и кузницей теперь до краёв полон нежити: вурдалаки, банши, сшитые из плоти чудовища и наставники Культа Проклятых." }, { 26.25, "Даже тем, кто умеет ходить в тени, здесь не спрятаться — незримые слуги Плети видят всё." }, { 33.70, "Именно близ перекрёстка агенты Серебряного Рассвета когда-то подобрали израненного Карлина Редпата." } } } },
    ["a556953d"] = { d = 29.4, v = "named/thrall", c = { x = { { 0.00, "Эти демонические доспехи носил демон, поразивший наш народ проклятием кровожадности." }, { 7.32, "Благодаря геройскому поступку одного храброго орка он был побеждён." }, { 13.08, "Нет больше Маннорота Разрушителя." }, { 15.97, "Да послужат эти доспехи напоминанием нам о том, как глубоко мы пали и как отчаянно мы сражались за то, чтобы вновь обрести наше доброе имя." }, { 27.88, "- Тралл, Вождь Орды" } } } },
    ["a5587bcc"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "Пещеры на северо-восточном берегу озера заняли огры клана Мо'грош." }, { 5.12, "Среди старых руин они устроили курганы и ходят оттуда в набеги на Телсамар, Каменную Плотину и раскопки." }, { 13.08, "Возглавляет их Чок'сул, за голову которого магистрат Телсамара назначил награду." }, { 19.07, "Подкрепление из Стальгорна придёт нескоро, поэтому городу приходится надеяться на наёмников и странствующих искателей приключений." }, { 28.58, "У огров находят и странные кристаллы, которые они добывают в своих пещерах." } } } },
    ["a5592c83"] = { d = 29.0, v = "human-male", c = { x = { { 0.00, "Мне, наконец, удалось найти кое-какие сведения о солдате, с которым ты сражался." }, { 5.62, "Его родословная сохранилась очень плохо, так что мне пришлось постараться." }, { 10.75, "Представляешь, что выяснилось: управляющий Ален в часовне Последней Надежды, оказывается, сын Кристофа!" }, { 17.81, "Ты можешь облегчить его боль, если расскажешь, что случилось с его отцом." }, { 22.93, "Так что, если будешь на службе у Серебряного Рассвета, поговори с ним." }, { 27.75, "Сделай доброе дело." } } } },
    ["a591aa17"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Высокорождённые, или Кель'дорай, как их ранее называла Азшара, в конце концов достигли берегов восточных земель, которые люди позднее назовут Лордерон." }, { 12.20, "Они планировали создать своё собственное королевство магов, Кель'Талас, и отречься от поклонения луне и от ночного образа жизни, свойственных ночным эльфам." }, { 24.76, "С тех пор и вовеки они станут поклоняться солнцу и будут известны как высшие эльфы." } } } },
    ["a59a7eac"] = { d = 35.5, v = "narrator", c = { x = { { 0.00, "Арена Гурубаши стоит к северу от Пиратской бухты — древнее ристалище империи троллей, пережившее её гибель." }, { 8.63, "В старину бои здесь шли до смерти, и песок арены пропитан кровью." }, { 13.88, "Ныне пираты устроили здесь забаву: раз в несколько часов распорядитель, Коротышка Джон Мифрил, бросает в центр арены сундук с добычей, и за него сражаются все против всех." }, { 27.40, "Старые истории предупреждают: кто найдёт в полночь кроваво-красный амулет, того к рассвету сожрёт демон." } } } },
    ["a5b03de4"] = { d = 24.9, v = "human-female", c = { x = { { 0.00, "В дополнение к крови в камень были вплавлены силы стихий." }, { 4.56, "Огонь, вода, гром и камни были перемешаны с кровью (но всё же, с чьей кровью?), и несмотря на то, что эта смесь была внешне инертна, все эти силы внутри неё бушевали в неистовом противостоянии." }, { 19.42, "Столь много вопросов возникло об этом поразительном, знаковом материале." } } } },
    ["a5c0528c"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Руины Исильдиэна — остатки большого города ночных эльфов на юго-западе Фераласа, в глубине Высокогорных дебрей." }, { 8.74, "Город погиб десять тысяч лет назад, во время Раскола, и с тех пор джунгли поглотили его улицы." }, { 16.22, "Круглое здание в конце лестницы, похожее на Храм Луны, когда-то, возможно, было святилищем Элуны." }, { 23.91, "Ныне руины — вотчина огров Гордунни, устроивших здесь стойбище, а в пещере на восточном краю развалин они устроили себе логово." } } } },
    ["a5cfb871"] = { d = 29.4, v = "dwarf-male", c = { x = { { 0.00, "День шестой." }, { 0.89, "Гералату становится хуже." }, { 2.75, "Сегодня он открыл глаза лишь однажды." }, { 5.43, "Говорил он, превозмогая боль, но вполне ясно." }, { 8.62, "Если мне удастся избежать зловещей судьбы в Лабиринтах Иглошкурых, я должен буду передать Хранителю дорог Фалфинделу в Таланаар, что Чарлга Остробок собирает своих приспешников в южных Степях." }, { 22.29, "Его мощь крепнет с каждым днём." }, { 24.52, "Эту ведьму нужно остановить, пока зло не вышло за пределы Лабиринтов." } } } },
    ["a5d2d5b5"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Южный Золотой Путь — продолжение великого тракта за Лагерем Таурахо." }, { 5.64, "Дорога идёт через Поля Великанов мимо стад кодо и грозовых ящеров, минует поворот на Мулгор и спускается на юг, к Великому Подъёмнику." }, { 16.63, "Охраняют её куда хуже северного отрезка: сторожевые башни у обочины стоят заброшенными, а свинобразы всё чаще выходят на дорогу." }, { 27.25, "И всё же именно по ней таурены и орки идут в Тысячу Игл и Пылевые топи." } } } },
    ["a5df6b98"] = { d = 23.1, v = "skyborne-male" },
    ["a5e21cb6"] = { d = 35.0, v = "human-female", c = { x = { { 0.00, "Вот что произнёс Кеган, когда протягивал мне свою подвеску Кровавого камня, и был страх и, может быть, благоговение в его глазах, когда он делал это." }, { 10.82, "Когда его рука встретилась с моей, он замешкался, будто не желая расставаться с подвеской." }, { 17.49, "Я содрогнулась от отвращения и по сей день не знаю, из-за того ли, что я ощутила касание его мёртвой плоти, или это подвеска заставила меня поёжиться." }, { 28.38, "Ибо я почувствовала в ней силу." }, { 30.68, "Глубокую, скрытую, ненасытную силу." }, { 33.32, "И острую жажду свободы." } } } },
    ["a6161038"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Берег Южного прилива — юго-западное побережье Серебряного бора, длинная полоса берега вдоль Великого моря." }, { 8.69, "Она тянется от северных пляжей до самой Стены Седогрива, за которой начинается закрытый Гилнеас." }, { 16.52, "Здесь тихо: лишь шум прибоя, серые сосны над обрывом и звери, спускающиеся к воде." } } } },
    ["a65a5691"] = { d = 61.7, v = "narrator", c = { x = { { 0.00, "Лунная поляна — укромная долина в горах северного Калимдора, между Осквернённым лесом и Зимними Ключами." }, { 8.14, "По суше сюда ведут лишь туннели фурболгов-Древобрюхов, и чужаки редко находят дорогу в это святилище друидов." }, { 16.77, "В древности здесь обитал полубог Кенарий, и по сей день Лунная поляна остаётся домом Круга Кенария: ночные эльфы и таурены вместе служат природе, и вражда Альянса с Ордой не имеет здесь силы." }, { 31.65, "Посреди долины лежит озеро Элуне'ара, на его берегу стоит селение Ночная Гавань, а на северо-востоке — кельи, где в Изумрудном Сне спит Малфурион Ярость Бури." }, { 44.07, "Стражем Лунной поляны служит хранитель Ремул, сын Кенария." }, { 48.71, "Раз в год друиды открывают долину всем народам: на Лунный фестиваль сюда съезжаются праздновать древнюю победу над Легионом, а из глубин озера поднимается безумный Омен." } } } },
    ["a664c5e1"] = { d = 15.1, v = "narrator", c = { x = { { 0.00, "Скала Мантия — одна из каменных глыб Мулгора, каких немало в этой долине." }, { 6.07, "Такие скалы поднимаются над травой, как молчаливые стражи, и служат ориентирами охотникам и кочующим стадам кодо." } } } },
    ["a670b04d"] = { d = 40.0, v = "narrator", c = { x = { { 0.00, "Лордамерские выселки стоят на холме над берегом озера, неподалёку от купола Даларана." }, { 6.69, "После Второй войны здесь держали пленных орков, а теперь лагерь охраняют щитоносцы и теурги Даларана, и его стены служат тюрьмой и лабораторией разом." }, { 18.39, "Сюда угодила небольшая группа нежити во главе с Кеганом Мракмаром — беглецы из Подгорода, которых Отрёкшиеся считают предателями." }, { 28.28, "Стражница лагеря изучает загадочные кровавые подвески, принесённые пленниками, а часовые на вышках зорко следят за дорогой: гостей с севера здесь не жалуют." } } } },
    ["a684a3bf"] = { d = 22.9, v = "narrator", c = { x = { { 0.00, "Когда наши побратимы уходят В мир иной, потусторонний, Душа застывает В глубине подземелий долины." }, { 8.74, "Когда наши побратимы уходят В Храм Горы, Мы на защиту встаём их духу, Сокрытому в святом синем кристалле." }, { 18.03, "Когда наши побратимы уходят, Восходит Луна над долиной." } } } },
    ["a6861663"] = { d = 14.7, v = "narrator", c = { x = { { 0.00, "Гряда на горизонте — один из хребтов, замыкающих Мулгор со всех сторон." }, { 5.76, "Здесь нет поселений — только ветер, камень, редкие сосны на склонах и тропы зверей, спускающихся к траве равнин." } } } },
    ["a68953aa"] = { d = 18.0, v = "narrator", c = { x = { { 0.00, "Кенарий научил детей земли разговаривать с деревьями и травами." }, { 5.13, "Шу'хало стали друидами и совершили множество чудес, приносящих земле здоровье." }, { 11.50, "Многие поколения Шу'хало охотились вместе с Кенарием и хранили землю от тёмных сил." } } } },
    ["a693c1f5"] = { d = 21.9, v = "narrator", c = { x = { { 0.00, "Сторожка у заснеженной сосны — одинокий домик среди сосен в центральной части Дун Морога." }, { 6.94, "Он стоит в стороне от дороги, и снег вокруг него редко тревожат чужие следы." }, { 12.91, "В последнее время здесь держит пост посланник ордена Серебряного Рассвета, следящий за далёкими вестями с чумных земель." } } } },
    ["a6afc94b"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "У южного берега нагорья, на подводном рифе, лежат обломки двух кораблей пиратов Черноводья." }, { 7.04, "Экспедиция шла сюда за эльфийскими сокровищами, но у самой бухты Фальдира на неё обрушился внезапный прилив, и два судна из трёх пошли ко дну." }, { 17.75, "Теперь среди разбитых корпусов и рваных парусов хозяйничают наги, а в трюмах ещё хранятся судовые журналы погибших кораблей." } } } },
    ["a6b13400"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "В последней отчаянной попытке Молот Рока и его командиры храбро ринулись в атаку с Пика и схлестнулись с паладинами Лотара прямо посреди Пылающих степей." }, { 12.11, "Молот Рока и Лотар сошлись в яростном бою, который изрядно измотал обоих могучих бойцов." }, { 19.21, "И хотя Оргрим в итоге смог одолеть Лотара, смерть прославленного героя не возымела того эффекта, на который надеялся орочий вождь." } } } },
    ["a6c5123e"] = { d = 26.2, v = "human-male", c = { x = { { 0.00, "Боюсь, мой отец сделал огромную ошибку, решившись остаться и защищать наш дом." }, { 5.45, "Силы Плети свирепствуют в Тирисфальских лесах, и несмотря на то что мы достаточно укреплены и у нас хватает запасов, после предательства моего брата Девлина у нас не хватает сил и рук, чтобы противостоять их постоянным атакам." }, { 20.92, "Когда ты получишь моё письмо, Иветта, то будешь знать, что Девлин – предатель." } } } },
    ["a70d9966"] = { d = 19.8, v = "human-male", c = { x = { { 0.00, "*(Страница обгорела в нескольких местах, как будто кто-то пытался сжечь её второпях.*" }, { 6.72, "*Часть текста уцелела)*" }, { 8.40, "Ада!" }, { 8.83, "Приятно слышать… остров недалеко от Тёмного берега…" }, { 12.96, "Один из наших агентов… пароль…" }, { 15.50, "\"Когда задувают одну свечу, зажигают вторую.\"" }, { 19.27, "Митчеллс" } } } },
    ["a711d7a7"] = { d = 24.9, v = "narrator", c = { x = { { 0.00, "Эонар, титан-покровительница всего живого, отдала часть своей силы красной огромной Алекстразе." }, { 7.97, "С тех пор Алекстраза зовётся Хранительницей Жизни и охраняет всех созданий этого мира." }, { 14.98, "За её мудрость и безграничное сострадание ко всему живому Алекстраза была избрана Королевой драконов и возглавила свой род." } } } },
    ["a729e9fd"] = { d = 30.6, g = 1, v = "orc-male", c = { m = { { 0.00, "Приветствую тебя, брат." }, { 1.92, "Изувеченная Длань выражает тебе своё почтение и надеется, что в нашей долине ты найдёшь, где применить своё ремесло." }, { 11.25, "Учти: мы пристально следим за твоими успехами и неудачами." }, { 16.06, "Мне поручено оценить твоё мастерство и сообщить, когда ты будешь готов к серьёзным делам." }, { 23.32, "Как будет время, навести меня в глубинах Логова." }, { 27.39, "-Руаг, наставник разбойников." } }, f = { { 0.00, "Приветствую тебя, сестра." }, { 2.19, "Изувеченная Длань выражает тебе своё почтение и надеется, что в нашей долине ты найдёшь, где применить своё ремесло." }, { 11.73, "Учти: мы пристально следим за твоими успехами и неудачами." }, { 16.65, "Мне поручено оценить твоё мастерство и сообщить, когда ты будешь готова к серьёзным делам." }, { 24.14, "Как будет время, навести меня в глубинах Логова." }, { 28.30, "-Руаг, наставник разбойников." } } } },
    ["a7786ad0"] = { d = 13.0, v = "human-female", c = { x = { { 0.00, "Порез был неглубокий, хотя обильно кровоточил." }, { 3.34, "Прежде чем я обмотала мой палец бинтом, добрая порция моей крови пролилась на стол." }, { 9.33, "И когда я начала убирать её, я заметила странную вещь…" } } } },
    ["a7a21ac9"] = { d = 28.1, v = "narrator", c = { x = { { 0.00, "Лотар и его войны, возвращавшиеся из Каражана, надеялись остановить кровопролитие и спасти свою некогда славную родину." }, { 9.60, "Но было слишком поздно: когда они вернулись, их королевство лежало в руинах." }, { 15.81, "Орда опустошала деревни и захватывала близлежащие земли." }, { 20.36, "Лотар и его войско, вынужденные скрываться от врагов, поклялись вернуть свою родину любой ценой." } } } },
    ["a7a34dbe"] = { d = 27.6, v = "narrator", c = { x = { { 0.00, "Великий Подъёмник — деревянный лифт, построенный тауренами на южном краю Степей, там, где равнина обрывается в каньоны Тысячи Игл." }, { 9.71, "Скрипучая платформа на канатах — единственный удобный спуск с плато вниз, и по нему идут все, кто держит путь на юг." }, { 18.32, "В последнее время свинобразы расширили свои владения и почти перекрыли дорогу к подъёмнику, так что путь до него стал опасным." } } } },
    ["a7b4afec"] = { d = 18.0, v = "creature/furbolg", c = { x = { { 0.58, "Огненная вода." }, { 2.16, "Сделай ещё." }, { 3.36, "Ещё огненной воды." }, { 5.31, "Огненная вода даёт силу." }, { 7.90, "Помогает побеждать врагов." }, { 10.69, "У Зимней Спячки нет союзников." }, { 13.84, "Но есть сила." } } } },
    ["a7b4db3c"] = { d = 28.9, v = "narrator", c = { x = { { 0.00, "Сияющий берег — восточное побережье Серебряного бора вдоль озера Лордамер, от границы Тирисфаля на севере до холмов, отделяющих лес от Альтерака." }, { 11.16, "Вдоль всего берега стоят поселения мурлоков, и для неопытного путника здесь опасно." }, { 17.47, "Аптекарь Берард в своих записях упоминал редкую опухоль, которую можно добыть у этих мурлоков и которая, по его мнению, пригодилась бы для новой чумы." } } } },
    ["a7d803a3"] = { d = 35.5, g = 1, v = "human-male", c = { m = { { 0.00, "Существует четыре правила магии:" }, { 2.44, "Магия могущественна." }, { 3.96, "Магия развращает." }, { 5.28, "Магия порождает зависимость." }, { 7.39, "Магия притягивает обитателей Круговерти Пустоты к тому, кто её применяет." }, { 12.73, "Эти правила неизменны." }, { 14.45, "Этим правилам ты должен будешь подчинить всю свою жизнь, если захочешь продолжить путь магов…" }, { 21.31, "Если у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства." }, { 30.01, "Я буду ждать тебя на втором этаже." }, { 32.59, "-Кельден Бремен, наставник магов" } }, f = { { 0.00, "Существует четыре правила магии:" }, { 2.49, "Магия могущественна." }, { 4.03, "Магия развращает." }, { 5.37, "Магия порождает зависимость." }, { 7.52, "Магия притягивает обитателей Круговерти Пустоты к тому, кто её применяет." }, { 12.96, "Эти правила неизменны." }, { 14.71, "Этим правилам ты должна будешь подчинить всю свою жизнь, если захочешь продолжить путь магов…" }, { 21.70, "Если у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства." }, { 30.56, "Я буду ждать тебя на втором этаже." }, { 33.18, "-Кельден Бремен, наставник магов" } } } },
    ["a7e6702f"] = { d = 18.6, v = "human-male", c = { x = { { 0.00, "Дела культа, том сто двадцать семь" }, { 2.58, "Воистину, это счастливый день!" }, { 4.88, "Нас испытали в Силитусе, и мы прошли испытание!" }, { 8.40, "Рассказы о разгроме нашего северного лагеря могут наполнить страхом сердца неверных, но для нас эта резня не должна быть несчастьем, нет!" } } } },
    ["a7fe4660"] = { d = 40.7, v = "narrator", c = { x = { { 0.00, "На юго-западе Тёмных берегов, посреди небольшого озера, возвышается Меч Властителя — исполинский клинок, вонзённый в череп невиданного существа." }, { 11.41, "Ону из Рощи Древних говорит, что здесь пал один из старых, очень старых богов этой земли, низвергнутых в незапамятные времена." }, { 21.59, "Ночные эльфы издавна считали это место священным, но теперь вокруг черепа разбил лагерь клан Сумеречного Молота." }, { 30.76, "Культисты поклоняются Древним богам и, судя по всему, пытаются с помощью древней эльфийской магии вернуть в мир своих хозяев." } } } },
    ["a85520dc"] = { d = 35.5, v = "human-male", c = { x = { { 0.00, "Я провёл следующие недели, перебегая с места на место, нигде не задерживаясь, из страха перед всадниками." }, { 7.51, "Сейчас я остановился в заброшенном городе Вороньем холме – прячусь, как обычно." }, { 13.20, "Я не могу встретиться с той силой, что они использовали на жене Свена, и я знаю, что она рыщет по Сумеречному лесу, всё ещё ищет косу." }, { 22.85, "Я потерял её, и за это я благодарю Свет, ибо если бы я оставил её у себя, я знаю, меня бы обнаружили." }, { 30.10, "Даже теперь в глубине моего сердца я уверен, что меня найдут." }, { 34.63, "Я так устал..." } } } },
    ["a85d1f67"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Во время битвы на полях Калимдора произошло нечто ужасное." }, { 4.76, "Подробности этого происшествия были утеряны, но известно лишь то, что дракон Нелтарион, аспект земли, в пылу битвы с Демонами вдруг сошёл с ума." }, { 16.24, "Он начал распадаться на части, по всей его чёрной шкуре вспыхивали языки пламени, и в итоге это разъярённое горящее чудовище назвало себя Смертокрылом и напало на своих собратьев, из-за чего пятеро драконов были вынуждены покинуть поле боя." } } } },
    ["a862933d"] = { d = 37.6, v = "narrator", c = { x = { { 0.00, "Застава Вольного Ветра — поселение тауренов Орды на вершине столовой горы в сердце Тысячи Игл." }, { 7.83, "Наверх ведут деревянный подъёмник и верёвочные мосты между иглами, и кентаврам до заставы не добраться." }, { 16.18, "Здешние таурены сдерживают племя Галак, посылают молодых воинов в Скальное гнездовье за яйцами виверн и с тревогой следят за Пиком Тёмного Облака." }, { 28.22, "Заставой ведает Рау Скальный Бегун, а Дозорный утёсов Долгорог собирает вести о злодеяниях Арнака Зловещего Тотема." } } } },
    ["a87f83ef"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Лагерь Злого Клыка в сердце Болотины — крупнейшая стоянка орков клана Драконьей Пасти в этом краю." }, { 7.85, "Когда красные драконы вырвались из рабства и разорили Грим Батол, уцелевшие орки бежали в горы и болота, и с тех пор их отряды бесчинствуют по всей Болотине." }, { 19.98, "Отсюда они уходят к Дун Альгазу и к дорогам вокруг гавани, а в лагере за частоколом горят костры и стоят шатры воинов и шаманов." } } } },
    ["a880161d"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Гибельный берег — самое южное побережье Восточных королевств, где земля встречается с Южными морями." }, { 7.60, "У островков близ берега стоят на якоре три фрегата пиратов Кровавого Паруса, готовящих нападение на Пиратскую бухту, а на самом берегу разбит их лагерь." }, { 19.08, "Вдоль полосы прибоя бродит морской великан Горлаш, а в песке попадаются бутылки с посланиями." }, { 26.14, "На востоке пролив отделяет берег от острова Жагуаро." } } } },
    ["a8813767"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Паучье логово — пещера на северо-западной окраине Тенистой долины, целиком затянутая паутиной." }, { 7.52, "В ней плодятся чащобные тенётники: они куда крупнее своих сородичей с материка, и друиды полагают, что виной тому влияние самого Древа Жизни." }, { 18.72, "В глубине логова спрятано гнездо с яйцами, и пауки яростно его защищают." }, { 24.53, "Гилшалан Буйный Ветер, стоящий у Альдрассила, собирает здесь образцы яда, чтобы понять природу этих тварей." } } } },
    ["a883dbd1"] = { d = 32.3, v = "narrator", c = { x = { { 0.00, "Колодец Заиндевевшего Копыта стоит на краю Холмистых равнин в южном Мулгоре." }, { 6.26, "Это один из трёх священных колодцев тауренов, и именно с него начинается их очищение: гоблины Торговой компании и их прислужники отравили воду, чтобы взять под власть источники долины." }, { 21.04, "Мулл Громовой Рог из деревни Кровавого Копыта создаёт тотем очищения из лап койотов и когтей долгоногов, а подступы к колодцу стерегут гоблины." } } } },
    ["a8c70eee"] = { d = 29.3, v = "narrator", c = { x = { { 0.00, "Таверна «Громоварка» — сердце Караноса и одна из самых известных пивоварен мира." }, { 5.96, "Здесь варят громовой эль, а завсегдатаи больше всего любят кабаньи рёбрышки в пиве по фамильному рецепту Рагнара Громовара." }, { 14.98, "В таверне есть постель для путников, а наверху и на кухне обучают ремёслам и боевому искусству." }, { 21.87, "Соперники из семьи Ячменоваров не прочь подменить бочонок в её подвале, чтобы доказать, чьё пиво лучше." } } } },
    ["a8c9092f"] = { d = 24.7, v = "narrator", c = { x = { { 0.00, "Казармы Колючего Холма — самое большое здание посёлка, отличающее его от прочих застав Дуротара." }, { 7.79, "Под их крышей обучают воинов, жрецов и шаманов, учат искусству первой помощи и торгуют всем необходимым." }, { 16.15, "Отсюда же командование Колючего Холма следит за угрозами округи, от Иглогривых до сектантов Пылающего Клинка." } } } },
    ["a8cbba8e"] = { d = 18.2, v = "dwarf-male", c = { x = { { 0.00, "Дун Модр, Болотина" }, { 1.26, "Дорогая моя Сара!" }, { 2.59, "Судя по всему, через несколько дней мы сменим позиции, чтобы охранять Мост Тандола." }, { 8.46, "Возможно, я больше не смогу писать тебе." }, { 11.36, "Мне хочется написать несколько строк, которые могут попасться тебе на глаза, когда меня не станет." } } } },
    ["a8e080be"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Деревня Гелкис стоит на юго-западе Пустошей, у дороги, ведущей в Фералас." }, { 5.79, "Это главное селение кентавров клана Гелкис: их хижины кольцом окружают глубокий овраг, через который перекинуты мосты, а в пещере на южном склоне восседает сам хан." }, { 18.63, "Гелкис враждуют с кланом Маграм, и всякий путник, идущий по дороге к югу, рискует попасть под их копыта." } } } },
    ["a8edfc23"] = { d = 20.6, v = "human-male", c = { x = { { 0.00, "Господин мой!" }, { 0.94, "Война близко." }, { 1.94, "Злой рок стучит нам в двери." }, { 3.88, "Являясь чиновником магистрата города Приозёрье, считаю своим долгом сообщить вам о недавнем вооружённом столкновении в крайней восточной колонии Его Величества." }, { 14.89, "Ниже вы найдёте рассказ об Озёрном государстве, что лежит среди отрогов Красногорья." } } } },
    ["a9016095"] = { d = 23.1, v = "narrator", c = { x = { { 0.00, "Молодой и талантливый учёный по имени Фурион Ярость Бури, который очень долго изучал эффекты Источника, начал подозревать, что Высокорождёнными и обожаемой королевой овладела тёмная сила." }, { 14.71, "И хотя он не мог постичь природы этого зла, он осознавал, что жизнь ночных эльфов скоро изменится навсегда..." } } } },
    ["a92ce9c8"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Гордая Эгвин, веря, что она сможет противостоять грозному богу, обрушила всю свою силу на аватару Саргераса." }, { 8.60, "С необыкновенной лёгкостью Эгвин одолела лорда демонов и уничтожила его физическую оболочку." }, { 15.79, "Опасаясь, что дух Саргераса выжил, наивная Эгвин спрятала изуродованные останки в одном из древних дворцов Калимдора, ушедших под воду после разрушения Источника Вечности." } } } },
    ["a93460a1"] = { d = 21.4, v = "narrator", c = { x = { { 0.00, "Мельница Бровача стоит к северу от часовни Последней Надежды." }, { 5.10, "Когда-то здесь пилили лес, но чума добралась и сюда: хозяин мельницы погиб, был поднят вурдалаком и теперь сторожит собственные владения." }, { 16.34, "Среди сараев бродят скелеты, банши и сшитые из плоти поганища." } } } },
    ["a95c5d04"] = { d = 36.0, v = "narrator", c = { x = { { 0.00, "Современные наблюдения" }, { 1.62, "Со временем и другие народы начали признавать праздник Зимнего Покрова временем великого празднества, хотя отмечать праздник они стали не совсем так, как описано в легенде." }, { 14.10, "Сегодня этому торжеству в разных уголках мира соответствует множество обычаев, часто ставящих своей целью лишь собственно празднество и обмен подарками." }, { 25.15, "Иногда на праздниках появляются и портреты Дедушки Зимы, но, как правило, затем, чтобы бойче шла торговля, а не ради восхваления могущественного титана." } } } },
    ["a982c345"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "Эредары, коварная раса демонических чародеев, использовала магию своих чернокнижников, чтобы поработить множество миров." }, { 9.60, "Расы тех миров мутировали под влиянием злых сил эредаров и сами превращались в демонов." } } } },
    ["a9bffc09"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Пещера Когтей — курган друидов, вырытый в недрах Пика Каменного Когтя." }, { 5.98, "Здесь, под присмотром дриад, хранителей рощи и кенарийских смотрителей, спят друиды, странствуя по Изумрудному Сну." }, { 15.33, "В коридорах кургана порхают волшебные дракончики, а сокровища и могущественные предметы друиды укрыли в хитроумных тайниках." }, { 25.57, "Ключами к ним ведает дриада Ринтариэль, Хранительница Ключей, и Орда давно точит на неё зуб." } } } },
    ["a9c4db7e"] = { d = 31.1, v = "dwarf-male", c = { x = { { 0.00, "День пятый." }, { 0.86, "Этот проклятый медведь добрался до меня!" }, { 3.88, "Он бросился на меня в полдень и напал со спины." }, { 7.37, "Я бы унюхал его задолго до этого, если бы он напал на меня не с подветренной стороны – запах от него шёл ужасный!" }, { 15.67, "Одна только вонь от его грязной шкуры и гнилое дыхание заставили бы меня сбежать оттуда!" }, { 22.25, "Я сражался с ним, но он хорошо подрал мою ногу." }, { 25.74, "Теперь я не могу двигаться, эля нет, и я так и не нашёл эту руду." }, { 30.48, "Проклятье!" } } } },
    ["a9c5bccf"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Лагерь Джерода – лодочная пристань на речном берегу к югу от Златоземья." }, { 5.41, "С виду это простые доки, но по донесениям агентов Штормграда пристань захватило Братство Справедливости и превратило в перевалочный пункт: отсюда переправляют крупные партии контрабанды из Красногорья в Западный Край." }, { 21.35, "Всем здесь заправляет портовый начальник, а расписание поставок он держит при себе." } } } },
    ["a9f35619"] = { d = 6.8, v = "narrator", c = { x = { { 0.00, "Они обрели бы вечную жизнь и им было бы незачем бояться грядущего Раскола..." } } } },
    ["aa30a764"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "В то время как высшие эльфы шли по гористым землям Лордерона, их путешествие становилось всё более опасным." }, { 8.21, "Поскольку они были отрезаны от животворных энергий Источника Вечности, многие из них начали болеть из-за холодного климата или умирать от голода." }, { 19.55, "Но ужаснее всего было то, что теперь они были не бессмертны и не могли противостоять стихиям." } } } },
    ["aa35d4cb"] = { d = 20.0, v = "narrator", c = { x = { { 0.00, "Вернувшись к жизни, он обнаружил, что уже повзрослел, а его друзья Ллан и Андуин стали правителями Азерота." }, { 8.69, "Он желал использовать обретённые силы на благо своей родной земли, но злой дух Саргераса овладел его разумом и направил его на путь злодеяний." } } } },
    ["aa684e0e"] = { d = 39.1, v = "narrator", c = { x = { { 0.00, "Деревня Гиблотопь на северо-западе болота — единственный оплот Орды в Пылевых топях." }, { 6.97, "Её основали огры клана Каменного Молота, бежавшие с юга после того, как их деревню разорили чёрные драконы; теперь ими правит властитель Мок'Морокк, а рядом живут орки и таурены." }, { 21.66, "Среди хижин и огрского кургана горят костры, отсюда летают ветрокрылы в Оргриммар и Громовой Утёс, а дозорные следят за разведчиками Терамора у самых стен." }, { 34.21, "Огры не забыли утраченный дом и ждут дня, когда вернутся на юг." } } } },
    ["aa973572"] = { d = 32.1, v = "tauren-male", c = { x = { { 0.00, "Натака, в Тысяче Игл всё хорошо." }, { 2.76, "Кентавры вот только иногда нападают, но это нельзя назвать реальной угрозой." }, { 9.34, "Впрочем, говорят, что в последнее время кланы кентавров объединяются." }, { 15.24, "Мы всё понимаем, к чему может привести объединение такого безжалостного народа, как кентавры…" }, { 23.12, "Я стараюсь не думать об этом, ты же знаешь… их ненависть вечна… даже друг к другу." }, { 30.09, "-Дозорный утёсов Долгорог" } } } },
    ["aa9804b3"] = { d = 26.9, v = "dwarf-male", c = { x = { { 0.00, "Попытался проучить монстра, но в итоге получил глубокий порез на руке." }, { 5.19, "Похоже, придётся накладывать швы." }, { 7.56, "ТРЕТИЙ ДЕНЬ." }, { 8.48, "Похолодало." }, { 9.34, "Ночью выпало немного снега." }, { 11.44, "ЧЕТВЁРТЫЙ ДЕНЬ." }, { 12.49, "Ученик поправился и пребывает в хорошем расположении духа, поэтому мы рискнули посмотреть на троллей." }, { 19.86, "Или скорее, Снежную Гриву, исходя из отметок на их коже и различных амулетов, которые они носят." } } } },
    ["aa9df36e"] = { d = 19.3, v = "narrator", c = { x = { { 0.00, "Около шестнадцати тысяч лет назад, задолго до того как ночные эльфы навлекли на себя гнев Пылающего Легиона, большая часть Калимдора принадлежала троллям." }, { 12.40, "Они основали две империи: Гурубаши в юго-восточных джунглях и Амани в центре материка." } } } },
    ["aadffb88"] = { d = 25.6, v = "tauren-female", c = { x = { { 0.00, "День первый." }, { 1.01, "Торговая компания по-прежнему внушает тревогу." }, { 4.77, "Их рудники только разрастаются, а оттуда доносится новый скрежет – похоже, туда привезли какую-то новую жуткую машину." }, { 14.40, "Пока я не считаю их серьёзной угрозой для Громового Утёса, но если их раздразнить, они вполне могут ударить по деревне Кровавого Копыта с юга." } } } },
    ["ab1171a1"] = { d = 22.1, v = "narrator", c = { x = { { 0.00, "Под водами залива Бурь скрывается затонувший храм Элуны, который ныне называют Гнездом Хетайры." }, { 7.55, "Его заняли гидры — дети Хетайры, а сама многоголовая мать плавает в водах чуть севернее и порой выбирается на скалистый островок." }, { 17.81, "Спускаться сюда отваживаются лишь самые опытные пловцы." } } } },
    ["ab211b15"] = { d = 42.0, v = "narrator", c = { x = { { 0.00, "Холм Печали — старое кладбище к югу от Андорала." }, { 3.93, "В мирные годы здесь хоронили и знать, и бедняков, оттого рядом с богатыми склепами тянутся ряды простых плит." }, { 12.74, "Когда началась Чума, могилы рыли наспех и почти не помечали, а под конец горожане и вовсе стали сжигать мертвецов, боясь, что те восстанут." }, { 24.10, "Последним делом уходящих жителей стала гробница Утера на вершине холма." }, { 29.99, "Но чумные котлы сделали своё: скелеты павших солдат и вурдалаки из бывших горожан сторожат собственные могилы, а из склепа поднимаются мёртвые чародеи." } } } },
    ["ab29e59d"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Руины Полуденной Тени — древние тролльские развалины к востоку от Прибамбасска, на северо-востоке Танариса." }, { 8.18, "Здесь укрылась часть шайки Скитальцев Пустыни: потомки пиратов, брошенных когда-то на этом берегу, теперь грабят гоблинские обозы и захватывают колодцы." }, { 19.89, "Водная компания Прибамбасска ищет тех, кто сократит число кочевников и вернёт ей воду." } } } },
    ["ab4904b7"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Руины Абораза стоят на юго-восточном побережье, на северном краю Хрустального взморья." }, { 6.84, "Здесь обосновался Занзил Отверженный — знахарь, изгнанный своим племенем за то, что травил сородичей зельями." }, { 15.31, "Его смеси лишают разума всех, кто их выпьет: по руинам бродят одурманенные наги, тролли и поднятые мертвецы." }, { 23.84, "Среди его невольников — Йеннику, сын вождя Чёрного Копья, и должники пиратского капитана из Пиратской бухты." } } } },
    ["ab4e2315"] = { d = 38.0, v = "narrator", c = { x = { { 0.00, "Длинный пролив, вопреки названию, — самый короткий отрезок побережья: пустынная полоса песка к югу от Аубердина, до широты Амет'Арана." }, { 10.88, "Под вечно пасмурным небом берег кажется сумрачным даже днём, а песок усеян обломками и костями морских животных." }, { 20.02, "В воде к западу от деревни, рядом с затонувшим судном, лежит скелет морской черепахи." }, { 26.98, "Мурлоки клана Серой Мглы появляются здесь всё чаще: в их поселении скрывается Глубомрак, за голову которого совет деревни назначил награду." } } } },
    ["ab699c1b"] = { d = 30.6, v = "dwarf-female", c = { x = { { 0.00, "Дополнительные ресурсы, чтобы сократить их распространение." }, { 4.21, "Горные пехотинцы не могут и дальше перекладывать эту проблему на искателей приключений и надеяться на лучшее." }, { 12.05, "Рано или поздно еда закончится, и вендиго будут вынуждены открыто нападать на наши города." }, { 18.73, "Возможно, это коснётся и Стальгорна." }, { 21.32, "Прошу передать мои соболезнования семье горного пехотинца Корнелия." }, { 26.25, "Он отважно сражался ради безопасности Дун Морога и его народа." } } } },
    ["ab6b8d45"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Посёлок Грош'гок — самая большая и самая южная из пещер Погани, главное логово огров Мёртвого Ветра." }, { 8.44, "Внутри курган пропах дымом и гнилью; огры и их колдуны сторожат вход, и тропа мимо него — последняя перед самой башней." }, { 18.62, "Здесь редко кто задерживается по своей воле." } } } },
    ["ab816e8f"] = { d = 2.4, v = "narrator", c = { x = { { 0.00, "ДИАГРАММА СЕВЕРНОГО ПИЛОНА" } } } },
    ["ab90be8d"] = { d = 22.8, v = "narrator", c = { x = { { 0.00, "Орки и люди, враждовавшие не одно поколение, не хотели и слушать его." }, { 5.72, "Медиву пришлось общаться с каждой расой по отдельности, обманом заставить их пересечь море и ступить на легендарную землю Калимдора." }, { 16.50, "Вскоре орки и люди обнаружили скрывавшуюся долгое время цивилизацию кальдорай." } } } },
    ["ab962a02"] = { d = 19.1, v = "dwarf-female", c = { x = { { 0.00, "Дорогой Таррел!" }, { 1.22, "Прости за поспешность, с которой написано это послание, однако сейчас время для нас роскошь." }, { 8.21, "Раскопщики достигли неплохих результатов в поиске артефактов титанов." }, { 13.43, "Но мы обнаружили также другие древние предметы – в частности, огромные кости." } } } },
    ["abd15fd6"] = { d = 22.3, v = "narrator", c = { x = { { 0.00, "Спящая теснина — небольшой разлом в восточной части перевала." }, { 5.02, "Одна из троп к Каражану ныряет в него и тянется по дну между скал, прежде чем свернуть на восток, в Погань." }, { 13.60, "Тишина здесь такая, будто ущелье и впрямь спит; только ветер над головой напоминает, что оно лишь притворяется." } } } },
    ["ac36f8bb"] = { d = 15.3, v = "narrator", c = { x = { { 0.00, "Акири основали две крупнейших колонии – Азжол-Неруб на севере и Ан'Кираж на юге." }, { 6.42, "Тролли предполагали, что существуют и другие колонии под поверхностью Калимдора, но эти подозрения не оправдались." } } } },
    ["ac3e801c"] = { d = 26.0, v = "narrator", c = { x = { { 0.00, "Драконы смотрели, как из Ан'Киража исторгался нескончаемый поток силитидов и киражей." }, { 6.96, "Им стало ясно, что никакая армия, сколь угодно большая, эту войну не выиграет." }, { 13.48, "В главном храме ждали своего часа десятки тысяч воинов." }, { 18.23, "С каждой секундой вылуплялись и вставали под знамёна всё новые их бойцы, готовые ринуться в сечу." } } } },
    ["ac3ff993"] = { d = 30.3, v = "narrator", c = { x = { { 0.00, "Шли века, сообщество ночных эльфов набиралось сил и разрасталось, занимая всё новые и новые территории леса, который они назвали Ясеневым." }, { 11.85, "Появились и расплодились многие существа, жившие ещё до Великого Раскола, – например, фурболги и иглогривы." }, { 20.93, "Ночные эльфы жили под управлением мудрых друидов и наслаждались эрой небывалого спокойствия и мира под звёздами." } } } },
    ["ac763d77"] = { d = 30.4, v = "narrator", c = { x = { { 0.00, "С другой стороны, достоверно установлено, что раса ночных эльфов обрела могущество именно после обнаружения источника Вечности." }, { 10.00, "Несмотря на все попытки троллей защитить свои владения, эта раса стремительно захватывала первобытный Калимдор." }, { 18.72, "Сильная магия, недостижимая для суеверных троллей, позволила ночным эльфам добиться того, что не смогли сделать акири, – разрушить две великие империи." } } } },
    ["ac76c856"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Сухие холмы — пыльные высоты на северо-западе Степей, где среди скал гнездятся гарпии стаи Зачарованного Крыла." }, { 8.95, "Отсюда они налетают на караваны Орды со съестными припасами, и кости на склонах напоминают о цене этих набегов." }, { 17.90, "Стаей правит Серена Кровавое Перо — сестра гарпии, которую давным-давно убил Рексар; месть за сестру и гонит её на дороги." }, { 27.78, "На Перекрёстке Дарсок Точный Нож ведёт с гарпиями свою собственную войну." } } } },
    ["acb094a3"] = { d = 18.5, v = "human-male", c = { x = { { 0.00, "*И ветра быстрей прискакали они, И громко он их имена возгласил:*" }, { 5.76, "\"Ну, Мерсер!" }, { 6.78, "Ну, Чилтон!" }, { 7.72, "Ну, Джордан и Каплан!" }, { 9.47, "Но, Нэйгл!" }, { 10.27, "Но, Пардо!" }, { 11.14, "Но, Гудман и Метцен!" }, { 12.81, "Бегом на крыльцо!" }, { 14.27, "На стену скорей!" }, { 15.65, "И мчитесь, мчитесь, мчитесь резвей!\"" } } } },
    ["acb99c1c"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Священный Камень — место, святое для шаманов Орды." }, { 4.40, "Он стоит высоко в горах над Долиной Испытаний, куда ведёт Потайная тропа." }, { 10.73, "Здесь начинающие шаманы пьют сапту, напиток, связывающий дух со стихией, и впервые слышат голос Земли." }, { 19.45, "Сапту можно пить лишь в священном месте, и потому камень оберегают от чужих глаз." } } } },
    ["acbbbcd3"] = { d = 1.1, v = "goblin-male", c = { x = { { 0.00, "Мельницы." } } } },
    ["acec5b51"] = { d = 25.7, v = "narrator", c = { x = { { 0.00, "Пещера Железнолесья уходит глубоко под холмы на северо-востоке Железнолесья." }, { 6.31, "Внутри темно и сыро, и в этой темноте копошатся криводревы — живорезы и моходеры, порченые древни, которые сдирают мох и кору со всего, до чего дотянутся." }, { 19.08, "У входа рыщут опустошители-сквернолапы, так что случайных путников здесь не бывает." } } } },
    ["aceea7ec"] = { d = 5.8, v = "narrator", c = { x = { { 0.00, "Элиза" }, { 0.68, "Возлюбленная жена, пусть земля утолит твой голод." } } } },
    ["ad9f40f3"] = { d = 42.7, v = "narrator", c = { x = { { 0.00, "Аубердин — небольшая портовая деревня ночных эльфов на берегу Сокрытого Моря, единственное обжитое место на Тёмных берегах." }, { 9.71, "Низкие деревянные дома соединены мостками и освещены фонарями, а над пристанью возвышается маяк." }, { 17.29, "Отсюда корабли ходят к подножию Тельдрассила и через море в Гавань Менетилов, а гиппогрифы уносят путников на юг." }, { 26.22, "Деревней управляет старейшина Тандрис Ветропряд, а рядом с эльфами живут дворфы, гномы и люди." }, { 33.73, "Говорят, давным-давно у маяка разбился корабль капитана Элуры, и сундуки с элунитовой рудой до сих пор лежат на дне." } } } },
    ["adb95612"] = { d = 38.7, v = "narrator", c = { x = { { 0.00, "На берегу озера, Амет'Аран и Башал'Аран были впереди всех, обладая благословлением Азшары, возлюбленной королевы калдорай, при своём создании." }, { 10.60, "Её любимые слуги из высокорождённых прибыли вместе с ней для обитания в городах-близнецах; управлять ими она назначила Атрикуса Нарассина, хотя оказалось так, что он стал проводить большую часть времени в своей башне Алталакса, на некотором расстоянии от городов." }, { 30.17, "Его помощником, магом, известным своим мастерством в тайных искусствах наравне со своими физическими способностями," } } } },
    ["ade96ef7"] = { d = 31.5, g = 1, v = "human-male", c = { m = { { 0.00, "Я никогда так не гордился своим ремеслом, как в последние несколько лет." }, { 4.91, "Спрос на услуги убийц, шпионов и разведчиков высок как никогда." }, { 9.27, "На первый взгляд может показаться, что нас кормит война." }, { 13.13, "Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу." }, { 20.03, "Мне передали, что ты появился в наших краях и хочешь кое-чему научиться." }, { 25.07, "Когда будет время, приходи к стойлам позади аббатства." }, { 28.93, "-Джорик Керридан, наставник разбойников" } }, f = { { 0.00, "Я никогда так не гордился своим ремеслом, как в последние несколько лет." }, { 4.89, "Спрос на услуги убийц, шпионов и разведчиков высок как никогда." }, { 9.23, "На первый взгляд может показаться, что нас кормит война." }, { 13.07, "Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу." }, { 19.94, "Мне передали, что ты появилась в наших краях и хочешь кое-чему научиться." }, { 25.02, "Когда будет время, приходи к стойлам позади аббатства." }, { 28.86, "-Джорик Керридан, наставник разбойников" } } } },
    ["ae084a5c"] = { d = 35.4, v = "dwarf-male", c = { x = { { 0.00, "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Дун Морога." }, { 5.37, "Подготовлен Сениром Белобородом, особым посланником Сената." }, { 9.54, "Большая часть троллей, обитающих в Дун Мороге, сконцентрирована в форте Мерзлогривов, горной пещере на западной границе." }, { 17.88, "Их численность может вызывать некоторые опасения, однако, похоже, они не собираются покидать свою пещеру." }, { 25.33, "Вне всяких сомнений, они не хотят вновь вызывать гнев дворфов, которые могут их полностью изничтожить." }, { 32.47, "Они всего лишь обороняют свою территорию и" } } } },
    ["ae1406a0"] = { d = 3.8, v = "narrator", c = { x = { { 0.00, "(Вы не можете разобрать надписи на этих страницах.)" } } } },
    ["ae24ce8f"] = { d = 34.7, v = "human-male", c = { x = { { 0.00, "Мои руки дрожат, когда я вспоминаю о подробностях той ночи, когда Свен ушёл и его семья была обречена встретиться с чёрными всадниками один на один." }, { 10.35, "Вновь сожаления гложут меня, ибо я был там и мог восстать против монстров из Мёртвого Ветра." }, { 16.68, "Но это никчёмные сожаления." }, { 18.56, "Подобные сомнения терзают любого, выжившего после трагедии." }, { 22.76, "Я знаю, что если бы я покинул моё убежище, я тоже был бы убит, моё тело было бы разорвано и раскромсано, а его части разбросаны так далеко, что никто не смог бы меня опознать." } } } },
    ["ae6bb52e"] = { d = 28.6, v = "narrator", c = { x = { { 0.00, "Остров Жагуаро лежит у юго-восточного побережья, отделённый от материка мелким проливом." }, { 6.84, "Его джунгли населяют небогривые гориллы и жагуары, а правит островом исполинская горилла, чей рёв заставляет содрогаться всё живое." }, { 17.08, "В плену у неё томится знатная пленница-таурен, которая бросает в море бутылки с записками в надежде на спасение." }, { 25.90, "Волны выносят их на Гибельный берег." } } } },
    ["ae7600ba"] = { d = 30.7, v = "gnome-male", c = { x = { { 0.00, "Вот параметры поршня:" }, { 1.65, "Длина: тридцать два ша-у" }, { 3.58, "Диаметр: двенадцать ша-у" }, { 5.51, "Вес: от двадцати трёх с половиной о-эм-гэ до двадцати пяти с половиной о-эм-гэ" }, { 11.44, "Проводимость: семьдесят пэ-зэ" }, { 13.71, "Прочность на сдвиг: девяносто восемь или выше" }, { 17.23, "Рейтинг перенаправления: \"Суперпрочный\" или выше" }, { 20.95, "На случай, если ты забыл гномские сокращения:" }, { 24.46, "Ша-у — «Ширина Уса»." }, { 26.11, "О-эм-гэ — «Очень Мелкие Граммы»." }, { 28.66, "Пэ-зэ — «Пальцевые Завитки»." } } } },
    ["ae9a375f"] = { d = 9.8, v = "narrator", c = { x = { { 0.00, "Яна Кровавое Копьё" }, { 1.59, "Второй предводитель убийц Алого ордена" }, { 4.92, "Жительница Даларана" }, { 6.59, "Пропала без вести в Тирисфальских лесах" } } } },
    ["ae9b7162"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Пещера Багрового Тумана — тёмный грот в склоне горы, где культисты Пылающего Клинка укрываются от чужих глаз." }, { 9.03, "Здесь, вдали от света, орки-чернокнижники ведут свои обряды и хранят предметы, пропитанные демонической силой." }, { 18.29, "Из глубины тянет сыростью и гарью, а у входа дежурят послушники культа." } } } },
    ["ae9f2878"] = { d = 37.3, v = "dwarf-female", c = { x = { { 0.00, "Отчёт о состоянии вендиго в пещерах близ Караноса." }, { 3.62, "Составлен горным пехотинцем Гретхен на основе наблюдений горного пехотинца Корнелия." }, { 9.80, "Вендиго редко выходят из своих пещер, но нам поступают сообщения о том, что они нападают на мирных жителей около близлежащих поселений, таких как Каранос и Посёлок Пивоваров." }, { 22.43, "Судя по всему, агрессия зверей растёт с отчаянными поисками пищи." }, { 27.23, "Недавно мы и сами потеряли товарища, пытаясь их сдерживать." }, { 31.57, "Хотя мы считаем полное устранение этих созданий нецелесообразным, мы запрашиваем" } } } },
    ["aeaefc8a"] = { d = 30.6, v = "dwarf-male", c = { x = { { 0.00, "Достопочтенные коллеги и искатели правды." }, { 2.91, "Раскопки продолжаются, но они были приостановлены из-за троггов, о которых я сообщал в моём последнем докладе." }, { 10.61, "Я уверен, их проблему можно решить даже несмотря на то, что некоторые трогги гораздо более агрессивны, чем обычно." }, { 18.64, "Мы нашли ещё больше артефактов, хотя во всех случаях, кроме одного (о котором я напишу ниже), эти находки были такие же, как и раньше, – интересные, если не сказать более." } } } },
    ["aeb16e65"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Сокрытое Море омывает западный край Силитуса, и его волны едва слышны за грядой прибрежных скал." }, { 7.90, "Здесь пустыня обрывается в океан, что тянется вдоль всего западного побережья Калимдора, а с воды дует редкий прохладный ветер." }, { 18.20, "На этот глухой берег почти никто не заходит: ни силитиды, ни сектанты не ищут ничего у солёной воды." } } } },
    ["aec4c93a"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Великое море омывает Пылевые топи с востока." }, { 3.72, "Оно родилось при Великом Расколе, когда воды хлынули в разлом древнего Калимдора, и с тех пор отделяет один континент от другого." }, { 14.21, "Отсюда, от причалов Терамора, корабли уходят в Гавань Менетилов, а у берегов болота в солёных волнах живут черепахи, акулы и мурлоки; дальше в море заплывать не стоит — там нет ничего, кроме бездны." } } } },
    ["aecea9fc"] = { d = 20.7, v = "named/13717", c = { x = { { 0.00, "В пещерах Мародона блуждают духи наших первых Ханов." }, { 5.22, "Они – первые дети наших Матери и Отца и наши величайшие вожди, их зовут Гелк, Колк, Магра, Мародос и Венг." }, { 15.58, "Каждый из этих духов хранит один из пропавших камней." } } } },
    ["aef337ce"] = { d = 31.6, v = "narrator", c = { x = { { 0.00, "Великое море — океан, разделяющий земли Азерота." }, { 4.24, "Оно родилось в Великом Расколе, когда воды хлынули в разлом на месте Источника Вечности, а посреди него по сей день бушует Водоворот." }, { 15.72, "У берегов Азшары море сурово: волны бьют в утёсы, среди рифов торчат скалистые островки, а в глубине плавают наги, гидры и морские великаны." }, { 27.83, "Уплывший слишком далеко от берега не вернётся." } } } },
    ["aef8be10"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Сатирнаар лежит на северо-востоке леса, у дороги от заставы Расщеплённого Дерева в Азшару." }, { 7.19, "Из трёх сатирских логовищ Ясеневого леса это самое обжитое: среди разрушенных эльфийских построек сатиры разбили шатры, а у жаровен с тёмным пламенем призывают бесов и демонов Бездны." }, { 21.85, "Они в союзе с кланом Тёмной Нити и стерегут один из его камней душ." }, { 27.32, "Поскольку Сатирнаар стоит у самой дороги, он чаще других становится целью и орков, и эльфов." } } } },
    ["af369b9e"] = { d = 25.6, v = "human-male", c = { x = { { 0.00, "Но прежде чем читатель поспешит отбросить мысли о сказках, поспешу его уверить: воргены существуют на самом деле." }, { 7.97, "Возможно, они не из нашего мира, но между мирами сейчас проложены свои тропы, и чудовищ можно призвать сюда из их миров с помощью сильной магии." }, { 18.21, "Но лучше такой магией не пользоваться, ведь где бы ни появлялись воргены, с собой они приносят ужас и смерть." } } } },
    ["af36b52d"] = { d = 24.5, v = "human-male", c = { x = { { 0.00, "Всё началось с находки этой проклятой косы в Погибели Роланда." }, { 4.56, "До того, как я нашёл косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья." }, { 12.70, "Но с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил её, Погибель Роланда превратилась в место ужасной смерти!" } } } },
    ["af3dd956"] = { d = 10.3, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.94, "Часть два." }, { 4.02, "Рыцарь-защитник." }, { 5.89, "Рыцарь-капитан." }, { 7.65, "Рыцарь-лейтенант." }, { 9.62, "Рыцарь." } } } },
    ["af6c88fc"] = { d = 27.5, v = "narrator", c = { x = { { 0.00, "После гражданской войны пути оставшихся троллей Гурубаши разошлись." }, { 5.83, "Племена Дробителей Черепов, Кровавого Скальпа и Чёрного Копья племена нашли своё пристанище в джунглях Тернистой долины." }, { 16.02, "На руинах империи воцарился хрупкий мир, но в народной памяти осталось пророчество о том, что однажды Хаккар вернётся в мир и поглотит его." } } } },
    ["af809aaa"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Пещера Болгана — грот в южных скалах Пустошей, куда ведёт шаткий верёвочный мост через ущелье Деревни Гелкис." }, { 8.67, "Здесь живёт вождь племени Гелкис — Шак, и чужаку сюда хода нет." }, { 13.61, "В глубине пещеры растут синие кристаллы, которые кентавры зовут Слезами Терадрас: шаманы Гелкис берегут их как святыню, веря, что через них мать кентавров хранит племя." }, { 27.07, "Племя Маграм, не признающее власти Терадрас, мечтает разбить их и показать врагам, что заступницы у тех нет." } } } },
    ["af8faf6a"] = { d = 32.3, v = "narrator", c = { x = { { 0.00, "Залив Яростных Волн — южная оконечность Пылевой бухты, к югу от Терамора и у самого берега Драконьих топей." }, { 8.74, "Мелководье усеяно островками и рифами, о которые разбились уже два корабля; их остовы облюбовали макруры." }, { 17.26, "На одном из островков поселился Нэт Пэгл, самый знаменитый рыбак Азерота: он удит с утра до вечера и охотно рассказывает о своих приключениях каждому, кто по-настоящему предан рыбной ловле." } } } },
    ["af9eeb0b"] = { d = 40.3, v = "narrator", c = { x = { { 0.00, "Озеро Элуне'ара занимает середину Лунной поляны и названо в честь самой Элуны." }, { 6.63, "Его вода прозрачна и чиста, и в ней, словно в зеркале, отражаются звёзды и луна." }, { 13.34, "На северном берегу стоит Ночная Гавань, а молодые друиды ищут на дне озера реликвии, постигая облик водных существ." }, { 23.14, "Но в глубине спит Омен — древний волк, благословлённый Элуной и потерявший рассудок от ран Войны Древних." }, { 31.73, "Каждый год, когда приходит Лунный фестиваль, он поднимается из вод, и герои вновь возвращают его в озеро." } } } },
    ["afa75e90"] = { d = 29.3, v = "narrator", c = { x = { { 0.00, "Благой Пантеон, желающий оградить свои упорядоченные миры от всякого зла, зорко наблюдал за действиями тёмных сил Круговерти Пустоты." }, { 11.01, "Там, в неосязаемом мире неупорядоченных магических энергий, соединяющем мириады миров во Вселенной, обитали неисчислимые множества зловредных демонических существ, жаждавших лишь умерщвления и пожирания всего сущего в мирах." } } } },
    ["afd00e5d"] = { d = 19.2, v = "narrator", c = { x = { { 0.00, "Руины Ткаши лежат к юго-западу от лагеря Эрнестуэя, в густых джунглях." }, { 5.76, "Их занимает многочисленный отряд троллей Кровавого Скальпа, чьи знахари творят здесь свои обряды." }, { 13.52, "Древние камни Гурубаши поросли лианами, но племя не оставляет этих мест." } } } },
    ["aff1d31f"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Под бдительным присмотром Тирисфальского ордена Даларан стал центром обучения для всех волшебников." }, { 7.67, "Магократы, правившие Далараном, основали Кирин-Тор, особое тайное общество, регистрировавшее и изучавшее каждое заклинание, артефакт или магический предмет, известный в то время." } } } },
    ["b007cf8f"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "В конце страшного противостояния, известного под названием Войны Древних, Источник Вечности взорвался." }, { 8.06, "Мощная волна разорвала Калимдор на части, превратив его в несколько менее крупных континентов и островов." } } } },
    ["b07744e5"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Топи занимают юго-восток кратера — это первое, что видит путник, спустившийся из Танариса." }, { 7.21, "Влажные низины поросли высокой травой и тростником, а между лужами снуют равазавры — стремительные ящеры, среди которых немало ядовитых." }, { 18.02, "На высоком холме разбил стоянку таурен-следопыт, выслеживающий чудовище Лар'корви, огромную тварь с зубами, подобными булатным клинкам, а на другом склоне тролль-укротитель приручает равазавров." }, { 33.14, "Только здесь среди камней находят синие кристаллы Силы." } } } },
    ["b08d7ec8"] = { d = 16.2, v = "narrator", c = { x = { { 0.00, "Уступ Коррана — второй из холмов, отделяющих горы от предгорий Хилсбрада." }, { 5.95, "Здесь укрепились люди Синдиката: их костры видно с дороги, а стражи и наёмные убийцы не спускают глаз с проходящих внизу караванов." } } } },
    ["b0ac0c6d"] = { d = 28.0, v = "narrator", c = { x = { { 0.00, "Погост Отважных — первое, что встречает путника, поднявшегося по тропе из кратера Ун'Горо в Силитус." }, { 7.68, "На месте старых эльфийских руин стоит небольшой лагерь друидов Круга Кенария, а рядом — кладбище с могилами тех, кто пал в этой пустыне." }, { 18.19, "Отсюда ночные эльфы наблюдают за силитидами и Сумеречным Молотом; именно они прорубили путь вниз, в кратер, чтобы возить припасы." } } } },
    ["b0eed56b"] = { d = 18.5, v = "narrator", c = { x = { { 0.00, "Даже практически оставшись без сил, Артас сумел опередить Иллидана и первым добраться до Ледяного Трона." }, { 8.25, "Своим руническим мечом, Ледяной Скорбью, Артас разрушил ледяную тюрьму, а потом забрал из неё зачарованный шлем и доспехи Нер'зула." } } } },
    ["b117443e"] = { d = 14.3, v = "human-male", c = { x = { { 0.00, "Ну что ж, неплохо!" }, { 1.35, "Теперь отправляйся на восток по крутым берегам." }, { 4.91, "Когда выйдешь на дорогу, ищи на обочине развалившуюся дымоходную трубу." }, { 10.30, "Там ты найдёшь старую бочку, а в ней следующую подсказку." } } } },
    ["b16238d5"] = { d = 40.6, g = 1, v = "tauren-male", c = { m = { { 0.00, "Могучие воины защищают наши дома." }, { 3.24, "Мудрые шаманы охраняют наши души и ведут нас по дороге предков." }, { 9.21, "Друиды сообщают нам волю Матери-Земли." }, { 12.87, "Но ты – охотник, а это призвание объединяет в себе умения воинов, шаманов и друидов." }, { 20.67, "Такие, как ты, являются сердцем нашего народа." }, { 24.98, "К тебе будут обращаться за советом и защитой." }, { 29.22, "Я должен удостовериться, что ты готов к этому." }, { 33.45, "Приходи в Лагерь Нараче." }, { 35.78, "-Ланко Дальний Выстрел, наставник охотников" } }, f = { { 0.00, "Могучие воины защищают наши дома." }, { 3.30, "Мудрые шаманы охраняют наши души и ведут нас по дороге предков." }, { 9.40, "Друиды сообщают нам волю Матери-Земли." }, { 13.12, "Но ты – охотница, а это призвание объединяет в себе умения воинов, шаманов и друидов." }, { 21.16, "Такие, как ты, являются сердцем нашего народа." }, { 25.57, "К тебе будут обращаться за советом и защитой." }, { 29.88, "Я должен удостовериться, что ты готова к этому." }, { 34.29, "Приходи в Лагерь Нараче." }, { 36.66, "-Ланко Дальний Выстрел, наставник охотников" } } } },
    ["b174a5a3"] = { d = 41.4, v = "narrator", c = { x = { { 0.00, "Аббатство Североземья – обитель ордена клириков, что столетия назад пришли с севера нести учение Света в молодое королевство." }, { 9.58, "В Первую войну орки разрушили аббатство, и лишь после Второй войны его отстроили заново, а братство Североземья возродилось." }, { 19.08, "Сегодня аббатство служит местом сбора и обучения всех, кто готов защищать королевство: здесь наставники всех ремёсел, библиотека с древними трактатами и гарнизон маршала Макбрайда." }, { 32.56, "Заместитель судьи Виллем следит за порядком у ворот, а в лесу вокруг стало неспокойно от волков, кобольдов и бандитов." } } } },
    ["b1c37586"] = { d = 35.6, v = "scourge-male", c = { x = { { 0.00, "Мы в жутком положении, ты не находишь?" }, { 3.38, "Отравленные проклятым принцем." }, { 6.11, "Отвергнутые всеми, кого мы любили." }, { 9.24, "Да, прекрасная Сильвана принесла нам свободу воли, но что это даёт нам сейчас?" }, { 16.15, "Мы сменили хозяев, но остались рабами." }, { 19.61, "А что если мы сами станем хозяевами?" }, { 22.90, "Ты ведь знаешь о чём я думаю, правда?" }, { 26.20, "Мы ведь чужие даже среди Отрёкшихся." }, { 29.41, "И потому нам обязательно нужно встретиться." }, { 33.27, "Я буду в церкви Могильника." } } } },
    ["b1fc19a8"] = { d = 22.9, v = "narrator", c = { x = { { 0.00, "Пока политические споры и соперничество семи людских государств разгорались и утихали, Хранители постоянно оставались на страже в своей войне против хаоса." }, { 11.93, "За годы сменилось немало Хранителей." }, { 14.76, "Одна из последних Хранителей того времени прославилась как могучая воительница, отважно противостоявшая тьме." } } } },
    ["b218ba4a"] = { d = 9.4, v = "narrator", c = { x = { { 0.00, "…и там ты найдёшь легендарный меч Командира Алых – Испепелитель." }, { 5.09, "Разве не замечательно добыть такое на обычной рыбалке?" } } } },
    ["b25aee95"] = { d = 25.5, v = "narrator", c = { x = { { 0.00, "Камен'гор — холм к северу от Стромгарда, где обосновалась часть огров клана Тяжёлого Кулака." }, { 7.01, "В склоне холма вырыт их лагерь, а рядом с ограми держатся и лесные тролли из племени Сухокожих." }, { 14.52, "Когда в Павшем Молоте узнали о союзе огров и троллей, первых воинов послали именно сюда." }, { 21.60, "Тропа через Камен'гор опасна для одинокого путника." } } } },
    ["b28aec28"] = { d = 38.4, v = "narrator", c = { x = { { 0.00, "Холмы Ледополоха раскинулись к юго-востоку от Круговзора." }, { 4.56, "Здесь живут йети Ледополоха — неповоротливые, но покрытые такой толстой шкурой, что выдерживают любые удары; матриархи и патриархи племени держатся в пещере на склоне, а молодняк бродит по округе." }, { 20.02, "Охотники приходят сюда за густым мехом и рогами йети, а в самой пещере поблёскивают ториевые жилы." }, { 27.86, "Гоблинские инженеры Круговзора тоже присматриваются к местным йети — одна из них мечтает собрать механического йети и разыграть друзей." } } } },
    ["b2dea2a9"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "Крепость Тяжёлого Кулака — укреплённое логово огров на юге нагорья, между мостом Тандола и деревней Сухокожих." }, { 8.63, "Огры устроили её в холме, обнесли частоколом и вырыли просторную пещеру, где сидит их вождь." }, { 15.84, "Клан Тяжёлого Кулака заключил союз с троллями Сухокожими против людей Стромгарда и орков Павшего Молота и вместе с ними захватил целый квартал разрушенной столицы." }, { 28.71, "Из этих пещер огры выходят в набеги, и пока крепость стоит, покоя на юге нагорья не будет." } } } },
    ["b2fb8149"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "На западной окраине Дун Морога лежит вход в Гномреган — подземную столицу гномов." }, { 6.44, "Дворфы помогли гномам заложить этот город, и веками он был чудом инженерной мысли." }, { 13.10, "Но недавно в его глубины прорвались трогги, и, чтобы выжечь их, гномы наполнили город радиацией." }, { 20.84, "Захватчиков это не остановило, а большая часть гномов погибла или превратилась в безумных лепрогномов." }, { 28.93, "Теперь у ворот бродят прокажённые и трогги, а изгнанники в Стальгорне строят машины, чтобы отбить родной дом." } } } },
    ["b31bc5e8"] = { d = 21.7, v = "narrator", c = { x = { { 0.00, "Ниже приведён список учеников, получивших Платиновую звезду в Школе Горного Дела и Геодезии Брока и заработавших Почётную Шахтную Кирку:" }, { 12.40, "Мелия Потрясательница камней," }, { 15.11, "Бардин Железняк," }, { 16.67, "Уми Триггервольт," }, { 18.31, "Руми Триггервольт," }, { 20.04, "Ворел Стальной Шип." } } } },
    ["b32e9bc4"] = { d = 22.1, v = "human-male", c = { x = { { 0.00, "...жизнь мне не мила." }, { 1.42, "Сначала она надо-мной потешалась – и вот уже обручена." }, { 5.20, "Жестокая обманщица притворялась, что любит меня, а на самом деле хотела надо-мной поиздеваться." }, { 11.76, "Меня переполняет злоба, и с каждым днём она становится всё сильнее." }, { 16.40, "Кровь, что вот-вот прольётся, – ничто в сравнении с количеством выплаканных мной слёз..." } } } },
    ["b331dc45"] = { d = 35.9, v = "narrator", c = { x = { { 0.00, "Кому: Всем новым студентам тайных искусств" }, { 3.30, "Вы должны явиться к своему преподавателю, гному Маррайку Нуррибиту, и находиться в его распоряжении до того момента, пока вы не будете призваны на помощь своему народу в освоении новых земель." }, { 18.00, "Будьте готовы к предельно жёстким экзаменам и изнурительным тренировкам одновременно с поиском жилья и (или) установкой контактов с местным населением." }, { 29.40, "С вопросами по поводу ваших обязанностей и возможностей обращайтесь к Маррику Нуррибиту." } } } },
    ["b337de40"] = { d = 35.3, v = "human-female", c = { x = { { 0.00, "Я боюсь, что война между Стоунфилдами и Маклурами убьёт начинающийся роман между Томми Джо и Мейбелл." }, { 7.10, "В такие времена, когда мрачные новости и слухи о войне доходят до нас, о молодости и любви должно заботиться." }, { 14.83, "Так вот, просьба: я прошу тебя использовать свои умения и создать зелье или эликсир, который бы помог этим молодым влюблённым встретиться друг с другом." }, { 25.54, "Спасибо тебе, Вильям." }, { 27.12, "И пожалуйста, когда найдёшь время оторваться от работы, заходи в гости." }, { 32.13, "У нас есть о чём вспомнить и посмеяться." }, { 34.85, "Милдред" } } } },
    ["b34f339f"] = { d = 21.0, v = "narrator", c = { x = { { 0.00, "Хаккар Свежеватель Душ – жестокий и кровожадный дух – решил прийти на помощь троллям." }, { 6.89, "Открыв Гурубаши секреты крови, он помог им захватить большую часть Тернистой долины и несколько островов Южных морей." }, { 16.49, "Но за свою помощь Хаккар потребовал очень дорогую цену." } } } },
    ["b3508cf3"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Когда рассветные туманы рассеялись, наступили дни, которые мы помним." }, { 6.02, "Кенарий ушёл по своим неизбывным путям." }, { 9.45, "Из-за его ухода Шу'хало, наречённые тауренами, впали в отчаянье и забыли многое из того, чему он учил." }, { 18.44, "Сменилось поколение, и они разучились говорить с деревьями и травами." }, { 24.46, "И тогда их ушей вновь начали достигать тёмные голоса из недр земли." } } } },
    ["b3572106"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "Мост Тандола — два огромных дворфийских моста через пролив, ведущие из Болотины в Нагорье Арати." }, { 7.71, "Недавно дворфы Чёрного Железа устроили здесь диверсию: один пролёт почти разрушен, и по нему уже не пройти." }, { 16.28, "Второй мост дворфы Стальгорна удерживают ценой немалой крови, ведь без него север Каз Модана отрезан от Арати." }, { 25.14, "Внизу шумит вода, а на уцелевшем пролёте стоят дозорные и смотрят на север." } } } },
    ["b382b5e2"] = { d = 9.4, v = "dwarf-male", c = { x = { { 0.00, "Но вооружение у них никудышное и нет дисциплины." }, { 3.75, "Небольшое проявление силы – вот и всё, что нужно для устранения \"угрозы\"." } } } },
    ["b3908b45"] = { d = 22.3, v = "narrator", c = { x = { { 0.00, "Ратуша Брилла — самое заметное здание городка." }, { 3.85, "С её кафедры правит мировой судья Севрен, раздавая поручения Отрёкшимся, готовым послужить общему делу." }, { 12.22, "Это редкий случай, когда ратушей управляют восставшие из мёртвых, и сюда стекаются донесения обо-всём, что творится в Тирисфале." } } } },
    ["b43742cd"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Кровавая низина — ещё один курган огров Раздробленного Хребта, укрытый в глубине гор." }, { 6.66, "Здесь клан хранит награбленное, а в одной из клеток томится пленный гном, который от безысходности приторговывает с редкими гостями." }, { 16.75, "Название низины говорит само за себя: мало кто выбирался отсюда невредимым." } } } },
    ["b44b9c4b"] = { d = 74.9, v = "narrator", c = { x = { { 0.00, "Пылающие степи — выжженная земля к северу от Красногорья, на единственной сухопутной дороге из Штормграда в Каз Модан." }, { 9.21, "Когда-то это была часть зелёных Красногорных гор, но столетия назад чародей-тан Тауриссан, вождь изгнанных дворфов Чёрного Железа, призвал на помощь силу, которой не мог управлять: из недр земли восстал повелитель огня Рагнарос." }, { 26.80, "Его пробуждение расплавило горы, обратило долины в пепел и породило вулкан, что ныне зовётся Чёрной горой." }, { 36.64, "Во Вторую войну здесь стояла Орда, и у подножия вулкана пал сэр Андуин Лотар, верховный командующий Альянса." }, { 45.08, "С тех пор небо над степями красно от извержений, а по трещинам течёт лава." }, { 50.78, "Землю делят между собой орки клана Чёрной горы под началом Ренда Чернорука, чёрные драконы Нефариана, брата Ониксии, огры и дворфы Чёрного Железа." }, { 62.31, "Альянс держится лишь в Дозоре Моргана на юго-востоке, а нейтральный Пламенеющий Стяг даёт приют редким путникам, что осмелились пройти этой дорогой." } } } },
    ["b4506611"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Кровожадный бог требовал ежедневного приношения множества жертв." }, { 5.07, "Он мечтал явиться в реальный мир и выпить кровь всех живых существ." }, { 10.42, "Но в конце концов Гурубаши поняли, что за создание им помогает, и восстали против него." }, { 17.44, "Самые сильные племена пошли войной на Хаккара и его верных жрецов Атал'ай." } } } },
    ["b46a20b1"] = { d = 41.8, v = "human-male", c = { x = { { 0.00, "Самоцвет Кора – судя по тем историям, что я слышал, эти драгоценные камни используются некоторыми заклинателями для сосредоточения в них энергии, необходимой для их магии, что придаёт им ещё больше смертоносной мощи." }, { 13.97, "Ночной эльф, которому я однажды помог, Тандрис Ветропряд, может рассказать тебе более подробно, если ты скажешь ему, что ты от меня." }, { 22.76, "Я считаю, что один из таких драгоценных камней, хранящих энергию, может быть использован для создания твоего оружия." }, { 30.43, "Когда мы говорили с ним последний раз, Тандрис был в городе Аубердин, на Тёмном берегу, в глубине осквернённого леса, что окаймляет побережье в тени родины этого ночного эльфа." } } } },
    ["b4817625"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "Нефтяное болото — чёрная топь в северных Степях, над которой торчат вышки Торговой Компании." }, { 7.30, "Гоблины качают нефть из смоляных ям, гоняют по грязи механические резаки и хранят в вёдрах с инструментами свои заготовки, а в юго-западной части болота они устроили исследовательский центр, где возятся с загадочной штуковиной под названием самофланж." }, { 26.98, "Севернее стоит башня Компании под присмотром надсмотрщика, и у Орды среди этих гоблинов есть свой тайный человек." } } } },
    ["b487b5a6"] = { d = 9.8, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.71, "Часть вторая." }, { 4.06, "Рыцарь-защитник." }, { 5.77, "Рыцарь-капитан." }, { 7.39, "Рыцарь-лейтенант." }, { 9.20, "Рыцарь." } } } },
    ["b4a76425"] = { d = 9.6, v = "narrator", c = { x = { { 0.00, "Предъявитель данного свидетельства имеет права на уважение и почтение, которого заслуживает любой первостатейный жулик и вор." } } } },
    ["b4b66e4f"] = { d = 20.1, v = "human-male", c = { x = { { 0.00, "Уважаемый получатель!" }, { 1.53, "Если ты читаешь это письмо, то я могу предположить, что ты находишься в одном из двух мест:" }, { 7.91, "(один) На южном полуострове Азшары." }, { 10.46, "(два) В брюхе скального великана." }, { 12.82, "И то, и другое одинаково нежелательно." }, { 15.50, "Следует заметить, что я некогда был в первом, а теперь – во втором." } } } },
    ["b4baa45d"] = { d = 31.2, v = "narrator", c = { x = { { 0.00, "Упрямые эльфы, не желавшие отдавать свои новые владения, использовали магию, оставшуюся от Источника Вечности, и заставили свирепых троллей отступить." }, { 11.63, "Под командой Дат'Ремара они сумели победить отряды Амани, которые десятикратно превосходили их числом." }, { 19.58, "Некоторые эльфы, помнившие древние предупреждения кальдорай, почувствовали, что использование магии может привлечь внимание изгнанного Пылающего Легиона." } } } },
    ["b4d437ec"] = { d = 26.3, v = "narrator", c = { x = { { 0.00, "Второй город-государство Аратора, Даларан, был построен севернее Строма." }, { 5.67, "Многие юные волшебники покинули ограничивавшие их границы Строма и отправились в Даларан, где они надеялись получить свободу в использовании заклинаний." }, { 17.44, "Эти маги использовали свои силы, чтобы создать зачарованные башни Даларана, и с головой погрузились в исследования." } } } },
    ["b4ecf087"] = { d = 26.4, v = "narrator", c = { x = { { 0.00, "Башня королевской стражи возвышается над дорогой к востоку от поместья Маррисов." }, { 6.34, "Некогда дозорная башня Лордерона, она была разрушена при нашествии Плети, и от неё остались лишь руины." }, { 14.52, "Теперь за эти развалины, как и за три другие башни края, сражаются Альянс и Орда: тот, кто удержит башню, получает преимущество на всех окрестных землях." } } } },
    ["b4fa9907"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "Элементалей воды, существ, целиком состоящих из воды, что прежде удавалось только могущественным магам Кирин-Тора." }, { 8.84, "Воин отправился в Зул'Гуруб, в сердце империи, чтобы продемонстрировать свои новые способности императору." }, { 17.05, "Он с лёгкостью добился аудиенции при дворе после того, как продемонстрировал своё могущество в центре столицы империи." }, { 26.03, "Его способности поразили императора Гурубаши, который немедленно предоставил ему почётное место при дворе, назвав воина Владыкой Приливов." }, { 36.75, "Прежнее его имя" } } } },
    ["b523f67b"] = { d = 49.3, v = "narrator", c = { x = { { 0.00, "Крепость Стражей Пустоты возвышается на утёсе у единственной дороги, ведущей в Выжженные земли." }, { 7.74, "Её построили после Второй войны по настоянию архимага Кадгара, чтобы никто больше не пришёл из Дренора сквозь разрушенный Тёмный портал, а гарнизон составили маги Кирин-Тора." }, { 21.88, "С тех пор здесь изучают, как энергии Портала искалечили эту землю, отбивают набеги огров и не спускают глаз с демонов на юге." }, { 32.05, "После гибели Даларана крепость держится лишь на поддержке Штормграда и караванах с припасами." }, { 39.64, "Суровые и неразговорчивые, Стражи Пустоты — единственные, кто здесь примет путника из Альянса." }, { 47.22, "Хоть и без особого радушия." } } } },
    ["b53be82d"] = { d = 19.9, v = "narrator", c = { x = { { 0.00, "За изгнанным кланом Северного Волка через портал последовали лишь несколько кланов." }, { 6.18, "Орки быстро развернули базу в Чёрных Топях, тёмной болотистой местности на востоке королевства Штормград." }, { 13.89, "Начав исследовать новую территорию, они тут же столкнулись с защитниками Штормграда." } } } },
    ["b5672618"] = { d = 17.0, v = "nightelf-female", c = { x = { { 0.00, "Гурдл," }, { 0.45, "Я с нетерпением ожидаю, когда будет готово твоё новое изобретение." }, { 5.21, "Я жду не дождусь, когда смогу с его помощью записывать результаты моих исследований." }, { 11.25, "Пожалуйста, доверь его моему посланнику." }, { 14.21, "С сердечным приветом," }, { 15.75, "Дарин Лёгкий Ветер" } } } },
    ["b5846d72"] = { d = 42.2, v = "human-male" },
    ["b5ff282d"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Поляна Когтистых Ветвей — небольшая застава ночных эльфов на севере леса, к югу от Крепости Древобрюхов." }, { 8.01, "Здесь стоит дом у лунного колодца, дежурят часовые Альянса и держат гиппогрифов, чтобы летать в Аубердин, на Лунную поляну и в Круговзор." }, { 18.42, "Для путников Альянса это единственное спокойное пристанище в северной части леса перед дорогой через туннели фурболгов." } } } },
    ["b606e1ca"] = { d = 23.9, v = "narrator", c = { x = { { 0.00, "НАСТАВЛЕНИЕ ПО ВОИНСКИМ ЗВАНИЯМ." }, { 2.73, "Ниже перечислены воинские звания Альянса, снабжённые пояснениями, касающимися народов Орды." }, { 10.41, "Звания представлены в двух разделах – офицерский и рядовой состав – и перечислены в каждом разделе в убывающем порядке, от старших к младшим." }, { 22.18, "Да здравствует Альянс!" } } } },
    ["b63bbe9a"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Пепельное Море — плоская равнина на юге ущелья, у самого подножия Чёрной горы." }, { 6.58, "Огонь и ветер давно выжгли здесь всё живое: земля ещё тлеет, и в воздухе постоянно кружат пепел и искры, забивая глаза и глотку." }, { 17.34, "Среди тлеющих пустошей бродят элементали пламени и лавовые пауки." }, { 22.87, "Путники стараются пересечь это место как можно быстрее — здесь негде укрыться и нечем дышать." } } } },
    ["b687ca6e"] = { d = 35.0, v = "named/thrall", c = { x = { { 0.00, "*Здесь покоится Громмаш Адский Крик, вождь клана Песни Войны*" }, { 6.08, "Проклятие нашего народа началось с него – и им же закончилось." }, { 12.14, "На нашем древнем языке его имя означает \"Сердце великана\"." }, { 18.02, "Он заслужил его, вступив в поединок с демоном Манноротом и купив нам свободу ценой собственной крови." }, { 27.93, "Лок'тар огар, брат." }, { 29.86, "Да пребудет вечно клан Песни Войны." }, { 33.37, "-Тралл, вождь Орды" } } } },
    ["b6c785ff"] = { d = 26.2, v = "nightelf-female", c = { x = { { 0.00, "Хотя я перестала призывать новых воргенов, их число по-прежнему растёт." }, { 4.71, "Коса словно больше не нуждается в моей помощи." }, { 7.87, "Это призывает беспокойство." }, { 9.72, "Я собрала все возможные стаи и приказала им оставаться в святилище Мел-Тандрис." }, { 14.91, "Тем временем я обыскала библиотеки Дарнасса и посоветовалась с Кругом Древних на Тёмных берегах." }, { 21.17, "Я не нашла абсолютно никаких сведений об этих воргенах." }, { 24.87, "До меня дошли слухи," } } } },
    ["b6f2581e"] = { d = 41.0, v = "narrator", c = { x = { { 0.00, "Рука Дагуна" }, { 0.99, "Древние тексты утверждают, что когти Дагуна источают яд, который не убивает жертву, но превращает её в нечто иное – представителя старых рас." }, { 12.07, "Его ценность для нас неоспорима." }, { 14.63, "Дагун живёт глубоко в море, но его регулярно выманивает на поверхность племя мурлоков Болотного Плавника в Пылевых топях." }, { 24.22, "Их оракулы призывают его при помощи зачарованных морских водорослей." }, { 29.61, "Если ты убьёшь достаточно оракулов, то соберёшь необходимое количество этих водорослей." }, { 36.36, "Положи их на алтарь мурлоков: так ты сможешь призвать Дагуна." } } } },
    ["b7c8fa5c"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "Угол Семи Ветров — маленькая, хорошо укрытая пещера в северной стене каньона." }, { 6.20, "Чтобы найти её, нужно подняться от Заставы Вольного Ветра к утёсам над иглами и идти вдоль обрыва на восток до пологого подъёма." }, { 16.15, "В пещере живут два старых таурена-отшельника: они испытывают веру, выносливость, силу и знания тех, кто приходит к ним за мудростью, и лишь прошедшему все испытания открывают последнюю тайну." } } } },
    ["b7d4694d"] = { d = 25.6, v = "narrator", c = { x = { { 0.00, "Долина Костей — ущелье на южном краю Пустошей, у самой дороги в Фералас." }, { 6.19, "Её дно усеяно костями исполинов, а у скал лежат два колоссальных скелета, чьё происхождение никому не известно." }, { 15.33, "Кентавры обходят это место стороной, считая его проклятым: здесь бродят скелеты и некроманты, а по ночам — призраки павших." } } } },
    ["b7f217a8"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Ристалище — огромная яма под открытым небом посреди разрушенных площадей Забытого Города." }, { 7.22, "Говорят, огры устраивают здесь свои игрища, а между собой сходятся и искатели приключений: на арене нет ни своих, ни чужих, и всякий, кто спрыгнет вниз, становится добычей." }, { 20.95, "Единственный выход — туннель на западной стороне, где дремлют своры гордокских гиен." }, { 27.74, "Порой на арену выпускают редкого чудовищного зверя, и тогда бой идёт не на жизнь, а на смерть." } } } },
    ["b7fa8739"] = { d = 32.2, v = "tauren-female", c = { x = { { 0.00, "День третий." }, { 1.05, "Кентавры вторглись в Мулгор!" }, { 3.44, "Наш самый мерзкий и древний враг посмел вернуться на эти равнины, откуда его однажды изгнали." }, { 11.30, "Гнев верховного вождя обрушится на них!" }, { 14.51, "Я должна узнать, что они замышляют, чтобы дать им самый верный отпор." }, { 20.35, "Если буду двигаться бесшумно, думаю, смогу подобраться достаточно близко и подслушать." }, { 27.61, "Похоже, они собираются..." }, { 29.78, "(Остальной текст залит кровью.)" } } } },
    ["b805ec74"] = { d = 29.6, v = "dwarf-male", c = { x = { { 0.00, "Господин Шипучка!" }, { 1.29, "Напиток, который вы дали моему помощнику, возымел большой успех." }, { 5.99, "Мало того что он крепок и сильно затуманивает разум, он, похоже, ещё и вызывает привыкание." }, { 12.49, "Уверен: те, кто его отведали, будут просить добавки." }, { 16.29, "Мы в долгу перед вами, Кранк." }, { 18.41, "Также приглашаю вас посетить Мерцающую равнину либо послать своё доверенное лицо, дабы воспользоваться нашими новыми возможностями в азартных играх." }, { 29.04, "--Крейвел" } } } },
    ["b85a9f95"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "Но одно племя, известное как Арати, поняло, что тролли сделались слишком серьёзной угрозой, чтобы продолжать их игнорировать." }, { 9.59, "Арати хотели подчинить себе все племена, чтобы выступить единым фронтом против троллей." } } } },
    ["b85d78fc"] = { d = 26.5, v = "narrator", c = { x = { { 0.00, "Озеро Дарроумир — одно из крупнейших озёр Восточных королевств, лежащее на юго-востоке Чумных земель." }, { 8.07, "Во Вторую войну на его водах гремели морские сражения." }, { 12.49, "Посреди озера чернеет остров Каэр Дарроу с усадьбой дома Баровых, а под ней укрылся Некроситет." }, { 20.13, "С севера в Дарроумир впадает река Тондрорил." }, { 23.70, "Ныне воды озера безжизненны и тихи." } } } },
    ["b87caeb2"] = { d = 42.5, v = "narrator", c = { x = { { 0.00, "Озеро Слёз – большое озеро на востоке Болота Печали, со всех сторон обступленное топью." }, { 7.23, "Больше тысячи лет назад изгнанные из Зул'Гуруба жрецы Атал'ай воздвигли здесь Храм Атал'Хаккара, готовя возвращение Свежевателя Душ, но Изера обрушила храм в глубину, и теперь над водой видны лишь его верхние ярусы." }, { 24.90, "Вокруг несут стражу зелёные драконы и дракониды, не пуская никого ни внутрь, ни наружу." }, { 31.88, "По берегам и на дне разбросаны артефакты Атал'ай, по которым чернокнижник Фел'зерул из Каменора пытается понять, что здесь произошло." } } } },
    ["b8e36583"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Скальное гнездовье — возвышенная долина на западе Тысячи Игл, где на скалах гнездятся гордые виверны." }, { 8.09, "Над головой парят самки, вожаки стерегут кладки, под гнёздами белеет высохшая на солнце скорлупа." }, { 15.88, "Молодых тауренов с Заставы Вольного Ветра посылают сюда за яйцами — из детёнышей вырастают ветрокрылы Орды." }, { 24.47, "Не всякий возвращается с добычей: юный Паока Ходячая Гора, приехавший изучать здешних зверей, оказался в ловушке среди разъярённых виверн." } } } },
    ["b8ea9eb6"] = { d = 39.5, v = "narrator", c = { x = { { 0.00, "Астранаар — главный город ночных эльфов в Ясеневом лесу и самое крупное поселение края." }, { 7.03, "Он стоит на острове посреди озера, прямо на большой дороге из Аубердина, и с берегом его соединяют лишь два моста." }, { 16.04, "Городом командует часовая Раэна Волкопас; она следит за фурболгами Колючего Меха, что расплодились к северу, и ищет способ ослабить порчу, расползающуюся по лесу." }, { 28.88, "Здесь же живёт Пельтур, чья дочь Релара тяжело больна." }, { 33.07, "Орда нередко совершает набеги на город, так что часовые на мостах всегда настороже." } } } },
    ["b92096a7"] = { d = 31.1, v = "narrator", c = { x = { { 0.00, "Лагерь Мор'шан — одно из крупнейших поселений Орды в северных Степях, стоящее у самой границы с Ясеневым лесом, рядом с заставой." }, { 10.01, "Здесь собираются всадники Песни Войны, готовящиеся к битвам в ущелье, а к югу от заставы обосновалась гоблинка-механик Венаки Бенике, обожающая возиться с диковинными устройствами." }, { 23.75, "Отсюда же уходят на север отряды, которые Кадрак направляет на защиту новых рубежей Орды в лесу." } } } },
    ["b960466a"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Стародревье лежит на западной окраине Хиджала, у перевалов, за которыми начинается Осквернённый лес." }, { 8.12, "Это старый лес горы, помнящий времена, когда ночные эльфы после Великого Раскола строили новые дома среди зелёных деревьев у подножия Хиджала." }, { 20.13, "Здесь, под сенью древних стволов, стоит небольшое поселение — одно из немногих обжитых мест на горе." }, { 28.40, "Отсюда видно, как далеко отступила порча: за хребтом лес искалечен Скверной, а тут он всё ещё дышит покоем." } } } },
    ["b9848074"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Малфурион был уверен, что демоны рвутся в этот мир из Источника Вечности, поэтому он стал настаивать на его уничтожении." }, { 9.32, "Но так как именно Источник являлся залогом могущества и бессмертия Ночных эльфов, такое решение привело остальных в ужас." }, { 18.85, "Однако Тиранда поняла весь замысел Малфуриона и убедила Кенария и его соратников напасть на храм Азшары и найти способ закрыть источник раз и навсегда." } } } },
    ["b9a855f9"] = { d = 16.9, v = "narrator", c = { x = { { 0.00, "Эти образцы древней глиняной посуды были найдены при раскопках Ульдамана." }, { 5.63, "Хотя на них не так много загадочных рун или иероглифов, они позволяют оценить мастерство изготовления этих повседневных предметов древней расы дворфов." } } } },
    ["b9ae5809"] = { d = 48.2, v = "narrator", c = { x = { { 0.00, "Укрытие Маршалла — пещера в северной стене кратера и единственное подобие поселения в Ун'Горо." }, { 7.40, "Сюда отступила экспедиция Маршалла, когда её лагеря на равнине растоптали ящеры: теперь исследователи живут в шатрах под сводом скалы, изучают кратер и мечтают выбраться отсюда живыми." }, { 21.91, "В глубине пещеры мерцают кристаллы Силы, над которыми колдует гномка Джей Ди, составившая руководство к пилонам, а у входа сидит гном Линкен, потерявший память и не помнящий, зачем ему меч." }, { 36.63, "Рядом жуёт листья кодо Даданга, а над лагерем кружат жутедактили, которых здесь боятся больше всего." }, { 44.52, "Отсюда летают в Прибамбасск и в Крепость Кенария." } } } },
    ["b9b42be8"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Гряда Гибели Демона поднимается к западу над одноимённым каньоном." }, { 5.15, "По её склонам бродят младшие демоны, а в толще скал зияет вход в заброшенный курган друидов, который они сделали своим логовом." }, { 15.17, "В самой глубине кургана обитает повелитель ужаса, что правит демонами Ясеневого леса, и мало кто из вошедших туда возвращался." } } } },
    ["b9ce44ea"] = { d = 37.8, v = "scourge-male", c = { x = { { 0.00, "По приказу верховного палача Хадрика ниже я привожу список предметов, требуемых для пополнения запаса Гробницы:" }, { 9.35, "Двенадцать длинных мечей" }, { 11.46, "Девять кинжалов" }, { 12.81, "Восемь круглых щитов" }, { 14.62, "Пятнадцать топоров" }, { 16.21, "Одна тысяча стрел" }, { 17.71, "Поставку запасов из данного списка считать личным распоряжением Тёмной Госпожи." }, { 24.35, "Те, кто ответственен за выполнение приказа, будут находиться под Её неусыпным наблюдением, как и те, кто будет противиться либо ещё как-нибудь препятствовать Её воле." } } } },
    ["b9e1052c"] = { d = 24.8, g = 1, v = "orc-female", c = { m = { { 0.00, "Лок-тар, брат." }, { 1.18, "Стихии указали на тебя и поручили мне показать тебе путь шамана." }, { 6.48, "Духи наших предков смотрят на нас и гордятся тем, что ты вступил в наши ряды." }, { 12.81, "Когда будешь готов, найди меня у входа в Логово." }, { 16.94, "Я обучаю там наших собратьев." }, { 19.37, "Да будет тебе попутный ветер." }, { 21.87, "-Шикрик, наставница шаманов" } }, f = { { 0.00, "Лок-тар, сестра." }, { 1.42, "Стихии указали на тебя и поручили мне показать тебе путь шамана." }, { 6.82, "Духи наших предков смотрят на нас и гордятся тем, что ты вступила в наши ряды." }, { 13.34, "Когда будешь готова, найди меня у входа в Логово." }, { 17.61, "Я обучаю там наших собратьев." }, { 20.08, "Да будет тебе попутный ветер." }, { 22.63, "-Шикрик, наставница шаманов" } } } },
    ["ba1a7214"] = { d = 22.9, v = "narrator", c = { x = { { 0.00, "Изера Спящая тоже зачаровала Древо Жизни, связав его со своим миром, астральным измерением, известным как Изумрудный Сон." }, { 9.88, "Этот огромный мир, населённый духами, не подчинялся законам физического мира." }, { 16.06, "Из своего Сна Изера могла управлять жизнью природы и развитием всего остального мира." } } } },
    ["ba273528"] = { d = 21.4, v = "narrator", c = { x = { { 0.00, "Убежище Драконьей Пасти — укромная стоянка орков клана Драконьей Пасти, спрятанная в стороне от больших дорог Болотины." }, { 9.06, "Сюда уходят отряды, разбитые у гавани и на перевалах, чтобы зализать раны и собраться с силами." }, { 16.30, "Дым костров над скалами выдаёт их лишь тому, кто знает, куда смотреть." } } } },
    ["ba2aab5b"] = { d = 28.1, v = "narrator", c = { x = { { 0.00, "В намерении добраться до Ледяной Короны и предложить свою службу Королю-личу, верховный маг миновал опустошённые войной земли Азжол-Неруба." }, { 11.32, "Кел'Тузад своими глазами увидел, насколько могучим и яростным был Нер'зул." }, { 17.43, "Он начал осознавать, сколь мудрым было его решение вступить в союз с загадочным Королём-личом и какие плоды этот союз мог принести." } } } },
    ["ba3ab6a6"] = { d = 35.9, v = "nightelf-male", c = { x = { { 0.00, "Шаэл'дрин – это дриада, охраняющая лунный колодец к северо-востоку от озера Ирисов." }, { 6.70, "Она отказывается покинуть лес и оставить его во власти порчи." }, { 11.62, "Я знаю, что у неё достаточно сил и знаний, чтобы восстановить жезл или по крайней мере сказать мне, как я могу это сделать самостоятельно." }, { 22.46, "Навершие" }, { 23.17, "Навершие попало в руки друидов Дор'Данила." }, { 26.59, "Но тут всё не так просто: эти друиды погибли." }, { 30.15, "Теперь в Дор'Даниле обитают их духи, которые не отличаются гостеприимством." } } } },
    ["ba3eb689"] = { d = 24.2, v = "orc-male", c = { x = { { 0.00, "-День шестнадцать" }, { 1.34, "Улег и Таргил вернулись с задания в доках Терамора." }, { 5.41, "В порту они видели новый корабль – \"Бешеный Воробей\"." }, { 9.70, "Корабль прибыл из Гавани Менетилов." }, { 12.51, "Завтра Улег и Таргил вернутся в доки и прокрадутся на корабль." }, { 17.43, "Они надеются найти там политические документы, раскрывающие отношения Терамора и Альянса." } } } },
    ["ba4b1979"] = { d = 23.7, v = "narrator", c = { x = { { 0.00, "Ползучие руины — остатки древнего поселения троллей у реки в центральной части Внутренних земель." }, { 7.97, "Своё имя они получили не зря: по замшелым камням ползёт живая слизь, поглотившая всё, что осталось от прежних жителей." }, { 17.40, "Здесь почти нет троллей, но нефритовые слизнюки и зелёная слизь опасны не меньше." } } } },
    ["ba4f246e"] = { d = 24.7, v = "scourge-male", c = { x = { { 0.00, "В старом доме Ивара была занята оборонительная позиция, и пока Ран стоял на страже в ожидании дальнейших атак, Эрланд продолжил миссию рекогносцировки." }, { 12.40, "Затем Эрланда прижали Ворги в северном фруктовом саду, и ему удалось спастись лишь при помощи другого агента Отрёкшихся." }, { 22.23, "Этот агент и несёт данный отчёт." } } } },
    ["ba4f68bb"] = { d = 32.5, v = "narrator", c = { x = { { 0.00, "Обескураживало могущественных троллей." }, { 2.91, "Здесь следует отметить, что последние открытия, по всей видимости, показывают, что тролли мало интересовались исследованием земель, находящихся за Великим морем." }, { 15.10, "Хотя различные племена троллей обитали на всей территории Азерота, Каз Модана и Лордерона, в новооткрытых землях Калимдора и на островах Южных морей следов их цивилизации обнаружено практически не было." }, { 30.55, "Говорит ли это о нежелании" } } } },
    ["ba714d84"] = { d = 29.1, v = "narrator", c = { x = { { 0.00, "Погибель Берена — пещера в холмах к юго-западу от Янтарной Мельницы, между главной дорогой и просёлком, ведущим от деревни." }, { 9.41, "По донесениям разведчиков, здесь укрылась нежить, готовящая нападение на Гробницу." }, { 15.60, "Это слуги Тула Когтя Ворона: чернорабочие и стражи, которых он послал с острова Фенриса на большую землю." }, { 23.77, "Жрец Тьмы Алистер хочет ударить первым и задушить их замысел в зародыше." } } } },
    ["ba8e966f"] = { d = 27.9, v = "narrator", c = { x = { { 0.00, "Под руководством мудрого шамана Дрек'Тара Тралл изучил древнюю культуру своего народа, которая была почти полностью забыта при правлении коварного Гул'дана." }, { 12.21, "Со временем Тралл сам стал могучим шаманом и занял своё законное место вождя клана." }, { 18.67, "Исполненный силы самих стихий, Тралл отправился в путь, чтобы освободить свой народ и снять с него демоническое проклятие." } } } },
    ["ba92417e"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "Тернистый холм — большое стойбище свинобразов племени Иглогривых на северном склоне горы между Перекрёстком и Дуротаром." }, { 9.68, "Его обитатели повадились грабить караваны Орды на дороге в Дуротар, и набеги ведёт Криниг Грознорыл, чьё имя не даёт покоя Торку из Перекрёстка." }, { 21.34, "На холме живут и старые мистики племени, хранящие его тайны." }, { 26.41, "Пока Криниг жив, обозам на этой дороге не будет покоя." } } } },
    ["ba9c3294"] = { d = 34.9, v = "narrator", c = { x = { { 0.00, "Лагерь Курцена стоит на севере долины, к востоку от Лагеря Повстанцев." }, { 5.48, "Полковник Курцен, некогда благородный офицер Штормграда, привёл сюда экспедицию, но попал под власть тёмной магии огра-мага с холма Мош'Огг и обратился против собственного королевства." }, { 19.56, "Его бойцы держат лесопилку, дрессируют пойманных пантер и тигров для войны и стерегут пещеру-схрон в глубине лагеря." }, { 28.58, "Повстанцы называют Курцена зверем и знают: покой не вернётся в джунгли, пока он жив." } } } },
    ["bac5198b"] = { d = 28.7, v = "narrator", c = { x = { { 0.00, "Несмотря на то что причина стала ясна, Антонидасу не удалось найти лекарства, чтобы вывести орков из этого состояния." }, { 9.20, "Кроме того, многие маги и некоторые лидеры Альянса полагали, что пытаться излечить орков – не самая благоразумная идея." }, { 18.61, "Размышляя над проблемой, Антонидас пришёл к выводу, что лекарство для орков, каким бы оно ни было, должно врачевать душу, а не тело." } } } },
    ["badcb5bf"] = { d = 19.8, v = "human-male", c = { x = { { 0.00, "Пролитие крови нашей одним из Высокого Совета Бездны есть благословение!" }, { 5.62, "Мы должны завидовать нашим павшим товарищам, ибо души их теперь покоятся во чреве самого добродетельного зверя!" }, { 14.30, "Восславим же Древних Богов!" }, { 16.45, "Восславим слуг их!" }, { 17.84, "Восславим Сумеречный Молот!" } } } },
    ["bb170aeb"] = { d = 22.0, v = "narrator", c = { x = { { 0.00, "Родник Нек'Мани бьёт высоко в скалах над Южным Гибельным берегом." }, { 5.17, "Это единственный источник чистой пресной воды к югу от Сумеречного леса, и каждый народ Азерота считает его священным для себя." }, { 15.36, "Недавно к роднику пробрался отряд наг, и они яростно охраняют воду от всех пришельцев." } } } },
    ["bb1cf8a0"] = { d = 9.7, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ." }, { 2.80, "Часть два." }, { 3.95, "Центурион." }, { 5.19, "Легионер." }, { 6.33, "Кровавый страж." }, { 8.10, "Каменный Страж." } } } },
    ["bb3d0863"] = { d = 29.5, v = "dwarf-male", c = { x = { { 0.00, "Этих грязных троггов так просто обвести вокруг пальца!" }, { 4.03, "Их ненависть к нашему роду позволяет двигать ими, как пешками." }, { 8.59, "Вообще непонятно, как они пошли хоть на какой-то союз, ведь мы для них самая страшная угроза... по крайней мере, пока." }, { 17.11, "Когда начнутся нападения, обе стороны ослабнут и не устоят перед нашим натиском." }, { 23.03, "Захватите ферму к югу от озера Ложе Хелма и ждите дальнейших указаний." }, { 28.23, "Стальгорн будет наш." } } } },
    ["bb69e2d0"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Друиды не смогли заставить себя вынести стольким сородичам смертный приговор, поэтому решили просто изгнать безрассудных Высокорождённых из своих земель." }, { 11.57, "Дат'Ремар и его сородичи были только рады освободиться от традиционного общества друидов, поэтому они быстро погрузились на флотилию судов и пустились в плавание по морям." }, { 24.57, "Никто не знал, что ждёт их за исполинским бурлящим Водоворотом, но Высокорождённые хотели найти себе новый дом, где они могли бы безнаказанно практиковать свою любимую магию." } } } },
    ["bb7769b1"] = { d = 29.9, v = "narrator", c = { x = { { 0.00, "Когда рассветные туманы рассеялись, наступили дни, которые мы помним." }, { 5.97, "Ценарион ушёл по своим неизбывным путям." }, { 9.46, "Из-за его ухода Шу'хало, наречённые тауренами, впали в отчаянье и забыли многое из того, чему он учил." }, { 18.37, "Сменилось поколение, и они разучились говорить с деревьями и травами." }, { 24.34, "И тогда их ушей вновь начали достигать тёмные голоса из недр земли." } } } },
    ["bb9aee08"] = { d = 54.2, v = "narrator" },
    ["bba6646e"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Лагерь Железного Камня — маленькая стоянка Орды на границе Мерцающей равнины." }, { 6.04, "Сюда отступили остатки боевого отряда, посланного выгнать дворфов из Карьера Ржавой Кувалды: с землекопами воины справились, но не ждали, что из пещеры на них хлынут силитиды." }, { 19.50, "Теперь уцелевшие бойцы и их кодо стерегут этот пост и ищут добровольцев среди путников, съезжающихся на гонки, чтобы очистить карьер от роя." } } } },
    ["bbc5b78b"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Довольный успехами Кел'Тузада в Лордероне, Король-лич готовился к нападению на людскую цивилизацию." }, { 6.88, "Нер'зул поместил сгустки энергии чумы в передвижные артефакты, именовавшиеся котлами чумы, и приказал Кел'Тузаду перенести их в Лордерон, где их нужно было спрятать в селениях последователей Культа." } } } },
    ["bbe2fac6"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Ночная поляна лежит на востоке леса, на узком мысе между Приютом в Ночных Лесах и заставой Расщеплённого Дерева, и подойти к ней трудно: с трёх сторон её защищают отвесные скалы." }, { 14.18, "Это самое маленькое из трёх сатирских логовищ Ясеневого леса: лишь несколько разбитых колонн среди развалин служат кровом сатирам." }, { 24.64, "Они хранят один из камней душ клана Тёмной Нити, с которым состоят в союзе, и жгут в своих ритуалах масло, украденное с лесозаготовок Песни Войны." } } } },
    ["bbe43ba8"] = { d = 37.3, v = "narrator", c = { x = { { 0.00, "Удел Эгмонда — заброшенный раскоп на юге Бесплодных земель, названный по имени дворфа-старателя, что нашёл здесь свой конец: раскоп кишел троггами, и в Стальгорне до сих пор ждут вестей о его судьбе." }, { 14.93, "Ныне по ямам и отвалам по-прежнему копошатся трогги, а среди камней бродят разъярённые каменные элементали." }, { 23.04, "Неподалёку разбил стоянку безумный дворф-отшельник, бежавший из Сумеречного Молота: он бормочет о грядущей гибели, что поднимается из-под земли, и о свитке, который отобрали у него элементали." } } } },
    ["bc3074ba"] = { d = 21.6, v = "dwarf-male", c = { x = { { 0.00, "Я повёл группу по направлению к морю, надеясь, что линия берега послужит нам защитой от ящеров." }, { 6.43, "В спешке мы забрались слишком далеко к северу, на особенно высокий холм." }, { 11.33, "Это было ошибкой." }, { 12.62, "Я был виноват." }, { 13.60, "Мы остановились прямо перед обрывом, заканчивающимся отвесной скалой, а ящеры были всего в нескольких шагах позади нас." } } } },
    ["bc491471"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Лагерь Вург расположился среди Знойных Песков, к востоку от Каргата, в западной части пустыни." }, { 7.39, "Это одна из четырёх стоянок огров-Гнилобрюхов: здесь стоят их грубые шатры, а вокруг бродят громилы племени." }, { 15.90, "Всерьёз огры не угрожают ни дворфам, ни оркам, но нападают на караваны и одиноких путников, и дорога мимо лагеря считается неспокойной." } } } },
    ["bc4af43c"] = { d = 10.8, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.77, "Часть один." }, { 3.96, "Главнокомандующий." }, { 5.81, "Фельдмаршал." }, { 7.10, "Маршал." }, { 7.93, "Командир." }, { 8.94, "Лейтенант-командор." } } } },
    ["bc518815"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Западные комбинации кристаллов." }, { 2.53, "Существует два возможных эффекта: один повышает вашу защиту от урона, второй ослабляет защиту противника." }, { 11.08, "КРИСТАЛЛ-ХРАНИТЕЛЬ: Требуются красные и зелёные кристаллы." }, { 15.71, "Повышает вашу характеристику \"броня\"." }, { 18.75, "КРИСТАЛЛ-ГУБИТЕЛЬ: Требуются синие и красные кристаллы." }, { 23.24, "Может снизить характеристику \"броня\" выбранной цели." } } } },
    ["bc628ab0"] = { d = 16.1, v = "narrator", c = { x = { { 0.00, "Кил'джеден знал, что Орда, наконец, готова." }, { 3.71, "Орки стали мощнейшей силой Пылающего Легиона." }, { 7.73, "Коварный демон рассказал обо-всём своему повелителю, и Саргерас согласился, что час расплаты настал." } } } },
    ["bcc96b8d"] = { d = 31.8, v = "human-male", c = { x = { { 0.00, "Не понимаю, как мне удалось выжить в ту ночь." }, { 3.10, "Я всегда был осторожным, не ввязывался в драки и не попадался в ловушки." }, { 8.11, "Я даже получил за это своё прозвище." }, { 10.70, "Наверное, эта природная осторожность спасла меня от смерти..." }, { 15.07, "Или Коса, которую я вытащил из хлама." }, { 17.80, "Хотя вряд ли сама Коса, её я потерял во время своего отчаянного бегства." }, { 22.93, "Но если воргены появились в Сумеречном лесу из-за меня, тогда, похоже, они оказали мне ответную любезность." }, { 30.59, "Чтоб им провалиться!" } } } },
    ["bccdbd25"] = { d = 16.4, v = "narrator", c = { x = { { 0.00, "Сотня людских магов и множество эльфийских волшебников вызвали ярость небес и напустили пламя на армию троллей." }, { 9.54, "Огонь стихий лишал троллей возможности исцеления ран, сжигая их изнутри и снаружи." } } } },
    ["bced6fdf"] = { d = 36.8, v = "narrator", c = { x = { { 0.00, "Начать процесс охлаждения, который в этот момент потребует примерно от одной до двух минут (в зависимости от ситуации) для своего завершения." }, { 10.20, "ВАЖНОЕ ЗАМЕЧАНИЕ: главным силовым рубильником можно манипулировать, только когда три контрольных клапана на самих машинах выключены." }, { 19.81, "Выключать эти клапаны можно в любом порядке." }, { 23.15, "Первый – ГЛАВНЫЙ КОНТРОЛЬНЫЙ КЛАПАН, который можно найти у основания большой вертикальной дымовой трубы." }, { 30.80, "Далее – КЛАПАН УПРАВЛЕНИЯ ТОПЛИВОМ, его можно найти на большой трубе, которая ведёт" } } } },
    ["bcf82165"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Здесь, среди отвесных стен каньона, испокон веков гнездится стая гарпий Кровавой Ярости." }, { 7.92, "Скалы усеяны их гнёздами, а на дне ущелья белеют кости тех, кто не сумел уйти." }, { 14.80, "Мало кто возвращался отсюда живым, и те, кому это удалось, советуют одно: не поднимать шума." } } } },
    ["bcfdddcb"] = { d = 31.8, v = "human-male" },
    ["bd39f105"] = { d = 26.6, v = "nightelf-female" },
    ["bd59f608"] = { d = 16.2, v = "dwarf-male", c = { x = { { 0.00, "Опалённый паучий клык:" }, { 1.62, "Огневитовая жила, найденная в Пещере Тельгена, сожгла живших по соседству пауков." }, { 7.78, "Яд из их жвал кипит и вступает в реакцию с самими их клыками, в результате чего получается очень стойкое вещество." } } } },
    ["bd7f6872"] = { d = 36.8, v = "narrator", c = { x = { { 0.00, "Поле Маннорок — выжженная равнина к югу от Заставы Скитающихся Духов, названная в честь повелителя преисподней Маннорота." }, { 9.84, "Среди эльфийских руин пылают порталы, через которые Пылающий Клинок призывает инферналов, суккубов, гончих Скверны и стражей ужаса." }, { 20.72, "Воздух густ от Скверны, и на плечи путника ложится мертвенная тяжесть." }, { 26.45, "Демонами повелевает лорд Азреток, скрепляющий договоры с культистами, и сколько бы порталов ни запечатали, новые открываются вновь." } } } },
    ["bd8301ae"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Станция Альгаз — застава горных пехотинцев в северо-западной части Лок Модана, к востоку от Северных врат и к югу от перевала Дун Альгаз, по которому она и названа." }, { 12.06, "Здесь у сторожевой башни несёт службу горный пехотинец Грингер Грозовая Вершина, а оружейник чинит доспехи путникам." }, { 20.60, "Пехотинцы приглядывают за дорогой к Болотине и за выработанным рудником у Серебряного ручейка, куда пробрались кобольды." } } } },
    ["bd9d66a7"] = { d = 17.2, v = "narrator", c = { x = { { 0.00, "Среди политической неразберихи многие начальники лагерей стали замечать изменения в поведении пленных орков." }, { 8.68, "Число попыток побега и даже драк между заключёнными резко уменьшилось." }, { 14.27, "Орки стали спокойными и безразличными." } } } },
    ["bdabd758"] = { d = 27.3, g = 1, v = "nightelf-female", c = { m = { { 0.00, "Надеюсь, ты получил мой знак." }, { 2.08, "Я пишу тебе, потому что нашему народу нужны мечники, копьеносцы и другие отважные воины." }, { 8.58, "С тех пор как нам стало известно о других расах Азерота, мы ещё больше нуждаемся в сильных защитниках." }, { 15.86, "Это твой путь." }, { 16.90, "Твоё призвание." }, { 18.00, "Я расскажу тебе больше, но только при встрече с глазу на глаз." }, { 22.49, "Ищи меня на нижнем уровне Альдрассила." }, { 25.35, "-Алайссия, наставница воинов" } }, f = { { 0.00, "Надеюсь, ты получила мой знак." }, { 2.10, "Я пишу тебе, потому что нашему народу нужны мечники, копьеносцы и другие отважные воины." }, { 8.47, "С тех пор как нам стало известно о других расах Азерота, мы ещё больше нуждаемся в сильных защитниках." }, { 15.61, "Это твой путь." }, { 16.62, "Твоё призвание." }, { 17.71, "Я расскажу тебе больше, но только при встрече с глазу на глаз." }, { 22.10, "Ищи меня на нижнем уровне Альдрассила." }, { 24.91, "-Алайссия, наставница воинов" } } } },
    ["bdb9a437"] = { d = 41.7, v = "narrator", c = { x = { { 0.00, "Стромгард стоит на юго-западе нагорья, там, где Торадин мечом очертил границы своей столицы Строма." }, { 8.40, "Тысячелетия этот город был сердцем империи Аратор, а затем столицей королевства Стромгард, чьи короли из рода Троллебоев вели людей во Вторую войну." }, { 20.84, "Ныне город разграблен и расколот на три части: цитадель держит Синдикат, квартал магов заняли огры с троллями, а последний уголок удерживают верные солдаты Стромгарда." }, { 34.86, "В склепе Троллебоев по-прежнему покоится Трол'калар, легендарный меч, гроза троллей." } } } },
    ["bdd2ed79"] = { d = 24.6, v = "dwarf-male", c = { x = { { 0.00, "Некоторое время назад в штабе Лиги исследователей в Стальгорне нам читал лекцию главный археолог Седой Ус." }, { 7.44, "Старикан упоминал такое божество, почитаемое странными эльфами Дарнасса за его, по слухам, бескорыстную натуру..." }, { 15.32, "Ба!" }, { 15.57, "Один момент." }, { 16.51, "Я слышу хрюканье за моей палаткой." }, { 18.95, "Наверняка это просто щетинистые вепри пытаются добраться до моего запаса яблок..." } } } },
    ["bddbb07c"] = { d = 70.4, v = "narrator", c = { x = { { 0.00, "Тирисфальские леса лежат на северном побережье Лордерона, там, где некогда билось сердце людского королевства." }, { 8.94, "Чума Короля-лича прошла по этим холмам, и с тех пор небо здесь вечно затянуто зеленоватой мглой, а деревья цепляются за последние крохи жизни." }, { 20.51, "Теперь это земля Отрёкшихся: восставшие из мёртвых, сбросившие волю Плети, они присягнули Тёмной Госпоже Сильване Ветрокрылой и устроили столицу в Подгороде, под руинами Лордерона." }, { 35.02, "Но покоя здесь нет." }, { 36.56, "С востока, из Чумных земель, мимо защитников Бастиона просачиваются приспешники Плети, а на заброшенных фермах бродят безмозглые мертвецы." }, { 47.77, "На северо-востоке, в Монастыре Алого ордена, укрепились живые фанатики, для которых всякая нежить достойна лишь огня." }, { 57.37, "И всё же у этого угрюмого края есть своя мрачная красота: каменистый северный берег, тихие улочки Брилла и обветшалые мельницы Агамондов ещё помнят иные времена." } } } },
    ["be005400"] = { d = 20.5, v = "narrator", c = { x = { { 0.00, "Высокий отрог — холм, нависающий над городком Хилсбрад и полями предгорий." }, { 5.81, "Отсюда открывается вид на крепость Дарнхольд на востоке, а рядом начинается тропа к проходу в Альтеракскую долину." }, { 14.75, "На скалистых склонах живут горные львы, а по вечерам с гор спускаются йети." } } } },
    ["be68f082"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Плато звездочётов лежит к северо-западу от Громового Утёса." }, { 4.60, "Здесь швартуется неборез — летучий корабль небеснорождённых с далёкого острова Зефрис, и Ваятели ветра, первопроходцы этого народа, ступают отсюда на землю Азерота." }, { 17.33, "Алаана Штормовой Полёт встречает прибывших в Мулгоре, а юные шаманы возвращаются с этого плато домой, чтобы ответить на зов огня." } } } },
    ["be892041"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Высшие эльфы, ведомые Дат'ремаром, покинули Калимдор и миновали Водоворот с его бурями." }, { 7.09, "Их флот много долгих лет плавал среди обломков старого мира, они открыли множество тайн и потерянных королевств." }, { 16.22, "Дат'ремар, взявший имя Солнечный Скиталец (или \"тот, кто ходит весь день\"), искал места с большей магической энергией, чтобы построить там новое королевство для своего народа." } } } },
    ["bebe12f1"] = { d = 35.3, g = 1, v = "dwarf-male", c = { m = { { 0.00, "В это время, когда Божественный Свет согревает наши души, а каждый день дарит нам новые открытия, особенно хорошо быть одним из сыновей Стальгорна." }, { 10.39, "Лига Исследователей с каждым днём всё более продвигается вперёд, находя давно потерянные ответы на ещё более древние вопросы." }, { 19.13, "А ещё теперь среди нас есть ты, способный помочь в борьбе с троггами и всеми другими врагами." }, { 25.65, "Найди меня, когда у тебя будет время." }, { 28.44, "Я буду в Старой Наковальне, что находится выше по склону." }, { 32.49, "- Брансток Халдер, наставник жрецов" } }, f = { { 0.00, "В это время, когда Божественный Свет согревает наши души, а каждый день дарит нам новые открытия, особенно хорошо быть одной из дочерей Стальгорна." }, { 10.51, "Лига Исследователей с каждым днём всё более продвигается вперёд, находя давно потерянные ответы на ещё более древние вопросы." }, { 19.35, "А ещё теперь среди нас есть ты, способная помочь в борьбе с троггами и всеми другими врагами." }, { 25.94, "Найди меня, когда у тебя будет время." }, { 28.76, "Я буду в Старой Наковальне, что находится выше по склону." }, { 32.86, "- Брансток Халдер, наставник жрецов" } } } },
    ["becc55b8"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Призывы Короля-лича не остались незамеченными, особенно в небольшой группе могущественных личностей." }, { 7.58, "Среди них был верховный маг Кел'Тузад, влиятельный участник правящего круга Даларана, Кирин-Тора." }, { 14.90, "Его стремление овладеть всеми видами волшебства нарушало правила Кирин-Тора, возбраняющие практиковаться в чёрной магии." }, { 23.98, "Кел'Тузад оставил Кирин-Тор, порвал все связи с обычным миром и поклялся стать прилежным учеником Короля-лича." } } } },
    ["beccdb7c"] = { d = 32.3, v = "bloodelf-male", c = { x = { { 0.00, "*Страницы покрыты древними эльфийскими рунами.*" }, { 3.68, "Эти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня." }, { 15.20, "Да не получат наши враги никогда доступ к этим письменам." }, { 19.76, "Да доживу я до тех пор, когда бледный свет луны вновь осветит Кель'Талас." }, { 25.38, "Да умру я во имя Кель'таса." }, { 27.55, "Да буду убивать я во славу Иллидана." }, { 30.43, "-Мастер Кариэль Винтхалус" } } } },
    ["bf69ac50"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Таверна «Большая вода» — сердце Гавани Менетилов." }, { 3.97, "У её очага сходятся моряки, ждущие корабля, солдаты гарнизона и путники, только что сошедшие с трапа." }, { 11.98, "Здесь можно снять комнату, выучить основы врачевания и услышать последние слухи со всей Болотины, а то и угодить в драку, которые в этом заведении не редкость." } } } },
    ["bf72e1f0"] = { d = 48.1, v = "narrator", c = { x = { { 0.00, "Лагерь Братства Тория стоит на скальном уступе в северной части ущелья, над самым Котлованом." }, { 7.36, "Его основали дворфы Чёрного Железа, порвавшие со своим кланом: они не пожелали служить Рагнаросу и живут своим ремеслом." }, { 16.82, "Братство славится кузнецами — говорят, это лучшие мастера Азерота, хранящие секреты, добытые в Огненных Недрах." }, { 25.59, "Лагерь открыт и для Альянса, и для Орды: здесь есть кузница, торговцы и площадка, откуда грифоны и ветрокрылы летают в Стальгорн, Каргат и Пылающие степи." }, { 37.43, "Отсюда надзиратель Братства и его дозорные следят за делами Чёрного Железа и щедро платят тем, кто готов сражаться с их бывшими собратьями." } } } },
    ["bf732235"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Хотя империи Гурубаши и Амани недолюбливали друг друга, конфликты между ними были редкостью." }, { 7.22, "Их общим врагом был Аз'Акир – цивилизация насекомоподобных существ с дальнего запада." }, { 13.75, "Разумные насекомые отличались невероятной агрессивностью и стремились искоренить все остальные формы жизни Калимдора." } } } },
    ["bfbd5440"] = { d = 32.1, v = "dwarf-male", c = { x = { { 0.00, "Отчёт о положении дел с троллями из племени Мерзлогривов в регионе Холодной долины." }, { 5.75, "Подготовлен Грелином Белобородом, особым посланником Сената." }, { 9.98, "Я потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфийским поселениям в этом районе." }, { 22.49, "Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии." }, { 28.50, "Учитывая помощь горных пехотинцев, уже находящихся в" } } } },
    ["bfc8161f"] = { d = 39.7, v = "narrator", c = { x = { { 0.00, "Перед вами руины Лордерона — всё, что осталось от столицы величайшего людского королевства." }, { 7.29, "Город пал, когда принц Артас, вернувшись с севера, убил своего отца, короля Теренаса Менетила, и открыл ворота Плети." }, { 16.81, "Дворец стоит до сих пор, и в его пустых залах, говорят, ещё звучат отголоски того дня: приглушённые голоса во дворе, звон колоколов, приветственные крики в честь принца." }, { 30.16, "Теперь под руинами раскинулся Подгород, столица Отрёкшихся, а наверху, по разорённым дворам, всё ещё бродят мертвецы Плети." } } } },
    ["bfd43961"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Каранос — самый большой городок Дун Морога, укрытый среди горных вершин к северу от Холодной долины." }, { 8.00, "Здесь стоят кузница, гномья мастерская и знаменитая таверна «Громоварка»." }, { 13.73, "Сюда докладывают новобранцы из Старой Наковальни, и здесь Сенир Белобород собирает донесения о троллях и троггах для Стальгорна." }, { 23.72, "С запада к городу подступает Серая берлога, полная вендиго, а на севере, на Мерцающем хребте, закрепились тролли Мерзлогривы." }, { 33.56, "При всём своём уюте Каранос живёт как передовой пост." } } } },
    ["bfdabf97"] = { d = 30.4, v = "narrator", c = { x = { { 0.00, "В северо-западной части горы, среди хребтов, укрыта Колыбель Спокойствия — тихая долина с озером, к востоку от Стародревья." }, { 10.46, "Название говорит о покое, которого так не хватает остальному Хиджалу." }, { 16.30, "Вода здесь чиста, лес густ, и друиды видят в этой долине залог того, что гора исцелится." }, { 23.81, "Для путника, уставшего от выжженных склонов, это место, где можно перевести дух." } } } },
    ["bffca993"] = { d = 31.4, v = "human-male", c = { x = { { 0.00, "*Генерал Туралион Правая рука лорда Андуина Лотара.*" }, { 4.21, "*Рыцарь ордена Серебряной Длани.*" }, { 6.82, "*Главнокомандующий экспедиции Альянса, которая отправилась на Дренор, родной мир орков.*" }, { 13.71, "*Предположительно погиб.*" }, { 15.52, "Эзарус тар но-Дарадор – \"Кровью и честью мы служим\"." }, { 19.34, "Ты был десницей справедливости и добродетели, старый друг." }, { 23.48, "Твоё имя всегда будет почитаться в наших землях." }, { 27.10, "- Лорд Утер Светоносный, рыцарь ордена Серебряной Длани" } } } },
    ["c01c28d7"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "Дозорная башня – одна из сторожевых башен стражи Штормграда на востоке Элвинна." }, { 6.17, "Такие башни хорошо защищены и стоят на страже людских земель." }, { 11.02, "Эта следит за гноллами и орками, что могут прийти из Красногорья, за нежитью из Сумеречного леса и за бандитами из окрестных лагерей." } } } },
    ["c02b5da6"] = { d = 35.5, v = "narrator", c = { x = { { 0.00, "Алтарь Зула — ступенчатая пирамида племени Порочной Ветви к югу от Джинта'Алора." }, { 6.34, "На её вершине тролли совершают жертвоприношения, а верховный хранитель стережёт священный молот, которым, если верить старым записям, можно пробудить силу алтаря в Джинта'Алоре и выковать молот Зул'Фаррака." }, { 22.42, "Название алтаря, как считают, восходит к Зулу, пророку троллей." }, { 27.42, "У подножия пирамиды бродят охотники и ворожеи, и здесь, как и в Джинта'Алоре, нет пощады никому из чужаков." } } } },
    ["c034ceeb"] = { d = 15.4, g = 1, v = "human-male" },
    ["c04765a6"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Карьер Грязнули лежит на востоке ущелья, у дороги к Выжженной долине." }, { 5.48, "Когда-то это был раскоп дворфов Стальгорна: археологи из Зала Исследователей искали здесь древние реликвии, и, как говорят, именно в этой яме были найдены камни Сунтары." }, { 18.77, "Ныне карьером владеют дворфы Чёрного Железа, и их надсмотрщики с плетьми гонят по ямам невольников." }, { 26.51, "На дне карьера лежит раненый археолог Дориус — единственный, кто остался от экспедиции; остальных угнали в Котлован." } } } },
    ["c0546f33"] = { d = 25.7, v = "narrator", c = { x = { { 0.00, "Лагерь Апарахе на юго-востоке гор был мирной деревней тауренов, пока сюда не пришли воины Зловещего Тотема под началом Грундига Тёмное Облако." }, { 11.98, "Почти всех жителей перебили; уцелевший Макаба Плоское Копыто скитается у границы гор и ищет свою дочь Кайю." }, { 21.01, "Теперь у большого красного тотема хозяйничают захватчики." } } } },
    ["c0759c14"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Восточная комбинация кристаллов" }, { 2.67, "Существует два возможных эффекта: один оказывает положительный эффект на дух, второй создаёт щит, наносящий урон." }, { 12.14, "КРИСТАЛЬНАЯ СИЛА: требуются синие и зелёные кристаллы." }, { 16.72, "Повышает вашу характеристику \"дух\"." }, { 19.69, "КРИСТАЛЬНЫЙ ШИП: требует синих и жёлтых кристаллов." }, { 23.97, "Создаёт щит, который будет наносить урон атакующим." } } } },
    ["c0c6f36c"] = { d = 45.3, v = "narrator", c = { x = { { 0.00, "Даларан — город магов, столица Кирин-Тора, что стоит на южном берегу озера Лордамер." }, { 6.95, "В Третью войну демон Архимонд обратил его в развалины, и уцелевшие волшебники накрыли город непроницаемым лиловым куполом, чтобы отстроить его в тайне от чужих глаз." }, { 20.19, "Сквозь мерцающую завесу не пройти никому, а снаружи, среди разрушенных окраин, несут дозор волшебники Даларана и их каменные слуги-элементали." }, { 31.49, "Здесь же обосновался верховный маг Ансирем Руноплет, чьи мысли заняты пропавшей в далёких джунглях дочерью." }, { 39.85, "Маги Даларана враждебны Отрёкшимся и ревниво следят за берегами озера." } } } },
    ["c0d17d85"] = { d = 29.3, g = 1, v = "goblin-female", c = { m = { { 0.00, "Привет, Фелнок!" }, { 1.17, "Мои исследования в Пылающих степях продвигаются отлично." }, { 5.28, "Я весьма обязана путнику за его помощь!" }, { 8.22, "Вот что мне нужно, чтобы продолжать исследования:" }, { 11.74, "Бумбербитцель из рулонной стали," }, { 14.09, "Ледяной гаечный ключ номер семнадцать," }, { 16.90, "Двенадцать фунтов утиных перьев" }, { 19.25, "И банку твоего клея." }, { 20.81, "Спасибо тебе большое, Фелнок, когда мы увидимся снова, напомни, чтобы я не подкладывала уголь в твои ботинки!" }, { 28.84, "— Тинки" } }, f = { { 0.00, "Привет, Фелнок!" }, { 1.18, "Мои исследования в Пылающих степях продвигаются отлично." }, { 5.29, "Я весьма обязана путнику за её помощь!" }, { 8.10, "Вот что мне нужно, чтобы продолжать исследования:" }, { 11.63, "Бумбербитцель из рулонной стали," }, { 13.99, "Ледяной гаечный ключ номер семнадцать," }, { 16.80, "Двенадцать фунтов утиных перьев" }, { 19.15, "И банку твоего клея." }, { 20.72, "Спасибо тебе большое, Фелнок, когда мы увидимся снова, напомни, чтобы я не подкладывала уголь в твои ботинки!" }, { 28.76, "— Тинки" } } } },
    ["c0dabe69"] = { d = 37.5, v = "human-male", c = { x = { { 0.00, "Приветствую тебя." }, { 1.26, "Мне удалось-таки узнать кое-что из той записки." }, { 4.52, "О Джеймсе выяснилось немногое." }, { 6.65, "Но зато о семье Амелии мне удалось разузнать больше." }, { 10.36, "Она и её дети не пережили войну, а вот её брат, Александр Кальдер, выжил; найти его ты можешь в Заброшенном гроте, что в Стальгорне; там он изучает зловещую магию Пылающего легиона." }, { 22.91, "Ещё она близко общалась с сестрой, Дези Холодная, которая теперь живёт в Оргриммаре и занимается проблемой Низины Арати." }, { 31.32, "Когда будешь поблизости, найди одного из них." }, { 34.52, "Уверен, им будет интересно узнать об Амелии." } } } },
    ["c0dd9032"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "И воды упали на джунгли, смывая всё на своём пути." }, { 4.90, "Тролли и звери кричали от ужаса и муки, пока воды терзали и поглощали их." }, { 12.17, "Многие Гурубаши гадали, за что океан обрушился на них, но они умерли, так ничего и не узнав." }, { 21.10, "И наконец, достигнув гор, воды остановились." }, { 25.39, "Умиротворённые, они вернулись в свои берега, оставляя за собой смерть." }, { 32.13, "Воды отступили, но И'лалай они окружили и затопили навсегда." } } } },
    ["c0f42f54"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Холмы Древолапов — лесистые взгорья на юго-востоке Фераласа, родные земли гноллов клана Древолапов." }, { 7.70, "В последнее время гноллы будто обезумели: их набеги на Лагерь Мохаче становятся всё отчаяннее, и Хадокен Быстрый Странник собирает воинов, чтобы отбросить их." }, { 19.92, "Но по лагерям Древолапов ходят слухи, что гноллов гонит на север нечто, вылезшее из-под земли на юге." }, { 27.83, "Недавно в холмах появились и горные великаны, спустившиеся с вершин." } } } },
    ["c12c2ecb"] = { d = 20.2, v = "dwarf-male", c = { x = { { 0.00, "Наш поход может продлиться всего несколько дней и оказаться приятной прогулкой, а может завершиться кровопролитным сражением, в котором я погибну." }, { 10.62, "Если уж мне суждено пасть, сражаясь за Альянс, то я готов." }, { 14.84, "Меня не терзают никакие сомнения или колебания, моя храбрость несокрушима." } } } },
    ["c12c5d0d"] = { d = 30.0, v = "narrator", c = { x = { { 0.00, "Первые удары Плети по Дарроуширу были сравнительно редкими и слабыми." }, { 5.56, "Отдельные группы скелетов и ходячих трупов, нападавшие на окрестности деревни, легко отгонялись её защитниками." }, { 14.33, "Но Плеть не собиралась отступать, и вскоре на поселение обрушилась вторая волна атак." }, { 21.03, "Отборные вурдалаки под предводительством лорда Хоргуса спустились с холмов и вступили в бой с защитниками Дарроушира." } } } },
    ["c1308c99"] = { d = 25.6, v = "narrator", c = { x = { { 0.00, "Шаол'вата — руины лесных троллей на северо-востоке Внутренних земель, некогда храм империи Амани." }, { 7.65, "Ныне здесь обосновались тролли племени Порочной Ветви: воины и ворожеи стерегут разрушенные постройки на берегу реки, недалеко от рощи Серадан." }, { 18.87, "До деревни Сломанного Клыка отсюда недалеко, и дозоры на обеих сторонах не смыкают глаз." } } } },
    ["c1322ac5"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "На горном уступе в середине Хиджала стоит Святилище Авианы — Древней, повелительницы всех крылатых созданий Азерота и матери гарпий." }, { 11.03, "В Войну Древних Авиана сражалась против Пылающего Легиона и пала, сбитая с неба демонами; с тех пор её чтят друиды Когтя, принимающие облик птиц." }, { 23.11, "Это тихое место среди сожжённых склонов, и ветер с вершины доносит сюда дыхание Нордрассила." }, { 30.91, "Друиды приходят сюда, чтобы почтить память Древней и просить её благословения." } } } },
    ["c13346f1"] = { d = 37.8, v = "gnome-male", c = { x = { { 0.00, "Дорогой дневник, прости, я заснул." }, { 2.50, "Когда я в ярости летал и разбрасывал листы из этой глупой книги, то увидел под собой в Теснине Зловещего Шёпота демона и решил сделать из страниц первой главы магическое торнадо, чтобы разорвать его тело на миллион кусочков!" }, { 18.60, "Я словно заново родился." }, { 20.40, "Магия плюс бумага равно веселье." }, { 22.77, "Этот случай меня изрядно развеселил, и я решил полететь в Восточные королевства." }, { 28.54, "Первой моей остановкой были Огненные Недра." }, { 31.75, "Нарайн постоянно о них твердил!" }, { 33.99, "\"А вот когда я был в Огненных Недрах, да в Рагнаросе...\"" } } } },
    ["c136a0ad"] = { d = 20.4, v = "narrator", c = { x = { { 0.00, "Клан Бронзобородов под управлением тана Мадорана Бронзоборода имел хорошие связи с королём и был защитником Стальгорна." }, { 8.99, "Клан Громового Молота, управляемый таном Кардросом Громовым Молотом, населял холмы и утёсы у подножья горы и пытался добиться большей власти в городе." } } } },
    ["c14495c4"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Всё более снедаемый тревогой и тоской, Саргерас был вынужден по приказу титанов вступить в бой с ещё одной группой тварей, жаждавшей разрушения: Натрезим." }, { 12.72, "Эта тёмная раса демонов-вампиров (также известных как повелители ужаса) завоевала множество населённых миров, вселяясь в их обитателей и склоняя их ко тьме." } } } },
    ["c16cc2c6"] = { d = 5.4, v = "narrator", c = { x = { { 0.00, "Элиза." }, { 0.71, "Возлюбленная жена, пусть земля утолит твой голод." } } } },
    ["c18a7251"] = { d = 11.1, v = "human-male", c = { x = { { 0.00, "Матиас Шоу послал какого-то рассыльного убить меня..." }, { 3.92, "*Текст неразборчив*" }, { 5.68, "Теперь он бродит снаружи." }, { 7.97, "Тупой, безжизненный чурбан." }, { 10.41, "Ха-ха-ха!" } } } },
    ["c1e34c02"] = { d = 28.0, v = "narrator", c = { x = { { 0.00, "Империя росла и охватывала все новые земли, а юные маги двинулись на юг." }, { 6.00, "Используя свои мистические силы, маги защищали своих собратьев от диких животных и сделали возможной постройку новых городов-государств в диких местах." }, { 18.60, "Но в то время как их силы росли, маги становились всё более высокомерными и всё больше отдалялись от остальных людей." } } } },
    ["c1ea0851"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "На протяжении многих лет ночные эльфы работали не покладая рук, чтобы восстановить то, что осталось от их древней родины." }, { 9.37, "Они оставили свои разрушенные храмы и дороги зарастать и построили новые дома среди зелёных деревьев и тенистых холмов у подножия горы Хиджал." }, { 20.65, "Мало-помалу из своих укрытий выбрались и драконы, пережившие Великий Раскол." } } } },
    ["c2467367"] = { d = 38.5, v = "narrator", c = { x = { { 0.00, "Мерцающая равнина — необъятная соляная пустошь на юго-востоке Тысячи Игл, у границы с Танарисом." }, { 8.11, "Когда-то здесь плескалось озеро; о нём напоминает остов парусника, застрявший в соли на севере равнины." }, { 16.74, "Ни деревца, ни травинки — только слепящая белизна, по которой бродят василиски, скорпиды, черепахи и стервятники." }, { 26.21, "Ровное дно высохшего озера приглянулось гоблинам и гномам: они устроили здесь Виражи на Миражах, и вся округа усеяна воронками и обломками их машин." } } } },
    ["c24bf40f"] = { d = 43.2, v = "narrator", c = { x = { { 0.00, "Джеденар лежит на западе леса, среди древних руин ночных эльфов и двух друидских курганов." }, { 7.55, "Имя ему дали в честь Кил'джедена, и служат здесь его почитатели — чернокнижники Совета Теней, орки и Отрёкшиеся, окружённые гончими Скверны, суккубами и сатирами." }, { 20.72, "В центре руин стоит лунный колодец с отравленной водой, и отсюда Совет Теней разносит порчу по лесу." }, { 29.15, "Друиды Изумрудного Круга открыто воюют с сектантами, и Грета Замшелое Копыто ищет тех, кто поможет проредить их ряды." }, { 38.84, "Под руинами скрыты Оплот Теней и Святилище Искусителя." } } } },
    ["c25f9d96"] = { d = 41.6, v = "narrator", c = { x = { { 0.00, "Порт Картеля — маленькая гоблинская гавань на восточном берегу Танариса, соединённая дорогой с Прибамбасском." }, { 8.06, "У причала ждут корабли, ходящие к далёким островам Южных морей, но делиться судами с другими народами картель не спешит." }, { 17.08, "В посёлке живут гоблины и мирные тролли: одни рыбачат, другие стерегут склады от пиратов Южных морей, чьё логово лежит южнее по берегу." }, { 27.38, "Здесь же обитает тролль Йе'кинья, собирающий духов ради старых тайн своего народа, а начальник отдела безопасности Чепухастер обещает награду за пиратские шляпы и за голову Андре Огнебородого." } } } },
    ["c2680c65"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Лагерь Повстанцев стоит на самом севере долины, у дороги из Сумеречного леса." }, { 5.76, "Здесь укрылись солдаты Штормграда, некогда пришедшие в джунгли с экспедицией полковника Курцена." }, { 12.77, "Когда их командир обезумел и обратился ко злу, часть отряда во главе с Дореном взбунтовалась и ушла на запад." }, { 20.72, "Повстанцы по-прежнему верны Штормграду и ведут войну против бывших товарищей, а припасы и мины для обороны им присылает Кразек из Пиратской бухты." } } } },
    ["c27df993"] = { d = 32.0, v = "narrator", c = { x = { { 0.00, "Приют Гюнтера — остров посреди озера Ясноводного." }, { 3.91, "Здесь обитает лич Гюнтер, некогда маг Кирин-Тора из Даларана, павший жертвой Чумы." }, { 10.25, "Он остался свободен от воли Короля-лича, но не верит, что свободны остальные: лич убеждён, что вся нежить по-прежнему служит Плети, и велел своим зомби нападать на всякого, кто ступит на берег." }, { 25.11, "Бетор Ледострел из Подгорода, его старый друг по Кирин-Тору, надеется вернуть его к своим." } } } },
    ["c2e3047d"] = { d = 7.9, v = "narrator", c = { x = { { 0.00, "Уровень секретности этой информации СТОЛЬ высок, что понадобится изобретение нового числа, чтобы описать его!" } } } },
    ["c2e7e1af"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Река Отравленной Крови берёт начало у одноимённого водопада в сердце леса и течёт на запад, к обрывам над Тёмными берегами, где спускается с гор и становится Петляющей рекой." }, { 14.16, "Вода в ней мутная и ядовитая: по берегам ползают проклятые и нечистые слизнюки, а звери, приходящие на водопой, теряют разум." }, { 24.57, "Порчу этой реки чувствуют даже фурболги и олени далеко за пределами Осквернённого леса." } } } },
    ["c2fde3ef"] = { d = 27.9, v = "orc-male", c = { x = { { 0.00, "Составляющие Ритуала" }, { 1.76, "Перед началом ритуала у тебя должны быть следующие компоненты:" }, { 7.11, "Кувшин Д'жииви" }, { 8.42, "Чёрный Магнит" }, { 9.56, "Ксоротианские Иероглифы" }, { 11.55, "За определённую цену мой слуга Горзиеки добудет их для тебя." }, { 16.60, "Без них ни одно действие ритуала выполнять нельзя." }, { 20.89, "Каждый компонент очень важен." }, { 23.49, "На следующих страницах я подробно опишу их применение." } } } },
    ["c30ab469"] = { d = 33.1, v = "narrator", c = { x = { { 0.00, "Рудник у Серебряного ручейка лежит в северной части Лок Модана, между станцией Альгаз и Каменной Плотиной." }, { 8.21, "Некогда он щедро давал серебро дворфам Стальгорна, но давно выработан, и Лига рудокопов превратила штольни в склад для своих инструментов." }, { 18.77, "Теперь рудник кишит кобольдами-крысами, которые растащили ящики с оборудованием по всем ходам." }, { 26.02, "За рудником до сих пор ржавеют разбитые орочьи повозки и катапульты, оставшиеся от прежних войн." } } } },
    ["c326cfcf"] = { d = 25.5, v = "human-male", c = { x = { { 0.00, "ОТЧЁТ: Воры." }, { 0.92, "Более тревожит то, что не только кобольды, но и банды людей-воров появились в долине." }, { 7.15, "Они носят красные повязки и называют себя братством." }, { 11.09, "Такой уровень организованности может доставить неприятности и здесь, и во всём Элвиннском лесу." }, { 17.92, "Мы идентифицировали одного из их лидеров – это Гаррик Тихокрад – и надеемся вскоре предать его правосудию." } } } },
    ["c3275500"] = { d = 18.8, v = "narrator", c = { x = { { 0.00, "Со временем лорды Строма переселились в богатые северные земли Лордерона, оставив засушливый юг." }, { 7.71, "Наследники короля Торадина, последние потомки рода Арати, запретили покидать Стром, чем вызвали недовольство богачей, которые желали уехать." } } } },
    ["c349305e"] = { d = 19.5, v = "narrator", c = { x = { { 0.00, "Логово Древолапов — пещера в холмах на юго-востоке Фераласа, где укрываются вожаки гноллов клана Древолапов." }, { 8.71, "Здесь сходятся их тропы, здесь они хранят добычу и отсюда ведут свою отчаянную войну на два фронта." }, { 16.77, "Южнее логова лежат заросшие руины." } } } },
    ["c3a0986e"] = { d = 28.1, v = "human-male", c = { x = { { 0.00, "Девлином завладело отчаяние, и он искал, как избежать ожидающей нас печальной участи, и вот почему он заключил договор с Плетью." }, { 8.73, "Я не знаю, сколько ему пообещали за предательство, но я уверен, всё это было ложью." }, { 14.48, "Если ты встретишь моего брата, беги от него." }, { 17.64, "Он – монстр." }, { 18.44, "Несколько ночей назад он убил двоих наших часовых и провёл небольшую группу Плети через эту брешь к тому месту, где спало большинство из нас." } } } },
    ["c3beec8f"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Струящаяся Тьма — заброшенная шахта на северо-западе леса, недалеко от берега." }, { 6.41, "Её выработки и окрестности кишат пауками, а в глубине, среди коконов, прячется их огромная матка." }, { 14.38, "Аптекари Гробницы посылают сюда за паучьей кровью: в соединении с ядом из сердца бешеного медведя она, по их расчётам, даёт смертельный эликсир для новой чумы." } } } },
    ["c3d933a2"] = { d = 30.7, v = "human-male", c = { x = { { 0.00, "Храмовники Бездны" }, { 1.20, "Тебе, как новичку, разрешается обращаться к Храмовникам Бездны для проведения обычных ритуалов." }, { 7.52, "Не забывай надевать подобающее убранство при обращении с Ветровыми Камнями, чтобы на тебя не подействовали наши защитные чары." }, { 15.94, "Если вдруг случится нечто непредвиденное в отсутствие старших, тебе разрешается вызвать Храмовника Бездны." }, { 23.04, "За подробностями о проведении соответствующих ритуалов призыва обращайся к выпуску Истинно Верующего за прошлый месяц." } } } },
    ["c45b9953"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Великое море омывает северный берег Тирисфаля." }, { 3.93, "Его холодные тёмные воды тянутся до самого горизонта, отделяя Восточные королевства от далёкого Калимдора." }, { 12.61, "У берега на волнах покачиваются обломки кораблекрушений, а дальше, в глубине, нет ничего, кроме бесконечной серой воды." } } } },
    ["c4b2710e"] = { d = 7.6, v = "narrator", c = { x = { { 0.00, "(Значительная часть текста на странице залита кровью, но вы можете разобрать одно имя)" }, { 7.02, "Карендин" } } } },
    ["c4c22ed5"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "Делянка Ивара — тыквенное поле на севере леса, недалеко от дороги в Тирисфаль." }, { 6.19, "Когда-то это была богатая ферма, и её владелец Ивар держал много работников, но Плеть разорила Лордерон, а сам хозяин обратился в вурдалака." }, { 17.17, "Ивар Нечистый до сих пор торчит в старом амбаре." }, { 20.97, "На заброшенной ферме укрылись стражи смерти Ран и Квинн Йорик, отправленные на разведку северного Серебряного бора." } } } },
    ["c51e1374"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Проходили века, Хранители защищали людей от невидимой угрозы Пылающего Легиона по всему Аратору и Кель'Таласу." }, { 9.45, "Аратор рос и процветал, а использование магии распространилось по всей империи." }, { 16.06, "Тем временем Хранители пристально наблюдали: не появится ли признаков активности демонов." } } } },
    ["c5383d77"] = { d = 43.3, v = "narrator", c = { x = { { 0.00, "Туманный Предел — самая длинная полоса побережья Тёмных берегов: она тянется от Аубердина на север до оконечности края." }, { 9.72, "Здесь сменяют друг друга мрачные бухты и серые пляжи, усыпанные обломками и тушами морских тварей, которых выбрасывает на песок." }, { 20.18, "В прибрежных водах лежат затонувшие корабли — среди них «Серебряная Заря» и «Туманная Пелена», потопленные мурлоками на подходе к Аубердину." }, { 31.51, "Мурлоки и теперь не дают покоя берегу, но ещё больше здесь крабов, снующих по всей отмели." }, { 38.83, "В эти воды впадает река Скалистая, несущая с гор порчу." } } } },
    ["c53d160d"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "Форт Мерзлогривов — пещерное логово ледяных троллей на западе Дун Морога, к юго-западу от Посёлка Пивоваров." }, { 8.34, "Некогда Мерзлогривы правили всеми этими горами, а теперь укрываются здесь, среди немногих хижин и тёмных тоннелей." }, { 17.24, "Пещеру стерегут охотники за головами и свежеватели, и Сенир Белобород не решился идти туда в одиночку." }, { 25.22, "Стальгорну нужно знать, сколько троллей засело в форте и что они замышляют." } } } },
    ["c5688049"] = { d = 17.7, v = "orc-female", c = { x = { { 0.00, "Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению." }, { 6.60, "Мы всё – как неприступная твердыня, ведь иначе нам не выжить." }, { 11.61, "А ничего другого мне и не надо." }, { 14.27, "Ника Алый Шрам" }, { 15.56, "Глава разведчиков, Каргат." } } } },
    ["c5728ed1"] = { d = 32.7, v = "human-male", c = { x = { { 0.00, "Среди них – кузнечный молот, что дал мне мой отец." }, { 3.31, "В молодости я сомневался в этом, но он всегда говорил мне, что этот молот зачарован, и это последнее, что он сказал мне перед тем, как его погубила Плеть." }, { 13.48, "Принеси мне этот молот, чтобы я смог использовать его со всем своим пылом." }, { 18.48, "Если он действительно зачарован, то он поможет нам обоим." }, { 22.27, "Я оставил его в стойлах в главном внутреннем дворе крепости." }, { 26.36, "Если населяющие её чудовища сами не занимаются кузнечным делом, то, я думаю, он всё ещё лежит там." } } } },
    ["c5ea0591"] = { d = 34.2, v = "narrator", c = { x = { { 0.00, "История Гри'лека Странника." }, { 2.42, "...Начало надписи, выбитой на камне, стёрлось, но окончание всё ещё можно было прочитать..." }, { 10.22, "Гри'лек топал по джунглям." }, { 12.56, "Его глаза горели, и его грудь клокотала, ибо великий гнев переполнял его." }, { 19.03, "В ярости он рычал на небо и воздевал руку." }, { 22.78, "Он воздевал левую руку, ставшую сильной и крепкой от охоты без своего близнеца." }, { 29.72, "Ибо правая рука Гри'лека была утрачена безвозвратно." } } } },
    ["c633038b"] = { d = 33.6, v = "gnome-male", c = { x = { { 0.00, "Кстати, будь осторожен с ними." }, { 1.92, "Один нитромирглицероний сам по себе может разнести тебя в пыль." }, { 5.87, "Я поместил часть жидкости в медные пробирки, которые должны защитить от сотрясений и обеспечить безопасность." }, { 12.64, "Свиток, который ты получил от Коллина, я использовал в коробках с детонаторами." }, { 17.55, "Теперь они пошлют бесшумное сообщение зарядам эн-джи-пять когда ты их включишь." }, { 22.57, "Я использовал простой сталтваргонский механизм, чтобы обеспечить оптимальную проводимость проводов и скорость потока нитромирглицерония между разностными жидкостями лучше среднего." } } } },
    ["c64a9007"] = { d = 33.9, v = "narrator", c = { x = { { 0.00, "Храм Зин-Малор стоит посреди руин Эльдарата; когда-то ночные эльфы поклонялись здесь Элуне, и его очертания напоминают Храм Луны в Дарнасе." }, { 11.61, "Ныне храм захватили наги Злобного Прибоя, и их военачальник восседает там, где прежде звучали молитвы." }, { 20.07, "Здесь хранился кристалл Зин-Малора, дающий владельцу почти безграничную магическую силу, если он её достоин; но кристалл давно похищен и увезён на север, в Зимние Ключи." } } } },
    ["c64adf97"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "При поддержке своих помощников Утера Светоносного, адмирала Даэлина Праудмура и Туралиона, Лотар убедил получеловеческие народы Лордерона в необходимости противостоять надвигающемуся вторжению." }, { 14.84, "Альянс также смог заручиться поддержкой дворфов из Стальгорна и некоторых высших эльфов из Кель'Таласа." } } } },
    ["c6539a1d"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Адмирал поставил Джайну перед страшным выбором: выступить против новообретенных союзников-орков или сразиться с собственным отцом в надежде сохранить хрупкий мир между Альянсом и Ордой." }, { 14.24, "После сильных душевных метаний Джайна выбрала последнее и встала на сторону Тралла." } } } },
    ["c660eed5"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "Звезда Ксиль'и" }, { 1.32, "Звезда у Грелборга Скряги." }, { 3.66, "Он – жадный огр, который проводит свои дни в горах и руинах Альтерака в поисках блестяшек." }, { 11.44, "Большая часть его коллекции бесполезна, но одна вещь, Звезда Ксиль'и, обладает ценными свойствами." } } } },
    ["c6667594"] = { d = 32.3, v = "narrator", c = { x = { { 0.00, "Цитадель — сердце Терамора, приземистая крепость посреди города, где расположены казармы стражи." }, { 7.56, "Отсюда командует гарнизоном капитан Ваймс, ведущий дознание о сожжённой таверне на границе Степей; здесь же несёт службу командир Самаул из гвардии леди Джайны." }, { 19.99, "Стены цитадели помнят и худшие дни: именно здесь пал адмирал Даэлин Праудмур, когда Орда во главе с Рексаром штурмовала город, занятый флотом Кул-Тираса." } } } },
    ["c6c31679"] = { d = 31.2, g = 1, v = "human-male", c = { m = { { 0.00, "Прежде чем я продолжу, позволь мне поблагодарить тебя ещё раз за то, что ты сделал для меня и моей жены." }, { 7.05, "Ты спас ей жизнь, и за это я обязан тебе большим, чем смогу отплатить за сотни жизней." }, { 12.93, "Она – всё для меня." }, { 14.29, "Если бы она умерла... ну, я не знаю, что бы я сделал." }, { 17.94, "Вот список того, что тебе нужно собрать, если ты хочешь, чтобы я сковал тебе оружие Света." }, { 24.32, "Я записал их по порядку, от простого к сложному – надеюсь, так тебе будет проще." } }, f = { { 0.00, "Прежде чем я продолжу, позволь мне поблагодарить тебя ещё раз за то, что ты сделала для меня и моей жены." }, { 7.42, "Ты спасла ей жизнь, и за это я обязан тебе большим, чем смогу отплатить за сотни жизней." }, { 13.74, "Она – всё для меня." }, { 15.16, "Если бы она умерла... ну, я не знаю, что бы я сделал." }, { 18.96, "Вот список того, что тебе нужно собрать, если ты хочешь, чтобы я сковал тебе оружие Света." }, { 25.60, "Я записал их по порядку, от простого к сложному – надеюсь, так тебе будет проще." } } } },
    ["c6ce700b"] = { d = 36.6, v = "narrator", c = { x = { { 0.00, "Перекрёсток Мертвеца — развилка на главной дороге перевала: на запад — Сумеречный лес, на восток — Болото Печали, а на юг — тропа к Каражану." }, { 11.15, "Своё имя перекрёсток получил по дереву-виселице, на котором до сих пор качаются два тела." }, { 18.18, "Рядом стоит столб с указателями «Поверни назад!» и «Оставь надежду, всяк сюда входящий»." }, { 25.27, "Несмотря на угрозы, сама дорога здесь сравнительно безопасна, и путники, идущие в болота, минуют её без потерь, если только не сходят с колеи." } } } },
    ["c6e5a11b"] = { d = 26.8, v = "narrator", c = { x = { { 0.00, "В конце концов ночные эльфы обожглись именно на том чародейском огне, который стремились подчинить." }, { 7.79, "Их безрассудное злоупотребление магией привлекло в мир демонов Пылающего Легиона, которые нанесли существенный урон эльфийской цивилизации." }, { 18.53, "Насчёт войн демонов с троллями ничего не известно, но можно предположить, что нашествие не обошло их стороной." } } } },
    ["c6fe9976"] = { d = 10.9, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.79, "Часть один." }, { 3.99, "Главнокомандующий." }, { 5.85, "Фельдмаршал." }, { 7.15, "Маршал." }, { 7.99, "Командор." }, { 9.01, "Лейтенант-командор." } } } },
    ["c7214e3b"] = { d = 32.7, g = 1, v = "nightelf-male", c = { m = { { 0.00, "Как только мне стало известно, что ты готов к обучению, я тотчас же послал тебе знак." }, { 6.97, "Друиды Кенария рады любому пополнению своих рядов." }, { 11.27, "Даже духи становятся сильнее, когда нас больше." }, { 15.27, "Рано или поздно, проявив должное терпение, мы вернём былое величие." }, { 20.90, "Найди меня возле верхушки Альдрассила." }, { 24.17, "Я буду твоим проводником, пока ты живёшь в Тенистой долине." }, { 29.06, "- Мардант Крепкий Дуб, наставник друидов" } }, f = { { 0.00, "Как только мне стало известно, что ты готова к обучению, я тотчас же послал тебе знак." }, { 7.13, "Друиды Кенария рады любому пополнению своих рядов." }, { 11.48, "Даже духи становятся сильнее, когда нас больше." }, { 15.54, "Рано или поздно, проявив должное терпение, мы вернём былое величие." }, { 21.24, "Найди меня возле верхушки Альдрассила." }, { 24.54, "Я буду твоим проводником, пока ты живёшь в Тенистой долине." }, { 29.50, "- Мардант Крепкий Дуб, наставник друидов" } } } },
    ["c728c6a2"] = { d = 19.4, v = "narrator", c = { x = { { 0.00, "Руины Зиата'джаи лежат в восточных джунглях, к югу от лагеря Гром'гол." }, { 5.86, "Древние постройки Гурубаши заняли тролли клана Дробителей Черепов, чьи охотники за головами носят ожерелья из костей врагов." }, { 16.18, "Путников здесь встречают копья и топоры." } } } },
    ["c764f34e"] = { d = 31.6, g = 1, v = "human-male", c = { m = { { 0.00, "Я никогда так не гордился своим ремеслом, как в последние несколько лет." }, { 4.93, "Спрос на услуги убийц, шпионов и разведчиков высок как никогда." }, { 9.29, "На первый взгляд может показаться, что нас кормит война." }, { 13.16, "Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу." }, { 20.08, "Мне передали, что ты появился в наших краях и хочешь кое-чему научиться." }, { 25.13, "Когда будет время, приходи к стойлам позади аббатства." }, { 29.00, "-Джорик Керридан, наставник разбойников" } }, f = { { 0.00, "Я никогда так не гордился своим ремеслом, как в последние несколько лет." }, { 4.88, "Спрос на услуги убийц, шпионов и разведчиков высок как никогда." }, { 9.20, "На первый взгляд может показаться, что нас кормит война." }, { 13.03, "Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу." }, { 19.89, "Мне передали, что ты появилась в наших краях и хочешь кое-чему научиться." }, { 24.95, "Когда будет время, приходи к стойлам позади аббатства." }, { 28.78, "-Джорик Керридан, наставник разбойников" } } } },
    ["c77884ac"] = { d = 69.2, v = "narrator", c = { x = { { 0.00, "Серебряный бор лежит между Тирисфальскими лесами и предгорьями Хилсбрада, от Великого моря на западе до озера Лордамер на востоке." }, { 11.04, "Когда-то это был чистый и красивый лес Лордерона, но Третья война прошла по нему огнём и чумой: Плеть жгла посевы и вырезала деревни, а сосны побледнели от заразы и стоят теперь серые и больные." }, { 27.26, "Даларан был занят восстановлением своего города, Гилнеас затворился за Стеной Седогрива, и присматривать за лесом стало некому." }, { 37.90, "Север заняли Отрёкшиеся: из Гробницы стражи смерти ведут разведку, а аптекари варят новую чуму." }, { 45.97, "На юге, в крепости Тёмного Клыка, засел безумный архимаг Аругал, и его воргены рыщут по дорогам." }, { 54.12, "На острове Фенриса окопались гноллы-гнилошкуры, слуги Плети, а в Янтарной Мельнице держатся волшебники Кирин-Тора." }, { 63.71, "Каждая из этих сил считает лес своим, и судьба его пока не решена." } } } },
    ["c79b1df6"] = { d = 27.9, v = "gnome-male", c = { x = { { 0.00, "Мор Серое Копыто, продолжение." }, { 2.28, "Позже мы узнали, что Мор тогда выжил." }, { 5.09, "Но после этого его ждала ещё более страшная участь, чем смерть: его взяли в плен тролли Тазз'Алаора." }, { 12.59, "Там его подверг страшным пыткам Воевода Вун, а потом его нашли убийцы Вальтхалака и избавили, наконец, от мучений." }, { 21.17, "Дух Мора Серого Копыта ты найдёшь в логове Воеводы Вуна; это ещё одно из мест с привидениями." } } } },
    ["c7babf30"] = { d = 16.1, v = "narrator", c = { x = { { 0.00, "Титан Норганнон, хранитель знаний и владыка магии, даровал синему дракону Малигосу часть своей великой силы." }, { 9.13, "С того времени Малигос, известный как Хранитель Магии, хранит магию и тайные знания." } } } },
    ["c7cabfd9"] = { d = 14.7, v = "narrator", c = { x = { { 0.00, "Эльфы под предводительством Анастериана Солнечного Скитальца не хотели вмешиваться в предстоящий конфликт." }, { 7.84, "Но они не могли отказать Лотару – последнему из рода Арати, который поддерживал их в прошлом." } } } },
    ["c837f886"] = { d = 21.0, v = "human-male", c = { x = { { 0.00, "Аргус, как тебе известно, я сейчас занимаюсь различным ремонтом в армии." }, { 4.93, "Работа спорится, но вот мои запасы железа иссякли." }, { 8.40, "У меня не хватает материалов на подковы." }, { 11.14, "Зная, что ты всегда хранишь большой запас, хочу одолжить у тебя пятьдесят пар, пока я не получу следующую партию железа." }, { 19.35, "Заранее благодарю," }, { 20.63, "-Вернер" } } } },
    ["c87b2488"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Здесь покоятся останки короля Теренаса Менетила Второго – Последнего Истинного Короля Лордерона." }, { 8.18, "Велики были его дела, долгим было его правление, немыслимой была его смерть." }, { 14.91, "\"Да не будет на отце вины за бесстыдные поступки сына." }, { 19.58, "Да останется потерянной и забытой окровавленная корона\"." } } } },
    ["c87d349f"] = { d = 30.6, v = "goblin-male", c = { x = { { 0.00, "*Ещё цитаты!*" }, { 1.68, "\"Знаешь это чувство, когда ты заканчиваешь делать что-то и включаешь это первый раз, чтобы испытать его силу и насладиться своим изобретением, когда оно начинает оживать?" }, { 14.21, "А вот гномы не знают\"." }, { 15.84, "-- Никс Шепружин, главный гоблинский инженер из Прибамбасска" }, { 20.08, "*\"Инженерное дело – это когда берётся фантазия и делается ещё более фантастичной!\" - Ровис Мак-Хрясьшатун, гномский изобретатель.*" } } } },
    ["c8b536e0"] = { d = 12.2, v = "gnome-male", c = { x = { { 0.00, "Список дел." }, { 0.91, "Уложить снаряжение перед выходом на охоту." }, { 4.27, "Снабдить пояс Грунда карабинами." }, { 6.85, "Починить сварочную маску." }, { 8.88, "Послать маме открытку." }, { 10.70, "Страница сорок пять." } } } },
    ["c914f655"] = { d = 34.8, v = "narrator", c = { x = { { 0.00, "Всего через несколько месяцев после завершения строительства Крепости Стражей Пустоты вся энергия Тёмного портала слилась воедино и открылся новый проход на Дренор." }, { 12.14, "Оставшиеся кланы орков под предводительством старого шамана Нер'зула вновь напали на Азерот." }, { 18.90, "Собираясь украсть ряд магических артефактов, которые должны были увеличить могущество Нер'зула, орки планировали открыть несколько новых порталов на Дреноре, которые позволили бы им навсегда покинуть свой обречённый мир." } } } },
    ["c924e0d3"] = { d = 34.1, v = "narrator", c = { x = { { 0.00, "Потрёпанным и обескровленным оркам оставалось лишь спешно сбежать в последний оплот орочьей силы – в Тёмный портал." }, { 9.20, "Туралион и его воины гнались за остатками войска орков по зловонному Болоту Печали в мрачные Выжженные земли, где стоял Тёмный портал." }, { 20.15, "Там, у подножия колоссального портала, обессиленная Орда и измотанный Альянс схлестнулись в схватке – той, что должна была стать последней, самой кровавой битвой Второй войны." } } } },
    ["c952f53d"] = { d = 42.0, v = "narrator", c = { x = { { 0.00, "Все наши шмыгуносы хорошо обучены, и вам достаточно лёгкого взмаха вашей палочки-погонялочки, чтобы перевести ближайшего шмыгуноса в режим поиска." }, { 11.08, "После этого шмыгунос начнёт принюхиваться в поисках корней, и если он почует один из них, то двинется по направлению к нему и начнёт его выкапывать." }, { 22.24, "Если вы ещё раз взмахнете палочкой-погонялочкой в сторону шмыгуноса, ищущего корни, он прекратит свои поиски и радостно вернётся к вам." }, { 32.36, "Мы уверяем вас, что вы найдёте наших шмыгуносов хорошо обученным, полезным и невероятно подходящим приобретением для вашей команды!" } } } },
    ["c96285de"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Убеждённые в том, что они могут самостоятельно противостоять троллям или даже эльфам, военачальники Арати решили построить могучий город-крепость в южных регионах Лордерона." }, { 14.19, "Город, названный Стром, стал столицей государства Арати, Аратора." }, { 19.52, "В то время как Аратор процветал, люди со всего огромного континента шли на юг, дабы жить под защитой Строма." } } } },
    ["c966789f"] = { d = 19.7, v = "narrator", c = { x = { { 0.00, "Мазра'Алор — большой зиккурат в сердце Зул'Машара, святилище лесных троллей." }, { 5.96, "На его ступенях несут стражу охотники за духами, и чужаков здесь встречают копьями." }, { 12.47, "Тролли говорят с лоа и чтят старые обряды даже теперь, когда чума подступает к самым стенам." } } } },
    ["c9668620"] = { d = 33.4, v = "dwarf-male", c = { x = { { 0.00, "Твой драгоценный зверь не очень-то хорошо себя чувствует в обжигающем жаре Выжженной Теснины… лучше тебе незамедлительно выполнить наши требования." }, { 10.84, "Ты принесёшь нам пять звёздных рубинов и семьсот золотых, и положишь всё это в один пакет без пометок." }, { 18.22, "Пакет не позже чем через неделю оставь у входа на Подгорную тропу." }, { 23.20, "Если наши требования не будут выполнены, Метцен украсит собой традиционный дворфийский стол на Праздник Зимнего Покрова." }, { 32.11, "Олень… вкуснятина…" } } } },
    ["c96bfe1a"] = { d = 17.8, v = "narrator", c = { x = { { 0.00, "Озеро Мерельдар раскинулось к югу от Перекрёстка Корина." }, { 4.43, "Его воды давно отравлены, и в них поднимаются порчёные элементали." }, { 9.64, "На берегу стоят развалины старого дома, а рядом — хижина и паром, когда-то принадлежавшие здешней ферме." } } } },
    ["c9a79c79"] = { d = 46.7, v = "narrator", c = { x = { { 0.00, "Рыболовный чемпионат Тернистой долины!" }, { 2.78, "Проводится по воскресеньям, с четырнадцати до шестнадцати часов." }, { 7.30, "Закиньте удочки где угодно на побережье Тернистой долины (кроме Пиратской бухты) и ищите косяки вкуснорыбы, что появляются вдоль берега!" }, { 17.07, "Старайтесь забросить удочку как можно ближе к стайке рыб, и тогда у вас будет возможность поймать особенную рыбу вместо обычных, которых полно в Тернистой долине." }, { 28.77, "Первый, кто выловит сорок вкуснорыб, сможет сдать их Мастеру Мормышу в Пиратской бухте и получить вознаграждение!" }, { 36.85, "Даже если вам не удалось поймать сорок вкуснорыб первому, вы сможете обменять их на деньги, а за некоторых рыб можно получить ценные призы!" } } } },
    ["c9b7ff9d"] = { d = 32.6, v = "bloodelf-female", c = { x = { { 0.00, "*Капитан следопытов Аллерия Ветрокрылая*" }, { 3.04, "." }, { 3.18, "Знаменитая охотница на троллей из Кель'Таласа." }, { 6.77, "Главная разведчица при экспедиции Альянса, которая отправилась в Дренор, родной мир орков." }, { 13.81, "Предположительно погибла." }, { 15.78, "Сестра, твоё сердце было решительно и неукротимо, как стрела, летящая по ветру." }, { 21.97, "Ты была самой яркой из нашего Ордена." }, { 24.99, "Ты была самой любимой из нашего рода." }, { 28.02, "- Сильвана Ветрокрылая, предводитель егерей Кель'Таласа" } } } },
    ["c9c3c1f1"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Терраса Торговцев занимает юг Дарнасса и служит средоточием всей торговли ночных эльфов." }, { 6.88, "Здесь стоят лавки и лотки, здесь же работает аукцион города." }, { 11.58, "К северу лежит Терраса Воинов, а на западе — Храм Луны и Храмовые сады." }, { 17.19, "Даже торговля здесь ведётся негромко, как и всё в столице калдорай." } } } },
    ["c9d4ae1d"] = { d = 13.1, g = 1, v = "creature/ancient", c = { m = { { 0.00, "Знай, охотник, эти демоны дерутся только по своим правилам." }, { 6.02, "Если им покажется, что одолеть тебя нельзя, они сбегут." }, { 11.67, "ИДИ К НИМ ОДИН." } }, f = { { 0.00, "Знай, охотница, эти демоны дерутся только по своим правилам." }, { 5.95, "Если им покажется, что одолеть тебя нельзя, они сбегут." }, { 11.47, "ИДИ К НИМ ОДНА." } } } },
    ["c9f66ff6"] = { d = 16.0, v = "narrator", c = { x = { { 0.00, "Несмотря на то что восстание было подавлено, Орде не удалось оправиться от ужасных потерь." }, { 6.48, "Предательство Гул'дана не только придало Альянсу уверенности, но и обеспечило им время на перегруппировку и подготовку к ответной атаке." } } } },
    ["ca01ccb5"] = { d = 28.5, v = "narrator", c = { x = { { 0.00, "Видя, что Орда раскалывается изнутри, лорд Лотар собрал последние силы и отбросил Молота Рока на юг, к центру Штормграда." }, { 9.52, "Там войска Альянса окружили Орду в вулканической крепости пика Чёрной горы." }, { 15.44, "Лотар пал в этой битве, но один из его командиров, Туралион, в последний момент взял на себя командование войском и заставил Орду отступить к бескрайнему Болоту Печали." } } } },
    ["ca0340f7"] = { d = 28.9, g = 1, v = "goblin-female", c = { m = { { 0.00, "Привет, Фелнок!" }, { 1.15, "Мои исследования в Пылающих степях продвигаются отлично." }, { 5.18, "Я весьма обязана путнику за его помощь!" }, { 8.05, "Вот что мне нужно, чтобы продолжать исследования:" }, { 11.51, "Бумбербитцель из рулонной стали." }, { 13.81, "Ледяной гаечный ключ номер семнадцать." }, { 16.56, "Двенадцать фунтов утиных перьев." }, { 18.92, "Банка твоего клея." }, { 20.33, "Спасибо тебе большое, Фелнок." }, { 22.50, "Когда мы увидимся снова, напомни, чтобы я не подкладывала уголь в твои ботинки!" }, { 28.19, "-Тинки" } }, f = { { 0.00, "Привет, Фелнок!" }, { 1.17, "Мои исследования в Пылающих степях продвигаются отлично." }, { 5.26, "Я весьма обязана путнику за её помощь!" }, { 8.05, "Вот что мне нужно, чтобы продолжать исследования:" }, { 11.56, "Бумбербитцель из рулонной стали." }, { 13.90, "Ледяной гаечный ключ номер семнадцать." }, { 16.69, "Двенадцать фунтов утиных перьев." }, { 19.09, "Банка твоего клея." }, { 20.52, "Спасибо тебе большое, Фелнок." }, { 22.73, "Когда мы увидимся снова, напомни, чтобы я не подкладывала уголь в твои ботинки!" }, { 28.51, "-Тинки" } } } },
    ["ca2017db"] = { d = 23.8, g = 1, v = "human-female", c = { m = { { 0.00, "Брат Нилз," }, { 0.70, "Мой виноград спасён!" }, { 2.11, "Путник, предъявитель сего письма, спас мой наводненный головорезами виноградник и собрал весь виноград, что я не успела собрать." }, { 11.06, "Несмотря на то что бандиты всё ещё бродят у реки, практически весь мой урожай был спасён." }, { 17.20, "Ты можешь добавить к своим запасам полные корзины винограда." }, { 21.55, "Да защитит нас Свет," }, { 22.96, "-Милли Осворт" } }, f = { { 0.00, "Брат Нилз," }, { 0.69, "Мой виноград спасён!" }, { 2.07, "Путница, предъявитель сего письма, спасла мой наводненный головорезами виноградник и собрала весь виноград, что я не успела собрать." }, { 11.16, "Несмотря на то что бандиты всё ещё бродят у реки, практически весь мой урожай был спасён." }, { 17.18, "Ты можешь добавить к своим запасам полные корзины винограда." }, { 21.44, "Да защитит нас Свет," }, { 22.82, "-Милли Осворт" } } } },
    ["ca6685d0"] = { d = 51.0, v = "narrator", c = { x = { { 0.00, "Мельницы Агамондов — обширная сеть ветряных мельниц на холмах северного Тирисфаля, некогда владение самой преуспевающей семьи в этих краях." }, { 10.61, "Когда Плеть пришла впервые, Грегор Агамонд решил остаться: семья укрепила усадьбу и уговорила работников держать оборону вместе с хозяевами." }, { 21.35, "Погубил их младший сын Девлин, переметнувшийся к Плети и впустивший мертвецов за стены." }, { 27.92, "Теперь мельницы — едва ли не крупнейший оплот Плети в Тирисфале: между обветшалых крыльев бродят скелеты-солдаты и заклинатели, а на дороге, говорят, до сих пор слышно безумное бормотание Девлина." }, { 42.77, "Колман Фартинг, бывший работник Агамондов, а ныне Отрёкшийся из Брилла, так и не простил хозяевам своей смерти." } } } },
    ["ca756704"] = { d = 20.5, v = "narrator", c = { x = { { 0.00, "Рудник Ветрорезов вырыт на восточной окраине Утёса Ветрорезов, там, где кончается Волчья река." }, { 7.42, "Торговая компания добывает здесь олово руками кобольдов, что копошатся в штольнях и не терпят чужаков." }, { 15.49, "Говорят, в глубине рудника гоблины хранят свои бумаги и письма." } } } },
    ["ca82c104"] = { d = 36.7, v = "narrator", c = { x = { { 0.00, "Деревня Ночных Охотников — рыбацкий посёлок троллей на юго-западном берегу Пустошей, у Побережья Сар'Терис." }, { 8.72, "Это главная опора Орды в этих краях: таверна с видом на море, ветрокрылы, торговцы и учителя рыбной ловли." }, { 17.59, "Тролли кормят уловом и себя, и Заставу Скитающихся Духов, но море неспокойно: наги нападают на рыбаков, и кое-кто из троллей поклялся извести их род." }, { 29.76, "А южнее, на берегу, дриада из Круга Кенария расспрашивает путников об останках Зейтара." } } } },
    ["ca92d96a"] = { d = 22.5, v = "narrator", c = { x = { { 0.00, "Во главе с Громом Адским Криком все вожди, кроме Дуротана, повиновались и тем самым обрекли себя на вечную службу Пылающему Легиону." }, { 10.81, "Те, кого коснулась ярость Маннорота, пусть не желая того, превратили своих ничего не подозревающих собратьев в таких же рабов, какими стали сами." } } } },
    ["ca9b0141"] = { d = 34.3, v = "narrator", c = { x = { { 0.00, "В преданиях троллей говорится, что в первый раз Камень Приливов попал в империю Гурубаши, будучи найденным воином-троллем, бродившим по побережью Тернистой долины." }, { 13.39, "Воину попался на глаза таинственный синий камень, внутри которого сплетались и струились молочно-белые прожилки." }, { 22.71, "Заинтригованный воин взял камень с собой и продолжил свой путь." }, { 27.82, "Со временем воин обнаружил, что камень даёт ему власть над водами." }, { 33.22, "Он мог вызывать" } } } },
    ["caac48f2"] = { d = 25.4, v = "human-male", c = { x = { { 0.00, "Зная Эдвина ван Клифа всю свою жизнь, я могу сказать, что видеть в нём своего врага мне неприятно." }, { 7.02, "Понимаете, он был моим другом детства, и я лично учил его мастерству теней, надеясь, что однажды он будет работать вместе со мной." }, { 16.37, "Если ван Клиф стоит во главе Братства Справедливости, то да помилует Свет наши души!" }, { 22.36, "Мастер Матиас Шоу," }, { 23.78, "Гильдия убийц Штормграда" } } } },
    ["cac73745"] = { d = 22.4, v = "narrator", c = { x = { { 0.00, "Кил'джеден отправил Нер'зула обратно на Азерот." }, { 3.75, "Его ледяная тюрьма пронеслась по ночному небу и упала на заснеженный северный континент Нордскол, погрузившись глубоко в ледник Ледяной Короны." }, { 15.06, "После падения кристалл принял форму трона, а дух Нер'зула, заключённый в нём, вскоре пробудился." } } } },
    ["cad44c1e"] = { d = 28.8, v = "narrator", c = { x = { { 0.00, "Туманная долина – узкая долина в северо-западном углу болота, к северу от входа на перевал Мёртвого Ветра." }, { 9.09, "Здесь нет ни дорог, ни жилья: среди тумана бродят тиноброды и их старейшины, а из вязкой земли поднимаются перевитые ужасы." }, { 19.48, "В глубине долины, в пещере, обитает Хозяин болота – древнее создание, к которому редко кто решается спуститься." } } } },
    ["caf28ed4"] = { d = 15.2, v = "narrator", c = { x = { { 0.00, "Святилище Ретресса — разрушенная эльфийская часовня на Опустошённом берегу, к юго-западу от памятника Чёрному Ворону." }, { 8.94, "Ныне оно пустует; лишь заблудшие мурлоки и макрура порой забредают сюда с пляжа." } } } },
    ["cb0912c8"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Южные моря омывают южные берега Восточных королевств и Калимдора." }, { 5.51, "Их тёплые воды кишат акулами и нагами, а над волнами бродят морские великаны." }, { 11.91, "Где-то за горизонтом лежит Зандалар, родина троллей, и острова, где прячутся пираты Кровавого Паруса." } } } },
    ["cb38bb75"] = { d = 19.3, v = "narrator", c = { x = { { 0.00, "Гордость Оленьего Шлема была растоптана." }, { 3.24, "Во второй раз за всю свою жизнь он почувствовал в животе трепетание, которое могло быть вызвано лишь страхом." }, { 11.62, "Позже, в Танарисе, он пришёл к Анахроносу, отпрыску Ноздорму, и попросил Бронзовых драконов о помощи." } } } },
    ["cb4917fd"] = { d = 67.4, v = "narrator", c = { x = { { 0.00, "Тельдрассил поднимается из вод Сокрытого Моря у северо-западного побережья Калимдора: это и остров, и исполинское древо, в кроне которого раскинулась новая родина ночных эльфов." }, { 14.12, "После Третьей войны, когда Малфурион ушёл в Изумрудный Сон, верховный друид Фэндрал Олений Шлем убедил старейшин вырастить новое Древо Жизни взамен ослабевшего Нордрассила." }, { 27.88, "Имя ему дали «венец земли», а в ветвях возвели столицу Дарнасс, где правит Тиранда Шелест Ветра." }, { 35.77, "Но великие драконы не благословили это древо, и рост его оказался с изъяном." }, { 41.86, "Над лесом стоит вечный сумрак, а в лунных колодцах хранится сила Элуны." }, { 47.67, "И всё же сюда просачивается порча: древесники впадают в ярость, фурболги Кривой Сосны обратились против леса, в пещерах завелись грелли и сатиры." }, { 59.28, "Часовые и друиды стерегут покой Тельдрассила, и отсюда юные ночные эльфы впервые выходят в большой мир." } } } },
    ["cb59252c"] = { d = 35.5, v = "narrator", c = { x = { { 0.00, "Телсамар стоит на западном берегу озера Лок и остаётся единственным городом Лок Модана." }, { 6.66, "Дворфы и гномы живут здесь под властью Стальгорна, а порядок блюдёт мировой судья Тупонос." }, { 13.60, "В городке есть таверна, кузница с наковальней, конюшня и кладбище, а грифоны с площадки летают в Стальгорн и в Гавань Менетилов." }, { 23.39, "По дороге через Телсамар ходит дозором горный пехотинец Кэдрелл." }, { 28.45, "Городок славится кровяными колбасками, а вечерами в таверне собираются путники со всей округи." } } } },
    ["cb941d17"] = { d = 35.5, v = "narrator", c = { x = { { 0.00, "Ежевичная лощина на северо-восточной окраине плато Красного Облака — логово свинобразов из племени Дыбогривов." }, { 8.85, "Отсюда они совершают набеги на охотничьи угодья и по ночам грабят Лагерь Нараче, натаскивая для войны боевых вепрей, а шаманы племени готовят здесь свои ритуальные мази." }, { 22.51, "В глубине лощины, в большой хижине, обитает их вождь — Остроклык Терновая Мантия." }, { 28.98, "Молодые таурены приходят сюда, чтобы пройти обряд Силы и доказать свою храбрость." } } } },
    ["cb9a3d88"] = { d = 33.5, v = "narrator", c = { x = { { 0.00, "В горах к северу от Павильона Лорисс огры Гордунни разбили одно из своих главных становищ." }, { 7.39, "Их присутствие отравило землю: буйная зелень Фераласа здесь пожухла и побурела, и на склонах остались лишь голые камни да ямы." }, { 17.52, "В холмах две пещеры — малая у входа и большой огрский курган в глубине, где обитают заклинатели и укротители клана." }, { 26.79, "Отсюда Гордунни выходят в набеги, и здесь Орда рассчитывает нанести им ощутимый удар." } } } },
    ["cbb34f01"] = { d = 37.8, v = "narrator", c = { x = { { 0.00, "Кости Граккаронда — исполинский скелет бронзового дракона, лежащий посреди песков центрального Силитуса." }, { 8.25, "Граккаронд откликнулся на зов Анахроноса и сражался с киражами в Войне Зыбучих песков, пока каменный страж врага не пронзил его крыло; рухнув, дракон раздавил под собой множество насекомых, но рой довершил дело." }, { 24.90, "С тех пор его кости стали святыней для каменных слуг киражей — свидетельством того, что даже дракон может пасть." }, { 33.72, "Друиды Круга Кенария с опаской смотрят на это место." } } } },
    ["cbbdaba9"] = { d = 3.2, v = "narrator", c = { x = { { 0.00, "(Оставшаяся часть книги пуста.)" } } } },
    ["cbc226c8"] = { d = 9.7, v = "narrator", c = { x = { { 0.00, "Феррен Маркус" }, { 1.12, "Аббат Монастыря Алого ордена" }, { 3.44, "Гражданин Стратхольма" }, { 5.13, "Погиб при обороне монастыря во время Первого летнего штурма" } } } },
    ["cbd3cfe2"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Долго дети звёзд обитали на берегах мерцающих вод Источника Вечности." }, { 5.81, "Всем было известно, что Элуна, свет вечной полуночи, аспект и богиня луны, обитала в его водах в то время, когда отдыхала от трудов." }, { 16.96, "На берегах Источника построили свои дома дети звёзд, любимцы Элуны, живущие, не отводя взора от неба, глядя в лунную ночь." }, { 27.29, "Хотя было построено много городов и мест обитания" } } } },
    ["cbd61b4c"] = { d = 36.9, g = 1, v = "tauren-male", c = { m = { { 0.00, "Во многих племенах способность разговаривать с умершими предками считается очень ценным даром." }, { 8.92, "Но ты, герой, должен помнить, что твой дар не менее ценен." }, { 14.36, "Те, кто говорит с духами, не могут поднять тяжёлое оружие или вытерпеть телесные страдания, причиняемые тайной магией." }, { 25.49, "Ты – можешь." }, { 26.68, "Ты сильный." }, { 27.78, "Я помогу тебе стать ещё сильнее." }, { 30.84, "Ищи меня в Лагере Нараче." }, { 33.39, "-Харутт Громовой Рог, наставник воинов" } }, f = { { 0.00, "Во многих племенах способность разговаривать с умершими предками считается очень ценным даром." }, { 8.73, "Но ты, героиня, должна помнить, что твой дар не менее ценен." }, { 14.21, "Те, кто говорит с духами, не могут поднять тяжёлое оружие или вытерпеть телесные страдания, причиняемые тайной магией." }, { 25.10, "Ты – можешь." }, { 26.26, "Ты сильная." }, { 27.34, "Я помогу тебе стать ещё сильнее." }, { 30.34, "Ищи меня в Лагере Нараче." }, { 32.83, "-Харутт Громовой Рог, наставник воинов" } } } },
    ["cbe57982"] = { d = 38.5, v = "narrator", c = { x = { { 0.00, "Проклятый лес тянется от стен Стратхольма на юг и запад до самой Долины Ужаса." }, { 6.43, "Некогда эти рощи сравнивали с Элвиннским лесом; чума превратила землю в бурую губку, а грибы выросли до размеров деревьев и выдыхают клубы чёрного газа." }, { 19.21, "Лес густо занят Плетью: здесь стоят её зиккураты и бойни, а над кронами парит некрополь Наксрамас, врата к которому стережёт Серебряный Рассвет." }, { 31.09, "По дороге к Стратхольму ходят и дозоры Алого ордена, что рубят живых и мёртвых без разбора." } } } },
    ["cc20d145"] = { d = 31.5, v = "dwarf-male", c = { x = { { 0.00, "*Артишок клана Северного Волка: Повести о славе Грозовой Вершины Автор Вандар Грозовая Вершина*" }, { 9.12, "Что такое клан Северного Волка?" }, { 11.57, "Ответ прост: клан Северного Волка – сборище дикарей, жаждущих низвергнуть нас, своих законных повелителей." }, { 19.76, "Он, подобно артишоку, окружён колючим и твёрдым защитным слоем, сняв который, можно добраться до сердцевины и съесть её с доброй чесночной подливой." }, { 31.04, "Вкусно!" } } } },
    ["cc2b037b"] = { d = 36.0, v = "human-male", c = { x = { { 0.00, "Я не могу описать того, что случилось дальше." }, { 3.31, "Я ясно помню всё, но даже моя истерзанная душа не может изложить на бумагу последовавшие за тем несколько ужасающих минут." }, { 12.13, "Я могу лишь написать, что семья Свена была убита." }, { 15.76, "И вскоре вернулся Свен, чтобы увидеть эту страшную картину смерти." }, { 20.63, "Такое горе исказило его черты, что я боялся выйти к нему." }, { 24.91, "И я так боялся, что он может обнаружить меня сам, что покинул своё убежище в сарае." }, { 30.81, "Я не знаю, где теперь Свен, но я молюсь, что когда-нибудь он обретёт покой." } } } },
    ["cc2f2f06"] = { d = 26.9, v = "narrator", c = { x = { { 0.00, "После гражданской войны пути оставшихся троллей из племени Гурубаши разошлись." }, { 6.54, "Племена Дробителей Черепов, Кровавого Скальпа и Чёрного Копья нашли своё пристанище в джунглях Тернистой долины." }, { 15.75, "На руинах империи воцарился хрупкий мир, но в народной памяти осталось пророчество о том, что однажды Хаккар вернётся в мир и поглотит его." } } } },
    ["cc9b64cf"] = { d = 31.8, v = "dwarf-male", c = { x = { { 0.00, "Отчёт о положении дел с троллями из племени мерзлогривов в регионе Холодной долины." }, { 5.71, "Подготовлен Грелином Белобородом, особым посланником Сената." }, { 9.92, "Я потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе." }, { 22.23, "Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии." }, { 28.20, "Учитывая помощь горных пехотинцев, уже находящихся в" } } } },
    ["cca906bc"] = { d = 21.7, v = "orc-male", c = { x = { { 0.00, "Так о чём я?" }, { 0.92, "В общем, Укрытиями Дун Болдара (расположены они в Дун Болдаре) управляют защитники из клана Грозовой Вершины – лучшие стражи Вандара, которым он доверяет больше всех." }, { 14.01, "Уничтожь две башни, и подкрепление, которое выходит на помощь Вандару, прекратит своё существование." } } } },
    ["ccbb82b8"] = { d = 10.9, v = "human-male", c = { x = { { 0.00, "Агашам!" }, { 0.60, "Наши планы должны оставаться тайной при любых обстоятельствах!" }, { 5.28, "Нельзя допустить, чтобы остальные племена узнали о них." }, { 9.42, "Подпись:" }, { 10.09, "Вестник Эльм" } } } },
    ["ccc5b530"] = { d = 18.6, v = "narrator", c = { x = { { 0.00, "Третья фракция, клан Чёрного Железа, была под командованием тана-чародея Тауриссана." }, { 6.59, "Дворфы Чёрного Железа таились в самых глубоких тенях под горой и замышляли заговор против своих собратьев из клана Бронзобородов и клана Громового Молота." } } } },
    ["ccf416fa"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Руины старого Даларана окружают лиловый купол на берегу озера Лордамер." }, { 6.51, "Это остатки окраин города магов, разрушенных демоном Архимондом в Третью войну: обломки башен и стен торчат из земли у самой мерцающей завесы." }, { 18.32, "Среди руин несут стражу волшебники и заклинатели Даларана в сопровождении каменных элементалей, оберегая тайну возрождающегося города." } } } },
    ["cd2f2546"] = { d = 37.1, v = "narrator", c = { x = { { 0.00, "На границе Степей и Пылевых топей чернеют обгорелые стены таверны «Последний привал»." }, { 7.19, "Её построил человек из Терамора, Джеймс Хьяль, чтобы давать кров путникам на дороге к морю, но однажды таверна сгорела дотла, а его жена и ребёнок погибли в огне." }, { 20.58, "Кто поджёг её, так и не выяснено: улики в пепле ведут в разные стороны, и дознание ведут разом стража Терамора и посланцы Орды из Гиблотопи." }, { 32.19, "Над пожарищем тишина, и лишь ветер со Степей перебирает золу." } } } },
    ["cd7d70e6"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Высокорождённые с головой ушли в работу и беспрерывно изучали Источник." }, { 5.49, "Со временем они развили в себе способности управлять его космической энергией." }, { 11.69, "Чем больших успехов Высокорождённые достигали в своих опытах, тем явственней они понимали, что с помощью своих новообретенных навыков они могут как творить, так и разрушать." }, { 25.06, "Злосчастные Высокорождённые зациклились на примитивной магии и твёрдо решили добиться мастерского владения ею." } } } },
    ["cd90c367"] = { d = 11.6, v = "human-male" },
    ["cdba2246"] = { d = 38.4, v = "narrator", c = { x = { { 0.00, "Источники Ледяного Пламени — цепочка дымящихся горячих озёр на дальнем западе Зимних Ключей, у самого выхода из Крепости Древобрюхов." }, { 10.53, "Посреди вечных снегов эти тёплые воды кажутся чудом: в Зимних Ключах нет вулканов, и дворфийка Донова, разбившая рядом лагерь, пытается понять, откуда взялся жар." }, { 23.47, "Она подозревает, что источники связаны с демонами далеко на юге, в Теснине Зловещего Шёпота." }, { 30.73, "К горячим ключам часто приходят фурболги племени Зимней Спячки, так что купаться здесь небезопасно." } } } },
    ["cdcfc786"] = { d = 20.0, v = "dwarf-male", c = { x = { { 0.00, "Первый успех взбодрил нашу команду." }, { 2.68, "Барнил налил всем меда, чтобы отметить его." }, { 5.95, "Но нашему празднованию не суждено было продолжаться долго." }, { 10.20, "Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рёв." }, { 16.48, "Я в жизни не слышал такого леденящего кровь звука." } } } },
    ["ce55bab2"] = { d = 31.6, v = "narrator", c = { x = { { 0.00, "Дальняя застава — небольшой форпост Орды у моста через реку Строптивую, первое, что видит путник, входящий в Степи из Дуротара." }, { 9.66, "Сторожевая башня, орочья землянка и пара катапульт стерегут переправу, а рядом собираются караваны с кодо, идущие на запад к Перекрёстку." }, { 19.93, "Заставой командует Каргал, и именно он отправляет новобранцев Орды дальше по дороге." }, { 26.28, "Здесь же Ак'Зелот ищет следы демонической порчи культа Пылающего Клинка." } } } },
    ["ce70956b"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "Культисты под командованием Кел'Тузада жаждали смерти, после которой они могли бы восстать и служить своему тёмному властелину." }, { 10.08, "В этом они увидели шанс на бессмертие и возрадовались ему." }, { 14.72, "Чем дальше расходилась чума, тем больше ужасных зомби появлялось в северных землях." }, { 21.37, "Кел'Тузад, глядя на растущее войско Короля-лича, назвал его Плетью – ведь скоро она придёт к воротам Лордерона... и могучим ударом бича снесёт человечество с лица земли." } } } },
    ["ce971121"] = { d = 55.9, v = "narrator", c = { x = { { 0.00, "Ульдаман — древнее хранилище титанов, погребённое в недрах Каз Модана со времён сотворения мира." }, { 7.49, "Легенды говорят, что титаны создали троггов из камня, сочли опыт неудачным и заперли их здесь, а затем попробовали снова, и так появились земельники, предки дворфов." }, { 20.55, "Дворфы Стальгорна докопались до забытого города ещё до Третьей войны и разбудили троггов, которые перебили большую часть исследователей." }, { 31.25, "Ныне по залам рыщут трогги и дворфы клана Тенегорна: те ищут Диски Норганнона, где записана история сотворения дворфов, чтобы поднести их своему огненному владыке." }, { 44.30, "Город стерегут исполинские стражи из живого камня, а где-то за баррикадами держатся трое дворфов во главе с Бейлогом, ищущие путь в Чертог Хаз'Мула." } } } },
    ["cebf4a8a"] = { d = 39.1, v = "narrator", c = { x = { { 0.00, "Ядовитый улей, который зовут ещё ульем Сентипаара, прячется на юго-западе Танариса, над обрывом в кратер Ун'Горо." }, { 9.31, "Земля здесь просела, словно когда-то тут было русло реки или мелкое озеро, но силитиды выпили воду и высушили запад пустыни." }, { 19.64, "Из песка торчат подрагивающие клешни зарывшихся тварей, а под землёй тянутся тёплые сырые туннели, чьи стены облеплены кислотой и незрелыми личинками." }, { 31.73, "Здесь роятся членистоноги-сентипаары, а огры Песчаного Молота, говорят, не брезгуют их мясом." } } } },
    ["ceeb1ce3"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "На этот раз не должно было быть никаких ошибок." }, { 3.65, "Кил'джеден решил, что нужно ослабить оборону Азерота ещё до того, как Легион ступит на его земли." }, { 11.14, "Расы смертных, такие как ночные эльфы и драконы, занятые борьбой с новым врагом, были бы уже неспособны противостоять нашествию Легиона." } } } },
    ["cef0a91d"] = { d = 28.4, v = "narrator", c = { x = { { 0.00, "Дворфы" }, { 0.55, "Они, неустанно исследуя свои собственные корни, предпочитают отмечать праздник, восхваляя самого Дедушку Зиму." }, { 9.10, "Его дворфы считают воплощением древних жителей Азерота – титанов." }, { 14.21, "Полагая, что сами они приходятся в какой-то мере родней этим таинственным существам, дворфы объявили своё снежное обиталище Дун Морог главным доказательством благосклонности Дедушки Зимы." } } } },
    ["cef3b913"] = { d = 32.3, v = "narrator", c = { x = { { 0.00, "Карьер Гол'Болар на юго-востоке Дун Морога — большой раскоп, где дворфы добывали руду и камень." }, { 7.12, "Чем глубже копали горняки, тем больше троггов лезло наружу, пока племя Каменной Челюсти не выгнало их из шахт и не разгромило лагерь." }, { 16.97, "Штейгер Камнелоб до сих пор не может смотреть на разбитые бочки с порохом без злости." }, { 23.22, "Сенатор Мер Каменная Реликвия от имени Лиги Исследователей нанимает добровольцев, чтобы очистить карьер и вернуться к работе." } } } },
    ["cefce42b"] = { d = 28.2, v = "human-male", c = { x = { { 0.00, "*К ящику прилагается записка.*" }, { 2.61, "*В ней значится:*" }, { 3.92, "\"Вернер, грустно слышать, что в Красногорье нехватка ресурсов." }, { 8.29, "Вот подковы, которые ты просил." }, { 10.47, "Когда будет возможность, пришли мне сто серебряных монет.\"" }, { 14.53, "\"Или, если хочешь, можешь расплатиться брюшной чешуёй детёнышей чёрного дракона (слышал, что в Красногорье их полно)." }, { 22.58, "Так как ты мой друг..." }, { 24.01, "Четырёх чешуек будет более чем достаточно." }, { 26.95, "Благодарю. -- Аргус\"" } } } },
    ["cefe0df0"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "Осклизлая скала — руины лесных троллей на востоке Внутренних земель, ныне кишащие слизнями." }, { 7.13, "Во Вторую войну здесь стояла база старой Орды, пока Альянс Лордерона и дворфы Громового Молота не выбили орков и их союзников-троллей из этих мест." }, { 18.56, "Орки ушли в спешке и бросили здесь ящики с местным медовым напитком, о котором до сих пор помнят любители выпить." }, { 27.28, "В пещере под скалой растут редкие призрачные грибы, а на её склонах пузырится и ползёт всё, что осталось от прежних хозяев." } } } },
    ["cf07176d"] = { d = 24.6, v = "dwarf-male", c = { x = { { 0.00, "Мне вспоминаются блаженные минуты, проведённые с тобой, и я испытываю огромную благодарность Свету и тебе за то, что наслаждался ими так долго." }, { 10.42, "Но как же тяжело мне отказаться от них и спалить дотла надежды на будущие годы, в которых мы всё ещё могли бы жить вместе, любить друг друга и смотреть, как наши сыновья растут честными дворфами!" } } } },
    ["cf196dc8"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Зловещее море омывает восточный берег Лордерона за Дланью Тира." }, { 5.27, "Это неизведанные, не нанесённые на карты воды; по преданию, во Вторую войну Орда держала крепость на острове в устье залива Тира, чтобы перерезать пути снабжения в Кель'Талас." }, { 19.54, "Ныне только ветер с моря приносит в отравленный край глоток свежего воздуха." } } } },
    ["cf26a39a"] = { d = 16.8, v = "narrator", c = { x = { { 0.00, "На крохотном островке в западной части залива Бурь темнеет пещера Чешуеборода." }, { 6.47, "Здесь живёт древняя морская черепаха, но застать её дома удаётся редко: Чешуебород предпочитает охотиться в водах Великого моря." } } } },
    ["cf392849"] = { d = 35.1, v = "narrator", c = { x = { { 0.00, "Руины Деревни Каменного Молота — всё, что осталось от прежнего дома огров клана." }, { 6.49, "Они поселились в южных топях, придя в Калимдор вместе с Ордой; здесь Рексар одолел их жестокого вождя, возглавил клан и повёл его на войну с Кул-Тирасом." }, { 18.75, "Но затем на деревню обрушился выводок Ониксии, и уцелевшие огры бежали на север, в Гиблотопь." }, { 26.26, "Теперь среди обгорелых хижин хозяйничают драконоиды чёрной стаи, а огры мечтают однажды отвоевать родные руины." } } } },
    ["cf6a6fbf"] = { d = 17.6, v = "narrator", c = { x = { { 0.00, "Флот Праудмура представлял серьёзную угрозу стабильности в регионе." }, { 5.38, "Будучи знаменитым героем Второй войны, отец Джайны всей душой ненавидел Орду." }, { 11.65, "Он твёрдо решил уничтожить Дуротар прежде, чем орки закрепятся на этой земле." } } } },
    ["cf6f25c7"] = { d = 31.2, v = "narrator", c = { x = { { 0.00, "К западу от Святилища Авианы, среди скал, лежит Обитель Скорби." }, { 5.34, "Имя её говорит о скорби по павшим в битве за Хиджал, которых было без счёта." }, { 11.73, "Но покой этого места нарушен: нежить Плети, которую Архимонд привёл на гору вместе с демонами, не исчезла с гибелью своего повелителя, и мёртвые здесь по-прежнему не знают отдыха." }, { 26.62, "Друиды и стражи Хиджала не спускают глаз с этих склонов." } } } },
    ["cf728091"] = { d = 19.9, v = "narrator", c = { x = { { 0.00, "Жаждавший могущества, Гул'дан отправился на поиски подводной Гробницы Саргераса, где он надеялся раскрыть тайну абсолютной силы." }, { 9.86, "Гул'дан уже обрёк своих воинов на вечное рабство в Пылающем Легионе и о своём долге перед Молотом Рока он беспокоился меньше всего." } } } },
    ["cf8c83cf"] = { d = 36.9, v = "dwarf-male", c = { x = { { 0.00, "С какой радостью я бы смыл своими собственными слезами малейшее пятнышко на твоём счастье и боролся бы со всеми невзгодами этого мира, чтобы защитить тебя и наших дорогих деток!" }, { 13.56, "Но я не могу." }, { 14.59, "Мне придётся наблюдать за тобой из Круговерти Пустоты и витать возле тебя, пока ты в одиночку противостоишь всем бурями со своей драгоценной маленькой ношей, выдерживаешь шторм со своим маленьким ценным грузом." }, { 30.49, "Мне придётся терпеливо ждать, пока мы встретимся, чтобы больше не расставаться никогда." } } } },
    ["cf9378f9"] = { d = 29.6, v = "human-male", c = { x = { { 0.00, "Лорд Элло Чернодрев-- Город Приозёрье смиренно просит Ночной дозор о помощи." }, { 5.66, "Нас осаждают, нас держат в осаде орки Чёрной Горы и гноллы из стаи Темношкуров, прислуживающие Морганту." }, { 13.31, "Я бы никогда не попросил о помощи, но мы в тяжёлом положении." }, { 17.70, "Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу Вас оказать нам поддержку." }, { 24.69, "Падёт королевство – и все люди будут обречены." }, { 28.08, "Мировой судья Соломон" } } } },
    ["cfb831f9"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "Кил'джеден подготавливал Орду к нападению на Азерот, а Медив в это время продолжал сражаться с Саргерасом за свою душу." }, { 8.83, "Король Ллейн, благородный правитель Штормграда, узнал о том, что тьма завладела душой его бывшего друга." } } } },
    ["cfc12f74"] = { d = 20.8, v = "human-male", c = { x = { { 0.00, "Боюсь, за происходящим в Северных землях стоит более могущественное и ужасное зло, чем мы предполагали." }, { 7.51, "Королевство Штормград обязано принять меры, иначе нас ждёт погибель или, что хуже, мы станем послушными рабами нашего врага." }, { 16.76, "Подпись," }, { 17.42, "Чиновник Соломон" }, { 18.69, "Приозёрье" }, { 19.35, "Королевство Штормград" } } } },
    ["cfc58b7d"] = { d = 26.6, v = "gnome-male", c = { x = { { 0.00, "Прежде чем я вернусь к подробностям своего плана, давай я объясню тебе, куда поместить взрывчатку." }, { 6.66, "План альфа – лесопилка:" }, { 8.23, "Перед лесопилкой есть вагончик (это к северо-востоку от места, где они вырубают лес и собирают древесину)." }, { 15.38, "Я подозреваю, что инженерные планы находятся внутри лесопилки." }, { 19.56, "Чтобы установить заряд, направляйся за вагончик." }, { 22.83, "Установив его, поспеши удалиться на приличное расстояние." } } } },
    ["d0037d12"] = { d = 31.7, v = "human-male", c = { x = { { 0.00, "Очищенная руда – есть в Телсамаре дворф-кузнец по имени Балор Крепкорук, в своё время он учил меня." }, { 6.76, "Он делает очень специфичный сплав, который, я думаю, идеально подошёл бы для твоего оружия." }, { 12.90, "По идее, партия сплава должна была прибыть ещё во время моего пребывания в Стальгорне, но до сих пор ни слуху ни духу." }, { 20.95, "Найди его и проверь, не готова ли моя партия товара." }, { 24.63, "Если его нет на озере Лок Модан, то мне хотелось бы хотя бы узнать, что случилось с моим старым учителем." } } } },
    ["d0204149"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "Карьер Тяжелоступа лежит в восточной части пустыни, к северу от Долины Клыков." }, { 6.08, "Раскоп назван по имени дворфа Тяжелоступа, что вёл здесь работы для Лиги Исследователей и искал древности титанов." }, { 14.78, "По слухам, место прибрала к рукам шайка дворфов Чёрного Железа, часть тех же сил, что засели в Ульдамане, а сам Тяжелоступ пропал." }, { 24.59, "Уцелевшие старатели держатся у палаток на краю карьера и не теряют надежды, хотя, как говорят здесь, в Бесплодных землях каждый день убивает надежду." } } } },
    ["d024fea2"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Алая Базилика — огромный собор в сердце Длани Тира, выстроенный по образу Собора Света в Штормграде." }, { 7.96, "Это высшее седалище духовной власти Алого ордена, тесно связанное с аббатством Длани Тира и далёким Монастырём Алого ордена в Тирисфале." }, { 18.68, "Под его сводами восседает лорд-крестоносец, правящий городом, и здесь орден вершит свои обряды и суды." } } } },
    ["d02ec687"] = { d = 14.4, v = "narrator", c = { x = { { 0.00, "Шу'хало навсегда покинули родные земли и стали кочевать по бескрайним равнинам." }, { 6.54, "Но они хранят надежду, что их племена найдут новое пристанище под сенью любящих рук Матери-Земли." } } } },
    ["d04761ee"] = { d = 39.4, v = "narrator", c = { x = { { 0.00, "Зул'Гуруб — древняя столица империи Гурубаши, укрытая в долине на северо-востоке джунглей." }, { 7.03, "Среди увитых лианами зиккуратов тролли некогда призвали кровавого бога Хаккара Свежевателя Душ, требовавшего бесчисленных жертв." }, { 16.91, "Племя Зандалар и восставшие Гурубаши штурмовали город и низвергли Хаккара на его алтаре, а жрецов Атал'ай изгнали в северные топи." }, { 27.07, "Ныне тролли шепчут, что Свежеватель Душ возродился в своём храме и его верховные жрецы вновь собрались в Зул'Гурубе." }, { 35.97, "Потому Зандалар ищет союзников среди чужаков." } } } },
    ["d08689e2"] = { d = 37.3, v = "narrator", c = { x = { { 0.00, "Острова Эха — россыпь тропических островков у юго-восточного берега Дуротара, новая родина племени Чёрного Копья в Калимдоре." }, { 9.72, "Тролли едва успели обжиться здесь, когда знахарь Залазан, некогда друг Вол'джина, обратил тёмные силы против своих же и подчинил их разум." }, { 20.42, "Племени пришлось отступить на берег Дуротара, а острова остались во власти Залазана и его околдованных слуг." }, { 28.75, "В джунглях рыщут ящеры и тигры, а на самом большом острове стоит круг черепов, в которых заперты души погибших." } } } },
    ["d0e85908"] = { d = 23.1, v = "narrator", c = { x = { { 0.00, "«Кровавая Завеса» — флагман пиратов Кровавого Паруса, средний из трёх фрегатов, стоящих на якоре у Гибельного берега." }, { 8.98, "Им командует флотоводец Фираллон, замысливший обстрелять Пиратскую бухту и сжечь город." }, { 15.60, "В капитанской каюте хранятся письма с планами нападения, за которыми охотятся Разбойники Черноводья." } } } },
    ["d100e87b"] = { d = 27.7, v = "bloodelf-female", c = { x = { { 0.00, "Тысячелетиями мы скрывались от чужаков." }, { 2.90, "Я буду первой из нас, кто признает, что в прошлом мы ошибались." }, { 7.55, "Нельзя было открывать людям магию." }, { 10.24, "Я не отрицаю этого, но и не желаю приговаривать нас к заточению за промахи предшественников." }, { 16.98, "Совместное существование Кель'дорай и других народов этого мира может принести много пользы." }, { 23.99, "Мы должны учиться терпимости." }, { 26.21, "(продолжение следует)" } } } },
    ["d1490c07"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Малака'джин — небольшая деревня троллей Чёрного Копья на юге Когтистых гор, у границы со Степями." }, { 7.53, "Здешние охотники живут с земли и продают добычу проезжим воинам Орды; за целебными зельями сюда шлют гонцов даже из лагерей Степей." }, { 17.94, "В пещере деревни обитает знахарь Джин'Зил: в клетках у него томятся пленные ночные эльфы, а в котле варится его лесная магия." }, { 27.92, "По ночам к стоянкам подкрадываются моховые пауки с Паучьего тракта, и Ксен'Зилла рад любой помощи." } } } },
    ["d15b70e9"] = { d = 32.9, v = "narrator", c = { x = { { 0.00, "Краккены взревели, и голоса их были подобны грому в час бури:" }, { 5.52, "\"Мы идём!\"" }, { 6.40, "Но Мин'лот не дрогнул." }, { 8.40, "Он призвал свою магию." }, { 10.48, "Волны, посланные на И'лалай, расступились, обогнули город и залили джунгли позади него." }, { 18.32, "Затем Мин'лот велел своим помощникам произнести сковывающие заклинания, и десятки тролльих голосов слились в нестройную песнь." }, { 29.52, "Но один голос звучал громче остальных." } } } },
    ["d18d95f1"] = { d = 17.9, v = "narrator", c = { x = { { 0.00, "Нечестивые, коварные повелители ужаса обращали друг против друга целые народы, манипулируя их бездумной ненавистью и недоверием друг к другу." }, { 11.80, "Саргерас легко победил натрезимов, но их порча глубоко запала в его душу." } } } },
    ["d198655c"] = { d = 20.9, v = "narrator", c = { x = { { 0.00, "На этот раз Плеть превратила практически весь Лордерон и Кель'Талас в ядовитые Чумные земли." }, { 6.81, "Там осталось лишь несколько очагов сопротивления Альянса." }, { 11.05, "Один из них, состоявший в основном из высших эльфов, возглавлял последний представитель династии Солнечного Скитальца – принц Кель'тас." } } } },
    ["d1ad7e08"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Никто не знает точно, как зародилась Вселенная." }, { 3.70, "Кто-то предполагает, что после сильнейшего космического взрыва в Великой Тьме стали вращаться бесконечные миры – миры, в которых затем зародилось великое многообразие форм жизни." }, { 17.45, "Другие же считают, что Вселенная в её современном виде была создана одной-единственной всемогущей сущностью." } } } },
    ["d1d1d16b"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "ВОИНСКИЕ ЗВАНИЯ ОРДЫ И АЛЬЯНСА." }, { 2.64, "Тром-ка!" }, { 3.37, "В этой книге ты найдёшь подробный перечень воинских званий Орды и жалкого Альянса." }, { 10.12, "Сначала в списках идёт Орда, а затем Альянс, и для обеих сторон перечислены офицерские и рядовые звания." }, { 18.63, "Как и подобает, вверху списка располагаются старшие чины, а младшие – ниже." } } } },
    ["d1fd9b0a"] = { d = 27.5, v = "human-male", c = { x = { { 0.00, "Приказ пиратам Кровавого Паруса" }, { 2.17, "Читайте и запоминайте, ребятки, другого такого удачного шанса напасть на Пиратскую бухту у нас не будет!" }, { 9.16, "Старину Данкена я послал с разведкой на север и сказал ему ждать сигнала." }, { 14.10, "\"Госпожа Удача\" бросит якорь у южного мыса, чтобы взять припасы." }, { 18.50, "Наш коротышка, капитан Штиллец, со своей командой приготовится забрать всё награбленное на борт." }, { 24.83, "Ну а с остальным управится наш болван Брут." } } } },
    ["d2033063"] = { d = 24.7, v = "narrator", c = { x = { { 0.00, "Кил'джеден не давал духу шамана умереть, заставляя его в полной мере чувствовать ужасную боль, которую ему причинял." }, { 9.28, "Нер'зул умолял демона послать ему смерть, но тот был непреклонен: он сказал, что Кровавый договор, который они очень давно заключили, всё ещё в силе, и Нер'зул ещё должен был сослужить демону службу." } } } },
    ["d211b8cb"] = { d = 42.6, v = "narrator", c = { x = { { 0.00, "Вороний Холм – опустевший городок на западе Сумеречного леса, между участком Эддла на юге и огромным кладбищем на севере." }, { 9.92, "Некогда это было второе большое село здешних мест, но тьма и нежить выгнали жителей, и теперь дома стоят пустыми, а тишину нарушают лишь мертвецы, забредающие сюда с кладбища." }, { 24.33, "Впрочем, Калор из Темнолесья клянётся, что две ночи подряд видел здесь крадущиеся тени, а на третью – свет в одном из окон." }, { 34.26, "В брошенном доме и правда прячется нервный человек по прозвищу Трясунчик, сбежавший из города на запад." } } } },
    ["d22d4ffa"] = { d = 45.9, v = "narrator", c = { x = { { 0.00, "В юго-восточном углу пустыни стоит Тёмный портал — врата между Азеротом и Дренором, родиной орков." }, { 8.30, "Их открыли объединёнными усилиями Медив и чернокнижники Совета Теней во главе с Гул'даном, и именно отсюда началась Первая война." }, { 19.00, "В конце Второй войны Кадгар и маги Кирин-Тора разрушили врата, а остатки Орды бежали сквозь них в свой гибнущий мир." }, { 28.65, "С тех пор колоссальная арка стоит безмолвной и тёмной, но разведчики доносят, что подступы к ней стерегут демоны, и мало кто верит, что путь между мирами закрыт навсегда." }, { 42.56, "Стражи Пустоты не спускают с Портала глаз." } } } },
    ["d2442eeb"] = { d = 23.4, v = "human-female", c = { x = { { 0.00, "Здравствуй, Вильям!" }, { 1.49, "Мы уже много лет не разговариваем, но я надеюсь, что у вас с братом всё в порядке и что ваша аптека процветает." }, { 9.66, "У меня к тебе просьба, Вильям." }, { 12.02, "В общем, мой внук Томми Джо влюблён в юную Мейбелл Маклур." }, { 16.35, "Они друг в друге души не чают, но наши семьи..." }, { 19.99, "Конечно, наши семьи враждуют уже много лет..." } } } },
    ["d2563b3f"] = { d = 32.6, v = "narrator", c = { x = { { 0.00, "Долина Ужаса — городок в северо-западном углу края, на краю Проклятого леса." }, { 6.28, "Живых здесь почти не осталось: по улицам бродят вурдалаки-людоеды, чумные кабаны и раздутые големы, а над обгорелыми домами витают беспокойные духи." }, { 18.33, "Лишь безумный торговец, что зовёт Долину «жемчужиной Лордерона», да дворф-изобретатель, поклявшийся освобождать души нежити, всё ещё живут здесь." }, { 29.80, "К северу зияет вход в Туннель Ужаса." } } } },
    ["d2591cf4"] = { d = 40.9, v = "narrator", c = { x = { { 0.00, "Гробница Утера Светоносного венчает Холм Печали, и это единственное место в Чумных землях, где ещё чувствуется Свет." }, { 9.55, "Утер погиб у стен Андорала от руки Артаса, своего лучшего ученика, которого любил как сына." }, { 17.23, "Уцелевшие воины вынесли его тело и выстроили ему усыпальницу к югу от руин." }, { 23.65, "На постаменте стоит статуя паладина с книгой Света в одной руке и боевым молотом в другой." }, { 31.26, "За гробницей и садом присматривает эльф-жрец Тельданис, но склоны вокруг кишат тварями Плети, и путь сюда небезопасен." } } } },
    ["d288e78e"] = { d = 10.3, v = "narrator", c = { x = { { 0.00, "Он не искал себе почёт и славу" }, { 2.54, "И не хотел сородичами править." }, { 5.09, "Решил он биться за Лордерон," }, { 7.48, "Чтоб после уж народ его жил в мире." } } } },
    ["d2a45130"] = { d = 29.5, g = 1, v = "human-male", c = { m = { { 0.00, "Надеюсь, это письмо дошло до тебя, герой." }, { 2.97, "Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота." }, { 12.21, "Никогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несёт скверну в наши дома." }, { 19.83, "Меня назначили твоим наставником на первое время." }, { 23.30, "Когда будешь готов, ищи меня в Аббатстве Североземья." }, { 27.08, "-Брат Самуэль, наставник паладинов." } }, f = { { 0.00, "Надеюсь, это письмо дошло до тебя, героиня." }, { 3.10, "Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота." }, { 12.32, "Никогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несёт скверну в наши дома." }, { 19.94, "Меня назначили твоим наставником на первое время." }, { 23.41, "Когда будешь готова, ищи меня в Аббатстве Североземья." }, { 27.25, "-Брат Самуэль, наставник паладинов." } } } },
    ["d2de86ea"] = { d = 46.8, v = "narrator", c = { x = { { 0.00, "Альтеракская долина — заснеженная долина в самом сердце гор." }, { 4.92, "Давным-давно чернокнижник Гул'дан изгнал сюда клан Северного Волка, и орки жили здесь в уединении, пока в долину не пришла экспедиция дворфов Грозовой Вершины в поисках руды и реликвий предков." }, { 20.72, "С тех пор две армии сошлись в нескончаемой битве: орков ведёт старый шаман Дрек'Тар, а дворфов — их генерал из крепости Дун Балдар." }, { 31.30, "У входов в долину вербовщики зазывают бойцов: воевода Лаггронд собирает силы Орды, а офицеры Грозовой Вершины — воинов Альянса." }, { 41.81, "В глубине долины обитают ещё троги, кобольды, гарпии и гноллы." } } } },
    ["d2f7a4eb"] = { d = 43.8, v = "narrator", c = { x = { { 0.00, "Смоляные ямы Лаккари лежат на севере кратера, к югу от Укрытия Маршалла, там, где редеют деревья." }, { 8.14, "Чёрная вязкая смола выглядит обманчиво спокойной, но ноги увязают в ней, и зверь, ступивший слишком близко, уже не выбирается: из ям торчат кости сотен ящеров, иные древнее любой памяти." }, { 23.60, "Вокруг кружат падальщики в ожидании лёгкой добычи, а сама смола порой шевелится — из неё поднимаются твари, слепленные из чёрной жижи и костей." }, { 35.40, "Исследователи ценят эти места: вырытые здесь кости рассказывают о временах, когда кратер был ещё молод." } } } },
    ["d311cc86"] = { d = 22.9, v = "narrator", c = { x = { { 0.00, "Каньон Колючего Ветра лежит по обе стороны дороги из Колючего Холма в Оргриммар." }, { 6.41, "Это гнездовье гарпий Пыльного Ветра, и в каньоне их великое множество." }, { 11.97, "Тропы уводят к ферме Тор'кренов на западе и к пещере, ведущей в Сухую лощину." }, { 18.10, "Неосторожный путник, свернувший с дороги, рискует не вернуться." } } } },
    ["d316c67c"] = { d = 15.1, v = "narrator", c = { x = { { 0.00, "Когда тролли были изгнаны из северных земель, эльфы Кель'Таласа направили все свои усилия на воссоздание своего великолепного царства." }, { 10.36, "Армия Аратора с победой вернулась домой, в южные земли Строма." } } } },
    ["d33ed044"] = { d = 38.8, v = "narrator", c = { x = { { 0.00, "КАК ВЫГУЛИВАТЬ ШМЫГУНОСА" }, { 1.95, "Шмыгунос любит укромные, тёмные места." }, { 5.07, "И он очень застенчив." }, { 6.81, "Если вы хотите отправиться на прогулку с вашим шмыгуносом, то должны пойти в такое место, где бы он чувствовал себя как дома." }, { 16.87, "И вы ДОЛЖНЫ отвести его туда, где бы он чувствовал запах его любимой еды – корней синелиста!" }, { 24.40, "Ближайшее такое место – это \"котлован\" в Лабиринтах Иглошкурых." }, { 29.54, "Если вы откроете клетку неподалёку от неё и ваш шмыгунос почует запах клубней, то он решится отправиться вслед за вами." } } } },
    ["d362d8f3"] = { d = 21.5, v = "narrator", c = { x = { { 0.00, "Кил'джеден пришёл к предводителю кланов, могучему шаману по имени Нер'зул." }, { 5.81, "Он пообещал ему необычайную мощь и мудрость, если тот заключит с демоном пакт, который отдаст кланы во власть Пылающего Легиона." }, { 15.79, "Этот пакт предопределил не только судьбу орков, но и судьбу всего их мира." } } } },
    ["d37a3b5b"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Поляна Оракула — святилище на северо-западе Тельдрассила." }, { 4.54, "Здесь растёт Древо-оракул с ветвями, похожими на орла на спине медведя; говорят, его вырастила магия природы." }, { 13.20, "Вместе с друидами древо следит за ростом Тельдрассила и шлёт вести Фэндралу Оленьему Шлему на кусках исписанной коры." }, { 22.50, "Под его ветвями лежит первый и самый могучий из лунных колодцев острова." }, { 28.32, "Но на поляне свили гнёзда гарпии Кровавого Пера, и часовой Арания Проблеск Солнца с малым отрядом пытается их вытеснить." } } } },
    ["d38fcc1b"] = { d = 14.5, v = "narrator", c = { x = { { 0.00, "Уггель Тяжелорук" }, { 1.46, "Уггель – серьёзный и талантливый гравер, и когда он не отягощён тёмным ключом, из-под его рук выходят образчики великих творений, хранящихся в Зале Ремесла." } } } },
    ["d3c48447"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Южная башня — разрушенная сторожевая вышка на самом западе предгорий, у дороги, ведущей в Серебряный бор." }, { 8.43, "Люди давно оставили её, и теперь здесь несёт службу страж смерти Леш: с уединённого поста Отрёкшиеся следят за передвижениями Альянса по дороге между Хилсбрадом и Южнобережьем." }, { 22.18, "Место тихое и глухое, и одинокому наблюдателю не на кого рассчитывать, кроме гонцов с Мельницы Таррен." } } } },
    ["d3cd5285"] = { d = 31.9, v = "dwarf-male", c = { x = { { 0.00, "С первыми лучами солнца мы отправились на охоту на юг, за руины Ткаши." }, { 4.88, "Барнил беспокоился, что мы можем наткнуться на троллей племени Кровавого Скальпа." }, { 10.52, "Мои слова о том, что это племя сейчас занято войной со своими заклятыми врагами из племени Дробителей Черепов, конечно же, ничуть не успокоили его." }, { 20.85, "Меня же возможность засады беспокоила гораздо меньше: в моих руках была заряженная винтовка, на поясе – полная сумка пороха, а рядом – трое отличных охотников." } } } },
    ["d3e15111"] = { d = 35.7, v = "named/thrall", c = { x = { { 0.00, "*Здесь покоится Громмаш Адский Крик, вождь клана Песни Войны*" }, { 6.00, "." }, { 6.17, "Проклятие нашего народа началось с Грома – и им же закончилось." }, { 12.25, "На нашем древнем языке его имя означает \"Сердце великана\"." }, { 18.06, "Он заслужил его, вступив в поединок с демоном Манноротом и купив нам свободу ценой собственной крови." }, { 27.86, "Лок'тар огар, старший брат." }, { 30.55, "Да пребудет вечно клан Песни Войны." }, { 34.02, "— Тралл, вождь Орды" } } } },
    ["d3e287dc"] = { d = 33.1, v = "gnome-male", c = { x = { { 0.00, "ПОЗДРАВЛЯЕМ!" }, { 0.98, "Вы стали владельцем замечательного шмыгуноса!" }, { 4.46, "Зверёк довольно робкий, но вам непременно полюбятся его пушистое обаяние и невероятный нюх." }, { 11.44, "На следующих страницах приводится информация о:" }, { 15.07, "Один." }, { 15.55, "Кормлении и заботе о шмыгуносе" }, { 17.93, "Два." }, { 18.27, "Эксцентричном (и очаровательном) поведении шмыгуноса" }, { 22.25, "Три." }, { 22.60, "Применении запатентованной палочки-погонялочки для шмыгуносов" }, { 27.27, "Поздравляем вас ещё раз." }, { 29.08, "Вы не пожалеете," }, { 30.34, "-Марвиг Ржавоболт" }, { 31.74, "Владелец \"Шмыг Инк.\"" } } } },
    ["d4284cae"] = { d = 48.7, v = "narrator", c = { x = { { 0.00, "Андорал был сердцем северных провинций Лордерона: отсюда зерно расходилось по всему королевству, и именно его отравил Кел'Тузад, чтобы разнести Чуму." }, { 12.31, "После падения королевства рыцари Серебряной Длани под началом Утера удерживали город, пока сюда не пришёл рыцарь смерти Артас за останками Кел'Тузада." }, { 24.69, "Утер пал у стен Андорала, и с тех пор город принадлежит Плети: в руинах правит лич Арадж Призыватель, а по улицам бродят вурдалаки, скелеты и поганища." }, { 36.93, "Все часы в городе остановились ровно в три, в тот миг, когда здесь вспыхнула Чума, и бронзовый дракон Хроми ищет в руинах следы искажения времени." } } } },
    ["d43d6e5a"] = { d = 35.8, v = "narrator", c = { x = { { 0.00, "Альдрассил — могучее древо в центре Тенистой долины, внутри которого устроено целое селение." }, { 7.52, "В его верхней комнате обитает Тенарон Хватка Бури; он отправляет подающих надежды юных эльфов в большой мир и рассказывает им о недавней истории народа." }, { 19.80, "Под сенью Альдрассила наставники обучают новичков, а чуть севернее лежит лунный колодец с водой, хранящей силу Элуны." }, { 29.27, "У подножия древа стоит Гилшалан Буйный Ветер, изучающий пауков из Паучьего логова." } } } },
    ["d4498f92"] = { d = 67.0, v = "narrator", c = { x = { { 0.00, "Зимние Ключи — заснеженная долина на северо-востоке Калимдора, на склонах горы Хиджал, выше Лунной поляны и восточнее Осквернённого леса." }, { 11.06, "Здесь царит вечная зима: воздух чист и морозен, а над долиной нависают исполинские корни Нордрассила." }, { 19.16, "После Великого Раскола ночные эльфы пытались начать здесь новую жизнь, и от тех времён остались руины Кел'Терила с призраками высокорождённых." }, { 30.37, "Ныне единственный город долины — Круговзор, торговый пост гоблинов картеля Хитрая Шестерёнка, где принимают и Орду, и Альянс." }, { 40.35, "Ночные эльфы держат Деревню Звездопада, фурболги Древобрюхи стерегут проход в Осквернённый лес, а их сородичи из племени Зимней Спячки поддались порче и нападают на всех подряд." }, { 54.46, "В ледяных пещерах Маззорила несут стражу синие драконы, на севере бродят ледопарды, а на юге, в Теснине Зловещего Шёпота, затаились демоны Пылающего Легиона." } } } },
    ["d471bd28"] = { d = 26.3, v = "nightelf-female", c = { x = { { 0.00, "Одна стая потеряна." }, { 1.35, "Я послала воргенов прочесать лес и выяснить, где кроются демоны, но они не вернулись." }, { 6.88, "Я начинаю волноваться из-за лидеров, которым я доверила руководство." }, { 11.35, "Они примитивны и немедленно начали злоупотреблять данной им властью." }, { 15.82, "Сохраню ли я над ними власть?" }, { 17.70, "Может быть, я временно перестану вызывать новых воргенов." }, { 21.46, "Да пребудет со мной благословение Элуны, пока не будет выполнена моя работа." } } } },
    ["d4b2fa3e"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Аспекты их поклонения змеям в предыдущих томах этой работы, здесь я хотел бы рассмотреть примеры особого отношения троллей к морю." }, { 10.77, "Великое море." }, { 11.96, "Империя Гурубаши с трёх сторон была окружена морем, так что неудивительно, что морские воды играли значительную роль в жизни их общества." }, { 23.18, "Обширные пространства своей поросшей джунглями империи тролли могли контролировать беспрепятственно, а вот море не желало им подчиняться." }, { 34.39, "Широкое, бескрайнее, оно, несомненно," } } } },
    ["d4b5cf17"] = { d = 22.8, v = "narrator", c = { x = { { 0.00, "Расселина — логово фурболгов Кривой Сосны к северо-западу от Доланаара, прямо под сторожевым постом Часовых." }, { 8.24, "Отсюда душители племени выходят на дорогу и подстерегают путников, что везут грузы и вести между Доланааром и Дарнассом." }, { 17.36, "У входа дорогу стережёт часовой Амара Ночная Странница со своими воинами." } } } },
    ["d4ba9d00"] = { d = 24.6, v = "orc-male", c = { x = { { 0.00, "Эпилог" }, { 0.61, "Проделав всё это, ты доберёшься до самой цели, до центра луковицы." }, { 6.20, "Вандар Грозовая Вершина будет один и безо всякой защиты." }, { 11.17, "Правила ведения войны требуют нам предложить ему сдаться в плен, прежде чем убивать." }, { 18.37, "Поэтому, как увидишь его, обязательно предложи ему сдаться… а потом убей." } } } },
    ["d4c0c01f"] = { d = 16.7, v = "narrator", c = { x = { { 0.00, "Драконы знали, что действовать им надо быстро, не то мир постигнет новая ужасная катастрофа." }, { 7.02, "Тщательно взвесив всё, они решили, что лучше всего будет остановить враждебные армии на этом источнике энергии или рядом с ним." } } } },
    ["d4d2cf39"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Несмотря на нехватку сил, вызванную слабостью повелителя, Артас всё же ввязался в братоубийственную войну в Лордероне." }, { 8.42, "Тогда половина его уцелевших войск во главе с банши Сильваной Ветрокрылой вышла из-под его контроля и взяла власть в свои руки." }, { 17.76, "Призванный своим господином, Артас был вынужден передать командование Плетью своему заместителю Кел'Тузаду, а война тем временем охватывала все новые области Чумных земель." } } } },
    ["d4f8adf0"] = { d = 25.1, v = "dwarf-male", c = { x = { { 0.00, "Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила." }, { 12.90, "Однако стрела пролетела мимо." }, { 15.13, "Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек." } } } },
    ["d500f8e6"] = { d = 31.5, v = "gnome-male", c = { x = { { 0.00, "Дорогой будущий я!" }, { 1.40, "На этот раз не забудь про хлеб." }, { 3.67, "- два галлона ледяного молока" }, { 5.87, "- двадцать ломтиков выдержанного чеддера (крысы вечно всё подъедают)" }, { 10.93, "- один восхитительный шоколадный торт" }, { 13.67, "- Хотя нет, пусть будет два торта" }, { 16.13, "- четыре канистры взрывоопасного гоблинского ракетного топлива" }, { 20.73, "- две ториевые трубки" }, { 22.33, "- один преобразователь из истинного серебра" }, { 25.53, "-" }, { 25.60, "*Дальше надпись так размазана, что не разобрать ни слова.*" }, { 29.92, "два гирохронатома" } } } },
    ["d50cdb69"] = { d = 25.9, v = "narrator", c = { x = { { 0.00, "Сторожевой пост Алого ордена — башня на северо-востоке Тирисфаля, за могилой Фаола." }, { 6.41, "Орден держит гарнизон в этой глуши лишь затем, чтобы никто не подобрался к монастырю с его плохо защищённой северной стороны." }, { 16.07, "Командует постом жестокий капитан Мелраш, и именно отсюда, по сведениям палача Зуганда из Брилла, идут набеги на земли Отрёкшихся." } } } },
    ["d5137c28"] = { d = 30.2, g = 1, v = "orc-male", c = { m = { { 0.00, "Приветствую тебя, брат." }, { 1.89, "Изувеченная Длань выражает тебе своё почтение и надеется, что в нашей долине ты найдёшь, где применить своё ремесло." }, { 11.07, "Учти: мы пристально следим за твоими успехами и неудачами." }, { 15.81, "Мне поручено оценить твоё мастерство и сообщить, когда ты будешь готов к серьёзным делам." }, { 22.94, "Как будет время, навести меня в глубинах Логова." }, { 26.95, "-Руаг, наставник разбойников." } }, f = { { 0.00, "Приветствую тебя, сестра." }, { 2.16, "Изувеченная Длань выражает тебе своё почтение и надеется, что в нашей долине ты найдёшь, где применить своё ремесло." }, { 11.54, "Учти: мы пристально следим за твоими успехами и неудачами." }, { 16.39, "Мне поручено оценить твоё мастерство и сообщить, когда ты будешь готова к серьёзным делам." }, { 23.76, "Как будет время, навести меня в глубинах Логова." }, { 27.86, "-Руаг, наставник разбойников." } } } },
    ["d5235c47"] = { d = 19.7, v = "gnome-male", c = { x = { { 0.00, "И знаешь что?" }, { 0.93, "Если уж ему так там нравится, пусть попробует восстановить главу из книги, отправившись в Огненные Недра и покопавшись в куче пепла!" }, { 10.00, "Ха!" }, { 10.25, "Пока я там летал, обнаружил пресмыкающихся механиков в Лаборатории Виктора Нефариуса – им могут пригодиться Драконьи штуки." }, { 18.70, "Сбросить бомбы!" } } } },
    ["d526a9ad"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Бейл Модан — раскоп дворфов Стальгорна в холмах на юге Степей." }, { 5.18, "Здесь, у древних руин титанов, землекопы взрывают склоны и день и ночь грохочут машинами, а над ямами высится крепость Бейл'дан." }, { 15.76, "Прежде в этих холмах жило племя тауренов: их земли захвачены, и Ганн Каменное Копьё в одиночестве бродит по родному краю, так и не добившись справедливости миром." } } } },
    ["d543ede5"] = { d = 32.6, v = "narrator", c = { x = { { 0.00, "Они облекли планеты небесными слоями и бушующими атмосферами, воплощая свой непостижимый и дальновидный замысел, создавая порядок из хаоса." }, { 11.17, "Они научили древние примитивные племена приглядывать за своими детищами и поддерживать целостность созданных миров." }, { 20.45, "Титаны, которыми правила элитная группа – Пантеон, – создали порядок в сотнях миллионов миров, рассеянных по Великой Запредельной Тьме на заре творения." } } } },
    ["d55a9b16"] = { d = 51.3, v = "narrator", c = { x = { { 0.00, "Каргат — небольшая застава на западной окраине Бесплодных земель и единственный оплот Орды во всём Каз Модане, названный в честь орочьего вождя Каргата Острорука." }, { 12.26, "По приказу самого Тралла Каргатский экспедиционный корпус совершает отсюда вылазки в пустыню: главная его цель — проложить путь через Тлеющее ущелье к Чёрной горе, но и раскопки Ульдамана, которыми так дорожат дворфы, не остались без внимания орков." }, { 31.09, "Суровый климат, злобные звери и отсутствие помощи извне закаляют бойцов: как пишет глава разведчиков Ника Алый Шрам, выйдут отсюда лишь лучшие из воинов." }, { 42.87, "В Каргате есть таверна и конюшня, а ветрокрылы связывают северные и южные владения Орды в Восточных королевствах." } } } },
    ["d597bec3"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Великое море омывает западный берег Серебряного бора." }, { 4.56, "Это бескрайний океан, разделяющий континенты Азерота, а в самом его центре бушует Водоворот." }, { 12.34, "На побережье леса о нём напоминают лишь прибой, обломки кораблей на песке и серые сосны над обрывами." } } } },
    ["d5a07e88"] = { d = 19.0, v = "narrator", c = { x = { { 0.00, "Огромное древо стало символом вечного союза ночных эльфов и природы, а его жизнетворная энергия впоследствии исцелила весь мир." }, { 10.99, "Ночные эльфы дали своему Древу Жизни имя Нордрассил, что на их языке означало \"корона жизни\"." } } } },
    ["d5a18625"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Правительством Кель'Таласа стал совет Луносвета, хотя династия Солнечных Скитальцев также отчасти сохраняла политическую власть." }, { 9.50, "Включавший в себя семерых величайших эльфийских лордов совет заботился о безопасности эльфов и эльфийских земель." }, { 17.99, "Под защитой барьера высшие эльфы отвергли былые предупреждения кальдорай и с преступной беспечностью продолжали использовать магию практически во всех аспектах своей жизни." } } } },
    ["d5d7a61b"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Объединённые под одним знаменем, людские племена создали сильную, жизнерадостную культуру." }, { 7.05, "Торадин, король Аратора, знал, что таинственные эльфы на севере постоянно сражались с троллями, но отказался рисковать безопасностью своих людей ради скрытных незнакомцев." }, { 20.50, "Много месяцев прошло, прежде чем слухи о близком поражении эльфов распространились с севера." }, { 27.83, "Только тогда, когда измученные послы Кель'Таласа добрались до Строма, Торадин осознал истинную угрозу, идущую от троллей." } } } },
    ["d5f7dfd0"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "Приют в Ночных Лесах стоит в самом сердце Ясеневого леса, у великого древа, к востоку от лунного колодца." }, { 8.79, "Это застава защитников природы: здесь несут стражу хранители Круга Кенария, дриады и мерцающие дракончики, а с холма они следят за дорогой на север, в Осквернённый лес." }, { 22.52, "На вершине древа укрылся хранитель рощи, один из старших сыновей лесного бога Кенария: Совет Теней ищет его голову, и его стерегут пуще всего." } } } },
    ["d5faede3"] = { d = 21.5, v = "tauren-male", c = { x = { { 0.00, "Клык тролля из клана Кровавый Скальп:" }, { 3.27, "Клыки троллей из клана Кровавый Скальп из Тернистой долины обладают редким качеством." }, { 10.84, "Безнравственность Кровавых скальпов заключена в их клыках, и если их истолочь в порошок, можно выпустить их гибельную силу." } } } },
    ["d64b01d9"] = { d = 19.8, v = "narrator", c = { x = { { 0.00, "В конечном итоге Сильвана и её мятежники, назвавшие себя Отрёкшимися, объявили руины столицы Лордерона своей собственностью." }, { 9.68, "В подземельях под этими руинами они обустроили собственную крепость, поклявшись победить Плеть и изгнать из своих земель Кел'Тузада." } } } },
    ["d652c818"] = { d = 33.3, v = "human-male", c = { x = { { 0.00, "Дневник – день пятьсот двенадцать" }, { 2.38, "Бананы начали говорить со мной, и я многое узнал об их культуре." }, { 6.96, "Теперь я перестал бездумно разрушать их дома и поедать их детей." }, { 11.59, "Как же мало мне было известно о великой цивилизации, которую я уничтожал." }, { 16.81, "Кроме того, у меня, кажется, заканчиваются бутылки и бумага." }, { 21.19, "Когда я впервые оглядел ту огромную кучу бумаги, что выбросило волнами на берег, то подумал, что она не переведётся никогда." }, { 30.01, "Увы, скоро мне придётся прекратить свои записи." } } } },
    ["d666fe74"] = { d = 31.5, v = "narrator", c = { x = { { 0.00, "Башня Азоры – небольшая башня магов к востоку от Златоземья, на дороге к лесопилке." }, { 6.74, "Ею правит верховный маг Теокрит, а прислуживают ему гномы." }, { 11.52, "Маги Азоры давно враждуют с чернокнижником Моргантом из башни Илгалара в Красногорье, и обе башни без устали следят друг за другом с помощью магии." }, { 23.48, "По словам слуг, всё живое, что забредает слишком близко к башне, странно меняется под действием её чар." } } } },
    ["d669e88e"] = { d = 29.0, v = "nightelf-female", c = { x = { { 0.00, "Неясный шёпот, о волшебнике из Кирин Тор по имени Аругал." }, { 3.91, "Согласно тому, что я слышала, возможно, что он тоже вызывал воргенов." }, { 8.69, "Как бы мне ни было неприятно, придётся посоветоваться с этим волшебником, выяснить, что ему известно." }, { 15.52, "Воргены опасны, и я желаю остановить их нашествие." }, { 19.00, "Завтра же я отправлюсь в порт в Степях и оплачу путешествие в Новый мир." }, { 23.90, "Да пребудет со мной благословение Элуны, пока не будет выполнена моя работа." } } } },
    ["d67b5e54"] = { d = 36.1, v = "narrator", c = { x = { { 0.00, "Однажды он вернётся к своей жене и детям." }, { 3.66, "Наконец, Морган вернулся домой, но всё изменилось с тех пор, как он здесь был." }, { 10.33, "Когда-то зелёный лес был заражён и населён нежитью и монстрами." }, { 15.66, "Везде стояли разрушенные дома и фермы, и большую часть округи занимало кладбище возле Вороньего Холма." }, { 24.80, "Поражённый и сбитый с толку, Морган пришёл к своему дому и увидел одни развалины." }, { 31.95, "Не зная, что случилось с его родными местами, он" } } } },
    ["d67f35ef"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Сумеречная пещера — грот у подножия Лагеря Оленьего Шлема в северном Силитусе, где укрылась одна из общин Сумеречного Молота." }, { 9.81, "У входа разбит небольшой стан, а в глубине, среди факелов и тёмных алтарей, повелители культа проводят свои обряды." }, { 18.85, "Здесь прячутся самые опасные из сектантов, и ночные эльфы с башни наверху не спускают глаз с этого входа." } } } },
    ["d691b20e"] = { d = 9.0, v = "narrator", c = { x = { { 0.00, "Эти следы Второй войны служат грозным напоминанием о том, как опасно близка была орда к завоеванию Железных гор." } } } },
    ["d697ced7"] = { d = 17.8, v = "narrator", c = { x = { { 0.00, "Отпустить зверя:" }, { 1.38, "Спустя тридцать минут зверь вернётся к себе домой в Пустоту." }, { 6.24, "Примечание:" }, { 7.18, "В этом своём стремлении зверь МОЖЕТ броситься со скалы или упасть с горы." }, { 13.13, "Не горюйте о потере ищейки Скверны, лучше вызовите другую." } } } },
    ["d69cff0d"] = { d = 36.2, v = "human-male", c = { x = { { 0.00, "*(Из-за пятен возможно прочесть лишь часть журнала.)*" }, { 4.08, "Ульдаман, день третий." }, { 5.80, "Поверить не могу, как я был глуп." }, { 8.28, "Эти злобные дворфы Тенегорна провели меня, как простачка." }, { 12.76, "Мои раны заживают медленно, я безусловно отравлен ядом." }, { 17.10, "Я чувствую, как мои силы тают." }, { 19.51, "Несмотря на это я должен двигаться вперёд..." }, { 22.88, "...хуже того, ожерелье, что сделал для меня гном, треснуло!" }, { 27.43, "Три его самых больших драгоценных камня потеряны." }, { 31.28, "Я должен найти их, без них ожерелье будет лишено всей своей силы." } } } },
    ["d6c529c7"] = { d = 30.7, v = "narrator", c = { x = { { 0.00, "Очи Матери-Земли взирали сверху на созданные ею земли." }, { 5.33, "Её правое око, Ан'ше – солнце, дарило тепло и свет всей земле, а левое, Му'ша – луна, приносило покой и сон детям рассвета." }, { 17.01, "Сила её взгляда была такова, что пока одно её око дремало, небо поворачивалось другой стороной." }, { 26.15, "Её любящий взгляд превращал день в ночь, и наоборот." } } } },
    ["d6fbb3c4"] = { d = 12.9, v = "narrator" },
    ["d6ff13e3"] = { d = 19.3, v = "narrator", c = { x = { { 0.00, "Столп поглощения — сооружение титанов на террасе: каменная колонна, покрытая рунами и окутанная гудящей энергией." }, { 9.96, "Что именно она поглощает и зачем, знали лишь те, кто её возвёл; смертным остаётся лишь смотреть и не касаться." } } } },
    ["d708057b"] = { d = 12.7, g = 1, v = "creature/ancient", c = { m = { { 0.00, "Знай, охотник, эти демоны дерутся только по своим правилам." }, { 5.83, "Если им покажется, что одолеть тебя нельзя, они сбегут." }, { 11.32, "ИДИ К НИМ ОДИН." } }, f = { { 0.00, "Знай, охотница, эти демоны дерутся только по своим правилам." }, { 5.81, "Если им покажется, что одолеть тебя нельзя, они сбегут." }, { 11.19, "ИДИ К НИМ ОДНА." } } } },
    ["d73feb92"] = { d = 24.0, g = 1, v = "human-female", c = { m = { { 0.00, "Брат Нилз, мой виноград спасён!" }, { 2.12, "Путник, предъявитель сего письма, спас мой наводненный головорезами виноградник и собрал весь виноград, что я не успела собрать." }, { 11.14, "Несмотря на то что бандиты всё ещё бродят у реки, практически весь мой урожай был спасён." }, { 17.32, "Ты можешь добавить к своим запасам полные корзины винограда." }, { 21.70, "Да защитит нас Свет," }, { 23.11, "-Милли Осворт" } }, f = { { 0.00, "Брат Нилз, мой виноград спасён!" }, { 2.09, "Путница, предъявитель сего письма, спасла мой наводненный головорезами виноградник и собрала весь виноград, что я не успела собрать." }, { 11.27, "Несмотря на то что бандиты всё ещё бродят у реки, практически весь мой урожай был спасён." }, { 17.35, "Ты можешь добавить к своим запасам полные корзины винограда." }, { 21.66, "Да защитит нас Свет," }, { 23.05, "-Милли Осворт" } } } },
    ["d7463565"] = { d = 32.0, v = "dwarf-male", c = { x = { { 0.00, "Клянусь бородой Магни, нам нужно многое обсудить, а времени очень мало." }, { 5.34, "Как можно скорее найди меня в Старой Наковальне, что в Холодной долине." }, { 10.61, "Там и начнём обучение." }, { 12.19, "Я мог бы открыть тебе секреты быстроты движений… но об этом говорить ещё рано." }, { 17.92, "Сначала тебе нужно научиться правильно держать топор, привыкнуть к весу доспехов и запаху пота, заливающему лицо в тяжёлом бою…" }, { 27.34, "Для начала этого будет достаточно." }, { 29.91, "-Тран Корман, наставник воинов" } } } },
    ["d750fc0f"] = { d = 29.0, v = "narrator", c = { x = { { 0.00, "Хотя доподлинное происхождение хаотичной Вселенной неизвестно, очевидно, что могущественные создания явились, дабы привнести в миры порядок и обеспечить тем, кто будет их населять, мир и спокойствие." }, { 15.56, "Титаны – колоссальные железнокожие боги из далёких пределов космоса – занимались обустройством встреченных ими миров." }, { 24.77, "Они возводили высокие горы и создавали морские пучины." } } } },
    ["d75de218"] = { d = 29.5, v = "narrator", c = { x = { { 0.00, "Таверна «Петля висельника» — постоялый двор в Брилле, единственная настоящая таверна во владениях Отрёкшихся." }, { 8.35, "Под её крышей собираются наставники воинов, жрецов, магов, разбойников и чернокнижников, а хозяйка держит комнаты для усталых путников." }, { 18.80, "В подвалах, впрочем, не так уютно: там в клетках держат пленных — ревнителя Алого ордена и дворфа, на которых аптекари испытывают свои яды." } } } },
    ["d78dade0"] = { d = 14.3, v = "nightelf-male", c = { x = { { 0.00, "Это риск, но сейчас у меня нет других зацепок..." }, { 3.89, "Когда я узнаю больше, я запишу детали сюда, но до тех пор я буду работать над тем, чтобы найти части жезла и помочь Ясеневому лесу." } } } },
    ["d79dbaa7"] = { d = 36.7, v = "narrator", c = { x = { { 0.00, "Долина Свирепого Утёса — цепь пещер в Высокогорных дебрях на западе Фераласа, недалеко от Забытого берега." }, { 8.36, "Здесь обитают йети Свирепого Утёса — свирепые звери, чьи толстые шкуры высоко ценят кожевники Крепости Оперённой Луны." }, { 17.72, "Говорят, огры Гордунни вырубили леса на прежних землях йети, и звери ушли на восток, в холмы гноллов." }, { 25.94, "В глубине первого туннеля гномы потеряли одну из своих механических куриц серии оу-оу-экс, и её сигнал бедствия до сих пор ловят в округе." } } } },
    ["d7ad3010"] = { d = 24.2, g = 1, v = "gnome-male", c = { m = { { 0.00, "ВНИМАНИЕ:" }, { 0.74, "Ничего не говори!" }, { 2.08, "Не оглядывайся!" }, { 3.22, "За тобой могут следить." }, { 5.02, "Меня зовут Аламар Гримм." }, { 6.90, "Я обучаю тех, кого интересует мудрость и сила из… из других миров." }, { 11.86, "Меня попросили связаться с тобой и предложить тебе услуги учителя." }, { 16.88, "Когда будешь готов, ищи меня на задворках Старой Наковальни." }, { 21.51, "-Аламар Гримм, наставник чернокнижников" } }, f = { { 0.00, "ВНИМАНИЕ:" }, { 0.73, "Ничего не говори!" }, { 2.06, "Не оглядывайся!" }, { 3.20, "За тобой могут следить." }, { 4.99, "Меня зовут Аламар Гримм." }, { 6.86, "Я обучаю тех, кого интересует мудрость и сила из… из других миров." }, { 11.79, "Меня попросили связаться с тобой и предложить тебе услуги учителя." }, { 16.78, "Когда будешь готова, ищи меня на задворках Старой Наковальни." }, { 21.44, "-Аламар Гримм, наставник чернокнижников" } } } },
    ["d7b8f95e"] = { d = 12.2, v = "human-female", c = { x = { { 0.00, "Пришлось отправить в Даларан другого посланца." }, { 3.17, "Мне стало известно, что они прочёсывают руины возле нашей защитной сферы в поисках подвески." }, { 9.44, "Остаётся лишь надеяться, что мы не опоздали." } } } },
    ["d7c9618e"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "Южные врата соединяют Дун Морог с юго-западом Лок Модана и выводят путника в Долину Королей." }, { 7.16, "Посреди перевала стоит застава горных пехотинцев Стальгорна, которые давно очистили окрестности от опасного зверья, так что здесь спокойнее, чем у северных соседей." }, { 19.62, "Через заставу проходит большинство путников, идущих в Телсамар или из него." }, { 25.47, "Среди пехотинцев служит и Велларт Ячменовар из известной семьи пивоваров." } } } },
    ["d7f48da6"] = { d = 16.9, v = "narrator", c = { x = { { 0.00, "ПИЛОНЫ: ИНСТРУКЦИЯ ПО ЭКСПЛУАТАЦИИ." }, { 3.15, "\"Руководство по сбору и использованию кристаллов силы Кратера Ун'Горо\"." }, { 9.53, "Глава один: Северный пилон." }, { 12.11, "Глава два: Восточный пилон." }, { 14.62, "Глава три: Западный пилон." } } } },
    ["d7f56c38"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "Чумная лощина — узкий проход в горах на западе Внутренних земель, к северо-западу от сторожки Кель'Данил." }, { 7.89, "По нему можно выйти на север, к Кэр Дарроу и в Западные Чумные земли." }, { 13.10, "Над тропой висит ядовитый туман, тянущийся из-за перевала, и он резко отличается от свежести остальных лесов." }, { 21.25, "В лощине не живёт никто, и это, пожалуй, самое верное предупреждение для путника." } } } },
    ["d8125e07"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Опустошённый берег — южное побережье Азшары у границы с Дуротаром: пляжи и утёсы, изрезанные заливчиками, усеянные руинами и остовами кораблей." }, { 11.76, "Как и у Острых рифов, здесь опасны и мели, и обитатели — мурлоки, гидры и макрура." }, { 18.58, "На западной оконечности берега на холме стоит домик гномов-инженеров, торгующих припасами для мастеров." } } } },
    ["d81c5e57"] = { d = 23.6, v = "narrator", c = { x = { { 0.00, "Виноградники Маклура тянутся по южному Элвинну, неподалёку от фермы Стоунфилдов, с которыми Маклуры ведут давнюю вражду." }, { 9.24, "Между лоз то и дело шастает мальчишка Билли Маклур, а среди виноградников пасутся целые стада кабанов." }, { 17.22, "Юная Мэйбелл Маклур мечтает сбежать отсюда к своему возлюбленному из семьи соседей." } } } },
    ["d84618c5"] = { d = 36.5, v = "scourge-female", c = { x = { { 0.00, "Скверна и зло, с которыми, как принято считать, сопряжена тайная магия, – ничто по сравнению с тем, что мы уже пережили." }, { 11.46, "Мы больше не жертвы." }, { 13.46, "Мы сами выбираем свою судьбу." }, { 16.41, "Сильвана указала нам путь – она доказала, что у нас есть своя воля и что мы не обязаны подчиняться этому ублюдку Артасу." }, { 27.88, "Найди меня в церкви – я расскажу тебе больше… если захочешь." }, { 33.87, "- Изабелла, наставница магов" } } } },
    ["d860934e"] = { d = 35.6, v = "nightelf-male", c = { x = { { 0.00, "Если я не смогу найти камень, спрятанный в храме, он может оказаться у одного из мурлоков." }, { 6.93, "Древковая часть" }, { 8.10, "Эта часть жезла была дана древням возле леса, который сейчас называется Осквернённым." }, { 14.68, "Ни фурболги, ни мой народ не могли заподозрить, что такие величественные создания падут жертвой порчи, охватившей эти земли." }, { 24.15, "Мои исследования говорят мне, что стражи хранили эту часть в сундуке, на небольшой лужайке." }, { 31.08, "Чтобы узнать больше, мне нужно будет поговорить с Шаэл'дрин." } } } },
    ["d8b3fa12"] = { d = 21.7, v = "narrator", c = { x = { { 0.00, "Водрузив на свою голову шлем, Артас стал новым Королём-личом." }, { 4.98, "Души Нер'зула и Артаса слились воедино, обретя небывалое могущество." }, { 10.62, "Увидев, что Артас стал самым грозным существом в истории этого мира, Иллидан со своими войсками был вынужден бежать обратно в Запределье." } } } },
    ["d8bdbe74"] = { d = 30.9, v = "tauren-female", c = { x = { { 0.00, "День второй." }, { 1.05, "От утёсов на востоке, где наш край граничит с равнинами Степей, эхом отдаётся громовой топот, будто несётся целое стадо." }, { 10.87, "Быть может, это очередной табун зебр или газелей, а может, разъярённый громовой ящер – но шум не стихает и глубокой ночью, когда такие звери обычно уже спят." }, { 23.98, "Я пойду дальше, чтобы разузнать больше, но буду держаться на безопасном расстоянии." } } } },
    ["d93cc924"] = { d = 24.1, v = "named/13717", c = { x = { { 0.00, "Далеко в Долине Копий стоит святой храм Мародона." }, { 4.14, "Мало того, скоро ты узнаешь, почему я попросил тебя о помощи в делах." }, { 9.97, "Там, за дверями, проходить за которые могут лишь духи и самые чтимые жрецы, есть некто по имени Безымянный Пророк." }, { 19.36, "Он превыше всех в духовных делах и старше многих старейшин." } } } },
    ["d950b879"] = { d = 27.3, v = "narrator", c = { x = { { 0.00, "Она верила, что древние эльфы и люди-старейшины, возглавлявшие совет, были слишком непреклонны в своих решениях и не смотрели в будущее достаточно далеко, чтобы положить конец войне против хаоса." }, { 15.02, "Раздражённая слишком долгим обсуждением и дебатами, она жаждала показать своим завистникам и старшим по званию, на что она способна, и предпочла храбрость мудрости." } } } },
    ["d996808c"] = { d = 20.1, v = "narrator", c = { x = { { 0.00, "Застава Алого ордена — сторожевая башня на холмах восточного Тирисфаля." }, { 5.58, "Отсюда воины ордена следят за главной дорогой и прикрывают подступы к монастырю с фланга." }, { 12.56, "Командует башней капитан Вакон, чьи отряды совершают набеги на земли Отрёкшихся близ фермы Балнира." } } } },
    ["da28c4f1"] = { d = 36.3, v = "human-male", c = { x = { { 0.00, "После того как я выжил при побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен." }, { 7.93, "Я провёл в нём несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза." }, { 16.04, "Но оттуда, с моего места я мог видеть, что эти фермеры – славные ребята." }, { 21.18, "Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять." }, { 28.92, "И стало ещё тяжелее после случившегося ужаса в шахте." }, { 32.72, "Так что я оставался в укрытии." }, { 34.81, "И это спасло мне жизнь." } } } },
    ["da35f979"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Лагерь Кэгг лежит на юго-западе Бесплодных земель, у подножия скал перед Гротом Гнилобрюхих." }, { 7.56, "Здесь собралось больше всего огров племени: громилы, шаманы, мистики и охотники на драконов." }, { 15.13, "Между лагерями ходит их главарь То'грун, огромный огр, что держит племя в кулаке." }, { 21.81, "Стервятники кружат над самыми шатрами, чуя поживу." } } } },
    ["da47a7e3"] = { d = 36.7, v = "narrator", c = { x = { { 0.00, "Армии Альянса под предводительством сэра Андуина Лотара, Утера Светоносного и адмирала Даэлина Праудмура отбросили орков к югу, в разорённые земли Азерота – первого королевства, павшего под яростным напором орков." }, { 16.39, "Силам Альянса под командованием сэра Лотара удалось оттеснить кланы, которыми предводительствовал Молот Рока, из Лордерона обратно в подконтрольные оркам области Азерота." }, { 29.99, "Войска Лотара окружили вулканическую орочью цитадель – Пик Чёрной горы – и осадили её." } } } },
    ["da6661bb"] = { d = 37.4, v = "orc-male", c = { x = { { 0.00, "Я пишу это послание самыми могущественными чернилами, какие только могу создать." }, { 6.97, "Они принесут проклятье любому, кроме тебя." }, { 10.72, "Я вызываю могущественных демонов Круговерти Пустоты просто для развлечения." }, { 17.08, "Я убиваю своих врагов, пока они спят." }, { 20.37, "Ты уже видел могущество, которое можно обрести на моём пути." }, { 25.57, "Мои братья этому рады." }, { 27.64, "Когда освоишься, найдёшь меня в глубине Логова." }, { 31.70, "Нам надо поговорить о важных вещях." }, { 34.76, "-Нарток, наставник чернокнижников" } } } },
    ["da9daa46"] = { d = 36.5, v = "narrator", c = { x = { { 0.00, "Подводный риф тянется вдоль южного берега нагорья и издавна губит корабли: здесь нашли последнюю гавань и два судна пиратов Черноводья." }, { 10.61, "Под водой залива лежат руины древнего эльфийского города, в которых поселились наги под началом своего принца." }, { 19.38, "Говорят, наги научились повелевать приливами, и не одна команда, искавшая укрытия в бухте Фальдира, погибла из-за их колдовства." }, { 29.49, "В камнях рифа скрыты окаменевшие эльфийские самоцветы, которые уже учуяли приборы гномов." } } } },
    ["dab96f07"] = { d = 17.4, v = "narrator", c = { x = { { 0.00, "«Бурун» — западный из трёх фрегатов Кровавого Паруса, что стоят у островков Гибельного берега." }, { 6.85, "Команда ждёт приказа флотоводца, чтобы двинуться на Пиратскую бухту." }, { 11.86, "Алые паруса на горизонте заставляют торговцев сдаваться прежде первого залпа." } } } },
    ["dabb5c53"] = { d = 16.6, v = "narrator", c = { x = { { 0.00, "Участок Демонта лежит к западу от Луноречья." }, { 3.47, "От прежней фермы, как и от Мёртвой пашни, почти ничего не осталось." }, { 8.60, "Уцелевшие постройки заняли агенты Братства Справедливости, и здесь, на окраине их вотчины, чужаков не ждут." } } } },
    ["dad1dbaf"] = { d = 82.2, v = "narrator", c = { x = { { 0.00, "Штормград — столица людей и сердце Альянса, белокаменный город на юге Восточных королевств." }, { 7.30, "В Первую войну Орда сровняла его с землёй, а после Второй войны Гильдия каменщиков заново возвела его из белого камня, вернув прежнее величие." }, { 18.83, "Но знать так и не заплатила мастерам, и обиженные каменщики ушли в Западный край, где со временем превратились в Братство Справедливости." }, { 29.42, "Король Вариан Ринн пропал при загадочных обстоятельствах, и ради порядка корону возложили на его юного сына Андуина." }, { 38.73, "Регентом при мальчике-короле стоит верховный лорд Болвар Фордрагон, а при дворе большое влияние имеет леди Престор, чьё слово в совете весит не меньше королевского." }, { 51.83, "Над крышами возвышается Собор Света — духовное сердце королевства, а в Торговом квартале не смолкает гул сделок." }, { 60.70, "В Квартале Дворфов гудят кузни и уходит под землю Подземный поезд, связавший Штормград со Стальгорном." }, { 68.86, "Старый город хранит свои тайны, Парк дышит зеленью, а в крепости Штормграда решаются судьбы королевства." }, { 77.24, "Этот город был разрушен и восстал из руин, и в этом — его сила." } } } },
    ["db16cbef"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Опустошительная Вторая война против орочьей орды оставила Альянс Лордерона в потрясении и беспорядке." }, { 7.64, "Кровожадные орки, которых возглавлял могущественный вождь, Оргрим Молот Рока, не только силой проложили себе путь через дворфийские земли Каз Модана, но и стёрли с лица земли множество центральных провинций Лордерона." }, { 23.86, "Жестокие орки разграбили даже отдалённое эльфийское королевство Кель'Талас, прежде чем их разрушительный поход был остановлен." } } } },
    ["db2a16ab"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Тьмой они созданы – злу нет предела" }, { 3.33, "Тому, что на Вершине Тумана Багрового воссело." }, { 7.76, "Несётся над миром смех наглеца," }, { 10.66, "Чьим элементалям не видно конца." }, { 13.73, "Тебе с этим магом оружье скрестить" }, { 17.14, "И в схватке смертельной его победить." } } } },
    ["db39053f"] = { d = 19.5, v = "narrator", c = { x = { { 0.00, "Оплот Легаши — укреплённое гнездо сатиров Легаши на севере Азшары." }, { 5.41, "Здесь, среди обломков высокорождённых, демонические отродья собираются под защитой стен и тёмных знаков, и жар их костров виден издалека." }, { 16.24, "Путнику лучше обойти это место стороной." } } } },
    ["db3948b2"] = { d = 23.4, v = "dwarf-male", c = { x = { { 0.00, "Покинув Лабиринты, я направлюсь в Тысячу Игл, а затем на запад в сторону Таланаара, к границе с таинственным лесом Фералас." }, { 9.16, "Там я найду друида, известного как Хранитель дорог Фалфиндел." }, { 13.74, "Пытаясь узнать прошлое моего народа, я, кажется, наткнулся на что-то большее." }, { 19.60, "Теперь в моих руках – безопасность всего Альянса..." } } } },
    ["db54d089"] = { d = 22.3, v = "narrator", c = { x = { { 0.00, "Не знавшие о том, что Саргерас намерен уничтожить плоды их бесчисленных трудов, титаны продолжали передвигаться от мира к миру, формируя и приводя в порядок те планеты, что они находили пригодными." }, { 14.73, "В своём путешествии они случайно попали в небольшой мир, который его обитатели позже назвали Азеротом." } } } },
    ["db6000ee"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Гниющий сад раскинулся на юге Сумеречного леса, между усадьбой Йоргена на западе и Безмятежным кладбищем на востоке, к юго-западу от Темнолесья." }, { 11.47, "Когда-то здесь были плодовые сады, но деревья медленно умирают под вечными сумерками, а в обветшалых постройках устроили логово воргены из стаи Ночной Погибели." }, { 24.24, "Одни колдуют у костров, другие сторожат в тени, так что заходить сюда лучше с оружием наготове." } } } },
    ["db6e29e4"] = { d = 46.0, v = "narrator", c = { x = { { 0.00, "Рыболовный чемпионат Тернистой долины!" }, { 2.89, "Проводится воскресным днём, с четырнадцати до шестнадцати часов." }, { 7.60, "Закиньте удочки где угодно на побережье Тернистой долины (кроме Пиратской бухты) и ищите косяки вкуснорыбы, что появляются вдоль берега!" }, { 17.76, "Если ваш поплавок попадёт прямо в косяк, вы поймаете особенную рыбу вместо обычных, которых полно в Тернистой долине." }, { 26.57, "Первый, кто выловит сорок вкуснорыб, сможет сдать их Мастеру Окуневой Приманке в Пиратской бухте и получить вознаграждение!" }, { 35.72, "Даже если вам не удалось поймать сорок вкуснорыб первому, вы сможете обменять их на деньги, а за некоторых рыб можно получить ценные призы!" } } } },
    ["db74bd56"] = { d = 23.6, v = "narrator", c = { x = { { 0.00, "Мир между орками и людьми был нарушен с прибытием огромного флота Альянса под командованием отца Джайны, Великого адмирала Даэлина Праудмура." }, { 10.87, "Этот флот покинул Лордерон перед самым падением королевства." }, { 15.81, "В течение долгих месяцев плавания адмирал Праудмур искал любых уцелевших союзников по Альянсу." } } } },
    ["dbb17bb4"] = { d = 36.3, v = "narrator", c = { x = { { 0.00, "Высота Найджела — форпост Альянса в северных горах Пустошей, среди скал и старых эльфийских развалин." }, { 8.14, "Гарнизоном командует капитан Штормграда, следящий за войной Маграм и Гелкис: кто бы ни победил, он станет угрозой Альянсу." }, { 17.88, "Рядом стоит Круг Кенария: хранитель рощи Марандис и его сёстры-дриады пришли из Когтистых гор, чтобы вернуть из Мародона останки Зейтара." }, { 28.90, "Тут же Горная корпорация ищет пропавший груз Карнитола, а Алый орден держит своего посланника." } } } },
    ["dbd97b95"] = { d = 37.8, v = "narrator", c = { x = { { 0.00, "В распоряжении пауков-повелителей Неруба имелось немалое войско и сеть подземных тоннелей, простирающихся почти на половину территории Нордскола." }, { 10.95, "Они нападали небольшими отрядами, и это не позволяло Королю-личу разделаться с ними раз и навсегда." }, { 18.54, "В конце концов Нер'зулу удалось победить в этой войне, нанеся сокрушительный удар по воинам Неруба." }, { 26.21, "Вместе со зловещими повелителями ужаса и огромной армией нежити Король-лич напал на Азжол-Неруб и обрушил их подземные храмы на головы пауков-повелителей." } } } },
    ["dbeb45a4"] = { d = 17.0, v = "narrator", c = { x = { { 0.00, "Руины Мизжа лежат к юго-востоку от лагеря Гром'гол." }, { 4.15, "Их заняли громилы и знахари огров Мош'Огг, которые отсюда устраивают засады на караваны Орды, идущие в Каменор." }, { 12.96, "Древние камни троллей теперь служат ограм укрытием." } } } },
    ["dbf5fe14"] = { d = 25.7, v = "human-male", c = { x = { { 0.00, "После того как я вытащил косу, они напали на нас отовсюду, выползая из укромных щелей под нашими ногами и падая на нас откуда-то с потолка." }, { 9.60, "Половина наших людей погибла в эти первые минуты паники." }, { 13.62, "Оставшиеся, включая меня, пытались бежать." }, { 16.60, "Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье." } } } },
    ["dc423fca"] = { d = 45.8, v = "skyborne-female", c = { x = { { 0.00, "*(Прикоснувшись к светящемуся кристаллу, вы ощущаете порыв ветра, который доносит тихие слова.)*" }, { 8.24, "Высший орден следил за тобой, и мы уверены, что в тебе скрыт большой потенциал." }, { 14.63, "Духи ветра оставили остров Зефрис, и сейчас такие многообещающие маги, как ты, нужны нам как никогда." }, { 22.83, "Чтобы наш народ научился полагаться на себя и пережил эти трудные времена, нужно использовать наши знания о магии и раскрыть секреты этих земель." }, { 34.73, "Разыщи меня в деревне Тендал, на нижнем уровне великого древа." }, { 39.89, "Твоё обучение начнётся по-настоящему." }, { 42.79, "Дорийя Громкий Шёпот, наставница магов" } } } },
    ["dc4ec722"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "Владыка Приливов таял." }, { 1.99, "С каждым приливом и отливом он терял часть себя, утрачивал свою телесную форму – исчезая и снова появляясь, – пока, наконец, в свой смертный час он не отправился на берег, на котором нашёл Камень, и не вошёл в море, исчезнув в последний раз." }, { 22.17, "Несколько поколений спустя Камень Приливов снова вынесло прибоем на берега Тернистой долины, и тролль, принёсший его в Зул-Гуруб, был избран новым" } } } },
    ["dc50e9b5"] = { d = 32.7, v = "orc-male", c = { x = { { 0.00, "Ниже находится список предметов, необходимых для создания твоей брони:" }, { 5.58, "Закопчённые слитки железа кобольдов Утёса Ветрорезов, что обитают в Руднике Ветрорезов в Когтистых горах." }, { 13.71, "Толчёный азурит, который можно достать у хилсбрадских шахтёров." }, { 18.59, "Железные слитки можно взять у горняков или добыть в месторождениях железа, если ты горняк." }, { 25.73, "Сосуд флогистона, который надо добыть у иглогрива по имени Ругуг из Лабиринтов Иглошкурых." } } } },
    ["dc5f2158"] = { d = 50.4, v = "narrator", c = { x = { { 0.00, "Пещеры Времени — древнее логово Ноздорму, Аспекта времени, и его бронзовых драконов в горах восточного Танариса." }, { 9.22, "С тех пор как мир был молод, бронзовые драконы стерегут этот извилистый лабиринт, следя, чтобы ход времени оставался неизменным, и по воле титанов не пускают внутрь смертных." }, { 23.19, "Вход охраняют драконы Хроналис, Оккулус и Тик, а у самых ворот сидит Анахронос, наследник Ноздорму." }, { 31.24, "Именно он первым понял, какую угрозу несут силитиды, гнездящиеся в дальних углах пустыни, и не забыл войну Зыбучих песков." }, { 41.34, "Что скрыто в глубине пещер, знают лишь драконы, и тому, кто ступает под их своды, лучше держаться от них подальше." } } } },
    ["dc699bdb"] = { d = 26.6, v = "dwarf-male", c = { x = { { 0.00, "ПЯТЫЙ ДЕНЬ." }, { 0.79, "Оставил парня присматривать за лагерем, а сам прокрался к пещере, чтобы немного осмотреться." }, { 6.98, "Троллей здесь огромное количество." }, { 9.29, "Чтобы очистить пещеру от этих паразитов потребуется немало солдат." }, { 13.85, "Я вспомнил, что в последнее время я вообще не видел троггов." }, { 17.91, "Они появляются в регионе в огромных количествах, но они настолько примитивны, что вряд ли представляют угрозу." }, { 25.26, "Хотя поживём – увидим." } } } },
    ["dc7353b8"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "Логово Залашьи — небольшая пещера на восточном берегу Танариса, дом одинокого наги по имени Залашья." }, { 8.34, "Он бродит между своей норой и полосой прибоя и подолгу смотрит на воду, словно ждёт кого-то с моря." }, { 16.67, "Зачем нага поселился в пустыне и что связывает его с Южными морями, никто из гоблинов не знает." } } } },
    ["dc746f6f"] = { d = 28.8, v = "narrator", c = { x = { { 0.00, "Судьба Джозефа Редпат" }, { 1.85, "Джозеф Редпат погиб во время битвы при Дарроушире." }, { 6.07, "Его искалеченная душа стала совершенно новым существом, несущим великое зло всему Лордерону." }, { 13.77, "Силы Альянса в конечном счёте победили Редпата на пустоши Гаррона в восточной части Андорала." }, { 21.47, "Его щит до сих пор лежит возле амбара на чумной ферме, и приспешники Плети помнят об этом." } } } },
    ["dc7ff7ad"] = { d = 21.8, v = "dwarf-male", c = { x = { { 0.00, "Уже почти неделю нет ни капли эля." }, { 3.55, "ШЕСТОЙ ДЕНЬ." }, { 4.79, "Опять похолодало." }, { 6.57, "Идёт снег." }, { 7.54, "Тролли." }, { 8.34, "Эля нет." }, { 9.23, "СЕДЬМОЙ ДЕНЬ." }, { 10.56, "Снег белеет," }, { 11.80, "Небо синеет," }, { 13.13, "Волки воют," }, { 14.38, "А эля всё нет." }, { 15.80, "ВОСЬМОЙ ДЕНЬ." }, { 17.13, "Тролли, возможно, не такая уж проблема." }, { 21.03, "Их много," } } } },
    ["dd11123f"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Курганы Иглошкурых — древняя столица свинобразов, лабиринт из терновых лоз, выросших, по преданию, из крови полубога-вепря Агамаггана." }, { 10.70, "Здесь жили верховные жрецы племени, но после Третьей войны в терновые залы пришла Плеть: лич подчинил себе свинобразов, и их святыня превратилась в оплот нежити." }, { 23.65, "Чума расползлась по лабиринту, а племя ведёт отчаянную борьбу за свой город, пока холод Плети не пополз по всем Степям." } } } },
    ["dd1688db"] = { d = 22.5, v = "narrator", c = { x = { { 0.00, "Во время атаки Легиона на Ясеневый лес Иллидан был освобождён из своей тюрьмы, где он провёл в заточении десять тысяч лет." }, { 9.20, "Сначала Иллидан пытался помочь своим товарищам, но вскоре он принял своё истинное обличие и поглотил энергию могущественного волшебного артефакта под названием Череп Гул'дана." } } } },
    ["dd22eb5a"] = { d = 38.5, v = "narrator", c = { x = { { 0.00, "Тролли-знахари содрогнулись и воззвали к своему владыке." }, { 5.04, "Мин'лот смотрел на горы, поднявшиеся из моря, обречённый и несгибаемый." }, { 11.28, "Он повернулся к ученикам и прошептал свои последние слова, которые тролли запечатлели в камне." }, { 19.68, "Затем Мин'лот повернулся к надвигающимся краккенам." }, { 24.24, "Он нахмурился и метнул в них свой посох." }, { 27.76, "Это было его последнее деяние." }, { 30.64, "Краккены направили свою ярость на Мин'лота, и океан обрушился на И'лалай." }, { 37.20, "И его не стало." } } } },
    ["dd46bad3"] = { d = 23.3, v = "troll-male", c = { x = { { 0.00, "Мы призываем тебя, Занза Зулдазара." }, { 3.09, "Благослови тех, что помощи твоей ищут, Лоа Занза." }, { 7.43, "Благослови тех, что хотят помочь Зандаларскому народу." }, { 12.07, "Помоги нам в эти трудные времена." }, { 15.01, "Помоги нам, Лоа." }, { 16.48, "Дай нам силу сразить врагов наших." }, { 19.49, "Дай нам силу сокрушить Кровавого Бога ещё раз." } } } },
    ["dd4ce197"] = { d = 25.9, v = "dwarf-male", c = { x = { { 0.00, "Сосуд флогистона:" }, { 1.34, "Последняя стадия создания брони потребует чрезвычайно горячего кузнечного горна." }, { 7.35, "Чтобы обеспечить необходимый уровень жара, мне понадобится сосуд флогистона." }, { 13.03, "Единственно известный источник данной субстанции – легендарный иглогрив, Ругуг, и он не отдаст её без боя." }, { 20.85, "Ругуг обитает в глубинах Лабиринтов Иглошкурых, в южной части Степей." } } } },
    ["dd5f9f99"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Строптивая берёт начало в озере на склонах Хиджала и водопадами спускается в низины, чтобы широкой быстрой рекой отделить Ясеневый лес от Азшары." }, { 12.11, "Дальше к югу она становится границей Дуротара и Степей и впадает в Великое море возле Кабестана." }, { 20.31, "Через реку перекинут единственный здесь мост: за ним начинается дорога в Ясеневый лес, а у самого берега Азшары стоит застава Талрендис." } } } },
    ["dda6326a"] = { d = 35.3, v = "narrator", c = { x = { { 0.00, "Долина Галарделл лежит на северо-востоке Красногорья, в стороне от озера." }, { 5.64, "Над ней возвышается башня Илгалара, где обосновался чародей Моргант, а сама долина кишит гноллами стаи Темношкуров, которых он подчинил своей тайной магией." }, { 17.48, "Ими командует лейтенант Фангор, объявленный в Приозёрье предателем Штормграда: стоит напасть на него, и он созывает на помощь всю стаю." }, { 27.61, "Мировой судья Соломон приговорил его к смерти и назначил награду тому, кто принесёт его лапу в ратушу." } } } },
    ["ddadb93b"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Туралион, наиболее приближенный к Лотару командир, поднял его окровавленный щит и призвал своих поражённых горем собратьев нанести со всей яростью ответный удар." }, { 13.04, "Под истрёпанными знамёнами Лордерона и Азерота воинство Туралиона разбило почти всю армию Молота Рока в славной, но жестокой сече." } } } },
    ["ddb7206d"] = { d = 31.0, v = "human-male", c = { x = { { 0.00, "Сегодня Синдикат контролирует лишь малые силы, но они хорошо знают эту область и собрали достаточное количество воинов для выполнения задач." }, { 9.64, "С должным руководством, я уверен, Синдикат захватит Альтерак довольно скоро." }, { 14.85, "Мы убедили Синдикат направиться в город Стромгард неподалёку в нагорье Арати." }, { 20.07, "Этот город – поле боя между нашими силами, ограми и людьми Стромгарда, но мы думаем, что продумав тщательную тактику, мы завладеем этим когда-то великим городом." } } } },
    ["ddeefade"] = { d = 22.4, v = "narrator", c = { x = { { 0.00, "Стром по-прежнему оставался центром Аратора, но на континенте Лордерон возникло множество новых городов-государств." }, { 9.15, "Гильнеас, Альтерак и Кул-Тирас были первыми среди этих городов-государств, и хотя во всех этих городах были свои обычаи и своя экономика, все они подчинялись Строму." } } } },
    ["de1b1d2c"] = { d = 19.8, v = "dwarf-male", c = { x = { { 0.00, "Но мне не пришлось долго наслаждаться успехом." }, { 3.29, "На вершине утёса, прямо над несчастным Барнилом, появились несколько силуэтов." }, { 8.82, "“Беги, Барнил!” – закричали мы." }, { 11.08, "Ажек, сэр Эрлгедин и я выстрелили поверх головы Барнила в сторону преследующих его ящеров." }, { 17.59, "Кто-то даже убил одного из них." } } } },
    ["de205207"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "Плотоклюй." }, { 0.92, "Отряд: скорпионы." }, { 2.45, "Климат: засушливый." }, { 4.14, "Как следует из названия, этот скорпид отщипывает и пожирает плоть с костей других животных." }, { 11.88, "Он падальщик и предпочитает кормиться крупными тушами." } } } },
    ["de30e7f5"] = { d = 22.0, v = "narrator", c = { x = { { 0.00, "Офгут Каменный Кулак" }, { 1.78, "Бессчётно количество павших от молота Тёмного хранителя Офгута." }, { 6.91, "Солдаты Западного гарнизона склоняются пред ним в благоговении, когда он проходит мимо." }, { 14.05, "Кто среди них может заглянуть в глаза Офгуту и увидеть там секреты, что нашёптывает ему тёмный ключ?" } } } },
    ["de713aa4"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Западная колонна — второй из Двух Колоссов, гигантская столовая гора, между которой и её сестрой проходит дорога из Пустошей в Фералас." }, { 10.94, "У её подножия живёт ночная эльфийка, владеющая искусством переносить желающих на вершину соседней скалы — путешествие, как она честно предупреждает, в один конец." }, { 24.00, "Тень колонны ложится на лес ещё до заката." } } } },
    ["df3c60c0"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Тропа Крылатого Ужаса тянется по восточной части степей — это долина, которую облюбовал чёрный драконий выводок." }, { 9.02, "Здесь кишат детёныши драконов и дракониды, а над тропой кружат чёрные драконы постарше." }, { 15.81, "Среди лавовых потоков порой встречается и огромный магматический великан, бредущий по долине." }, { 23.25, "Тропу считают одним из самых опасных мест в степях: даже бывалые герои не решаются пройти по ней в одиночку." } } } },
    ["df4a06cd"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Посёлок Пивоваров — крохотное поселение на западном берегу Заледеневшего озера, неподалёку от Гномрегана." }, { 8.30, "Здесь живёт семья Ячменоваров, без устали совершенствующих дворфийское искусство пивоварения." }, { 15.65, "Регольд Ячменовар варит «Вечное сияние», способное уложить самого крепкого дворфа, а Марлетта не даёт покоя Громоварам из Караноса." }, { 26.28, "Вокруг посёлка бродят медведи, леопарды и кабаны, и пивоварам вечно не хватает рук, чтобы отгонять зверьё." } } } },
    ["df62719e"] = { d = 45.9, v = "narrator", c = { x = { { 0.00, "Джинта'Алор — огромный город лесных троллей на юго-востоке Внутренних земель, второй по величине после Зул'Амана." }, { 9.10, "Его построили тролли империи Амани и назвали в честь Джинты, древнего вождя, а ныне им владеет племя Порочной Ветви." }, { 18.49, "Террасы и лестницы поднимаются к вершине, где стоит алтарь, и на нём жрецы приносят жертвы кровавому богу Хаккару." }, { 27.59, "Порочная Ветвь охотится на слабых соседей из племени Сломанного Клыка, а однажды сюда затащили даже похищенного у дворфов грифона Остроклюва." }, { 38.83, "В городе полно воинов, ворожей, пауков и слизи, и пройти его в одиночку почти невозможно." } } } },
    ["df6e8b05"] = { d = 11.6, v = "human-male", c = { x = { { 0.00, "РАПОРТ: Кобольды." }, { 1.31, "Рядом с Долиной Североземья наблюдается повышенная активность кобольдов." }, { 6.56, "Все кобольды были оттеснены ордой обезумевших орков клана Чёрной горы." } } } },
    ["df70c255"] = { d = 17.6, v = "narrator", c = { x = { { 0.00, "Новый Авалон — поселение Алого ордена на побережье к востоку от Длани Тира, у самого Зловещего моря." }, { 8.72, "У крестоносцев здесь свои сады, кузница и ратуша; орден живёт тут замкнутым миром, куда чужакам хода нет." } } } },
    ["df75837a"] = { d = 15.1, v = "narrator", c = { x = { { 0.00, "Убив тело Медива, Лотар и юный Кадгар, сами того не зная, изгнали дух Саргераса в бездну." }, { 8.20, "А праведный дух Медива остался жив… и долгие годы скитался по астральному миру." } } } },
    ["df85b356"] = { d = 31.7, v = "narrator", c = { x = { { 0.00, "Застывший оазис лежит на юго-востоке Степей, между Торговым побережьем и Золотым Путём." }, { 7.38, "У его стоячих вод стоит командный шатёр кентавров клана Колкар, где скрывается Верог Дервиш, а по берегам бродят одинокие заблудившиеся кодо." }, { 19.19, "В оазисе клюёт странная искажённая рыба, и друиды проверяют, нет ли и здесь расселины, дающей воде жизнь." }, { 27.77, "Южнее, в гнёздах, стерегут кладки грозные ящеры." } } } },
    ["df891cd8"] = { d = 30.3, v = "human-female", c = { x = { { 0.00, "Люди, верящие в Свет, часто боятся тех, кто интересуется настоящей силой, считая, что тайная магия непознаваема." }, { 8.28, "Но не всё, что приходит извне, является злом." }, { 11.56, "Не все сущности стремятся подчинить себе других." }, { 15.17, "Если у тебя будет достаточно силы, те же самые сущности станут твоими слугами." }, { 21.11, "Об этом я хотела бы поговорить с тобой." }, { 24.05, "Жду тебя на кладбище справа от аббатства." }, { 27.13, "-Друзилла ла Салле, наставница чернокнижников" } } } },
    ["dfbb059d"] = { d = 74.9, v = "narrator", c = { x = { { 0.00, "Элвиннский лес – сердце королевства Штормград, край могучих дубов, тихих озёр и ухоженных ферм." }, { 7.50, "На севере его замыкают горы у подножия Пылающих степей, на востоке лежит Красногорье, на юге за рекой начинается Сумеречный лес, а на западе – Западный Край." }, { 20.11, "В Первую войну орки сожгли этот лес почти дотла, но после Второй войны деревья поднялись вновь, а столицу отстроили руками гильдии каменщиков." }, { 31.64, "Когда знать отказалась платить мастерам, из обиды родилось Братство Справедливости, и теперь его бандиты в красных повязках хозяйничают на фермах и в рудниках." }, { 44.33, "Армия далеко от дома, и порядок держат лишь маршалы Макбрайд в Североземье и Дугхан в Златоземье." }, { 52.11, "Кобольды заняли шахты, мурлоки расселились по озёрам, из Сумеречного леса приходят волки, а на западной границе рыщут гноллы стаи Речной Лапы во главе с грозным Дробителем." }, { 65.95, "И всё же Элвинн остаётся самым мирным уголком людских земель – здесь начинается путь каждого, кто присягнул короне." } } } },
    ["dfcf8b56"] = { d = 25.5, v = "narrator", c = { x = { { 0.00, "Этот окаменевший коготь был найден у южных берегов Тернистой долины." }, { 5.08, "Экологи полагают, что этот коготь принадлежал древнему солнечному руху." }, { 10.36, "Несмотря на то что упоминания об этих существах присутствуют в примитивных мифологических сказаниях тауренов, находка этого когтя предполагает тот факт, что, вероятно, подобное создание действительно существовало." } } } },
    ["e00ee524"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Горечь потери своего дома ожесточила их сердца." }, { 3.70, "Король Бронзобород предложил дворфам Громового Молота место, где они бы могли жить в границах Стальгорна, но они отказались." }, { 13.15, "Кардрос повёл свой народ на север к землям Лордерона." }, { 17.19, "Поселившись в буйно зеленеющих лесах Внутренних земель, клан Громового Молота построил город Заоблачный пик, где дворфы стали ближе к природе и даже приручили могучих грифонов, живших там." } } } },
    ["e02e51f0"] = { d = 36.6, v = "nightelf-male", c = { x = { { 0.00, "Я не устаю удивляться, как легко можно подчинять всех своей воле, играя на их ненависти." }, { 6.85, "С орками и троллями было легче всего, ненависть к Альянсу сделала их прилежными учениками Тёмной Нити." }, { 14.83, "Понимают ли они хоть отчасти, какой могучей силе служат?" }, { 19.30, "Этот паладин, который меня бесит, Делгрен Очиститель, суёт нос в наши дела в Ясеневом лесу, пока его прислужник, Балтул, шпионит за моей башней, думая, что мне о его присутствии неизвестно." }, { 34.13, "Делгрен считает нас незначительной" } } } },
    ["e03593be"] = { d = 28.9, v = "human-male", c = { x = { { 0.00, "Озрик!" }, { 0.49, "Ниже приведён перечень доспехов, которые нам требуются:" }, { 4.26, "Десять кольчужных рубах" }, { 5.93, "Двадцать шлемов" }, { 7.04, "Тридцать накладок на доспехи" }, { 9.02, "Пятнадцать кольчужных ботинок" }, { 11.05, "Мы, как обычно, у тебя в долгу." }, { 13.21, "И если Западный край когда-нибудь избавится от досаждающих ему воров, я сочту себя обязанным пригласить тебя в наш дом на вкусный обед, достойный былой щедрости, что некогда прославляла эти земли." }, { 26.68, "-Льюис" }, { 27.17, "Интендант, Сторожевой Холм." } } } },
    ["e05123c3"] = { d = 70.4, v = "narrator", c = { x = { { 0.00, "Гора Хиджал — священная вершина северного Калимдора между Осквернённым лесом и Зимними Ключами." }, { 8.01, "После Великого Раскола Иллидан вылил в горное озеро воду Источника Вечности, а ночные эльфы вырастили над ним Нордрассил, Древо Жизни, благословлённое Алекстразой, Изерой и Ноздорму." }, { 23.20, "Тысячи лет древо дарило калдорай бессмертие." }, { 26.98, "В конце Третьей войны сюда пришёл Архимонд с Пылающим Легионом и Плетью: ночные эльфы, люди Джайны Праудмур и Орда Тралла держали склоны, пока Малфурион не призвал к Древу огоньков." }, { 43.24, "Их жертва испепелила демона у самых корней, но Нордрассил был опалён, а бессмертие ночных эльфов утрачено." }, { 52.09, "Долгие годы гора оставалась закрытой, и лишь теперь в предгорья снова ведёт путь через Теснину Зловещего Шёпота." }, { 61.46, "Лес медленно исцеляется, но склоны ещё хранят следы битвы, а у подножия Древа лежат кости самого Архимонда." } } } },
    ["e064e792"] = { d = 11.1, v = "creature/ancient", c = { x = { { 0.00, "Арториус Судьбоносный:" }, { 2.28, "Всему, чего касается в Зимних Ключах, он приносит смерть и разрушение." }, { 9.38, "Найди его и убей." } } } },
    ["e06edab6"] = { d = 20.8, v = "tauren-male", c = { x = { { 0.00, "Клык тролля из клана Кровавого Скальпа:" }, { 3.45, "Клыки троллей из клана Кровавого Скальпа из Тернистой долины обладают редким качеством." }, { 11.15, "Всё зло этого клана сконцентрировано в клыках, и если их истолочь в порошок, можно выпустить эту гибельную силу." } } } },
    ["e092405a"] = { d = 15.2, v = "narrator" },
    ["e0ff4643"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Грот Пылающего Клинка скрыт в пыльных горах, замыкающих Долину Испытаний с севера." }, { 6.60, "Из его устья выползают бесы и другие слабые демоны, и покоя в долине больше нет." }, { 13.20, "Поговаривают, что в заброшенных пещерах обосновались чернокнижники культа Пылающего Клинка, а в глубине хозяйничает нечто пострашнее бесов." }, { 24.29, "Для новобранцев поход в этот грот становится последним испытанием перед тем, как долина отпустит их во внешний мир." } } } },
    ["e149d9c3"] = { d = 58.2, v = "narrator", c = { x = { { 0.00, "Силитус — раскалённая пустыня на юго-западной оконечности Калимдора, куда ведёт единственная тропа из северо-западного угла кратера Ун'Горо." }, { 10.65, "Тысячу лет назад здесь гремела Война Зыбучих песков: ночные эльфы Фэндрала Оленьего Шлема и драконы четырёх выводков во главе с Анахроносом остановили полчища киражей и заперли их в Ан'Кираже за Стеной Скарабея." }, { 26.72, "Силитиды, насекомые-слуги киражей, с тех пор расплодились и изрыли пески громадными ульями." }, { 33.65, "За ними следят друиды Круга Кенария из Крепости Кенария, а бронзовые драконы Ноздорму впервые за долгие века вернулись в пустыню." }, { 43.61, "В дальних лагерях сектанты Сумеречного Молота через Ветровые Камни взывают к повелителям стихий из Совета Бездны." }, { 52.33, "А у запертых врат висит Гонг Скарабея, и час, когда в него ударят, уже близок." } } } },
    ["e16847e1"] = { d = 67.6, v = "narrator", c = { x = { { 0.00, "Кратер Ун'Горо — огромная зелёная чаша на юге Калимдора, зажатая между пустынями Танариса и Силитуса." }, { 7.99, "Со всех сторон его окружают отвесные стены, и путник, спустившийся с раскалённых песков, будто попадает в другой мир: здесь парят влажные джунгли, гремят водопады и бродят ящеры, каких не встретишь больше нигде в Азероте." }, { 25.32, "Посреди кратера дымит вулкан, у подножия которого рыщут элементали огня, а на гребнях стен стоят три древних пилона, чьё назначение не разгадал никто." }, { 37.13, "Учёные считают эту землю древней лабораторией титанов: по всему кратеру рассыпаны кристаллы Силы, а в свитках киражи Ун'Горо назван «Землёй Богов», куда их полчища так и не смогли ступить." }, { 51.91, "Единственный приют для смертных — Укрытие Маршалла, пещера в северной стене, где остатки разбитой экспедиции изучают здешние чудеса." }, { 62.31, "На юге гудит улей силитидов, а на Пути Ужаса хозяйничают дьявозавры." } } } },
    ["e17e3e43"] = { d = 4.0, v = "narrator", c = { x = { { 0.00, "Командующий флотами Альянса." }, { 2.66, "Друг Штормграда." } } } },
    ["e17e6b88"] = { d = 26.0, v = "human-male", c = { x = { { 0.00, "Распространение сведений производите на своё усмотрение." }, { 3.66, "Тирисфальское региональное командование" }, { 6.24, "Капитан Мелроуз" }, { 7.31, "Капитан Вакон" }, { 8.27, "Капитан Перрин" }, { 9.29, "Указания даны самим верховным лордом." }, { 11.87, "Капитан Перрин, продолжайте укреплять позицию на юго-западной башне (как уже было сказано)." }, { 18.05, "Провиант подвезут позднее." }, { 19.84, "Материалы можно добывать на близлежащих фермах." }, { 23.02, "Не забывайте о разведке и собирании информации." } } } },
    ["e186c539"] = { d = 42.4, v = "narrator", c = { x = { { 0.00, "Каменор – орочий форпост и единственный город на Болоте Печали." }, { 4.98, "Его заложила Старая Орда в Первую войну, вскоре после открытия Тёмного портала, и это одно из старейших поселений орков на Азероте." }, { 15.35, "При Тралле Каменор отстроили заново: здесь стоят большой зал и две землянки, а вокруг ходят патрули каменорских рубак." }, { 24.53, "Отсюда летают в Гром'гол, Пиратскую Бухту и Каргат; мастер-алхимик Рогвар обучает своему ремеслу, Хелгрум Быстроногий ждёт донесений из Бесплодных земель, а чернокнижник Фел'зерул по поручению вождя изучает тайны затонувшего храма." } } } },
    ["e1d0714d"] = { d = 25.3, v = "human-male", c = { x = { { 0.00, "Капралу Адамору." }, { 1.19, "С первыми лучами солнца соберите максимум десять пехотинцев и доложитесь охотнику за головами Терри Долгопиву." }, { 8.89, "С ним вы пойдёте по следу опасного дезертира – вероятно, вооружённого и агрессивного." }, { 14.59, "Этот охотник за головами был близким союзником покойного лорда-адмирала, и я прошу относиться к нему с почтением, как к старшему офицеру." }, { 24.11, "Лейтенант Бенедикт" } } } },
    ["e1d23964"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Туннель Когтя — извилистый проход под горами, соединяющий Утёс Ветрорезов с Ясеневым лесом у озера Мистраль." }, { 8.92, "В темноте здесь тихо: ни зверя, ни человека, лишь тупики и странные ниши в стенах." }, { 15.69, "Над пещерой ещё можно различить остатки старой дороги, по которой когда-то ходили поверху." } } } },
    ["e21e73bc"] = { d = 35.0, g = 1, v = "orc-male", c = { m = { { 0.00, "Чтобы подчинить коня погибели, нужно сделать три вещи:" }, { 4.57, "Сотворить Круг Великого Призыва." }, { 7.23, "Внутри этого круга открыть портал в Ксорот и вывести коня через него." }, { 13.13, "Победить его и покорить его дух." }, { 15.86, "На следующих страницах подробно описан каждый из трёх шагов." }, { 20.80, "Сделать это непросто, но ты доказал, что способности у тебя есть." }, { 26.11, "Я уверен, что ты со своей целеустремлённостью подчинишь себе коня гибели." }, { 32.02, "Читай дальше." }, { 33.20, "-Мор'зул Вестник Крови" } }, f = { { 0.00, "Чтобы подчинить коня погибели, нужно сделать три вещи:" }, { 4.57, "Сотворить Круг Великого Призыва." }, { 7.23, "Внутри этого круга открыть портал в Ксорот и вывести коня через него." }, { 13.13, "Победить его и покорить его дух." }, { 15.86, "На следующих страницах подробно описан каждый из трёх шагов." }, { 20.81, "Сделать это непросто, но ты доказала, что способности у тебя есть." }, { 26.19, "Я уверен, что ты со своей целеустремлённостью подчинишь себе коня гибели." }, { 32.09, "Читай дальше." }, { 33.28, "-Мор'зул Вестник Крови" } } } },
    ["e2ac508a"] = { d = 62.4, v = "human-male", c = { x = { { 0.00, "Милая Ройбен!" }, { 0.99, "Знаю, скорее всего ты никогда не получишь это письмо, но мне просто нечем больше заняться." }, { 7.28, "Мне надо как-то отвлечься от этих чудовищных звуков, доносящихся из-за крепостных стен, окружающих Дольный Очаг." }, { 14.99, "Нежить окружила нашу деревню и не собирается отступать, а нам поручено защищать жителей и ждать подкрепления." }, { 22.39, "В последнем сражении я сломал ногу и теперь совершенно беспомощен; мне остаётся только сидеть и ждать, когда наша оборона падёт." }, { 31.09, "Вокруг только стоны и смерть… это ужасно." }, { 33.98, "Страх повсюду, даже в воздухе." }, { 36.08, "На нашей стороне сражается принц Артас." }, { 38.80, "Если бы не он, нам бы уже давно пришёл конец." }, { 41.88, "Его преданность и любовь к родине завораживает; я с радостью буду сражаться и погибну рядом с ним." }, { 48.60, "Бой идёт уже у наших ворот, и я не могу больше сидеть тут, жалея сломанную ногу." }, { 54.15, "Нам нужен каждый, кто может держать в руках меч." }, { 57.48, "Надеюсь, эти строки ты будешь читать в лучшие времена." }, { 61.31, "Твой друг," }, { 61.99, "Леагрем" } } } },
    ["e2ef6553"] = { d = 33.8, v = "narrator", c = { x = { { 0.00, "Аку'май, Принцесса Глубин, служит Древним Богам." }, { 4.38, "Она проживает в Непроглядной Пучине, озаряя тамошние подземелья своей древней мудростью." }, { 12.26, "Аку'май, пришедшая в Пучину по воле старейшин смертных, олицетворяет божественность." }, { 19.67, "Она обладает лишь частичкой мощи и ярости Древних Богов, но и такая малость выше нашего разумения." }, { 28.51, "Поэтому ей поклоняются." }, { 30.58, "Поэтому её боятся и любят." }, { 32.96, "--Лоргалис" } } } },
    ["e30ef480"] = { d = 24.1, v = "narrator", c = { x = { { 0.00, "Эти силы хаоса бушевали и бились с колоссами-титанами на груди мира." }, { 5.56, "Несмотря на то что элементали были настолько могущественны, что смертным даже представить невозможно, их объединённых сил было недостаточно, чтобы остановить могучих титанов." }, { 19.10, "Один за другим повелители элементалей пали, а их силы отступили." } } } },
    ["e3229478"] = { d = 19.0, v = "named/13717", c = { x = { { 0.00, "Пророк обладает большим могуществом и общается с духами наших предков." }, { 6.12, "Но он глуп!" }, { 7.04, "Он сам не знает, насколько силён." }, { 9.83, "Он носит Амулет Духов, в котором и содержится большая часть его силы." }, { 15.87, "Я узнал, что Амулет силён, но не полон." } } } },
    ["e330089c"] = { d = 25.7, v = "narrator", c = { x = { { 0.00, "Удовлетворённые упорядочением этого небольшого мира и окончанием трудов, титаны приготовились покинуть Азерот." }, { 8.29, "Однако перед своим уходом они поручили величайшим существам этого мира присматривать за Калимдором, поскольку любое враждебное вмешательство могло поколебать его идеальный баланс." }, { 22.06, "В то время существовало множество родов драконов." } } } },
    ["e3341211"] = { d = 6.1, v = "narrator", c = { x = { { 0.00, "Буквы вспыхивают на записке и исчезают." }, { 3.57, "Уловить их смысл невозможно..." } } } },
    ["e3773229"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "Отвесные скалы — восточный край Внутренних земель, где горы резко обрываются к морскому берегу." }, { 7.60, "Большая река, что пересекает весь край, здесь срывается с обрыва огромным водопадом." }, { 14.19, "Высоту этих скал многие путники недооценивали, и не всякий спуск заканчивался благополучно." }, { 21.36, "На узкой полосе песка внизу греются морские кусачие черепахи, доставляющие немало хлопот рыбакам из деревни Сломанного Клыка, а за прибоем начинается Зловещее море." } } } },
    ["e398b19a"] = { d = 31.2, v = "tauren-female", c = { x = { { 0.00, "Полагаю, что беспорядки, которые устраивают в недрах горы духи при поддержке тауренов-шаманов и друидов, отвлекают добытчиков – ведь таурены считают Торговую компанию в Когтистых горах явной угрозой." }, { 15.19, "Угроза это или нет, мы должны помочь союзникам." }, { 18.91, "Лидон, ты отлично разбираешься в ядах." }, { 21.86, "Можешь ли ты придумать такую отраву, которой мы могли бы заразить гоблинов в Когтистых горах?" }, { 29.01, "С почтением к учёному," }, { 30.66, "П." }, { 30.87, "Зама." } } } },
    ["e3c55f73"] = { d = 21.8, v = "dwarf-female" },
    ["e3d0b82a"] = { d = 25.4, v = "narrator", c = { x = { { 0.00, "Агол'вата — руины лесных троллей в северной части Внутренних земель, некогда храм поздней империи Амани." }, { 8.65, "Ныне древние камни заполонили зелёная слизь и нефритовые слизнюки, и между разрушенными стенами не слышно ничего, кроме их чавканья." }, { 19.45, "Эта тишина обманчива: с востока к руинам подступают земли Порочной Ветви." } } } },
    ["e3d2887c"] = { d = 33.1, v = "narrator", c = { x = { { 0.00, "Адэлас Блэкмур, руководитель всех лагерей для военнопленных, наблюдал за орками из своей крепости Дарнхольд." }, { 8.51, "Один из орков пользовался его особым вниманием: молодой сирота, пойманный почти восемнадцать лет назад." }, { 16.81, "Блэкмур воспитал орчонка как своего раба, назвал его Траллом и обучил тактике, философии и фехтованию." }, { 25.04, "Тралл даже пробовал себя в качестве гладиатора." }, { 28.84, "Блэкмур пытался сделать из юного орка орудие убийства." } } } },
    ["e3d739e2"] = { d = 21.4, v = "narrator", c = { x = { { 0.00, "Восточная башня стоит у дороги между озером Чернолесья и Моровым оврагом, на пути к Северному Долу." }, { 7.83, "Её, как и остальные дозорные башни, разрушила Плеть при вторжении в Лордерон." }, { 13.69, "Теперь Альянс и Орда сражаются за её руины: власть над башней даёт войскам преимущество по всему краю." } } } },
    ["e416e7c3"] = { d = 32.9, v = "narrator", c = { x = { { 0.00, "Сторожевой холм — последний оплот порядка в Западном Крае." }, { 4.40, "Когда Штормград отозвал войска, здешние фермеры сами взялись за оружие и создали Народное ополчение." }, { 12.05, "Лагерь раскинулся у подножия старой сторожевой башни; здесь Гриан Камнегрив и капитан Данувин принимают всех, кто готов помочь против Братства Справедливости и гноллов." }, { 24.64, "Разведчики ополчения следят за передвижениями бандитов, а с холма видна почти вся равнина — до самого Луноречья." } } } },
    ["e41ace51"] = { d = 23.0, v = "human-male", c = { x = { { 0.00, "Добрый день, Шнайдер!" }, { 1.47, "Надеюсь, дела в районе каналов идут хорошо." }, { 4.55, "У нас тут, в торговом квартале, большой наплыв покупателей." }, { 8.54, "Нам нужно побольше вязаной одежды, наши запасы на исходе." }, { 12.53, "Пожалуйста, пришлите мне стандартную партию при первой же возможности." }, { 17.26, "Удачи." }, { 17.76, "Надеюсь, занятия вашего сына Турмана тоже продвигаются неплохо." }, { 22.18, "Харлан Багли" } } } },
    ["e47eb900"] = { d = 26.6, v = "narrator", c = { x = { { 0.00, "Логово Раздробленного Хребта — огромный курган огров к северу от руин Альтерака." }, { 6.52, "В пещере и окрестных лагерях живёт основная сила клана: громилы, крушители и маги-огры, готовые броситься на любого, кто подойдёт к их кострам." }, { 17.96, "Отсюда огры совершают набеги на дороги Хилсбрада, и маршалы Южнобережья давно назначили награду за их головы." } } } },
    ["e4da015e"] = { d = 32.1, v = "bloodelf-male", c = { x = { { 0.00, "*Страницы покрыты древними эльфийскими рунами.*" }, { 3.76, "Эти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня." }, { 15.15, "Да не получат наши враги никогда доступ к этим письменам." }, { 19.66, "Да доживу я до тех пор, когда бледный свет луны вновь осветит Кель'Талас." }, { 25.22, "Да умру я во имя Кель'таса." }, { 27.37, "Да буду убивать я во славу Иллидана." }, { 30.22, "-Мастер Кариэль Винтхалус" } } } },
    ["e4daff75"] = { d = 25.0, v = "narrator", c = { x = { { 0.00, "Когда Саргерас убедился, что его армии в сборе и готовы следовать всем его приказам, он выпустил свои необъятные силы на просторы Великой запредельной тьмы." }, { 13.24, "Он назвал свою растущую армию Пылающим Легионом." }, { 17.43, "До сих пор никто не знает, сколько миров они уничтожили, пройда по вселенной огнём и мечом." } } } },
    ["e4f58939"] = { d = 29.4, v = "narrator", c = { x = { { 0.00, "Дун Альгаз — горный перевал, соединяющий Лок Модан с Болотиной, единственная сухопутная дорога с юга." }, { 7.72, "Прежде здесь стоял пост горных пехотинцев Стальгорна, но орки клана Драконьей Пасти вытеснили дворфов к верхнему туннелю и заняли проход." }, { 18.28, "Теперь путь между дворфийскими землями и Гаванью Менетилов стал опасен, и пехотинцы собирают добровольцев, чтобы орки не отрезали порт от Лок Модана." } } } },
    ["e4f737ac"] = { d = 68.6, v = "narrator", c = { x = { { 0.00, "Дун Морог — заснеженное нагорье в сердце Каз Модана, самые высокие горы Восточных королевств." }, { 7.46, "Попасть сюда можно лишь через перевалы, которые стерегут дворфийские горные пехотинцы." }, { 14.42, "Когда-то этими землями правили ледяные тролли Мерзлогривы, но пришедшие из Ульдамана гномы, а следом и дворфы, построили здесь свои города и оттеснили троллей в холмы." }, { 27.76, "Под самой высокой горой дворфы возвели Стальгорн, а на западе помогли гномам выстроить Гномреган." }, { 35.50, "Недавно Гномреган пал: город захватили трогги, а отчаянная попытка выжечь их радиацией погубила большую часть гномьего народа." }, { 45.54, "Уцелевшие нашли приют в Стальгорне у короля Магни Бронзоборода." }, { 50.57, "Пока армия сражается за Альянс вдали, трогги Каменной Челюсти выползают из-под земли по всему краю, а в холмах вновь поднимают голову Мерзлогривы." }, { 62.33, "Снег здесь лежит круглый год, но над каждым посёлком вьётся дым кузниц и пивоварен." } } } },
    ["e5090961"] = { d = 31.1, v = "narrator", c = { x = { { 0.00, "Орков, отправившихся в путь через Степи Калимдора под предводительством Тралла, преследовали неудачи." }, { 7.98, "Они заключили союз с Кэрном Кровавым Копытом и его могучими тауренами-воинами, но при этом многих орков стала одолевать жажда крови, мучившая их на протяжении многих лет." }, { 21.71, "Гром Адский Крик, лучший лейтенант Тралла, предал Орду и позволил своим самым низменным инстинктам взять верх над собой." } } } },
    ["e50c5e74"] = { d = 32.3, g = 1, v = "nightelf-male", c = { m = { { 0.00, "Сал'ах, друг мой." }, { 1.37, "Я надеюсь, ты получил мой знак." }, { 3.82, "Меня попросили помочь тебе." }, { 6.12, "Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила." }, { 11.30, "Если тебе нужны знания, обращайся ко мне." }, { 14.69, "В наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга." }, { 22.32, "По-другому мы не сможем сохранить Тельдрассил и наше ремесло." }, { 27.22, "Приходи, когда сможешь." }, { 29.16, "-Фрагун Шёпот Тени, наставник разбойников" } }, f = { { 0.00, "Сал'ах, друг мой." }, { 1.33, "Я надеюсь, ты получила мой знак." }, { 3.79, "Меня попросили помочь тебе." }, { 6.04, "Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила." }, { 11.10, "Если тебе нужны знания, обращайся ко мне." }, { 14.40, "В наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга." }, { 21.85, "По-другому мы не сможем сохранить Тельдрассил и наше ремесло." }, { 26.62, "Приходи, когда сможешь." }, { 28.52, "-Фрагун Шёпот Тени, наставник разбойников" } } } },
    ["e510e0d3"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Лагерь Гром'гол — укреплённый форпост Орды на западном побережье долины." }, { 5.65, "Частокол и сторожевые башни защищают его от троллей, наг и Альянса, что приходит из Пиратской бухты и Сумеречного леса." }, { 14.98, "Отсюда караваны с припасами идут в Каменор, в Болото Печали, но огры Мош'Огг устраивают засады, а тролли Кровавого Скальпа крадут провизию." }, { 26.00, "Дирижабли связывают лагерь с Оргриммаром и Подгородом, а тролли Чёрного Копья ищут здесь след Йеннику — пропавшего сына своего вождя." } } } },
    ["e531a70f"] = { d = 35.7, v = "narrator", c = { x = { { 0.00, "Остров Раназьяр — скалистый островок у северо-западного берега Пустошей." }, { 5.81, "На нём стоят руины высокорождённых, некогда бывшие частью того же города, что и Этель-Ретор, а ныне остров облюбовали наги." }, { 15.70, "Капитан Ракмор, спасаясь от нагов, спрятал на этом острове свой сундук: его открывают два ключа, золотой и серебряный, но оба потеряны в бою — один достался нагам, другой утащили в глубину макруры." }, { 31.76, "Сокровище всё ещё ждёт того, кто соберёт оба ключа." } } } },
    ["e57d317b"] = { d = 32.7, v = "narrator", c = { x = { { 0.00, "Бухта Черноводья — укрытая утёсами лагуна на южной оконечности долины, вокруг которой выросла Пиратская бухта." }, { 8.58, "Когда-то Штормград основал здесь небольшой порт, но тролли быстро вытеснили людей, а затем гоблины изгнали троллей и обосновались в бухте сами." }, { 19.68, "Отсюда и пошло имя Разбойников Черноводья — пиратов, воров и наёмников, которые правят городом." }, { 27.08, "В тихой воде лагуны стоят корабли, а по берегам тянутся причалы и склады." } } } },
    ["e5a589ea"] = { d = 16.2, v = "human-male" },
    ["e5a972f3"] = { d = 24.0, v = "narrator", c = { x = { { 0.00, "Драко'дар — опалённые холмы на юго-западе степей, где хозяйничает чёрный драконий выводок." }, { 7.18, "Здесь бродят дракониды и детёныши драконов, а в небе патрулируют их старшие сородичи." }, { 13.93, "Путникам, идущим по южной дороге, лучше не сходить с неё в сторону холмов: чёрный дракон считает каждого чужака своей добычей." } } } },
    ["e5b1312d"] = { d = 28.6, v = "dwarf-male", c = { x = { { 0.00, "Никчёмные глупцы!" }, { 1.34, "Мой план требовал одновременного уничтожения обоих мостов." }, { 5.87, "А вы что сделали, тупые головорезы?" }, { 8.63, "Вы сделали лишь полдела и предупредили весь Альянс о наших намерениях." }, { 14.08, "Глупцы!" }, { 14.71, "Но у вас есть шанс исправить то, что вы натворили." }, { 18.46, "У нас есть запас взрывчатки на нагорье Арати, недалеко от моста." }, { 23.49, "Закончите дело, если вам дороги ваши жалкие жизни!" }, { 27.59, "--Кам Гневливый" } } } },
    ["e5b73065"] = { d = 25.4, v = "dwarf-male", c = { x = { { 0.00, "И тогда случилось чудо." }, { 1.84, "Прямо рядом с нами раздался резкий, ужасающий рёв огромного белого тигра." }, { 7.50, "Несмотря на количество, ящеры развернулись и бросились врассыпную." }, { 12.48, "Мы увидели лишь белый сполох, когда тигр минул нас и помчался за одним из ящеров." }, { 18.62, "Нам не требовалось команды." }, { 20.67, "Все четыре члена нашего отряда знали, что пришло время бежать." } } } },
    ["e5c40bee"] = { d = 30.1, v = "human-male", c = { x = { { 0.00, "Странно, но Моргант отверг своё орочье войско сразу же после их жалкой победы." }, { 5.46, "Чернокнижник возвёл магическую башню на северо-востоке и использовал всю свою силу, чтобы создать небольшую армию гноллов из стаи Темношкуров, которые воплощают его злые замыслы." }, { 17.81, "Орки и люди стали жертвами звероподобных монстров, служащих чернокнижнику." }, { 22.96, "Что до того, почему Моргант предал Гат'Илзогга, вождя Чёрной горы, – об этом остаётся только догадываться." } } } },
    ["e608f12a"] = { d = 26.4, v = "narrator", c = { x = { { 0.00, "Пещера Камнепадов в конце одноимённого ущелья кишит кобольдами." }, { 5.40, "Они лихорадочно копают редкие кристаллы резонита, светящиеся лиловым светом и хранящие след древней магии земли, и защищают их ценой жизни." }, { 17.45, "Мор'рогал из Приюта у Солнечного Камня чует в этой пещере неладное: что-то беспокойное таится под горами." } } } },
    ["e61734b5"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "НОМЕР ЗАКАЗА: сорок пять, ка, три" }, { 3.03, "ПОКУПАТЕЛЬ: Крейвел Угольная Борода" }, { 6.31, "НАКЛАДНАЯ:" }, { 7.30, "Гидромеханизмы (три)" }, { 9.10, "Усилительные болты (пятьдесят)" }, { 11.89, "Тридцатидюймовая медная труба калибра двадцать (двенадцать)" }, { 17.30, "Табак марки Тёмная Ярость (один)" }, { 20.33, "Высококачественная призма (три)" } } } },
    ["e61ad97c"] = { d = 35.2, v = "scourge-female", c = { x = { { 0.00, "Порча и зло, с которыми, как принято считать, сопряжена тайная магия, – ничто по сравнению с тем, что мы уже пережили." }, { 10.95, "Мы больше не жертвы." }, { 12.88, "Мы сами выбираем свою судьбу." }, { 15.75, "Сильвана указала нам путь – она доказала, что у нас есть своя воля и что мы не обязаны подчиняться этому ублюдку Артасу." }, { 26.86, "Найди меня в церкви – я расскажу тебе больше… если захочешь." }, { 32.67, "- Изабелла, наставница магов" } } } },
    ["e62b0c01"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Гряда Ящеров тянется на востоке Болотины, к северо-западу от Врат Драконьей Пасти." }, { 6.73, "Ящеры гнездятся здесь во множестве, а в пещере на гряде матриарх стаи стережёт свой выводок." }, { 14.12, "Земля вокруг усеяна костями добычи, и даже опытные охотники подходят к этому месту с осторожностью." } } } },
    ["e6358a5a"] = { d = 34.6, v = "human-male", c = { x = { { 0.00, "Всё началось с находки этой проклятой косы в шахте, которую называют Погибелью Роланда." }, { 6.32, "Да, тогда всё и началось." }, { 8.13, "Прежде чем это случилось, Братство Справедливости радовалось нашим успехам в Сумеречном лесу." }, { 14.84, "До того, как я нашёл косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья." }, { 22.90, "Но с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил её, Погибель Роланда превратилась в место ужасной смерти!" } } } },
    ["e6456aca"] = { d = 26.5, v = "dwarf-male", c = { x = { { 0.00, "Глава четыре – Восточная и Западная башни Северного Волка" }, { 4.51, "Теперь от победы тебя отделяет только один рубеж – самые преданные и сильные стражи Дрек'Тара, стражи Северного Волка." }, { 13.80, "Их присылают из резервных отрядов, что содержатся в Восточной и Западной Башнях Северного Волка." }, { 21.15, "Уничтожь эти башни – и увидишь, как позорно побегут оставшиеся Стражи." } } } },
    ["e64bdb29"] = { d = 28.5, v = "narrator", c = { x = { { 0.00, "Форт у Южных врат — сторожевая застава посреди южного перевала на границе с Лок Моданом." }, { 6.52, "Горные пехотинцы под началом капитана Ругельфасса давно очистили окрестности от зверья, и здесь спокойнее, чем на северной заставе." }, { 16.20, "Однако полк не может отойти от Врат: в холмах Лок Модана расплодились трогги, и капитан ищет добровольцев для вылазок." }, { 24.93, "Через заставу постоянно идут путники в Телсамар." } } } },
    ["e6685cb2"] = { d = 29.4, v = "human-male", c = { x = { { 0.00, "Они нападали на нас отовсюду, выползая из укромных щелей под ногами и падая на нас откуда-то с потолка." }, { 7.19, "Половина моих товарищей погибла в эти первые минуты паники." }, { 11.47, "Оставшиеся, включая меня, пытались бежать." }, { 14.50, "Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье." }, { 23.89, "Всё, что я знаю, – это то, что я – единственный, кто смог спастись из этого места." } } } },
    ["e671b894"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "Остров Фенриса лежит посреди озера Лордамер, и вместе с Рассветными островами он образует разорванное кольцо суши на воде." }, { 10.05, "Когда Плеть пришла в Лордерон, жители острова бежали или были перебиты, а опустевшую крепость заняли гноллы-гнилошкуры." }, { 19.52, "Ими правит Тул Коготь Ворона, бывший маг Кирин-Тора, предавший своих братьев ради Короля-лича." }, { 27.09, "Отрёкшиеся считают остров главным оплотом Плети в Серебряном бору и готовят на него нападение." } } } },
    ["e677524b"] = { d = 21.0, v = "narrator", c = { x = { { 0.00, "Дворфы Стальгорна многие века жили в спокойствии." }, { 4.02, "Но их стало слишком много, им перестало хватать места в подземных городах." }, { 9.99, "И хотя могучий король Модимус Старая Наковальня правил всеми дворфами мудро и справедливо, три мощные фракции появились в обществе дворфов." } } } },
    ["e68173e1"] = { d = 31.4, v = "narrator", c = { x = { { 0.00, "Малфурион знал, что планы его брата, одержимого жаждой могущества, не сулят ничего хорошего, поэтому он решил раз и навсегда избавиться от Иллидана." }, { 11.75, "Вместе с Кенарием они заключили его в тюрьму под холмами, где Иллидану надлежало оставаться до конца его жизни, обессиленным и закованным в цепи." }, { 23.35, "Малфурион поручил юной стражнице по имени Майев Песнь Теней следить за пленником, чтобы тот не сбежал." } } } },
    ["e6bcead1"] = { d = 28.2, v = "dwarf-male", c = { x = { { 0.00, "День шестой." }, { 0.97, "Медведь ещё не вернулся; должно быть, я задал ему хорошую трёпку!" }, { 5.94, "Но я всё ещё слышу его рычание." }, { 8.35, "Я думаю, он ждёт, когда я умру!" }, { 10.77, "Кто бы ни нашёл эту книгу, я прошу тебя." }, { 13.88, "Убей этого грязного медведя." }, { 16.16, "Убей его и отнеси книгу моему другу Большеногу." }, { 19.95, "Он захочет узнать, что произошло." }, { 22.51, "И возьми мою броню." }, { 24.10, "Она понадобится тебе в бою со старым Паршивым Когтем!" } } } },
    ["e7135b36"] = { d = 66.9, v = "narrator", c = { x = { { 0.00, "Мулгор — зелёная долина, укрытая горами со всех сторон; единственный проход из неё ведёт на восток, в Степи." }, { 8.71, "Это исконная земля тауренов: среди высоких плато и травяных равнин они кочевали долгие века, отбиваясь от кентавров." }, { 18.46, "После Третьей войны Кэрн Кровавое Копыто заключил союз с Траллом, изгнал кентавров с равнин и возвёл на вершинах утёсов Громовой Утёс — столицу своего народа." }, { 31.38, "На юге, на плато Красного Облака, учат молодых охотников, а в сердце долины у озера Каменного Быка стоит деревня Кровавого Копыта." }, { 42.23, "По равнинам бродят кодо, долгоноги, волки прерий и пумы плоскогорья." }, { 47.91, "Но и в этом мирном краю есть тревоги: свинобразы Дыбогривы захватили Ежевичную лощину и священные Красные скалы, гоблины Торговой компании отравили колодцы и роют рудник в восточных горах, а на гребнях гнездятся гарпии Ярости Ветра." } } } },
    ["e7311f89"] = { d = 10.7, v = "narrator", c = { x = { { 0.00, "Конечно, героям удалось разрушить портал и спасти Азерот, но сумели ли они выжить среди предсмертных мук Дренора – остаётся загадкой." } } } },
    ["e741f50c"] = { d = 35.7, v = "narrator", c = { x = { { 0.00, "Стена Седогрива закрывает весь юг Серебряного бора." }, { 4.02, "Король Генн Седогрив возвёл её после Второй войны, когда Гилнеас вышел из Альянса и решил отгородиться от остального Лордерона." }, { 13.97, "С тех пор ворота заперты, а стражи на стене не видно, и никто по эту сторону не знает, что происходит за ней." }, { 22.43, "В её тени ютятся измождённые и больные беженцы, которым Гилнеас так и не открыл ворота, и они становятся лёгкой добычей воргенов, забредающих сюда из крепости Тёмного Клыка." } } } },
    ["e74327b6"] = { d = 21.6, v = "narrator", c = { x = { { 0.00, "Умница луна договорилась с великим оленем, что освободит его в обмен на его любовь." }, { 6.79, "Желание Му'ша исполнилось, и она зачала от Апа'ро ребёнка, который родился тёмной ночью." }, { 13.88, "Он получил имя Ценарион и бродил по звёздной тропе между пробуждающимся миром и небесным царством." } } } },
    ["e74ebca0"] = { d = 28.2, v = "narrator", c = { x = { { 0.00, "Кентавры племени Галак живут в Тысяче Игл, к югу от Мулгора, но их разведчиков видели и на равнинах долины." }, { 8.04, "Когда-то кентавры безжалостно теснили кочующих тауренов, пока Кэрн Кровавое Копыто вместе с Траллом не отвоевал эти равнины." }, { 17.44, "Небольшой лагерь налётчиков в Мулгоре — напоминание о том, что старые враги не забыли дорогу сюда, и таурены не намерены терпеть их у своих границ." } } } },
    ["e7679855"] = { d = 19.4, v = "dwarf-male", c = { x = { { 0.00, "Гералат и его помощники хотят найти здесь источник зла." }, { 4.18, "Он сказал мне, что Агамагган почитается за подлинного бога." }, { 8.57, "А почему эта земля кишит зловредными тварями и колкими шипами – вот это тайна." }, { 14.58, "Я хотел узнать у Гералата больше, но он впал в очередное забытьё..." } } } },
    ["e78138e1"] = { d = 44.9, v = "narrator", c = { x = { { 0.00, "Ульдумом зовётся дальний юго-западный угол Танариса, где среди скал стоят неприступные ворота древнего города титанов." }, { 9.53, "Многие считают Ульдум мифом, но иероглифы на дисках, найденных в Ульдамане, в переводе упоминают именно это место." }, { 18.76, "Врата запечатаны с незапамятных времён, и никто из смертных не входил в них; лишь Каменный Страж, оставленный титаном Норганноном, хранителем знаний, отзывается тому, кто принесёт к постаменту нужные диски." }, { 34.93, "Он говорит, что для входа не хватает Ульдумских пластин, а за воротами спят тайны земных глубин, грозящие великими опасностями." } } } },
    ["e7820dfd"] = { d = 21.1, v = "human-male", c = { x = { { 0.00, "Для немедленного распространения среди всех членов Сумеречного Молота." }, { 4.87, "Ниже описан порядок применения Ветровых Камней для связи с нашими повелителями из Совета Бездны." }, { 11.71, "Всякое неподобающее использование Ветровых Камней будет караться самым жестоким образом." }, { 17.97, "-Хранитель Хавунт из культа Сумеречного Молота" } } } },
    ["e782a01f"] = { d = 10.3, v = "nightelf-female", c = { x = { { 0.00, "*Святилище Мел-Тандрис*" }, { 2.64, "\"Пусть свет Элуны вечно озаряет эту долину и освещает пути леса, как было с незапамятных времён\"." } } } },
    ["e789918e"] = { d = 33.2, v = "narrator", c = { x = { { 0.00, "Грот Гнилобрюхих — большой курган-пещера на юго-западе Бесплодных земель, родовое гнездо огров племени Гнилобрюхов." }, { 8.95, "Здесь живут их вожди и огры-маги, и отсюда племя расходится по четырём лагерям, разбросанным по пустыне." }, { 16.99, "Огры мало заботятся о других народах: они грабят караваны и разоряют одинокие стоянки, но их слишком мало, чтобы всерьёз угрожать дворфам или оркам Каргата." }, { 29.29, "И всё же в темноту грота без нужды не заходит никто." } } } },
    ["e7986438"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Несмотря на невосприимчивость воинов Неруба к чуме, Нер'зулу удалось воскресить пауков-воинов и подчинить их своей воле." }, { 9.38, "Нер'зул отдал дань уважения их силе и храбрости, позаимствовав их необычный архитектурный стиль для строительства своих крепостей и сооружений." } } } },
    ["e7a6e284"] = { d = 37.6, v = "narrator", c = { x = { { 0.00, "Руины Констелласа лежат на западе леса, между Джеденаром и долиной Нефритового Пламени." }, { 6.61, "По остаткам колонн и лунному колодцу видно, что здесь стояло одно из поселений ночных эльфов у подножия Хиджала." }, { 15.03, "Теперь колодец отравлен Скверной, и его стережёт сатир Ксаватрас с разбойниками и тенеловами Нефритового Пламени — он растит порчу по воле Ксаварика, вожака сатиров с севера." }, { 28.04, "За этой водой шлют посланцев и друиды Изумрудного святилища, и Винна Хеззард с заставы Отравленной Крови, хотя цели у них разные." } } } },
    ["e7a9522b"] = { d = 14.4, v = "narrator", c = { x = { { 0.00, "Слышишь ли ты его крик?" }, { 2.38, "Клич боевой за Орду:" }, { 4.49, "Победа или смерть!" }, { 6.42, "Должны мы вовек запомнить," }, { 9.16, "Как отважно презрел он смерть." }, { 12.19, "Мечты его воплотились." } } } },
    ["e7ada840"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "Лагерь Гев'рек — новая стоянка кентавров у восточной границы Мулгора, недалеко от деревни Кровавого Копыта." }, { 8.00, "Небольшой отряд налётчиков из племени Галак проник в долину и разбил здесь лагерь; в нём кипит бурная деятельность, а среди кентавров — Херак Разоритель." }, { 19.27, "Дальноходы, доверенные разведчики верховного вождя, первыми заметили угрозу, и Бейн Кровавое Копыто не намерен допустить, чтобы деревня оказалась в опасности." } } } },
    ["e7c40427"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Хотя Кил'джедену удалось склонить к себе Гул'дана после неудачи с Нер'зулом, он по-прежнему ненавидел шамана и поклялся заставить его принять тот самый пакт." }, { 12.85, "Кил'джеден захватил Нер'зула и начал истязать шамана невыносимой медленной пыткой." }, { 19.61, "Нер'зул молил о смерти, а Кил'джеден всё напоминал ему о пакте." }, { 24.82, "Затем Кил'джеден убил орка, но умертвил при этом лишь его тело." }, { 30.11, "Душу орочьего шамана Кил'джеден удерживал, пока она не нашла свой путь в Круговерть Пустоты." } } } },
    ["e80cca28"] = { d = 16.0, v = "narrator", c = { x = { { 0.00, "Совершенствуя свои навыки под неусыпным надзором повелителей ужаса, Король-лич вскоре сумел дотянуться до небольшого поселения людей на самом краю Драконьего Погоста." }, { 12.82, "На нём Нер'зул и решил испытать свои силы." } } } },
    ["e81c13c3"] = { d = 26.8, v = "narrator", c = { x = { { 0.00, "Когда вы вглядываетесь в Око, перед вами встают картины великой битвы." }, { 6.07, "Похоже, что эта ужасная схватка происходит где-то в Лордероне." }, { 11.39, "Вы с трудом можете разглядеть одинокий силуэт женщины, стоящей среди тысячи трупов, отгоняющей полчища Плети." }, { 20.73, "Полчища эти несметны." }, { 22.63, "Из её рук исходят лучи света, разя нежить сотнями." } } } },
    ["e8304cb3"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Холм Дарроу лежит на севере предгорий, под кручами, ведущими к Альтеракским горам." }, { 6.35, "По его лугам бродят олени и горные львы, а в пещерах на склоне живут йети, чьи косматые шкуры ценят портные Южнобережья." }, { 15.78, "Через холм проходит дорога между Мельницей Таррен и землями Альянса, и здесь нередко сходятся отряды обеих сторон." } } } },
    ["e83e9118"] = { d = 66.2, v = "narrator", c = { x = { { 0.00, "Предгорья Хилсбрада — мягкий зелёный край на юге Лордерона, почти не тронутый чумой: сосны на холмах, тучные пастбища и дороги между деревнями напоминают, каким было королевство до Третьей войны." }, { 16.03, "С севера на юг землю рассекает река, на востоке границу держит стена Торадина, а на юге лежит Великое море с одиноким Островом Очищения." }, { 27.33, "Мирный вид обманчив: именно здесь Альянс и Орда впервые сошлись в бою во Вторую войну, и с тех пор эта земля не знает покоя." }, { 37.59, "Люди Южнобережья хранят верность Альянсу, а Мельницу Таррен на севере заняли Отрёкшиеся, и между двумя городами не утихает вражда." }, { 48.30, "В руинах Дарнхольда засел Синдикат, на брошенных фермах хозяйничают гноллы, берега держат мурлоки и наги, а в пещерах живут йети." }, { 59.01, "Дальше к северу поднимаются Альтеракские горы, где под магическим куполом укрылся Даларан." } } } },
    ["e8497c86"] = { d = 40.7, v = "narrator", c = { x = { { 0.00, "Пляж на Краю Света — самая южная точка Танариса и всего Калимдора, дальний юго-восточный угол материка." }, { 8.32, "Здесь кончается земля: за полосой песка лишь Южные моря, по берегу бродят береговые черепахи, а в прибое ворочаются земляные яростни — морские великаны, которым нет дела до чужаков, пока те держатся поодаль." }, { 24.81, "Отсюда до силитидских ульев Зияющей бездны рукой подать, а на западе, за горами, скрываются врата Ульдума." }, { 33.34, "Место тихое и пустынное, куда редко заходит кто-то, кроме охотников за черепашьими панцирями." } } } },
    ["e8533546"] = { d = 31.2, v = "narrator", c = { x = { { 0.00, "Северная башня стоит у оживлённого участка дороги, ведущей из Терамора в Степи, — это самый дальний из постов, что люди леди Джайны возвели после основания города." }, { 12.50, "Её гарнизон стережёт путь и присматривает за северными топями, где в Синей топи и дальше к востоку прячутся таурены Зловещего Тотема." }, { 22.47, "С тех пор как западная башня досталась дезертирам, эта застава осталась последним надёжным оплотом Терамора на дороге." } } } },
    ["e886bfcb"] = { d = 34.8, v = "narrator", c = { x = { { 0.00, "Янтарная Мельница на юго-востоке леса до Третьей войны была тихим посёлком лесорубов." }, { 6.51, "После войны сюда пришли волшебники Даларана: деревня стоит на спящем узле силовых линий, и Кирин-Тор хочет пробудить его для какой-то большой цели." }, { 17.85, "Повозки из Хилсбрада везут магам сундуки с припасами, а маги, окудники и заступники носят подвески Даларана." }, { 26.06, "Для Отрёкшихся это последний оплот людей в Серебряном бору, и Гробница внимательно следит за каждым шагом волшебников." } } } },
    ["e8a70209"] = { d = 18.1, v = "narrator", c = { x = { { 0.00, "Яростный диссонанс чужих душ, наполнивший разум бывшего шамана, ещё более увеличил его силу." }, { 8.04, "Нер'зул буквально пожирал души умерших." }, { 11.51, "Но вскоре контроль над зомби наскучил Нер'зулу – слишком уж это было просто." } } } },
    ["e8a787f9"] = { d = 17.3, v = "narrator", c = { x = { { 0.00, "Похлёбка Западного Края." }, { 2.02, "Три куска жилистого мяса стервятника, три рыла жутеклыка, три глаза мурлока, три окры." }, { 9.20, "Смешать и довести до кипения." }, { 11.67, "Тушить на медленном огне по крайней мере часа два и подавать на стол." } } } },
    ["e8e6a6b1"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Вновь получив силу и возможность свободно странствовать по миру, Иллидан отправился на поиски своей судьбы; но на этом пути он столкнулся с Кил'джеденом, который сделал Иллидану предложение, от которого тот не мог отказаться." }, { 17.57, "Кил'джеден был разгневан поражением Архимонда у горы Хиджал, но ему предстояли более важные дела, чем отмщение." } } } },
    ["e8f96064"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "Тихий Омут — небольшое озерцо к западу от Брилла." }, { 3.81, "До чумы сюда приходили на пикники, а дети, которым ещё рано было плавать в глубоком Ясноводном, плескались на его мелководье." }, { 13.33, "Теперь пруд лежит серый и забытый: под поверхностью остались лишь скелеты рыб, а по берегам, у старого моста, бродят гниющие мертвецы Плети и псы тьмы." } } } },
    ["e9086bb8"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Кел'Тузад вернулся в Лордерон в новом обличии и через три года, благодаря богатству и уму, собрал вокруг себя тайное братство." }, { 10.04, "Это братство, которое он назвал Культом Проклятых, обещало всем своим служителям абсолютное равенство и вечную жизнь в Азероте в обмен на службу и покорность Нер'зулу." } } } },
    ["e90f83bc"] = { d = 23.1, v = "dwarf-male", c = { x = { { 0.00, "Зелёные холмы Тернистой долины." }, { 2.41, "Наш первый день прошёл, как обычно проходят первые дни." }, { 6.54, "Большую часть времени мы обустраивали лагерь." }, { 9.98, "Мне удалось найти идеальное место у небольшой чистой заводи." }, { 14.66, "Старые, обветшавшие мостки указывали на то, что в этом месте когда-то жили." }, { 20.45, "Кто именно там жил, мы пока не знали." } } } },
    ["e91de543"] = { d = 26.2, v = "human-male", c = { x = { { 0.00, "План приведён в действие." }, { 1.63, "Сделай из этого некогда великого бастиона веры Геройской Стражи наш лагерь, и мы начнём перебрасывать туда подкрепление из Западного Края, как только узнаем от тебя, что лагерь должным образом подготовлен." }, { 15.36, "Жители и солдаты Штормграда давно забыли об этом месте, и мы сможем успешно устраивать оттуда набеги." }, { 22.25, "Братство Справедливости отобьёт Штормград!" }, { 25.03, "Жду твоего ответа." } } } },
    ["e92155ce"] = { d = 15.7, v = "narrator", c = { x = { { 0.00, "План Короля-лича сработал идеально." }, { 2.89, "Многие северные деревни чума поразила почти мгновенно." }, { 7.37, "Как и в Нордсколе, жители, заразившиеся чумой, умирали и восставали из мёртвых верными рабами Короля-лича." } } } },
    ["e92b1aea"] = { d = 34.1, v = "narrator", c = { x = { { 0.00, "Воды горного озера вмиг напитались энергией Источника Вечности, и оно превратилось в новый источник." }, { 7.73, "Иллидан ликовал: он считал, что это станет настоящим даром для будущих поколений, поэтому был несказанно удивлён, когда на него вдруг набросился его брат." }, { 19.46, "Малфурион объяснил Иллидану, что в основе всей магии лежит хаос и что её использование неизбежно приведёт к одержимости и войнам." }, { 29.19, "Иллидан, однако, не спешил отказываться от своей магической силы." } } } },
    ["e93989fb"] = { d = 36.2, v = "narrator", c = { x = { { 0.00, "Палатка Дубильщицы — крошечный лагерь на юго-востоке ущелья, где живёт одинокая кожевница из Штормграда, лучший мастер Альянса по выделке шкур элементалей." }, { 12.06, "Не всякий решится поселиться в таком месте, но здесь, среди лавовых пауков и огненных тварей, ей всегда есть с чем работать." }, { 21.72, "За палаткой начинается длинный извилистый проход в холмы, в конце которого лежит логово громового ящера Маргола Яростня — грозы всех археологов, что когда-либо забредали в Тлеющее ущелье." } } } },
    ["e96c751c"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Укрытие Ортелла — маленькая пещера в скалах юго-восточного Силитуса." }, { 5.41, "Здесь скрывается Ортелл, бывший член Сумеречного Молота, порвавший с культом." }, { 11.39, "Сектанты не прощают предателей и ищут его, но Ортелл сумел пустить их по ложному следу: разведчики культа уверены, что он прячется в пещерах далёкого Западного Края." }, { 24.25, "Отшельник знает шифры и обычаи своих прежних собратьев, и враг Сумеречного Молота для него — друг." } } } },
    ["e9928304"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Дун Альгаз — извилистый горный перевал, ведущий из Лок Модана вниз, к Болотине." }, { 6.02, "Во Вторую войну здесь стоял последний оплот Орды в Каз Модане, а после войны дворфы обустроили в проходе сторожевой пост." }, { 15.35, "Недавно орки клана Драконьей Пасти вышли из укрытий в холмах и захватили перевал, вынудив горных пехотинцев отступить к верхнему тоннелю." }, { 26.00, "Теперь дорога между дворфийскими землями и Гаванью Менетилов стала опасной, и Лок Модану грозит оказаться отрезанным от порта." } } } },
    ["e99b6f18"] = { d = 29.3, g = 1, v = "orc-male", c = { m = { { 0.00, "Тром-ка, воин." }, { 1.23, "Меня не интересуют твои подвиги – это все дела прошлого." }, { 5.87, "Когда ты последний раз убивал человека?" }, { 9.06, "Наверняка давно." }, { 10.44, "Ты теряешь хватку без дела." }, { 12.69, "Мне нужен напарник." }, { 14.28, "А взамен я дам тебе то, что тебе нужно, – полезную тренировку." }, { 19.28, "Когда до тебя дойдёт, что я дело говорю, – приходи." }, { 23.42, "Я буду ждать тебя под навесом прямо возле Логова." }, { 27.48, "-Франг, наставник воинов" } }, f = { { 0.00, "Тром-ка, воин." }, { 1.20, "Меня не интересуют твои подвиги – это все дела прошлого." }, { 5.72, "Когда ты последний раз убивала человека?" }, { 8.89, "Наверняка давно." }, { 10.23, "Ты теряешь хватку без дела." }, { 12.42, "Мне нужна напарница." }, { 14.04, "А взамен я дам тебе то, что тебе нужно, – полезную тренировку." }, { 18.91, "Когда до тебя дойдёт, что я дело говорю, – приходи." }, { 22.93, "Я буду ждать тебя под навесом прямо возле Логова." }, { 26.89, "-Франг, наставник воинов" } } } },
    ["e9b1edc9"] = { d = 34.6, v = "narrator", c = { x = { { 0.00, "Этель-Ретор — руины ночных эльфов на северо-западном берегу Пустошей." }, { 5.30, "Большая часть города ушла под воду; над волнами осталась лишь башня с мостиком к запертым вратам." }, { 12.74, "В затопленных залах и на суше хозяйничают наги, но у башни держится маг Серебряного Рассвета: он изучает запечатанное строение и разыскивает Скипетр Света — реликвию, способную, по легендам, потопить целые города." }, { 28.93, "Он подозревает, что скипетр в руках чернокнижников Крепости Громового Топора." } } } },
    ["ea238ffc"] = { d = 36.6, v = "narrator", c = { x = { { 0.00, "Теснина Ледяного Шёпота — каньон на юге Зимних Ключей, лежащий прямо перед Тесниной Зловещего Шёпота; над пропастью перекинут большой мост, ведущий дальше на юг." }, { 13.39, "По дну ущелья и по гребням над ним разбросаны руины ночных эльфов." }, { 18.89, "Здесь живут великаны ледяного молота — огромные ледяные исполины и их хранители, сильные и яростные." }, { 27.24, "В развалинах древнего храма на юго-восточном гребне обосновался сатир Лоракс, и терпение его лучше не испытывать." } } } },
    ["ea23d740"] = { d = 35.5, g = 1, v = "human-male", c = { m = { { 0.00, "Существует четыре правила магии:" }, { 2.45, "Магия могущественна." }, { 3.97, "Магия развращает." }, { 5.29, "Магия порождает зависимость." }, { 7.40, "Магия притягивает обитателей Круговерти Пустоты к тому, кто её применяет." }, { 12.75, "Эти правила неизменны." }, { 14.47, "Этим правилам ты должен будешь подчинить всю свою жизнь, если захочешь продолжить путь магов…" }, { 21.35, "Если у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства." }, { 30.07, "Я буду ждать тебя на втором этаже." }, { 32.65, "Кельден Бремен, наставник магов" } }, f = { { 0.00, "Существует четыре правила магии:" }, { 2.49, "Магия могущественна." }, { 4.04, "Магия развращает." }, { 5.38, "Магия порождает зависимость." }, { 7.54, "Магия притягивает обитателей Круговерти Пустоты к тому, кто её применяет." }, { 12.99, "Эти правила неизменны." }, { 14.74, "Этим правилам ты должна будешь подчинить всю свою жизнь, если захочешь продолжить путь магов…" }, { 21.74, "Если у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства." }, { 30.62, "Я буду ждать тебя на втором этаже." }, { 33.24, "Кельден Бремен, наставник магов" } } } },
    ["ea5111ba"] = { d = 35.6, v = "narrator", c = { x = { { 0.00, "Дун Гарок — дворфийская крепость в юго-восточных холмах предгорий, недалеко от стены Торадина." }, { 7.27, "У её ворот стоят осадные машины, а гарнизон горных пехотинцев, стрелков и жрецов из Стальгорна помогает людям Хилсбрада оборонять край и Лазуритовый рудник." }, { 19.26, "Отрёкшиеся с Мельницы Таррен ненавидят это присутствие Альянса у своих границ и посылают к крепости своих лазутчиков." }, { 28.27, "Крепость невелика, но дворфы держат её крепко, а с холмов вокруг открывается вид на всё побережье." } } } },
    ["ea665846"] = { d = 28.1, v = "dwarf-male", c = { x = { { 0.00, "Господин Шипучка!" }, { 1.23, "Податель сего письма и я затеваем одно дело, к которому просим присоединиться и вас." }, { 7.01, "Как вам известно, большую часть своего времени я провожу на Мерцающей равнине – упомянутое дело относится к проводимым там гонкам." }, { 15.80, "Если гонки – а особенно ставки на их исход – вас интересуют, читайте, пожалуйста, дальше, ведь ваше знание Тернистой долины наверняка можно будет использовать во благо нашего плана." } } } },
    ["eacb2bbc"] = { d = 16.2, v = "human-male", c = { x = { { 0.00, "Я схожу с ума?" }, { 1.05, "Сегодня я оторвал голову одному из самых доверенных стражников под предлогом того, что я хочу получше рассмотреть его душу." }, { 9.61, "И когда я смотрел, как воздух покидает его дыхательные пути, я вспомнил, что несколько дней не ел!" } } } },
    ["ead163e6"] = { d = 37.4, v = "narrator", c = { x = { { 0.00, "Остров Ужаса — южный из двух больших островов у побережья Фераласа, отделённый от Сардора узким проливом." }, { 8.47, "Его сердце — замкнутая долина, куда можно войти лишь с юго-востока: со всех прочих сторон её запирают неприступные скалы." }, { 18.40, "В долине обитают химероки — древние могучие химеры под началом своего лорда, а на северной оконечности острова, в извилистой пещере, засели наги Гребня Ненависти." }, { 31.61, "Повар Могиль из Прибамбасска, по слухам, знает толк в мясе здешних химер." } } } },
    ["eb0ed19c"] = { d = 37.7, v = "narrator", c = { x = { { 0.00, "Таланаар — крохотный лагерь ночных эльфов на самой восточной границе Фераласа, там, где джунгли обрываются в каньоны Тысячи Игл." }, { 10.29, "Здесь нет ни стен, ни рынка — лишь пара торговцев да гиппогрифы, готовые унести путника к Крепости Оперённой Луны или в Прибамбасск." }, { 20.73, "За порядком в лагере присматривает Хранитель дорог Фалфиндел, друид, к которому стекаются тревожные вести из соседних степей." }, { 30.80, "Для Альянса это последний мирный привал перед дорогой мимо тауренского Лагеря Мохаче." } } } },
    ["eb30c624"] = { d = 29.4, v = "narrator", c = { x = { { 0.00, "Несмотря на постоянные преследования со стороны людей, душа Адского Крика была по-прежнему полна неутолимой жажды боя." }, { 9.19, "Вместе со своим верным кланом Песни Войны он продолжал партизанскую войну против поработителей своего народа." }, { 17.69, "К несчастью, он так и не нашёл способ вернуть пленным оркам их жизненную энергию." }, { 23.77, "Юного Тралла завораживал идеализм Адского Крика и воинские традиции Орды." } } } },
    ["eb370643"] = { d = 28.8, v = "human-female", c = { x = { { 0.00, "Но после нескольких недель отсутствия новостей терпение у меня иссякло." }, { 4.76, "Из Даларана мне сообщили, что кровавый камень к моим коллегам так и не попал." }, { 9.83, "Курьер каким-то образом пропал по дороге, а с ним была утрачена и подвеска кровавого камня!" }, { 15.90, "Это очень печальные новости, так как, хотя у Кегана и его последователей есть ещё образцы кровавого камня, с которыми мы можем экспериментировать, я опасаюсь, что подвеска попадёт в неподходящие руки." } } } },
    ["eb3fc329"] = { d = 20.6, v = "narrator", c = { x = { { 0.00, "Тенистый закоулок — небольшая долина к югу от Приюта в Ночных Лесах и к востоку от деревни Зелёной Лапы." }, { 8.40, "Здесь нет ни руин, ни поселений: только пещера в склоне, в которой живёт медвежье семейство, да густой подлесок." }, { 17.31, "Место тихое, но медведи не любят чужаков." } } } },
    ["eb54a3d3"] = { d = 16.3, v = "narrator", c = { x = { { 0.00, "Кил'джеден поместил душу Нер'зула в ледяную глыбу, принесённую из Круговерти Пустоты, и наделил её ещё большим могуществом." }, { 9.50, "Потеря телесной оболочки и обладание невероятной силой привели к перевоплощению Нер'зула." } } } },
    ["eb7137fc"] = { d = 26.9, v = "narrator", c = { x = { { 0.00, "Маревые равнины лежат на юго-западе, к востоку от Грота Гнилобрюхих и к югу от Каргата." }, { 7.37, "Здесь, где воздух дрожит от жары, охотятся огромные стервятники, старые хищные кошки и койоты, а вдали неспешно ступают осадные големы." }, { 18.83, "Плоская выжженная земля просматривается на многие мили, но найти тень в этих местах почти негде." } } } },
    ["ebb5f0d9"] = { d = 35.0, v = "narrator", c = { x = { { 0.00, "Сокрытое Море — бескрайние воды к северу и западу от Калимдора, из которых поднимается ствол Тельдрассила." }, { 8.44, "Своё имя море получило от тумана, которым ночные эльфы веками скрывали Калимдор от чужих глаз, пока Третья война не сорвала эту завесу." }, { 19.47, "В его глубинах живут исполинские морские черепахи, а с края великого древа в море срывается водопад Родниковой реки." }, { 28.91, "За проливом лежит Аубердин на Тёмных берегах, куда из Рут'терана ходит паром." } } } },
    ["ebb841b4"] = { d = 38.4, v = "narrator", c = { x = { { 0.00, "Усадьба Йоргена – заброшенная ферма на юге Сумеречного леса, к западу от Гниющего сада." }, { 6.81, "Здесь жил Свен, пока тёмные всадники, спустившиеся с перевала Мёртвого Ветра, не перебили всю его семью, когда он был в отлучке." }, { 16.46, "Вернувшись, Свен заметил у амбара незнакомца, который что-то закапывал возле старого пня, и с тех пор ищет ответы из своего лагеря на северо-западе леса." }, { 28.27, "Теперь ферму заняли разбойники Братства Справедливости, и многие из них прячутся в тени, так что подходить сюда стоит с осторожностью." } } } },
    ["ec0a0683"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Пещеры Сухокожих уходят в скалу за деревней троллей на юго-востоке нагорья." }, { 5.88, "В просторном гроте собираются вожди и знахари племени Сухокожих, здесь же хранятся их тотемы и вудуистские снадобья." }, { 14.72, "В этих пещерах тролли обсуждают набеги на Павший Молот и союз с ограми клана Тяжёлого Кулака, и чужаку сюда лучше не заходить без веской причины." } } } },
    ["ec0d1e6b"] = { d = 34.2, v = "human-male", c = { x = { { 0.00, "Или, возможно, я был обречён стать свидетелем тех перемен, что навлёк я на Сумеречный лес." }, { 6.03, "Возможно, мой жребий – наблюдать, как воргены врываются на эту землю, окрашивая её в ещё более тёмный цвет своей злобой." }, { 14.33, "Если это и правда мой жребий, то он выпал мне дважды." }, { 18.10, "Поскольку воргены – не единственная сила, что пыталась ворваться в Сумеречный лес: монстры со стороны Мёртвого Ветра также пытались вторгнуться в него." }, { 28.54, "Это будет в следующей главе моей истории, и я молюсь, чтобы она была последней..." } } } },
    ["ec326120"] = { d = 24.0, v = "narrator", c = { x = { { 0.00, "Две статуи должны были стоять на страже прохода в южные земли, покрытого застывшей лавой из-за близости всесжигающего Рагнароса." }, { 9.77, "Они служили не только грозным предупреждением всем тем, кто решится напасть на дворфийские королевства, но также и напоминанием о цене, которую клан Чёрного Железа заплатил за свои преступления." } } } },
    ["ec3fb343"] = { d = 42.3, v = "narrator", c = { x = { { 0.00, "(Грубый набросок дворфийского лица занимает почти весь листок." }, { 5.01, "Под ним написано несколько строчек.)" }, { 7.88, "Известный нарушитель!" }, { 9.60, "Шпион!" }, { 10.17, "Ещё и посмел допрашивать НАШИХ горожан!" }, { 13.32, "Посетители Тенегорна, путешествующие парами, докладывают о столкновениях с преступником." }, { 20.20, "Свидетели отмечают его странный акцент и то, что он постоянно повторяет фразу: \"Это не те двое, кого мы ищем\"." }, { 29.01, "Если заметите нарушителя, тут же дайте знать любому офицеру Ярости Горна!" }, { 34.88, "Обратите внимание: ещё ни одна большая группа горожан не столкнулась со шпионом." }, { 41.25, "Будьте начеку!" } } } },
    ["ec724160"] = { d = 23.6, v = "human-male", c = { x = { { 0.00, "Группа из братства Справедливости встретится с Вымогателем, после чего он переправит собранное золото." }, { 6.64, "Убедитесь, что этот процесс произойдёт без ошибок и в условиях строжайшей секретности." }, { 12.16, "Вымогатель ответственен за переправку золота, но в конечном счёте каждый член братства Справедливости должен убедиться, что его роль будет выполнена со всем тщанием и осторожностью." } } } },
    ["eca1e012"] = { d = 29.0, v = "human-male", c = { x = { { 0.00, "Ниже представлена схема и расписание перевозки золота братством Справедливости из шахт Элвиннского леса в наш штаб в Западном крае." }, { 9.02, "Расписание:" }, { 9.83, "Воскресенье – в двенадцать тридцать" }, { 12.27, "Среда – в двенадцать тридцать" }, { 14.34, "В указанные дни золото, добытое в шахтах Элвин, будет доставляться на тыквенное поле Бреквеллов." }, { 21.04, "Лицо, отвечающее за весь процесс – \"Вымогатель\" – будет носить на пальце специальное кольцо, которое я дал ему лично." } } } },
    ["eca247e2"] = { d = 74.5, v = "narrator", c = { x = { { 0.00, "Тернистая долина — влажные джунгли на юге Восточных королевств, к югу от Сумеречного леса, с трёх сторон окружённые морем." }, { 10.16, "Тысячелетиями здесь правила империя Гурубаши, и руины её городов до сих пор крошатся под натиском лиан и зноя." }, { 19.26, "В пору голода Гурубаши призвали кровавого лоа Хаккара Свежевателя Душ, но его жажда оказалась ненасытной: племя Зандалар с восставшими троллями низвергло его в Зул'Гурубе, а империя распалась на враждующие племена Кровавого Скальпа и Дробителей Черепов." }, { 40.40, "Люди Штормграда пытались проложить сюда торговые пути, но их порт в бухте Черноводья разорили тролли, и на его месте гоблины выстроили Пиратскую бухту." }, { 53.12, "Ныне Орда держит лагерь Гром'гол, Торговая компания валит лес, дворф Эрнестуэй ведёт большую охоту, а пираты Кровавого Паруса готовят удар по Пиратской бухте." }, { 66.43, "В чаще рыщут тигры, пантеры и ящеры, а колючие лианы, давшие долине имя, оплетают каждую тропу." } } } },
    ["eca5a3ed"] = { d = 38.6, v = "narrator", c = { x = { { 0.00, "Силы защитников были на исходе, когда им на помощь пришли паладины Серебряной Длани." }, { 6.98, "Их предводитель Дейвил Крокфорд сам был родом из Дарроушира." }, { 11.83, "Услышав о нападении, он привёл на помощь своих соратников." }, { 16.53, "Совместными усилиями они остановили слуг Хоргуса." }, { 20.57, "Когда на поле битвы появился сам Хоргус, Дейвил вышел ему навстречу." }, { 26.29, "Их поединок длился очень долго, но Дейвил сумел одержать верх." }, { 31.44, "Однако смертельная рана, полученная им, не позволила ему намного пережить своего врага." } } } },
    ["ecd5912e"] = { d = 22.1, v = "narrator", c = { x = { { 0.00, "Ринг — площадка под открытым небом в сердце Арены Гурубаши." }, { 5.06, "Здесь нет ни флагов, ни союзов: всякий, кто ступит на песок, становится добычей для всех остальных." }, { 13.34, "Именно сюда пираты бросают сундук с добычей, и именно здесь решается, кто достоин звания мастера арены." } } } },
    ["ecd75ba3"] = { d = 33.2, v = "narrator", c = { x = { { 0.00, "Гряда Ярости Ветра тянется вдоль гор на юго-востоке Мулгора, в стороне от дороги." }, { 6.53, "На её гребнях гнездятся гарпии стаи Ярости Ветра — извечные враги тауренов: они бросаются на всякого, кто подойдёт к гнёздам, а по склонам рыщут пумы и волки." }, { 19.08, "Таурены охотятся на гарпий ради ярких перьев, которыми в Громовом Утёсе украшают свадьбы и празднества, а воин Руул Орлиный Коготь посылает сюда молодых, чтобы испытать их силу." } } } },
    ["ece145cc"] = { d = 35.7, v = "narrator", c = { x = { { 0.00, "Панель управления самофланжа можно использовать, чтобы автоматически регулировать поток топлива, газов, жидкостей и связанные с этим механизмы." }, { 10.97, "После завершения исходной регулировки она должна работать без проблем при минимальной поддержке." }, { 17.60, "Краткий список компонентов панели управления (слева направо)." }, { 22.90, "Первое: тумблер включения." }, { 24.97, "Позиция «включено» задействует самофланж." }, { 28.13, "Контрольный механизм не отключится автоматически при переводе рычага в положение «выключено»." }, { 35.15, "Это лишь" } } } },
    ["ecf60bb7"] = { d = 32.1, v = "narrator", c = { x = { { 0.00, "Несмотря на то что Нер'Зул согласился сыграть свою роль, Кил'джеден не был уверен в его преданности." }, { 7.72, "Удерживая дух Короля-лича в заточении, демон мог не беспокоиться о его покорности, но, тем не менее, он предпочёл не оставлять его без присмотра." }, { 18.82, "Для этого Кил'джеден приставил к Нер'Зулу своих лучших демонов-стражников, повелителей ужаса, чтобы те охраняли его и следили за тем, чтобы он выполнил свою жуткую миссию." } } } },
    ["ecf8ee74"] = { d = 29.1, v = "narrator", c = { x = { { 0.00, "Гордая Эгвин, веря, что она сможет противостоять грозному богу, использовала свои силы против аватары Саргераса." }, { 8.91, "С необыкновенной лёгкостью Эгвин одолела лорда демонов и убила его физическую оболочку." }, { 15.72, "Опасаясь, что дух Саргераса выжил, наивная Эгвин сокрыла изуродованные останки в одном из древних дворцов Калимдора, утонувшего в море во время разрушения Источника Вечности." } } } },
    ["ed15a234"] = { d = 41.5, v = "narrator", c = { x = { { 0.00, "Обитель Дор'Данил — курган друидов к югу от заставы Расщеплённого Дерева." }, { 6.32, "Издавна здесь спали ночные эльфы-друиды, погружённые в Изумрудный Сон, но приход Орды оставил курган в глубине вражеских земель." }, { 17.40, "Оркам не было дела до спящих эльфов, зато Отрёкшиеся заинтересовались ими: они принялись отделять спящих от их духов, и друиды сошли с ума." }, { 29.58, "Теперь по тёмным коридорам крадутся убийцы Отрёкшихся, а среди них бродят обезумевшие духи друидов Дор'Данила, и трое из них особенно сильны." } } } },
    ["ed24cac7"] = { d = 37.4, g = 1, v = "human-male", c = { m = { { 0.00, "Приветствую тебя." }, { 1.21, "Думаю, тебя заинтересуют результаты моего расследования." }, { 5.04, "Оказывается, и у Ройбена, и у Леагрема есть родные." }, { 8.43, "Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами." }, { 15.05, "Бывшую жену Ройбена, Джоанну Вайтхолл, ты найдёшь в Квартале Воинов Подгорода; там она проводит большую часть времени." }, { 23.00, "А вот как она воспримет твою новость – это вопрос." }, { 26.46, "Что касается Леагрема – у него есть тётя, которая теперь хозяйка сиротского приюта в Штормграде." }, { 32.89, "Какой бы путь в жизни ты ни выбрал, желаю удачи во всех твоих делах." } }, f = { { 0.00, "Приветствую тебя." }, { 1.21, "Думаю, тебя заинтересуют результаты моего расследования." }, { 5.03, "Оказывается, и у Ройбена, и у Леагрема есть родные." }, { 8.42, "Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами." }, { 15.02, "Бывшую жену Ройбена, Джоанну Вайтхолл, ты найдёшь в Квартале Воинов Подгорода; там она проводит большую часть времени." }, { 22.96, "А вот как она воспримет твою новость – это вопрос." }, { 26.41, "Что касается Леагрема – у него есть тётя, которая теперь хозяйка сиротского приюта в Штормграде." }, { 32.84, "Какой бы путь в жизни ты ни выбрала, желаю удачи во всех твоих делах." } } } },
    ["ed25f842"] = { d = 34.0, v = "narrator", c = { x = { { 0.00, "Лесная опушка – клин леса к юго-западу от Штормграда, зажатый между садом у Зеркального озера и реками, за которыми начинается Западный Край." }, { 11.15, "Здесь, к югу от гарнизона, обосновались гноллы стаи Речной Лапы под началом Дробителя, могучего гнолла, которого стража так и не смогла изловить." }, { 22.58, "Среди деревьев бродят кабаны, а по берегам рек попадаются медные жилы и лечебные травы." }, { 29.54, "На северном краю опушки стоит гарнизон у Западного ручья." } } } },
    ["ed2b761d"] = { d = 39.8, v = "narrator", c = { x = { { 0.00, "Роща Древних укрылась на юго-востоке Тёмных берегов, у подножия гор, там, где шумит Петляющая река." }, { 8.21, "Это священные руины старого храма ночных эльфов, где обитает Ону, Древо Мудрости, — терпеливый и мудрый исполин, к чьему совету прислушиваются даже в Дарнассе." }, { 21.56, "Рядом с ним расположились пара торговцев и друид Керлониан Вечный Сумрак, который очнулся от Изумрудного Сна и никак не может проснуться до конца." }, { 33.65, "Ону тревожат наги на побережье и клан Сумеречного Молота у Меча Властителя." } } } },
    ["ed3b5ddd"] = { d = 32.8, v = "gnome-male", c = { x = { { 0.00, "Изалиен." }, { 0.66, "Жрица Луны ночных эльфов" }, { 2.57, "Изалиен решила распрощаться со своими товарищами и отправиться в Забытый Город, разорённый город ночных эльфов, некогда известный как Эльдре'Талас." }, { 13.27, "В нём сохранилась огромная библиотека, святая святых, которую небольшой группе ночных эльфов удалось спасти от разрушения." }, { 22.25, "Там Изалиен надеялась найти информацию о своём наследии и о частях амулета." }, { 27.73, "Стоит заметить, что она была хорошим другом Фарлина Садовника Дерева." } } } },
    ["ed481adf"] = { d = 28.0, v = "narrator", c = { x = { { 0.00, "Порт Штормграда раскинулся у западных стен столицы, там, где белый камень спускается к водам Великого моря." }, { 8.12, "Сюда приходят корабли с дальних берегов, и отсюда открывается путь ко всем побережьям Азерота." }, { 15.28, "У причалов стоят на страже солдаты, а на верхних ярусах — орудия, охраняющие вход в город с моря." }, { 22.71, "Крики чаек и скрип снастей смешиваются здесь с шумом столицы за стеной." } } } },
    ["ed5e24dd"] = { d = 7.2, v = "narrator", c = { x = { { 0.00, "РЯДОВЫЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.62, "Старшина." }, { 3.69, "Старший сержант." }, { 5.53, "Капрал." }, { 6.41, "Рядовой." } } } },
    ["ed620b05"] = { d = 26.7, v = "narrator", c = { x = { { 0.00, "Лестница Прилива — причудливые каменные террасы на берегу к югу от Кабестана, похожие на исполинские ступени, уходящие в море." }, { 10.63, "Здесь удят рыбу и беседуют с духами воды двое тауренов, и среди них Марен Небесная Провидица." }, { 18.60, "Глядя на прибой, охотники узнают об Иша Авак — огромной твари, что таится в глубинах у побережья." } } } },
    ["ed7643f6"] = { d = 29.8, v = "narrator", c = { x = { { 0.00, "Орки Дренора (мира, из которого они изначально пришли) были благородными и стремились к знаниям." }, { 7.71, "Они были могучими воинами, сильными телом и душой." }, { 11.85, "Именно поэтому их упорно разыскивал Пылающий Легион." }, { 16.07, "Кил'джеден, демон великой мощи из рядов Легиона, возжаждал поработить орочьи кланы и напустить их полчища на те миры, которые ещё только предстояло покорить Пылающему Легиону." } } } },
    ["edf93cb0"] = { d = 48.5, v = "narrator", c = { x = { { 0.00, "Каражан, Башня из слоновой кости, стоит в южной части перевала, у самого края каньона." }, { 7.06, "Здесь жил Медив, последний Хранитель Тирисфаля — величайший чародей своего времени и тот, кто открыл оркам Тёмный портал." }, { 16.64, "Его друг Андуин Лотар вместе с учеником Медива Кадгаром взяли башню штурмом и убили обезумевшего волшебника; с той поры Каражан закрылся от мира, и ни одни его ворота не отворяются." }, { 31.27, "Проклятие башни просачивается наружу и высасывает жизнь из земли вокруг." }, { 37.03, "Говорят, любопытные дворяне из Темнолесья отправлялись сюда разузнать о причинах напасти — и ни один не вернулся." }, { 46.04, "Смотреть на башню лучше издали." } } } },
    ["edfdde07"] = { d = 28.2, v = "dwarf-male", c = { x = { { 0.00, "День четвёртый." }, { 1.03, "Мои запасы подходят к концу." }, { 3.15, "У меня всё ещё очень много еды, но я не планировал столь долго оставаться в лесу, так далеко от моего танка, и взял с собой лишь два кега эля." }, { 13.26, "Я не спал обе прошлые ночи, прислушиваясь к этому проклятому рёву, и практически до дна выпил оба кега!" }, { 20.60, "Завтра мне придётся повернуть назад к Большеногу и нашим паровым танкам." }, { 25.75, "Я не хочу здесь пропасть без выпивки." } } } },
    ["ee00fd4a"] = { d = 27.0, v = "dwarf-male", c = { x = { { 0.00, "Я нашёл способ проникнуть в Чертог Хаз'Мула!" }, { 3.12, "Возьми медальон Вогникив из моего сундука." }, { 6.18, "Победи трогга Ревлоша в зале перед комнатой с картой и забери у него стержень Хыннещихоп." }, { 12.61, "Соедини медальон и стержень – и получишь посох Древнейшей Истории." }, { 17.32, "Используй посох в комнате с картой, чтобы открыть двери, ведущие в чертог Хаз'Мула." }, { 23.30, "Сделай это, и комната будет принадлежать нам!" }, { 26.55, "— Бейлог" } } } },
    ["ee06cb7d"] = { d = 22.2, v = "narrator", c = { x = { { 0.00, "Мёртвая пашня — выжженное поле на юго-востоке края, у моста в Сумеречный лес." }, { 5.98, "Когда Братство Справедливости пришло в Западный Край, стоявшую здесь ферму сожгли вместе с посевами." }, { 13.70, "От хозяйства остались лишь дымящиеся руины, а по обугленной земле по-прежнему кружат механические дозорные полей." } } } },
    ["ee0cb10a"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Правительством Кель'Таласа стал совет Луносвета, хотя династия Солнечных Скитальцев также отчасти сохраняла политическую власть." }, { 9.35, "Включавший в себя семерых величайших эльфийских лордов совет заботился о безопасности эльфов и эльфийских земель." }, { 17.70, "Под защитой барьера высшие эльфы отвергли былые предупреждения калдорай и с преступной беспечностью продолжали использовать магию практически во всех аспектах своей жизни." } } } },
    ["ee1457e9"] = { d = 32.7, v = "narrator", c = { x = { { 0.00, "Ферма Гаррена — большая усадьба на севере Тирисфаля: дом, амбар, пара силосных башен и широкое поле." }, { 8.29, "Когда-то щедрая земля посерела и омертвела от чумы, а Гаррен с семьёй погиб при нашествии Плети." }, { 16.14, "Теперь на ферме хозяйничают гноллы-Гнилошкуры и их вожак Червеглаз, объявленный в розыск в Брилле: Плеть подослала их разграблять братские могилы к юго-востоку отсюда и таскать трупы для армии Короля-лича." } } } },
    ["ee1efad8"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "В ходе своих путешествий Тралл встретил старого вождя Оргрима Молота Рока, который долгие годы жил отшельником." }, { 9.06, "Молот Рока был близким другом отца Тралла." }, { 12.61, "Он решил помочь юному орку освободить пленённые кланы." }, { 17.03, "При поддержке опытных воинов Траллу удалось вернуть Орду к жизни и стать её духовным учителем." } } } },
    ["ee5d9ba9"] = { d = 38.3, v = "human-male", c = { x = { { 0.00, "Дела культа, том девяносто два" }, { 2.34, "С радостным сердцем приветствую я вас, братья и сёстры мои, ибо дела нашего культа идут наилучшим образом." }, { 10.51, "Имя нам – легион, и всякие замыслы наши всё ближе к воплощению." }, { 15.39, "В ряды наши встаёт всё больше новичков." }, { 18.41, "Хвалебная песнь возносится к нашим господам на Тёмных берегах, и склоняются они в радостных грёзах среди Тлеющего ущелья, и обнимают они слугу наших господ, Аку'май, в Непроглядной Пучине." }, { 32.70, "Поистине, братья мои и сёстры, скоро вера наша разнесётся по всему Азероту!" } } } },
    ["ee5e6eae"] = { d = 27.2, v = "dwarf-male", c = { x = { { 0.00, "День третий." }, { 0.96, "О, какое великолепное открытие!" }, { 3.37, "Сегодня я нашёл потрясающую вещь: массивные останки существа, похожего на кабана." }, { 9.48, "Его череп возвышался надо-мной на много ростов." }, { 13.19, "Каждый зуб зверя мог заставить казаться карликом даже... ну, дворфа." }, { 18.42, "Учитывая размер находки, я склонен полагать, что это останки одного из Древних Богов, о которых повествуют предания." } } } },
    ["ee7ac797"] = { d = 27.7, v = "narrator", c = { x = { { 0.00, "Эльфы обнаружили, что хотя люди были неловки в обращении с магией, у них была потрясающая природная связь с ней." }, { 8.65, "Эльфы обучили сотню людей самым азам своих магических тайн: не больше, чем было нужно для битвы с троллями." }, { 17.16, "Убеждённые в том, что их ученики-люди готовы вступить в бой, эльфы покинули Стром и пошли на север вместе с могучей армией короля Торадина." } } } },
    ["ee855320"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Река Фалфаррен пересекает Ясеневый лес с северо-востока на юго-запад и служит рубежом между землями ночных эльфов у Астранаара и владениями орков у заставы Расщеплённого Дерева." }, { 13.98, "Она рождается на склонах Хиджала, водопадами спускается в озеро у Ксавиана и уходит под горы у северных Степей." }, { 22.77, "Река невелика, но дожди быстро наполняют её, а на отмелях у Холма Демонического Огня прячутся болотные твари." }, { 31.43, "Главный мост через Фалфаррен на большой дороге — самое оживлённое место в лесу." } } } },
    ["eeced428"] = { d = 29.8, v = "named/13717", c = { x = { { 0.00, "В амулете не хватает пяти камней." }, { 2.66, "Если их найти и вставить на место, сила амулета возрастёт многократно." }, { 8.13, "Я узнал, где находятся пять камней, но для того чтобы их собрать, мне понадобится один из твоих навыков." }, { 16.18, "Разумеется, убийство Безымянного Пророка – тягчайший грех, как и воровство с его бездыханного тела, но о том, о чём я тебя сейчас попрошу, всякому кентавру запрещено даже думать." } } } },
    ["eed9deac"] = { d = 14.2, v = "narrator", c = { x = { { 0.00, "Имя его принесло Свет во тьму Азерота." }, { 3.38, "Доблесть его победила всякое отчаяние." }, { 6.85, "Серебряная Длань не могла сделать большего," }, { 10.62, "Чем дать миру рыцаря, что отдал миру себя." } } } },
    ["eee2e8c4"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Остров Жанейро — островок у входа в Пиратскую бухту." }, { 4.02, "На нём возвышается исполинская статуя гоблина с распростёртыми руками — маяк, встречающий корабли." }, { 11.31, "Остров избрал своим жилищем морской великан, у которого хранится кушак с монограммой потопленного им капитана Смоттса." } } } },
    ["ef0a6278"] = { d = 23.4, v = "narrator", c = { x = { { 0.00, "Пантеон, обеспокоенный склонностью Древних Богов ко злу, начал войну против элементалей и их тёмных повелителей." }, { 9.45, "Армии Древних Богов вели в бой наиболее могущественные элементали: Рагнарос Повелитель Огня, Теразан Матерь Камня, Ал'Акир Владыка Ветра и Нептулон Охотник Прилива." } } } },
    ["ef34c049"] = { d = 34.0, v = "dwarf-male", c = { x = { { 0.00, "Не представляют для нас реальной угрозы до тех пор, пока мы не нарушаем их границ." }, { 5.72, "Возможно, народу дворфов неприятна сложившаяся ситуация, но, учитывая дефицит военных сил, будет благоразумнее перенести решение этой проблемы на более поздний срок и бросить все усилия на борьбу с троггами и дворфами Чёрного Железа." }, { 22.25, "В письме вы также найдёте отчёт моего брата Грелина о Старой Наковальне и данные о вендиго, полученные от одного из наших горных пехотинцев." }, { 32.22, "Подписано:" }, { 32.99, "Сенир Белобород" } } } },
    ["ef3eb330"] = { d = 32.9, v = "bloodelf-female", c = { x = { { 0.00, "*Капитан следопытов Аллерия Ветрокрылая Знаменитая охотница на троллей из Кель'Таласа.*" }, { 6.77, "*Главная разведчица при экспедиции Альянса, которая отправилась на Дренор, родной мир орков.*" }, { 14.05, "*Предположительно погибла.*" }, { 16.00, "Сестра, твоё сердце было решительно и неукротимо, как стрела, летящая по ветру." }, { 22.17, "Ты была самой яркой из нашего ордена." }, { 25.18, "Ты была самой любимой из нашего рода." }, { 28.19, "- Сильвана Ветрокрылая, предводительница следопытов Кель'Таласа" } } } },
    ["ef4edd8f"] = { d = 30.9, v = "narrator", c = { x = { { 0.00, "К югу от Каргата среди песков лежат исполинские кости дракона, которые называют Скелетом Апокрифана." }, { 8.43, "Никто не помнит, как и когда погиб этот зверь: его рёбра давно выбелены солнцем и ветром." }, { 15.89, "Над костями кружат громадные стервятники, слетающиеся сюда со всей западной пустыни, а в тени рёбер рыщут хищные кошки." }, { 25.73, "Место это мрачное, и путники стараются миновать его засветло." } } } },
    ["ef5b3537"] = { d = 40.4, v = "narrator", c = { x = { { 0.00, "Хозяйский погреб — подземелья под руинами маленькой деревни к югу от Каражана." }, { 6.33, "Похоже, здесь жила прислуга башни, и кто-то перебил всех её обитателей: кто именно — Медив или силы, которые он призвал, — по сей день неизвестно." }, { 18.06, "Из двух уцелевших домов открытые входы ведут вниз: один — в обширный винный погреб, другой — в такой же, где пол провалился и открыл ходы в глубокие пещеры." }, { 30.65, "И там, и там во тьме толпятся неупокоенные: бывшие жильцы, сторожа, воющие тени, — и их присутствие уходит далеко под землю." } } } },
    ["ef8cef0a"] = { d = 16.9, v = "narrator", c = { x = { { 0.00, "Плато Дерзкого Ветра — одна из столовых гор Мулгора, каких немало в этой долине." }, { 6.71, "Ветер здесь не стихает, пригибая траву к красноватой земле, а внизу расстилаются равнины, где пасутся кодо и бродят долгоноги." } } } },
    ["ef904111"] = { d = 30.0, v = "human-male", c = { x = { { 0.00, "Воргена можно узнать по его сходству с волками из нашего мира." }, { 4.61, "Глядя на воргена, каждый с лёгкостью заметит, как сильно его грубая шерсть, заострённые уши и длинная морда похожи на волчьи." }, { 13.58, "Но сразу же станут заметны и отличия: грубая шерсть покрывает мощное тело с двумя ногами, из пасти торчат длинные клыки, а когти – словно кинжалы." }, { 24.23, "В завываниях же его слышится такая злоба, которой нет ни у одного здешнего зверя." } } } },
    ["ef9f8f35"] = { d = 34.8, v = "narrator", c = { x = { { 0.00, "Река Строптивая — самая большая река Калимдора и восточная граница Ясеневого леса." }, { 6.73, "Она рождается в озере на горе Хиджал, водопадами обрушивается вниз и широким быстрым потоком отделяет лес от разорённых земель Азшары, а дальше на юг — Степи от Дуротара." }, { 20.26, "Близ Ясеневого леса реку пересекает лишь один мост, ведущий в Азшару; ниже по течению, у Оргриммара, стоят мосты Орды." }, { 29.81, "Оттуда к орочьим лагерям на востоке леса приходят подкрепления." } } } },
    ["efa24d27"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "Найденное в знойной пустыне Танарис, это необычное яйцо остаётся загадкой для современных экологов." }, { 7.57, "Работы по определению его возраста позволяют предположить, что этому яйцу около тысячи лет." }, { 14.59, "Несмотря на то что определённые элементы указывают на его принадлежность насекомовидному существу, его настоящее происхождение невозможно понять." }, { 25.47, "Особей, откладывающих столь характерные яйца, всё ещё предстоит обнаружить." } } } },
    ["efa51510"] = { d = 29.4, v = "narrator", c = { x = { { 0.00, "На юго-востоке Фераласа земля вспучилась и разверзлась: из-под холмов Древолапов выползли силитиды улья Зукк'аш." }, { 9.37, "Гудящая Бездна — их гнездо, прорытое в склонах и наполненное неумолчным стрёкотом." }, { 16.06, "Именно эти твари, а не Орда, гонят гноллов на север, доводя их до исступления." }, { 22.60, "В Лагере Мохаче лишь начинают понимать, что за древняя угроза пробудилась под лесом." } } } },
    ["efbb4889"] = { d = 36.4, v = "narrator", c = { x = { { 0.00, "Пик Тёмного Облака — три столовые горы к востоку от Великого Подъёмника, соединённые верёвочными мостами; на их вершинах стоит селение племени Зловещего Тотема, и оба подступа к нему хорошо охраняются." }, { 15.95, "Здесь правит Арнак Зловещий Тотем, за чью голову назначена награда: его сородичи похищают тауренов с Заставы Вольного Ветра, а вожди племени ведут тайную переписку с некой тёмной силой." }, { 31.02, "Что задумал Зловещий Тотем, на заставе хотели бы знать больше всего." } } } },
    ["efbd5641"] = { d = 33.2, v = "narrator", c = { x = { { 0.00, "Забытые пруды — самый молодой из оазисов Степей, лежащий к северо-западу от Перекрёстка." }, { 7.06, "Ещё недавно здесь была голая земля, а теперь у воды шумят пальмы и толпятся звери на водопое." }, { 14.62, "Друиды Громового Утёса чувствуют, что из глубин к поверхности рвётся какая-то сила, и Тонга Рунический Тотем ищет её источник на дне прудов." }, { 25.72, "У кромки оазиса разбили лагерь кентавры клана Колкар, так что мирной эта красота лишь кажется." } } } },
    ["efeb0576"] = { d = 31.0, v = "narrator", c = { x = { { 0.00, "Бешеный Воробей: Декларация груза и пассажиров." }, { 4.11, "Двадцать бочонков рома." }, { 6.21, "Пункт назначения: Терамор." }, { 8.46, "Пятьдесят мешков муки." }, { 10.48, "Пункт назначения: Терамор." }, { 12.73, "Два ящика с гномскими инструментами." }, { 15.83, "Пункт назначения: Кабестан." }, { 18.16, "Тридцать рулонов хлопчатой ткани." }, { 21.11, "Пункт назначения: Терамор." }, { 23.36, "Четыре ящика пряностей." }, { 25.45, "Пункт назначения: Терамор." }, { 27.71, "Три пассажира." }, { 28.95, "Пункт назначения: Терамор." } } } },
    ["f01699bf"] = { d = 39.9, v = "narrator", c = { x = { { 0.00, "Фермерша Калаба" }, { 1.40, "Крупный долг." }, { 2.57, "Выплата долга сельскохозяйственной продукцией обещана в урожай." }, { 8.03, "Гражданин Уилкс" }, { 9.43, "Все задолженности выплачены." }, { 11.85, "Гражданин Боноан" }, { 13.33, "Все задолженности выплачены." }, { 15.75, "Шахтёр Веллти" }, { 16.92, "Крупный долг." }, { 18.09, "Выплата долга состоится после поставки руды из Лазурного рудника." }, { 23.86, "Шахтёр Сидней" }, { 25.03, "Крупный долг." }, { 26.20, "Выплата долга состоится после поставки руды из Лазурного рудника." }, { 31.97, "Шахтёр Хакетт" }, { 33.14, "Крупный долг." }, { 34.31, "Выплата долга состоится после поставки руды из Лазурного рудника." } } } },
    ["f0235d49"] = { d = 20.2, v = "narrator", c = { x = { { 0.00, "Это письменное доказательство подтверждает тот факт, что податель сего убил Маргола Яростня – бич Выжженной теснины." }, { 9.32, "Музей Стальгорна ценит этот экспонат и благодарит дарителя за столь щедрое подношение." }, { 16.31, "-Главный смотритель музея, Ториус Каменный Сторож" } } } },
    ["f0531549"] = { d = 24.3, v = "narrator", c = { x = { { 0.00, "Застава Чести — западная окраина Степей, где дорога от Перекрёстка поднимается к перевалу в Когтистые горы." }, { 8.44, "Здесь равнина кончается: сухая трава сменяется каменистыми склонами, и лишь редкие караваны пылят по дороге." }, { 17.03, "Мимо проходят все, кто держит путь из сердца Орды на запад — к Пику Каменного Когтя и дальше." } } } },
    ["f099770a"] = { d = 36.8, v = "human-male", c = { x = { { 0.00, "...Джайлс, мальчик, показался мне непослушным, с его обучением, возможно, будут проблемы." }, { 6.18, "А вот девочка постарше, Тиллоа, – исключительно сообразительный ребёнок." }, { 11.10, "Я также обратил внимание на её пленительную красоту." }, { 14.75, "Она уже превращается из подростка в женщину." }, { 17.90, "Господин, кажется, в будущем году собирается выдать её замуж..." }, { 22.38, "Но я что-то отвлёкся." }, { 23.83, "На этой неделе я отправлюсь со всем семейством в летний домик рядом с Лесопилкой Восточной Долины в Элвиннском лесе, это совсем недалеко от Красногорья." }, { 34.55, "Рассчитываю там продолжить работу." } } } },
    ["f0b67bf1"] = { d = 21.9, v = "narrator", c = { x = { { 0.00, "Именно тогда Кил'джеден обнаружил покрытый густыми зарослями мир Дренора, который мирно парил по бескрайним просторам Великой запредельной тьмы." }, { 11.66, "Дренор, родина поклонявшихся духам орков и миролюбивых дренеев, был миром настолько же безмятежным и тихим, насколько бескрайним." } } } },
    ["f0da963a"] = { d = 31.5, v = "narrator", c = { x = { { 0.00, "Но втайне от Альянса, большая группа орков продолжала странствовать по пустошам Каз Модана." }, { 6.89, "Клан Драконьей Пасти, возглавляемый коварным чернокнижником Некроссом, с помощью могущественного артефакта под названием \"Душа Демона\" подчинил себе королеву драконов Алекстразу и её подданных." }, { 21.36, "Удерживая королеву в заложниках, Некросс собрал тайную армию в заброшенной цитадели Громового Молота, которую многие считали проклятой." } } } },
    ["f0e106c7"] = { d = 35.3, v = "narrator", c = { x = { { 0.00, "Река Строптивая — самая большая река Калимдора." }, { 3.98, "Она берёт начало в озере на горе Хиджал, срывается вниз каскадом водопадов, разделяет Ясеневый лес и Азшару, а затем становится границей между Степями и Дуротаром и впадает в Великое море." }, { 19.37, "Через её быстрые воды переброшен мост у Дальней заставы — по нему проходят все караваны из Оргриммара." }, { 27.70, "Шаманы Орды почитают реку: по преданию, вдоль её берегов лежит тайная тропа к святилищу огня." } } } },
    ["f10e442f"] = { d = 31.0, v = "dwarf-male", c = { x = { { 0.00, "Раскопки Бейл Модана" }, { 1.49, "Первая исследовательская команда, отправленная Лигой Исследователей, не ошиблась в своих выводах." }, { 8.43, "Здешняя земля содержит артефакты неограниченной ценности для нашего народа." }, { 13.87, "Без сомнения, под песком и скалами Бейл Модана мы найдём много новых знаний." }, { 19.32, "Геология этого региона, однако, заставляет нас прибегать к крайним мерам." }, { 24.64, "Многие из залежей песка затвердели под воздействием суровой погоды и переменчивого климата." } } } },
    ["f119d992"] = { d = 29.2, v = "narrator", c = { x = { { 0.00, "Виноградники Североземья раскинулись к востоку от аббатства и когда-то были гордостью всего Штормграда." }, { 7.78, "Милли Осворт по-прежнему собирает здесь урожай, но лозы захватили бандиты Братства Справедливости под началом Гаррика Тихокрада." }, { 17.47, "Именно здесь новобранцы короны впервые сталкиваются с людьми в красных повязках." }, { 23.55, "Заместитель судьи Виллем в аббатстве назначил награду за головы разбойников." } } } },
    ["f16ee066"] = { d = 29.0, v = "dwarf-male", c = { x = { { 0.00, "Мы без остановки мчались назад, к нашему лагерю." }, { 3.59, "Позже той ночью мы тихо сидели у костра, зная, что наши жизни были спасены по странной прихоти судьбы." }, { 11.30, "Этому риску подвергается любой участник большой охоты." }, { 15.42, "Мы – игрушки в руках судьбы." }, { 17.55, "Когда-нибудь каждый из нас встретится с хищным оскалом смерти." }, { 22.07, "И ваш покорный слуга рад, что эта встреча не произошла на зелёных холмах Тернистой долины." }, { 28.65, "Конец." } } } },
    ["f17a8c86"] = { d = 27.2, v = "narrator", c = { x = { { 0.00, "Застава Талрендис — маленький лагерь ночных эльфов на границе Азшары и Ясеневого леса, у самого моста через реку." }, { 8.84, "Здесь стоит лишь горстка часовых, и путникам застава ничего не предлагает, кроме крыши от дождя." }, { 16.23, "Зато отсюда рукой подать до восточной дороги в Ясеневый лес, и те, кто идёт в Азшару за призраками высокорождённых и сатирами, начинают путь отсюда." } } } },
    ["f18e6a79"] = { d = 24.2, v = "narrator", c = { x = { { 0.00, "Из двух рас Кил'джеден выбрал воинственных орков: их было легче привлечь под знамёна Легиона." }, { 7.23, "Он околдовал главного шамана орков Нер'зула точно так же, как много лет назад Саргерас подчинил своей воле королеву Азшару." }, { 17.01, "Коварный шаман стал исполнителем воли демона, пробуждая в орках жестокость и жажду сражения." } } } },
    ["f1a4a1d3"] = { d = 27.0, v = "narrator", c = { x = { { 0.00, "Хотя Артас сокрушил всех, кого теперь считал своими врагами, его не переставал преследовать дух Кел'Тузада." }, { 8.26, "Призрак сказал, что Артас должен помочь вернуть его к жизни, чтобы продолжить выполнение плана Короля-лича." }, { 16.66, "Для этого Артас должен был принести останки Кел'Тузада к волшебному Солнечному Колодцу, сокрытому в королевстве высших эльфов Кель'Таласе." } } } },
    ["f1a8d2ed"] = { d = 24.5, v = "narrator", c = { x = { { 0.00, "Рудник Янго на северо-западе края когда-то поставлял в Штормград руду и золото." }, { 6.07, "Теперь шахта заброшена, и в её штольнях хозяйничает Братство Справедливости: грабители обирают всё, что осталось от старых выработок." }, { 15.92, "Разведчики ополчения замечали здесь и звероловов Братства, а по дороге к Прииску на Золотом Берегу ходят их вестники." } } } },
    ["f1abcfae"] = { d = 36.1, v = "human-male", c = { x = { { 0.00, "Привет тебе, Элло Чернодрев, мэр Темнолесья." }, { 3.38, "Боюсь, у меня плохие вести для вашего города." }, { 6.89, "Видишь ли, я создатель." }, { 8.65, "Я обманом заставил того, кто доставил это письмо, помочь мне в создании моего последнего, самого ужасного творения – демона из плоти, костей и металла!" }, { 20.07, "Когда ты читаешь эти строки, он находится рядом с моим скромным жилищем, скрежеща зубами." }, { 26.90, "Одно моё слово – и он начнёт убивать и крушить всё на своём пути." }, { 31.70, "И в скором времени вы испытаете это на себе." }, { 35.08, "-Бальзамировщик" } } } },
    ["f1d326d6"] = { d = 25.5, v = "narrator", c = { x = { { 0.00, "Мёртвое поле — заброшенная ферма на севере Серебряного бора, к северу от Гробницы." }, { 6.35, "Чьё это было хозяйство, уже никто не помнит; теперь здесь устроили лагерь гноллы-гнилошкуры, слуги Плети." }, { 14.65, "Отрёкшиеся посылали против них небольшие отряды, но каждый раз гноллам приходила на помощь банши Плеть Ночи, и её крик обращал воинов в бегство." } } } },
    ["f1d8d6c8"] = { d = 32.1, v = "narrator", c = { x = { { 0.00, "На северо-восточном берегу озера Каменного Быка чадят обгорелые повозки Торговой компании." }, { 7.04, "Караван под охраной вёз припасы для гоблинского рудника, но таурены-разведчики, уже потерявшие двоих в прошлой стычке, напали без промедления и сожгли его." }, { 18.91, "Ящики с рудой и минералами бросили, решив, что огонь уничтожит всё ценное, однако вскоре у тлеющих остатков появились мародёры Торговой компании, ревниво стерегущие свой груз." } } } },
    ["f1daca97"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "На юге горы, между Укрытием Малорна и Осквернёнными предгорьями, в земле зияет Сквернокровный Шрам — рана, оставленная Пылающим Легионом." }, { 11.70, "Здесь Скверна выжгла лес до камня, и в расселинах до сих пор светятся зелёные лужи демонической магии." }, { 20.31, "Такая сила манит чернокнижников, и они стекаются к Шраму, чтобы черпать из него." }, { 27.36, "Для друидов это самая больная язва Хиджала: пока она не затянется, гора не исцелится." } } } },
    ["f1db33aa"] = { d = 11.2, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.82, "Часть первая." }, { 4.23, "Главнокомандующий." }, { 6.11, "Фельдмаршал." }, { 7.43, "Маршал." }, { 8.27, "Командир." }, { 9.31, "Лейтенант-командор." } } } },
    ["f1e2dddf"] = { d = 19.2, v = "narrator", c = { x = { { 0.00, "Берег Северного прилива — северо-западное побережье Серебряного бора, полоса песка и узкая кромка Великого моря." }, { 8.71, "Самая приметная вещь здесь — полузатонувший корабль, лежащий у самой воды." }, { 14.34, "Иных следов человека на этом пустынном берегу почти не осталось." } } } },
    ["f1ee957d"] = { d = 24.2, v = "human-male", c = { x = { { 0.00, "Сейчас я прошу Его Величество помочь в эти трудные времена добрым гражданам Озёр." }, { 5.71, "Нам нужны люди для защиты нашей земли и боевые орудия взамен разрушенных на поле боя." }, { 11.73, "Запасы еды и питья истощились." }, { 13.90, "Умоляю, государь, окажите нам поддержку в защите последнего бастиона на пути ненавистных орков!" }, { 20.47, "Враг должен быть изгнан за пределы королевства Штормград!" } } } },
    ["f234e011"] = { d = 13.6, v = "human-female", c = { x = { { 0.00, "Товар у меня." }, { 1.03, "Я буду прятаться в верховьях реки, неподалёку от Хрустального озера, возле стены." }, { 6.81, "Если отправите за добром кого-то из своих агентов, пусть убедится, что его никто не видел!" }, { 13.29, "Катти" } } } },
    ["f23e9811"] = { d = 34.0, v = "narrator", c = { x = { { 0.00, "Кабестан — гоблинский порт на Торговом побережье, единственное место в Степях, где орку и человеку нальют за одной стойкой." }, { 9.16, "Город основал Газлоу: Тралл щедро заплатил ему за помощь в строительстве Оргриммара, и на эти деньги гоблин отстроил гавань, а теперь достраивает обсерваторию." }, { 21.08, "Отсюда ходит корабль в Пиратскую бухту, а торговлей заведует управляющий пристанью Головокружилкинс." }, { 28.56, "Лишь пираты Южных морей да пушки Северной Стражи портят гоблинам прибыль." } } } },
    ["f241b3f8"] = { d = 37.1, v = "narrator", c = { x = { { 0.00, "Озеро Лок — самое большое озеро Каз Модана и одно из крупнейших в известном мире." }, { 6.39, "Своими размерами оно обязано Каменной Плотине, удерживающей талые воды гор." }, { 12.35, "На островах посреди озера гнездятся кроколиски, а в глубинах ходят трешадоны и стаи прожорливых рыб." }, { 20.14, "На дне и на отмелях до сих пор лежат обломки катапульт и баллист, оставшиеся со Второй войны, когда орки Орды сражались здесь с дворфами." }, { 30.74, "Недавно над озером видели гномский летательный аппарат, пропавший вместе с пилотом." } } } },
    ["f244154d"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Медвежий угол лежит у юго-восточного края гор Азшары." }, { 4.41, "На утёсе здесь поднимается башня, в которой затворился верховный маг Ксилем со своими учениками; к нему приходят маги и разбойники, ищущие наставления." }, { 16.41, "Своё имя это место получило по деревушкам фурболгов Древобрюхов, что стоят здесь как передовые посты их крепости и Урсолана." } } } },
    ["f2442373"] = { d = 23.0, v = "narrator", c = { x = { { 0.00, "Потом чума начала заполонять страну и заражать её ничего не подозревающих обитателей." }, { 6.68, "Под присмотром Кел'Тузада войско Короля-лича быстро росло, и вскоре тот подчинил себе обширные земли." }, { 14.69, "Это войско стало известным под именем Плеть, и единственной его целью было истребление всех жителей Азерота." } } } },
    ["f249a291"] = { d = 30.2, v = "narrator", c = { x = { { 0.00, "Надел Моргана — ветхая часовня с погостом, притаившаяся за Каражаном." }, { 5.78, "Покосившиеся надгробия и старый склеп говорят о том, что когда-то у стен башни жили люди и хоронили здесь своих близких." }, { 15.68, "Но покой этому месту не дан: мёртвые не лежат в могилах, и в часовне и на склоне холма бродят призрачные обитатели." }, { 25.21, "Кто такой Морган, чьё имя носит надел, история не сохранила." } } } },
    ["f24df2a6"] = { d = 34.4, v = "narrator", c = { x = { { 0.00, "Таурены" }, { 0.62, "Таурены с их шаманистическим отношением к зиме и интересом к делам друидов, буквально подтверждают собой легенду о Зимнем Покрове." }, { 10.49, "Они, однако же, видят в ней прежде всего путь обновления знаний, а поклонение собственно легенде оставляют тем народам, что, по их мнению, не так глубоко познали природу вещей." }, { 23.79, "Многие таурены считают, что именно во время этого праздника им приличествует благодарить судьбу за благословение их нового обиталища, Мулгора." } } } },
    ["f24edb34"] = { d = 21.1, v = "narrator", c = { x = { { 0.00, "У подножия северных гор Азшары укрыта фурболгская крепость, названная по племени Черночревов." }, { 7.72, "Вход в неё вырублен в виде медвежьей головы, а вокруг тянутся грубые ограды и тотемы." }, { 14.83, "Фурболги здесь не жалуют чужаков, и путнику лучше не задерживаться у их ворот." } } } },
    ["f26688b1"] = { d = 32.0, v = "narrator", c = { x = { { 0.00, "Дун Мандарр — небольшая стоянка у ледяной пещеры на юго-востоке Зимних Ключей." }, { 6.16, "Лагерь разбил дворф Джерон, и дворфийское имя выдаёт, кто дал название этому месту; но стоило ему найти амулет с синими перьями, как совухи пришли в ярость, разгромили лагерь и прогнали его прочь." }, { 21.43, "Теперь среди разбросанных пожитков и брошенного фургона хозяйничают разъярённые совухи, а сам дворф зарёкся соваться сюда без крайней нужды." } } } },
    ["f267ac64"] = { d = 35.0, v = "nightelf-male", c = { x = { { 0.00, "Он рассказал мне, что исходил Дор'Данил вдоль и поперёк, но ни разу не видел такого сундука или другого места, где могло бы храниться навершие." }, { 10.69, "Он также рассказал мне, что в тех краях завелась гниющая слизь, которая пожирает почти всё, что ей попадётся." }, { 18.72, "Он видел, как она \"поедает\" столы, скульптуры, медведей, и даже гномов!" }, { 24.16, "Эта слизь, похоже, обретает силу, поглощая магические предметы." }, { 28.99, "Если сундук, в котором лежало навершие, был зачарован, слизь могла сожрать и его." } } } },
    ["f276fe80"] = { d = 33.1, v = "narrator", c = { x = { { 0.00, "Озеро Лордамер — огромное пресное озеро в сердце Лордерона, у восточной границы Серебряного бора." }, { 8.24, "В былые времена оно кормило рыбой и поило водой королевства людей, а на его южном берегу стоял Даларан." }, { 17.13, "Давным-давно древняя чума погубила в озере всякую жизнь, и аптекари Отрёкшихся до сих пор изучают её тайну." }, { 25.93, "Посреди воды лежит остров Фенриса с разорённой крепостью, а южнее — Рассветные острова." } } } },
    ["f2873a23"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "За десять тысяч лет до того, как орки и люди сошлись в Первой войне, мир Азерота вмещал лишь один массивный континент, окружённый бескрайними бушующими морями." }, { 13.00, "На этом континенте, известном как Калимдор, жило множество самых разных народов и существ, борющихся за выживание на просторах нового мира." }, { 24.44, "В центре тёмного континента находилось таинственное озеро, бурлившее энергией." } } } },
    ["f28d8b41"] = { d = 34.6, v = "human-female", c = { x = { { 0.00, "Но почему я вспомнила об этом?" }, { 2.19, "Я это сделала для того, чтобы вы поверили тому, что я собираюсь написать, словам, что произнесли губы Кегана, и надеюсь, мои коллеги, читая этот дневник, поймут, почему я поверила тому, что он сказал:" }, { 16.64, "\"То, что осталось от Древних Богов, всё ещё влачит жалкое существование в глубоких расщелинах этого мира." }, { 24.13, "Новые силы ищут способ обуздать эти древние силы, и тот, кто сумеет это сделать, получит в своё распоряжение ужасное орудие против своих врагов\"." } } } },
    ["f2ad3f58"] = { d = 39.5, v = "narrator", c = { x = { { 0.00, "С благословенными." }, { 1.59, "Сражались не все из высокорождённых." }, { 4.62, "Многие стояли в оцепенении, словно охваченные безумием." }, { 9.56, "Большие и маленькие города, как один, падали вокруг них." }, { 14.58, "В Амет'Аране всё было в руинах, его жители цеплялись за землю, словно это могло их спасти от уничтожения." }, { 23.98, "Именно тогда Атрикус Нарассин, любимец Азшары, появился, чтобы спасти их." }, { 30.60, "Он сказал, что может защитить их заклинаниями." }, { 34.66, "Пока вокруг них погибали братья и сёстры, отцы и матери," } } } },
    ["f2ceb207"] = { d = 23.5, v = "narrator", c = { x = { { 0.00, "В поисках друидов, которых ещё не удалось пробудить, Малфурион наткнулся на древнюю тюрьму, в которой он заточил своего брата Иллидана." }, { 10.41, "Тиранда освободила его в надежде, что он присоединится к ним в битве с Легионом." }, { 16.52, "Некоторое время Иллидан помогал им, но затем бежал, решив, что личные цели для него важнее." } } } },
    ["f2d22fd4"] = { d = 37.1, g = 1, v = "human-male", c = { m = { { 0.00, "Приветствую тебя." }, { 1.20, "Думаю, тебя заинтересуют результаты моего расследования." }, { 4.96, "Оказывается, и у Ройбена, и у Леагрема есть родные." }, { 8.31, "Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами." }, { 14.82, "Бывшую жену Ройбена, Джоанну Вайтхолл, ты найдёшь в Квартале Воинов Подгорода; там она проводит большую часть времени." }, { 22.65, "А вот как она воспримет твою новость – это вопрос." }, { 26.06, "Что касается Леагрема – у него есть тётя, которая теперь хозяйка сиротского приюта в Штормграде." }, { 32.40, "Какой бы путь в жизни ты ни выбрал, желаю удачи во всех твоих делах." } }, f = { { 0.00, "Приветствую тебя." }, { 1.20, "Думаю, тебя заинтересуют результаты моего расследования." }, { 5.00, "Оказывается, и у Ройбена, и у Леагрема есть родные." }, { 8.37, "Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами." }, { 14.93, "Бывшую жену Ройбена, Джоанну Вайтхолл, ты найдёшь в Квартале Воинов Подгорода; там она проводит большую часть времени." }, { 22.81, "А вот как она воспримет твою новость – это вопрос." }, { 26.24, "Что касается Леагрема – у него есть тётя, которая теперь хозяйка сиротского приюта в Штормграде." }, { 32.63, "Какой бы путь в жизни ты ни выбрала, желаю удачи во всех твоих делах." } } } },
    ["f2defe29"] = { d = 47.4, v = "narrator", c = { x = { { 0.00, "Южнобережье — портовый город на южном берегу предгорий, один из последних оплотов людей в Лордероне, верных Альянсу." }, { 8.96, "Когда-то это была рыбацкая деревня, но во Вторую войну сюда причалили корабли беженцев из Штормграда, и посёлок вырос в оживлённую гавань." }, { 19.51, "Ныне здесь живут уцелевшие в Третьей войне, среди них бывшие рыцари Серебряной Длани и маги Кирин-Тора." }, { 27.51, "Мировой судья Малеб видит в Синдикате угрозу самому существованию города, маршал Редпат ищет смельчаков против огров Альтерака, а хранитель мудрости Диббс собирает уцелевшие книги для библиотеки Штормграда." }, { 43.37, "С севера городу угрожают Отрёкшиеся с Мельницы Таррен." } } } },
    ["f2e267aa"] = { d = 26.7, v = "human-female", c = { x = { { 0.00, "Но чтобы ответить на эти вопросы, понадобятся ещё тесты и исследования подвески, и я боюсь, что Лордамерские выселки не смогут снабдить меня ни помощниками, ни оборудованием для выполнения этой задачи." }, { 13.23, "Поэтому я отправила подвеску Кровавого камня вместе с посыльным в Даларан с особыми инструкциями о том, как исследовать его, чтобы они могли избежать тех разочарований, что постигли меня с самого начала." } } } },
    ["f2f8453c"] = { d = 7.1, v = "narrator", c = { x = { { 0.00, "Самые большие из птиц-долгоногов, геру, весьма немногочисленны и редко встречаются." } } } },
    ["f3324ba2"] = { d = 15.7, v = "narrator", c = { x = { { 0.00, "Даже его жрецы из племени Атал'ай, были изгнаны из столицы Зул'Гуруба в северные топи." }, { 7.32, "Там, посреди болот, они воздвигли огромный Храм Атал'Хаккара и продолжили дело своего павшего хозяина…" } } } },
    ["f33f924f"] = { d = 45.8, v = "gnome-male", c = { x = { { 0.00, "Лорд Вальтхалак." }, { 1.18, "Благородный драконид и бывший генерал Пика Чёрной горы" }, { 5.18, "Лорд Вальтхалак, невероятно могущественный волшебник-драконид, жил ещё до генерала Драккисата." }, { 11.87, "Пик часто переходил из рук в руки, но, к сожалению, в этот раз нам суждено было сыграть свою роль в смене власти." }, { 20.07, "Один гоблин-контрабандист из Пиратской бухты, Гремник Риззлшмыг, дал нам задание украсть книгу заклинаний Вальтхалака." }, { 28.67, "Мы не знаем, хотел ли он её продать или изучить сам (или и то, и другое), да теперь это и неважно." }, { 35.82, "Важно то, что мы проникли на верхние уровни Пика Чёрной горы и убили Вальтхалака прямо в его логове." }, { 43.16, "Тогда-то и началось настоящее веселье." } } } },
    ["f340d0c0"] = { d = 41.1, v = "narrator", c = { x = { { 0.00, "Родниковое поле названо так за водонапорные башни, которые качают живительную влагу из глубоких подземных запасов." }, { 8.69, "Их построили гоблины Прибамбасска, чтобы напоить свои предприятия в пустыне, но затея сорвалась: в поле явились бродячие разбойники, называющие себя Скитальцами Пустыни, и присвоили башни себе." }, { 23.40, "Бандиты, воры и тёмные маги шайки сидят на чужой земле, а их вожак Калиф Жало Скорпида бродит здесь с двумя телохранителями." }, { 32.91, "Водная компания Прибамбасска платит за каждый отбитый у кочевников бурдюк с водой и за голову самого Калифа." } } } },
    ["f36f91f5"] = { d = 31.7, v = "narrator", c = { x = { { 0.00, "Забытый берег тянется вдоль всего западного края Фераласа, там, где джунгли выходят к Сокрытому Морю." }, { 7.89, "По песку бродят водяные элементали и морские великаны, а в прибрежных скалах гнездятся ветрокрылы." }, { 15.50, "У воды стоит рыбацкая деревенька мурлоков, живущих в вечном страхе перед птицами и набегами." }, { 22.76, "С пристани на берегу отходит лодка к острову Сардор и Крепости Оперённой Луны — для Альянса это главная дорога в лес." } } } },
    ["f3bcc2fc"] = { d = 33.3, v = "narrator", c = { x = { { 0.00, "Туралион и Кадгар решили героически принести себя в жертву, разрушив Тёмный портал со стороны Дренора." }, { 8.20, "Их жизни и жизни их воинов – немалая цена за разрушение портала, но они понимали, что это единственный шанс спасти Азерот." }, { 17.97, "Адский Крик и Мёртвый Глаз успели пройти через Тёмный портал навстречу своей свободе, и через мгновение он взорвался за их спинами." }, { 28.33, "Для них и остальных орков на Азероте пути назад больше не было." } } } },
    ["f4010e73"] = { d = 17.4, v = "narrator", c = { x = { { 0.00, "Лотар решил последовать своим инстинктам и, заручившись поддержкой ученика Медива – Кадгара, – пошёл на штурм крепости волшебника – Каражана." }, { 10.82, "Кадгару и Лотару удалось победить Стражника, которого они считали причиной всей войны." } } } },
    ["f414990e"] = { d = 23.5, v = "narrator", c = { x = { { 0.00, "Но один великий дух ускользнул от них." }, { 3.01, "Это был Апа'ро, которого ночные эльфы называли Малорном, гордый белоснежный олень." }, { 9.68, "Его рога упирались в небеса, а его сильные копыта оставляли глубокие следы по всей земле." }, { 16.93, "Шу'хало долго охотились за Апа'ро, но в конце концов сумели окружить гордого оленя." } } } },
    ["f4328b29"] = { d = 21.7, v = "narrator", c = { x = { { 0.00, "Прошло около тысячи лет после \"Войны Зыбучих песков\"." }, { 4.71, "Именно на этой войне в сердце пустыни Силитуса случилось великое горе и великое бремя пало на Фэндрала Олений Шлем." }, { 14.74, "Считается, что именно описанные здесь события отвратили от добра верховного Друида." } } } },
    ["f45ff07f"] = { d = 28.3, v = "narrator", c = { x = { { 0.00, "Западное побережье тянется от Южнобережья на запад, к подножию холмов Лазуритового рудника." }, { 7.24, "Весь берег усеян маленькими стоянками мурлоков: они ставят хижины у самой воды, сушат сети и с визгом кидаются на всякого, кто подойдёт слишком близко." }, { 19.36, "У этих же берегов водятся морские черепахи, чьё мясо шеф-повар Джессен из Южнобережья кладёт в свой знаменитый суп." } } } },
    ["f49b9676"] = { d = 27.4, v = "narrator", c = { x = { { 0.00, "Высокорождённые довольно бездумно обращались с магией, в результате чего из источника Вечности начали расходиться волны, проникающие даже в самые дальние уголки Великой запредельной тьмы и привлекающие внимание тамошних обитателей." }, { 18.39, "Вскоре и Саргерас – Великий враг всего живого и Разрушитель миров – почуял эти волны и устремился к их источнику." } } } },
    ["f4ae9cb9"] = { d = 15.4, v = "narrator", c = { x = { { 0.00, "С помощью кланов Бушующего Шторма и Сумеречного Молота Гул'дану удалось поднять Гробницу Саргераса с морского дна." }, { 9.34, "Но когда он открыл древний склеп, его встретили полчища обезумевших демонов." } } } },
    ["f4d6a55b"] = { d = 40.8, v = "narrator", c = { x = { { 0.00, "Крепость Марденхольд — сердце Дольного Очага, и отсюда некогда правил всем краем Тирион Фордринг, лорд Марденхольдский." }, { 9.35, "Горожане гордились, что её стены не пали даже в самые чёрные дни орочьего нашествия." }, { 15.94, "Тирион был обвинён в измене за помощь орку, отлучён от ордена Серебряной Длани и изгнан." }, { 22.81, "После падения Лордерона именно здесь собирались уцелевшие паладины, и здесь родился Алый орден." }, { 30.32, "Теперь крепостью владеет верховный лорд Таэлан Фордринг, сын Тириона, и Марденхольд стал главной твердыней крестоносцев в Чумных землях." } } } },
    ["f4dd8ae9"] = { d = 35.9, v = "narrator", c = { x = { { 0.00, "Совиная чаща — цепь пещер на юге Зимних Ключей, где во множестве гнездятся обезумевшие и разъярённые совухи." }, { 8.37, "У входа в чащу стоит лагерь ночной эльфийки Раншаллы, изучающей древние надписи: она полагает, что на вершине гряды скрыт алтарь Элуны, а пять факелов в пещерах отпирают путь к нему." }, { 22.64, "Раншалла хочет узнать, почему совухи так ревностно стерегут это место, и ключ к разгадке, по её мнению, кроется в заклинаниях, переписанных ею с камней в руинах Кел'Терила." } } } },
    ["f4e57bb6"] = { d = 24.4, v = "human-male", c = { x = { { 0.00, "Однако благородные мужи Штормграда влезли в огромные долги, расширяя военное присутствие королевства в Элвиннском лесу и Тернистой долине." }, { 9.67, "Огромные долги опустошили казну, и ван Клиф со своими товарищами не получили обещанных денег." }, { 16.13, "Потратив несколько лет на возведение великого города, Каменщики остались ни с чем, забытые продажными чиновниками столицы." } } } },
    ["f4eac962"] = { d = 37.9, v = "narrator", c = { x = { { 0.00, "Безмятежное кладбище лежит чуть юго-восточнее Темнолесья, сразу за городской оградой." }, { 6.76, "Название давно стало насмешкой: среди могил поднялись скелеты-воины и маги-скелеты, хотя они и слабее той нежити, что бродит у Вороньего холма, поэтому именно сюда Ночной дозор посылает новых помощников." }, { 23.13, "В разрушенной часовне или возле неё бродит Невменяемый Вурдалак." }, { 28.25, "Неподалёку стоит старая ферма, где обитает несчастное привидение по имени Слепая Мэри, оплакивающее свою утраченную красоту." } } } },
    ["f4eee36e"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "На побережье к югу от Аубердина дворфы из Лиги исследователей ведут раскопки, названные в честь их начальника — геолога Сомнамбулера, знаменитого в Стальгорне своими открытиями и не менее знаменитого своей рассеянностью." }, { 16.48, "Под слоем песка обнаружились следы некогда крупного поселения." }, { 21.26, "Но стоило копнуть глубже, как из-под земли выскочили древние големы и заполонили весь раскоп." }, { 28.37, "Говорят, геолог нашёл здесь удивительную окаменелость, наделённую таинственными свойствами, — и тут же забыл, куда её положил." } } } },
    ["f4f00623"] = { d = 26.2, v = "narrator", c = { x = { { 0.00, "Но несмотря на все катаклизмы, остатки империй Амани и Гурубаши по-прежнему существуют в современных Кель'Таласе и Тернистой долине." }, { 10.31, "Колонии акири Азжол-Неруб и Ан'Кираж в Нордсколе и Танарисе также пережили катастрофу." }, { 17.14, "Ужаснувшись гибелью большей части привычного им мира, тролли понемногу начали восстанавливать своё былое могущество." } } } },
    ["f52edf9c"] = { d = 14.6, v = "narrator", c = { x = { { 0.00, "Леди Мара Фордрагон." }, { 1.74, "Высший клирик Штормграда." }, { 3.84, "Покровительница беженцев, наводнивших Лордерон после Первой войны." }, { 9.21, "Она была светлой матерью нашего будущего." }, { 12.69, "Да упокоится она в Свете." } } } },
    ["f57a7078"] = { d = 21.4, v = "orc-male", c = { x = { { 0.00, "Нужно заметить, что Чёрному магниту, используемому для восстановления Колокола, Колеса и Свечи в случае их поломки, нужны Осколки душ." }, { 10.27, "При каждом восстановлении ритуального предмета с помощью Магнита расходуется один Осколок души, поэтому перед ритуалом стоит запасти их побольше." } } } },
    ["f59553d2"] = { d = 26.1, v = "narrator", c = { x = { { 0.00, "После долгих месяцев приготовлений Культ Проклятых под предводительством Кел'Тузада нанёс первый удар, выпустив чуму на земли Лордерона." }, { 10.63, "Утер и его паладины обследовали заражённые территории в надежде найти способ остановить чуму; но, несмотря на все их старания, болезнь продолжала распространяться, угрожая полностью уничтожить Альянс." } } } },
    ["f5c7514d"] = { d = 39.4, v = "narrator", c = { x = { { 0.00, "До Великого Раскола Эльдарат был цветущим городом и твердыней высокорождённых." }, { 6.02, "В Войну Древних здесь бились с Пылающим Легионом, а потом море поглотило большую часть города, и лишь обломки на утёсах напоминают о былом величии." }, { 17.49, "Ночные эльфы давно сторонятся этих мест: руины заняли наги Злобного Прибоя, а среди колонн стоят таблички, на которых маги высокорождённых записывали свои прозрения о тайной магии." }, { 31.80, "Говорят, здесь спрятаны могущественные реликвии — не случайно за руинами приглядывают синие драконы." } } } },
    ["f5d191d3"] = { d = 28.2, v = "dwarf-male", c = { x = { { 0.00, "В тот день мы пошли на юг, двигаясь по свежим следам пантеры." }, { 4.24, "Вскоре мы пришли к ущелью, через которое был перекинут длинный верёвочный мостик." }, { 9.92, "При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн." }, { 16.31, "Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо." } } } },
    ["f6147b6b"] = { d = 22.4, v = "narrator", c = { x = { { 0.00, "Штаб-квартира Торговой компании — буровая платформа, возведённая гоблинами посреди озера Назферити." }, { 7.47, "Здесь трудятся механики и геологи, а бригадир руководит вырубкой леса и добычей кристаллов." }, { 14.39, "Крошилки компании оснащены новыми регуляторами топлива, чертежи которых очень интересуют барона Ревилгаза." } } } },
    ["f6229f30"] = { d = 10.9, v = "narrator", c = { x = { { 0.00, "ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА." }, { 2.74, "Часть первая." }, { 4.11, "Главнокомандующий." }, { 5.94, "Фельдмаршал." }, { 7.22, "Маршал." }, { 8.04, "Командор." }, { 9.04, "Лейтенант-командор." } } } },
    ["f6485080"] = { d = 46.3, v = "narrator", c = { x = { { 0.00, "Сокрытое Море — огромный океан, омывающий Калимдор с запада и севера." }, { 5.78, "Своё имя оно получило от тумана, которым ночные эльфы окутали континент, чтобы скрыть его от чужаков до самой Третьей войны." }, { 16.16, "В его водах растёт мировое древо Тельдрассил, а из Аубердина через него ходят корабли в Гавань Менетилов." }, { 24.90, "Море холодное и штормовое, и лишь умелые мореходы проводят суда сквозь дожди и туманы; те, кому не повезло, остались лежать на отмелях у берега." }, { 36.76, "В глубинах живут гигантские черепахи и кракены, а после Раскола под воду ушли город Зорам и храм Непроглядной Пучины." } } } },
    ["f657a7a4"] = { d = 24.3, v = "narrator", c = { x = { { 0.00, "Кил'джеден знал, что уже справился со своей задачей, но хотел быть уверенным в преданности орков." }, { 7.96, "Он дал Совету Теней тайный приказ призвать Маннорота Уничтожителя, живое воплощение ярости и разрушения." }, { 16.59, "Гул'дан собрал вождей кланов и убедил их, что, испив крови Маннорота, они станут непобедимыми." } } } },
    ["f65f7334"] = { d = 32.8, v = "goblin-male", c = { x = { { 0.00, "Сбалансированная шпага Сталлера." }, { 2.39, "И последнее: я хочу вернуть одну из моих лучших кузнечных работ." }, { 7.24, "Эта шпага – невероятное оружие, и я подарил его тому, кого я считал весьма благородным и великим воином." }, { 15.08, "В общем, его побил мурлок по имени... как его там, Джаркай?" }, { 19.53, "Как-то так." }, { 20.39, "Он подвергся атаке этого чудища во время своего путешествия по берегу Болота Печали." }, { 26.70, "Он проиграл сражение и, видимо, обратился в бегство, оставив оружие в лапах мурлока." } } } },
    ["f6675b63"] = { d = 16.6, v = "narrator", c = { x = { { 0.00, "Возвышенность Соферы — холм над северо-восточными предгорьями Хилсбрада." }, { 5.24, "На его вершине стоит лагерь Синдиката: отсюда разбойники следят за дорогой на мельницу Таррен и в Странбрад." }, { 13.26, "Пастухи и путники обходят это место стороной." } } } },
    ["f688cbb4"] = { d = 9.2, v = "narrator", c = { x = { { 0.00, "…и там ты найдёшь легендарный меч Командира Алых – Пеплоносец." }, { 4.90, "Разве не замечательно добыть такое на обычной рыбалке?" } } } },
    ["f68b0602"] = { d = 33.4, v = "narrator", c = { x = { { 0.00, "Поля Великанов занимают южную часть Степей между Лагерем Таурахо и границей Пылевых топей." }, { 7.23, "По равнине бродят стада кодо и громадные грозовые ящеры, а Золотой Путь здесь охраняется куда хуже, чем на севере: сторожевые башни у дороги давно заброшены." }, { 19.62, "Главная тревога последних лет — силитиды: их курганы, самые северные в Калимдоре, выросли посреди полей, и тролль Корран из Перекрёстка следит за насекомыми по приказу Оргриммара." } } } },
    ["f69ddeed"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Кил'джедена разозлила непокорность Нер'зула, и он стал искать другого орка, который смог бы заставить свой народ присоединиться к Легиону." }, { 10.63, "Хитрому великому демону удалось-таки найти достойного кандидата – им стал тщеславный ученик Нер'зула, Гул'дан." }, { 19.23, "Кил'джеден пообещал ему невиданную силу в обмен на полное повиновение." } } } },
    ["f6a1bff3"] = { d = 28.0, v = "nightelf-female", c = { x = { { 0.00, "Всё идёт хорошо." }, { 1.11, "Я вызвала себе на помощь значительное число воргенов." }, { 4.80, "Хотя они недалёкие существа, они умеют отлично сражаться строем и координировать свои атаки." }, { 11.21, "В каждой стае я отыскала лидера." }, { 13.49, "Им я доверила командование небольшими группами воинов." }, { 17.18, "Мы атакуем сразу из многих мест в лесу, и моя кампания против демонов идёт успешно." }, { 22.91, "Да пребудет со мной благословение Элуны, пока не будет выполнена моя работа." } } } },
    ["f6af07c5"] = { d = 32.8, v = "bloodelf-male", c = { x = { { 0.00, "*(Страницы исписаны древними эльфийскими рунами)*" }, { 4.00, "На этих страницах описаны события, случившиеся при сборе и создании ингредиентов, нужных для получения мощного зелья." }, { 13.34, "Пусть же наши враги никогда не заполучат эти манускрипты." }, { 17.94, "Пусть же я доживу до того дня, когда снова увижу Кель'Талас, озарённый бледным светом луны." }, { 25.19, "Пусть же я умру, но умру во славу Кель'таса." }, { 28.71, "Пусть же я убью во славу Иллидана." }, { 31.44, "-Кариэль Винтхалус" } } } },
    ["f6b28118"] = { d = 18.6, v = "narrator", c = { x = { { 0.00, "Свиноферма — одна из нескольких свиных ферм у ворот Оргриммара." }, { 5.35, "Здесь есть амбар, большой загон и пруд, а свинина отсюда идёт на столы Орды." }, { 11.76, "Ферма выглядит заброшенной: в загонах бродят одичавшие свиньи, а хозяев не видно." } } } },
    ["f6b867ea"] = { d = 29.6, v = "narrator", c = { x = { { 0.00, "Южные моря омывают восточный и южный берег Танариса; это часть Великого моря, лежащая между Калимдором и Восточными королевствами, к югу от Водоворота." }, { 11.53, "Где-то за горизонтом лежат тропические острова, откуда родом гоблины и куда уходят корабли из Порта Картеля." }, { 19.85, "В этих водах хозяйничают пираты Южных морей, в глубине кружат большие акулы, а на мелководье у берега пасутся береговые черепахи." } } } },
    ["f6e64ca5"] = { d = 30.6, v = "narrator", c = { x = { { 0.00, "Первая сотня магов, обученная эльфами использовать магию, развила своё могущество и начали глубже изучать тайны плетения заклинаний." }, { 10.55, "Эти маги, изначально выбранные из-за их сильной воли и доблести, всегда очень осторожно практиковали свою магию; но они передали свою силу и тайны магии новому поколению, не имевшему никакого представления об ужасах войны или необходимости самоконтроля." } } } },
    ["f707828b"] = { d = 47.8, v = "narrator", c = { x = { { 0.00, "Круговзор — торговый город гоблинов картеля Хитрая Шестерёнка, стоящий на перекрёстке главных дорог Зимних Ключей." }, { 8.66, "Это единственный крупный гоблинский форпост на севере Калимдора: гоблины добывают здесь торий и арканит и торгуют со всеми, кто платит, — с Ордой и Альянсом наравне." }, { 21.24, "В городе есть таверна, банк, аукцион и площадка для гиппогрифов и ветрокрылов, а за порядком следят крепкие вышибалы, готовые заступиться за друзей картеля." }, { 33.00, "Здесь же посланник Серебряного Рассвета Грегор ведёт переговоры с гоблинами, дворф из Братства Тория торгует редкими рецептами, а инженеры вроде Мегги и Харло вечно ищут помощников для своих затей." } } } },
    ["f7078b22"] = { d = 30.1, v = "narrator", c = { x = { { 0.00, "Малфурион знал, что планы его брата, одержимого могуществом, не приведут ни к чему хорошему, поэтому он решил раз и навсегда избавиться от Иллидана." }, { 11.25, "Вместе с Кенарием они заключили его в тюрьму под холмами, где Иллидану надлежало оставаться до конца его жизни, обессиленным и закованным в цепи." }, { 22.44, "Малфурион поручил юной стражнице по имени Майев Песнь Теней следить за Иллиданом, чтобы тот не сбежал." } } } },
    ["f71d74f7"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "Храмовые сады — сердце Дарнасса, широкое озеро с островами и мостами в самом центре города." }, { 7.52, "Названы они по Храму Луны, что высится на южном берегу." }, { 12.12, "На самом большом острове стоит банк, а на западном краю светится портал, ведущий вниз, в Деревню Рут'теран у подножия древа." }, { 22.20, "Мосты связывают сады со всеми террасами города и с Анклавом Кенария." }, { 27.82, "Здесь тихо, и вода отражает лунный свет даже днём." } } } },
    ["f71f25ed"] = { d = 63.5, v = "narrator", c = { x = { { 0.00, "Дуротар — суровая красная земля на восточном побережье Калимдора, ставшая домом орков после Третьей войны." }, { 8.80, "Тралл назвал её в честь своего отца Дуротана, вождя клана Северного Волка, а столицу Оргриммар — в честь Оргрима Молота Рока." }, { 18.99, "Растрескавшаяся почва, сухие каньоны и колючие заросли напоминают оркам о родном Дреноре." }, { 26.33, "На западе, за рекой Строптивой, лежат Степи, на севере — Азшара, а восточный берег омывает Великое море." }, { 34.91, "Мир здесь хрупок: флот Кул-Тираса под началом адмирала Праудмура уже пытался уничтожить молодую Орду, и остатки его солдат до сих пор держат крепость Тирагард." }, { 47.50, "Иглогривые, кентавры Колкар и гарпии Пыльного Ветра теснят поселения, а в пещерах тайно собирается культ Пылающего Клинка." }, { 57.48, "Рядом с орками живут тролли Чёрного Копья, изгнанные с островов Эха." } } } },
    ["f762f773"] = { d = 30.0, v = "human-female", c = { x = { { 0.00, "Я снова загорелась интересом и вернулась к своим экспериментам." }, { 4.31, "В этот раз я не выдвигала никаких предположений, методично делая все тесты, что были в моём распоряжении." }, { 11.38, "Это чрезвычайно увеличило понадобившиеся усилия, но шансы прояснить что-либо увеличились соответственно." }, { 18.45, "И, несмотря на то что моя лаборатория мала и у меня нет помощников, к которым я могла бы обратиться за помощью, я обнаружила ещё одно интригующее свойство кровавого камня..." } } } },
    ["f78a18bd"] = { d = 15.6, v = "narrator", c = { x = { { 0.00, "Тролли долгие годы воевали с акири, но так и не смогли одержать над ними настоящую победу." }, { 6.92, "Всё, что им удалось, – это расколоть вражеское королевство на части и изгнать насекомых в далёкие земли севера и юга." } } } },
    ["f7a9838e"] = { d = 12.6, v = "narrator", c = { x = { { 0.00, "Котлы должны были находиться под охраной служителей Культа, а впоследствии использоваться в качестве источников чумы, разносящих по всем деревням и городам на севере Лордерона." } } } },
    ["f7b72f63"] = { d = 10.3, v = "narrator", c = { x = { { 0.00, "Бетек Штормоскал" }, { 1.56, "Странствия Бетека завели его в глубины Чёрной горы." }, { 6.31, "Секреты гор манили его." }, { 8.52, "Да укрепится его дух." } } } },
    ["f7d2efa1"] = { d = 14.7, v = "narrator", c = { x = { { 0.00, "Со временем Кенарий стал другом Шу'хало и рассказывал им о мире." }, { 5.15, "Дети земли назвали его своим братом и поклялись помогать ему в заботе о полях жизни и любимых созданиях Матери-Земли." } } } },
    ["f7e55230"] = { d = 9.4, v = "narrator", c = { x = { { 0.00, "В случае успеха миссии по истреблению людей Кил'джеден пообещал Нер'зулу свободу от проклятия и новое здоровое тело." } } } },
    ["f7ecf4ee"] = { d = 24.6, g = 1, v = "orc-female", c = { m = { { 0.00, "Лок-тар, брат." }, { 1.16, "Стихии указали на тебя и поручили мне показать тебе путь шамана." }, { 6.37, "Духи наших предков смотрят на нас и гордятся тем, что ты вступил в наши ряды." }, { 12.60, "Когда будешь готов, найди меня у входа в Логово." }, { 16.66, "Я обучаю там наших собратьев." }, { 19.05, "Да будет тебе попутный ветер." }, { 21.51, "-Шикрик, наставница шаманов" } }, f = { { 0.00, "Лок-тар, сестра." }, { 1.41, "Стихии указали на тебя и поручили мне показать тебе путь шамана." }, { 6.75, "Духи наших предков смотрят на нас и гордятся тем, что ты вступила в наши ряды." }, { 13.21, "Когда будешь готова, найди меня у входа в Логово." }, { 17.44, "Я обучаю там наших собратьев." }, { 19.89, "Да будет тебе попутный ветер." }, { 22.41, "-Шикрик, наставница шаманов" } } } },
    ["f8131d7a"] = { d = 28.3, v = "narrator", c = { x = { { 0.00, "Хири'вата — деревня троллей племени Сухокожих на западе Внутренних земель, к югу от сторожки Кель'Данил." }, { 8.11, "Среди старых руин Амани стоят хижины, горят костры и висят тотемы: Сухокожие живут здесь, как их предки, а до эльфийской сторожки и дворфийских дорог отсюда рукой подать." }, { 21.47, "Меж хижин ходят охотники, ворожеи и берсерки, и пришельцу лучше не задерживаться на виду." } } } },
    ["f8182456"] = { d = 22.6, v = "narrator", c = { x = { { 0.00, "Вершина Охотников лежит к югу от центрального утёса." }, { 4.18, "Здесь живут охотники и воины тауренов, а с ними трапперы, следопыты и кожевники." }, { 10.60, "Под навесами стоят мишени для упражнений, и здесь же вербовщики ищут желающих сразиться с Альянсом." }, { 18.46, "Мосты ведут отсюда на нижний ярус и к вершине вождя." } } } },
    ["f8245961"] = { d = 24.1, v = "narrator", c = { x = { { 0.00, "Они плыли в молчании, глядя на то, что осталось от их народа, и понимая, что в этом виноваты лишь они сами и их страсти." }, { 10.14, "Конечно, после уничтожения Источника Саргерасу и Пылающему Легиону больше не было хода в этот мир, но цена, которую пришлось заплатить за это, была поистине ужасной." } } } },
    ["f827d45a"] = { d = 12.5, v = "tauren-male", c = { x = { { 0.00, "Ниже ты найдёшь список того, что мне понадобится для заклинания призыва великого Циклониана." }, { 8.29, "Да сопутствует тебе удача." }, { 10.75, "--Бат-ра Ветростраж." } } } },
    ["f84e01c5"] = { d = 23.5, v = "narrator", c = { x = { { 0.00, "Молот Рока желал наказать своенравных орков за столь дерзкое предательство и послал своих воинов убить Гул'дана и вернуть остальных изменников." }, { 10.91, "Обезумевшие демоны, которых столь опрометчиво освободил Гул'дан, разорвали его на клочки." }, { 17.67, "Потеряв своего командира, воины тотчас сдались на милость войска Молота Рока." } } } },
    ["f862d9f3"] = { d = 20.1, v = "dwarf-male", c = { x = { { 0.00, "Первое убийство взбодрило нашу команду." }, { 2.92, "Барнил налил всем меда, чтобы отметить его." }, { 6.16, "Но нашему празднованию не суждено было продолжаться долго." }, { 10.37, "Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рёв." }, { 16.59, "Я в жизни не слышал такого леденящего кровь звука." } } } },
    ["f880dd26"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "Аригос первым заметил странное излучение." }, { 3.49, "Массивный храм на юге Ан'Киража испускал слабые магические волны, не похожие ни на что, исходящее прежде от киражей." }, { 12.98, "Как союзники ни пытались, никому не удалось проникнуть в храм и найти источник этой энергии." }, { 20.54, "Окружить себя такой непробиваемой защитой могло лишь нечто, обладающее огромной силой." }, { 27.74, "Возможно, это было нечто, управляющее насекомыми." }, { 31.89, "Нечто, управляющее даже киражей." } } } },
    ["f88330d8"] = { d = 38.6, v = "narrator", c = { x = { { 0.00, "Деревня Звездопада — небольшое поселение ночных эльфов на главной дороге, к северо-западу от Круговзора и южнее Уступа Ледопардов; это единственный оплот Альянса в Зимних Ключах." }, { 14.48, "Здесь стоит эльфийская хижина, домик поменьше и тихая берлога Бен'Таллоу, а торговцы предлагают еду, товары и припасы." }, { 24.09, "Ночные эльфы деревни присматривают за совухами, живущими по соседству, и хранят память о высокорождённых Кел'Терила; вместе с ними здесь трудится дворф Джерон, изучающий руины у озера." } } } },
    ["f888d013"] = { d = 35.4, v = "narrator", c = { x = { { 0.00, "Мост Тандола — две исполинские каменные арки через пропасть между Болотиной Каз Модана и нагорьем Арати." }, { 8.14, "Дворфы Стальгорна возвели их после войны Трёх Кланов, чтобы сохранить торговлю с сородичами из клана Громового Молота." }, { 17.41, "Во Вторую войну именно через мост Тандола Альянс вытеснил Орду обратно в Каз Модан." }, { 24.01, "Недавно дворфы Чёрного Железа разрушили одну из арок и захватили Дун Модр по ту сторону пропасти, и теперь дворфы отчаянно обороняют уцелевший пролёт." } } } },
    ["f89875ae"] = { d = 23.6, v = "dwarf-male", c = { x = { { 0.00, "И в заключение я должен вновь напомнить о моей просьбе доставить взрывчатого порошка." }, { 5.98, "Мои запасы подходят к концу, что серьёзно препятствует успеху экспедиции." }, { 11.14, "Мне обещали, что взрывчатый порошок вскоре будет доставлен, но я до сих пор его не получил." }, { 17.51, "Какова причина, позвольте спросить, этой задержки?" }, { 21.13, "С уважением," }, { 22.02, "Геолог Дартеус Железняк" } } } },
    ["f8a5608a"] = { d = 33.1, v = "narrator", c = { x = { { 0.00, "Ферма Балнира — разорённое хозяйство на востоке Тирисфаля, к северо-востоку от руин Лордерона." }, { 7.25, "Семья Балниров разводила знаменитых белых коней Лордерона, которых покупали для королевского двора." }, { 15.00, "Теперь здесь гнездится Плеть: мертвецы, проскользнувшие мимо защитников Бастиона, находят приют на пустых полях, и страж смерти Линнея просит прореживать их ряды." }, { 27.48, "Среди сорняков ещё цветёт львиный зёв, который когда-то выращивали Балниры." } } } },
    ["f8a9059b"] = { d = 28.5, v = "narrator", c = { x = { { 0.00, "Оставшись в одиночестве защищать Калимдор от опасностей нового мира, Тиранда собрала мощную армию своих сестёр, ночных эльфиек." }, { 9.94, "Бесстрашные, искусные воительницы, поклявшиеся защищать Калимдор, стали известны как Часовые." }, { 17.15, "Хотя они предпочитали самостоятельно патрулировать тенистый Ясеневый лес, у них было множество союзников, которых они призывали во время опасностей." } } } },
    ["f8b0abf6"] = { d = 34.7, v = "narrator", c = { x = { { 0.00, "Усадьба Дабири стоит на севере нагорья, в стороне от дороги, по которой ходят конные разъезды Стромгарда." }, { 8.26, "Здесь живёт семья Дабири — подданные павшего королевства, сумевшие пережить войну и сохранить хозяйство." }, { 16.31, "Хозяйка держит наёмных работников и собственное ополчение, и чужаков, будь то Альянс или Орда, на своей земле не жалуют." }, { 25.63, "У Отрёкшихся к этой семье старые счёты: те, кто потерял всё во время чумы, не простили Дабири их уцелевшего благополучия." } } } },
    ["f8b69de1"] = { d = 37.0, v = "narrator", c = { x = { { 0.00, "Лагерь экспедиции Эрнестуэя разбит у реки, к северу от озера Назферити." }, { 5.70, "Прославленный дворфийский охотник Эрнестуэй привёл сюда спутников ради большой охоты: Ажек учит выслеживать тигров, сэр Эрлгедин — пантер, а сам Эрнестуэй — ящеров." }, { 18.66, "Верный Барнил записывает их приключения в книгу «Зелёные холмы Тернистой долины», страницы которой ветер разносит по всей долине." }, { 28.85, "Новичку здесь придётся доказать своё мастерство, прежде чем его допустят к самым грозным зверям джунглей." } } } },
    ["f8b8ee04"] = { d = 33.0, v = "narrator", c = { x = { { 0.00, "Контроль над зверем:" }, { 1.59, "Ищейка Скверны понимает только звериные эмоции." }, { 5.31, "Чтобы заставить вашу ищейку Скверны искать залежи азшарита, необходимо на неё бешено зарычать!" }, { 12.62, "(Нацельтесь на ищейку Скверны и изобразите эмоцию «бешенство».)" }, { 17.45, "Когда ищейка Скверны обнаружит залежь, она побежит к ней, не обращая внимания на окружающих существ." }, { 25.18, "Хотя вам не нужно защищать ищейку Скверны, возможно, вы захотите быть рядом с ней, чтобы не потерять её." } } } },
    ["f8d8e254"] = { d = 31.4, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Ты уже ощутил зов чего-то более великого, чем ты сам, и это зов стихий." }, { 5.48, "У нас, дворфов, крепкая связь с землёй, но при должном обучении ты сможешь разговаривать со всеми стихиями." }, { 13.53, "Элементали бывают требовательными и непокорными, но я могу обучить тебя общаться с ними." }, { 20.34, "Разыщи меня в Старой Наковальне, и я поделюсь знаниями о том, как слушать стихии и заставлять их слышать тебя." }, { 28.80, "Тео Молотошторм, наставник шаманов" } }, f = { { 0.00, "Ты уже ощутила зов чего-то более великого, чем ты сама, и это зов стихий." }, { 5.60, "У нас, дворфов, крепкая связь с землёй, но при должном обучении ты сможешь разговаривать со всеми стихиями." }, { 13.51, "Элементали бывают требовательными и непокорными, но я могу обучить тебя общаться с ними." }, { 20.20, "Разыщи меня в Старой Наковальне, и я поделюсь знаниями о том, как слушать стихии и заставлять их слышать тебя." }, { 28.53, "Тео Молотошторм, наставник шаманов" } } } },
    ["f8d9b643"] = { d = 32.7, v = "narrator", c = { x = { { 0.00, "Павильон Лорисс — просторное открытое строение в эльфийском стиле к северу от Лагеря Мохаче." }, { 7.14, "Дриады, что живут вокруг, некогда были мирными, но порча извратила их, и теперь они бросаются на всякого." }, { 15.33, "Под сводами павильона нашёл приют Высокорождённый, покинувший Забытый Город: он не смирился с безумием принца Тортелдрина и ушёл потайным ходом, что открывается у подножия павильона." }, { 29.06, "По дороге бесёнок стащил у него книгу заклинаний." } } } },
    ["f900b565"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Скала Черепа — пещера на северо-востоке Дуротара, к востоку от Оргриммара, одно из убежищ культа Пылающего Клинка." }, { 9.56, "Здесь скрывается орк-чернокнижник Газз'уз, а его сектанты совершают гнусные обряды и носят обжигающие ошейники, связывающие их с демонами." }, { 20.91, "Заговор зреет под самым носом у столицы Орды." } } } },
    ["f90d94b6"] = { d = 28.3, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Готов спорить, что ты сначала решил, будто это настоящее письмо от короля или кого-то там ещё." }, { 6.56, "Видишь ли, я знаю толк в фальшивых письмах." }, { 9.53, "Мне надо было убедиться, что ты точно прочтёшь это послание, а как ещё этого добиться?" }, { 15.41, "Я нахожусь в Старой Наковальне, рядом с огненной ямой." }, { 19.18, "Как будешь готов, приходи, поговорим." }, { 21.78, "Было бы любопытно с тобой познакомиться." }, { 24.56, "-Сольм Харгрин, наставник разбойников" } }, f = { { 0.00, "Готов спорить, что ты сначала решила, будто это настоящее письмо от короля или кого-то там ещё." }, { 6.90, "Видишь ли, я знаю толк в фальшивых письмах." }, { 10.00, "Мне надо было убедиться, что ты точно прочтёшь это послание, а как ещё этого добиться?" }, { 16.13, "Я нахожусь в Старой Наковальне, рядом с огненной ямой." }, { 20.06, "Как будешь готова, приходи, поговорим." }, { 22.84, "Было бы любопытно с тобой познакомиться." }, { 25.74, "-Сольм Харгрин, наставник разбойников" } } } },
    ["f9138366"] = { d = 25.3, g = 1, v = "human-male", c = { m = { { 0.00, "Мастер Карвин!" }, { 1.08, "Принёсший это сообщение осенён благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Карвин на их пути к Свету." }, { 14.36, "В моём послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света." }, { 24.10, "С уважением," }, { 24.98, "Калор" } }, f = { { 0.00, "Мастер Карвин!" }, { 1.06, "Принёсшая это сообщение осенена благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Карвин на их пути к Свету." }, { 14.23, "В моём послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света." }, { 23.80, "С уважением," }, { 24.67, "Калор" } } } },
    ["f919171a"] = { d = 48.6, v = "human-male", c = { x = { { 0.00, "Самла!" }, { 0.49, "Принц Артас ведёт нас всё дальше и дальше на север, и у меня на сердце становится совсем тяжело." }, { 6.94, "Когда-то в этом молодом паладине ярко сиял Свет, а теперь я чувствую, как его поглощает тьма." }, { 13.28, "От его былого рвения и бесстрашия не осталось и следа, его преследует что-то ужасное; как бы мне хотелось знать, что это…" }, { 21.44, "Скоро мы выберемся из этой ледяной пустыни." }, { 24.42, "Многие солдаты замёрзли насмерть и пали от когтей местных хищников, но Артас говорит, что если наши поиски увенчаются успехом, всему этому кошмару придёт конец." }, { 35.32, "Но его слова не придали мне никакой уверенности: после окончания речи на лице Артаса появилась мрачная улыбка, от которой у меня на душе стало ещё холоднее." }, { 45.98, "Молись за нас, Самла, и за наш мир," }, { 48.29, "Торгал" } } } },
    ["f9229d75"] = { d = 20.7, v = "narrator", c = { x = { { 0.00, "Настал роковой для Оленьего Шлема момент – младшему Оленьему Шлему, Вальстану, было приказано оборонять заставу ночных эльфов в деревне Южного Ветра." }, { 12.39, "Увы, в тот же день Вальстан расстался с жизнью: Деревня Южного Ветра пала под натиском армий Ан'Киража." } } } },
    ["f964d518"] = { d = 37.0, v = "goblin-male", c = { x = { { 0.00, "Задержанная посылка -" }, { 1.54, "Я нанял кое-кого с репутацией надёжного пилота, чтобы доставить груз из Терамора." }, { 7.32, "Я ошибался." }, { 8.16, "Несмотря на то что пилот выжил и смог рассказать мне эту историю, он бросил и свой дирижабль и весь мой груз, чтобы спасти свою шею." }, { 17.47, "В общем, мне нужно вернуть мой товар." }, { 20.17, "Исходя из того, что рассказал мне Бизиль, он потерпел крушение к западу от берега Пылевых топей." }, { 27.04, "Он начал падать сразу после того, как пересёк холмы, окаймляющие море." }, { 32.11, "Хм-м-м... он никогда не рассказывал мне, что послужило причиной аварии..." } } } },
    ["f96aca92"] = { d = 34.5, v = "narrator", c = { x = { { 0.00, "Дун Модр — дворфийский город на севере Болотины, у самого моста Тандола." }, { 5.72, "Недавно его захватили и разграбили дворфы Чёрного Железа, и теперь на улицах слышна их речь, а не речь Стальгорна." }, { 14.67, "Уцелевшие защитники отступили и разбили лагерь у дороги к югу от города, откуда наблюдают за захватчиками и ждут подкреплений." }, { 24.61, "Тому, кто идёт от Гавани Менетилов на север, стоит помнить: за этим лагерем начинается земля, где приказы отдаёт Чёрное Железо." } } } },
    ["f96b5b26"] = { d = 38.6, v = "narrator", c = { x = { { 0.00, "Скользкий овраг — глубокая расселина на юге кратера, изрытая ходами силитидов." }, { 6.39, "Здесь живёт рой Гориши: рабочие и осы стерегут кладки яиц в тёплых сырых туннелях, а из глубины улья тянется гул, от которого дрожит земля." }, { 17.58, "Насекомые не терпят чужаков и бросаются на любого, кто ступит на их землю, но преследовать беглеца за пределы оврага не станут." }, { 27.75, "Учёные из Укрытия Маршалла заметили, что улей вырос как раз там, где у кратера недостаёт южного пилона, и гадают, что бы это могло значить." } } } },
    ["f96fe89e"] = { d = 18.9, v = "dwarf-male", c = { x = { { 0.00, "Я обещал своим товарищам, что на следующий день мы отправимся охотиться на пантер, так как их мех очень высоко ценится по всему Азероту." }, { 9.17, "Учитывая, что большинство охотников и торговцев мехом сейчас храбро отдавали свои жизни, сражаясь за Альянс, этот мех ещё больше возрос в цене." } } } },
    ["f98e9cc8"] = { d = 43.1, v = "narrator", c = { x = { { 0.00, "Дарроушир на южной окраине края назван в честь озера Дарроумир." }, { 5.11, "Когда Плеть хлынула в Лордерон, деревню защищали её ополченцы под началом капитана Джозефа Редпата и паладины Серебряной Длани во главе с Дейвилом Крокфордом." }, { 17.71, "Вурдалаков лорда Хоргуса удалось остановить, но рыцарь смерти Мардук Чёрный обратил душу Редпата во тьму, и защитники сами перерезали тех, кого укрывали." }, { 29.95, "Ныне Дарроушир — тихие руины, где среди пепла бродят призраки, а девочка Памела всё ещё ждёт своего отца." }, { 38.45, "Говорят, порой над деревней тени вновь разыгрывают ту битву." } } } },
    ["f9938852"] = { d = 45.0, v = "narrator", c = { x = { { 0.00, "Чёрная гора встаёт над южным краем ущелья — огромный вулкан, рождённый в тот день, когда колдун-тан Тауриссан призвал Рагнароса." }, { 10.95, "Она отделяет Тлеющее ущелье от Пылающих степей, и единственный путь между ними проходит сквозь её недра." }, { 20.02, "В глубине горы дворфы Чёрного Железа возвели свой город, Глубины Чёрной горы, а ещё ниже, в Огненных Недрах, дремлет сам Повелитель Огня." }, { 31.90, "Вершину, Пик Чёрной горы, держат орки клана Чёрной горы, и над ними властвует чёрный дракон Нефариан." }, { 40.66, "Из ущелья к горе ведёт дорога через Пепельное Море." } } } },
    ["f9971be0"] = { d = 25.8, v = "narrator", c = { x = { { 0.00, "Но в последние дни Второй войны, когда победа Орды казалась уже неизбежной, между двумя самыми могучими орками Азерота возникли небывалые раздоры." }, { 11.25, "Когда Молот Рока готовился к решающей атаке на столицу Лордерона, которая должна была сокрушить последние силы Альянса, Гул'дан и его сторонники покинули остальное войско и отправились в море." } } } },
    ["f9deacb3"] = { d = 11.4, v = "orc-male", c = { x = { { 0.00, "Эльф!" }, { 0.43, "Как гостю Орды, вождь дозволяет тебе свободно передвигаться по её территориям." }, { 6.58, "Этот путеводитель поможет тебе не потеряться на наших землях." } } } },
    ["f9ff6b17"] = { d = 24.2, v = "orc-male", c = { x = { { 0.00, "-День семнадцать" }, { 1.31, "Улег вернулся с задания." }, { 3.35, "Он потерпел неудачу, а Таргил попал в плен." }, { 6.84, "Я послал Улега доставить это сообщение Назиру." }, { 10.70, "Я останусь здесь." }, { 12.08, "Я видел, что от побережья Терамора всё чаще отходят корабли." }, { 16.96, "Продолжу вести наблюдение и буду лично сообщать о всяком заслуживающем упоминания событии." } } } },
    ["fa042061"] = { d = 22.1, v = "narrator", c = { x = { { 0.00, "Ферма Тор'кренов расположена на северо-западе Дуротара, к юго-востоку от Громового хребта." }, { 6.72, "Это небольшая свиноферма, не столь прибыльная, как соседние." }, { 11.11, "Хозяйка, Майша Тор'крен, ведёт хозяйство одна: её сын Крон ушёл охотиться на кроколисков к реке Строптивой и не вернулся, и мать всё ещё ждёт вестей о нём." } } } },
    ["fa0d7706"] = { d = 23.7, v = "human-male", c = { x = { { 0.00, "Нападение произойдёт за несколько миль до места прибытия." }, { 3.73, "Именно там будут ожидать наши союзники." }, { 6.44, "Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный." }, { 15.16, "Но это, в общем-то, не важно." }, { 17.14, "Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!" } } } },
    ["fa11d57b"] = { d = 30.3, v = "goblin-male", c = { x = { { 0.00, "Прочная хрустальная нога-" }, { 1.79, "Хрустальные пауки из Тлеющего ущелья сделаны из невероятного кристаллоподобного материала." }, { 7.89, "Из их ног, в том случае если они не повреждены при убийстве их владельцев, получаются замечательные трубки, необходимые в экспериментах моих компаньонов-инженеров." }, { 18.87, "Мне понадобится некоторое их количество, чтобы провести тестирование." }, { 23.56, "У пауков есть восемь ног, так что достать их будет не проблемой для крепкого воина или опытного мага." } } } },
    ["fa1c94c8"] = { d = 33.0, g = 1, v = "troll-male", c = { m = { { 0.00, "Надеюсь, духи исправно тебя защищали." }, { 3.18, "Тебе предстоит ещё много испытаний, поэтому я хочу вот обучить тебя тому, что сам знаю." }, { 10.42, "Сам решай, хочешь ли обладать нашими силами, и если да, то приходи." }, { 15.97, "Выбирать тебе – я могу только вести тебя." }, { 19.52, "Ну, одни-то, конечно, учатся быстро, а другие вот… помедленней." }, { 24.69, "Но ты не волнуйся заранее." }, { 26.84, "Как захочешь меня увидеть – приходи, поговорим." }, { 30.75, "-Кен'джай, наставница Жрецов." } }, f = { { 0.00, "Надеюсь, духи исправно тебя защищали." }, { 3.10, "Тебе предстоит ещё много испытаний, поэтому я хочу вот обучить тебя тому, что сам знаю." }, { 10.18, "Сама решай, хочешь ли обладать нашими силами, и если да, то приходи." }, { 15.73, "Выбирать тебе – я могу только вести тебя." }, { 19.20, "Ну, одни-то, конечно, учатся быстро, а другие вот… помедленней." }, { 24.25, "Но ты не волнуйся заранее." }, { 26.34, "Как захочешь меня увидеть – приходи, поговорим." }, { 30.17, "-Кен'джай, наставница Жрецов." } } } },
    ["fa3137c6"] = { d = 29.7, v = "narrator", c = { x = { { 0.00, "Как только Кел'Тузад вернулся к жизни, Артас повёл Плеть на юг, к Даларану." }, { 5.89, "Там лич должен был найти книгу заклинаний Медива и с её помощью вернуть в этот мир Архимонда." }, { 13.30, "После этого Архимонд должен был возглавить Легион и повести его в решающий бой." }, { 19.70, "Даже волшебники Кирин-Тора не смогли помешать Артасу завладеть книгой Медива, и Кел'Тузаду оставалось лишь прочесть заклинание." } } } },
    ["fa35b9b3"] = { d = 33.5, v = "human-male", c = { x = { { 0.00, "Нападение было ужасным." }, { 1.65, "Они убили треть из нас к тому моменту, когда мы смогли их уничтожить." }, { 6.37, "И теперь у нас едва хватает людей для защиты наших границ." }, { 10.40, "Это лишь вопрос времени, когда наши утомлённые стражники падут и Плеть атакует нас." }, { 16.03, "И хотя я видел лицо Девлина среди доведённых до отчаяния мужчин и мрачнолицых воинов Плети в ту проклятую ночь, он ускользнул от меня прежде, чем я смог до него добраться." }, { 27.54, "Возможно, он мёртв – а возможно, выжил, и стал агентом Плети." }, { 31.64, "Как бы то ни было, он – монстр." } } } },
    ["fa471f16"] = { d = 18.5, v = "narrator", c = { x = { { 0.00, "Лагерь талассийского авангарда — передовой пост экспедиции эльфов крови из Кель'Таласа, пришедшей в Азшару за реликвиями высокорождённых." }, { 10.32, "Его палатки и знамёна стоят на пути к главному поселению, и дозорные с подозрением встречают всякого чужака." } } } },
    ["fa4eeaf3"] = { d = 37.5, v = "narrator", c = { x = { { 0.00, "Лагерь Кош — самая северная из четырёх стоянок огров-Гнилобрюхов, разбитая среди скал на северо-востоке пустыни." }, { 8.76, "Отсюда огры нападают на обозы, что идут через Бесплодные земли в Каргат или дальше, в Тлеющее ущелье." }, { 16.95, "Когда дворфы спешно уходили с раскопок Ульдамана, им пришлось бросить по дороге повозки и ящики с припасами, и всё это, вместе с оружием и провизией, растащили огры из лагеря Кош." }, { 31.12, "Здесь живут воины и мистики племени, и путникам лучше обходить их костры стороной." } } } },
    ["fa7fa085"] = { d = 31.4, v = "bloodelf-male", c = { x = { { 0.00, "*(Страницы исписаны древними эльфийскими рунами)*" }, { 3.84, "На этих страницах описаны события, случившиеся при сборе и создании ингредиентов, нужных для изготовления магического камня." }, { 13.11, "Пусть же наши враги никогда не заполучат эти манускрипты." }, { 17.44, "Пусть же я доживу до того дня, когда снова увижу Кель'Талас, озарённый бледным светом луны." }, { 24.28, "Пусть же я умру, но умру во славу Кель'таса." }, { 27.59, "Пусть же я убью во славу Иллидана." }, { 30.17, "-Кариэль Винтхалус" } } } },
    ["faa63e5f"] = { d = 11.0, v = "narrator", c = { x = { { 0.00, "В честь сумерек, павших на мир в их последний день работы, титаны назвали этот континент Калимдором – \"землёй вечного звёздного света\"." } } } },
    ["faadd69d"] = { d = 30.6, v = "skyborne-male" },
    ["fab08f5e"] = { d = 18.2, v = "narrator", c = { x = { { 0.00, "Череп Гул'дана дал Иллидану демонический облик и огромную силу." }, { 4.98, "Кроме того, он получил часть воспоминаний Гул'дана, главным образом о Гробнице Саргераса – подземелье на острове, где, по слухам, находились останки Титана Мрака Саргераса." } } } },
    ["fadffd0e"] = { d = 19.5, v = "narrator", c = { x = { { 0.00, "Многим высокорождённым тоже удалось выжить, и они отправились к берегам новой земли вместе с ночными эльфами." }, { 8.25, "Малфурион до сих пор сомневался в Высокорождённых, но он был рад хотя бы тому, что Источника больше нет, а без его энергии они не представляют собой угрозы." } } } },
    ["fb09f2b3"] = { d = 67.1, v = "narrator", c = { x = { { 0.00, "Танарис — бескрайняя пустыня на юго-востоке Калимдора, к югу от Тысячи Игл и к востоку от кратера Ун'Горо." }, { 8.47, "Под безоблачным небом здесь тянутся раскалённые дюны, а песчаные бури налетают внезапно и стирают любые следы." }, { 17.23, "Когда-то эти земли были джунглями империи Гурубаши, но Великий Раскол превратил их в пески, и уцелевшие тролли племени Песчаной Бури заперлись в городе Зул'Фаррак." }, { 30.37, "На севере гоблины картеля Хитрая Шестерёнка выстроили Прибамбасск и Порт Картеля, где рады любому, кто платит." }, { 39.06, "Редкие колодцы в песках оспаривают друг у друга Скитальцы Пустыни, пираты Южных морей и огры клана Песчаного Молота, а под барханами роют свои ульи силитиды." }, { 51.76, "В горах на востоке лежат Пещеры Времени, где с незапамятных времён обитают бронзовые драконы Ноздорму, а на дальнем юге, в Долине Стражей, стоят запертые врата древнего города титанов — Ульдума." } } } },
    ["fb256e8c"] = { d = 19.0, v = "narrator", c = { x = { { 0.00, "После долгих месяцев блуждания по суровым снежным пустошам Кел'Тузад, наконец, добрался до Ледяной Короны." }, { 8.62, "Он смело подошёл к тёмной крепости Нер'зула, и, к его удивлению, стражники-нежить молча расступились – так, словно мага здесь ждали." } } } },
    ["fb344233"] = { d = 38.4, v = "orc-male", c = { x = { { 0.00, "Колокол, Колесо и Свеча не только хранят энергию для ритуала, но и обладают собственными уникальными свойствами." }, { 9.09, "Колокол Детмуры, испуская звон, дарует чернокнижникам в круге силу и энергию." }, { 15.39, "Колесо Чёрного Похода при вращении защищает тех, кто стоит в круге, от урона." }, { 21.62, "Когда горит Свеча Судного Дня, она поражает врагов, вступивших в круг, магической энергией." }, { 29.10, "Эти предметы очень полезны, и потому очень важно следить за тем, чтобы во время ритуала они работали бесперебойно." } } } },
    ["fb8dbeaa"] = { d = 27.1, v = "narrator", c = { x = { { 0.00, "Застава Зловещего Тотема на юго-востоке гор — оплот отступников-тауренов, не признающих единения племён под властью Кэрна Кровавого Копыта." }, { 11.70, "Здесь правит свирепый Грундиг Тёмное Облако, а вокруг патрулируют громилы, бузотёры, наёмники и колдуны племени." }, { 20.97, "Отсюда Зловещие Тотемы напали на соседний Лагерь Апарахе и увели пленных." } } } },
    ["fb9a4eb3"] = { d = 24.6, v = "narrator", c = { x = { { 0.00, "Вскоре он превратил эту миролюбивую расу в жестоких, кровожадных воинов." }, { 6.03, "Нер'зулу и его народу оставалось сделать последний роковой шаг: стать вестниками смерти, полностью посвятив себя войне." }, { 15.93, "Но старый шаман понял, что для орков это означало вечное рабство, и ему удалось не поддаться воле демона." } } } },
    ["fbb0c70b"] = { d = 27.0, v = "dwarf-male", c = { x = { { 0.00, "Если мы сможем сами решать, какой машине быть в отличном состоянии, а какой нет... полагаю, излишне объяснять, какое преимущество это даст нам на ставках." }, { 11.48, "Итак, от вас, милый Шипучка, мы ожидаем средство, которое ослабит прилежание техников." }, { 17.92, "Нет ли в Тернистой долине растений, трав или напитков, что могли бы размягчить мозги гномам и гоблинам?" }, { 25.58, "-- К." }, { 25.98, "Угольная Борода" } } } },
    ["fbeb03b3"] = { d = 25.6, v = "dwarf-male", c = { x = { { 0.00, "Шли недели, шкур пантер и тигров становилось всё больше." }, { 4.05, "Мне показалось, что настало время сосредоточить наши силы на более серьёзной добыче: ящерах." }, { 10.72, "Люди поблагодарили нас с Барнилом за уроки, но отказались использовать огнестрельное оружие." }, { 17.32, "Ажек чувствовала себя куда более уверенно с луком в руках, а сэр Эрлгедин не расставался со своим мощным арбалетом." } } } },
    ["fbefa0f2"] = { d = 31.8, v = "narrator", c = { x = { { 0.00, "В то время как Медив пытался убедить орков и людей в необходимости объединить силы, ночные эльфы сами боролись с Легионом." }, { 9.57, "Тиранда Шелест Ветра, бессмертная верховная жрица ночных эльфов-Стражей, отчаянно сражалась с демонами и мертвецами, чтобы не дать им захватить Ясеневый лес." }, { 21.72, "Тиранда поняла, что одной ей не справиться, и велела пробудить друидов ночных эльфов от многовекового сна, чтобы просить их о помощи." } } } },
    ["fbf76798"] = { d = 70.6, v = "narrator", c = { x = { { 0.00, "Сумеречный лес лежит к югу от Элвиннского леса, между Западным Краем и перевалом Мёртвого Ветра, а на юге за мостом начинается Тернистая долина." }, { 11.52, "Когда-то это была южная окраина Элвинна, но после того как с перевала пришла тьма, над лесом навсегда сгустился полумрак, деревья скрючились, а на кладбищах поднялась нежить." }, { 25.49, "По чащам рыщут воргены, с юга подступили огры, на брошенных фермах хозяйничает Братство Справедливости." }, { 33.77, "Штормград бросил эти земли на произвол судьбы, и жители Темнолесья создали своё ополчение – Ночной дозор." }, { 42.27, "В сердце леса, в кратере потухшего вулкана, стоит древнее дерево с порталом в Изумрудный Сон, и вокруг него царят не мрак, а тихие сумерки." }, { 53.43, "На северо-западе Свен ищет способ одолеть некроманта Морбента Скверна, поднявшего мертвецов на кладбище Вороньего холма." }, { 63.08, "Люди здесь пугливы и подозрительны, но любой помощи рады: слишком много тьмы обступило их дома." } } } },
    ["fc71140e"] = { d = 23.8, v = "narrator", c = { x = { { 0.00, "Почти четыре тысячи лет высшие эльфы спокойно жили в своём укромном королевстве." }, { 6.77, "Тем не менее мстительные тролли сдаваться не собирались." }, { 11.43, "В глуши лесов они строили планы и копили силы." }, { 15.49, "В конце концов могучая армия троллей вышла из тени лесов и вновь осадила сияющие башни Кель'Таласа." } } } },
    ["fc734ce5"] = { d = 25.8, v = "human-male", c = { x = { { 0.00, "Прибыв в этот городок, я уже через несколько дней стал учить местных детишек с близлежащих ферм." }, { 6.42, "Уроки проходили так успешно, что местный глава города поручил мне организацию школы, и строительство здания уже началось!" }, { 14.52, "Я прошёл от Серебряного бора до Штормграда, и вот сейчас живу в Луноречье – кто бы мог подумать, что я обойду чуть ли не пол-Азерота?" }, { 23.10, "С наилучшими пожеланиями," }, { 24.78, "Сталван Мистмантл" } } } },
    ["fcd408f5"] = { d = 6.6, v = "goblin-male", c = { x = { { 0.00, "Найдите их для меня и принесите в Прибамбасск вместе с этим гроссбухом, и я награжу вас." } } } },
    ["fce0d734"] = { d = 41.0, v = "skyborne-male", c = { x = { { 0.00, "*(Прикоснувшись к светящемуся кристаллу, вы ощущаете порыв ветра, который доносит тихие слова.)*" }, { 8.16, "Ваятели ветра внимательно наблюдали за тобой, и пора тебе сделать следующий шаг в освоении искусства шамана." }, { 16.75, "Духи Ветра давно исчезли с острова Зефрис, и теперь мы должны лицом к лицу встретить всё опасности обители стихий, чтобы вернуть их домой." }, { 27.83, "Это наш священный долг, от которого зависит само наше выживание." }, { 32.94, "Разыщи меня в центре деревни Тендал." }, { 35.93, "Я займусь твоим обучением." }, { 38.06, "Ваятель ветра Боро, наставник шаманов" } } } },
    ["fcf208e0"] = { d = 22.7, v = "narrator", c = { x = { { 0.00, "Озеро Доблести — небольшое тихое озеро к северо-востоку от Шадра'Алора, в стороне от дорог." }, { 7.09, "По его берегам растёт редкий фиолетовый гриб, за которым сюда приходят не только звери, но и охотники за диковинными ингредиентами." }, { 17.10, "Вокруг бродят волки и совухи, а до троллей Сухокожих отсюда рукой подать." } } } },
    ["fcf7933c"] = { d = 43.4, v = "narrator", c = { x = { { 0.00, "Брилл — небольшой городок в самом сердце Тирисфаля, к северу от руин Лордерона." }, { 6.29, "Во время Третьей войны он одним из первых был поражён Чумой нежити, и братские могилы у его окраин вырыли, чтобы вместить бесчисленных погибших." }, { 17.79, "Ныне Брилл принадлежит Отрёкшимся, и правит им из ратуши мировой судья Севрен." }, { 23.93, "Сюда, покинув Могильник, приходят новопробуждённые: город даёт им кров, а стражи смерти и палачи — работу в войне против Плети и Алого ордена." }, { 35.15, "Как здесь говорят, это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире." } } } },
    ["fd0fd402"] = { d = 31.9, v = "nightelf-female", c = { x = { { 0.00, "В руках, я получила видение хаоса." }, { 2.64, "Люди-волки... воргены... сражались с невероятным врагом." }, { 6.90, "Воргены яростно сражались, как подобает их примитивной расе, но их враг был неодолим – повелители Изумрудного Пламени." }, { 15.63, "И именно тогда я осознала подлинную силу Косы." }, { 19.21, "Сосредотачиваясь на ней, я смогла общаться с воргенами." }, { 23.27, "Только не при помощи речи." }, { 25.30, "Это было что-то другое... мне не описать это словами." }, { 29.43, "Важно было то, что воргены слышали" } } } },
    ["fd16c88c"] = { d = 23.4, v = "dwarf-female", c = { x = { { 0.00, "Но какой ценой должны вестись войны за сохранение жизни?" }, { 4.20, "После которой смерти павшего в бою солдата мы поймём, что жизнь, которую мы стремимся спасти, ускользает от нас на поле боя?" }, { 13.21, "Под сколько мечей и топоров должны мы бросить наше будущее?" }, { 17.61, "Под сколькими метрами пропитанной кровью земли должны мы похоронить наше прошлое?" } } } },
    ["fd1c78b6"] = { d = 37.7, v = "human-male", c = { x = { { 0.00, "Моё почтение Элло Чернодреву, мэру Темнолесья." }, { 3.51, "Боюсь, что у меня есть новости для вашего города." }, { 7.23, "Важные новости." }, { 8.44, "Видите ли, я – создатель." }, { 10.34, "Я обманул носителя этого письма, чтобы он помог мне создать моё последнее, наиболее ужасающее творение – монстра из плоти, костей и перекрученного металла!" }, { 21.95, "В тот момент, когда вы читаете эти слова, оно находится снаружи моего скромного жилища, скрежеща зубами и ожидая одного моего слова, чтобы отправиться убивать." }, { 34.11, "Но вскоре вы сами обо-всём узнаете." }, { 36.75, "Бальзамировщик" } } } },
    ["fd36f370"] = { d = 22.4, v = "human-male", c = { x = { { 0.00, "Бронзовые драконы, что считаются защитниками, склонны обитать в обжитых местах." }, { 5.43, "Вневременный и всё его племя по натуре своей очень терпеливы и всегда обдумают всё заранее, прежде чем действовать." }, { 13.34, "Ноздорму неизменно будет защищать нормальное течение времени, а также и смертные народы, если им будут угрожать могущественные враги." } } } },
    ["fd414de7"] = { d = 21.2, v = "narrator", c = { x = { { 0.00, "Ферма Мольсена — одно из многих хозяйств Западного Края, отнятых Братством Справедливости." }, { 7.09, "Хозяева ушли, и по пустым полям бродят лишь механические големы, дозорные полей." }, { 13.41, "Ополчение доносило, что звероловы Братства промышляют и здесь, и у соседней тыквенной фермы Хмуроброва." } } } },
    ["fd426ed1"] = { d = 59.0, g = 1, v = "nightelf-male", c = { m = { { 0.00, "Господину Алекстону, Штормград." }, { 2.52, "Позвольте поздравить вас с тем, что долгий труд по восстановлению Штормграда увенчался успехом." }, { 9.92, "Многие из тех, чей путь лежит через Аубердин, с восхищением говорят о его величии и прочных основаниях." }, { 18.12, "Именно этот успех и побудил меня написать вам." }, { 21.93, "Аубердин обрёл своё место в этом мире у моря." }, { 25.60, "Когда-то мы были отрезаны от всех, а ныне надежду нам приносят те самые ветра, что терзают наши берега." }, { 33.87, "Податель сего письма – один из тех странников, которых принесли ко мне ветра." }, { 40.06, "Надеюсь, он поможет вашему народу так же, как помог моему." }, { 44.73, "Взамен прошу вас прислать в Аубердин припасы и мастеровых, дабы мы могли укрепить город против гнева этого мира, отнявшего у нас так много." }, { 55.95, "Тандрис Ветропряд, старейшина Аубердина" } }, f = { { 0.00, "Господину Алекстону, Штормград." }, { 2.49, "Позвольте поздравить вас с тем, что долгий труд по восстановлению Штормграда увенчался успехом." }, { 9.81, "Многие из тех, чей путь лежит через Аубердин, с восхищением говорят о его величии и прочных основаниях." }, { 17.91, "Именно этот успех и побудил меня написать вам." }, { 21.68, "Аубердин обрёл своё место в этом мире у моря." }, { 25.30, "Когда-то мы были отрезаны от всех, а ныне надежду нам приносят те самые ветра, что терзают наши берега." }, { 33.48, "Податель сего письма – один из тех странников, которых принесли ко мне ветра." }, { 39.59, "Надеюсь, она поможет вашему народу так же, как помогла моему." }, { 44.50, "Взамен прошу вас прислать в Аубердин припасы и мастеровых, дабы мы могли укрепить город против гнева этого мира, отнявшего у нас так много." }, { 55.58, "Тандрис Ветропряд, старейшина Аубердина" } } } },
    ["fd61195c"] = { d = 24.3, v = "narrator", c = { x = { { 0.00, "Обитель Лунного Ужаса — небольшая пещера к северо-востоку от ворот Круговзора, всего в нескольких минутах ходьбы от города." }, { 9.10, "Внутри гнездятся разъярённые совухи, и их крики слышны у самых стен гоблинского форпоста." }, { 15.56, "Хотя отсюда рукой подать до Деревни Зимней Спячки, гора преграждает прямой путь, и к фурболгам приходится ехать в обход." } } } },
    ["fd949f48"] = { d = 36.8, v = "narrator", c = { x = { { 0.00, "Улей Зора раскинулся в западном Силитусе, между лагерями Сумеречного Молота и берегом Сокрытого Моря." }, { 8.28, "Песок здесь прорезан рытвинами и норами, а над ними высятся колючие наросты, из которых постоянно выползают новые силитиды." }, { 18.22, "Гнездо охраняют летучие осы и рои мелких насекомых, а в глубине улья, за узким входом, скрываются самые опасные его обитатели." }, { 28.60, "Круг Кенария считает этот улей одной из главных угроз и щедро вознаграждает тех, кто бьётся с его роем." } } } },
    ["fd9f3a2a"] = { d = 18.2, v = "narrator", c = { x = { { 0.00, "Лагерь Халдарр стоит на западе Азшары, к северо-востоку от святилища Песни Теней и к югу от Храбростана." }, { 8.50, "Среди эльфийских руин здесь плотно засели сатиры Халдарр, и путникам с дороги лучше не сходить: сатиры не терпят живых." } } } },
    ["fdb921e3"] = { d = 39.1, v = "scourge-male", c = { x = { { 0.00, "Агенты приступили к прочёсыванию, обнаружив существенное присутствие воргов." }, { 5.94, "Рекомендую отправить туда отряды охотников для уменьшения этой угрозы." }, { 11.59, "На ферме, названной агентами Мёртвым полем, были обнаружены гноллы-нежить." }, { 17.53, "Что им нужно на этой ферме – неизвестно, хотя их передвижения и уровень готовности делают вероятными грядущие боевые действия." }, { 27.54, "Во время наблюдения за ними среди гноллов не было обнаружено явных лидеров." }, { 33.62, "Предполагается, что они ожидают прибытия командования или подкрепления." } } } },
    ["fdc01707"] = { d = 34.0, v = "narrator", c = { x = { { 0.00, "Через несколько месяцев суеверные простолюдины начали подозревать, что их правители-волшебники от них что-то скрывали." }, { 8.64, "Слухи о революции пронеслись по всем улицам Даларана, в то время как подозрительные горожане начали сомневаться в действиях и принципах магов, которыми они раньше восхищались." }, { 21.46, "Магократы, опасаясь, что крестьяне поднимут бунт и что Стром может предпринять что-то против них, обратились к одной группе, которая, как они надеялись, поймёт их, – к эльфам." } } } },
    ["fddc0c5a"] = { d = 35.7, v = "orc-male", c = { x = { { 0.00, "Затем советую тебе вернуться в Мулгор и разыскать в Громовом Утёсе Кэрна Кровавое Копыто." }, { 6.63, "Кэрн – вождь тауренского племени Кровавого Копыта, и именно с его позволения твой народ и Служители Земли получили право обосноваться в Мулгоре." }, { 17.18, "Дорога в Громовой Утёс тебе уже должна быть знакома." }, { 21.10, "Найди распорядителя полётов в центре Оргриммара и лети на ветрокрыле в Громовой Утёс." }, { 27.20, "Кэрна можно найти на центральном плато, чуть восточнее великого тотема, что служит в городе насестом для ветрокрылов." } } } },
    ["fde3c449"] = { d = 39.8, v = "narrator", c = { x = { { 0.00, "Деревня Мёртвого Леса стоит на самом юге Осквернённого леса, у дороги из Ясеневого леса." }, { 6.97, "Здесь живут фурболги племени Мёртвого Леса — некогда мирный народ, чей разум отравила порча: теперь они нападают на всякого, кто подойдёт к их кострам и грубым шатрам." }, { 20.13, "Шаманы племени вырезают ритуальные тотемы, от которых несёт разложением, а сородичи из Крепости Древобрюхов считают их потерянными." }, { 30.38, "Фурболг Гразл у Изумрудного святилища просит путников проредить ряды племени — так чужак заслуживает доверие Древобрюхов." } } } },
    ["fe015ab9"] = { d = 24.0, v = "narrator", c = { x = { { 0.00, "Плато Железного Камня — полоса голого камня на северо-восточной кромке кратера, у самой стены." }, { 7.71, "Здесь почти не растёт лес, зато на уступах гнездятся молодые жутедактили, и их крики разносятся над всей северной частью Ун'Горо." }, { 17.88, "Место уединённое и на удивление тихое; отсюда открывается вид на топи и вулкан." } } } },
    ["fe032efd"] = { d = 21.8, v = "narrator", c = { x = { { 0.00, "Кель, опытный маг, был обеспокоен слабостью Альянса." }, { 4.21, "Его подданные, огорчённые потерей своей родины, назвали себя эльфами крови – в память о своём погибшем народе." }, { 13.28, "Лишённые энергии Солнечного Колодца, они ценой огромных страданий сдерживали дальнейшее наступление Плети." } } } },
    ["fe221ad8"] = { d = 25.9, v = "narrator", c = { x = { { 0.00, "Земли Иглогривых лежат в сердце Дуротара, к западу от Колючего Холма." }, { 5.71, "Это передовая войны со свинобразами Иглогривых, рвущимися из Степей в земли орков." }, { 12.45, "Землю усыпают обглоданные кости, а из красных скал вырываются заросли колючек." }, { 18.82, "Орки не пускают Иглогривых дальше, но на месте каждого убитого из зарослей выходят двое." } } } },
    ["fe449523"] = { d = 18.3, v = "gnome-male", c = { x = { { 0.00, "Дорогой дневник, теперь я в порядке." }, { 2.92, "Я бил своего прислужника до тех пор, пока он не начал рыдать, словно девчонка." }, { 9.06, "Хм…" }, { 9.34, "Что-то на душе тоскливо." }, { 11.34, "Минутку!" }, { 12.05, "Демоны!" }, { 12.69, "Я же ЗЛОЙ гений!" }, { 13.98, "Злой, понимаешь?" }, { 15.26, "Как я в себе разочарован." }, { 17.26, "Скоро вернусь." } } } },
    ["fe6f0de9"] = { d = 25.2, v = "narrator", c = { x = { { 0.00, "Через несколько месяцев Орда истребила почти всех дренеев, живших на Дреноре." }, { 6.53, "Лишь немногие сумели избежать гнева орков." }, { 10.13, "Гул'дан был доволен: его Орда была непобедима." }, { 14.10, "Но он знал, что если им будет не с кем сражаться, непреодолимая жажда крови заставит их убивать друг друга и войско уничтожит само себя." } } } },
    ["fe7c39df"] = { d = 25.9, v = "narrator", c = { x = { { 0.00, "Юный орк охотно согласился быть учеником демона и вскоре стал одним из самых могущественных смертных волшебников в истории." }, { 9.69, "Он учил других орков тёмным искусствам и пытался искоренить их древние ритуалы." }, { 15.96, "Гул'дан показал своим братьям волшебство, которое никто из них никогда не видел, ужасающую мощь, способную повсюду сеять смерть." } } } },
    ["fec60183"] = { d = 29.7, v = "nightelf-male", c = { x = { { 0.00, "Помехой – возможно, лишь ещё одним культом смерти." }, { 4.16, "Ему невдомёк, что мы – не что иное, как одна из... нитей Совета Теней." }, { 9.87, "Ребёнком я слышал историю о насекомом, один укус которого мог с лёгкостью убить жертву, хотя выглядело оно как обычная мушка, как пятнышко, вряд ли заслуживающее внимания." }, { 23.82, "Именно то, что оставляют без внимания, и наносит нам самый крупный ущерб." } } } },
    ["feebd87e"] = { d = 22.0, v = "narrator", c = { x = { { 0.00, "Слово \"ПРЕДАТЕЛЬ\" криво нацарапано поверх красиво высеченной эпитафии, гласящей:" }, { 7.02, "\"Здесь покоится Юрив." }, { 8.89, "Отец, муж, паладин." }, { 10.61, "Пусть же потомки знают, что преданность его Свету была неколебима." }, { 16.38, "Он никогда не требовал от других того, чего не стал бы делать сам\"." } } } },
    ["feefdfc6"] = { d = 31.3, v = "narrator", c = { x = { { 0.00, "Его друзья-титаны пытались убедить его не совершать ошибки, пытались успокоить его разбушевавшиеся чувства, но он принимал их более чем оптимистичные верования за корыстные заблуждения." }, { 14.29, "Покинув навсегда их ряды, Саргерас отправился на поиски своего собственного места во вселенной." }, { 21.67, "Несмотря на то что Пантеон был опечален его уходом, даже титаны не могли предугадать того, как далеко зайдёт их заблудший брат." } } } },
    ["fef2a689"] = { d = 38.7, v = "gnome-male", c = { x = { { 0.00, "Лорд Вальтхалак, продолжение." }, { 1.91, "Если бы мы представляли себе, насколько могущественным волшебником был Вальтхалак (особенно по части подчинения себе душ), то ни за что на свете не согласились бы на это задание." }, { 13.51, "Но судьба распорядилась иначе, и эта работа оказалась для нас последней." }, { 18.29, "Убив Лорда Вальтхалака и забрав его книгу заклинаний, Кормок, должно быть, почувствовал, что с его амулетом что-то не так." }, { 26.42, "Он чуть не затеял драку из-за того, что хотел забрать амулет себе." }, { 30.91, "Тогда мы ещё не знали, что в амулете была заключена часть души Вальтхалака; выяснили мы это, к сожалению, намного позже." } } } },
    ["fef42baa"] = { d = 18.2, v = "narrator", c = { x = { { 0.00, "В древние времена, после того как титаны покинули Азерот, их дети, известные как земельники, продолжали охранять и обустраивать глубины мира." }, { 10.89, "Земельникам не было дела до наземных рас, они желали лишь проникать всё глубже и глубже в землю." } } } },
    ["ff151e67"] = { d = 32.2, v = "narrator", c = { x = { { 0.00, "Болота Синежабрых лежат на западном побережье Болотины, к северу от Гавани Менетилов." }, { 6.42, "Здесь стоят поселения мурлоков племени Синежабрых, которые выходят из морских глубин и селятся на берегу." }, { 14.33, "Они нападают на рыбаков и торговцев, устраивают засады на дорогах и растаскивают грузы с кораблей, а потом прячутся в своих хижинах у воды, где их непросто достать." }, { 26.63, "Мурлоки держатся стайками, и одинокому путнику здесь лучше не задерживаться." } } } },
    ["ff35dbdb"] = { d = 30.4, v = "human-male", c = { x = { { 0.00, "Озрик, ниже приведён перечень доспехов, которые нам требуются:" }, { 4.35, "Десять Панцирных Рубах," }, { 6.05, "Двадцать Шлемов," }, { 7.24, "Тридцать Накладок на Доспех," }, { 9.26, "Пятнадцать Бронированных Ботинок." }, { 11.59, "Мы, как обычно, у тебя в долгу." }, { 13.79, "И если Западный Край когда-нибудь избавится от досаждающих ему воров, я сочту себя просто обязанным пригласить тебя в наш дом на вкусный обед, достойный былой щедрости, что некогда прославляла эту страну." }, { 28.09, "— Льюис" }, { 28.65, "Интендант, Сторожевой Холм." } } } },
    ["ff3e6dac"] = { d = 29.6, v = "narrator", c = { x = { { 0.00, "Башня Пепла возвышается на пепельной равнине к югу от Чёрной горы." }, { 5.44, "Вокруг неё раскинулось становище орков клана Чёрной горы: здесь стоят их хижины, горят костры и упражняются воины." }, { 14.77, "Чародеи и чернокнижники клана поднимаются на башню, откуда видны все подходы к горе." }, { 21.67, "Одинокому путнику лучше обойти это место стороной — орки не щадят никого, кто ступит на их землю." } } } },
    ["ff576b6f"] = { d = 32.1, v = "narrator", c = { x = { { 0.00, "Западный Круг Обуздания стоит на западе нагорья, у самой Стены Торадина." }, { 6.00, "Древние камни здесь окружены элементалями огня, и трава вокруг круга выжжена дочерна." }, { 13.12, "Это один из четырёх кругов, которыми горные великаны сковали принцессу земли, и в западном камне заключён один из ключей от её темницы." }, { 24.23, "Пламя, что мечется среди монолитов, служит не путнику, а стражу, и не любит, когда его тревожат." } } } },
    ["ffc1ce7a"] = { d = 26.4, v = "narrator", c = { x = { { 0.00, "Из глубин Ледяного Трона Нер'зул направил свой могучий разум ко всем обитателям Нордскола." }, { 7.16, "Без особых усилий он подчинил своей воле многих существ, включая ледяных троллей и свирепых вендиго." }, { 15.24, "Силы его духа были практически безграничны, и с их помощью он создал небольшую армию, которую собрал в бесконечных лабиринтах Ледяной Короны." } } } },
    ["ffd78c29"] = { d = 46.7, v = "nightelf-male" },
    ["ffd90e16"] = { d = 26.1, v = "gnome-male", c = { x = { { 0.00, "Изалиен, продолжение." }, { 1.51, "Но когда она со своим гиппогрифом Неземным входила в город, на них напал Алззин Перевертень и его воины." }, { 8.89, "И в этом бою её глаза закрылись навеки." }, { 11.72, "Может быть, это и к лучшему, что ей не удалось раскрыть секрет того зловещего проклятия, которое Лорд Вальтхалак наложил на амулет, чтобы заключить там свою душу." }, { 23.07, "Логово Алззина – одно из мест с привидениями." } } } },
    ["ffdac019"] = { d = 36.8, v = "narrator", c = { x = { { 0.00, "Лагерь Аридена — заброшенная стоянка чуть севернее главной дороги, что ведёт из Сумеречного леса к Болоту Печали." }, { 9.04, "Кострище давно остыло, повозки и пожитки брошены, но никаких следов хозяев: ни костей, ни могил." }, { 16.85, "Кем был Ариден и куда он делся вместе со спутниками, на перевале не знает никто, и только имя на карте напоминает, что здесь однажды пытались обжиться." }, { 28.93, "Путники, проходя мимо, обычно ускоряют шаг: пустой лагерь в мёртвой земле не сулит ничего хорошего." } } } },
    ["ffe67e35"] = { d = 29.4, v = "narrator", c = { x = { { 0.00, "Озеро Каменного Быка длинной подковой охватывает деревню Кровавого Копыта с трёх сторон." }, { 6.80, "Его прохладные воды славятся обилием рыбы, и не один час здесь проводят с удочкой в руках." }, { 13.73, "В самом узком месте озеро пересекает мост, а дорога через него ведёт от деревни на север, к Громовому Утёсу." }, { 21.97, "По северному берегу шли караваны Торговой компании — здесь и разгорелась вражда тауренов с гоблинами." } } } },
    ["ffea38be"] = { d = 37.6, v = "human-male", c = { x = { { 0.00, "Дела культа, том девяносто второй." }, { 2.60, "С радостным сердцем приветствую я вас, братья мои, ибо дела нашего культа идут сейчас наилучшим образом." }, { 10.47, "Имя нам – легион, и всякие замыслы наши всё ближе к воплощению." }, { 15.21, "В ряды наши встаёт всё больше новичков." }, { 18.14, "Хвалебная песнь возносится к нашим господам на Тёмных берегах, и склоняются они в радостных грёзах среди Выжженной теснины, и обнимают они слугу наших господ, Аку'май, в Непроглядной Пучине." }, { 32.14, "Поистине, братья мои и сёстры, скоро вера наша разнесётся по всему Азероту!" } } } },
}
